    @ObservedObject var model: CameraAppModel
    var s: Double
    var body: some View {
        ZStack {
            Color.black.opacity(0.45).onTapGesture { model.confirmingDelete = false }.accessibilityHidden(true)
            VStack(alignment: .leading, spacing: 8 * s) {
                Text("删除这张照片？").font(.system(size: 13 * s, weight: .bold, design: .rounded))
                Text((model.photos.indices.contains(model.albumIndex) ? model.photos[model.albumIndex].name + " " : "") + String(localized: "删除后不能恢复。"))
                    .font(.system(size: 10 * s)).foregroundStyle(FixedMenuStyle.inkSoft)
                HStack(spacing: 8 * s) {
                    CameraPill(title: String(localized: "取消"), symbol: "xmark", color: FixedMenuStyle.inkSoft, s: s, identifier: "camera-dialog-cancel") { model.confirmingDelete = false }
                    CameraPill(title: String(localized: "删除"), symbol: "trash", color: FixedMenuStyle.stop, s: s, identifier: "camera-dialog-confirm") { model.deleteChosen() }
                }
            }
            .padding(14 * s)
            .frame(maxWidth: 280 * s, alignment: .leading)
            .background(FixedMenuStyle.paper, in: RoundedRectangle(cornerRadius: 12 * s, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 12 * s, style: .continuous).strokeBorder(FixedMenuStyle.tileEdge, lineWidth: 1))
            .accessibilityElement(children: .contain)
            .accessibilityAddTraits(.isModal)
        }
    }
}

/// The two screens over the whole display, for LCDs too small to use (a
/// phone's 掌机模式 and 桌面模式), as 系统设置 does.
struct CameraFullScreen: View {
    @ObservedObject var model: CameraAppModel
    var body: some View {
        GeometryReader { proxy in
            let insets = proxy.safeAreaInsets
            let topHeight = min(proxy.size.height * 0.42, proxy.size.width * 0.6)
            VStack(spacing: 0) {
                CameraTopScreen(model: model)
                    .frame(width: proxy.size.width, height: topHeight)
                    .padding(.top, insets.top)
                    .background(Color.black)
                Rectangle().fill(FixedMenuStyle.bar).frame(height: 4)
                CameraBottomScreen(model: model)
                    .padding(.bottom, insets.bottom)
                    .background(FixedMenuStyle.bar)
            }
            .ignoresSafeArea()
        }
    }
}

// MARK: - On the cover (11-05; 11-06)

/// With the lid shut and the camera
/// running the cover is the camera's control deck, printed on the shell as
/// the console's own controls are. It stands upright however the console is
/// held (CoverHold: upright, across either way, upside down) and is laid out
/// for that hold (CoverDeckLayout, FoldGeometry.swift): the controls down
/// the right, 拍照 under the right thumb, all of them clear of the cover's
/// camera and of the Camera Control's overlay and at least 44 points; the
/// picture on the left. 内侧 is the cover's own camera (beside the picture,
/// so a selfie's eyes are near the lens), 外侧 the rear dual camera (0.5× is
/// its ultra wide). A swipe across the picture goes to the next lens and a
/// pinch zooms, as the system camera's do, but nothing looks like it. Stood
/// half open like a tent (held clockwise, hinge up), the cover faces the
/// people in the picture: the camera beside it takes them, the picture is as
/// large as fits, the controls are along the steady bottom edge, and a touch
/// counts down before the picture is taken.
struct CameraCoverDeck: View {
    @ObservedObject var model: CameraAppModel
    var finish: ShellFinish
    /// On the hardware cover (its rotation, and shown once it has settled);
    /// otherwise a preview (a phone without a hinge, the DEBUG flag).
    var fromDevice: Bool
    var tent: Bool
    /// A preview drawn at the cover's own size in another phone's window
    /// (the tests' pictures): the home indicator's edge the cover has, and
    /// the regions the shut Duo reports there (the window gives neither).
    var previewBottom: Double = 0
    var previewRegions: [CGRect] = []
    #if os(iOS)
    @ObservedObject private var displayRole = DisplayRoleMonitor.shared
    #endif
    @ObservedObject private var holds = CoverHoldMonitor.shared
    private var visible: Bool {
        #if os(iOS)
        return !fromDevice || displayRole.coverSettled
        #else
        return true
        #endif
    }
    /// The window's interface rotation against the hardware's own portrait
    /// frame: the cover's from DisplayRoleMonitor; a preview's from its
    /// window scene (a phone's window turns with the phone; the Duo's inner
    /// display runs upside down); with neither, a portrait window is taken as
    /// upright and a landscape one as turned the cover deck's old way.
    private func interfaceRotation(for size: CGSize) -> Double {
        #if os(iOS)
        if fromDevice, let rotation = displayRole.coverRotation(for: size) { return rotation }
        if let rotation = CoverHoldMonitor.sceneInterfaceRotation(),
           (abs(FixedFrameTransform.normalized(rotation)) == 90) == (size.width > size.height) { return rotation }
        #endif
        return size.height >= size.width ? 0 : -90
    }
    /// The tent is always held hinge up.
    private var hold: CoverHold { tent ? .clockwise : holds.hold }

    /// (The trace is the phone's; the Mac's preview has none.)
    private static func trace(_ line: String) {
        #if os(iOS)
        OrientationTrace.shared.event(line)
        #endif
    }
    /// One line for the trace: the deck's canvas and what is on it, and
    /// whether the body's own back is worn (if not, which step said no).
    static func note(canvas: CGSize, hold: CoverHold, fromDevice: Bool, safe: ViewportInsets, reported: [CGRect], cameras: [CGRect], overlay: CGRect,
                     body: CameraBody, wanted: CameraShellSkin?, frame: CoverBackFrame?, drawn: ShellPlan?, wide: CoverBackAcross?, worn: Bool) -> String {
        func r(_ rect: CGRect) -> String { "\(Int(rect.minX.rounded())),\(Int(rect.minY.rounded())) \(Int(rect.width.rounded()))x\(Int(rect.height.rounded()))" }
        var out = "camera deck: canvas \(Int(canvas.width))x\(Int(canvas.height)) hold \(hold.rawValue) device \(fromDevice)"
        out += " safe \(Int(safe.top))/\(Int(safe.leading))/\(Int(safe.bottom))/\(Int(safe.trailing))"
        out += " reported [" + reported.map(r).joined(separator: " | ") + "] cameras [" + cameras.map(r).joined(separator: " | ") + "] overlay " + r(overlay)
        out += " body \(body.rawValue) wants \(wanted?.rawValue ?? "none")"
        if let frame { out += " column " + r(frame.column) + " strip " + r(frame.strip) } else { out += " no column" }
        if let wide { out += " across: band " + r(wide.band) + " screen " + r(wide.screen) + " keys " + r(wide.keys) }
        if let drawn { out += " short \(Int(drawn.short.rounded())) shutter " + r(drawn.shutter) }
        out += worn ? " -> own back" : " -> the deck"
        return out
    }

    var body: some View {
        GeometryReader { safeProxy in
            let insets = safeProxy.safeAreaInsets
            GeometryReader { proxy in
                let placement = CoverHoldPlacement.calculate(window: proxy.size, interfaceRotation: interfaceRotation(for: proxy.size), hold: hold)
                let canvas = placement.canvasSize
                // On the cover only the home indicator's edge is kept (the
                // camera is a reserved region of its own, read below); a
                // preview keeps its window's whole safe area (a phone's notch).
                let windowSafe = fromDevice ? ViewportInsets(bottom: insets.bottom)
                    : ViewportInsets(top: insets.top, leading: insets.leading, bottom: Double(insets.bottom) + previewBottom, trailing: insets.trailing)
                let safe = placement.canvas(fromWindow: windowSafe)
                let hardware = CoverHardware.duo.fitted(to: placement.fixedSize)
                // The system's regions, as long as they lie in this window (954:
                // one came in the window's earlier frame for a moment).
                let raw = fromDevice ? DeviceFoldRegions.occlusions(proxy) : previewRegions
                let reported = placement.canvas(fromReported: raw)
                // The estimate is
                // kept out too, with whatever is reported (a region reported
                // smaller than the camera, or none, put 外侧 under it).
                let cameras = reported + [placement.canvas(fromFixed: hardware.camera)]
                let overlay = placement.canvas(fromFixed: hardware.overlay)
                let hinge = placement.canvas(fromFixed: CGRect(x: 0, y: 0, width: 14, height: placement.fixedSize.height))
                // The body's own back, where one is made for it and the deck is
                // the way up it is made for (CoverBackFrame) with room for its keys.
                let wanted: CameraShellSkin? = tent ? nil : CameraShellSkin.worn(by: model.body, album: model.phase == .album)
                let aspect = model.phase == .album ? 5.0 / 3 : model.shape.ratio
                let plain = CoverDeckLayout.calculate(canvas: canvas, safe: safe, cameras: cameras, overlay: overlay,
                                                      zoomStops: model.zoomStops.count, aspect: aspect)
                let frame: CoverBackFrame? = wanted == nil ? nil : CoverBackFrame.calculate(canvas: canvas, safe: safe, cameras: cameras, overlay: overlay)
                let drawn: ShellPlan? = frame.flatMap { back in wanted.map { ShellPlan(skin: $0, back: back) } }
                let own: CoverDeckLayout? = drawn.flatMap { $0.layout(from: plain, aspect: aspect, zoomStops: model.zoomStops.count) }
                let plan: ShellPlan? = own == nil ? nil : drawn
                // Held across it is laid out on its own (CoverBackAcross).
                let wide: CoverBackAcross? = wanted == nil || frame != nil ? nil
                    : CoverBackAcross.calculate(canvas: canvas, safe: safe, cameras: cameras, overlay: overlay)
                let acrossDrawn: ShellAcrossPlan? = wide.flatMap { back in wanted.map { ShellAcrossPlan(skin: $0, back: back) } }
                let acrossOwn: CoverDeckLayout? = acrossDrawn.flatMap { $0.layout(from: plain, aspect: aspect, zoomStops: model.zoomStops.count) }
                let across: ShellAcrossPlan? = acrossOwn == nil ? nil : acrossDrawn
                // What was decided, and from what, for the trace (sizes and
                // places only): why a body's own back is or is not worn.
                let decided = CameraCoverDeck.note(canvas: canvas, hold: hold, fromDevice: fromDevice, safe: safe, reported: reported, cameras: cameras,
                                                   overlay: overlay, body: model.body, wanted: wanted, frame: frame, drawn: drawn, wide: wide,
                                                   worn: plan != nil || across != nil)
                ZStack(alignment: .topLeading) {
                    if tent {
                        CameraTentFace(model: model, layout: CoverTentLayout.calculate(canvas: canvas, safe: safe, cameras: cameras),
                                       finish: finish, hinge: hinge, showsHardware: !fromDevice)
                    } else {
                        CameraDeckFace(model: model, thumbnails: model.thumbnails, finish: finish,
                                       layout: own ?? acrossOwn ?? plain,
                                       hinge: hinge, control: overlay, showsHardware: !fromDevice, plan: plan, across: across)
                    }
                    // The capture keys (the Camera Control, a volume key) take the
                    // picture here too; in the tent they count down first.
                    CaptureKeyCatcher(enabled: model.phase == .live, pressed: { tent ? model.tentShutter() : model.captureKey() })
                        .frame(width: 1, height: 1)
                        .allowsHitTesting(false)
                        .accessibilityHidden(true)
                    // How the deck is held and turned (the UI tests read it).
                    Color.clear.frame(width: 1, height: 1)
                        .accessibilityElement()
                        .accessibilityLabel(hold.title)
                        .accessibilityValue("\(hold.rawValue) \(Int(placement.rotationDegrees))")
                        .accessibilityIdentifier("camera-deck-hold")
                }
                .frame(width: canvas.width, height: canvas.height)
                .rotationEffect(.degrees(placement.rotationDegrees))
                .position(x: proxy.size.width / 2, y: proxy.size.height / 2)
                .animation(nil, value: placement)
                // A new hold: the deck fades to its new layout (no part of it
                // flies across the cover).
                .id(hold)
                .transition(.opacity.animation(.easeInOut(duration: 0.2)))
                .onAppear { logGeometry(placement: placement, insets: windowSafe, reported: reported, dropped: raw.count - reported.count) }
                .onAppear {
                    CameraCoverDeck.trace(decided)
                    model.filmBackWorn = (plan?.skin ?? across?.skin) == .film
                    model.instantBackWorn = (plan?.skin ?? across?.skin) == .instant
                }
                .onChange(of: plan?.skin ?? across?.skin) { _, now in
                    model.filmBackWorn = now == .film
                    model.instantBackWorn = now == .instant
                }
                .onDisappear {
                    model.filmBackWorn = false
                    model.instantBackWorn = false
                }
                .onChange(of: decided) { _, now in CameraCoverDeck.trace(now) }
                .onChange(of: placement) { _, next in logGeometry(placement: next, insets: windowSafe, reported: reported, dropped: raw.count - reported.count) }
                // The regions settle after the window does (954): logged too.
                .onChange(of: reported) { _, next in logGeometry(placement: placement, insets: windowSafe, reported: next, dropped: raw.count - next.count) }
            }
            .ignoresSafeArea()
        }
        .background(Color.black.ignoresSafeArea())
        .opacity(visible ? 1 : 0)
        .animation(.easeOut(duration: 0.25), value: visible)
        .environment(\.layoutDirection, .leftToRight)
        #if os(iOS)
        .statusBarHidden(!CameraTry.overlays).persistentSystemOverlays(CameraTry.overlays ? .automatic : .hidden)
        // The controls come near the home indicator's edge in some holds: a
        // first swipe there only shows it.
        .defersSystemGestures(on: .bottom)
        #endif
        .onAppear { holds.start() }
        .onDisappear { holds.stop() }
        // 11-15: the picture turns with the deck (CameraAppModel.outerAngle).
        .onChange(of: hold, initial: true) { _, next in model.setCoverHold(next) }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier(tent ? "camera-tent" : "camera-deck")
    }

    private func logGeometry(placement: CoverHoldPlacement, insets: ViewportInsets, reported: [CGRect], dropped: Int = 0) {
        NSLog("[camera] deck %@: hold %@, turned %d, window %dx%d, canvas %dx%d, safe %d/%d/%d/%d, %@%@",
              tent ? "tent" : "closed", placement.hold.rawValue, Int(placement.rotationDegrees),
              Int(placement.window.width), Int(placement.window.height),
              Int(placement.canvasSize.width), Int(placement.canvasSize.height),
              Int(insets.top), Int(insets.leading), Int(insets.bottom), Int(insets.trailing),
              reported.isEmpty ? "camera region: the estimate (none reported)"
                  : "camera region reported: " + reported.map { "\(Int($0.minX)),\(Int($0.minY)) \(Int($0.width))x\(Int($0.height))" }.joined(separator: "; "),
              dropped > 0 ? " (\(dropped) reported outside the window, left out)" : "")
    }
}

/// How the shut console is held, from UIKit's device orientation
/// (the system's own reading, with its own hysteresis). Lying flat (face up
/// or down) keeps the last hold; a turn counts once it has held for a
/// quarter of a second. iOS stops reporting turns while the iPhone's
/// orientation lock is on: the deck then stays as it was.
/// DEBUG `--foldarc-camera-hold=portrait|clockwise|counterclockwise|upsideDown`
/// fixes it (screenshots and UI tests without turning anyone's simulator).
@MainActor final class CoverHoldMonitor: ObservableObject {
    static let shared = CoverHoldMonitor()
    @Published private(set) var hold: CoverHold = .portrait
    private var users = 0
    private var pending: Task<Void, Never>?
    #if os(iOS)
    private var observer: NSObjectProtocol?
    #endif
    #if DEBUG
    static let forced: CoverHold? = ProcessInfo.processInfo.arguments
        .last { $0.hasPrefix("--foldarc-camera-hold=") }
        .flatMap { CoverHold(rawValue: String($0.dropFirst("--foldarc-camera-hold=".count))) }
    #endif

    func start() {
        users += 1
        guard users == 1 else { return }
        #if DEBUG
        if let forced = Self.forced {
            hold = forced
            NSLog("[camera] hold: %@ (the launch argument)", forced.rawValue)
            return
        }
        #endif
        #if os(iOS)
        // 11-15 (真机): the hold from gravity itself. UIKit's device
        // orientation lagged on the shut Duo (turned through all four holds,
        // it still said upright, the picture turning inside a deck that did
        // not), and the system's camera angle was off stood as a tent.
        read(settle: false)
        if motion.isDeviceMotionAvailable {
            motion.deviceMotionUpdateInterval = 1.0 / 15
            motion.startDeviceMotionUpdates(to: .main) { [weak self] data, _ in
                guard let gravity = data?.gravity else { return }
                MainActor.assumeIsolated { self?.felt(x: gravity.x, y: gravity.y) }
            }
        } else {
            UIDevice.current.beginGeneratingDeviceOrientationNotifications()
            observer = NotificationCenter.default.addObserver(forName: UIDevice.orientationDidChangeNotification, object: nil, queue: .main) { [weak self] _ in
                MainActor.assumeIsolated { self?.read(settle: true) }
            }
        }
        #endif
    }
    func stop() {
        users = max(0, users - 1)
        guard users == 0 else { return }
        pending?.cancel(); pending = nil
        #if os(iOS)
        motion.stopDeviceMotionUpdates()
        if let observer {
            NotificationCenter.default.removeObserver(observer)
            self.observer = nil
            UIDevice.current.endGeneratingDeviceOrientationNotifications()
        }
        #endif
    }
    #if os(iOS)
    private let motion = CMMotionManager()
    private func felt(x: Double, y: Double) {
        guard let next = CoverHold.fromGravity(x: x, y: y, current: hold) else { return }
        guard next != hold else { pending?.cancel(); pending = nil; candidate = nil; return }
        guard candidate != next else { return }
        candidate = next
        pending?.cancel()
        // (a turn counts once it has held a third of a second)
        pending = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(330))
            guard let self, !Task.isCancelled, self.candidate == next else { return }
            self.candidate = nil
            withAnimation(.easeInOut(duration: 0.2)) { self.hold = next }
            NSLog("[camera] hold: %@ (gravity)", next.rawValue)
            OrientationTrace.shared.event("camera cover hold -> \(next.rawValue) (gravity)")
        }
    }
    private var candidate: CoverHold?
    #endif

    #if os(iOS)
    /// UIKit's names are the home side's: landscapeLeft has it on the right,
    /// the console turned counterclockwise.
    nonisolated static func hold(for orientation: UIDeviceOrientation) -> CoverHold? {
        switch orientation {
        case .portrait: return .portrait
        case .portraitUpsideDown: return .upsideDown
        case .landscapeLeft: return .counterclockwise
        case .landscapeRight: return .clockwise
        default: return nil
        }
    }
    private func read(settle: Bool) {
        guard let next = Self.hold(for: UIDevice.current.orientation) else { return }
        pending?.cancel(); pending = nil
        guard next != hold else { return }
        guard settle else {
            hold = next
            NSLog("[camera] hold: %@", next.rawValue)
            OrientationTrace.shared.event("camera cover hold -> \(next.rawValue) (first read)")
            return
        }
        pending = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(250))
            guard let self, !Task.isCancelled, Self.hold(for: UIDevice.current.orientation) == next else { return }
            withAnimation(.easeInOut(duration: 0.2)) { self.hold = next }
            NSLog("[camera] hold: %@", next.rawValue)
            OrientationTrace.shared.event("camera cover hold -> \(next.rawValue)")
        }
    }
    /// The interface rotation of the foreground window scene (as
    /// DisplayRoleMonitor.interfaceRotation measures it), for previews.
    static func sceneInterfaceRotation() -> Double? {
        let scenes = UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }
            .filter { $0.session.role == .windowApplication }
        let scene = scenes.first { $0.activationState == .foregroundActive } ?? scenes.first
        switch scene?.effectiveGeometry.interfaceOrientation {
        case .portrait?: return 0
        case .portraitUpsideDown?: return 180
        case .landscapeLeft?: return -90
        case .landscapeRight?: return 90
        default: return nil
        }
    }
    #endif
}

private extension View {
    /// At `rect` in a top-leading ZStack (the canvas's points).
    func deckPlaced(_ rect: CGRect) -> some View {
        frame(width: max(0, rect.width), height: max(0, rect.height)).position(x: rect.midX, y: rect.midY)
    }
    /// A key that cannot do its work just now: paler, and VoiceOver is
    /// told why. (It stays a key: pressed, it says the same on the screen.)
    func deckDimmed(_ off: Bool, why: String) -> some View {
        opacity(off ? 0.5 : 1).accessibilityHint(off ? why : "")
    }
    /// A key at `rect` with at least 44 points to touch each way: it is
    /// drawn in `rect` as before, and the room it lacks is added round it
    /// (a key that knows of it — a shell's key, slide or ring — draws
    /// itself inside that room).
    func deckKey(_ rect: CGRect, least: CGFloat = 44) -> some View {
        let dx = max(0, (least - rect.width) / 2), dy = max(0, (least - rect.height) / 2)
        return environment(\.deckKeyInset, EdgeInsets(top: dy, leading: dx, bottom: dy, trailing: dx))
            .deckPlaced(rect.insetBy(dx: -dx, dy: -dy))
    }
}

/// The room round a key that is touched with it but not drawn on.
private struct DeckKeyInsetKey: EnvironmentKey {
    static let defaultValue = EdgeInsets()
}
extension EnvironmentValues {
    var deckKeyInset: EdgeInsets {
        get { self[DeckKeyInsetKey.self] }
        set { self[DeckKeyInsetKey.self] = newValue }
    }
}

/// The hinge, along whichever edge of the canvas it is on in this hold.
private struct CoverHingeBand: View {
    var finish: ShellFinish
    var rect: CGRect
    var canvas: CGSize
    var body: some View {
        let across = rect.width > rect.height
        let outerStart = across ? rect.midY < canvas.height / 2 : rect.midX < canvas.width / 2
        let stops: [Gradient.Stop] = [.init(color: finish.dark, location: 0), .init(color: finish.light, location: 0.4),
                                      .init(color: finish.base, location: 0.6), .init(color: finish.dark, location: 1)]
        let start: UnitPoint = across ? (outerStart ? .top : .bottom) : (outerStart ? .leading : .trailing)
        let end: UnitPoint = across ? (outerStart ? .bottom : .top) : (outerStart ? .trailing : .leading)
        LinearGradient(stops: stops, startPoint: start, endPoint: end)
            .deckPlaced(rect)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

/// Where the cover's camera and its Camera Control are, drawn on a preview
/// only (on the cover they are the hardware itself): the lens in its
/// reserved region, and a mark on the edge beside the button.
private struct CoverHardwareMarks: View {
    var cameras: [CGRect]
    var control: CGRect?
    var canvas: CGSize
    var body: some View {
        ZStack(alignment: .topLeading) {
            ForEach(Array(cameras.enumerated()), id: \.offset) { _, region in
                ZStack {
                    RoundedRectangle(cornerRadius: min(region.width, region.height) / 2, style: .continuous)
                        .strokeBorder(Color.white.opacity(0.22), style: StrokeStyle(lineWidth: 1, dash: [3, 3]))
                    Circle().fill(Color.black).frame(width: 16, height: 16)
                        .overlay(Circle().strokeBorder(Color.white.opacity(0.25), lineWidth: 1.5))
                }
                .deckPlaced(region)
            }
            // The button sits on the canvas edge the overlay comes in from.
            if let control, control.width > 0, control.height > 0 {
                let onSide = control.height > control.width
                let mark = onSide
                    ? CGRect(x: control.midX < canvas.width / 2 ? 0 : canvas.width - 4, y: control.midY - 22, width: 4, height: 44)
                    : CGRect(x: control.midX - 22, y: control.midY < canvas.height / 2 ? 0 : canvas.height - 4, width: 44, height: 4)
                Capsule().fill(Color.white.opacity(0.35)).deckPlaced(mark)
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// 「看这里」 by the cover's camera while counting down with it: people look
/// at the picture of themselves, not at the lens.
private struct LookHereBadge: View {
    var camera: CGRect
    var canvas: CGSize
    var big = false
    var body: some View {
        let c = CGPoint(x: camera.midX, y: camera.midY)
        let o = CGPoint(x: canvas.width / 2, y: canvas.height / 2)
        let length = max(1, hypot(o.x - c.x, o.y - c.y))
        let reach = (big ? 92.0 : 66.0) + max(camera.width, camera.height) / 2
        let p = CGPoint(x: c.x + (o.x - c.x) / length * reach, y: c.y + (o.y - c.y) / length * reach)
        let angle = atan2(c.y - p.y, c.x - p.x) * 180 / .pi + 90
        HStack(spacing: 4) {
            Image(systemName: "arrow.up").rotationEffect(.degrees(angle))
            Text("看这里")
        }
        .font(.system(size: big ? 22 : 13, weight: .heavy, design: .rounded))
        .foregroundStyle(.black)
        .padding(.horizontal, big ? 14 : 9).padding(.vertical, big ? 8 : 5)
        .background(Capsule().fill(Color.yellow))
        .fixedSize()
        .position(p)
        .allowsHitTesting(false)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("看这里：镜头在这边")
        .accessibilityIdentifier("camera-look-here")
    }
}

/// The lid shut: the control deck, laid out by CoverDeckLayout (canvas points).
private struct CameraDeckFace: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var finish: ShellFinish
    var layout: CoverDeckLayout
    var hinge: CGRect
    var control: CGRect
    var showsHardware: Bool
    /// The body's own back, where it has one made and it fits (ShellPlan).
    var plan: ShellPlan? = nil
    /// The same held across (ShellAcrossPlan).
    var across: ShellAcrossPlan? = nil
    @State private var pinchFrom: Double?
    /// The system's Camera Control menu is up over the picture: the lens and
    /// zoom controls it repeats step back (HIG Camera Control: "avoid
    /// duplicating controls … when the system displays the overlay").
    private var systemControlsUp: Bool { model.controlsShown }

    var body: some View {
        let l = layout
        ZStack(alignment: .topLeading) {
            // A camera body's own back where it has one (and there is the
            // block for its keys); else the handheld's deck (the lines
            // below, as they were).
            if let plan {
                shellFace(plan)
            } else if let across {
                shellAcrossFace(across)
            } else {
            FullScreenShellSurface(finish: finish, cover: true)
                .frame(width: l.canvas.width, height: l.canvas.height)
            CoverHingeBand(finish: finish, rect: hinge, canvas: l.canvas)
            if showsHardware { CoverHardwareMarks(cameras: l.keepOut, control: control, canvas: l.canvas) }
            viewfinder.deckPlaced(l.viewfinder)
            if model.phase != .album, l.zoomBar.width > 0 {
                zoomBar.deckPlaced(l.zoomBar)
                    .opacity(systemControlsUp ? 0 : 1)
                    .allowsHitTesting(!systemControlsUp)
            }
            if model.phase == .album {
                albumRow.deckPlaced(l.lensRow)
            } else {
                lensRow(lines: l.lensRow.height > 80 ? 2 : 1, width: l.lensRow.width).deckPlaced(l.lensRow)
                    .opacity(systemControlsUp ? 0 : 1)
                    .allowsHitTesting(!systemControlsUp)
            }
            toolRow.deckPlaced(l.toolRow)
            if model.phase != .album {
                CameraShootingRow(model: model, s: 1, idPrefix: "camera-deck-", lines: l.shootingRow.height > 80 ? 2 : 1, evWidth: 44, glyphs: true)
                    .deckPlaced(l.shootingRow)
            }
            flipTile.deckPlaced(l.flip)
            albumTile.deckPlaced(l.album)
            shutterButton.deckPlaced(l.shutter)
            if l.hint.width > 0 { hintText.deckPlaced(l.hint) }
            if model.bodiesOpen && model.phase != .album {
                bodyMenu.deckPlaced(l.bodyMenu).transition(.opacity)
            }
            if model.countdown != nil, model.side == .inner, let camera = l.keepOut.first {
                LookHereBadge(camera: camera, canvas: l.canvas)
            }
            }
        }
        .frame(width: l.canvas.width, height: l.canvas.height, alignment: .topLeading)
        .clipped()
    }

    // The picture, in a screen's bezel; a swipe goes along the lenses, a
    // pinch zooms. (The zoom is written in the chosen stop, not in a
    // second label on the picture; the picture's own chips keep clear of
    // the stops.)
    private var viewfinder: some View {
        let clear = layout.stopsClearance
        // (Clear of a body's own words along the picture's top: the phone's bar, the digital camera's line.)
        let worn: CameraShellSkin? = plan?.skin ?? across?.skin
        let top: Double = worn == .phone || worn == .digital ? 22 : (worn == .vcd ? 28 : 0)
        return CameraTopScreen(model: model, clearBottom: clear.bottom, clearTrailing: clear.trailing, clearTop: top)
            .clipShape(RoundedRectangle(cornerRadius: 5, style: .continuous))
            .padding(6)
            .background(RoundedRectangle(cornerRadius: 12, style: .continuous).fill(Color(white: 0.07))
                .overlay(RoundedRectangle(cornerRadius: 12, style: .continuous).strokeBorder(.white.opacity(0.14), lineWidth: 1))
                .shadow(color: .black.opacity(0.35), radius: 3, y: 2))
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 20).onEnded { value in
                guard model.phase == .live else { return }
                let dx = value.translation.width, dy = value.translation.height
                guard abs(dx) > 40, abs(dx) > abs(dy) * 1.5 else { return }
                model.stepLens(dx < 0 ? 1 : -1)
            })
            .simultaneousGesture(MagnifyGesture().onChanged { value in
                if pinchFrom == nil { pinchFrom = model.zoom }
                model.setZoom((pinchFrom ?? 1) * value.magnification)
            }.onEnded { _ in pinchFrom = nil })
            .accessibilityElement(children: .contain)
            .accessibilityIdentifier("camera-deck-picture")
    }
    static func zoomText(_ zoom: Double) -> String {
        zoom < 1 ? String(format: "%.1f×", zoom) : (abs(zoom.rounded() - zoom) < 0.05 ? "\(Int(zoom.rounded()))×" : String(format: "%.1f×", zoom))
    }

    /// The zoom stops on the picture (0.5× with the rear dual camera). Small see-through dark circles with white numbers,
    /// nothing behind them; the chosen one larger, in the accent, with the
    /// zoom in it (a pinch's 1.7× too); each pressed as 44 points. Held
    /// across they run down the picture's edge beside 拍照, larger upward.
    private var zoomBar: some View {
        let stops = model.zoomStops
        let chosen = stops.last { $0 <= model.zoom + 0.05 } ?? stops.first ?? 1
        let column = layout.zoomColumn
        let stack = column ? AnyLayout(VStackLayout(spacing: 0)) : AnyLayout(HStackLayout(spacing: 0))
        return stack {
            ForEach(column ? Array(stops.reversed()) : stops, id: \.self) { z in
                let on = z == chosen
                let dot = on ? CoverDeckLayout.chosenStopDot : CoverDeckLayout.stopDot
                Button { model.setZoom(z, sound: true) } label: {
                    Text(on ? Self.zoomText(model.zoom) : Self.stopText(z))
                        .font(.system(size: on ? 11.5 : 10.5, weight: .heavy, design: .rounded))
                        .lineLimit(1).minimumScaleFactor(0.7)
                        .foregroundStyle(.white)
                        .frame(width: dot, height: dot)
                        .background(Circle().fill(on ? stopAccent : Color.black.opacity(0.5)))
                        .frame(width: CoverDeckLayout.target, height: CoverDeckLayout.target)
                        .contentShape(Rectangle())
                }
                .buttonStyle(MenuPressStyle())
                .disabled(model.phase == .album)
                .accessibilityLabel(z < 1 ? "超广角 0.5 倍" : "放大 \(Int(z)) 倍")
                .accessibilityValue(on ? Self.zoomText(model.zoom) : "")
                .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier(z < 1 ? "camera-deck-zoom-05" : "camera-deck-zoom-\(Int(z))")
            }
        }
        .animation(.easeOut(duration: 0.15), value: chosen)
    }
    /// A stop not chosen: the number alone (".5", "2").
    static func stopText(_ zoom: Double) -> String { zoom < 1 ? ".5" : "\(Int(zoom))" }
    /// The chosen stop's colour: the deck's accent; on the clamshell phone's
    /// screen, or the digital camera's, the colour that body's own is.
    private var stopAccent: Color {
        switch plan?.skin ?? across?.skin {
        case .phone?: return clamPaint.accent
        case .digital?: return digiPaint.accent
        case .computer?: return RetroPaint.ink
        case .soda?: return SodaPaint.on
        case .booth?: return BoothPaint.pink.color()
        case .vcd?: return VcdPaint.chip
        case .mp4?: return mp4Paint.accent.color()
        case .bike?: return BikePaint.accent
        case .cake?: return CakePaint.accent
        case .register?: return RegisterPaint.lit
        default: return FixedMenuStyle.accent
        }
    }

    private enum Chip: Hashable {
        case lens(CameraLens), body(CameraBody)
    }
    /// Where the deck's lens row stands (lensRow).
    #if os(iOS)
    @State private var deckLensRow = ScrollPosition(edge: .leading)
    #endif
    private var chips: [Chip] { CameraLens.allCases.map(Chip.lens) + model.pinnedBodies.map(Chip.body) }

    /// (Nine lenses in two lines are five columns, wider than the row: it is
    /// moved to the lens chosen — a swipe across the viewfinder can choose
    /// one that is scrolled out.)
    private func lensRow(lines: Int, width: CGFloat) -> some View {
        let all = chips
        return ScrollView(.horizontal, showsIndicators: false) {
            HStack(alignment: .top, spacing: 6) {
                // Column by column (not lazy: every chip is there to be found).
                ForEach(Array(stride(from: 0, to: all.count, by: lines)), id: \.self) { i in
                    VStack(spacing: 6) {
                        ForEach(i..<min(i + lines, all.count), id: \.self) { j in chipView(all[j]) }
                    }
                }
            }
            .padding(.horizontal, 2)
        }
        #if os(iOS)
        .scrollPosition($deckLensRow)
        #endif
        .accessibilityIdentifier("camera-deck-lenses")
        .onAppear { moveDeckLensRow(lines: lines, width: width, animated: false) }
        .onChange(of: model.lens) { _, _ in moveDeckLensRow(lines: lines, width: width) }
    }
    /// The row's place with the chosen lens's column in the middle, as far
    /// as the row goes (a chip's width and 6 between two columns, 2 before
    /// the first and after the last: the row's own measures).
    private func moveDeckLensRow(lines: Int, width: CGFloat, animated: Bool = true) {
        #if os(iOS)
        let all = chips
        guard lines > 0, width > 0, let at = all.firstIndex(of: .lens(model.lens)) else { return }
        let chip = CoverDeckLayout.lensChip.width, pitch = chip + 6
        let columns = (all.count + lines - 1) / lines
        let content = 4 + CGFloat(columns) * pitch - 6
        let centre = 2 + CGFloat(at / lines) * pitch + chip / 2
        let x = min(max(0, content - width), max(0, centre - width / 2))
        if animated { withAnimation(.easeOut(duration: 0.15)) { deckLensRow.scrollTo(x: x) } } else { deckLensRow.scrollTo(x: x) }
        #endif
    }
    @ViewBuilder private func chipView(_ item: Chip) -> some View {
        switch item {
        case .lens(let lens):
            chip(title: lens.title, glyph: .lens(lens), chosen: model.lens == lens, colour: FixedMenuStyle.accent,
                 identifier: "camera-deck-lens-\(lens.rawValue)") { model.choose(lens) }
        case .body(let pinned):
            chip(title: pinned.title, glyph: .body(pinned), chosen: model.body == pinned, colour: FixedMenuStyle.go,
                 identifier: "camera-deck-pinned-\(pinned.rawValue)") { model.tapPinned(pinned) }
        }
    }

    // 切换机型 on the cover: the inside's 机型
    // menu — the same cards, ★ to pin into the lens row — in two rows that
    // scroll, over the rows beside the picture.
    private var bodyMenu: some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 6) {
                Image(systemName: "camera.on.rectangle").font(.system(size: 11, weight: .bold))
                Text("切换机型").font(.system(size: 12.5, weight: .heavy, design: .rounded))
                Text(model.body.blurb).font(.system(size: 10, weight: .semibold, design: .rounded)).lineLimit(1).opacity(0.75).layoutPriority(-1)
                Spacer(minLength: 0)
                CameraStrengthStepper(model: model, s: 1, idPrefix: "camera-deck-", target: CoverDeckLayout.target)
                pill(String(localized: "收起"), "chevron.down", FixedMenuStyle.bar, "camera-deck-bodies-close") { model.closeBodies() }
            }
            // Two rows, column by column (not lazy: every card is there to be
            // found, the ones scrolled out too).
            let all = CameraBody.allCases
            ScrollViewReader { reader in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(alignment: .top, spacing: 6) {
                        ForEach(Array(stride(from: 0, to: all.count, by: 2)), id: \.self) { i in
                            VStack(spacing: 6) {
                                bodyCard(all[i])
                                if i + 1 < all.count { bodyCard(all[i + 1]) }
                            }
                        }
                    }
                    .padding(.horizontal, 1)
                }
                .onAppear { reader.scrollTo(model.body, anchor: .center) }
            }
        }
        .foregroundStyle(FixedMenuStyle.ink)
        .padding(8)
        .background(RoundedRectangle(cornerRadius: 12, style: .continuous).fill(FixedMenuStyle.paper)
            .shadow(color: .black.opacity(0.35), radius: 6, y: 3))
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("camera-deck-bodies-panel")
    }
    private func bodyCard(_ item: CameraBody) -> some View {
        // Where the menu is high enough (the deck held upright) the cards
        // show the whole sample; held across, a strip of it.
        let tall = layout.bodyMenu.height >= 240
        return CameraBodyCard(model: model, candidate: item, s: 1, bodyID: "camera-deck-body-", pinID: "camera-deck-pin-", showsPin: false,
                              swatchHeight: tall ? 42 : 22)
            .frame(width: 104, height: tall ? 70 : 50)
            .id(item)
    }

    /// A lens's chip: its glyph (a pinned body's, a small drawing of its kind
    /// of camera), and its name under it on the chosen one alone.
    private func chip(title: String, glyph: ShellGlyph, chosen: Bool, colour: Color, identifier: String, action: @escaping () -> Void) -> some View {
        let ink: Color = chosen ? Color.white : FixedMenuStyle.ink
        return Button(action: action) {
            VStack(spacing: 3) {
                ShellGlyphView(glyph: glyph, size: chosen ? 16 : 19, ink: ink)
                if chosen {
                    Text(title).font(.system(size: 10, weight: .bold, design: .rounded)).lineLimit(1).minimumScaleFactor(0.6)
                }
            }
            .foregroundStyle(ink)
            .frame(width: CoverDeckLayout.lensChip.width, height: CoverDeckLayout.lensChip.height)
            .background(RoundedRectangle(cornerRadius: 10, style: .continuous).fill(chosen ? colour : FixedMenuStyle.tile)
                .shadow(color: .black.opacity(0.25), radius: 0, y: 1.5))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(title)
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }

    // 相册 on the cover: the picture shows the photo, these go along them.
    private var albumRow: some View {
        HStack(spacing: 8) {
            if model.doodle != nil {
                // The editor needs the touch screen: it waits there.
                Text("正在编辑 · 打开 Duo，在下屏接着画")
                    .font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(.white)
                    .lineLimit(2).minimumScaleFactor(0.7).multilineTextAlignment(.center)
                    .frame(maxWidth: .infinity)
                    .accessibilityIdentifier("camera-deck-editing")
            } else {
                // ‹, ▶ (■ while it plays) and ›, each in a pill as wide as it was with its words.
                let earlier = String(localized: "上一张"), later = String(localized: "下一张")
                deckGlyphPill(earlier, "chevron.left", FixedMenuStyle.inkSoft, "camera-deck-album-previous", label: earlier, action: { model.moveInAlbum(-1) }) {
                    ShellGlyphView(glyph: .previous, size: 18, ink: Color.white)
                }
                if model.albumPhoto?.isVideo == true {
                    let playWord: String = model.playing == nil ? String(localized: "播放") : String(localized: "停止")
                    let playSymbol: String = model.playing == nil ? "play.fill" : "stop.fill"
                    let playGlyph: ShellGlyph = model.playing == nil ? .play : .stop
                    deckGlyphPill(playWord, playSymbol, FixedMenuStyle.accent, "camera-deck-album-play", label: playWord, action: { model.togglePlay() }) {
                        ShellGlyphView(glyph: playGlyph, size: 18, ink: Color.white)
                    }
                    .frame(maxWidth: .infinity)
                } else {
                    Text(model.photos.isEmpty ? "还没有照片" : "\(model.albumIndex + 1) / \(model.photos.count)")
                        .font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(.white)
                        .frame(maxWidth: .infinity)
                }
                deckGlyphPill(later, "chevron.right", FixedMenuStyle.inkSoft, "camera-deck-album-next", label: later, action: { model.moveInAlbum(1) }) {
                    ShellGlyphView(glyph: .next, size: 18, ink: Color.white)
                }
            }
        }
        .frame(height: CoverDeckLayout.target)
    }

    /// The deck's own row of keys, each a glyph drawn as what it sets stands
    /// (回去拍照 keeps its words beside its glyph); every pill as wide as it
    /// was with its words (deckGlyphPill), so that none moves along the row.
    private var toolRow: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 6) {
                // 主菜单 first, as on the touch screen
                // (camera-home) — the camera closes, back to the menu or the library.
                let homeWord = String(localized: "camera.home.pill")
                deckGlyphPill(homeWord, "house", FixedMenuStyle.inkSoft, "camera-deck-home", label: homeWord, action: { model.leave() }) {
                    ShellGlyphView(glyph: .home, size: 19, ink: Color.white)
                }
                if model.phase == .album {
                    if model.doodle == nil {
                        let back = String(localized: "回去拍照")
                        deckGlyphPill(back, "camera.fill", FixedMenuStyle.accent, "camera-deck-album-close", label: back, action: { model.closeAlbum() }) {
                            ShellGlyphLabel(glyph: .returnToShooting, words: back, size: 15, wordSize: 12, ink: Color.white)
                        }
                    }
                } else {
                    // 拍照 / 录像: a camera and a video camera, the one in use filled.
                    let video = model.mode == .video
                    let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
                    let modeWord: String = video ? videoWord : photoWord
                    let modeSymbol: String = video ? "video.fill" : "camera.fill"
                    let modeColour: Color = video ? CameraShutterFace.red : FixedMenuStyle.inkSoft
                    deckGlyphPill(modeWord, modeSymbol, modeColour, "camera-deck-mode", label: photoWord + " / " + videoWord, value: modeWord,
                                  action: { model.setMode(model.mode == .video ? .photo : .video) }) {
                        DeckModeGlyphs(video: video)
                    }
                    // The picture's shape (the viewfinder takes it at once): the
                    // third pill, in sight without the row being pushed along
                    // on the narrowest deck; pale where only 4:3 can be had (a
                    // video, a sheet, a body that prints on the whole picture).
                    // Its frame in the shape in use, and its figures.
                    let shapeWord = model.shape.title
                    let shapeTone: Color = model.shape == .full ? FixedMenuStyle.inkSoft : FixedMenuStyle.accent
                    let shapeColour: Color = model.canShape ? shapeTone : FixedMenuStyle.inkSoft.opacity(0.45)
                    deckGlyphPill(shapeWord, "aspectratio", shapeColour, "camera-deck-aspect", label: shapeWord, value: shapeWord,
                                  action: { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } }) {
                        ShellGlyphView(glyph: .shape(model.shape), size: 16, ink: Color.white)
                    }
                    // The stopwatch (the seconds it is set to at its corner);
                    // the seconds left beside it while a timed picture waits.
                    let timerColour: Color = model.timer == .off && model.countdown == nil ? FixedMenuStyle.inkSoft : FixedMenuStyle.accent
                    let timerValue: String = model.countdown.map { String(localized: "还有 \($0) 秒") } ?? model.timer.title
                    deckGlyphPill(timerTitle, "timer", timerColour, "camera-deck-timer", label: timerTitle, value: timerValue, action: { model.cycleTimer() }) {
                        DeckTimerGlyph(timer: model.timer, left: model.countdown)
                    }
                    let levelWord = String(localized: "水平仪")
                    let levelSymbol: String = model.leveler ? "level.fill" : "level"
                    let levelColour: Color = model.leveler ? FixedMenuStyle.accent : FixedMenuStyle.inkSoft
                    let levelState: String = model.leveler ? String(localized: "开") : String(localized: "关")
                    deckGlyphPill(levelWord, levelSymbol, levelColour, "camera-deck-leveler", label: levelWord, value: levelState, action: { model.toggleLeveler() }) {
                        ShellGlyphView(glyph: .level(model.leveler), size: 18, ink: Color.white)
                    }
                    // 11-06: 切换机型 where 主菜单 was (with the lid
                    // shut the menu is inside it; 主菜单 only shut the camera).
                    // Two cameras traded.
                    let bodiesWord: String = model.body == .native ? String(localized: "切换机型") : String(localized: "机型 · \(model.body.title)")
                    let bodiesColour: Color = model.body == .native ? FixedMenuStyle.inkSoft : FixedMenuStyle.accent
                    deckGlyphPill(bodiesWord, "camera.on.rectangle", bodiesColour, "camera-deck-bodies", label: bodiesWord, value: model.body.title,
                                  selected: model.bodiesOpen, action: { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } }) {
                        ShellGlyphView(glyph: .changeBody, size: 24, ink: Color.white)
                    }
                }
            }
            .padding(.horizontal, 1)
        }
        .accessibilityIdentifier("camera-deck-tools")
    }

    /// The self-timer's pill: 定时 off; the seconds when on; the seconds left
    /// while it counts.
    private var timerTitle: String {
        if let left = model.countdown { return String(localized: "\(left) 秒") }
        return model.timer == .off ? String(localized: "定时") : model.timer.title
    }
    private func pill(_ title: String, _ symbol: String, _ colour: Color, _ identifier: String,
                      value: String? = nil, label: String? = nil, selected: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            HStack(spacing: 5) {
                Image(systemName: symbol).font(.system(size: 11, weight: .bold))
                // Never cut short.
                Text(title).font(.system(size: 12, weight: .bold, design: .rounded)).lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
                    .monospacedDigit()
            }
            .foregroundStyle(.white)
            .padding(.horizontal, 14)
            .frame(minWidth: CoverDeckLayout.target, minHeight: CoverDeckLayout.target, maxHeight: CoverDeckLayout.target)
            .background(Capsule().fill(colour).shadow(color: .black.opacity(0.25), radius: 0, y: 1.5))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(label ?? title)
        .accessibilityValue(value ?? "")
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
    /// A pill of the deck's own rows with a glyph (`face`) in place of its
    /// words: the words (`room`, after its old small picture) stay in it out
    /// of sight, holding the width the pill had with them, so that no pill
    /// grows, shrinks or moves along its row. VoiceOver says `label`, as it
    /// said the words.
    private func deckGlyphPill<Face: View>(_ room: String, _ symbol: String, _ colour: Color, _ identifier: String, label: String, value: String? = nil,
                                           selected: Bool = false, action: @escaping () -> Void, @ViewBuilder face: () -> Face) -> some View {
        let drawn = face()
        return Button(action: action) {
            HStack(spacing: 5) {
                Image(systemName: symbol).font(.system(size: 11, weight: .bold))
                Text(room).font(.system(size: 12, weight: .bold, design: .rounded)).lineLimit(1)
                    .fixedSize(horizontal: true, vertical: false)
                    .monospacedDigit()
            }
            .hidden()
            .overlay { drawn }
            .foregroundStyle(.white)
            .padding(.horizontal, 14)
            .frame(minWidth: CoverDeckLayout.target, minHeight: CoverDeckLayout.target, maxHeight: CoverDeckLayout.target)
            .background(Capsule().fill(colour).shadow(color: .black.opacity(0.25), radius: 0, y: 1.5))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(label)
        .accessibilityValue(value ?? "")
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }

    // The right hand: the switch and the album, 拍照 under the thumb.
    // 内 / 外: a camera with two arrows turning round its lens (which side is
    // in use is on the picture, not on the key).
    private var flipTile: some View {
        tile(identifier: "camera-deck-switch", label: String(localized: "切换内侧、外侧相机"), value: model.side.title, action: { model.switchSide() }) {
            ShellGlyphView(glyph: .flip, size: 24, ink: FixedMenuStyle.ink)
        }
        .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
    }
    private var albumTile: some View {
        tile(identifier: "camera-deck-album", label: String(localized: "相册"), value: String(localized: "\(model.photos.count) 张"),
             action: { model.phase == .album ? model.closeAlbum() : model.openAlbum() }) {
            VStack(spacing: 3) {
                if let latest = model.photos.first, let image = thumbnails.images[latest.url] {
                    Image(decorative: image, scale: 1).resizable().scaledToFill()
                        .frame(width: 46, height: 32).clipped()
                        .clipShape(RoundedRectangle(cornerRadius: 3))
                } else {
                    ShellGlyphView(glyph: .album, size: 22, ink: FixedMenuStyle.ink)
                }
                // How many pictures: the figures alone.
                Text(verbatim: "\(model.photos.count)").font(.system(size: 11, weight: .bold, design: .rounded)).monospacedDigit().lineLimit(1)
            }
            .onAppear { if let latest = model.photos.first { thumbnails.request(latest.url) } }
            .onChange(of: model.photos.first?.url) { _, url in if let url { thumbnails.request(url) } }
        }
    }
    private var shutterButton: some View {
        Button { ConsoleHaptics.shared.play(.faceButton, .press); model.shutter() } label: {
            GeometryReader { geo in
                let d = min(geo.size.width, geo.size.height)
                ZStack {
                    Circle().fill(Color.white).shadow(color: .black.opacity(0.35), radius: 0, y: 3)
                    Circle().strokeBorder(FixedMenuStyle.tileEdge, lineWidth: 2.5)
                    if model.mode == .video {
                        // 录像 — a red dot; while recording, a stop square and the time.
                        Circle().fill(model.recording ? Color.white : (model.canShoot && !model.savingVideo ? CameraShutterFace.red : FixedMenuStyle.inkSoft.opacity(0.5)))
                            .padding(d * 0.11)
                        VStack(spacing: 2) {
                            if model.recording {
                                RoundedRectangle(cornerRadius: d * 0.05, style: .continuous).fill(CameraShutterFace.red).frame(width: d * 0.26, height: d * 0.26)
                                Text(CameraAppModel.clock(model.recordedSeconds)).font(.system(size: 11, weight: .heavy, design: .rounded)).monospacedDigit()
                                    .foregroundStyle(CameraShutterFace.red)
                            } else {
                                // A video camera (on grey while the last one is kept).
                                ShellGlyphView(glyph: .video(true), size: d * 0.3, ink: Color.white)
                            }
                        }
                        .foregroundStyle(.white)
                    } else {
                        Circle().fill(model.canShoot ? FixedMenuStyle.stop : FixedMenuStyle.inkSoft.opacity(0.5)).padding(d * 0.11)
                        // A camera; the stopwatch while the self-timer is set (its seconds at its corner).
                        let mark: ShellGlyph = model.timer == .off ? .photo(true) : .timer(model.timer)
                        ShellGlyphView(glyph: mark, size: d * 0.34, ink: Color.white)
                    }
                }
                .frame(width: d, height: d)
                .position(x: geo.size.width / 2, y: geo.size.height / 2)
            }
        }
        .buttonStyle(MenuPressStyle())
        .disabled(model.phase == .album)
        .opacity(model.phase == .album ? 0.4 : 1)
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
    }
    /// (11-23: that the iPhone's keys take pictures too, only on a new console the first time; the timer's line
    /// always)
    @ViewBuilder private var hintText: some View {
        if model.countdown != nil {
            deckHint("再点一次拍照键不会重来")
        } else {
            OnceHintView("camera-deck-keys") { deckHint("音量键、相机控制键也能拍") }
        }
    }
    private func deckHint(_ text: LocalizedStringKey) -> some View {
        Text(text)
            .font(.system(size: 10.5, weight: .semibold, design: .rounded))
            .foregroundStyle(.white.opacity(0.75))
            .lineLimit(2).multilineTextAlignment(.center)
            .accessibilityIdentifier("camera-deck-hint")
    }

    private func tile<Content: View>(identifier: String, label: String, value: String, action: @escaping () -> Void,
                                     @ViewBuilder content: () -> Content) -> some View {
        Button(action: action) {
            content()
                .foregroundStyle(FixedMenuStyle.ink)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(RoundedRectangle(cornerRadius: 13, style: .continuous).fill(FixedMenuStyle.tile)
                    .shadow(color: .black.opacity(0.3), radius: 0, y: 2))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(label)
        .accessibilityValue(value)
        .accessibilityIdentifier(identifier)
    }
}

/// 拍照 / 录像 on the deck's pill: a camera and a video camera, the one in
/// use filled and bright, the other in outline and paler.
private struct DeckModeGlyphs: View {
    var video: Bool
    var body: some View {
        let faint = Color.white.opacity(0.55)
        HStack(spacing: 6) {
            ShellGlyphView(glyph: .photo(!video), size: 17, ink: video ? faint : Color.white)
            ShellGlyphView(glyph: .video(video), size: 17, ink: video ? Color.white : faint)
        }
    }
}

/// 定时 on the deck's pill: the stopwatch (the seconds it is set to at its
/// corner); while a timed picture waits, the seconds left beside it.
private struct DeckTimerGlyph: View {
    var timer: CameraTimer
    var left: Int?
    var body: some View {
        if let left {
            HStack(spacing: 3) {
                ShellGlyphView(glyph: .timer(.off), size: 17, ink: Color.white)
                Text(verbatim: "\(left)").font(.system(size: 13, weight: .heavy, design: .rounded)).monospacedDigit()
                    .foregroundStyle(Color.white)
            }
        } else {
            ShellGlyphView(glyph: .timer(timer), size: 18, ink: Color.white)
        }
    }
}

/// Stood half open like a tent: the cover faces the people in the picture.
/// The picture as large as fits (a 3-second count at least, in numbers big
/// enough to read from a few steps away, and 「看这里」 by the camera), and
/// the controls along the bottom edge — the one on the table — clear of
/// the camera; a touch on the picture counts down too.
private struct CameraTentFace: View {
    @ObservedObject var model: CameraAppModel
    var layout: CoverTentLayout
    var finish: ShellFinish
    var hinge: CGRect
    var showsHardware: Bool
    var body: some View {
        let l = layout
        ZStack(alignment: .topLeading) {
            Color.black.frame(width: l.canvas.width, height: l.canvas.height)
            CoverHingeBand(finish: finish, rect: hinge, canvas: l.canvas).opacity(0.6)
            if showsHardware { CoverHardwareMarks(cameras: l.keepOut, control: nil, canvas: l.canvas) }
            HStack(spacing: 6) {
                Image(systemName: "triangle").font(.system(size: 11, weight: .heavy))
                Text("帐篷模式").font(.system(size: 12, weight: .heavy, design: .rounded))
                Text(model.countdown != nil ? "看镜头！再点一下取消" : "点画面或「倒数拍照」，倒数 \(max(3, model.timer.rawValue)) 秒后拍")
                    .font(.system(size: 11.5, weight: .semibold, design: .rounded)).opacity(0.85)
                Spacer(minLength: 0)
                Text(model.side == .inner ? "朝着大家的相机" : "背面的相机")
                    .font(.system(size: 11, weight: .bold, design: .rounded)).opacity(0.7)
            }
            .foregroundStyle(.white)
            .lineLimit(1).minimumScaleFactor(0.7)
            .deckPlaced(l.header)
            CameraTopScreen(model: model, countdownScale: 1.7)
                .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
                .contentShape(Rectangle())
                .onTapGesture { model.tentShutter() }
                // A container (not a button): the countdown inside stays
                // its own element (the 17e merged it away, 918).
                .accessibilityElement(children: .contain)
                .accessibilityIdentifier("camera-tent-picture")
                .accessibilityAction(named: "倒数拍照") { model.tentShutter() }
                .deckPlaced(l.picture)
            bar.deckPlaced(l.bar)
            if model.countdown != nil, model.side == .inner, let camera = l.camera {
                LookHereBadge(camera: camera, canvas: l.canvas, big: true)
            }
        }
        .frame(width: l.canvas.width, height: l.canvas.height, alignment: .topLeading)
        .clipped()
    }
    private var bar: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                button(String(localized: "‹ 镜头"), "camera-tent-lens-previous") { model.stepLens(-1) }
                button(model.lens.title, "camera-tent-lens") { model.stepLens(1) }
                button(String(localized: "镜头 ›"), "camera-tent-lens-next") { model.stepLens(1) }
                button(String(localized: "倒数 \(max(3, model.timer.rawValue)) 秒"), "camera-tent-timer") { model.cycleTimer() }
                button(model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), "camera-tent-switch") { model.switchSide() }
                button(model.countdown != nil ? String(localized: "取消") : String(localized: "倒数拍照"), "camera-tent-shutter", prominent: true) { model.tentShutter() }
            }
            .padding(.horizontal, 2)
            .frame(maxHeight: .infinity)
        }
    }
    private func button(_ title: String, _ identifier: String, prominent: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Text(title).font(.system(size: 13, weight: .bold, design: .rounded)).foregroundStyle(.white)
                .padding(.horizontal, 16)
                .frame(minWidth: CoverDeckLayout.target, minHeight: CoverDeckLayout.target)
                .background(Capsule().fill(prominent ? FixedMenuStyle.stop : Color.white.opacity(0.2)))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(title)
        .accessibilityIdentifier(identifier)
    }
}

extension CameraLens {
    /// 录像: a lens a video can use (合体, 不可思议, 两联 and 四连拍 make one
    /// picture).
    var records: Bool { self != .merge && self != .mystery && sheetCount == 1 }
}

/// The shutter's face on the touch screen: 拍照 (a camera, or the
/// self-timer), 录像 (a red dot; while recording a stop square).
struct CameraShutterFace: View {
    @ObservedObject var model: CameraAppModel
    var d: Double
    static let red = Color(red: 0.90, green: 0.16, blue: 0.20)
    var body: some View {
        ZStack {
            Circle().fill(Color.white).shadow(color: FixedMenuStyle.ink.opacity(0.3), radius: 0, y: d * 0.03)
            Circle().strokeBorder(FixedMenuStyle.tileEdge, lineWidth: d * 0.025)
            if model.mode == .video {
                if model.recording {
                    RoundedRectangle(cornerRadius: d * 0.07, style: .continuous).fill(Self.red)
                        .frame(width: d * 0.34, height: d * 0.34)
                } else {
                    Circle().fill(model.canShoot && !model.savingVideo ? Self.red : FixedMenuStyle.inkSoft.opacity(0.5)).padding(d * 0.11)
                    Image(systemName: "video.fill").font(.system(size: d * 0.26, weight: .bold)).foregroundStyle(.white)
                }
            } else {
                Circle().fill(model.canShoot ? FixedMenuStyle.stop : FixedMenuStyle.inkSoft.opacity(0.5)).padding(d * 0.11)
                Image(systemName: model.timer == .off ? "camera.fill" : "timer").font(.system(size: d * 0.29, weight: .bold)).foregroundStyle(.white)
            }
        }
        .frame(width: d, height: d)
    }
}

#if os(iOS)
/// 录像: a video of the album playing on the upper screen.
struct CameraVideoPlayer: UIViewRepresentable {
    let url: URL
    var ended: () -> Void
    final class PlayerView: UIView {
        override class var layerClass: AnyClass { AVPlayerLayer.self }
        var playerLayer: AVPlayerLayer { layer as! AVPlayerLayer }
        var url: URL?
        var watch: NSObjectProtocol?
    }
    func makeUIView(context: Context) -> PlayerView {
        let view = PlayerView()
        view.backgroundColor = .black
        view.playerLayer.videoGravity = .resizeAspect
        load(into: view)
        return view
    }
    func updateUIView(_ view: PlayerView, context: Context) {
        if view.url != url { load(into: view) }
    }
    static func dismantleUIView(_ view: PlayerView, coordinator: ()) {
        view.playerLayer.player?.pause()
        if let watch = view.watch { NotificationCenter.default.removeObserver(watch) }
        view.watch = nil
    }
    private func load(into view: PlayerView) {
        view.playerLayer.player?.pause()
        if let watch = view.watch { NotificationCenter.default.removeObserver(watch) }
        let item = AVPlayerItem(url: url)
        let player = AVPlayer(playerItem: item)
        // 11-07: muted in a silent test run (`--foldarc-silent`).
        player.isMuted = SilentRun.on
        view.playerLayer.player = player
        view.url = url
        let ended = self.ended
        view.watch = NotificationCenter.default.addObserver(forName: AVPlayerItem.didPlayToEndTimeNotification, object: item, queue: .main) { _ in
            MainActor.assumeIsolated { ended() }
        }
        player.play()
    }
}
#endif

// MARK: - The camera bodies' own backs on the cover (11-19)

/// Which of the bodies' own backs the cover wears: the instant camera's
/// and the keypad phone's so far, upright or across (each laid out on its
/// own), while taking pictures and in their albums (the instant camera's
/// prints in a pile, the phone's 图库). (The other bodies: the handheld's
/// own deck, as before.) Each is its own shape of keys in its own places, the
/// keys going down and sounding as that kind of machine's do; what the
/// keys do is the deck's own. (The keypad phone's is a clamshell phone's
/// lower half, made in four colours: ClamPaint. The pocket digital
/// camera's, `digital`, is a slim card camera in five colours, DigiPaint,
/// with stickers to put on it; `computerClass`, a pocket body too, wears
/// the retro computer's, `computer`: RetroLayout.)
enum CameraShellSkin: String, Sendable, CaseIterable {
    case instant, phone, toy, film, digital
    case computer
    case soda
    case booth
    case vcd
    case mp4
    case bike
    case cake
    case register
    static func worn(by body: CameraBody, album: Bool) -> CameraShellSkin? {
        if body == .photoBooth { return .booth }
        if body == .vcdStill { return .vcd }
        if body == .dreamcore00 { return .mp4 }
        if body == .afterSchool { return .bike }
        if body == .birthdayNight { return .cake }
        if body == .receipt { return .register }
        switch body.shell {
        case .instant: return .instant
        case .keyPhone: return .phone
        case .toy: return .toy
        case .compact: return .film
        case .pocket: return body == .computerClass ? .computer : .digital
        case .disposable: return body == .snackStall ? .soda : nil
        default: return nil
        }
    }
    /// The body's plastic.
    var tone: ShellTone {
        switch self {
        case .instant: return ShellTone(r: 0.93, g: 0.90, b: 0.83)
        case .phone: return ClamPaint.pink.plastic
        case .toy: return ShellTone(r: 0.22, g: 0.69, b: 0.894)
        case .film: return ShellTone(r: 0.17, g: 0.17, b: 0.18)
        case .digital: return DigiPaint.violet.body
        case .computer: return RetroPaint.plastic
        case .soda: return SodaPaint.mint
        case .booth: return BoothPaint.body
        case .vcd: return VcdPaint.wood
        case .mp4: return Mp4Paint.lavender.body
        case .bike: return BikePaint.paint
        case .cake: return CakePaint.board
        case .register: return RegisterPaint.body
        }
    }
    /// What this kind of machine calls the album, and the picture's shape.
    var albumTitle: String {
        switch self {
        case .instant: return String(localized: "相片")
        case .toy: return String(localized: "照片")
        case .film: return String(localized: "底片")
        case .phone: return String(localized: "图库")
        case .digital: return String(localized: "回放")
        case .computer: return String(localized: "图片盘")
        case .soda: return String(localized: "相册")
        case .booth: return String(localized: "相册")
        case .vcd: return String(localized: "碟片菜单")
        case .mp4: return String(localized: "相册")
        case .bike: return String(localized: "照片袋")
        case .cake: return String(localized: "相册")
        case .register: return String(localized: "小票")
        }
    }
    var shapeTitle: String {
        switch self {
        case .phone: return String(localized: "尺寸")
        case .digital: return String(localized: "比例")
        case .computer: return String(localized: "比例")
        case .soda: return String(localized: "画幅")
        case .booth: return String(localized: "画幅")
        case .vcd: return String(localized: "画幅")
        case .mp4: return String(localized: "画幅")
        case .bike: return String(localized: "画幅")
        case .cake: return String(localized: "画幅")
        case .register: return String(localized: "画幅")
        case .instant, .toy, .film: return String(localized: "画幅")
        }
    }
    /// Stickers can be put on this back (a switch of their own).
    var takesStickers: Bool {
        switch self {
        case .digital: return true
        case .computer: return false
        case .soda: return false
        case .booth: return false
        case .vcd: return false
        case .mp4: return false
        case .bike: return false
        case .cake: return false
        case .register: return false
        case .instant, .phone, .toy, .film: return false
        }
    }
}

extension CameraBody {
    /// The shutter as this kind of machine sounds.
    var shutterSound: ConsoleSound {
        switch shell {
        case .instant: return .instantShutter
        case .keyPhone: return .phoneShutter
        case .disposable: return self == .snackStall ? .corkPop : .shutter
        case .register: return .chime
        default: return .shutter
        }
    }
}

/// A colour of a body's back, lighter (k > 0) or darker (k < 0) at need.
struct ShellTone: Equatable {
    var r: Double
    var g: Double
    var b: Double
    func color(_ k: Double = 0) -> Color {
        let to = k >= 0 ? 1.0 : 0.0, a = min(1, abs(k))
        return Color(red: r + (to - r) * a, green: g + (to - g) * a, blue: b + (to - b) * a)
    }
    var isLight: Bool { r + g + b > 1.5 }
    /// What is written on it.
    var ink: Color { isLight ? Color(red: 0.30, green: 0.27, blue: 0.23) : Color(white: 0.94) }
}

/// One colour a camera body's back is made in: the name it is kept and
/// asked for by, what it is called, and the colour of the dot that shows it.
struct ShellTint: Equatable {
    var name: String
    var title: String
    var dot: ShellTone
}

extension CameraShellSkin {
    /// The colours this back is made in, the one it comes in first; none
    /// where it has only its own.
    var tints: [ShellTint] {
        switch self {
        case .phone: return ClamPaint.all.map(\.tint)
        case .digital: return DigiPaint.all.map(\.tint)
        case .computer: return []
        case .soda: return []
        case .booth: return []
        case .vcd: return []
        case .mp4: return Mp4Paint.all.map(\.tint)
        case .bike: return []
        case .cake: return []
        case .register: return []
        case .instant, .toy, .film: return []
        }
    }
}

/// The dot on a body that changes its colour, as a key: a bead of the
/// colour that comes next, in its small well.
struct ShellTintStyle: ButtonStyle {
    var dot: ShellTone
    var sound: ConsoleSound = .keySlide
    func makeBody(configuration: Configuration) -> some View { ShellTintBody(configuration: configuration, style: self) }
}
private struct ShellTintBody: View {
    let configuration: ButtonStyle.Configuration
    let style: ShellTintStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed, tone = style.dot
        let bead = RadialGradient(colors: [tone.color(0.4), tone.color(0), tone.color(-0.22)], center: UnitPoint(x: 0.35, y: 0.3), startRadius: 0.5, endRadius: 9)
        configuration.label
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(Circle().fill(bead).overlay(Circle().strokeBorder(Color.white.opacity(0.7), lineWidth: 0.8)))
            .scaleEffect(down ? 0.86 : 1)
            .background(Circle().fill(Color.black.opacity(0.42)).padding(-1.6).offset(y: 0.6))
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: 0.08), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// The key on a body's back that changes its colour: its dot shows the
/// colour that comes next; VoiceOver is told the one the body is worn in.
/// (Placed with `deckKey`: the dot small, the room round it touched with it.)
struct ShellTintKey: View {
    var now: ShellTint
    var next: ShellTint
    var sound: ConsoleSound = .keySlide
    var action: () -> Void
    var body: some View {
        Button(action: action) { Color.clear }
            .buttonStyle(ShellTintStyle(dot: next.dot, sound: sound))
            .accessibilityLabel(String(localized: "机身配色"))
            .accessibilityValue(now.title)
            .accessibilityIdentifier("camera-deck-tint")
    }
}

/// A key of a camera body's back. It goes down under the finger (a rubber
/// one squashes too) and sounds as it goes down — not when it is let go.
struct ShellKeyStyle: ButtonStyle {
    var tone: ShellTone
    var radius: CGFloat = 10
    var travel: CGFloat = 1.5
    var sound: ConsoleSound = .keyMetal
    var soft = false
    /// The light behind a phone's key while it is down.
    var glow: Color? = nil
    /// Brushed metal; a dome's light on its top; a round key's turned grooves.
    var brushed = false
    var dome = false
    var rings = false
    /// How it feels going down: a setting's key lightly, the shutter fully.
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View {
        ShellKeyBody(style: self, pressed: configuration.isPressed, label: AnyView(configuration.label))
    }
}

private struct ShellKeyBody: View {
    var style: ShellKeyStyle
    var pressed: Bool
    var label: AnyView
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: style.radius, style: .continuous)
        let tone = style.tone
        return label
            .foregroundStyle(tone.ink)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background {
                ZStack {
                    ShellKeyFace(tone: tone, radius: style.radius, pressed: pressed, brushed: style.brushed, dome: style.dome, rings: style.rings).equatable()
                    if pressed, let glow = style.glow { shape.fill(glow.opacity(0.32)) }
                }
                .shadow(color: Color.black.opacity(pressed ? 0.2 : 0.55), radius: pressed ? 0.5 : 2.5, y: pressed ? 0.5 : 2)
            }
            .scaleEffect(x: 1, y: style.soft && pressed ? 0.93 : 1, anchor: .bottom)
            .offset(y: pressed ? style.travel : 0)
            // The well it sits in (which does not go down with it).
            .background(shape.fill(Color.black.opacity(0.45)).padding(-1.5).offset(y: 1.5))
            // (The room round it is touched with it.)
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: pressed ? 0.04 : (style.soft ? 0.16 : 0.08)), value: pressed)
            .onChange(of: pressed) { _, down in
                guard down else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// A slide switch with two ends. Dragged, it stays at the nearer end;
/// touched, it goes over to the other. It clicks when it arrives.
struct ShellSlide: View {
    var on: Bool
    var tone: ShellTone
    var set: (Bool) -> Void
    /// Clear room over the slot that is touched with it (a small picture
    /// of each end stands there), and the slot's own colour.
    var head: CGFloat = 0
    var track = Color(white: 0.06)
    @Environment(\.deckKeyInset) private var room
    @State private var pull: CGFloat? = nil
    var body: some View {
        GeometryReader { geo in
            let h = max(0, geo.size.height - head - room.top - room.bottom), w = geo.size.width
            let thumb = max(h, w * 0.5), run = max(0, w - 4 - thumb)
            let rest: CGFloat = on ? run : 0
            let x = min(run, max(0, pull ?? rest))
            ZStack(alignment: .leading) {
                Capsule().fill(track)
                Capsule().strokeBorder(Color.white.opacity(0.16), lineWidth: 1)
                ShellSlideThumb(tone: tone)
                    .frame(width: thumb, height: max(0, h - 4))
                    .offset(x: 2 + x)
            }
            .frame(height: h)
            .padding(.bottom, room.bottom)
            .frame(maxHeight: .infinity, alignment: .bottom)
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 0)
                .onChanged { value in pull = rest + value.translation.width }
                .onEnded { value in
                    let next = abs(value.translation.width) < 5 ? !on : (rest + value.translation.width > run / 2)
                    withAnimation(.easeOut(duration: 0.1)) { pull = nil }
                    guard next != on else { return }
                    ConsoleSounds.shared.play(.keySlide, scale: 0.8)
                    ConsoleHaptics.shared.play(.sliderNotch, .press)
                    withAnimation(.easeOut(duration: 0.1)) { set(next) }
                })
        }
    }
}

private struct ShellSlideThumb: View {
    var tone: ShellTone
    var body: some View {
        let face = LinearGradient(colors: [tone.color(0.3), tone.color(0), tone.color(-0.25)], startPoint: .top, endPoint: .bottom)
        return Capsule().fill(face)
            .overlay(Capsule().strokeBorder(Color.white.opacity(0.45), lineWidth: 1))
            .overlay {
                HStack(spacing: 2.5) {
                    ForEach(0..<5, id: \.self) { _ in
                        Capsule().fill(Color.black.opacity(0.3)).frame(width: 1.2)
                    }
                }
                .padding(.vertical, 6)
            }
            .shadow(color: Color.black.opacity(0.6), radius: 1.5, y: 1)
    }
}

/// The instant camera's brightness dial: turned, a notch (half a stop) at a
/// time, each with its click; or touched on its left or right, one notch
/// that way. The lamps round it show where it stands; in its middle ± in a
/// circle (曝光), how it is set under it.
struct ShellDial: View {
    /// −2 … 2.
    var value: Double
    var caption: String
    var tone: ShellTone
    var step: (Int) -> Void
    @State private var from: Double? = nil
    @State private var turning = false
    @State private var slack: Double = 0
    /// Degrees of turn to a notch.
    static let notch = 24.0
    var body: some View {
        GeometryReader { geo in
            let d = min(geo.size.width, geo.size.height)
            let centre = CGPoint(x: geo.size.width / 2, y: geo.size.height / 2)
            ZStack {
                ShellDialFace(value: value, slack: slack, tone: tone)
                    .frame(width: d, height: d)
                VStack(spacing: 0) {
                    ShellGlyphView(glyph: .exposure(""), size: max(12, d * 0.12), ink: tone.ink)
                    Text(caption).font(.system(size: max(8, d * 0.08), weight: .heavy, design: .rounded)).monospacedDigit()
                }
                .foregroundStyle(tone.ink)
                .allowsHitTesting(false)
            }
            .frame(width: geo.size.width, height: geo.size.height)
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 0)
                .onChanged { value in
                    let angle = Double(atan2(value.location.y - centre.y, value.location.x - centre.x)) * 180 / .pi
                    guard let last = from else { from = angle; return }
                    if abs(value.translation.width) + abs(value.translation.height) > 8 { turning = true }
                    guard turning else { return }
                    var turn = angle - last
                    if turn > 180 { turn -= 360 }
                    if turn < -180 { turn += 360 }
                    if abs(turn) >= Self.notch {
                        from = angle
                        slack = 0
                        ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
                        step(turn > 0 ? 1 : -1)
                    } else {
                        slack = turn
                    }
                }
                .onEnded { value in
                    if !turning {
                        ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
                        step(value.location.x < centre.x ? -1 : 1)
                    }
                    from = nil
                    turning = false
                    withAnimation(.easeOut(duration: 0.12)) { slack = 0 }
                })
        }
    }
}

private struct ShellDialFace: View {
    var value: Double
    var slack: Double
    var tone: ShellTone
    var body: some View {
        Canvas { context, size in
            let d = min(size.width, size.height), c = CGPoint(x: size.width / 2, y: size.height / 2)
            let ink = tone.ink
            func at(_ degrees: Double, _ radius: CGFloat) -> CGPoint {
                let a = degrees * Double.pi / 180
                return CGPoint(x: c.x + CGFloat(cos(a)) * radius, y: c.y + CGFloat(sin(a)) * radius)
            }
            // The disc with its turned grooves.
            let r = d * 0.406
            let disc = CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r)
            let plate = tone.color(-0.1)
            context.fill(Path(ellipseIn: disc.insetBy(dx: -3, dy: -3)), with: .color(Color.black.opacity(0.45)))
            context.fill(Path(ellipseIn: disc), with: .radialGradient(Gradient(colors: [tone.color(0.35), plate, tone.color(-0.42)]),
                                                                      center: CGPoint(x: c.x - r * 0.3, y: c.y - r * 0.4), startRadius: r * 0.1, endRadius: r * 1.25))
            var k: CGFloat = 0.82
            while k > 0.45 {
                context.stroke(Path(ellipseIn: disc.insetBy(dx: r * (1 - k), dy: r * (1 - k))), with: .color(Color.black.opacity(0.11)), lineWidth: 0.8)
                k -= 0.18
            }
            context.stroke(Path(ellipseIn: disc.insetBy(dx: 0.7, dy: 0.7)), with: .color(Color.white.opacity(0.4)), lineWidth: 1)
            // What each stop stands for, on the disc; its lamp outside it.
            let marks = ["house.fill", "cloud.fill", "sun.min.fill", "sun.max.fill", "plus"]
            for index in 0..<5 {
                let stop = Double(index - 2), degrees = -90 + stop * 30
                context.draw(Text(Image(systemName: marks[index])).font(.system(size: d * (index == 3 ? 0.105 : 0.09), weight: .bold)).foregroundColor(ink.opacity(0.9)),
                             at: at(degrees, d * 0.29))
                let near = max(0, 1 - abs(value - stop))
                let p = at(degrees, d * 0.478)
                let lamp = CGRect(x: p.x - 2.2, y: p.y - 2.2, width: 4.4, height: 4.4)
                context.fill(Path(ellipseIn: lamp.insetBy(dx: -1.2, dy: -1.2)), with: .color(Color.black.opacity(0.55)))
                context.fill(Path(ellipseIn: lamp), with: .color(near > 0.05 ? Color(red: 1.0, green: 0.6, blue: 0.16).opacity(0.3 + 0.7 * near) : Color(red: 0.47, green: 0.43, blue: 0.38)))
            }
            // The hub that turns, its red mark at where it stands.
            let h = d * 0.152
            let hub = CGRect(x: c.x - h, y: c.y - h, width: 2 * h, height: 2 * h)
            context.fill(Path(ellipseIn: hub), with: .color(tone.color(0.35)))
            context.stroke(Path(ellipseIn: hub), with: .color(Color.black.opacity(0.22)), lineWidth: 1)
            let turned = -90 + value * 30 + slack * 0.5
            var pointer = Path()
            pointer.move(to: at(turned, h + 7))
            pointer.addLine(to: at(turned - 20, h - 1))
            pointer.addLine(to: at(turned + 20, h - 1))
            pointer.closeSubpath()
            context.fill(pointer, with: .color(Color(red: 0.85, green: 0.3, blue: 0.22)))
        }
    }
}

/// A phone's navigation key: a ring that gives toward the side pressed,
/// round the key in its middle (which is a key of its own).
struct ShellNavigationKey<Centre: View>: View {
    var tone: ShellTone
    /// Arrows on all four sides (moving among things), not + and − up and down.
    var arrows = false
    /// What each side does, as VoiceOver says it (up, right, down, left);
    /// nil: moving that way (the arrows), or the camera's 变焦 and 镜头.
    var names: [String]? = nil
    private var said: [String] {
        if let names, names.count == 4 { return names }
        return arrows ? [String(localized: "向上"), String(localized: "向右"), String(localized: "向下"), String(localized: "向左")]
            : [String(localized: "变焦") + " +", String(localized: "镜头") + " ›", String(localized: "变焦") + " −", String(localized: "镜头") + " ‹"]
    }
    /// 0 up, 1 right, 2 down, 3 left.
    var press: (Int) -> Void
    @ViewBuilder var centre: () -> Centre
    @State private var side: Int? = nil
    private static func side(_ at: CGPoint, in size: CGSize) -> Int {
        let dx = at.x - size.width / 2, dy = at.y - size.height / 2
        if abs(dx) > abs(dy) { return dx > 0 ? 1 : 3 }
        return dy < 0 ? 0 : 2
    }
    var body: some View {
        GeometryReader { geo in
            let d = min(geo.size.width, geo.size.height)
            let lean: CGSize = side == 0 ? CGSize(width: 0, height: -1.4) : side == 1 ? CGSize(width: 1.4, height: 0)
                : side == 2 ? CGSize(width: 0, height: 1.4) : side == 3 ? CGSize(width: -1.4, height: 0) : .zero
            ZStack {
                ShellNavigationRing(tone: tone, side: side, arrows: arrows)
                    .frame(width: d, height: d)
                    .offset(lean)
                    .contentShape(Rectangle())
                    .gesture(DragGesture(minimumDistance: 0)
                        .onChanged { value in
                            let now = Self.side(value.location, in: CGSize(width: d, height: d))
                            guard now != side else { return }
                            side = now
                            ConsoleSounds.shared.play(.phoneSoft, scale: 0.6)
                            ConsoleHaptics.shared.play(.dpad, .press)
                        }
                        .onEnded { _ in
                            if let side { press(side) }
                            side = nil
                        })
                    .animation(.easeOut(duration: 0.06), value: side)
                    .accessibilityElement()
                    .accessibilityLabel(String(localized: "方向键"))
                    .accessibilityAction(named: Text(said[0])) { press(0) }
                    .accessibilityAction(named: Text(said[1])) { press(1) }
                    .accessibilityAction(named: Text(said[2])) { press(2) }
                    .accessibilityAction(named: Text(said[3])) { press(3) }
                centre().frame(width: d * 0.52, height: d * 0.52)
            }
            .frame(width: geo.size.width, height: geo.size.height)
        }
    }
}

private struct ShellNavigationRing: View {
    var tone: ShellTone
    var side: Int?
    var arrows = false
    var body: some View {
        GeometryReader { geo in
            let d = min(geo.size.width, geo.size.height)
            let shape = RoundedRectangle(cornerRadius: d * 0.22, style: .continuous)
            let chrome = LinearGradient(colors: [Color(white: 0.98), Color(white: 0.62), Color(white: 0.93), Color(white: 0.52), Color(white: 0.85)],
                                        startPoint: .topLeading, endPoint: .bottomTrailing)
            // The shade on the side that is down.
            let from: UnitPoint = side == 0 ? .top : side == 1 ? .trailing : side == 2 ? .bottom : .leading
            let to: UnitPoint = side == 0 ? .bottom : side == 1 ? .leading : side == 2 ? .top : .trailing
            ZStack {
                shape.fill(Color.black.opacity(0.5)).padding(-2).offset(y: 1.5)
                shape.fill(chrome).shadow(color: Color.black.opacity(0.55), radius: 2.5, y: 2)
                shape.strokeBorder(Color.white.opacity(0.55), lineWidth: 1)
                if side != nil {
                    shape.fill(LinearGradient(colors: [Color.black.opacity(0.3), Color.black.opacity(0)], startPoint: from, endPoint: to))
                }
                ForEach(0..<4, id: \.self) { index in
                    let names = arrows ? ["chevron.up", "chevron.right", "chevron.down", "chevron.left"] : ["plus", "chevron.right", "minus", "chevron.left"]
                    let a = Double(index) * Double.pi / 2 - Double.pi / 2
                    Image(systemName: names[index])
                        .font(.system(size: d * 0.11, weight: .heavy))
                        .foregroundStyle(Color(white: 0.2))
                        .offset(x: CGFloat(cos(a)) * d * 0.38, y: CGFloat(sin(a)) * d * 0.38)
                }
            }
            .frame(width: geo.size.width, height: geo.size.height)
        }
    }
}

/// The instant camera's slot. The newest print stands out of it (touched:
/// the album); when a picture has been kept the motor pushes a new one out,
/// blank at first, the picture coming up on it over a few seconds.
private struct InstantSlot: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var tone: ShellTone
    /// With the album's glyph and the count beside the slot (upright);
    /// without, the slot is the whole width (the band's run, held across).
    var counted = true
    /// How far the print is out (0: all of it inside), and how blank it still is.
    @State private var out: CGFloat = 1
    @State private var blank: Double = 0
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            let line = h - 10, rise = max(0, line - 4)
            let card = counted ? min(150, w * 0.4) : min(132, w * 0.7), tall = rise + 26, mid = counted ? w * 0.285 : w * 0.5
            let latest = model.photos.first
            Button { model.openAlbum() } label: {
                ZStack(alignment: .topLeading) {
                    // The print: only what is above the slot's line is seen.
                    if let latest {
                        InstantPrint(image: thumbnails.images[latest.url], blank: blank)
                            .frame(width: card, height: tall)
                            .rotationEffect(.degrees(-1.2))
                            .position(x: mid, y: line - rise * out + tall / 2)
                            .frame(width: w, height: line, alignment: .topLeading)
                            .clipped()
                    }
                    // The slot, and its lower lip in the body's colour.
                    Capsule().fill(LinearGradient(colors: [Color(white: 0.04), Color(red: 0.16, green: 0.15, blue: 0.14), tone.color(-0.1)], startPoint: .top, endPoint: .bottom))
                        .frame(width: counted ? w * 0.78 : w, height: 12)
                        .position(x: counted ? w * 0.411 : w / 2, y: line + 6)
                    // What it is (the album's glyph), and how many there are.
                    if counted {
                        HStack(spacing: 4) {
                            ShellGlyphView(glyph: .album, size: 15, ink: tone.ink)
                            Text(verbatim: "\(model.photos.count)").font(.system(size: 12, weight: .heavy, design: .rounded)).monospacedDigit()
                        }
                        .foregroundStyle(tone.ink)
                        .frame(width: max(0, w - 6), height: max(0, line - 6), alignment: .bottomTrailing)
                    }
                }
                .frame(width: w, height: h, alignment: .topLeading)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .onAppear { if let latest { thumbnails.request(latest.url) } }
            .onChange(of: model.photos.first?.url) { old, url in
                guard let url else { return }
                thumbnails.request(url)
                // (Only a picture just taken comes out of the slot: one more
                // than there was.)
                guard old != url, model.phase == .live else { return }
                var still = Transaction()
                still.disablesAnimations = true
                withTransaction(still) { out = 0; blank = 1 }
                ConsoleSounds.shared.play(.instantEject, scale: 0.9)
                Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 60_000_000)
                    withAnimation(.linear(duration: 1.42)) { out = 1 }
                    withAnimation(.easeIn(duration: 5).delay(1.3)) { blank = 0 }
                }
            }
        }
    }
}

private struct InstantPrint: View {
    var image: CGImage?
    var blank: Double
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, inset: CGFloat = 8
            ZStack(alignment: .top) {
                RoundedRectangle(cornerRadius: 2.5, style: .continuous).fill(Color(red: 0.985, green: 0.975, blue: 0.955))
                    .shadow(color: Color.black.opacity(0.3), radius: 2, y: 1)
                ZStack {
                    Color(red: 0.16, green: 0.16, blue: 0.15)
                    if let image {
                        Image(decorative: image, scale: 1).resizable().scaledToFill()
                    }
                    Color(red: 0.80, green: 0.82, blue: 0.78).opacity(blank)
                }
                .frame(width: max(0, w - 2 * inset), height: max(0, (w - 2 * inset) * 0.78))
                .clipped()
                .padding(.top, inset)
            }
        }
    }
}

/// Where the parts of a body's own back are: the Duo's cover's points
/// (the column 372 wide from x 14), scaled across to the column there is;
/// heights as they are, the picture's from its width.
struct ShellPlan: Equatable {
    var skin: CameraShellSkin
    var back: CoverBackFrame
    var u: CGFloat { back.column.width / CGFloat(CoverBackFrame.designWidth) }
    var top: CGFloat { back.column.minY }
    func x(_ at: CGFloat) -> CGFloat { back.column.minX + (at - 14) * u }
    /// The screen's glass (the phone, the digital camera's LCD) or the
    /// finder's plate (the instant camera) at its full height, where it
    /// begins, and how far the keys run under it.
    private var fullHeight: CGFloat {
        switch skin {
        case .phone: return 344 * u * 0.75 + 10
        case .film: return 344 * u * 0.75 + 28
        case .toy: return 314 * u * 0.75 + 42
        case .instant: return 340 * u * 0.75 + 24
        case .digital: return 360 * u * 0.75 + 13
        case .computer: return retroTubeHeight
        case .soda: return (343 * u - 23) * 0.75 + 23
        case .booth: return 320 * u * 0.75 + 36
        case .vcd: return 360 * u * 0.75
        case .mp4: return 344 * u * 0.75 + 70
        case .bike: return 344 * u * 0.75
        case .cake: return 332 * u * 0.75
        case .register: return 344 * u * 0.75 + 30
        }
    }
    private var surroundTop: CGFloat {
        switch skin {
        case .phone: return top - 6
        case .film: return top + 42
        case .toy: return top + 34
        case .instant: return top + 62
        case .digital: return top + 13
        case .computer: return top + 28
        case .soda: return top + 48.5
        case .booth: return top + 50
        case .vcd: return top + 2
        case .mp4: return top - 4
        case .bike: return top + 2
        case .cake: return top + 10
        case .register: return top - 4
        }
    }
    private var keysRun: CGFloat { keysGap + keysHeight }
    /// From the picture's surround to the keys, and how far they run.
    private var keysGap: CGFloat {
        switch skin {
        case .phone: return 22
        case .toy, .film: return 14
        case .instant: return 8
        case .digital: return 10
        case .computer: return 8
        case .soda: return 4.5
        case .booth: return 4
        case .vcd: return 31
        case .mp4: return 10
        case .bike: return 10
        case .cake: return 9
        case .register: return 54
        }
    }
    private var keysHeight: CGFloat {
        switch skin {
        case .phone: return 344
        case .film: return 284
        case .toy: return 288
        case .instant: return 262
        case .digital: return 306
        case .computer: return retroKeysHeight
        case .soda: return sodaKeysHeight
        case .booth: return 300
        case .vcd: return vcdKeysHeight
        case .mp4: return 292
        case .bike: return 360
        case .cake: return 362
        case .register: return 292
        }
    }
    /// How far all that would go below the column: up to 40 points are
    /// taken off the picture's height (a cover a little shorter than the
    /// Duo's as it was measured); more, and this back does not fit.
    var short: CGFloat { max(0, surroundTop + fullHeight + keysRun - back.column.maxY) }
    var fits: Bool { short <= 40 }
    var surround: CGRect {
        let h = fullHeight - min(short, 40)
        switch skin {
        case .phone: return CGRect(x: x(20), y: surroundTop, width: 362 * u, height: h)
        case .instant: return CGRect(x: back.column.minX, y: surroundTop, width: back.column.width, height: h)
        case .toy: return CGRect(x: x(36), y: surroundTop, width: 356 * u, height: h)
        case .film: return CGRect(x: back.column.minX, y: surroundTop, width: back.column.width, height: h)
        case .digital: return CGRect(x: x(14), y: surroundTop, width: 372 * u, height: h)
        case .computer: return CGRect(x: back.column.minX, y: surroundTop, width: back.column.width, height: h)
        case .soda: return CGRect(x: x(29.5), y: surroundTop, width: 343 * u, height: h)
        case .booth: return CGRect(x: x(16), y: surroundTop, width: 368 * u, height: h)
        case .vcd: return CGRect(x: x(22), y: surroundTop, width: 360 * u, height: h)
        case .mp4: return CGRect(x: x(16), y: surroundTop, width: 368 * u, height: h)
        case .bike: return CGRect(x: x(32), y: surroundTop, width: 344 * u, height: h)
        case .cake: return CGRect(x: x(26), y: surroundTop, width: 332 * u, height: h)
        case .register: return CGRect(x: x(16), y: surroundTop, width: 370 * u, height: h)
        }
    }
    /// The picture's place (4:3 unless the column is short); another shape
    /// stands in the middle of it.
    var box: CGRect {
        let s = surround
        switch skin {
        case .phone: return CGRect(x: x(29), y: s.minY + 5, width: 344 * u, height: max(0, s.height - 10))
        case .instant: return CGRect(x: x(30), y: s.minY + 12, width: 340 * u, height: max(0, s.height - 24))
        case .toy: return CGRect(x: x(57), y: s.minY + 21, width: 314 * u, height: max(0, s.height - 42))
        case .film: return CGRect(x: x(28), y: s.minY + 12, width: 344 * u, height: max(0, s.height - 28))
        case .digital: return CGRect(x: x(20), y: s.minY + 7, width: 360 * u, height: max(0, s.height - 13))
        case .computer: return CGRect(x: s.minX + 19, y: s.minY + 37.6, width: max(0, s.width - 38), height: max(0, s.height - 54.6))
        case .soda: return CGRect(x: s.minX + 11.5, y: s.minY + 11.5, width: max(0, s.width - 23), height: max(0, s.height - 23))
        case .booth: return CGRect(x: x(40), y: s.minY + 18, width: 320 * u, height: max(0, s.height - 36))
        case .vcd: return s
        case .mp4: return CGRect(x: x(28), y: s.minY + 34, width: 344 * u, height: max(0, s.height - 70))
        case .bike: return s
        case .cake: return s
        case .register: return CGRect(x: x(29), y: s.minY + 15, width: 344 * u, height: max(0, s.height - 30))
        }
    }
    func picture(aspect: Double) -> CGRect {
        let b = box
        guard aspect > 0, b.height > 0 else { return b }
        let w = min(b.width, b.height * CGFloat(aspect)), h = w / CGFloat(aspect)
        return CGRect(x: b.midX - w / 2, y: b.midY - h / 2, width: w, height: h)
    }
    /// Where the keys begin under it, and how far down they go.
    var keysTop: CGFloat { surround.maxY + keysGap }
    var keysBottom: CGFloat { keysTop + keysHeight }
    /// The shutter in the strip, under the Camera Control's overlay (the
    /// phone's: the key on its side, 56 wide in the strip's middle).
    var shutter: CGRect {
        let s = back.strip, floor = back.column.maxY
        let under = max((back.overlay?.maxY ?? 0) + 10, floor - (skin == .phone ? 92 : 72))
        if skin == .phone { return CGRect(x: s.midX - 28, y: under, width: 56, height: max(0, floor - 6 - under)) }
        let d = min(s.width - 2, floor - 4 - under)
        return CGRect(x: s.midX - d / 2, y: floor - 4 - d, width: d, height: d)
    }
    /// The deck's own layout with this back's picture, zoom stops and menu
    /// in it (the deck's own parts are drawn from that); nil when the keys
    /// do not fit under the picture or the shutter has no room.
    func layout(from plain: CoverDeckLayout, aspect: Double, zoomStops: Int) -> CoverDeckLayout? {
        guard fits, shutter.height >= 56, shutter.width >= 44, !back.keepOut.contains(where: { $0.intersects(shutter) }) else { return nil }
        var l = plain
        let p = picture(aspect: aspect)
        l.viewfinder = p.insetBy(dx: -6, dy: -6)
        let run = CGFloat(max(1, zoomStops)) * CGFloat(CoverDeckLayout.target)
        l.zoomBar = CGRect(x: p.midX - run / 2, y: p.maxY - (skin == .phone ? 25 : 4) - CGFloat(CoverDeckLayout.target), width: run, height: CGFloat(CoverDeckLayout.target))
        l.lensRow = .zero
        l.toolRow = .zero
        l.shootingRow = .zero
        l.hint = .zero
        l.album = .zero
        l.flip = .zero
        l.shutter = shutter
        l.pictureBelow = false
        l.keys = CGRect(x: back.column.minX, y: keysTop, width: back.column.width, height: back.column.maxY - keysTop)
        let menu = max(CGFloat(plain.bodyMenu.height), 156)
        l.bodyMenu = CGRect(x: back.column.minX, y: min(keysTop, back.column.maxY - menu), width: back.column.width, height: menu)
        return l
    }
}

/// A key's face, drawn: the gradient of its top, a brushed metal's lines,
/// a dome's light, a round key's turned grooves, the bevel; darker while down.
private struct ShellKeyFace: View, Equatable {
    var tone: ShellTone
    var radius: CGFloat
    var pressed: Bool
    var brushed = false
    var dome = false
    var rings = false
    var body: some View {
        Canvas { context, size in
            let rect = CGRect(origin: .zero, size: size)
            let half = min(size.width, size.height) / 2
            let r = min(radius, half)
            let shape = Path(roundedRect: rect, cornerRadius: r, style: .continuous)
            let round = r >= half - 0.5 && abs(size.width - size.height) < 2
            if round {
                let q = size.width / 2
                context.fill(Path(ellipseIn: rect), with: .radialGradient(Gradient(colors: [tone.color(0.45), tone.color(0), tone.color(-0.38)]),
                                                                         center: CGPoint(x: q * 0.7, y: q * 0.6), startRadius: q * 0.1, endRadius: q * 1.25))
                if rings {
                    var k: CGFloat = 0.82
                    while k > 0.2 {
                        context.stroke(Path(ellipseIn: rect.insetBy(dx: q * (1 - k), dy: q * (1 - k))), with: .color(Color.black.opacity(0.12)), lineWidth: 0.8)
                        k -= 0.18
                    }
                }
            } else {
                context.fill(shape, with: .linearGradient(Gradient(colors: [tone.color(0.25), tone.color(0), tone.color(-0.22)]),
                                                          startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height)))
            }
            if brushed {
                var inner = context
                inner.clip(to: shape)
                var seed: UInt32 = 7
                for _ in 0..<Int(size.height * 1.4) {
                    seed = seed &* 1_664_525 &+ 1_013_904_223
                    let y = CGFloat((seed >> 8) & 0xFFFF) / 65535 * size.height
                    seed = seed &* 1_664_525 &+ 1_013_904_223
                    let a = Double((seed >> 8) & 0xFF) / 255 * 0.11
                    let ink = (seed >> 20) & 1 == 0 ? Color.white : Color.black
                    inner.fill(Path(CGRect(x: 0, y: y, width: size.width, height: 0.5)), with: .color(ink.opacity(a)))
                }
            }
            if dome {
                let light = Path(roundedRect: CGRect(x: 2, y: 1.5, width: max(0, size.width - 4), height: size.height * 0.45), cornerRadius: r, style: .continuous)
                context.fill(light, with: .linearGradient(Gradient(colors: [Color.white.opacity(0.26), Color.white.opacity(0)]),
                                                          startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height * 0.5)))
            }
            let rim = Path(roundedRect: rect.insetBy(dx: 0.7, dy: 0.7), cornerRadius: max(0, r - 0.7), style: .continuous)
            context.stroke(rim, with: .color(Color.white.opacity(pressed ? 0.12 : 0.42)), lineWidth: 1)
            if pressed { context.fill(shape, with: .color(Color.black.opacity(0.14))) }
        }
    }
}

/// The body round the picture and under the keys, drawn as the pictures of
/// it were (mock/shell_lib.js, part for part): the plastic and its grain
/// or its brushing, the hinge's shade, the screen's glass or the finder's
/// plate, the earpiece, the speaker's holes, the grip where the Camera
/// Control's overlay comes in. Drawn once (it is the same until the deck
/// is another size or the picture another shape).
private struct ShellBackdrop: View, Equatable {
    var plan: ShellPlan
    var hinge: CGRect
    var body: some View {
        Canvas { context, size in
            let whole = CGRect(origin: .zero, size: size)
            let g = context
            let skin = plan.skin, tone = skin.tone, back = plan.back, s = back.strip, u = plan.u
            // the plastic, lit from the upper left
            context.fill(Path(whole), with: .linearGradient(Gradient(colors: [tone.color(0.22), tone.color(0), tone.color(-0.28)]),
                                                            startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
            var seed: UInt32 = 0x1234_5678
            func next() -> CGFloat {
                seed = seed &* 1_664_525 &+ 1_013_904_223
                return CGFloat((seed >> 8) & 0xFFFF) / 65535
            }
            if skin == .phone {
                // brushed down its length
                for _ in 0..<Int(size.width * 1.5) {
                    let x = next() * size.width, a = Double(next()) * 0.06
                    context.fill(Path(CGRect(x: x, y: 0, width: 0.5, height: size.height)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
                }
            } else {
                // the plastic's fine grain
                for _ in 0..<Int(size.width * size.height / 110) {
                    let at = CGPoint(x: next() * size.width, y: next() * size.height), a = Double(next()) * 0.05
                    context.fill(Path(CGRect(x: at.x, y: at.y, width: 1, height: 1)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
                }
            }
            // the hinge's side falls into shade
            if hinge.width > 0, hinge.height > 0, hinge.width < hinge.height {
                let deep = CGRect(x: hinge.minX, y: hinge.minY, width: hinge.width + 2, height: hinge.height)
                context.fill(Path(deep), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.45), Color.black.opacity(0)]),
                                                               startPoint: CGPoint(x: deep.minX, y: 0), endPoint: CGPoint(x: deep.maxX, y: 0)))
            }
            func dots(_ origin: CGPoint, _ columns: Int, _ rows: Int, _ gap: CGFloat, _ r: CGFloat) {
                guard columns > 0, rows > 0 else { return }
                for i in 0..<columns {
                    for j in 0..<rows {
                        let hole = CGRect(x: origin.x + CGFloat(i) * gap - r, y: origin.y + CGFloat(j) * gap - r, width: 2 * r, height: 2 * r)
                        g.fill(Path(ellipseIn: hole), with: .color(Color.black.opacity(0.6)))
                        g.stroke(Path(ellipseIn: hole.offsetBy(dx: 0, dy: 0.6)), with: .color(Color.white.opacity(0.16)), lineWidth: 0.5)
                    }
                }
            }
            let sur = plan.surround
            if skin == .phone {
                // the earpiece and its mesh, two sensors
                let ear = CGRect(x: plan.x(150), y: plan.top + 13, width: 100 * u, height: 6)
                context.fill(Path(roundedRect: ear, cornerRadius: 3), with: .color(Color(white: 0.02)))
                context.stroke(Path(roundedRect: ear.offsetBy(dx: 0, dy: 0.8), cornerRadius: 3), with: .color(Color.white.opacity(0.25)), lineWidth: 0.8)
                dots(CGPoint(x: ear.minX + 6, y: ear.midY), Int((ear.width - 12) / 4.9) + 1, 1, 4.9, 0.9)
                for dx in [plan.x(306), plan.x(318)] {
                    context.fill(Path(ellipseIn: CGRect(x: dx - 2.4, y: plan.top + 13.6, width: 4.8, height: 4.8)), with: .color(Color(white: 0.04)))
                }
                // the screen sunk in the body, its glass
                let well = Path(roundedRect: sur.insetBy(dx: -6, dy: -6), cornerRadius: 18, style: .continuous)
                context.fill(well, with: .linearGradient(Gradient(colors: [Color(white: 0.07), Color(white: 0.13), Color(white: 0.16)]),
                                                         startPoint: CGPoint(x: 0, y: sur.minY - 6), endPoint: CGPoint(x: 0, y: sur.maxY + 6)))
                context.stroke(well, with: .color(Color.black.opacity(0.6)), lineWidth: 1)
                context.stroke(Path(roundedRect: sur.insetBy(dx: -5.5, dy: -5.5).offsetBy(dx: 0, dy: 1.2), cornerRadius: 18, style: .continuous),
                               with: .color(Color.white.opacity(0.13)), lineWidth: 1)
                context.fill(Path(roundedRect: sur, cornerRadius: 12, style: .continuous), with: .color(Color(white: 0.03)))
                // a line over each soft key and over the navigation key
                for at in [plan.x(74), plan.x(200), plan.x(326)] {
                    context.fill(Path(CGRect(x: at - 14, y: plan.keysTop - 8, width: 28, height: 1.6)), with: .color(Color.white.opacity(0.28)))
                }
            } else {
                // the finder's plate, raised, and the dark glass in it
                let plate = Path(roundedRect: sur, cornerRadius: 26, style: .continuous)
                context.fill(plate.applying(CGAffineTransform(translationX: 0, y: 2.5)), with: .color(Color.black.opacity(0.28)))
                context.fill(plate, with: .linearGradient(Gradient(colors: [tone.color(0.7), tone.color(0.35), tone.color(0.1)]),
                                                          startPoint: CGPoint(x: 0, y: sur.minY), endPoint: CGPoint(x: 0, y: sur.maxY)))
                context.stroke(Path(roundedRect: sur.insetBy(dx: 0.7, dy: 0.7), cornerRadius: 25, style: .continuous), with: .color(Color.white.opacity(0.6)), lineWidth: 1)
                let glass = sur.insetBy(dx: 8, dy: 8)
                context.fill(Path(roundedRect: glass, cornerRadius: 20, style: .continuous), with: .color(Color(red: 0.09, green: 0.08, blue: 0.06)))
                context.stroke(Path(roundedRect: glass, cornerRadius: 20, style: .continuous), with: .color(Color.black.opacity(0.8)), lineWidth: 1.5)
            }
            // the strip: holes of a speaker between the camera and the overlay (the phone), the grip in the overlay's place
            let cameraFloor = (back.keepOut.map(\.maxY).max() ?? s.minY) + 16
            let zone = back.overlay ?? CGRect(x: s.minX, y: s.maxY, width: s.width, height: 0)
            if skin == .phone, zone.minY - cameraFloor > 40 {
                let columns = max(1, Int((s.width - 12) / 6)), rows = Int((zone.minY - 10 - cameraFloor) / 6)
                dots(CGPoint(x: s.midX - CGFloat(columns - 1) * 3, y: cameraFloor + 4), columns, rows, 6, 1.2)
            }
            if zone.height > 30 {
                var y = zone.minY + 14
                while y < zone.maxY - 10 {
                    let ridge = CGRect(x: s.minX + 4, y: y, width: max(0, s.width - 8), height: 2.4)
                    context.fill(Path(roundedRect: ridge, cornerRadius: 1.2), with: .color(Color.black.opacity(tone.isLight ? 0.17 : 0.5)))
                    context.fill(Path(roundedRect: ridge.offsetBy(dx: 0, dy: 2.4).insetBy(dx: 0, dy: 0.5), cornerRadius: 0.7), with: .color(Color.white.opacity(tone.isLight ? 0.55 : 0.1)))
                    y += 8
                }
            }
            // the edge all round
            context.stroke(Path(whole.insetBy(dx: 0.75, dy: 0.75)), with: .color(Color.white.opacity(0.3)), lineWidth: 1.5)
        }
        .accessibilityHidden(true)
    }
}

extension CameraDeckFace {
    /// A camera body's own back, part for part where its plan puts them.
    @ViewBuilder func shellFace(_ plan: ShellPlan) -> some View {
        if model.phase == .album {
            shellAlbumFace(plan)
        } else if plan.skin == .booth {
            AnyView(boothLive(plan.booth))
        } else {
            shellLive(plan)
        }
    }
    /// The album on the body's own back, type-erased (see shellBackdropFace).
    private func shellAlbumFace(_ plan: ShellPlan) -> AnyView {
        let c = plan.back.column
        switch plan.skin {
        case .film: return AnyView(Group {
                filmAlbum(table: CGRect(x: c.minX, y: c.minY + 2, width: c.width, height: c.height - 56),
                          keys: CGRect(x: c.minX + 4, y: c.maxY - 48, width: c.width - 8, height: 44), back: plan.shutter, stacked: false)
            })
        case .toy: return AnyView(Group {
                let strip = plan.back.strip, zone = plan.back.overlay ?? .zero, lens = plan.surround
                toyAlbum(lens: lens, band: 21, keys: CGRect(x: c.minX, y: lens.maxY + 14, width: c.width, height: max(0, c.maxY - lens.maxY - 14)), back: plan.shutter,
                         grip: CGRect(x: strip.minX + 6, y: zone.minY + 4, width: strip.width - 12, height: zone.height - 8),
                         name: CGRect(x: plan.x(40), y: plan.top - 2, width: 104 * plan.u, height: 30),
                         hump: CGRect(x: plan.x(232), y: plan.top - 4, width: 70 * plan.u, height: 32), stacked: false)
            })
        case .phone: return AnyView(clamAlbum(plan.clam))
        case .digital: return AnyView(digiAlbum(plan.digi))
        case .computer: return AnyView(retroAlbum(plan.retro))
        case .soda: return AnyView(sodaAlbum(plan.soda))
        case .booth: return AnyView(boothAlbum(plan.booth))
        case .vcd: return AnyView(vcdAlbum(plan.vcd))
        case .mp4: return AnyView(mp4Album(plan.mp4))
        case .bike: return AnyView(bikeAlbum(plan.bike))
        case .cake: return AnyView(cakeAlbum(plan.cake))
        case .register: return AnyView(registerAlbum(plan.register))
        default: return AnyView(Group {
                shellAlbum(.instant, tray: CGRect(x: c.minX, y: c.minY + 4, width: c.width, height: c.height - 66),
                           keys: CGRect(x: c.minX, y: c.maxY - 52, width: c.width, height: 46), stacked: false)
            })
        }
    }
    @ViewBuilder private func shellLive(_ plan: ShellPlan) -> some View {
        let l = layout
        shellBackdropFace(plan)
        if showsHardware { CoverHardwareMarks(cameras: l.keepOut, control: control, canvas: l.canvas) }
        viewfinder.deckPlaced(l.viewfinder)
        shellScreenFace(plan)
        if l.zoomBar.width > 0 {
            zoomBar.deckPlaced(l.zoomBar)
                .opacity(systemControlsUp ? 0 : 1)
                .allowsHitTesting(!systemControlsUp)
        }
        shellKeysFace(plan)
        if model.bodiesOpen {
            bodyMenu.deckPlaced(l.bodyMenu).transition(.opacity)
        }
        if model.countdown != nil, model.side == .inner, let camera = l.keepOut.first {
            LookHereBadge(camera: camera, canvas: l.canvas)
        }
    }
    /// 11-22: the body's backdrop, its screen and its keys (and its album) each come type-erased. With every body's
    /// own drawing in one view type, the runtime built that whole type whichever body was worn, and on the device a
    /// closed Duo with the camera open ran the main thread out of stack doing it.
    private func shellBackdropFace(_ plan: ShellPlan) -> AnyView {
        let l = layout
        switch plan.skin {
        case .toy: return AnyView(toyBackdrop(plan).frame(width: l.canvas.width, height: l.canvas.height))
        case .film: return AnyView(filmBackdrop(plan).frame(width: l.canvas.width, height: l.canvas.height))
        case .phone: return AnyView(clamBackdrop(plan.clam).frame(width: l.canvas.width, height: l.canvas.height))
        case .digital: return AnyView(digiBackdrop(plan.digi).frame(width: l.canvas.width, height: l.canvas.height))
        case .computer: return AnyView(retroBackdrop(plan.retro).frame(width: l.canvas.width, height: l.canvas.height))
        case .soda: return AnyView(sodaBackdrop(plan.soda).frame(width: l.canvas.width, height: l.canvas.height))
        case .vcd: return AnyView(vcdBackdrop(plan.vcd).frame(width: l.canvas.width, height: l.canvas.height))
        case .mp4: return AnyView(mp4Backdrop(plan.mp4).frame(width: l.canvas.width, height: l.canvas.height))
        case .bike: return AnyView(bikeBackdrop(plan.bike).frame(width: l.canvas.width, height: l.canvas.height))
        case .cake: return AnyView(cakeBackdrop(plan.cake).frame(width: l.canvas.width, height: l.canvas.height))
        case .register: return AnyView(registerBackdrop(plan.register).frame(width: l.canvas.width, height: l.canvas.height))
        default: return AnyView(Group {
            ShellBackdrop(plan: plan, hinge: hinge).equatable()
                .frame(width: l.canvas.width, height: l.canvas.height)
        })
        }
    }
    private func shellScreenFace(_ plan: ShellPlan) -> AnyView? {
        switch plan.skin {
        case .phone: return AnyView(clamScreen(plan.clam))
        case .digital: return AnyView(digiScreen(plan.digi))
        case .computer: return AnyView(retroScreen(plan.retro))
        case .soda: return AnyView(sodaScreen(plan.soda))
        case .vcd: return AnyView(vcdScreen(plan.vcd))
        case .mp4: return AnyView(mp4Screen(plan.mp4))
        case .bike: return AnyView(bikeScreen(plan.bike))
        case .cake: return AnyView(cakeScreen(plan.cake))
        case .register: return AnyView(registerScreen(plan.register))
        default: return nil
        }
    }
    private func shellKeysFace(_ plan: ShellPlan) -> AnyView {
        switch plan.skin {
        case .instant: return AnyView(instantFace(plan))
        case .toy: return AnyView(toyFace(plan))
        case .film: return AnyView(filmFace(plan))
        case .digital: return AnyView(digiFace(plan.digi))
        case .computer: return AnyView(retroFace(plan.retro))
        case .soda: return AnyView(sodaFace(plan.soda))
        case .vcd: return AnyView(vcdFace(plan.vcd))
        case .mp4: return AnyView(mp4Face(plan.mp4))
        case .bike: return AnyView(bikeFace(plan.bike))
        case .cake: return AnyView(cakeFace(plan.cake))
        case .register: return AnyView(registerFace(plan.register))
        default: return AnyView(clamFace(plan.clam))
        }
    }

    /// The name on the body.
    private func shellName(_ tone: ShellTone, size: CGFloat = 13) -> some View {
        Text(verbatim: "ZERO").font(.system(size: size, weight: .heavy, design: .rounded)).tracking(size * 0.28)
            .foregroundStyle(tone.ink.opacity(0.55))
            .lineLimit(1).fixedSize()
            .accessibilityHidden(true)
    }

    /// A key with its glyph on it, drawn as what it sets stands — in the
    /// key's own ink, or `ink` (the lamp's colour, on the instant camera
    /// held across, while what it sets is on) — and figures beside it where
    /// the key keeps them (how many pictures); 画幅's figures under its
    /// frame on a round key (`stacked`). It says its name (`label`, else
    /// `title`) and how it is set to VoiceOver, as it did while its words
    /// were printed on it.
    private func shellKey(_ title: String, glyph: ShellGlyph, size: CGFloat = 19, ink: Color? = nil, stacked: Bool = false, figures: String = "",
                          value: String? = nil, identifier: String, style: ShellKeyStyle, label: String? = nil, selected: Bool = false,
                          action: @escaping () -> Void) -> some View {
        let tint: Color = ink ?? style.tone.ink
        return Button(action: action) {
            HStack(spacing: 4) {
                ShellGlyphView(glyph: glyph, size: size, ink: tint, stacked: stacked)
                if !figures.isEmpty {
                    Text(verbatim: figures).font(.system(size: 12, weight: .heavy, design: .rounded)).monospacedDigit()
                        .foregroundStyle(tint)
                        .lineLimit(1).minimumScaleFactor(0.6)
                }
            }
            .padding(.horizontal, 3)
        }
        .buttonStyle(style)
        .accessibilityLabel(label ?? title)
        .accessibilityValue(value ?? "")
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
    /// A long key with its glyph in the middle (主菜单, the level), in the
    /// key's own ink or `ink`.
    private func shellBarKey(_ title: String, glyph: ShellGlyph, size: CGFloat = 20, ink: Color? = nil, value: String? = nil, identifier: String, style: ShellKeyStyle,
                             label: String? = nil, selected: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            ShellGlyphView(glyph: glyph, size: size, ink: ink ?? style.tone.ink)
                .padding(.horizontal, 6)
        }
        .buttonStyle(style)
        .accessibilityLabel(label ?? title)
        .accessibilityValue(value ?? "")
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }

    /// The lenses (and the bodies pinned among them) as a strip of this
    /// body's own; the one chosen kept in sight. Each shows its glyph (a
    /// pinned body, a small drawing of its kind of camera); only the chosen
    /// one its name too.
    private func shellLenses(ink: Color, chosen: Color, chosenInk: Color, radius: CGFloat) -> some View {
        let all = chips
        return ScrollViewReader { reader in
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 2) {
                    ForEach(all, id: \.self) { item in
                        shellChip(item, ink: ink, chosen: chosen, chosenInk: chosenInk, radius: radius).id(item)
                    }
                }
                .padding(.horizontal, 3)
            }
            .onAppear { reader.scrollTo(Chip.lens(model.lens), anchor: .center) }
            .onChange(of: model.lens) { _, lens in
                withAnimation(.easeOut(duration: 0.15)) { reader.scrollTo(Chip.lens(lens), anchor: .center) }
            }
        }
        .accessibilityIdentifier("camera-deck-lenses")
        .opacity(systemControlsUp ? 0 : 1)
        .allowsHitTesting(!systemControlsUp)
    }
    private func shellChip(_ item: Chip, ink: Color, chosen: Color, chosenInk: Color, radius: CGFloat) -> some View {
        let title: String, glyph: ShellGlyph, on: Bool, identifier: String
        switch item {
        case .lens(let lens):
            title = lens.title; glyph = .lens(lens); on = model.lens == lens; identifier = "camera-deck-lens-\(lens.rawValue)"
        case .body(let pinned):
            title = pinned.title; glyph = .body(pinned); on = model.body == pinned; identifier = "camera-deck-pinned-\(pinned.rawValue)"
        }
        let tint: Color = on ? chosenInk : ink
        return Button {
            ConsoleSounds.shared.play(.keyRubber, scale: 0.6)
            switch item {
            case .lens(let lens): model.choose(lens)
            case .body(let pinned): model.tapPinned(pinned)
            }
        } label: {
            VStack(spacing: 2) {
                ShellGlyphView(glyph: glyph, size: on ? 15 : 18, ink: tint)
                if on {
                    Text(title).font(.system(size: 10.5, weight: .bold, design: .rounded)).lineLimit(1).minimumScaleFactor(0.6)
                }
            }
            .foregroundStyle(tint)
            .frame(width: 62)
            .frame(maxHeight: .infinity)
            .background(RoundedRectangle(cornerRadius: radius, style: .continuous).fill(on ? chosen : Color.clear).padding(2))
            .contentShape(Rectangle())
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(title)
        .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }

    /// 拍照 / 录像 as a slide switch, a camera and a video camera over its
    /// ends (the one it is at filled, and brighter).
    private func shellModeSlide(_ tone: ShellTone, ink: Color) -> some View {
        let video = model.mode == .video
        let photoInk: Color = video ? Color.white.opacity(0.5) : ink.opacity(0.8)
        let videoInk: Color = video ? CameraShutterFace.red : Color.white.opacity(0.5)
        return ZStack {
            ShellSlide(on: video, tone: tone, set: { next in model.setMode(next ? .video : .photo) })
            HStack {
                ShellGlyphView(glyph: .photo(!video), size: 13, ink: photoInk)
                Spacer(minLength: 0)
                ShellGlyphView(glyph: .video(video), size: 13, ink: videoInk)
            }
            .padding(.horizontal, 14)
            .allowsHitTesting(false)
        }
        .accessibilityElement()
        .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
        .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
        .accessibilityAddTraits(.isButton)
        .accessibilityAction { model.setMode(video ? .photo : .video) }
        .accessibilityIdentifier("camera-deck-mode")
    }

    /// 拍照 as this body's own key: what it shows is the deck's (a red dot
    /// for a video, the square and the time while one runs).
    private func shellShutter(_ style: ShellKeyStyle, ring: Bool) -> some View {
        var style = style
        style.haptic = .faceButton
        return Button { model.shutter() } label: {
            GeometryReader { geo in
                let d = min(geo.size.width, geo.size.height)
                ZStack {
                    if model.mode == .video {
                        if model.recording {
                            VStack(spacing: 2) {
                                RoundedRectangle(cornerRadius: d * 0.05, style: .continuous).fill(CameraShutterFace.red).frame(width: d * 0.24, height: d * 0.24)
                                Text(CameraAppModel.clock(model.recordedSeconds)).font(.system(size: 11, weight: .heavy, design: .rounded)).monospacedDigit()
                            }
                        } else {
                            Circle().fill(CameraShutterFace.red).frame(width: d * 0.3, height: d * 0.3)
                        }
                    } else if !ring {
                        Image(systemName: model.timer == .off ? "camera.fill" : "timer").font(.system(size: d * 0.36, weight: .bold))
                            .opacity(model.canShoot ? 0.85 : 0.35)
                    }
                }
                .frame(width: geo.size.width, height: geo.size.height)
            }
        }
        .buttonStyle(style)
        .background {
            if ring {
                Circle().fill(LinearGradient(colors: [Color(white: 0.99), Color(white: 0.6), Color(white: 0.95), Color(white: 0.5), Color(white: 0.9)],
                                             startPoint: .topLeading, endPoint: .bottomTrailing))
                    .padding(-6)
                    .shadow(color: Color.black.opacity(0.5), radius: 3, y: 2)
            }
        }
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
    }

    // MARK: the instant camera

    @ViewBuilder private func instantFace(_ plan: ShellPlan) -> some View {
        let skin = CameraShellSkin.instant
        let tone = skin.tone
        let cream = ShellTone(r: 0.98, g: 0.965, b: 0.93)
        let accent = ShellTone(r: 0.94, g: 0.66, b: 0.63)
        let knob = ShellKeyStyle(tone: cream, radius: 200, travel: 1.5, sound: .keyRubber, soft: true)
        let capsule = ShellKeyStyle(tone: cream, radius: 22, travel: 1.5, sound: .keyRubber, soft: true)
        let c = plan.back.column, s = plan.back.strip, u = plan.u, top = plan.top, k = plan.keysTop
        let shooting = model.shooting
        // The slot over the finder, the print standing out of it.
        InstantSlot(model: model, thumbnails: thumbnails, tone: tone)
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(skin.albumTitle)
            .accessibilityValue(String(localized: "\(model.photos.count) 张"))
            .accessibilityAddTraits(.isButton)
            .accessibilityAction { model.openAlbum() }
            .accessibilityIdentifier("camera-deck-album")
            .deckPlaced(CGRect(x: c.minX, y: top, width: c.width, height: 62))
        // The dial with its lamps; beside it the film's window and six keys,
        // each with its glyph drawn as what it sets stands.
        let dial = min(138, 138 * u)
        ShellDial(value: shooting.exposure, caption: shooting.exposureTitle, tone: tone, step: { model.stepExposure($0) })
            .accessibilityElement()
            .accessibilityLabel(String(localized: "曝光"))
            .accessibilityValue(shooting.exposureTitle)
            .accessibilityAdjustableAction { direction in model.stepExposure(direction == .increment ? 1 : -1) }
            .accessibilityIdentifier("camera-deck-ev")
            .deckPlaced(CGRect(x: plan.x(76) - dial / 2, y: k - 2, width: dial, height: dial))
        instantDoor(tone).deckPlaced(CGRect(x: plan.x(152), y: k - 1, width: 228 * u, height: 44))
        let key = min(50, 64 * u), rowA = k + 50, rowB = rowA + 56
        shellKey(String(localized: "闪光"), glyph: .flash(shooting.flash), value: shooting.flash.title, identifier: "camera-deck-flash", style: knob) { model.cycleFlash() }
            .deckPlaced(CGRect(x: plan.x(190) - key / 2, y: rowA, width: key, height: key))
        shellKey(String(localized: "白平衡"), glyph: .whiteBalance(shooting.whiteBalance), value: shooting.whiteBalance.title, identifier: "camera-deck-wb", style: knob) { model.cycleWhiteBalance() }
            .deckPlaced(CGRect(x: plan.x(266) - key / 2, y: rowA, width: key, height: key))
        shellKey("ISO", glyph: .iso(shooting.iso), value: shooting.iso.title, identifier: "camera-deck-iso", style: knob) { model.cycleISO() }
            .deckPlaced(CGRect(x: plan.x(342) - key / 2, y: rowA, width: key, height: key))
        shellKey(String(localized: "日期"), glyph: .date(shooting.dateStamp), value: shooting.dateStamp ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-date", style: knob) { model.toggleDateStamp() }
            .deckPlaced(CGRect(x: plan.x(190) - key / 2, y: rowB, width: key, height: key))
        shellKey(skin.shapeTitle, glyph: .shape(model.shape), stacked: true, value: model.shape.title, identifier: "camera-deck-aspect", style: knob) {
            withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        }
        .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
        .deckPlaced(CGRect(x: plan.x(266) - key / 2, y: rowB, width: key, height: key))
        shellKey(String(localized: "定时"), glyph: .timer(model.timer), value: model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title,
                 identifier: "camera-deck-timer", style: knob) { model.cycleTimer() }
            .deckPlaced(CGRect(x: plan.x(342) - key / 2, y: rowB, width: key, height: key))
        // The switch under the dial.
        shellModeSlide(cream, ink: tone.ink)
            .deckKey(CGRect(x: plan.x(20), y: k + 129, width: 112 * u, height: 32))
        // The lenses in their groove.
        shellLenses(ink: tone.ink, chosen: accent.color(), chosenInk: .white, radius: 20)
            .background(Capsule().fill(LinearGradient(colors: [tone.color(-0.24), tone.color(-0.14)], startPoint: .top, endPoint: .bottom))
                .overlay(Capsule().strokeBorder(Color.black.opacity(0.22), lineWidth: 1)))
            .clipShape(Capsule())
            .deckPlaced(CGRect(x: plan.x(18), y: k + 166, width: 364 * u, height: 46))
        // 主菜单 (a house) and the level (filled, in the lamp's colour, while on).
        let levelInk: Color? = model.leveler ? Color(red: 0.86, green: 0.34, blue: 0.26) : nil
        shellBarKey(String(localized: "camera.home.pill"), glyph: .home, identifier: "camera-deck-home", style: capsule) { model.leave() }
            .deckPlaced(CGRect(x: plan.x(20), y: k + 218, width: 176 * u, height: 44))
        shellBarKey(String(localized: "水平仪"), glyph: .level(model.leveler), ink: levelInk, value: model.leveler ? String(localized: "开") : String(localized: "关"),
                    identifier: "camera-deck-leveler", style: capsule, label: String(localized: "水平仪"), selected: model.leveler) { model.toggleLeveler() }
            .deckPlaced(CGRect(x: plan.x(204), y: k + 218, width: 176 * u, height: 44))
        // The strip: the other camera, the name, the shutter in its ring.
        let under = (plan.back.keepOut.map(\.maxY).max() ?? top) + 12
        shellKey(model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), glyph: .flip, size: 20,
                 identifier: "camera-deck-switch", style: knob, label: String(localized: "切换内侧、外侧相机")) { model.switchSide() }
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckPlaced(CGRect(x: s.midX - 26, y: under, width: 52, height: 52))
        shellName(tone, size: 10.5).deckPlaced(CGRect(x: s.minX, y: under + 70, width: s.width, height: 16))
        shellShutter(ShellKeyStyle(tone: accent, radius: 200, travel: 2.5, sound: .keyMetal, rings: true), ring: true)
            .deckPlaced(plan.shutter.insetBy(dx: 7, dy: 7))
    }
    /// The film door's window: a strip of the pack's yellow, and two cameras
    /// traded (换机型) — the way to the other bodies.
    private func instantDoor(_ tone: ShellTone) -> some View {
        Button {
            ConsoleSounds.shared.play(.keySlide, scale: 0.7)
            if model.bodiesOpen { model.closeBodies() } else { model.openBodies() }
        } label: {
            HStack(spacing: 8) {
                RoundedRectangle(cornerRadius: 1.5).fill(Color(red: 0.95, green: 0.76, blue: 0.19)).frame(width: 8).padding(.vertical, 8)
                Spacer(minLength: 0)
                ShellGlyphView(glyph: .changeBody, size: 26, ink: Color(red: 0.96, green: 0.94, blue: 0.89))
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 8)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(RoundedRectangle(cornerRadius: 10, style: .continuous)
                .fill(LinearGradient(colors: [Color(red: 0.08, green: 0.075, blue: 0.07), Color(red: 0.13, green: 0.12, blue: 0.11)], startPoint: .top, endPoint: .bottom))
                .overlay(RoundedRectangle(cornerRadius: 10, style: .continuous).strokeBorder(Color.black.opacity(0.6), lineWidth: 1))
                .shadow(color: Color.white.opacity(0.5), radius: 0, y: 1))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
    }

    // MARK: the phone's keys (its back: the clamshell phone's, further down)

    /// Up and down: the zoom's next stop; left and right: the lenses.
    private func phoneNavigate(_ side: Int) {
        let stops = model.zoomStops
        let at = stops.lastIndex { $0 <= model.zoom + 0.05 } ?? 0
        switch side {
        case 0: if at + 1 < stops.count { model.setZoom(stops[at + 1], sound: false) }
        case 2: if at > 0 { model.setZoom(stops[at - 1], sound: false) }
        case 1: model.stepLens(1)
        default: model.stepLens(-1)
        }
    }
    /// What each of a phone's twelve keys does.
    private func phoneKey(_ index: Int) {
        switch index {
        case 0: model.cycleFlash()
        case 1: model.cycleWhiteBalance()
        case 2: model.cycleISO()
        case 3: model.stepExposure(-1)
        case 4: model.toggleDateStamp()
        case 5: model.stepExposure(1)
        case 6: model.stepBodyStrength(-1)
        case 7: withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        case 8: model.stepBodyStrength(1)
        case 9: model.cycleTimer()
        case 10: model.switchSide()
        default: model.toggleLeveler()
        }
    }
}

// MARK: - A body's own back, the cover held across

/// Where the parts of a body's own back are with the cover held across
/// (CoverBackAcross): the picture in its screen at the left, the keys in
/// their column — each key's place from the column's own corner.
struct ShellAcrossPlan: Equatable {
    var skin: CameraShellSkin
    var back: CoverBackAcross
    func key(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat) -> CGRect {
        CGRect(x: back.keys.minX + x, y: back.keys.minY + y, width: w, height: h)
    }
    /// The screen's glass (the phone, sunk in a well; the digital camera's
    /// LCD under its black glass) or the finder's plate (the instant
    /// camera), and the picture's place in it.
    var surround: CGRect {
        let s = back.screen
        switch skin {
        case .phone: return s.insetBy(dx: 6, dy: 6)
        case .digital: return CGRect(x: s.minX + 8, y: s.minY + 7, width: max(0, s.width - 16), height: max(0, s.height - 15))
        case .computer: return retroDesk?.bezel ?? s
        case .soda: return s.insetBy(dx: 4.5, dy: 4.5)
        case .booth: return CGRect(x: s.minX - 2, y: s.minY + 2, width: s.width, height: max(0, s.height - 3))
        case .vcd: return s
        case .mp4: return mp4Glass
        case .bike: return CGRect(x: s.minX + 9, y: s.minY + 1, width: max(0, s.width - 30), height: max(0, s.height - 27))
        case .cake: return s
        case .register: return CGRect(x: s.minX + 4, y: s.minY + 2, width: max(0, s.width - 14), height: max(0, s.height - 17))
        case .instant, .toy, .film: return s
        }
    }
    var box: CGRect {
        switch skin {
        case .phone: return surround.insetBy(dx: 8, dy: 8)
        case .digital: return back.screen.insetBy(dx: 14, dy: 14)
        case .computer: return CGRect(x: surround.minX + 17, y: surround.minY + 37.6, width: max(0, surround.width - 34), height: max(0, surround.height - 54.6))
        case .soda: return surround.insetBy(dx: 11.5, dy: 11.5)
        case .booth: return CGRect(x: back.screen.minX + 20, y: back.screen.minY + 20, width: max(0, back.screen.width - 44), height: max(0, back.screen.height - 40))
        case .vcd: return vcdBox
        case .mp4: return mp4Box
        case .bike: return CGRect(x: back.screen.minX + 14, y: back.screen.minY + 6, width: max(0, back.screen.width - 40), height: max(0, back.screen.height - 37))
        case .cake: return CGRect(x: back.screen.minX + 12, y: back.screen.minY + 28, width: max(0, back.screen.width - 36), height: max(0, back.screen.height - 34))
        case .register: return CGRect(x: surround.minX + 13, y: surround.minY + 10, width: max(0, surround.width - 26), height: max(0, surround.height - 20))
        case .instant, .toy, .film: return surround.insetBy(dx: 15, dy: 15)
        }
    }
    func picture(aspect: Double) -> CGRect {
        let b = box
        guard aspect > 0, b.height > 0 else { return b }
        let w = min(b.width, b.height * CGFloat(aspect)), h = w / CGFloat(aspect)
        return CGRect(x: b.midX - w / 2, y: b.midY - h / 2, width: w, height: h)
    }
    /// 拍照: the key in its ring beside the dial (the instant camera).
    /// The toy camera's is in the band's clear end, on its top; the phone's
    /// side key lies along the band there (the ring's middle takes the
    /// picture too).
    var shutter: CGRect {
        switch skin {
        case .phone:
            let end = back.spare.width >= 116 ? back.spare : back.run
            return CGRect(x: end.maxX - 110, y: end.midY - 24, width: 104, height: 50)
        case .instant: return key(126, 52, 68, 68)
        case .toy, .film:
            let end = back.spare.width >= 70 ? back.spare : back.run
            return CGRect(x: end.maxX - 62, y: end.midY - 26, width: 52, height: 52)
        case .digital:
            let end = back.spare.width >= 70 ? back.spare : back.run
            return CGRect(x: end.maxX - 88, y: end.midY - 29, width: 60, height: 60)
        case .computer: return retroShutter
        case .soda: return sodaShutter
        case .booth:
            let end = back.spare.width >= 70 ? back.spare : back.run
            return CGRect(x: end.maxX - 89, y: end.midY - 30, width: 60, height: 60)
        case .vcd: return vcdShutter
        case .mp4: return mp4Shutter
        case .bike: return bikeShutter
        case .cake: return cakeShutter
        case .register: return registerShutter
        }
    }
    /// The deck's own layout with this back's picture, zoom stops and menu
    /// in it; nil when the picture has no room.
    func layout(from plain: CoverDeckLayout, aspect: Double, zoomStops: Int) -> CoverDeckLayout? {
        let p = picture(aspect: aspect)
        guard box.width >= 280, box.height >= 200 else { return nil }
        var l = plain
        l.viewfinder = p.insetBy(dx: -6, dy: -6)
        let run = CGFloat(max(1, zoomStops)) * CGFloat(CoverDeckLayout.target)
        l.zoomBar = CGRect(x: p.midX - run / 2, y: p.maxY - (skin == .phone ? 25 : 4) - CGFloat(CoverDeckLayout.target), width: run, height: CGFloat(CoverDeckLayout.target))
        l.lensRow = .zero
        l.toolRow = .zero
        l.shootingRow = .zero
        l.hint = .zero
        l.album = .zero
        l.flip = .zero
        l.shutter = shutter
        l.pictureBelow = false
        l.keys = back.keys
        // The bodies' cards: along the lower edge, the picture's upper part
        // still in sight over them.
        let menu = max(CGFloat(plain.bodyMenu.height), 156)
        l.bodyMenu = CGRect(x: back.screen.minX, y: back.keys.maxY - menu, width: back.keys.maxX - back.screen.minX, height: menu)
        return l
    }
}

/// The back's body held across, drawn: the plastic, the hinge's shade
/// along its long edge, the band (the grip where the Camera Control's
/// overlay comes in; the phone's earpiece and sensors), the screen's well
/// or the finder's plate. Drawn once.
private struct ShellAcrossBackdrop: View, Equatable {
    var plan: ShellAcrossPlan
    var hinge: CGRect
    var body: some View {
        Canvas { context, size in
            let whole = CGRect(origin: .zero, size: size)
            let g = context
            let skin = plan.skin, tone = skin.tone, back = plan.back
            context.fill(Path(whole), with: .linearGradient(Gradient(colors: [tone.color(0.22), tone.color(0), tone.color(-0.28)]),
                                                            startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
            var seed: UInt32 = 0x1234_5678
            func next() -> CGFloat {
                seed = seed &* 1_664_525 &+ 1_013_904_223
                return CGFloat((seed >> 8) & 0xFFFF) / 65535
            }
            if skin == .phone {
                // brushed along its length
                for _ in 0..<Int(size.height * 1.5) {
                    let y = next() * size.height, a = Double(next()) * 0.06
                    context.fill(Path(CGRect(x: 0, y: y, width: size.width, height: 0.5)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
                }
            } else {
                for _ in 0..<Int(size.width * size.height / 110) {
                    let at = CGPoint(x: next() * size.width, y: next() * size.height), a = Double(next()) * 0.05
                    context.fill(Path(CGRect(x: at.x, y: at.y, width: 1, height: 1)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
                }
            }
            // the hinge's edge falls into shade
            if hinge.width > hinge.height, hinge.height > 0 {
                let upper = hinge.midY < size.height / 2
                let deep = CGRect(x: hinge.minX, y: upper ? hinge.minY : hinge.minY - 2, width: hinge.width, height: hinge.height + 2)
                context.fill(Path(deep), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.45), Color.black.opacity(0)]),
                                                               startPoint: CGPoint(x: 0, y: upper ? deep.minY : deep.maxY),
                                                               endPoint: CGPoint(x: 0, y: upper ? deep.maxY : deep.minY)))
            }
            func dots(_ origin: CGPoint, _ columns: Int, _ rows: Int, _ gap: CGFloat, _ r: CGFloat) {
                guard columns > 0, rows > 0 else { return }
                for i in 0..<columns {
                    for j in 0..<rows {
                        let hole = CGRect(x: origin.x + CGFloat(i) * gap - r, y: origin.y + CGFloat(j) * gap - r, width: 2 * r, height: 2 * r)
                        g.fill(Path(ellipseIn: hole), with: .color(Color.black.opacity(0.6)))
                        g.stroke(Path(ellipseIn: hole.offsetBy(dx: 0, dy: 0.6)), with: .color(Color.white.opacity(0.16)), lineWidth: 0.5)
                    }
                }
            }
            // the band: the grip in the overlay's place
            let band = back.band
            if let zone = back.overlay, zone.width > 30 {
                var x = zone.minX + 10
                while x < zone.maxX - 8 {
                    let ridge = CGRect(x: x, y: band.minY + 13, width: 2.4, height: max(0, band.height - 26))
                    context.fill(Path(roundedRect: ridge, cornerRadius: 1.2), with: .color(Color.black.opacity(tone.isLight ? 0.17 : 0.5)))
                    context.fill(Path(roundedRect: ridge.offsetBy(dx: 2.4, dy: 0).insetBy(dx: 0.5, dy: 0), cornerRadius: 0.7), with: .color(Color.white.opacity(tone.isLight ? 0.55 : 0.1)))
                    x += 8
                }
            }
            let sur = plan.surround
            if skin == .phone {
                // the earpiece and its mesh after the name; two sensors and a speaker's holes in the other run
                let run = back.run, spare = back.spare
                if run.width >= 150 {
                    let ear = CGRect(x: run.minX + 92, y: run.midY - 3, width: min(96, run.width - 100), height: 6)
                    context.fill(Path(roundedRect: ear, cornerRadius: 3), with: .color(Color(white: 0.02)))
                    context.stroke(Path(roundedRect: ear.offsetBy(dx: 0, dy: 0.8), cornerRadius: 3), with: .color(Color.white.opacity(0.25)), lineWidth: 0.8)
                    dots(CGPoint(x: ear.minX + 6, y: ear.midY), Int((ear.width - 12) / 4.9) + 1, 1, 4.9, 0.9)
                }
                if spare.width >= 60 {
                    for dx in [spare.minX + 14, spare.minX + 26] {
                        context.fill(Path(ellipseIn: CGRect(x: dx - 2.4, y: spare.midY - 2.4, width: 4.8, height: 4.8)), with: .color(Color(white: 0.04)))
                    }
                    let columns = Int((spare.width - 52) / 6)
                    dots(CGPoint(x: spare.maxX - 6 - CGFloat(max(0, columns - 1)) * 6, y: spare.midY - 15), columns, 6, 6, 1.2)
                }
                // the screen sunk in the body, its glass
                let well = Path(roundedRect: sur.insetBy(dx: -6, dy: -6), cornerRadius: 18, style: .continuous)
                context.fill(well, with: .linearGradient(Gradient(colors: [Color(white: 0.07), Color(white: 0.13), Color(white: 0.16)]),
                                                         startPoint: CGPoint(x: 0, y: sur.minY - 6), endPoint: CGPoint(x: 0, y: sur.maxY + 6)))
                context.stroke(well, with: .color(Color.black.opacity(0.6)), lineWidth: 1)
                context.stroke(Path(roundedRect: sur.insetBy(dx: -5.5, dy: -5.5).offsetBy(dx: 0, dy: 1.2), cornerRadius: 18, style: .continuous),
                               with: .color(Color.white.opacity(0.13)), lineWidth: 1)
                context.fill(Path(roundedRect: sur, cornerRadius: 12, style: .continuous), with: .color(Color(white: 0.03)))
            } else {
                // the finder's plate, raised, and the dark glass in it
                let plate = Path(roundedRect: sur, cornerRadius: 26, style: .continuous)
                context.fill(plate.applying(CGAffineTransform(translationX: 0, y: 2.5)), with: .color(Color.black.opacity(0.28)))
                context.fill(plate, with: .linearGradient(Gradient(colors: [tone.color(0.7), tone.color(0.35), tone.color(0.1)]),
                                                          startPoint: CGPoint(x: 0, y: sur.minY), endPoint: CGPoint(x: 0, y: sur.maxY)))
                context.stroke(Path(roundedRect: sur.insetBy(dx: 0.7, dy: 0.7), cornerRadius: 25, style: .continuous), with: .color(Color.white.opacity(0.6)), lineWidth: 1)
                let glass = sur.insetBy(dx: 8, dy: 8)
                context.fill(Path(roundedRect: glass, cornerRadius: 20, style: .continuous), with: .color(Color(red: 0.09, green: 0.08, blue: 0.06)))
                context.stroke(Path(roundedRect: glass, cornerRadius: 20, style: .continuous), with: .color(Color.black.opacity(0.8)), lineWidth: 1.5)
            }
            context.stroke(Path(whole.insetBy(dx: 0.75, dy: 0.75)), with: .color(Color.white.opacity(0.3)), lineWidth: 1.5)
        }
        .accessibilityHidden(true)
    }
}

extension CameraDeckFace {
    /// A camera body's own back with the cover held across.
    @ViewBuilder func shellAcrossFace(_ plan: ShellAcrossPlan) -> some View {
        if model.phase == .album {
            acrossAlbumFace(plan)
        } else if plan.skin == .booth {
            AnyView(boothLive(plan.booth))
        } else {
            shellAcrossLive(plan)
        }
    }
    /// The album on the body's own back, type-erased (see acrossBackdropFace).
    private func acrossAlbumFace(_ plan: ShellAcrossPlan) -> AnyView {
        switch plan.skin {
        case .film: return AnyView(filmAlbum(table: plan.back.screen, keys: plan.back.keys.insetBy(dx: 4, dy: 6), back: .zero, stacked: true))
        case .toy: return AnyView(Group {
                let band = plan.back.band, zone = plan.back.overlay ?? .zero, run = plan.back.run
                toyAlbum(lens: plan.back.screen.insetBy(dx: -4, dy: -4), band: 19, keys: plan.back.keys, back: plan.shutter,
                         grip: CGRect(x: zone.minX + 6, y: band.minY + 8, width: zone.width - 12, height: band.height - 16),
                         name: run.width >= 104 ? CGRect(x: run.minX + 4, y: run.midY - 15, width: 100, height: 30) : .zero,
                         hump: run.width >= 180 ? CGRect(x: run.minX + 112, y: run.midY - 16, width: 66, height: 32) : .zero, stacked: true)
            })
        case .phone: return AnyView(clamAlbum(plan.clam))
        case .digital: return AnyView(digiAlbum(plan.digi))
        case .computer: return AnyView(retroAlbum(plan.retro))
        case .soda: return AnyView(sodaAlbum(plan.soda))
        case .booth: return AnyView(boothAlbum(plan.booth))
        case .vcd: return AnyView(vcdAlbum(plan.vcd))
        case .mp4: return AnyView(mp4Album(plan.mp4))
        case .bike: return AnyView(bikeAlbum(plan.bike))
        case .cake: return AnyView(cakeAlbum(plan.cake))
        case .register: return AnyView(registerAlbum(plan.register))
        default: return AnyView(shellAlbum(plan.skin, tray: plan.back.screen, keys: plan.back.keys.insetBy(dx: 4, dy: 6), stacked: true))
        }
    }
    @ViewBuilder private func shellAcrossLive(_ plan: ShellAcrossPlan) -> some View {
        let l = layout
        acrossBackdropFace(plan)
        if showsHardware { CoverHardwareMarks(cameras: l.keepOut, control: control, canvas: l.canvas) }
        viewfinder.deckPlaced(l.viewfinder)
        acrossScreenFace(plan)
        if l.zoomBar.width > 0 {
            zoomBar.deckPlaced(l.zoomBar)
                .opacity(systemControlsUp ? 0 : 1)
                .allowsHitTesting(!systemControlsUp)
        }
        acrossKeysFace(plan)
        if model.bodiesOpen {
            bodyMenu.deckPlaced(l.bodyMenu).transition(.opacity)
        }
        if model.countdown != nil, model.side == .inner, let camera = l.keepOut.first {
            LookHereBadge(camera: camera, canvas: l.canvas)
        }
    }
    /// 11-22: the body's backdrop, its screen and its keys (and its album) each come type-erased. With every body's
    /// own drawing in one view type, the runtime built that whole type whichever body was worn, and on the device a
    /// closed Duo with the camera open ran the main thread out of stack doing it.
    private func acrossBackdropFace(_ plan: ShellAcrossPlan) -> AnyView {
        let l = layout
        switch plan.skin {
        case .toy: return AnyView(toyBackdrop(plan).frame(width: l.canvas.width, height: l.canvas.height))
        case .film: return AnyView(filmBackdrop(plan).frame(width: l.canvas.width, height: l.canvas.height))
        case .phone: return AnyView(clamBackdrop(plan.clam).frame(width: l.canvas.width, height: l.canvas.height))
        case .digital: return AnyView(digiBackdrop(plan.digi).frame(width: l.canvas.width, height: l.canvas.height))
        case .computer: return AnyView(retroBackdrop(plan.retro).frame(width: l.canvas.width, height: l.canvas.height))
        case .soda: return AnyView(sodaBackdrop(plan.soda).frame(width: l.canvas.width, height: l.canvas.height))
        case .vcd: return AnyView(vcdBackdrop(plan.vcd).frame(width: l.canvas.width, height: l.canvas.height))
        case .mp4: return AnyView(mp4Backdrop(plan.mp4).frame(width: l.canvas.width, height: l.canvas.height))
        case .bike: return AnyView(bikeBackdrop(plan.bike).frame(width: l.canvas.width, height: l.canvas.height))
        case .cake: return AnyView(cakeBackdrop(plan.cake).frame(width: l.canvas.width, height: l.canvas.height))
        case .register: return AnyView(registerBackdrop(plan.register).frame(width: l.canvas.width, height: l.canvas.height))
        default: return AnyView(Group {
            ShellAcrossBackdrop(plan: plan, hinge: hinge).equatable()
                .frame(width: l.canvas.width, height: l.canvas.height)
        })
        }
    }
    private func acrossScreenFace(_ plan: ShellAcrossPlan) -> AnyView? {
        switch plan.skin {
        case .phone: return AnyView(clamScreen(plan.clam))
        case .digital: return AnyView(digiScreen(plan.digi))
        case .computer: return AnyView(retroScreen(plan.retro))
        case .soda: return AnyView(sodaScreen(plan.soda))
        case .vcd: return AnyView(vcdScreen(plan.vcd))
        case .mp4: return AnyView(mp4Screen(plan.mp4))
        case .bike: return AnyView(bikeScreen(plan.bike))
        case .cake: return AnyView(cakeScreen(plan.cake))
        case .register: return AnyView(registerScreen(plan.register))
        default: return nil
        }
    }
    private func acrossKeysFace(_ plan: ShellAcrossPlan) -> AnyView {
        switch plan.skin {
        case .instant: return AnyView(instantAcross(plan))
        case .toy: return AnyView(toyAcross(plan))
        case .film: return AnyView(filmAcross(plan))
        case .digital: return AnyView(digiFace(plan.digi))
        case .computer: return AnyView(retroFace(plan.retro))
        case .soda: return AnyView(sodaFace(plan.soda))
        case .vcd: return AnyView(vcdFace(plan.vcd))
        case .mp4: return AnyView(mp4Face(plan.mp4))
        case .bike: return AnyView(bikeFace(plan.bike))
        case .cake: return AnyView(cakeFace(plan.cake))
        case .register: return AnyView(registerFace(plan.register))
        default: return AnyView(clamFace(plan.clam))
        }
    }

    /// A small key with only its symbol on it.
    private func shellIconKey(_ symbol: String, tint: Color? = nil, identifier: String, style: ShellKeyStyle,
                              label: String, value: String = "", selected: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Image(systemName: symbol).font(.system(size: 15, weight: .bold)).foregroundStyle(tint ?? style.tone.ink)
        }
        .buttonStyle(style)
        .accessibilityLabel(label)
        .accessibilityValue(value)
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }

    /// The instant camera on its side: the slot in the band (the print
    /// comes out of it there); at the right the film's window, the dial
    /// with the shutter beside it over the switch, eight keys, the lenses,
    /// 主菜单 — each key with its glyph.
    @ViewBuilder private func instantAcross(_ plan: ShellAcrossPlan) -> some View {
        let skin = CameraShellSkin.instant
        let tone = skin.tone
        let cream = ShellTone(r: 0.98, g: 0.965, b: 0.93)
        let accent = ShellTone(r: 0.94, g: 0.66, b: 0.63)
        let knob = ShellKeyStyle(tone: cream, radius: 200, travel: 1.5, sound: .keyRubber, soft: true)
        let capsule = ShellKeyStyle(tone: cream, radius: 22, travel: 1.5, sound: .keyRubber, soft: true)
        let shooting = model.shooting
        let run = plan.back.run, spare = plan.back.spare
        if run.width >= 110 {
            InstantSlot(model: model, thumbnails: thumbnails, tone: tone, counted: false)
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(skin.albumTitle)
                .accessibilityValue(String(localized: "\(model.photos.count) 张"))
                .accessibilityAddTraits(.isButton)
                .accessibilityAction { model.openAlbum() }
                .accessibilityIdentifier("camera-deck-album")
                .deckPlaced(CGRect(x: run.minX, y: run.minY, width: min(run.width, 190), height: run.height))
        }
        if spare.width >= 90 {
            // (Printed by the slot: the album's glyph and how many there are, and ZERO.)
            HStack(spacing: 10) {
                HStack(spacing: 4) {
                    ShellGlyphView(glyph: .album, size: 15, ink: tone.ink)
                    Text(verbatim: "\(model.photos.count)").font(.system(size: 12, weight: .heavy, design: .rounded)).monospacedDigit()
                }
                .foregroundStyle(tone.ink)
                shellName(tone, size: 10.5)
            }
            .accessibilityHidden(true)
            .deckPlaced(spare)
        }
        instantDoor(tone).deckPlaced(plan.key(6, -3, 194, 44))
        ShellDial(value: shooting.exposure, caption: shooting.exposureTitle, tone: tone, step: { model.stepExposure($0) })
            .accessibilityElement()
            .accessibilityLabel(String(localized: "曝光"))
            .accessibilityValue(shooting.exposureTitle)
            .accessibilityAdjustableAction { direction in model.stepExposure(direction == .increment ? 1 : -1) }
            .accessibilityIdentifier("camera-deck-ev")
            .deckPlaced(plan.key(3, 45, 110, 110))
        shellShutter(ShellKeyStyle(tone: accent, radius: 200, travel: 2.5, sound: .keyMetal, rings: true), ring: true)
            .deckPlaced(plan.shutter.insetBy(dx: 7, dy: 7))
        shellModeSlide(cream, ink: tone.ink).deckKey(plan.key(118, 138, 82, 30))
        // The eight keys, two rows of four: each glyph drawn as what it sets
        // stands, in the lamp's colour while that is on.
        let d: CGFloat = 44, step: CGFloat = 48.7, rowA: CGFloat = 176, rowB: CGFloat = 224
        let lamp = Color(red: 0.86, green: 0.34, blue: 0.26)
        let flashInk: Color? = shooting.flash != .off ? lamp : nil
        let balanceInk: Color? = shooting.whiteBalance != .auto ? lamp : nil
        let dateInk: Color? = shooting.dateStamp ? lamp : nil
        let timerInk: Color? = model.timer != .off ? lamp : nil
        let levelInk: Color? = model.leveler ? lamp : nil
        shellKey(String(localized: "闪光"), glyph: .flash(shooting.flash), size: 17, ink: flashInk, value: shooting.flash.title, identifier: "camera-deck-flash", style: knob) { model.cycleFlash() }
            .deckPlaced(plan.key(5, rowA, d, d))
        shellKey(String(localized: "白平衡"), glyph: .whiteBalance(shooting.whiteBalance), size: 17, ink: balanceInk, value: shooting.whiteBalance.title, identifier: "camera-deck-wb",
                 style: knob) { model.cycleWhiteBalance() }
            .deckPlaced(plan.key(5 + step, rowA, d, d))
        shellKey("ISO", glyph: .iso(shooting.iso), size: 17, value: shooting.iso.title, identifier: "camera-deck-iso", style: knob) { model.cycleISO() }
            .deckPlaced(plan.key(5 + step * 2, rowA, d, d))
        shellKey(String(localized: "日期"), glyph: .date(shooting.dateStamp), size: 17, ink: dateInk, value: shooting.dateStamp ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-date", style: knob) { model.toggleDateStamp() }
            .deckPlaced(plan.key(5 + step * 3, rowA, d, d))
        shellKey(skin.shapeTitle, glyph: .shape(model.shape), size: 17, stacked: true, value: model.shape.title, identifier: "camera-deck-aspect", style: knob) {
            withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        }
        .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
        .deckPlaced(plan.key(5, rowB, d, d))
        shellKey(String(localized: "定时"), glyph: .timer(model.timer), size: 17, ink: timerInk, value: model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title,
                 identifier: "camera-deck-timer", style: knob) { model.cycleTimer() }
            .deckPlaced(plan.key(5 + step, rowB, d, d))
        shellKey(model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), glyph: .flip, size: 17,
                 identifier: "camera-deck-switch", style: knob, label: String(localized: "切换内侧、外侧相机")) { model.switchSide() }
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckPlaced(plan.key(5 + step * 2, rowB, d, d))
        shellKey(String(localized: "水平仪"), glyph: .level(model.leveler), size: 17, ink: levelInk, value: model.leveler ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-leveler", style: knob, selected: model.leveler) { model.toggleLeveler() }
            .deckPlaced(plan.key(5 + step * 3, rowB, d, d))
        shellLenses(ink: tone.ink, chosen: accent.color(), chosenInk: .white, radius: 18)
            .background(Capsule().fill(LinearGradient(colors: [tone.color(-0.24), tone.color(-0.14)], startPoint: .top, endPoint: .bottom))
                .overlay(Capsule().strokeBorder(Color.black.opacity(0.22), lineWidth: 1)))
            .clipShape(Capsule())
            .deckPlaced(plan.key(2, 272, 198, 44))
        shellBarKey(String(localized: "camera.home.pill"), glyph: .home, identifier: "camera-deck-home", style: capsule) { model.leave() }
            .deckKey(plan.key(6, 321, 194, 34))
    }
}

// MARK: - The instant camera's album: the pile of prints

/// The instant camera's 相片: its prints in a pile in the tray, the newest
/// on top. The top one is pushed off to the left to see the one under it,
/// and comes back from there with a push to the right; a video's plays where
/// it lies. Under the tray (beside it, the cover held across) the keys.
private struct InstantPile: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var tone: ShellTone
    var tray: CGRect
    var keys: CGRect
    /// The keys one over the other (a column beside the tray).
    var stacked: Bool
    @State private var push: CGSize = .zero

    /// How a print lies in the pile: its own lean and place (from its
    /// name). The top one (`depth` 0) lies nearly straight in the middle;
    /// the ones under it lie out over the room the tray has, by turns
    /// above and below, farther and more askew the deeper they are.
    private func lie(_ url: URL, _ size: CGSize, depth: Int) -> (lean: Double, dx: CGFloat, dy: CGFloat) {
        var h: UInt32 = 2_166_136_261
        for scalar in url.lastPathComponent.unicodeScalars { h = (h ^ scalar.value) &* 16_777_619 }
        let a = Double(h % 1000) / 1000 - 0.5, b = Double((h / 1000) % 1000) / 1000 - 0.5, c = Double((h / 1_000_000) % 1000) / 1000 - 0.5
        guard depth > 0 else { return (a * 3, CGFloat(b) * 6, CGFloat(c) * 6) }
        let across = max(8, (tray.width - size.width) * 0.4), down = max(8, (tray.height - size.height) * 0.42)
        let far = min(1, 0.3 + 0.18 * Double(depth)), side: CGFloat = depth % 2 == 1 ? -1 : 1
        return (a * (10 + 4 * Double(depth)), CGFloat(b) * 2 * across, side * CGFloat(far * (0.8 + 0.4 * (c + 0.5))) * down)
    }
    private var still: Transaction {
        var transaction = Transaction()
        transaction.disablesAnimations = true
        return transaction
    }
    /// A print's size for a picture of this shape: the window as wide as the
    /// tray lets it be, never higher than the tray; the wide margin below.
    private func sheet(_ aspect: CGFloat) -> CGSize {
        let side: CGFloat = 12, foot: CGFloat = 44
        var w = min(308, tray.width - 24 - 2 * side), h = w / max(0.3, aspect)
        let most = tray.height - 44 - side - foot
        if h > most { h = most; w = h * aspect }
        return CGSize(width: w + 2 * side, height: h + side + foot)
    }
    private func step(_ delta: Int) {
        let photos = model.photos, at = model.albumIndex
        guard photos.indices.contains(at + delta), model.doodle == nil else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) { push = .zero }
            return
        }
        ConsoleSounds.shared.play(.cardFlip, scale: 0.8)
        let away = CGSize(width: -(tray.width + 120), height: 0)
        if delta > 0 {
            withAnimation(.easeIn(duration: 0.18)) { push = away }
            Task { @MainActor in
                try? await Task.sleep(nanoseconds: 190_000_000)
                model.moveInAlbum(1, quiet: true)
                withTransaction(still) { push = .zero }
            }
        } else {
            model.moveInAlbum(-1, quiet: true)
            withTransaction(still) { push = away }
            withAnimation(.spring(response: 0.36, dampingFraction: 0.82)) { push = .zero }
        }
    }

    var body: some View {
        let photos = model.photos, at = model.albumIndex
        let cream = ShellTone(r: 0.98, g: 0.965, b: 0.93)
        let capsule = ShellKeyStyle(tone: cream, radius: 22, travel: 1.5, sound: .keyRubber, soft: true)
        let middle = CGPoint(x: tray.midX, y: tray.midY)
        ZStack(alignment: .topLeading) {
            // The body's plastic, and the tray sunk in it.
            LinearGradient(colors: [tone.color(0.22), tone.color(0), tone.color(-0.28)], startPoint: .topLeading, endPoint: .bottomTrailing)
            RoundedRectangle(cornerRadius: 22, style: .continuous)
                .fill(LinearGradient(colors: [tone.color(-0.3), tone.color(-0.2), tone.color(-0.14)], startPoint: .top, endPoint: .bottom))
                .overlay(RoundedRectangle(cornerRadius: 22, style: .continuous).strokeBorder(Color.black.opacity(0.25), lineWidth: 1))
                .shadow(color: Color.white.opacity(0.5), radius: 0, y: 1)
                .frame(width: tray.width, height: tray.height)
                .position(middle)
                .accessibilityHidden(true)
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 14, weight: .heavy, design: .rounded)).foregroundStyle(tone.ink.opacity(0.7))
                    .frame(width: tray.width, height: tray.height)
                    .position(middle)
            } else if photos.indices.contains(at) {
                // The prints under the top one, the deepest first.
                ForEach([6, 5, 4, 3, 2, 1], id: \.self) { depth in
                    if photos.indices.contains(at + depth) {
                        let under = photos[at + depth]
                        let size = sheet(4.0 / 3), how = lie(under.url, size, depth: depth)
                        InstantSheet(image: thumbnails.images[under.url], caption: "", video: under.isVideo, playing: false, url: nil, ended: {})
                            .frame(width: size.width, height: size.height)
                            .rotationEffect(.degrees(how.lean))
                            .position(x: middle.x + how.dx, y: middle.y + how.dy)
                            .onAppear { thumbnails.request(under.url) }
                            .accessibilityHidden(true)
                    }
                }
                let photo = photos[at]
                let sharp: CGImage? = (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
                let aspect: CGFloat = sharp.map { CGFloat($0.width) / CGFloat(max(1, $0.height)) } ?? 4.0 / 3
                let size = sheet(aspect), how = lie(photo.url, size, depth: 0)
                InstantSheet(image: sharp,
                             caption: photo.date.formatted(.dateTime.locale(UILanguage.locale).year().month().day().hour().minute(.twoDigits)),
                             video: photo.isVideo, playing: model.playing == photo.url, url: photo.url, ended: { model.playedToEnd() })
                    .frame(width: size.width, height: size.height)
                    .rotationEffect(.degrees(how.lean + Double(push.width) / 20))
                    .position(x: middle.x + how.dx + push.width, y: middle.y + how.dy + push.height * 0.25)
                    .onAppear { thumbnails.request(photo.url) }
                    .onChange(of: photo.url) { _, url in thumbnails.request(url) }
                    .gesture(DragGesture(minimumDistance: 8)
                        .onChanged { push = $0.translation }
                        .onEnded { value in
                            let dx = value.translation.width, flick = value.predictedEndTranslation.width
                            if abs(dx) > 70 || abs(flick) > 220 {
                                step(dx < 0 ? 1 : -1)
                            } else {
                                withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) { push = .zero }
                            }
                        })
                    .onTapGesture { if photo.isVideo { model.togglePlay() } }
                    .accessibilityElement(children: .ignore)
                    .accessibilityLabel(photo.isVideo ? String(localized: "录像") : String(localized: "相片"))
                    .accessibilityValue(photo.name)
                    .accessibilityAdjustableAction { direction in step(direction == .increment ? 1 : -1) }
                    .accessibilityIdentifier("camera-deck-album-print")
            }
            // The keys: ‹ and ›, 回去拍照 (its words kept), a house (主菜单),
            // ▶ or the square for a video.
            let count = Text(verbatim: photos.isEmpty ? "0" : "\(at + 1) / \(photos.count)")
                .font(.system(size: 13, weight: .heavy, design: .rounded)).monospacedDigit().foregroundStyle(tone.ink)
                .lineLimit(1).minimumScaleFactor(0.6)
                .accessibilityIdentifier("camera-deck-album-position")
            let earlier = key(.previous, nil, String(localized: "上一张"), "camera-deck-album-previous", capsule) { step(-1) }
            let later = key(.next, nil, String(localized: "下一张"), "camera-deck-album-next", capsule) { step(1) }
            let back = key(.returnToShooting, String(localized: "回去拍照"), String(localized: "回去拍照"), "camera-deck-album-close", capsule) { model.closeAlbum() }
            let home = key(.home, nil, String(localized: "camera.home.pill"), "camera-deck-home", capsule) { model.leave() }
            let playing = model.playing != nil
            let playSign: ShellGlyph = playing ? .stop : .play
            let playWord = playing ? String(localized: "停止") : String(localized: "播放")
            Group {
                if stacked {
                    VStack(spacing: 8) {
                        // (The album's glyph where its name was, in the room the name took.)
                        Text("相片").font(.system(size: 15, weight: .heavy, design: .rounded)).hidden()
                            .overlay(ShellGlyphView(glyph: .album, size: 18, ink: tone.ink))
                            .accessibilityHidden(true)
                        count
                        HStack(spacing: 8) { earlier; later }.frame(height: 46)
                        if photos.indices.contains(at), photos[at].isVideo {
                            key(playSign, nil, playWord, "camera-deck-album-play", capsule) { model.togglePlay() }
                                .frame(height: 44)
                        }
                        Spacer(minLength: 0)
                        back.frame(height: 46)
                        home.frame(height: 44)
                    }
                } else {
                    HStack(spacing: 6) {
                        back.frame(width: 118)
                        earlier.frame(width: 50)
                        count.frame(maxWidth: .infinity)
                        later.frame(width: 50)
                        home.frame(width: 54)
                    }
                }
            }
            .frame(width: keys.width, height: keys.height)
            .position(x: keys.midX, y: keys.midY)
        }
    }

    /// A key of the pile: its glyph, in the key's own ink (with its words
    /// beside it where they are kept: 回去拍照).
    private func key(_ glyph: ShellGlyph, _ words: String?, _ label: String, _ identifier: String, _ style: ShellKeyStyle, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Group {
                if let words {
                    ShellGlyphLabel(glyph: glyph, words: words, size: 16, wordSize: 12.5, ink: style.tone.ink)
                } else {
                    ShellGlyphView(glyph: glyph, size: 18, ink: style.tone.ink)
                }
            }
            .padding(.horizontal, 6)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .buttonStyle(style)
        .accessibilityLabel(label)
        .accessibilityIdentifier(identifier)
    }
}

/// One print: the sheet, the picture in its window (a video's plays there),
/// the wide margin below with when it was taken.
private struct InstantSheet: View {
    var image: CGImage?
    var caption: String
    var video: Bool
    var playing: Bool
    var url: URL?
    var ended: () -> Void
    var body: some View {
        GeometryReader { geo in
            let side: CGFloat = 12, foot: CGFloat = 44
            let w = max(0, geo.size.width - 2 * side), h = max(0, geo.size.height - side - foot)
            ZStack(alignment: .top) {
                RoundedRectangle(cornerRadius: 3, style: .continuous).fill(Color(red: 0.985, green: 0.975, blue: 0.955))
                    .shadow(color: Color.black.opacity(0.32), radius: 4, y: 2)
                VStack(spacing: 0) {
                    ZStack {
                        Color(red: 0.16, green: 0.16, blue: 0.15)
                        if let image {
                            Image(decorative: image, scale: 1).resizable().scaledToFill().frame(width: w, height: h).clipped()
                        }
                        if video {
                            #if os(iOS)
                            if playing, let url {
                                CameraVideoPlayer(url: url, ended: ended).frame(width: w, height: h)
                                    .accessibilityIdentifier("camera-album-player")
                            }
                            #endif
                            if !playing {
                                Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9))
                                    .shadow(color: .black.opacity(0.5), radius: 4)
                            }
                        }
                    }
                    .frame(width: w, height: h)
                    .clipped()
                    .padding(.top, side)
                    Text(caption).font(.system(size: 11, weight: .semibold, design: .rounded)).foregroundStyle(Color(red: 0.36, green: 0.33, blue: 0.29))
                        .lineLimit(1).minimumScaleFactor(0.6)
                        .frame(width: w, height: foot)
                }
            }
        }
    }
}

extension CameraDeckFace {
    /// A body's album where its back is worn — the instant camera's pile:
    /// in the column's upper part with the keys under it (upright), in the
    /// screen's place with the keys in their column (across). (The phone's
    /// 图库 is on its own screen: clamAlbum.)
    @ViewBuilder func shellAlbum(_ skin: CameraShellSkin, tray: CGRect, keys: CGRect, stacked: Bool) -> some View {
        InstantPile(model: model, thumbnails: thumbnails, tone: skin.tone, tray: tray, keys: keys, stacked: stacked)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The clamshell phone's back

/// The clamshell phone's colours: the body's pearly plastic, the key panel
/// let into it and the keys on that, what is written on each, the screen's
/// bars and its chosen zoom stop, the lamps under the grip's surface. Four
/// sets, the same phone in each (on the navy one and the pearl one the panel
/// and the hinge are bright metal).
struct ClamPaint: Equatable {
    var name: String
    var plastic: ShellTone
    var panel: ShellTone
    var key: ShellTone
    var ink: Color
    var soft: Color
    /// What is printed on the body itself.
    var legend: Color
    var accent: Color
    var bar: Color
    var glow: Color
    var dark = false
    var metal = false

    static let pink = ClamPaint(name: "pink", plastic: ShellTone(r: 0.953, g: 0.722, b: 0.788), panel: ShellTone(r: 0.980, g: 0.839, b: 0.878), key: ShellTone(r: 1.0, g: 0.945, b: 0.961),
                                ink: Color(red: 0.482, green: 0.200, blue: 0.314), soft: Color(red: 0.627, green: 0.306, blue: 0.416),
                                legend: Color(red: 0.482, green: 0.200, blue: 0.314).opacity(0.8), accent: Color(red: 0.878, green: 0.322, blue: 0.478),
                                bar: Color(red: 0.212, green: 0.086, blue: 0.149).opacity(0.8), glow: Color(red: 1.0, green: 0.616, blue: 0.361))
    static let mint = ClamPaint(name: "mint", plastic: ShellTone(r: 0.620, g: 0.871, b: 0.804), panel: ShellTone(r: 0.784, g: 0.937, b: 0.894), key: ShellTone(r: 0.953, g: 0.992, b: 0.980),
                                ink: Color(red: 0.114, green: 0.361, blue: 0.325), soft: Color(red: 0.200, green: 0.475, blue: 0.427),
                                legend: Color(red: 0.114, green: 0.361, blue: 0.325).opacity(0.8), accent: Color(red: 0.090, green: 0.647, blue: 0.549),
                                bar: Color(red: 0.055, green: 0.173, blue: 0.157).opacity(0.8), glow: Color(red: 1.0, green: 0.706, blue: 0.361))
    static let navy = ClamPaint(name: "navy", plastic: ShellTone(r: 0.125, g: 0.196, b: 0.478), panel: ShellTone(r: 0.824, g: 0.839, b: 0.871), key: ShellTone(r: 0.933, g: 0.941, b: 0.961),
                                ink: Color(red: 0.106, green: 0.165, blue: 0.388), soft: Color(red: 0.267, green: 0.329, blue: 0.549),
                                legend: Color(red: 0.894, green: 0.918, blue: 0.980).opacity(0.88), accent: Color(red: 0.247, green: 0.427, blue: 0.949),
                                bar: Color(red: 0.047, green: 0.071, blue: 0.180).opacity(0.84), glow: Color(red: 0.624, green: 0.816, blue: 1.0), dark: true, metal: true)
    static let pearl = ClamPaint(name: "pearl", plastic: ShellTone(r: 0.957, g: 0.949, b: 0.925), panel: ShellTone(r: 0.839, g: 0.851, b: 0.878), key: ShellTone(r: 0.992, g: 0.992, b: 0.984),
                                 ink: Color(red: 0.267, green: 0.290, blue: 0.345), soft: Color(red: 0.420, green: 0.447, blue: 0.510),
                                 legend: Color(red: 0.267, green: 0.290, blue: 0.345).opacity(0.8), accent: Color(red: 0.435, green: 0.525, blue: 0.722),
                                 bar: Color(red: 0.094, green: 0.110, blue: 0.149).opacity(0.8), glow: Color(red: 1.0, green: 0.651, blue: 0.302), metal: true)
    /// Every colour the phone is made in, the one it comes in first.
    static let all: [ClamPaint] = [pink, mint, navy, pearl]
    /// The green key's colour and the red key's, the same on every body.
    static let green = ShellTone(r: 0.337, g: 0.729, b: 0.455)
    static let red = ShellTone(r: 0.894, g: 0.322, b: 0.306)
    /// Bright metal lit across it (the screen's surround, the ring's rim, the side key).
    static let chrome = Gradient(stops: [Gradient.Stop(color: Color(red: 0.984, green: 0.988, blue: 0.992), location: 0), Gradient.Stop(color: Color(red: 0.706, green: 0.725, blue: 0.761), location: 0.2),
                                         Gradient.Stop(color: Color(red: 0.949, green: 0.953, blue: 0.961), location: 0.42), Gradient.Stop(color: Color(red: 0.584, green: 0.608, blue: 0.647), location: 0.68),
                                         Gradient.Stop(color: Color(red: 0.886, green: 0.898, blue: 0.914), location: 1)])
    /// Metal turned on a lathe, the light going round it (the key in the ring's middle).
    static let turned = Gradient(stops: [Gradient.Stop(color: Color(red: 0.992, green: 0.992, blue: 0.996), location: 0), Gradient.Stop(color: Color(red: 0.702, green: 0.722, blue: 0.757), location: 0.13),
                                         Gradient.Stop(color: Color(red: 0.953, green: 0.957, blue: 0.965), location: 0.25), Gradient.Stop(color: Color(red: 0.635, green: 0.659, blue: 0.694), location: 0.38),
                                         Gradient.Stop(color: Color(red: 0.973, green: 0.976, blue: 0.980), location: 0.5), Gradient.Stop(color: Color(red: 0.690, green: 0.710, blue: 0.745), location: 0.63),
                                         Gradient.Stop(color: Color(red: 0.937, green: 0.941, blue: 0.949), location: 0.75), Gradient.Stop(color: Color(red: 0.620, green: 0.643, blue: 0.682), location: 0.88),
                                         Gradient.Stop(color: Color(red: 0.992, green: 0.992, blue: 0.996), location: 1)])

    /// What the colour is called.
    var title: String {
        switch name {
        case "mint": return String(localized: "薄荷绿")
        case "navy": return String(localized: "深蓝配银")
        case "pearl": return String(localized: "珍珠白配银")
        default: return String(localized: "粉")
        }
    }
    /// The colour as a back's (what is kept, and the dot that shows it).
    var tint: ShellTint { ShellTint(name: name, title: title, dot: plastic) }
    /// The paint of that name (none kept, or one not known: the one it comes in).
    static func named(_ name: String?) -> ClamPaint { all.first { $0.name == name } ?? pink }
}

/// What the lamps under the grip's surface show: a number in dots (the
/// self-timer's count), a disc (a video being taken).
enum ClamDots {
    static let large: [[String]] = [
        [".###.", "#...#", "#...#", "#...#", "#...#", "#...#", ".###."],
        ["..#..", ".##..", "..#..", "..#..", "..#..", "..#..", ".###."],
        [".###.", "#...#", "....#", "...#.", "..#..", ".#...", "#####"],
        [".###.", "#...#", "....#", "..##.", "....#", "#...#", ".###."],
        ["...#.", "..##.", ".#.#.", "#..#.", "#####", "...#.", "...#."],
        ["#####", "#....", "####.", "....#", "....#", "#...#", ".###."],
        ["..##.", ".#...", "#....", "####.", "#...#", "#...#", ".###."],
        ["#####", "....#", "...#.", "..#..", ".#...", ".#...", ".#..."],
        [".###.", "#...#", "#...#", ".###.", "#...#", "#...#", ".###."],
        [".###.", "#...#", "#...#", ".####", "....#", "...#.", ".##.."]
    ]
    static let small: [[String]] = [
        ["###", "#.#", "#.#", "#.#", "###"],
        [".#.", "##.", ".#.", ".#.", "###"],
        ["###", "..#", "###", "#..", "###"],
        ["###", "..#", "###", "..#", "###"],
        ["#.#", "#.#", "###", "..#", "..#"],
        ["###", "#..", "###", "..#", "###"],
        ["###", "#..", "###", "#.#", "###"],
        ["###", "..#", "..#", "..#", "..#"],
        ["###", "#.#", "###", "#.#", "###"],
        ["###", "#.#", "###", "..#", "###"]
    ]
    static let disc: [String] = [".###.", "#####", "#####", "#####", ".###."]
    /// A number's rows for lamps `columns` across: its figures side by side,
    /// a dark column between two; the small figures where the large do not fit.
    static func number(_ value: Int, columns: Int) -> [String] {
        let figures = String(max(0, value)).compactMap { $0.wholeNumberValue }
        guard !figures.isEmpty else { return [] }
        let font = figures.count * 6 - 1 <= columns ? large : small
        var rows: [String] = []
        for row in 0..<font[0].count {
            rows.append(figures.map { font[$0][row] }.joined(separator: "."))
        }
        return rows
    }
}

/// The twelve keys: the sign on each, the pair of tones it sounds, and what
/// it is called for the tests.
enum ClamKeys {
    static let marks: [String] = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "＊", "0", "#"]
    static let tones: [ConsoleSound] = [.phoneTone1, .phoneTone2, .phoneTone3, .phoneTone4, .phoneTone5, .phoneTone6, .phoneTone7, .phoneTone8,
                                        .phoneTone1, .phoneTone4, .phoneTone5, .phoneTone6]
    static let identifiers: [String] = ["camera-deck-flash", "camera-deck-wb", "camera-deck-iso", "camera-deck-ev-minus", "camera-deck-date", "camera-deck-ev-plus",
                                        "camera-deck-strength-minus", "camera-deck-aspect", "camera-deck-strength-plus", "camera-deck-timer", "camera-deck-switch", "camera-deck-leveler"]
    /// What each is called: what it sets.
    static func legends(shape: String) -> [String] {
        let exposure = String(localized: "曝光"), strength = String(localized: "浓淡")
        return [String(localized: "闪光"), String(localized: "白平衡"), "ISO", exposure + " −", String(localized: "日期"), exposure + " +",
                strength + " −", shape, strength + " +", String(localized: "定时"), String(localized: "内外侧"), String(localized: "水平仪")]
    }
}

/// What a key of the phone shows in place of its words: one of the cover
/// keys' glyphs, or one of the phone's own — 返回 (a turn back), ＊ and #
/// turning 图库's page (the nine with an arrow before or after them), 曝光 −
/// and ＋ (± in a circle with its sign beside it, as 浓淡's keys have theirs).
private enum ClamGlyph: Equatable {
    case cover(ShellGlyph)
    case back
    case page(forward: Bool)
    case exposure(up: Bool)
}

/// What is drawn on each of the twelve in place of what it sets: that
/// thing's glyph, as it stands.
private func clamGlyphs(_ shooting: CameraShooting, timer: CameraTimer, shape: CameraAspect, leveler: Bool) -> [ClamGlyph] {
    [.cover(.flash(shooting.flash)), .cover(.whiteBalance(shooting.whiteBalance)), .cover(.iso(shooting.iso)),
     .exposure(up: false), .cover(.date(shooting.dateStamp)), .exposure(up: true),
     .cover(.toneDown), .cover(.shape(shape)), .cover(.toneUp),
     .cover(.timer(timer)), .cover(.flip), .cover(.level(leveler))]
}

/// A ClamGlyph at `size` in `ink` (as ShellGlyphView draws, the phone's own
/// with the same weight); hidden from VoiceOver: the key says its own name.
private struct ClamGlyphView: View {
    var glyph: ClamGlyph
    var size: CGFloat
    var ink: Color
    var body: some View {
        art.accessibilityHidden(true)
    }
    @ViewBuilder private var art: some View {
        switch glyph {
        case .cover(let shell):
            ShellGlyphView(glyph: shell, size: size, ink: ink)
        case .back:
            Image(systemName: "arrow.uturn.backward").font(.system(size: size * 0.9, weight: ShellGlyphView.weight)).foregroundStyle(ink)
        case .page(let forward):
            HStack(spacing: size * 0.04) {
                if !forward { chevron("chevron.left") }
                Image(systemName: "square.grid.3x3.fill").font(.system(size: size * 0.72, weight: ShellGlyphView.weight))
                if forward { chevron("chevron.right") }
            }
            .foregroundStyle(ink)
        case .exposure(let up):
            HStack(spacing: size * 0.06) {
                Image(systemName: "plusminus.circle").font(.system(size: size * 0.78, weight: ShellGlyphView.weight))
                Image(systemName: up ? "plus" : "minus").font(.system(size: size * 0.48, weight: .heavy))
            }
            .foregroundStyle(ink)
        }
    }
    private func chevron(_ name: String) -> some View {
        Image(systemName: name).font(.system(size: size * 0.5, weight: .bold))
    }
}

/// Where the clamshell phone's parts are on the cover, upright (from a
/// ShellPlan) or across (from a ShellAcrossPlan): the same parts both ways,
/// each laid out for its hold.
struct ClamLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    /// The lid's glass, and the screen in it.
    var glass = CGRect.zero
    var glassRadius: CGFloat = 17
    var screen = CGRect.zero
    /// Where the lid meets the base: a line across the body (upright).
    var seam = CGRect.zero
    /// The key panel let into the base (its lower corners rounder), and the hinge's barrel.
    var panel = CGRect.zero
    var panelFoot: CGFloat = 26
    var barrel = CGRect.zero
    /// The direction ring: its middle, its half-axes, and those with the gap
    /// the keys round it keep.
    var ring = CGPoint.zero
    var rx: CGFloat = 80
    var ry: CGFloat = 72
    var reach = CGSize(width: 88, height: 80)
    /// How far out the ring's signs stand (at the sides, up and down), the
    /// words inside them, and the four arrows of 图库.
    var signs = CGSize(width: 68, height: 56)
    var wordsAt = CGSize.zero
    var arrowsAt = CGSize(width: 54, height: 50)
    /// How far past the ring each side is touched too (over the word printed
    /// beside it, held across), and how wide those strips are.
    var ringOut = CGSize.zero
    var ringArm = CGSize(width: 56, height: 44)
    /// The upper left of the four keys round the ring (the others: `wingDrop`
    /// under it, and mirrored across the ring), and how wide it is clear of
    /// the ring (its word stands in the middle of that).
    var wing = CGRect.zero
    var wingDrop: CGFloat = 75
    var wingRadius: CGFloat = 16
    var wingBend: CGFloat = 10
    var wingClear: CGFloat = 88
    /// The first of the twelve, and the step to the next across and down.
    var digit = CGRect.zero
    var digitStep = CGSize.zero
    /// The key on the phone's side.
    var side = CGRect.zero
    /// ZERO, the dot beside it that changes the colour, the lamps under the
    /// surface and the grip's ribs (.zero: no room for it).
    var name = CGRect.zero
    var chip = CGRect.zero
    var lamps = CGRect.zero
    var lampColumns = 0
    var lampRows = 0
    var lampPitch: CGFloat = 6.6
    var ribs = CGRect.zero
    /// The column's width against the Duo's (upright, the parts are that much narrower).
    var u: CGFloat = 1

    /// The room kept round the ring for its shadow.
    static let ringRoom: CGFloat = 8
    /// One of the four keys round the ring: the upper or the lower, on the
    /// ring's near side or mirrored across it.
    func wingRect(low: Bool, mirror: Bool) -> CGRect {
        let x = mirror ? 2 * ring.x - wing.maxX : wing.minX
        return CGRect(x: x, y: wing.minY + (low ? wingDrop : 0), width: wing.width, height: wing.height)
    }
    func wingShape(low: Bool, mirror: Bool) -> ClamWing {
        let middle = CGPoint(x: ring.x - wing.minX, y: ring.y - wing.minY - (low ? wingDrop : 0))
        return ClamWing(centre: middle, reach: reach, radius: wingRadius, bend: wingBend, mirror: mirror)
    }
    func digitRect(_ index: Int) -> CGRect {
        digit.offsetBy(dx: CGFloat(index % 3) * digitStep.width, dy: CGFloat(index / 3) * digitStep.height)
    }
    /// The ring with the room round it (as far as it is touched), and the
    /// key in its middle.
    var ringFrame: CGRect {
        let half = CGSize(width: rx + max(Self.ringRoom, ringOut.width), height: ry + max(Self.ringRoom, ringOut.height))
        return CGRect(x: ring.x - half.width, y: ring.y - half.height, width: 2 * half.width, height: 2 * half.height)
    }
    var hub: CGRect { CGRect(x: ring.x - 22, y: ring.y - 22, width: 44, height: 44) }
    var sideRadius: CGFloat { max(4, min(side.width, side.height) / 2 - 2) }
    /// The lamps' place round `middle`, with room for a lit one's glow.
    static func lampBox(_ middle: CGPoint, columns: Int, rows: Int, pitch: CGFloat) -> CGRect {
        let w = CGFloat(columns - 1) * pitch + 16, h = CGFloat(rows - 1) * pitch + 16
        return CGRect(x: middle.x - w / 2, y: middle.y - h / 2, width: w, height: h)
    }
}

extension ShellPlan {
    /// The clamshell phone's parts, upright: the lid's glass at the head of
    /// the column, the hinge's barrel under it, the key panel below that;
    /// in the strip the lamps, the ribs where the Camera Control's overlay
    /// comes in, and the side key; under the panel ZERO and the colour's dot.
    var clam: ClamLayout {
        let glass = surround, k = keysTop, strip = back.strip
        var l = ClamLayout()
        l.canvas = back.canvas
        l.u = u
        l.glass = glass
        l.screen = box
        l.seam = CGRect(x: 1, y: glass.maxY + 10, width: max(0, back.canvas.width - 2), height: 0)
        l.panel = CGRect(x: x(12), y: glass.maxY + 10, width: 378 * u, height: 362)
        l.barrel = CGRect(x: x(13), y: glass.maxY + 1.5, width: 376 * u, height: 17)
        l.ring = CGPoint(x: x(201), y: k + 72)
        l.rx = 80 * u
        l.reach = CGSize(width: 88 * u, height: 80)
        l.signs = CGSize(width: 68 * u, height: 56)
        l.wordsAt = CGSize(width: 49 * u, height: 41)
        l.arrowsAt = CGSize(width: 54 * u, height: 50)
        l.wing = CGRect(x: x(20), y: k, width: 126 * u, height: 69)
        l.wingClear = 88 * u
        l.digit = CGRect(x: x(20), y: k + 150, width: 116 * u, height: 44)
        l.digitStep = CGSize(width: 123 * u, height: 50)
        l.side = shutter
        l.name = CGRect(x: x(204) - 50, y: keysBottom + 14, width: 100, height: 18)
        l.chip = CGRect(x: x(324.5) - 7, y: keysBottom + 16, width: 14, height: 14)
        if let zone = back.overlay {
            let floor = back.keepOut.map(\.maxY).max() ?? strip.minY
            if zone.minY - floor >= 84 {
                l.lampColumns = 7
                l.lampRows = 11
                l.lamps = ClamLayout.lampBox(CGPoint(x: strip.midX, y: (floor + zone.minY) / 2), columns: 7, rows: 11, pitch: l.lampPitch)
            }
            l.ribs = CGRect(x: strip.midX - 27, y: zone.minY + 14, width: 54, height: max(0, zone.height - 24))
        }
        return l
    }
}

extension ShellAcrossPlan {
    /// The clamshell phone's parts with the cover held across: the screen at
    /// the left; the key panel in the keys' column, the hinge's barrel
    /// standing between them; in the band ZERO, the colour's dot and the
    /// lamps in its longer clear run, the ribs in the overlay's place, the
    /// side key in the other run.
    var clam: ClamLayout {
        let s = back.screen, keys = back.keys, run = back.run
        let wide = (keys.width - 12) / 3
        var l = ClamLayout()
        l.across = true
        l.canvas = back.canvas
        l.glass = CGRect(x: s.minX + 7, y: s.minY + 7, width: max(0, s.width - 16), height: max(0, s.height - 14))
        l.glassRadius = 14
        l.screen = box
        l.panel = CGRect(x: keys.minX - 10, y: keys.minY - 5, width: keys.width + 15, height: keys.height + 10)
        l.panelFoot = 22
        l.barrel = CGRect(x: keys.minX - 15, y: keys.minY + 12, width: 10, height: max(0, keys.height - 50))
        l.ring = CGPoint(x: keys.minX + 100, y: keys.minY + 75)
        l.rx = 57
        l.ry = 57
        l.reach = CGSize(width: 63, height: 63)
        l.signs = CGSize(width: 42, height: 42)
        l.arrowsAt = CGSize(width: 42, height: 42)
        l.ringOut = CGSize(width: 43, height: 18)
        l.ringArm = CGSize(width: wide, height: 44)
        l.wing = key(0, 0, wide, 46)
        l.wingDrop = 104
        l.wingRadius = 13
        l.wingBend = 6
        l.wingClear = 48
        l.digit = key(0, 162, wide, 44)
        l.digitStep = CGSize(width: wide + 6, height: 50)
        l.side = shutter
        // (Where the side key has to share the longer run, what is left of it.)
        let room = back.spare.width >= 116 ? run.width : run.width - 116
        if room >= 80 { l.name = CGRect(x: run.minX + 6, y: run.midY - 8, width: 74, height: 20) }
        if room >= 120 { l.chip = CGRect(x: run.minX + 89, y: run.midY - 5, width: 14, height: 14) }
        if room >= 182 {
            l.lampColumns = 11
            l.lampRows = 7
            l.lampPitch = 6.2
            l.lamps = ClamLayout.lampBox(CGPoint(x: run.minX + 144, y: run.midY + 1), columns: 11, rows: 7, pitch: 6.2)
        }
        if let zone = back.overlay, zone.width > 30 {
            l.ribs = CGRect(x: zone.minX + 12, y: back.band.minY + 12, width: max(0, zone.width - 22), height: 50)
        }
        return l
    }
}

/// A key wrapped round the direction ring: a rounded block whose inner side
/// follows the ring at an even gap. (`centre`: the ring's middle from the
/// block's outer upper corner; `reach`: the ring's half-axes with the gap;
/// `mirror`: the block on the ring's other side.)
struct ClamWing: Shape, Equatable {
    var centre: CGPoint
    var reach: CGSize
    var radius: CGFloat = 16
    var bend: CGFloat = 10
    var mirror = false
    /// Larger all round by this much (the well the key sits in).
    var grow: CGFloat = 0
    func path(in rect: CGRect) -> Path {
        let a = max(1, reach.width - grow), b = max(1, reach.height - grow)
        let x0 = -grow, y0 = -grow, x1 = rect.width + grow, y1 = rect.height + grow
        let middle = centre
        func limit(_ y: CGFloat) -> CGFloat {
            let t = (y - middle.y) / b
            guard abs(t) < 1 else { return x1 }
            return min(x1, middle.x - a * (1 - t * t).squareRoot())
        }
        var path = Path()
        path.move(to: CGPoint(x: x0 + radius, y: y0))
        path.addLine(to: CGPoint(x: limit(y0) - bend, y: y0))
        path.addQuadCurve(to: CGPoint(x: limit(y0 + bend), y: y0 + bend), control: CGPoint(x: limit(y0), y: y0))
        var y = y0 + bend + 1.5
        while y < y1 - bend {
            path.addLine(to: CGPoint(x: limit(y), y: y))
            y += 1.5
        }
        path.addLine(to: CGPoint(x: limit(y1 - bend), y: y1 - bend))
        path.addQuadCurve(to: CGPoint(x: limit(y1) - bend, y: y1), control: CGPoint(x: limit(y1), y: y1))
        path.addLine(to: CGPoint(x: x0 + radius, y: y1))
        path.addQuadCurve(to: CGPoint(x: x0, y: y1 - radius), control: CGPoint(x: x0, y: y1))
        path.addLine(to: CGPoint(x: x0, y: y0 + radius))
        path.addQuadCurve(to: CGPoint(x: x0 + radius, y: y0), control: CGPoint(x: x0, y: y0))
        path.closeSubpath()
        let turn = mirror ? CGAffineTransform(a: -1, b: 0, c: 0, d: 1, tx: rect.width, ty: 0) : CGAffineTransform.identity
        return path.applying(turn).offsetBy(dx: rect.minX, dy: rect.minY)
    }
}

/// A small solid arrowhead: 0 up, 1 right, 2 down, 3 left.
struct ClamArrow: Shape {
    var way: Int
    func path(in rect: CGRect) -> Path {
        var path = Path()
        switch way {
        case 0:
            path.move(to: CGPoint(x: rect.midX, y: rect.minY))
            path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
            path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
        case 1:
            path.move(to: CGPoint(x: rect.maxX, y: rect.midY))
            path.addLine(to: CGPoint(x: rect.minX, y: rect.maxY))
            path.addLine(to: CGPoint(x: rect.minX, y: rect.minY))
        case 2:
            path.move(to: CGPoint(x: rect.midX, y: rect.maxY))
            path.addLine(to: CGPoint(x: rect.minX, y: rect.minY))
            path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
        default:
            path.move(to: CGPoint(x: rect.minX, y: rect.midY))
            path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
            path.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY))
        }
        path.closeSubpath()
        return path
    }
}

/// A domed key's top: lighter above, a gloss over its upper half and a shade
/// along its foot, a fine light edge; its shadow shorter while it is down,
/// the light behind it showing.
private struct ClamCap<S: Shape>: View {
    var shape: S
    var tone: ShellTone
    /// How bright the top is (a coloured key's less than a pale one's).
    var gloss: Double = 1
    var down = false
    var lamp: Color
    var body: some View {
        let top = LinearGradient(stops: [Gradient.Stop(color: tone.color(0.55 * gloss), location: 0), Gradient.Stop(color: tone.color(0), location: 0.42), Gradient.Stop(color: tone.color(-0.17), location: 1)],
                                 startPoint: .top, endPoint: .bottom)
        let shine = LinearGradient(stops: [Gradient.Stop(color: Color.white.opacity(0.5 * gloss), location: 0), Gradient.Stop(color: Color.white.opacity(0), location: 0.5),
                                           Gradient.Stop(color: Color.black.opacity(0), location: 0.72), Gradient.Stop(color: Color.black.opacity(0.10), location: 1)],
                                   startPoint: .top, endPoint: .bottom)
        ZStack {
            shape.fill(top)
            shape.fill(shine)
            if down { shape.fill(lamp.opacity(0.22)) }
            shape.stroke(Color.white.opacity(down ? 0.4 : 0.62), lineWidth: 1)
        }
        .shadow(color: Color.black.opacity(down ? 0.18 : 0.36), radius: down ? 0.6 : 1.5, y: down ? 0.5 : 1.6)
    }
}

/// A key of the phone going down: the cap on its well (which stays), the
/// key's sound and its feel as it goes.
private struct ClamKeyBody<S: Shape, T: Shape, W: View>: View {
    let configuration: ButtonStyle.Configuration
    var shape: S
    /// Where it is touched (with room round the key, all of that).
    var touch: T
    var well: W
    var tone: ShellTone
    var gloss: Double
    var ink: Color
    var lamp: Color
    var sound: ConsoleSound
    var haptic: HapticPart
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .foregroundStyle(ink)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ClamCap(shape: shape, tone: tone, gloss: gloss, down: down, lamp: lamp))
            .offset(y: down ? 1.4 : 0)
            .background(well)
            .padding(room)
            .contentShape(touch)
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(sound, scale: 0.8)
                ConsoleHaptics.shared.play(haptic, .press)
            }
    }
}

/// One of the phone's twelve keys: a small rounded cap in its well, its own
/// pair of tones as it goes down.
struct ClamKeyStyle: ButtonStyle {
    var paint: ClamPaint
    var radius: CGFloat = 11
    var sound: ConsoleSound = .phoneSoft
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View {
        let well = RoundedRectangle(cornerRadius: radius + 1.3).fill(Color.black.opacity(0.3))
            .padding(EdgeInsets(top: -1, leading: -1.3, bottom: -2.6, trailing: -1.3))
        return ClamKeyBody(configuration: configuration, shape: RoundedRectangle(cornerRadius: radius), touch: Rectangle(), well: well,
                           tone: paint.key, gloss: 1, ink: paint.ink, lamp: paint.accent, sound: sound, haptic: haptic)
    }
}

/// One of the four keys wrapped round the ring: the two soft keys in the
/// keys' own colour, the green key and the red.
struct ClamWingStyle: ButtonStyle {
    var paint: ClamPaint
    var wing: ClamWing
    var tone: ShellTone? = nil
    var gloss: Double = 1
    var ink: Color? = nil
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View {
        var deep = wing
        deep.grow = 1.3
        let well = deep.fill(Color.black.opacity(0.3)).offset(y: 1.2)
        return ClamKeyBody(configuration: configuration, shape: wing, touch: wing, well: well,
                           tone: tone ?? paint.key, gloss: gloss, ink: ink ?? paint.ink, lamp: paint.accent, sound: .phoneSoft, haptic: haptic)
    }
}

/// The key in the ring's middle: metal turned on a lathe, its fine circles
/// catching the light.
struct ClamHubStyle: ButtonStyle {
    var paint: ClamPaint
    var sound: ConsoleSound = .keyMetal
    var haptic: HapticPart = .faceButton
    func makeBody(configuration: Configuration) -> some View { ClamHubBody(configuration: configuration, style: self) }
}
private struct ClamHubBody: View {
    let configuration: ButtonStyle.Configuration
    let style: ClamHubStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .foregroundStyle(style.paint.ink)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ClamHubFace().brightness(down ? -0.08 : 0))
            .offset(y: down ? 1.2 : 0)
            .background(Circle().fill(Color.black.opacity(0.45)).padding(-0.8).offset(y: 1.2))
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}
private struct ClamHubFace: View {
    var body: some View {
        ZStack {
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(-2.2)))
            Canvas { context, size in
                let r = min(size.width, size.height) / 2, c = CGPoint(x: size.width / 2, y: size.height / 2)
                var k = r - 3
                while k > 3 {
                    context.stroke(Path(ellipseIn: CGRect(x: c.x - k, y: c.y - k, width: 2 * k, height: 2 * k)), with: .color(Color.black.opacity(0.045)), lineWidth: 0.7)
                    k -= 3
                }
                let rim = r - 0.7
                context.stroke(Path(ellipseIn: CGRect(x: c.x - rim, y: c.y - rim, width: 2 * rim, height: 2 * rim)), with: .color(Color.white.opacity(0.75)), lineWidth: 1)
            }
        }
    }
}

/// The key on the phone's side that takes the picture: a bar of bright
/// metal, a paler face let into it.
struct ClamSideStyle: ButtonStyle {
    var radius: CGFloat
    var sound: ConsoleSound = .keyMetal
    var haptic: HapticPart = .faceButton
    func makeBody(configuration: Configuration) -> some View { ClamSideBody(configuration: configuration, style: self) }
}
private struct ClamSideBody: View {
    let configuration: ButtonStyle.Configuration
    let style: ClamSideStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ClamSideFace(radius: style.radius, down: down))
            .offset(y: down ? 1.8 : 0)
            .background(RoundedRectangle(cornerRadius: style.radius + 2).fill(Color.black.opacity(0.4))
                .padding(EdgeInsets(top: -1.6, leading: -2, bottom: -3, trailing: -2)))
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}
private struct ClamSideFace: View {
    var radius: CGFloat
    var down: Bool
    var body: some View {
        let bar = RoundedRectangle(cornerRadius: radius), face = RoundedRectangle(cornerRadius: max(2, radius - 3))
        let pale = LinearGradient(colors: [Color.white, Color(red: 0.894, green: 0.902, blue: 0.918), Color(red: 0.765, green: 0.780, blue: 0.812)], startPoint: .top, endPoint: .bottom)
        ZStack {
            bar.fill(LinearGradient(gradient: ClamPaint.chrome, startPoint: .topLeading, endPoint: .bottomTrailing))
                .shadow(color: Color.black.opacity(down ? 0.2 : 0.45), radius: down ? 0.6 : 2, y: down ? 0.5 : 2)
            face.fill(pale).overlay(face.stroke(Color.black.opacity(0.22), lineWidth: 0.8)).padding(3.5)
            bar.stroke(Color.white.opacity(0.8), lineWidth: 0.9).padding(0.7)
            if down { bar.fill(Color.black.opacity(0.08)) }
        }
    }
}

/// The phone's body, drawn as the picture of it was (mock/flip3.js, part for
/// part): pearly plastic with a soft sheen and fine flecks, the lid's glass
/// in the shadow of its bright surround, the line where the lid meets the
/// base, the key panel let into the base (brushed metal on the navy and the
/// pearl), the grip's ribs where the Camera Control's overlay comes in, the
/// lamps under its surface, unlit. Drawn once for a colour.
private struct ClamBackdrop: View, Equatable {
    var layout: ClamLayout
    var paint: ClamPaint
    var hinge: CGRect
    var body: some View {
        Canvas { context, size in
            Self.plastic(context, size, paint, hinge)
            Self.lid(context, layout)
            Self.base(context, layout, paint)
            Self.grip(context, layout, paint)
            context.stroke(Path(CGRect(origin: .zero, size: size).insetBy(dx: 1.5, dy: 1.5)), with: .color(Color.white.opacity(0.35)), lineWidth: 1.2)
        }
        .accessibilityHidden(true)
    }

    private static func plastic(_ context: GraphicsContext, _ size: CGSize, _ paint: ClamPaint, _ hinge: CGRect) {
        let whole = CGRect(origin: .zero, size: size), tone = paint.plastic, far = max(size.width, size.height)
        context.fill(Path(whole), with: .linearGradient(Gradient(stops: [Gradient.Stop(color: tone.color(0.22), location: 0), Gradient.Stop(color: tone.color(0), location: 0.35),
                                                                         Gradient.Stop(color: tone.color(-0.28), location: 1)]),
                                                        startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
        var seed: UInt32 = 0x1357_9BDF
        func next() -> CGFloat {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            return CGFloat((seed >> 8) & 0xFFFF) / 65535
        }
        // the fine flecks in it
        let fleck = paint.dark ? 0.06 : 0.034
        for _ in 0..<Int(size.width * size.height / 28) {
            let at = CGPoint(x: next() * size.width, y: next() * size.height), a = Double(next()) * fleck
            context.fill(Path(CGRect(x: at.x, y: at.y, width: 1, height: 1)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
        }
        // the hinge's edge falls into shade
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let from = tall ? CGPoint(x: hinge.midX < size.width / 2 ? hinge.minX : hinge.maxX, y: 0) : CGPoint(x: 0, y: hinge.midY < size.height / 2 ? hinge.minY : hinge.maxY)
            let to = tall ? CGPoint(x: hinge.midX < size.width / 2 ? hinge.maxX : hinge.minX, y: 0) : CGPoint(x: 0, y: hinge.midY < size.height / 2 ? hinge.maxY : hinge.minY)
            context.fill(Path(hinge), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.45), Color.black.opacity(0)]), startPoint: from, endPoint: to))
        }
        // the sheen: a wide light from the upper left, a small one at the far corner
        context.fill(Path(whole), with: .radialGradient(Gradient(stops: [Gradient.Stop(color: Color.white.opacity(0.34), location: 0), Gradient.Stop(color: Color.white.opacity(0.05), location: 0.45),
                                                                         Gradient.Stop(color: Color.black.opacity(0.06), location: 1)]),
                                                        center: CGPoint(x: size.width * 0.22, y: size.height * 0.1), startRadius: 8, endRadius: far * 0.75))
        context.fill(Path(whole), with: .radialGradient(Gradient(colors: [Color.white.opacity(0.14), Color.white.opacity(0)]),
                                                        center: CGPoint(x: size.width * 0.86, y: size.height * 0.9), startRadius: 4, endRadius: far * 0.4))
    }

    /// The glass, black under the picture, and the shadow its surround throws.
    private static func lid(_ context: GraphicsContext, _ layout: ClamLayout) {
        let glass = layout.glass, r = layout.glassRadius
        guard glass.width > 0, glass.height > 0 else { return }
        var shade = context
        shade.addFilter(.shadow(color: Color.black.opacity(0.38), radius: 2.5, x: 0, y: 1.5))
        shade.fill(Path(roundedRect: glass.insetBy(dx: -3, dy: -3), cornerRadius: r + 3),
                   with: .linearGradient(ClamPaint.chrome, startPoint: glass.origin, endPoint: CGPoint(x: glass.maxX, y: glass.maxY)))
        context.fill(Path(roundedRect: glass, cornerRadius: r), with: .color(Color(red: 0.03, green: 0.03, blue: 0.04)))
    }

    /// The line where the lid meets the base, and the key panel let into the base.
    private static func base(_ context: GraphicsContext, _ layout: ClamLayout, _ paint: ClamPaint) {
        let seam = layout.seam
        if seam.width > 0 {
            context.fill(Path(CGRect(x: seam.minX, y: seam.minY - 0.8, width: seam.width, height: 1.5)), with: .color(Color.black.opacity(0.3)))
            context.fill(Path(CGRect(x: seam.minX, y: seam.minY + 0.7, width: seam.width, height: 1)), with: .color(Color.white.opacity(0.4)))
        }
        let panel = layout.panel, tone = paint.panel, foot = layout.panelFoot
        guard panel.width > 0, panel.height > 0 else { return }
        func plate(_ grow: CGFloat) -> Path {
            let radii = RectangleCornerRadii(topLeading: 10 + grow, bottomLeading: foot + grow, bottomTrailing: foot + grow, topTrailing: 10 + grow)
            return Path(roundedRect: panel.insetBy(dx: -grow, dy: -grow), cornerRadii: radii, style: .circular)
        }
        context.fill(plate(1.6), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.42), Color.black.opacity(0.12)]),
                                                       startPoint: CGPoint(x: 0, y: panel.minY), endPoint: CGPoint(x: 0, y: panel.maxY)))
        context.fill(plate(0), with: .linearGradient(Gradient(stops: [Gradient.Stop(color: tone.color(0.3), location: 0), Gradient.Stop(color: tone.color(0), location: 0.45),
                                                                      Gradient.Stop(color: tone.color(-0.14), location: 1)]),
                                                     startPoint: panel.origin, endPoint: CGPoint(x: panel.maxX, y: panel.maxY)))
        var inner = context
        inner.clip(to: plate(0))
        var seed: UInt32 = 0x0F1E_2D3C
        func next() -> CGFloat {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            return CGFloat((seed >> 8) & 0xFFFF) / 65535
        }
        if paint.metal {
            // brushed across it
            for _ in 0..<Int(panel.height * 1.6) {
                let y = panel.minY + next() * panel.height, a = Double(next()) * 0.07
                inner.fill(Path(CGRect(x: panel.minX, y: y, width: panel.width, height: 0.5)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
            }
        } else {
            for _ in 0..<Int(panel.width * panel.height / 20) {
                let at = CGPoint(x: panel.minX + next() * panel.width, y: panel.minY + next() * panel.height), a = Double(next()) * 0.03
                inner.fill(Path(CGRect(x: at.x, y: at.y, width: 1, height: 1)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
            }
        }
        // the shade its upper edge throws into it
        inner.fill(Path(CGRect(x: panel.minX, y: panel.minY, width: panel.width, height: 10)),
                   with: .linearGradient(Gradient(colors: [Color.black.opacity(0.16), Color.black.opacity(0)]),
                                         startPoint: CGPoint(x: 0, y: panel.minY), endPoint: CGPoint(x: 0, y: panel.minY + 10)))
        context.stroke(plate(-0.8), with: .color(Color.white.opacity(0.55)), lineWidth: 1)
    }

    /// The grip: its ribs (across the strip upright, down the band across),
    /// and the lamps under the surface, hardly seen until they light.
    private static func grip(_ context: GraphicsContext, _ layout: ClamLayout, _ paint: ClamPaint) {
        let ribs = layout.ribs
        if ribs.width > 8, ribs.height > 8 {
            let groove = Color.black.opacity(paint.dark ? 0.5 : 0.17), lip = Color.white.opacity(paint.dark ? 0.1 : 0.55)
            if layout.across {
                var x = ribs.minX
                while x < ribs.maxX {
                    context.fill(Path(roundedRect: CGRect(x: x, y: ribs.minY, width: 2.4, height: ribs.height), cornerRadius: 1.2), with: .color(groove))
                    context.fill(Path(roundedRect: CGRect(x: x + 2.4, y: ribs.minY, width: 1.4, height: ribs.height), cornerRadius: 0.7), with: .color(lip))
                    x += 8
                }
            } else {
                var y = ribs.minY
                while y < ribs.maxY {
                    context.fill(Path(roundedRect: CGRect(x: ribs.minX, y: y, width: ribs.width, height: 2.4), cornerRadius: 1.2), with: .color(groove))
                    context.fill(Path(roundedRect: CGRect(x: ribs.minX, y: y + 2.4, width: ribs.width, height: 1.4), cornerRadius: 0.7), with: .color(lip))
                    y += 8
                }
            }
        }
        guard layout.lampColumns > 0, layout.lampRows > 0 else { return }
        let middle = CGPoint(x: layout.lamps.midX, y: layout.lamps.midY), pitch = layout.lampPitch
        let unlit = paint.dark ? Color.white.opacity(0.045) : Color.black.opacity(0.04)
        for j in 0..<layout.lampRows {
            for i in 0..<layout.lampColumns {
                let x = middle.x + (CGFloat(i) - CGFloat(layout.lampColumns - 1) / 2) * pitch
                let y = middle.y + (CGFloat(j) - CGFloat(layout.lampRows - 1) / 2) * pitch
                context.fill(Path(ellipseIn: CGRect(x: x - 1.5, y: y - 1.5, width: 3, height: 3)), with: .color(unlit))
            }
        }
    }
}

/// What lies over the picture's edge: the glass's bright surround and the
/// black glass round the picture (over the picture's own bezel), the
/// earpiece's slit at its top, and the hinge's barrel — three knuckles, a
/// bright-metal cap at each end — lying along the lid's edge, or standing
/// beside the screen with the cover held across. Nothing is pressed through it.
private struct ClamLid: View, Equatable {
    var glass: CGRect
    var radius: CGFloat
    /// The picture, seen through the glass.
    var hole: CGRect
    var slit: Bool
    var barrel: CGRect
    var paint: ClamPaint
    var body: some View {
        Canvas { context, size in
            let pane = Path(roundedRect: glass, cornerRadius: radius)
            var surround = Path(roundedRect: glass.insetBy(dx: -3, dy: -3), cornerRadius: radius + 3)
            surround.addPath(pane)
            context.fill(surround, with: .linearGradient(ClamPaint.chrome, startPoint: glass.origin, endPoint: CGPoint(x: glass.maxX, y: glass.maxY)), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: glass.insetBy(dx: -2.4, dy: -2.4), cornerRadius: radius + 2.4), with: .color(Color.white.opacity(0.8)), lineWidth: 0.8)
            var rim = pane
            if hole.width > 0, hole.height > 0 { rim.addPath(Path(roundedRect: hole, cornerRadius: 5, style: .continuous)) }
            context.fill(rim, with: .linearGradient(Gradient(colors: [Color(red: 0.082, green: 0.090, blue: 0.110), Color(red: 0.027, green: 0.031, blue: 0.039)]),
                                                    startPoint: CGPoint(x: 0, y: glass.minY), endPoint: CGPoint(x: 0, y: glass.maxY)), style: FillStyle(eoFill: true))
            context.stroke(pane, with: .color(Color.black.opacity(0.85)), lineWidth: 1.2)
            if slit {
                let ear = CGRect(x: glass.midX - 20, y: glass.minY + 1.3, width: 40, height: 2.4)
                context.fill(Path(roundedRect: ear, cornerRadius: 1.2), with: .color(Color(red: 0.169, green: 0.180, blue: 0.212)))
                context.fill(Path(roundedRect: CGRect(x: ear.minX, y: ear.minY, width: ear.width, height: 1), cornerRadius: 0.5), with: .color(Color.black))
            }
            Self.knuckles(context, barrel, paint)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    private static func knuckles(_ context: GraphicsContext, _ rect: CGRect, _ paint: ClamPaint) {
        guard rect.width > 0, rect.height > 0 else { return }
        let tall = rect.height > rect.width
        let length = tall ? rect.height : rect.width, thick = tall ? rect.width : rect.height
        /// A slice of the barrel: `run` long from `from` along it; `deep` thick from `at` across it.
        func slice(_ from: CGFloat, _ run: CGFloat, at: CGFloat = 0, deep: CGFloat? = nil) -> CGRect {
            let d = deep ?? thick
            return tall ? CGRect(x: rect.minX + at, y: rect.maxY - from - run, width: d, height: run) : CGRect(x: rect.minX + from, y: rect.minY + at, width: run, height: d)
        }
        let start = tall ? CGPoint(x: rect.minX, y: 0) : CGPoint(x: 0, y: rect.minY)
        let end = tall ? CGPoint(x: rect.maxX, y: 0) : CGPoint(x: 0, y: rect.maxY)
        let tone = paint.metal ? ShellTone(r: 0.8, g: 0.816, b: 0.847) : paint.plastic
        let round = Path(roundedRect: rect, cornerRadius: thick / 2)
        let well = tall ? CGRect(x: rect.minX - 1.6, y: rect.minY - 1.5, width: thick + 4.4, height: length + 3)
            : CGRect(x: rect.minX - 1.5, y: rect.minY - 1.6, width: length + 3, height: thick + 4.4)
        context.fill(Path(roundedRect: well, cornerRadius: thick / 2 + 2), with: .color(Color.black.opacity(0.42)))
        let sheen = Gradient(stops: [Gradient.Stop(color: tone.color(-0.08), location: 0), Gradient.Stop(color: tone.color(0.8), location: 0.14), Gradient.Stop(color: tone.color(0.3), location: 0.3),
                                     Gradient.Stop(color: tone.color(0), location: 0.55), Gradient.Stop(color: tone.color(-0.4), location: 0.86), Gradient.Stop(color: tone.color(-0.22), location: 1)])
        context.fill(round, with: .linearGradient(sheen, startPoint: start, endPoint: end))
        var inner = context
        inner.clip(to: round)
        inner.fill(Path(slice(0, length, at: thick * 0.16, deep: 1)), with: .color(Color.white.opacity(0.55)))
        let cap = Gradient(stops: [Gradient.Stop(color: Color(red: 0.788, green: 0.804, blue: 0.827), location: 0), Gradient.Stop(color: Color.white, location: 0.16),
                                   Gradient.Stop(color: Color(red: 0.776, green: 0.792, blue: 0.820), location: 0.45), Gradient.Stop(color: Color(red: 0.463, green: 0.486, blue: 0.525), location: 0.86),
                                   Gradient.Stop(color: Color(red: 0.663, green: 0.682, blue: 0.714), location: 1)])
        for far in [false, true] {
            inner.fill(Path(slice(far ? length - 16 : 0, 16)), with: .linearGradient(cap, startPoint: start, endPoint: end))
            inner.fill(Path(slice(far ? length - 17 : 16, 1)), with: .color(Color.black.opacity(0.38)))
            inner.fill(Path(slice(far ? length - 18 : 17, 0.8)), with: .color(Color.white.opacity(0.5)))
        }
        for part in [CGFloat(0.25), 0.75] {
            inner.fill(Path(slice(length * part - 0.7, 1.4)), with: .color(Color.black.opacity(0.4)))
            inner.fill(Path(slice(length * part + 0.7, 0.8)), with: .color(Color.white.opacity(0.5)))
        }
        context.stroke(round, with: .color(Color.black.opacity(0.35)), lineWidth: 0.8)
    }
}

/// The lamps that are lit, over where the body shows them unlit: each a
/// bright dot in its own glow. (The rest are the body's.)
private struct ClamLamps: View, Equatable {
    var rows: [String]
    var columns: Int
    var lines: Int
    var pitch: CGFloat
    var glow: Color
    var body: some View {
        Canvas { context, size in
            let wide = rows.first?.count ?? 0
            guard wide > 0 else { return }
            let left = (columns - wide) / 2, top = (lines - rows.count) / 2
            let middle = CGPoint(x: size.width / 2, y: size.height / 2)
            for (j, row) in rows.enumerated() {
                for (i, mark) in row.enumerated() where mark == "#" {
                    let x = middle.x + (CGFloat(left + i) - CGFloat(columns - 1) / 2) * pitch
                    let y = middle.y + (CGFloat(top + j) - CGFloat(lines - 1) / 2) * pitch
                    context.fill(Path(ellipseIn: CGRect(x: x - 6, y: y - 6, width: 12, height: 12)),
                                 with: .radialGradient(Gradient(colors: [glow.opacity(0.6), glow.opacity(0)]), center: CGPoint(x: x, y: y), startRadius: 1, endRadius: 6))
                    context.fill(Path(ellipseIn: CGRect(x: x - 2.1, y: y - 2.1, width: 4.2, height: 4.2)), with: .color(glow))
                    context.fill(Path(ellipseIn: CGRect(x: x - 1.3, y: y - 1.3, width: 2.6, height: 2.6)), with: .color(Color(red: 1.0, green: 0.992, blue: 0.965)))
                }
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The direction ring's face: a bright-metal rim round a satin oval, the
/// groove the middle key sits in. Drawn once.
private struct ClamRingFace: View, Equatable {
    var rx: CGFloat
    var ry: CGFloat
    var groove: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2)
            func oval(_ inset: CGFloat) -> Path {
                Path(ellipseIn: CGRect(x: c.x - rx + inset, y: c.y - ry + inset, width: 2 * (rx - inset), height: 2 * (ry - inset)))
            }
            var shade = context
            shade.addFilter(.shadow(color: Color.black.opacity(0.45), radius: 2.5, x: 0, y: 2))
            shade.fill(oval(0), with: .linearGradient(ClamPaint.chrome, startPoint: CGPoint(x: c.x - rx, y: c.y - ry), endPoint: CGPoint(x: c.x + rx, y: c.y + ry)))
            context.stroke(oval(0.7), with: .color(Color.white.opacity(0.85)), lineWidth: 0.9)
            let satin = Gradient(stops: [Gradient.Stop(color: Color.white, location: 0), Gradient.Stop(color: Color(red: 0.914, green: 0.922, blue: 0.937), location: 0.45),
                                         Gradient.Stop(color: Color(red: 0.737, green: 0.757, blue: 0.792), location: 1)])
            context.fill(oval(4.2), with: .radialGradient(satin, center: CGPoint(x: c.x - rx * 0.25, y: c.y - ry * 0.55), startRadius: 3, endRadius: rx * 1.25))
            context.stroke(oval(4.2), with: .color(Color.black.opacity(0.28)), lineWidth: 0.8)
            let pit = CGRect(x: c.x - groove, y: c.y - groove, width: 2 * groove, height: 2 * groove)
            context.fill(Path(ellipseIn: pit), with: .linearGradient(Gradient(colors: [Color(red: 0.435, green: 0.459, blue: 0.498), Color(red: 0.627, green: 0.651, blue: 0.686),
                                                                                       Color(red: 0.835, green: 0.847, blue: 0.867)]),
                                                                     startPoint: CGPoint(x: 0, y: pit.minY), endPoint: CGPoint(x: 0, y: pit.maxY)))
            context.stroke(Path(ellipseIn: pit), with: .color(Color.white.opacity(0.7)), lineWidth: 0.8)
        }
    }
}

/// Where the direction ring is touched: the ring itself, a little into the
/// gap round it; and, where a side's word is printed beside the ring, a
/// strip out over that word.
private struct ClamRingTouch: Shape {
    var rx: CGFloat
    var ry: CGFloat
    var out: CGSize
    var arm: CGSize
    func path(in rect: CGRect) -> Path {
        var path = Path(ellipseIn: CGRect(x: rect.midX - rx - 3, y: rect.midY - ry - 3, width: 2 * (rx + 3), height: 2 * (ry + 3)))
        if out.height > 0 {
            path = path.union(Path(CGRect(x: rect.midX - arm.width / 2, y: rect.midY - ry - out.height, width: arm.width, height: 2 * (ry + out.height))))
        }
        if out.width > 0 {
            path = path.union(Path(CGRect(x: rect.midX - rx - out.width, y: rect.midY - arm.height / 2, width: 2 * (rx + out.width), height: arm.height)))
        }
        return path
    }
}

/// The phone's direction ring: it gives toward the side pressed, with the
/// soft key's sound, and does that side's work when the finger leaves it.
/// (The key in its middle is a key of its own, laid over it.)
private struct ClamRing: View {
    var paint: ClamPaint
    var rx: CGFloat
    var ry: CGFloat
    /// Arrows on all four sides (moving among pictures); else the camera's:
    /// 变焦 ＋ over the middle and − under it (a magnifying glass more and
    /// less), 镜头 ‹ and › at its sides (the filters' circles, an arrow
    /// before or after them).
    var arrows = false
    /// How far out the signs stand, at the sides and up and down, and how
    /// large the camera's are.
    var signs: CGSize
    var signSize: CGFloat = 16
    /// How far past the ring each side is touched too, and how wide there
    /// (ClamLayout.ringOut, ringArm).
    var out = CGSize.zero
    var arm = CGSize(width: 56, height: 44)
    /// What each side does as VoiceOver says it (up, right, down, left).
    var names: [String]
    /// 0 up, 1 right, 2 down, 3 left.
    var press: (Int) -> Void
    @State private var side: Int? = nil

    /// Half the ring's place: its half-axes with the room round it.
    private var half: CGSize {
        CGSize(width: rx + max(ClamLayout.ringRoom, out.width), height: ry + max(ClamLayout.ringRoom, out.height))
    }
    private func quarter(at point: CGPoint) -> Int {
        let dx = (point.x - half.width) / max(1, rx), dy = (point.y - half.height) / max(1, ry)
        if abs(dx) > abs(dy) { return dx > 0 ? 1 : 3 }
        return dy < 0 ? 0 : 2
    }
    private func said(_ index: Int) -> String { names.indices.contains(index) ? names[index] : "" }
    private func spot(_ way: Int, _ out: CGSize) -> CGSize {
        switch way {
        case 0: return CGSize(width: 0, height: -out.height)
        case 1: return CGSize(width: out.width, height: 0)
        case 2: return CGSize(width: 0, height: out.height)
        default: return CGSize(width: -out.width, height: 0)
        }
    }
    private var lean: CGSize {
        guard let side else { return .zero }
        let far = spot(side, CGSize(width: 1.4, height: 1.4))
        return far
    }

    var body: some View {
        ZStack {
            Ellipse().fill(Color.black.opacity(0.36)).frame(width: 2 * rx + 5, height: 2 * ry + 6).offset(y: 1)
            ZStack {
                ClamRingFace(rx: rx, ry: ry, groove: 28).equatable()
                if let side { shade(side).frame(width: 2 * rx - 8.4, height: 2 * ry - 8.4) }
                legends
            }
            .offset(lean)
            .animation(.easeOut(duration: 0.06), value: side)
            .allowsHitTesting(false)
        }
        .frame(width: 2 * half.width, height: 2 * half.height)
        .contentShape(ClamRingTouch(rx: rx, ry: ry, out: out, arm: arm))
        .gesture(DragGesture(minimumDistance: 0)
            .onChanged { value in
                let now = quarter(at: value.location)
                guard now != side else { return }
                side = now
                ConsoleSounds.shared.play(.phoneSoft, scale: 0.6)
                ConsoleHaptics.shared.play(.dpad, .press)
            }
            .onEnded { _ in
                if let side { press(side) }
                side = nil
            })
        .accessibilityElement()
        .accessibilityLabel(String(localized: "方向键"))
        .accessibilityAction(named: Text(said(0))) { press(0) }
        .accessibilityAction(named: Text(said(1))) { press(1) }
        .accessibilityAction(named: Text(said(2))) { press(2) }
        .accessibilityAction(named: Text(said(3))) { press(3) }
    }

    /// The shade on the side that is down.
    private func shade(_ side: Int) -> some View {
        let from: UnitPoint = side == 0 ? .top : side == 1 ? .trailing : side == 2 ? .bottom : .leading
        let to: UnitPoint = side == 0 ? .bottom : side == 1 ? .leading : side == 2 ? .top : .trailing
        return Ellipse().fill(LinearGradient(colors: [Color.black.opacity(0.22), Color.black.opacity(0)], startPoint: from, endPoint: to))
    }
    @ViewBuilder private var legends: some View {
        let ink = paint.ink
        if arrows {
            ForEach(0..<4, id: \.self) { way in
                ClamArrow(way: way).fill(ink)
                    .frame(width: way % 2 == 0 ? 12 : 10, height: way % 2 == 0 ? 10 : 12)
                    .offset(spot(way, signs))
            }
        } else {
            ShellGlyphView(glyph: .zoomIn, size: signSize, ink: ink).offset(y: -signs.height)
            ShellGlyphView(glyph: .zoomOut, size: signSize, ink: ink).offset(y: signs.height)
            ShellGlyphView(glyph: .lensPrevious, size: signSize, ink: ink).offset(x: -signs.width)
            ShellGlyphView(glyph: .lensNext, size: signSize, ink: ink).offset(x: signs.width)
        }
    }
}

/// The signal's four bars and the battery, as the phone's screen draws them.
private struct ClamSignal: View {
    var body: some View {
        HStack(alignment: .bottom, spacing: 1.4) {
            ForEach(0..<4, id: \.self) { step in
                Rectangle().frame(width: 2.6, height: 2 + CGFloat(step) * 2.6)
            }
        }
    }
}
private struct ClamBattery: View {
    var body: some View {
        HStack(spacing: 0.5) {
            RoundedRectangle(cornerRadius: 2).stroke(lineWidth: 1.3).frame(width: 17, height: 9)
                .overlay(alignment: .leading) { Rectangle().frame(width: 8, height: 5).padding(.leading, 2) }
            Rectangle().frame(width: 2, height: 4)
        }
    }
}

/// The two bars on the phone's screen. Along the top: the signal, a note
/// (the self-timer where it is set; 图库), the middle (the picture's shape;
/// in 图库 which picture of how many, read by VoiceOver), the battery.
/// Along the bottom: what the two soft keys are (their glyphs; none where
/// one has nothing to do), and between them the lens with an arrow at each
/// side, or what the ring does.
private struct ClamBars: View {
    var paint: ClamPaint
    var note: String
    var middle: String
    /// The middle is the album's place (told to VoiceOver and the tests).
    var counts = false
    var left: ClamGlyph? = nil
    /// One word, or two with an arrow outside each.
    var centre: [String]
    var arrows = false
    var right: ClamGlyph? = nil
    var body: some View {
        VStack(spacing: 0) {
            status.frame(height: 20).background(paint.bar)
            Spacer(minLength: 0)
            keys.frame(height: 24).background(paint.bar)
        }
        .foregroundStyle(Color.white)
        .clipShape(RoundedRectangle(cornerRadius: 5, style: .continuous))
        .allowsHitTesting(false)
    }
    private var status: some View {
        ZStack {
            HStack(spacing: 8) {
                ClamSignal().offset(y: -3)
                Text(note).lineLimit(1).minimumScaleFactor(0.7)
                Spacer(minLength: 0)
                ClamBattery()
            }
            .padding(.leading, 9)
            .padding(.trailing, 10)
            .accessibilityHidden(true)
            Text(middle).monospacedDigit().lineLimit(1)
                .accessibilityHidden(!counts)
                .accessibilityIdentifier(counts ? "camera-deck-album-position" : "")
        }
        .font(.system(size: 10.5, weight: .heavy, design: .rounded))
    }
    private var keys: some View {
        ZStack {
            HStack {
                if let left { softKey(left) }
                Spacer(minLength: 4)
                if let right { softKey(right) }
            }
            .padding(.horizontal, 11)
            HStack(spacing: 14) {
                ForEach(centre.indices, id: \.self) { index in
                    HStack(spacing: 4) {
                        if arrows, index == 0 { ClamArrow(way: 3).frame(width: 5, height: 6) }
                        Text(centre[index]).lineLimit(1).minimumScaleFactor(0.6)
                        if arrows, index == centre.count - 1 { ClamArrow(way: 1).frame(width: 5, height: 6) }
                    }
                }
            }
            .font(.system(size: 11, weight: .heavy, design: .rounded))
            .frame(maxWidth: 190)
        }
        .lineLimit(1)
        .accessibilityHidden(true)
    }
    /// What a soft key is, drawn white on the bar (换机型 no smaller than it
    /// can be drawn).
    private func softKey(_ glyph: ClamGlyph) -> some View {
        let size: CGFloat = glyph == ClamGlyph.cover(.changeBody) ? 18 : 15
        return ClamGlyphView(glyph: glyph, size: size, ink: Color.white)
    }
}

/// ZERO, printed on the body.
private struct ClamName: View {
    var paint: ClamPaint
    var size: CGFloat
    var leading = false
    var body: some View {
        Text(verbatim: "ZERO").font(.system(size: size, weight: .black, design: .rounded)).tracking(6)
            .foregroundStyle(paint.legend)
            .shadow(color: Color.white.opacity(paint.dark ? 0 : 0.6), radius: 0, y: 0.8)
            .lineLimit(1).fixedSize()
            .frame(maxWidth: .infinity, alignment: leading ? .leading : .center)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

/// What is on a key wrapped round the ring, in the part of the key that is
/// clear of the ring: a soft key's short bar over its glyph; on the green
/// key and the red their glyph alone, white (回去拍照's with its words
/// under it, kept).
private struct ClamWingLabel: View {
    var glyph: ClamGlyph?
    /// Words kept with a cover key's glyph (回去拍照).
    var words: String? = nil
    /// A soft key: its short bar over the glyph.
    var soft = true
    var ink: Color
    /// The cover held across: the keys small, in their column.
    var compact = false
    var clear: CGFloat
    var mirror = false
    var body: some View {
        let keyTop: CGFloat = compact ? (words == nil ? 19 : 10) : 16
        let top: CGFloat = soft ? (compact ? 9 : 16) : keyTop
        content
            .padding(.horizontal, 3)
            .frame(width: max(0, clear))
            .padding(.top, top)
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: mirror ? .topTrailing : .topLeading)
    }
    /// The cover key's glyph its words go with.
    private var named: ShellGlyph? {
        if case .cover(let shell)? = glyph { return shell }
        return nil
    }
    @ViewBuilder private var content: some View {
        if soft {
            VStack(spacing: compact ? 6 : 8) {
                Capsule().frame(width: compact ? 18 : 24, height: compact ? 3 : 3.6)
                if let glyph { ClamGlyphView(glyph: glyph, size: compact ? 18 : 20, ink: ink) }
            }
        } else if let words, let shell = named {
            ShellGlyphLabel(glyph: shell, words: words, size: compact ? 13 : 18, wordSize: compact ? 11 : 13, ink: ink, stacked: true)
        } else if let glyph {
            ClamGlyphView(glyph: glyph, size: compact ? 18 : 22, ink: ink)
                .frame(height: compact ? 18 : 38)
        }
    }
}

/// One of the four keys round the ring, as a key.
private struct ClamWingKey: View {
    var clam: ClamLayout
    var paint: ClamPaint
    var low = false
    var mirror = false
    var glyph: ClamGlyph? = nil
    /// Words kept with its glyph (回去拍照).
    var words: String? = nil
    /// The green key's colour or the red key's (what is on it white).
    var tone: ShellTone? = nil
    var identifier: String
    var label: String
    var value: String = ""
    var selected = false
    var action: () -> Void
    var body: some View {
        Button(action: action) {
            ClamWingLabel(glyph: glyph, words: words, soft: tone == nil, ink: tone == nil ? paint.ink : Color.white, compact: clam.across, clear: clam.wingClear,
                          mirror: mirror)
        }
        .buttonStyle(ClamWingStyle(paint: paint, wing: clam.wingShape(low: low, mirror: mirror), tone: tone, gloss: tone == nil ? 1 : 0.5, ink: tone == nil ? nil : Color.white))
        .accessibilityLabel(label)
        .accessibilityValue(value)
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
}

/// What is on one of the twelve: its sign large and, small beside it, what
/// it sets, drawn as it stands (曝光's value after its − or ＋ where that
/// is not ±0); held across the sign over the drawing.
private struct ClamDigitLabel: View {
    var mark: String
    var glyph: ClamGlyph
    var figures: String = ""
    var paint: ClamPaint
    var stacked = false
    var u: CGFloat = 1
    var body: some View {
        if stacked {
            VStack(spacing: 1) {
                Text(verbatim: mark).font(.system(size: 16.5, weight: .heavy, design: .rounded))
                ClamGlyphView(glyph: glyph, size: 15, ink: paint.soft)
            }
            .padding(.horizontal, 2)
        } else {
            HStack(spacing: 0) {
                Text(verbatim: mark).font(.system(size: 20, weight: .heavy, design: .rounded)).frame(width: 36 * u).padding(.leading, 4 * u)
                Rectangle().fill(paint.key.color(-0.16)).frame(width: 1).padding(.vertical, 11)
                HStack(spacing: 4) {
                    ClamGlyphView(glyph: glyph, size: 18, ink: paint.soft)
                    if !figures.isEmpty {
                        Text(verbatim: figures).font(.system(size: 10, weight: .heavy, design: .rounded)).monospacedDigit()
                            .lineLimit(1).minimumScaleFactor(0.6)
                            .foregroundStyle(paint.accent)
                    }
                }
                .padding(.leading, 8 * u)
                Spacer(minLength: 2)
            }
        }
    }
}

/// What the key in the ring's middle shows: its glyph, pressed into the
/// metal (none while it has nothing to do).
private struct ClamHubLabel: View {
    var glyph: ClamGlyph?
    var ink: Color
    var body: some View {
        if let glyph {
            ClamGlyphView(glyph: glyph, size: 18, ink: ink)
                .shadow(color: Color.white.opacity(0.7), radius: 0, y: 0.8)
        }
    }
}

/// What the side key shows: a camera — for a video a red dot, the square
/// and the time while one is taken (one over the other, or side by side
/// where the key lies along the band).
private struct ClamSideLabel: View {
    var paint: ClamPaint
    var across = false
    /// The time while a video is taken (none: the mark alone).
    var figures = ""
    var video = false
    var recording = false
    var ready = true
    var body: some View {
        let stack = across ? AnyLayout(HStackLayout(spacing: 7)) : AnyLayout(VStackLayout(spacing: 5))
        stack {
            mark.frame(width: 24, height: 20)
            if !figures.isEmpty {
                Text(verbatim: figures).font(.system(size: across ? 12 : 11.5, weight: .black, design: .rounded)).monospacedDigit().lineLimit(1).minimumScaleFactor(0.6)
            }
        }
        .foregroundStyle(paint.ink)
        .opacity(ready || video ? 1 : 0.45)
        .padding(.horizontal, 5)
    }
    @ViewBuilder private var mark: some View {
        if video {
            if recording {
                RoundedRectangle(cornerRadius: 2.5, style: .continuous).fill(CameraShutterFace.red).frame(width: 13, height: 13)
            } else {
                Circle().fill(CameraShutterFace.red).frame(width: 15, height: 15)
            }
        } else {
            ShellGlyphView(glyph: .photo(true), size: 18, ink: paint.ink)
        }
    }
}

extension CameraDeckFace {
    /// The colour the phone is worn in.
    var clamPaint: ClamPaint { ClamPaint.named(model.shellTints[CameraShellSkin.phone.rawValue]) }

    /// The clamshell phone's body under its keys (a new colour fades in).
    func clamBackdrop(_ clam: ClamLayout) -> some View {
        let paint = clamPaint
        return ClamBackdrop(layout: clam, paint: paint, hinge: hinge).equatable()
            .id(paint.name)
            .transition(.opacity)
    }

    /// What the screen's top bar says after the signal: a video's time while
    /// one is taken; else the self-timer where it is set (the seconds left
    /// while it counts).
    private var clamNote: String {
        if model.mode == .video {
            let video = String(localized: "录像")
            return model.recording ? video + " " + CameraAppModel.clock(model.recordedSeconds) : video
        }
        if let left = model.countdown {
            let seconds = String(localized: "\(left) 秒")
            return String(localized: "定时 \(seconds)")
        }
        return model.timer == .off ? "" : String(localized: "定时 \(model.timer.title)")
    }

    /// The phone's screen over the picture: the glass's edge with the hinge's
    /// barrel, the status along the top, and along the bottom what the two
    /// soft keys are (their glyphs: 换机型, 相册) with the lens's name between
    /// them (the ring's sides change it).
    @ViewBuilder func clamScreen(_ clam: ClamLayout) -> some View {
        let paint = clamPaint
        ClamLid(glass: clam.glass, radius: clam.glassRadius, hole: layout.picture, slit: !clam.across, barrel: clam.barrel, paint: paint).equatable()
            .id(paint.name)
            .transition(.opacity)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        ClamBars(paint: paint, note: clamNote, middle: model.shape.title, left: .cover(.changeBody), centre: [model.lens.title], arrows: true,
                 right: .cover(.album))
            .accessibilityHidden(true)
            .deckPlaced(clam.screen)
    }

    /// The clamshell phone, upright or across (the same keys, each where its
    /// hold has it): the two soft keys (换机型, 相册), the green key (录像,
    /// or back to 拍照) and the red (功能表: a house) wrapped round the
    /// direction ring — up and down the zoom, its sides the lens, its middle
    /// takes the picture — the twelve keys (each figure kept, what it sets
    /// drawn by it), the key on the side that takes the picture too, the
    /// lamps under the grip's surface, ZERO and the dot that changes the colour.
    @ViewBuilder func clamFace(_ clam: ClamLayout) -> some View {
        let paint = clamPaint
        if clam.name.width > 0 {
            ClamName(paint: paint, size: clam.across ? 15 : 12.5, leading: clam.across).deckPlaced(clam.name)
        }
        clamLamps(clam, paint)
        clamSoftKeys(clam, paint)
        clamRing(clam, paint)
        clamDigits(clam, paint)
        clamSide(clam, paint)
        clamTint(clam)
    }

    /// The lamps: the self-timer's count while it runs, a disc while a video is taken.
    @ViewBuilder private func clamLamps(_ clam: ClamLayout, _ paint: ClamPaint) -> some View {
        if clam.lampColumns > 0 {
            let rows: [String] = model.countdown.map { ClamDots.number($0, columns: clam.lampColumns) } ?? (model.recording ? ClamDots.disc : [])
            if !rows.isEmpty {
                ClamLamps(rows: rows, columns: clam.lampColumns, lines: clam.lampRows, pitch: clam.lampPitch, glow: paint.glow).equatable()
                    .deckPlaced(clam.lamps)
            }
        }
    }

    @ViewBuilder private func clamSoftKeys(_ clam: ClamLayout, _ paint: ClamPaint) -> some View {
        let video = model.mode == .video
        let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
        // (The green key shows what it turns to: a video camera, or back to the camera.)
        let turnTo: ShellGlyph = video ? .photo(true) : .video(true)
        ClamWingKey(clam: clam, paint: paint, glyph: .cover(.changeBody), identifier: "camera-deck-bodies", label: String(localized: "切换机型"), selected: model.bodiesOpen) {
            if model.bodiesOpen { model.closeBodies() } else { model.openBodies() }
        }
        .deckPlaced(clam.wingRect(low: false, mirror: false))
        ClamWingKey(clam: clam, paint: paint, mirror: true, glyph: .cover(.album), identifier: "camera-deck-album", label: CameraShellSkin.phone.albumTitle,
                    value: String(localized: "\(model.photos.count) 张")) {
            model.openAlbum()
        }
        .deckPlaced(clam.wingRect(low: false, mirror: true))
        ClamWingKey(clam: clam, paint: paint, low: true, glyph: .cover(turnTo), tone: ClamPaint.green,
                    identifier: "camera-deck-mode", label: photoWord + " / " + videoWord, value: video ? videoWord : photoWord) {
            model.setMode(model.mode == .video ? .photo : .video)
        }
        .deckPlaced(clam.wingRect(low: true, mirror: false))
        ClamWingKey(clam: clam, paint: paint, low: true, mirror: true, glyph: .cover(.home), tone: ClamPaint.red,
                    identifier: "camera-deck-home", label: String(localized: "功能表")) {
            model.leave()
        }
        .deckPlaced(clam.wingRect(low: true, mirror: true))
    }

    @ViewBuilder private func clamRing(_ clam: ClamLayout, _ paint: ClamPaint) -> some View {
        let zoom = String(localized: "变焦"), lens = String(localized: "镜头")
        // (Where the ring is wide enough the four glyphs stand between where its
        // signs and its words were; held across, where its signs were.)
        let wide = !clam.across && clam.rx >= 64
        let between = CGSize(width: (clam.signs.width + clam.wordsAt.width) / 2, height: (clam.signs.height + clam.wordsAt.height) / 2)
        let spots: CGSize = wide ? between : clam.signs
        let names: [String] = [zoom + " +", lens + " ›", zoom + " −", lens + " ‹"]
        ClamRing(paint: paint, rx: clam.rx, ry: clam.ry, signs: spots, signSize: wide ? 17 : 13, out: clam.ringOut, arm: clam.ringArm,
                 names: names, press: { phoneNavigate($0) })
            .deckPlaced(clam.ringFrame)
        // (Its middle: a camera; for a video the dot, the square while one is taken.)
        let hubSign: ShellGlyph = model.mode == .video ? (model.recording ? .stop : .record) : .photo(true)
        Button { model.shutter() } label: { ClamHubLabel(glyph: .cover(hubSign), ink: paint.ink) }
            .buttonStyle(ClamHubStyle(paint: paint))
            .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
            .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
            .accessibilityIdentifier("camera-deck-shutter-centre")
            .deckKey(clam.hub)
    }

    /// The twelve keys, each figure kept and what it sets drawn by it, as it
    /// stands (曝光's value by its − and ＋ where that is not ±0, upright);
    /// each sounds its own pair of tones.
    @ViewBuilder private func clamDigits(_ clam: ClamLayout, _ paint: ClamPaint) -> some View {
        let shooting = model.shooting
        let on = String(localized: "开"), off = String(localized: "关")
        let inner = model.side == .inner, sideWord = inner ? String(localized: "内侧") : String(localized: "外侧")
        let timer = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
        let legends = ClamKeys.legends(shape: CameraShellSkin.phone.shapeTitle)
        // (What VoiceOver calls each, and how it stands.)
        let names: [String] = [legends[0], legends[1], legends[2], legends[3], legends[4], legends[5], legends[6], legends[7], legends[8], legends[9], sideWord, legends[11]]
        let values: [String] = [shooting.flash.title, shooting.whiteBalance.title, shooting.iso.title,
                                shooting.exposureTitle, shooting.dateStamp ? on : off, shooting.exposureTitle,
                                "", model.shape.title, "",
                                timer, "", model.leveler ? on : off]
        // (What is drawn by each figure.)
        let glyphs = clamGlyphs(shooting, timer: model.timer, shape: model.shape, leveler: model.leveler)
        let exposed: String = shooting.exposure == 0 || clam.across ? "" : shooting.exposureTitle
        ForEach(0..<12, id: \.self) { index in
            let figures: String = index == 3 || index == 5 ? exposed : ""
            Button { phoneKey(index) } label: {
                ClamDigitLabel(mark: ClamKeys.marks[index], glyph: glyphs[index], figures: figures, paint: paint, stacked: clam.across, u: clam.u)
            }
            .buttonStyle(ClamKeyStyle(paint: paint, sound: ClamKeys.tones[index]))
            .accessibilityLabel(names[index])
            .accessibilityValue(values[index])
            .accessibilityIdentifier(ClamKeys.identifiers[index])
            .deckDimmed(index == 7 ? !model.canShape : index == 10 && model.lens == .merge,
                        why: index == 7 ? String(localized: "这个模式或机型只拍 4:3") : String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(clam.digitRect(index))
        }
    }

    /// The key on the phone's side: 拍照, a camera (what the deck's own key
    /// shows for a video, and the time while one is taken).
    private func clamSide(_ clam: ClamLayout, _ paint: ClamPaint) -> some View {
        let video = model.mode == .video
        let figures: String = video && model.recording ? CameraAppModel.clock(model.recordedSeconds) : ""
        return Button { model.shutter() } label: {
            ClamSideLabel(paint: paint, across: clam.across, figures: figures, video: video, recording: model.recording, ready: model.canShoot)
        }
        .buttonStyle(ClamSideStyle(radius: clam.sideRadius))
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
        .deckKey(clam.side)
    }

    /// The dot beside ZERO: the phone's next colour.
    @ViewBuilder private func clamTint(_ clam: ClamLayout) -> some View {
        if clam.chip.width > 0, let now = model.tint(of: .phone), let next = model.nextTint(of: .phone) {
            ShellTintKey(now: now, next: next, sound: .phoneSoft) {
                withAnimation(.easeInOut(duration: 0.2)) { model.cycleTint(of: .phone) }
            }
            .deckKey(clam.chip)
        }
    }

    /// The clamshell phone's 图库, upright and across.
    @ViewBuilder func clamAlbum(_ clam: ClamLayout) -> some View {
        ClamGallery(model: model, thumbnails: thumbnails, clam: clam, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The clamshell phone's album: 图库

/// The clamshell phone's 图库: the same phone, on its screen a page of
/// twelve small pictures, the chosen one a little larger in a white edge.
/// The ring moves among them; its middle, 查看 or a touch opens one whole
/// (a video's plays there; a push to the side goes to the next); 返回 goes
/// back a step — from the picture to the page, from the page to the camera.
/// The green key (回去拍照, its words kept) and the side key go back to the
/// camera too. ＊ and # turn the page; the other ten wait for the camera.
/// Each key shows its glyph, as the camera's do.
private struct ClamGallery: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var clam: ClamLayout
    var hinge: CGRect
    @State private var whole = false
    @State private var push: CGFloat = 0

    /// Four across on the wide screen of the cover held across.
    private var columns: Int { clam.across ? 4 : 3 }
    private static let page = 12
    /// A video is open whole (the ring's middle and the left soft key play it).
    private var video: Bool { whole && model.albumPhoto?.isVideo == true }
    /// A picture is open whole, or there is none: the left soft key and the
    /// ring's middle have nothing to do.
    private var idle: Bool { model.photos.isEmpty || (whole && !video) }
    /// What those two are called: 查看 on the page; with a video open, 播放
    /// or 停止; with a picture open, nothing.
    private var word: String {
        if !whole { return String(localized: "查看") }
        if video { return model.playing == nil ? String(localized: "播放") : String(localized: "停止") }
        return ""
    }
    /// What they show: the magnifying glass more (查看), ▶ or the square;
    /// with a picture open, nothing.
    private var sign: ClamGlyph? {
        if !whole { return ClamGlyph.cover(.zoomIn) }
        guard video else { return nil }
        let shown: ShellGlyph = model.playing == nil ? .play : .stop
        return ClamGlyph.cover(shown)
    }

    private func choose(_ next: Int) {
        guard model.photos.indices.contains(next), next != model.albumIndex, model.doodle == nil else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }
    private func navigate(_ side: Int) {
        let at = model.albumIndex
        switch side {
        case 0: choose(at - (whole ? 1 : columns))
        case 2: choose(at + (whole ? 1 : columns))
        case 1: choose(at + 1)
        default: choose(at - 1)
        }
    }
    private func turn(_ pages: Int) {
        choose(min(model.photos.count - 1, max(0, model.albumIndex + pages * Self.page)))
    }
    private func shut() {
        if model.playing != nil { model.togglePlay() }
        whole = false
    }
    /// 查看, the ring's middle: the chosen picture whole; a video open plays or stops.
    private func look() {
        if video { model.togglePlay() } else if !whole, !model.photos.isEmpty { whole = true }
    }

    var body: some View {
        let paint = ClamPaint.named(model.shellTints[CameraShellSkin.phone.rawValue])
        ZStack(alignment: .topLeading) {
            ClamBackdrop(layout: clam, paint: paint, hinge: hinge).equatable()
                .id(paint.name)
                .transition(.opacity)
            screen
            ClamLid(glass: clam.glass, radius: clam.glassRadius, hole: clam.screen, slit: !clam.across, barrel: clam.barrel, paint: paint).equatable()
                .id(paint.name)
                .transition(.opacity)
            bars(paint)
            if clam.name.width > 0 {
                ClamName(paint: paint, size: clam.across ? 15 : 12.5, leading: clam.across).deckPlaced(clam.name)
            }
            softKeys(paint)
            ring(paint)
            digits(paint)
            sideKey(paint)
            tintKey
        }
    }

    /// What the phone's screen shows: the page of twelve, or one picture whole.
    private var screen: some View {
        let photos = model.photos, at = model.albumIndex
        return ZStack {
            Color(red: 0.063, green: 0.071, blue: 0.102)
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
            } else if whole, photos.indices.contains(at) {
                picture(photos[at], at: at)
            } else {
                page(photos, at: at)
            }
        }
        .frame(width: clam.screen.width, height: clam.screen.height)
        .clipShape(RoundedRectangle(cornerRadius: 5, style: .continuous))
        .position(x: clam.screen.midX, y: clam.screen.midY)
    }

    private func picture(_ photo: CameraPhoto, at: Int) -> some View {
        let sharp: CGImage? = (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
        return ZStack {
            if let sharp { Image(decorative: sharp, scale: 1).resizable().scaledToFit() }
            if photo.isVideo {
                #if os(iOS)
                if model.playing == photo.url {
                    CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                        .accessibilityIdentifier("camera-album-player")
                }
                #endif
                if model.playing != photo.url {
                    Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9))
                        .shadow(color: .black.opacity(0.5), radius: 4)
                }
            }
        }
        .frame(width: clam.screen.width, height: clam.screen.height)
        .offset(x: push)
        .contentShape(Rectangle())
        .gesture(DragGesture(minimumDistance: 8)
            .onChanged { push = $0.translation.width }
            .onEnded { value in
                let dx = value.translation.width
                withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                if abs(dx) > 60 { choose(at + (dx < 0 ? 1 : -1)) }
            })
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : String(localized: "图库"))
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    /// The page the chosen picture is on: twelve to a page, a status bar's
    /// height kept clear above them and a soft-key bar's below.
    private func page(_ photos: [CameraPhoto], at: Int) -> some View {
        let rows = Self.page / columns, first = (at / Self.page) * Self.page
        let w = (clam.screen.width - 16 - CGFloat(columns - 1) * 6) / CGFloat(columns)
        let h = (clam.screen.height - 54 - CGFloat(rows - 1) * 5) / CGFloat(rows)
        let size = CGSize(width: max(1, w), height: max(1, h))
        return ZStack(alignment: .topLeading) {
            ForEach(0..<Self.page, id: \.self) { slot in
                if photos.indices.contains(first + slot) {
                    cell(photos[first + slot], slot: slot, index: first + slot, chosen: first + slot == at, size: size)
                }
            }
        }
        .frame(width: clam.screen.width, height: clam.screen.height, alignment: .topLeading)
    }
    private func cell(_ photo: CameraPhoto, slot: Int, index: Int, chosen: Bool, size: CGSize) -> some View {
        let column = slot % columns, row = slot / columns
        let grown: CGFloat = chosen ? 1.17 : 1
        // (The chosen one at the page's side keeps inside it.)
        let nudge: CGFloat = !chosen ? 0 : column == 0 ? 5 : column == columns - 1 ? -5 : 0
        let x = 8 + size.width / 2 + CGFloat(column) * (size.width + 6) + nudge
        let y = 25 + size.height / 2 + CGFloat(row) * (size.height + 5)
        let shape = RoundedRectangle(cornerRadius: 3, style: .continuous)
        return Button {
            if !chosen { model.chooseInAlbum(index, quiet: true) }
            whole = true
        } label: {
            ZStack(alignment: .bottomLeading) {
                Color(white: 0.14)
                if let image = thumbnails.images[photo.url] {
                    Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill())
                }
                if !chosen { Color(red: 0.031, green: 0.039, blue: 0.063).opacity(0.22) }
                if photo.isVideo {
                    Image(systemName: "video.fill").font(.system(size: 11, weight: .bold)).foregroundStyle(.white)
                        .shadow(color: .black.opacity(0.7), radius: 2).padding(4)
                }
            }
            .frame(width: size.width * grown, height: size.height * grown)
            .clipShape(shape)
            .background {
                if chosen {
                    RoundedRectangle(cornerRadius: 5, style: .continuous).fill(Color.white).padding(-3)
                        .shadow(color: Color.black.opacity(0.7), radius: 4.5, y: 3)
                }
            }
        }
        .buttonStyle(.plain)
        .zIndex(chosen ? 1 : 0)
        .position(x: x, y: y)
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityLabel(photo.name)
        .accessibilityAddTraits(chosen ? .isSelected : [])
        .accessibilityIdentifier("camera-deck-album-cell-\(slot)")
    }

    private func bars(_ paint: ClamPaint) -> some View {
        let photos = model.photos
        let place = photos.isEmpty ? "0" : "\(model.albumIndex + 1) / \(photos.count)"
        let centre: [String] = whole ? [String(localized: "上一张"), String(localized: "下一张")] : [String(localized: "方向键 移动")]
        return ClamBars(paint: paint, note: String(localized: "图库"), middle: place, counts: true, left: sign, centre: centre, arrows: whole, right: .back)
            .deckPlaced(clam.screen)
    }

    @ViewBuilder private func softKeys(_ paint: ClamPaint) -> some View {
        let said = word.isEmpty ? String(localized: "查看") : word
        let why = model.photos.isEmpty ? String(localized: "还没有照片") : String(localized: "已经在看这一张")
        ClamWingKey(clam: clam, paint: paint, glyph: sign, identifier: "camera-deck-album-view", label: said) { look() }
            .deckDimmed(idle, why: why)
            .deckPlaced(clam.wingRect(low: false, mirror: false))
        ClamWingKey(clam: clam, paint: paint, mirror: true, glyph: .back, identifier: "camera-deck-album-back", label: String(localized: "返回")) {
            if whole { shut() } else { model.closeAlbum() }
        }
        .deckPlaced(clam.wingRect(low: false, mirror: true))
        ClamWingKey(clam: clam, paint: paint, low: true, glyph: .cover(.returnToShooting), words: String(localized: "回去拍照"), tone: ClamPaint.green,
                    identifier: "camera-deck-album-close", label: String(localized: "回去拍照")) {
            model.closeAlbum()
        }
        .deckPlaced(clam.wingRect(low: true, mirror: false))
        ClamWingKey(clam: clam, paint: paint, low: true, mirror: true, glyph: .cover(.home), tone: ClamPaint.red,
                    identifier: "camera-deck-home", label: String(localized: "功能表")) {
            model.leave()
        }
        .deckPlaced(clam.wingRect(low: true, mirror: true))
    }

    @ViewBuilder private func ring(_ paint: ClamPaint) -> some View {
        let said = word.isEmpty ? String(localized: "查看") : word
        let why = model.photos.isEmpty ? String(localized: "还没有照片") : String(localized: "已经在看这一张")
        ClamRing(paint: paint, rx: clam.rx, ry: clam.ry, arrows: true, signs: clam.arrowsAt, out: clam.ringOut, arm: clam.ringArm,
                 names: [String(localized: "向上"), String(localized: "向右"), String(localized: "向下"), String(localized: "向左")], press: { navigate($0) })
            .deckPlaced(clam.ringFrame)
        Button { look() } label: { ClamHubLabel(glyph: sign, ink: paint.ink) }
            .buttonStyle(ClamHubStyle(paint: paint, haptic: .smallButton))
            .accessibilityLabel(said)
            .accessibilityIdentifier("camera-deck-album-centre")
            .deckDimmed(idle, why: why)
            .deckKey(clam.hub)
    }

    /// The twelve: ＊ turns back a page and # on (the nine with an arrow
    /// before or after them); the others set the camera (what they set
    /// drawn by them), and wait for it.
    @ViewBuilder private func digits(_ paint: ClamPaint) -> some View {
        let legends = ClamKeys.legends(shape: CameraShellSkin.phone.shapeTitle)
        let why = String(localized: "图库里用不了，回到相机再用")
        let back = String(localized: "上一页"), on = String(localized: "下一页")
        let glyphs = clamGlyphs(model.shooting, timer: model.timer, shape: model.shape, leveler: model.leveler)
        ForEach(0..<12, id: \.self) { index in
            let pages = index == 9 ? -1 : index == 11 ? 1 : 0
            let name: String = pages < 0 ? back : pages > 0 ? on : legends[index]
            let identifier: String = pages < 0 ? "camera-deck-album-page-back" : pages > 0 ? "camera-deck-album-page-on" : "camera-deck-album-key-\(index)"
            let glyph: ClamGlyph = pages == 0 ? glyphs[index] : .page(forward: pages > 0)
            Button {
                if pages != 0 { turn(pages) } else { ConsoleHaptics.shared.play(.sliderStop, .press) }
            } label: {
                ClamDigitLabel(mark: ClamKeys.marks[index], glyph: glyph, paint: paint, stacked: clam.across, u: clam.u)
            }
            .buttonStyle(ClamKeyStyle(paint: paint, sound: ClamKeys.tones[index]))
            .accessibilityLabel(name)
            .accessibilityIdentifier(identifier)
            .deckDimmed(pages == 0, why: why)
            .deckKey(clam.digitRect(index))
        }
    }

    /// The key on the side (a camera, as it is while taking pictures): back
    /// to taking pictures.
    private func sideKey(_ paint: ClamPaint) -> some View {
        Button { model.closeAlbum() } label: {
            ClamSideLabel(paint: paint, across: clam.across)
        }
        .buttonStyle(ClamSideStyle(radius: clam.sideRadius, haptic: .smallButton))
        .accessibilityLabel(String(localized: "回去拍照"))
        .accessibilityIdentifier("camera-deck-album-camera")
        .deckKey(clam.side)
    }

    @ViewBuilder private var tintKey: some View {
        if clam.chip.width > 0, let now = model.tint(of: .phone), let next = model.nextTint(of: .phone) {
            ShellTintKey(now: now, next: next, sound: .phoneSoft) {
                withAnimation(.easeInOut(duration: 0.2)) { model.cycleTint(of: .phone) }
            }
            .deckKey(clam.chip)
        }
    }
}

// MARK: - The toy camera's back

/// The toy camera's few plain colours, and the inks that read on them
/// (navy on the blue and on white, a deep red on yellow, a deep green on
/// green, a brown on orange).
enum ToyPaint {
    static let body = Color(red: 0.220, green: 0.690, blue: 0.894)
    static let deep = Color(red: 0.133, green: 0.557, blue: 0.776)
    static let light = Color(red: 0.471, green: 0.816, blue: 0.957)
    static let yellow = Color(red: 0.980, green: 0.816, blue: 0.188)
    static let yellowDeep = Color(red: 0.871, green: 0.659, blue: 0.078)
    static let yellowLight = Color(red: 1.0, green: 0.918, blue: 0.502)
    static let red = Color(red: 0.925, green: 0.259, blue: 0.180)
    static let redDeep = Color(red: 0.745, green: 0.157, blue: 0.118)
    static let green = Color(red: 0.282, green: 0.722, blue: 0.361)
    static let orange = Color(red: 0.973, green: 0.557, blue: 0.157)
    static let white = Color(red: 0.984, green: 0.980, blue: 0.965)
    static let ink = Color(red: 0.063, green: 0.243, blue: 0.408)
    static let redInk = Color(red: 0.690, green: 0.125, blue: 0.094)
    static let greenInk = Color(red: 0.031, green: 0.251, blue: 0.118)
    static let orangeInk = Color(red: 0.353, green: 0.141, blue: 0.0)
    static let softInk = Color(red: 0.318, green: 0.376, blue: 0.431)
    static let shade = Color(red: 0.0, green: 0.157, blue: 0.314)
    /// The stickers' grounds, by turns.
    static let stickers: [Color] = [red, Color(red: 0.259, green: 0.463, blue: 0.824), Color(red: 0.157, green: 0.588, blue: 0.275),
                                    Color(red: 0.886, green: 0.408, blue: 0.078), Color(red: 0.588, green: 0.376, blue: 0.800)]
}

/// A toy's key, thick plain plastic standing on its shadow: a block of one
/// colour (ribbed, or with a square pressed into it), a key moulded in the
/// body's own blue, or a yellow plate. Pressed, it goes down onto the shadow.
struct ToyKeyStyle: ButtonStyle {
    enum Make: Equatable { case block, moulded, plate }
    var make: Make = .block
    var color: Color = ToyPaint.white
    var ink: Color = ToyPaint.ink
    var radius: CGFloat = 13
    var ribs = false
    var inset = false
    var sound: ConsoleSound = .keyRubber
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View { ToyKeyBody(configuration: configuration, style: self) }
}
private struct ToyKeyBody: View {
    let configuration: ButtonStyle.Configuration
    let style: ToyKeyStyle
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .foregroundStyle(style.ink)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ToyKeyFace(style: style).brightness(down ? -0.06 : 0))
            .offset(y: down ? 3 : 0)
            .background(RoundedRectangle(cornerRadius: style.radius, style: .continuous).fill(ToyPaint.shade.opacity(0.4)).offset(y: 4))
            .contentShape(Rectangle())
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}
private struct ToyKeyFace: View {
    var style: ToyKeyStyle
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: style.radius, style: .continuous)
        ZStack {
            switch style.make {
            case .block:
                shape.fill(style.color)
                shape.fill(LinearGradient(stops: [.init(color: Color.white.opacity(0.34), location: 0), .init(color: Color.white.opacity(0), location: 0.42),
                                                  .init(color: Color.black.opacity(0.10), location: 1)], startPoint: .top, endPoint: .bottom))
                if style.ribs {
                    VStack(spacing: 4.5) {
                        ForEach(0..<4, id: \.self) { _ in
                            Capsule().fill(Color.black.opacity(0.2)).frame(height: 3)
                                .overlay(Capsule().fill(Color.white.opacity(0.45)).frame(height: 1.4).offset(y: 2.4))
                        }
                    }
                    .padding(.horizontal, 8)
                }
                if style.inset {
                    RoundedRectangle(cornerRadius: style.radius * 0.5, style: .continuous).strokeBorder(Color.black.opacity(0.16), lineWidth: 1.6).padding(11)
                }
                shape.strokeBorder(Color.black.opacity(0.2), lineWidth: 1.4)
            case .moulded:
                shape.fill(LinearGradient(colors: [ToyPaint.light, ToyPaint.body], startPoint: .top, endPoint: .bottom))
                shape.strokeBorder(ToyPaint.shade.opacity(0.35), lineWidth: 1.2)
                RoundedRectangle(cornerRadius: max(2, style.radius - 1.5), style: .continuous).strokeBorder(Color.white.opacity(0.55), lineWidth: 1.2).padding(1.5)
            case .plate:
                shape.fill(ToyPaint.yellow)
                shape.strokeBorder(ToyPaint.yellowDeep, lineWidth: 1.4)
                RoundedRectangle(cornerRadius: max(2, style.radius - 3), style: .continuous).strokeBorder(ToyPaint.yellowLight, lineWidth: 1.4).padding(3)
            }
        }
    }
}

/// Something of the toy's that is pressed whole (the knob, the window with
/// the last picture): down onto its shadow, with a key's click.
struct ToyPressStyle: ButtonStyle {
    var radius: CGFloat = 9
    var round = false
    func makeBody(configuration: Configuration) -> some View { ToyPressBody(configuration: configuration, style: self) }
}
private struct ToyPressBody: View {
    let configuration: ButtonStyle.Configuration
    let style: ToyPressStyle
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .brightness(down ? -0.05 : 0)
            .offset(y: down ? 3 : 0)
            .background(RoundedRectangle(cornerRadius: style.round ? 400 : style.radius, style: .continuous).fill(ToyPaint.shade.opacity(0.4)).offset(y: 4))
            .contentShape(Rectangle())
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.keyRubber, scale: 0.8)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// Points round a rounded rectangle, evenly apart, each with the way out of it.
private func toyWalk(_ rect: CGRect, radius r: CGFloat, step: CGFloat) -> [(at: CGPoint, out: CGVector)] {
    let sx = max(0, rect.width - 2 * r), sy = max(0, rect.height - 2 * r), arc = CGFloat.pi * r / 2
    let total = 2 * sx + 2 * sy + 4 * arc
    let count = max(1, Int((total / step).rounded()))
    var points: [(at: CGPoint, out: CGVector)] = []
    for i in 0..<count {
        var d = (CGFloat(i) + 0.5) * total / CGFloat(count)
        if d <= sx { points.append((CGPoint(x: rect.minX + r + d, y: rect.minY), CGVector(dx: 0, dy: -1))); continue }
        d -= sx
        if d <= arc {
            let a = -CGFloat.pi / 2 + d / r
            points.append((CGPoint(x: rect.maxX - r + cos(a) * r, y: rect.minY + r + sin(a) * r), CGVector(dx: cos(a), dy: sin(a)))); continue
        }
        d -= arc
        if d <= sy { points.append((CGPoint(x: rect.maxX, y: rect.minY + r + d), CGVector(dx: 1, dy: 0))); continue }
        d -= sy
        if d <= arc {
            let a = d / r
            points.append((CGPoint(x: rect.maxX - r + cos(a) * r, y: rect.maxY - r + sin(a) * r), CGVector(dx: cos(a), dy: sin(a)))); continue
        }
        d -= arc
        if d <= sx { points.append((CGPoint(x: rect.maxX - r - d, y: rect.maxY), CGVector(dx: 0, dy: 1))); continue }
        d -= sx
        if d <= arc {
            let a = CGFloat.pi / 2 + d / r
            points.append((CGPoint(x: rect.minX + r + cos(a) * r, y: rect.maxY - r + sin(a) * r), CGVector(dx: cos(a), dy: sin(a)))); continue
        }
        d -= arc
        if d <= sy { points.append((CGPoint(x: rect.minX, y: rect.maxY - r - d), CGVector(dx: -1, dy: 0))); continue }
        d -= sy
        let a = CGFloat.pi + d / r
        points.append((CGPoint(x: rect.minX + r + cos(a) * r, y: rect.minY + r + sin(a) * r), CGVector(dx: cos(a), dy: sin(a))))
    }
    return points
}

/// The toy camera's body, drawn: one plain blue of moulded plastic lit from
/// the upper left, a parting line under the lens, the yellow ribbed lens
/// the picture is seen through, the finder's hump, dimples where the Camera
/// Control's overlay comes in, the pad the red block stands on. Drawn once.
private struct ToyBackdrop: View, Equatable {
    var hinge: CGRect
    /// The yellow lens, and how wide it is round the picture.
    var lens: CGRect
    var band: CGFloat
    /// The parting line: where it starts, and how far it runs.
    var seam: CGRect
    var hump: CGRect
    var dimples: CGRect
    var pad: CGRect

    private static func mould(_ context: GraphicsContext, _ rect: CGRect, radius: CGFloat) {
        let shape = Path(roundedRect: rect, cornerRadius: radius, style: .continuous)
        context.fill(Path(roundedRect: rect.offsetBy(dx: 0, dy: 3.5), cornerRadius: radius, style: .continuous), with: .color(ToyPaint.shade.opacity(0.38)))
        context.fill(shape, with: .linearGradient(Gradient(colors: [ToyPaint.light, ToyPaint.body]), startPoint: CGPoint(x: 0, y: rect.minY), endPoint: CGPoint(x: 0, y: rect.maxY)))
        context.stroke(shape, with: .color(ToyPaint.shade.opacity(0.35)), lineWidth: 1.2)
        context.stroke(Path(roundedRect: rect.insetBy(dx: 1.5, dy: 1.5), cornerRadius: max(2, radius - 1.5), style: .continuous), with: .color(Color.white.opacity(0.55)), lineWidth: 1.2)
    }

    var body: some View {
        Canvas { context, size in
            let whole = CGRect(origin: .zero, size: size)
            context.fill(Path(whole), with: .color(ToyPaint.body))
            context.fill(Path(whole), with: .radialGradient(Gradient(stops: [.init(color: Color.white.opacity(0.20), location: 0), .init(color: Color.white.opacity(0.03), location: 0.5),
                                                                             .init(color: ToyPaint.shade.opacity(0.16), location: 1)]),
                                                            center: CGPoint(x: size.width * 0.2, y: size.height * 0.08), startRadius: 10, endRadius: max(size.width, size.height) * 0.9))
            if hinge.width > 0, hinge.height > 0 {
                let tall = hinge.height > hinge.width
                let from = tall ? CGPoint(x: hinge.midX < size.width / 2 ? hinge.minX : hinge.maxX, y: 0) : CGPoint(x: 0, y: hinge.midY < size.height / 2 ? hinge.minY : hinge.maxY)
                let to = tall ? CGPoint(x: hinge.midX < size.width / 2 ? hinge.maxX + 2 : hinge.minX - 2, y: 0) : CGPoint(x: 0, y: hinge.midY < size.height / 2 ? hinge.maxY + 2 : hinge.minY - 2)
                context.fill(Path(hinge.insetBy(dx: -2, dy: -2)), with: .linearGradient(Gradient(colors: [ToyPaint.shade.opacity(0.4), ToyPaint.shade.opacity(0)]), startPoint: from, endPoint: to))
            }
            // the parting line
            if seam.width > 0 || seam.height > 0 {
                var line = Path()
                line.move(to: seam.origin)
                line.addLine(to: CGPoint(x: seam.maxX, y: seam.maxY))
                context.stroke(line, with: .color(ToyPaint.shade.opacity(0.38)), style: StrokeStyle(lineWidth: 1.6, lineCap: .round))
                context.stroke(line.offsetBy(dx: seam.height > 0 ? 1.6 : 0, dy: seam.height > 0 ? 0 : 1.6), with: .color(Color.white.opacity(0.4)), style: StrokeStyle(lineWidth: 1.2, lineCap: .round))
            }
            // the dimples
            if dimples.width > 12, dimples.height > 12 {
                var row = 0
                var y = dimples.minY + 6
                while y <= dimples.maxY - 4 {
                    var x = dimples.minX + 8 + (row % 2 == 0 ? 0 : 6)
                    while x <= dimples.maxX - 6 {
                        context.fill(Path(ellipseIn: CGRect(x: x - 2.6, y: y - 2.6, width: 5.2, height: 5.2)), with: .color(ToyPaint.shade.opacity(0.3)))
                        var lip = Path()
                        lip.addArc(center: CGPoint(x: x, y: y + 0.9), radius: 2.6, startAngle: .radians(0.3), endAngle: .radians(2.85), clockwise: false)
                        context.stroke(lip, with: .color(Color.white.opacity(0.5)), lineWidth: 1)
                        x += 12
                    }
                    y += 10.4
                    row += 1
                }
            }
            // the finder's hump and its glass
            if hump.width > 0, hump.height > 0 {
                Self.mould(context, hump, radius: 7)
                let glass = hump.insetBy(dx: 9, dy: 6)
                context.fill(Path(roundedRect: glass, cornerRadius: 3), with: .color(Color(red: 0.09, green: 0.196, blue: 0.29)))
                context.fill(Path(roundedRect: CGRect(x: glass.minX, y: glass.minY, width: glass.width, height: glass.height / 2), cornerRadius: 3), with: .color(Color.white.opacity(0.14)))
            }
            if pad.width > 0, pad.height > 0 { Self.mould(context, pad, radius: 22) }
            // the lens: yellow, ribbed round its edge, a lighter lip, the dark well the picture sits in
            if lens.width > 2 * band, lens.height > 2 * band {
                let r = min(46, lens.height / 4)
                context.fill(Path(roundedRect: lens.offsetBy(dx: 0, dy: 4), cornerRadius: r), with: .color(ToyPaint.shade.opacity(0.42)))
                context.fill(Path(roundedRect: lens, cornerRadius: r), with: .color(ToyPaint.yellow))
                context.stroke(Path(roundedRect: lens.insetBy(dx: 1, dy: 1), cornerRadius: r - 1), with: .color(ToyPaint.yellowLight), lineWidth: 2)
                let middle = band * 0.46, reach = band * 0.30
                for point in toyWalk(lens.insetBy(dx: middle, dy: middle), radius: max(4, r - middle), step: 12.5) {
                    let a = CGPoint(x: point.at.x - point.out.dx * reach, y: point.at.y - point.out.dy * reach)
                    let b = CGPoint(x: point.at.x + point.out.dx * reach, y: point.at.y + point.out.dy * reach)
                    var light = Path()
                    light.move(to: CGPoint(x: a.x + 1.1, y: a.y + 1.1))
                    light.addLine(to: CGPoint(x: b.x + 1.1, y: b.y + 1.1))
                    context.stroke(light, with: .color(ToyPaint.yellowLight), style: StrokeStyle(lineWidth: 4.6, lineCap: .round))
                    var rib = Path()
                    rib.move(to: a)
                    rib.addLine(to: b)
                    context.stroke(rib, with: .color(ToyPaint.yellowDeep), style: StrokeStyle(lineWidth: 4.2, lineCap: .round))
                }
                let lip = band - 5
                context.fill(Path(roundedRect: lens.insetBy(dx: lip, dy: lip), cornerRadius: max(6, r - lip)), with: .color(ToyPaint.yellowLight))
                let well = band - 1.5
                context.fill(Path(roundedRect: lens.insetBy(dx: well, dy: well), cornerRadius: max(5, r - well)), with: .color(Color(red: 0.086, green: 0.125, blue: 0.18)))
            }
            context.stroke(Path(whole.insetBy(dx: 1, dy: 1)), with: .color(Color.white.opacity(0.4)), lineWidth: 2)
        }
        .accessibilityHidden(true)
    }
}

/// The yellow ring's face: scalloped and ribbed round its edge, a smooth
/// cone inside. (What is in its middle does not turn with it.)
private struct ToyRingFace: View, Equatable {
    var ridges: Int
    var body: some View {
        Canvas { context, size in
            let outer = min(size.width, size.height) / 2 - 2, centre = CGPoint(x: size.width / 2, y: size.height / 2)
            let hole = outer * 0.46
            var edge = Path()
            let steps = ridges * 8
            for i in 0...steps {
                let a = CGFloat(i) / CGFloat(steps) * 2 * CGFloat.pi
                let q = outer - 1.6 + 1.6 * cos(a * CGFloat(ridges))
                let p = CGPoint(x: centre.x + cos(a) * q, y: centre.y + sin(a) * q)
                if i == 0 { edge.move(to: p) } else { edge.addLine(to: p) }
            }
            edge.closeSubpath()
            context.fill(edge, with: .color(ToyPaint.yellow))
            context.stroke(edge, with: .color(ToyPaint.yellowDeep), lineWidth: 1.2)
            let grip = max(8, (outer - hole) * 0.36)
            for i in 0..<ridges {
                let a = (CGFloat(i) + 0.5) / CGFloat(ridges) * 2 * CGFloat.pi
                var rib = Path()
                rib.move(to: CGPoint(x: centre.x + cos(a) * (outer - grip), y: centre.y + sin(a) * (outer - grip)))
                rib.addLine(to: CGPoint(x: centre.x + cos(a) * (outer - 2.5), y: centre.y + sin(a) * (outer - 2.5)))
                context.stroke(rib, with: .color(ToyPaint.yellowDeep.opacity(0.9)), style: StrokeStyle(lineWidth: 2.2, lineCap: .round))
            }
            let inner = outer - grip - 1
            let cone = Path(ellipseIn: CGRect(x: centre.x - inner, y: centre.y - inner, width: 2 * inner, height: 2 * inner))
            context.fill(cone, with: .radialGradient(Gradient(colors: [ToyPaint.yellowLight, ToyPaint.yellow]),
                                                     center: CGPoint(x: centre.x - outer * 0.2, y: centre.y - outer * 0.3), startRadius: hole, endRadius: outer))
            context.stroke(cone, with: .color(ToyPaint.yellowDeep.opacity(0.8)), lineWidth: 1.2)
        }
    }
}

/// The ring that turns: either side of it pressed turns it one notch that
/// way, with its ratchet's click. A white disc in its middle says how it
/// stands; where the middle does something itself, it is a key.
struct ToyRing: View {
    /// What the middle says, or the symbol in it.
    var mid: String = ""
    var symbol: String? = nil
    var signs: (String, String)
    var labels: (String, String)
    var identifiers: (String, String)
    var value: String = ""
    var centre: (() -> Void)? = nil
    var centreLabel: String = ""
    var centreIdentifier: String = ""
    var step: (Int) -> Void
    @State private var turn = 0.0

    var body: some View {
        GeometryReader { geo in
            let d = min(geo.size.width, geo.size.height), hole = (d / 2 - 2) * 0.46
            ZStack {
                Circle().fill(ToyPaint.shade.opacity(0.42)).frame(width: d, height: d).offset(y: 3.5)
                ToyRingFace(ridges: d > 100 ? 30 : 26).equatable().frame(width: d, height: d).rotationEffect(.degrees(turn))
                HStack(spacing: 0) {
                    half(-1, d: d, hole: hole)
                    half(1, d: d, hole: hole)
                }
                .frame(width: d, height: d)
                middle(hole)
            }
            .frame(width: geo.size.width, height: geo.size.height)
        }
    }
    private func half(_ way: Int, d: CGFloat, hole: CGFloat) -> some View {
        let from = d / 2 - ((d / 2 - 2 + hole) / 2 + 2) - 9
        return Button {
            ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
            ConsoleHaptics.shared.play(.sliderNotch, .press)
            withAnimation(.easeOut(duration: 0.16)) { turn += Double(way) * 360 / 26 }
            step(way)
        } label: {
            Text(verbatim: way < 0 ? signs.0 : signs.1)
                .font(.system(size: 15, weight: .black, design: .rounded)).foregroundStyle(ToyPaint.redInk)
                .frame(width: 18, height: 18)
                .background(Circle().fill(ToyPaint.yellowLight))
                .padding(way < 0 ? .leading : .trailing, max(0, from))
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: way < 0 ? .leading : .trailing)
                .contentShape(Rectangle())
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(way < 0 ? labels.0 : labels.1)
        .accessibilityValue(value)
        .accessibilityIdentifier(way < 0 ? identifiers.0 : identifiers.1)
    }
    @ViewBuilder private func middle(_ hole: CGFloat) -> some View {
        let disc = ZStack {
            Circle().fill(ToyPaint.yellowLight).overlay(Circle().strokeBorder(ToyPaint.yellowDeep, lineWidth: 1)).frame(width: 2 * hole + 8, height: 2 * hole + 8)
            Circle().fill(ToyPaint.white).overlay(Circle().strokeBorder(ToyPaint.shade.opacity(0.3), lineWidth: 1)).frame(width: 2 * hole, height: 2 * hole)
            if let symbol {
                Image(systemName: symbol).font(.system(size: hole * 0.8, weight: .bold)).foregroundStyle(ToyPaint.ink)
            } else {
                Text(verbatim: mid).font(.system(size: hole * 0.72, weight: .black, design: .rounded)).foregroundStyle(ToyPaint.ink)
                    .lineLimit(1).minimumScaleFactor(0.5).frame(width: 2 * hole - 6)
            }
        }
        if let centre {
            Button(action: centre) { disc }
                .buttonStyle(MenuPressStyle())
                .accessibilityLabel(centreLabel)
                .accessibilityIdentifier(centreIdentifier)
        } else {
            disc.allowsHitTesting(false).accessibilityHidden(true)
        }
    }
}

/// A green key of two bumps: either end presses. Between them, where there
/// is room, what it turns (镜头: the filters' three circles).
private struct ToyBumps: View {
    var labels: (String, String)
    var identifiers: (String, String)
    var step: (Int) -> Void
    var body: some View {
        GeometryReader { geo in
            let h = geo.size.height, w = geo.size.width
            ZStack {
                Capsule().fill(ToyPaint.shade.opacity(0.4)).offset(y: 4)
                Capsule().fill(ToyPaint.green).brightness(-0.05).overlay(Capsule().strokeBorder(Color.black.opacity(0.22), lineWidth: 1.4))
                if w - 2 * h >= 14 {
                    ToyLensMark(size: 13, ink: ToyPaint.greenInk)
                }
                HStack(spacing: 0) {
                    bump(-1, h)
                    Spacer(minLength: 0)
                    bump(1, h)
                }
            }
        }
    }
    private func bump(_ way: Int, _ h: CGFloat) -> some View {
        Button { step(way) } label: {
            Text(verbatim: way < 0 ? "‹" : "›").font(.system(size: max(12, (h / 2 - 4) * 1.15), weight: .black, design: .rounded)).offset(y: -1.5)
        }
        .buttonStyle(ToyBumpStyle())
        .frame(width: max(h, 44), height: h)
        .accessibilityLabel(way < 0 ? labels.0 : labels.1)
        .accessibilityIdentifier(way < 0 ? identifiers.0 : identifiers.1)
    }
}
private struct ToyBumpStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View { ToyBumpBody(configuration: configuration) }
}
private struct ToyBumpBody: View {
    let configuration: ButtonStyle.Configuration
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .foregroundStyle(ToyPaint.greenInk)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(
                Circle().fill(RadialGradient(colors: [Color(red: 0.64, green: 0.86, blue: 0.68), ToyPaint.green, Color(red: 0.22, green: 0.56, blue: 0.28)],
                                             center: UnitPoint(x: 0.33, y: 0.3), startRadius: 1, endRadius: 30))
                    .padding(4)
                    .brightness(down ? -0.08 : 0)
            )
            .scaleEffect(down ? 0.94 : 1)
            .contentShape(Rectangle())
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.keyRubber, scale: 0.8)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// The flash, to press: its faceted reflector (lit while the flash is not
/// off) and what it is set to (闪光's glyph as it stands).
private struct ToyFlashFace: View {
    var lit: Bool
    var mode: CameraFlashMode
    var body: some View {
        let window = RoundedRectangle(cornerRadius: 6, style: .continuous)
        ZStack {
            window.fill(lit ? Color(red: 1.0, green: 0.90, blue: 0.50) : Color(red: 0.81, green: 0.85, blue: 0.89))
            Canvas { context, size in
                var x: CGFloat = 6
                while x < size.width {
                    context.fill(Path(CGRect(x: x, y: 0, width: 1, height: size.height)), with: .color(Color.white.opacity(0.85)))
                    x += 6
                }
                var y: CGFloat = 6
                while y < size.height {
                    context.fill(Path(CGRect(x: 0, y: y, width: size.width, height: 1)), with: .color(Color.white.opacity(0.85)))
                    y += 6
                }
            }
            .clipShape(window)
            window.strokeBorder(ToyPaint.shade.opacity(0.3), lineWidth: 1)
            ShellGlyphView(glyph: .flash(mode), size: 19, ink: lit ? ToyPaint.redInk : Color(red: 0.30, green: 0.38, blue: 0.46))
        }
        .padding(7)
    }
}

/// 镜头 on the toy (by the green key, and between its bumps): the filters'
/// three circles alone. (‹ 镜头 and 镜头 › of the cover keys' pictures
/// carry an arrow; the bumps have their own.)
private struct ToyLensMark: View {
    var size: CGFloat
    var ink: Color
    var body: some View {
        Image(systemName: "camera.filters").font(.system(size: size * 0.8, weight: ShellGlyphView.weight))
            .foregroundStyle(ink)
            .accessibilityHidden(true)
    }
}

extension ShellPlan {
    /// A key's place under the picture: from the keys' top, the Duo's points.
    func disc(_ cx: CGFloat, _ cy: CGFloat, _ r: CGFloat) -> CGRect { CGRect(x: x(cx) - r, y: keysTop + cy - r, width: 2 * r, height: 2 * r) }
    func caption(_ cx: CGFloat, _ cy: CGFloat) -> CGRect { CGRect(x: x(cx) - 36, y: keysTop + cy - 7, width: 72, height: 14) }
    func block(_ left: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat) -> CGRect { CGRect(x: x(left), y: keysTop + y, width: w * u, height: h) }
}
extension ShellAcrossPlan {
    func disc(_ cx: CGFloat, _ cy: CGFloat, _ r: CGFloat) -> CGRect { key(cx - r, cy - r, 2 * r, 2 * r) }
    func caption(_ cx: CGFloat, _ cy: CGFloat) -> CGRect { key(cx - 36, cy - 7, 72, 14) }
}

extension CameraDeckFace {
    /// The toy camera's body under its keys, upright and across.
    func toyBackdrop(_ plan: ShellPlan) -> some View {
        let strip = plan.back.strip, zone = plan.back.overlay ?? .zero, lens = plan.surround, column = plan.back.column
        return ToyBackdrop(hinge: hinge, lens: lens, band: 21,
                           seam: CGRect(x: column.minX, y: lens.maxY + 9, width: strip.maxX - column.minX - 12, height: 0),
                           hump: CGRect(x: plan.x(232), y: plan.top - 4, width: 70 * plan.u, height: 32),
                           dimples: CGRect(x: strip.minX + 6, y: zone.minY + 4, width: strip.width - 12, height: zone.height - 8),
                           pad: plan.shutter)
            .equatable()
    }
    func toyBackdrop(_ plan: ShellAcrossPlan) -> some View {
        let band = plan.back.band, zone = plan.back.overlay ?? .zero, run = plan.back.run
        return ToyBackdrop(hinge: hinge, lens: plan.back.screen.insetBy(dx: -4, dy: -4), band: 19, seam: .zero,
                           hump: run.width >= 180 ? CGRect(x: run.minX + 112, y: run.midY - 16, width: 66, height: 32) : .zero,
                           dimples: CGRect(x: zone.minX + 6, y: band.minY + 8, width: zone.width - 12, height: band.height - 16),
                           pad: plan.shutter.insetBy(dx: -5, dy: -5))
            .equatable()
    }

    /// A toy's key: its glyph in the key's own ink (画幅's figures under its
    /// frame, `stacked`), or a thick sign (the seconds left while the timer counts).
    private func toyKey(sign: String? = nil, glyph: ShellGlyph? = nil, stacked: Bool = false, size: CGFloat = 20, style: ToyKeyStyle,
                        identifier: String, label: String, value: String = "", selected: Bool = false, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            ZStack {
                if let glyph { ShellGlyphView(glyph: glyph, size: size, ink: style.ink, stacked: stacked) }
                if let sign { Text(verbatim: sign).font(.system(size: size, weight: .black, design: .rounded)) }
            }
        }
        .buttonStyle(style)
        .accessibilityLabel(label)
        .accessibilityValue(value)
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
    private func toyMoulded(_ radius: CGFloat = 23) -> ToyKeyStyle { ToyKeyStyle(make: .moulded, ink: ToyPaint.ink, radius: radius) }
    /// ZERO on its yellow plate.
    private func toyName() -> some View {
        Text(verbatim: "ZERO").font(.system(size: 17, weight: .black, design: .rounded)).tracking(4).foregroundStyle(ToyPaint.redInk).fixedSize()
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ToyKeyFace(style: ToyKeyStyle(make: .plate, radius: 9)))
            .background(RoundedRectangle(cornerRadius: 9, style: .continuous).fill(ToyPaint.shade.opacity(0.38)).offset(y: 3))
            .accessibilityHidden(true)
    }
    /// 机型 on its yellow plate: two cameras traded (换机型).
    private func toyBodies() -> some View {
        Button { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } } label: {
            ShellGlyphView(glyph: .changeBody, size: 26, ink: ToyPaint.redInk)
        }
        .buttonStyle(ToyKeyStyle(make: .plate, ink: ToyPaint.redInk, radius: 9))
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityIdentifier("camera-deck-bodies")
    }
    /// 照相 / 录像: the red ridged slide in its slot, a camera and a video
    /// camera over its ends (the one it is at filled).
    private func toyModeSlide() -> some View {
        let video = model.mode == .video
        let photoInk: Color = video ? ToyPaint.ink.opacity(0.45) : ToyPaint.ink
        let videoInk: Color = video ? ToyPaint.redInk : ToyPaint.ink.opacity(0.45)
        return ZStack(alignment: .top) {
            ShellSlide(on: video, tone: ShellTone(r: 0.925, g: 0.259, b: 0.18), set: { next in model.setMode(next ? .video : .photo) }, head: 14, track: ToyPaint.deep)
            HStack {
                ShellGlyphView(glyph: .photo(!video), size: 11, ink: photoInk)
                Spacer(minLength: 0)
                ShellGlyphView(glyph: .video(video), size: 11, ink: videoInk)
            }
            .padding(.horizontal, 13)
            .frame(height: 12)
            .allowsHitTesting(false)
        }
        .accessibilityElement()
        .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
        .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
        .accessibilityAddTraits(.isButton)
        .accessibilityAction { model.setMode(video ? .photo : .video) }
        .accessibilityIdentifier("camera-deck-mode")
    }
    /// 变焦: the yellow ring. Its middle says the factor.
    private func toyZoom() -> some View {
        let factor = model.zoom < 1 ? String(format: ".%d×", Int((model.zoom * 10).rounded())) : String(format: "%g×", (model.zoom * 10).rounded() / 10)
        return ToyRing(mid: factor, signs: ("−", "+"), labels: (String(localized: "变焦") + " −", String(localized: "变焦") + " +"),
                       identifiers: ("camera-deck-zoom-out", "camera-deck-zoom-in"), value: factor) { way in phoneNavigate(way > 0 ? 0 : 2) }
    }
    /// 镜头: the green key of two bumps.
    private func toyLensKey() -> some View {
        ToyBumps(labels: (String(localized: "镜头") + " ‹", String(localized: "镜头") + " ›"),
                 identifiers: ("camera-deck-lens-previous", "camera-deck-lens-next")) { way in phoneNavigate(way > 0 ? 1 : 3) }
    }
    private func toyFlash() -> some View {
        let flash = model.shooting.flash
        return Button { model.cycleFlash() } label: { ToyFlashFace(lit: flash != .off, mode: flash) }
            .buttonStyle(ToyKeyStyle(color: ToyPaint.white, radius: 11))
            .accessibilityLabel(String(localized: "闪光"))
            .accessibilityValue(flash.title)
            .accessibilityIdentifier("camera-deck-flash")
    }
    /// 定时: the orange key, a stopwatch on it (3 or 10 at its corner when
    /// set); while it counts, the seconds left instead.
    private func toyTimer() -> some View {
        let left = model.countdown
        let watch: ShellGlyph? = left == nil ? .timer(model.timer) : nil
        return toyKey(sign: left.map { String($0) }, glyph: watch, size: 21, style: ToyKeyStyle(color: ToyPaint.orange, ink: ToyPaint.orangeInk),
                      identifier: "camera-deck-timer", label: String(localized: "定时"),
                      value: model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title, selected: model.timer != .off) { model.cycleTimer() }
    }
    private func toyDate() -> some View {
        let on = model.shooting.dateStamp
        return toyKey(glyph: .date(on), size: 22, style: ToyKeyStyle(color: ToyPaint.yellow, ink: ToyPaint.redInk),
                      identifier: "camera-deck-date", label: String(localized: "日期"), value: on ? String(localized: "开") : String(localized: "关"), selected: on) { model.toggleDateStamp() }
    }
    /// 主菜单: a house.
    private func toyHome(_ radius: CGFloat) -> some View {
        toyKey(glyph: .home, size: 21, style: toyMoulded(radius), identifier: "camera-deck-home", label: String(localized: "camera.home.pill")) { model.leave() }
    }
    /// 画幅: the frame in the shape in use, its figures under it.
    private func toyAspect() -> some View {
        toyKey(glyph: .shape(model.shape), stacked: true, size: 17, style: toyMoulded(), identifier: "camera-deck-aspect", label: String(localized: "画幅"), value: model.shape.title) {
            withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        }
        .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
    }
    /// 水平仪: hollow while off, filled (and red) while on.
    private func toyLeveler(_ radius: CGFloat) -> some View {
        var style = toyMoulded(radius)
        if model.leveler { style.ink = ToyPaint.redInk }
        return toyKey(glyph: .level(model.leveler), size: 21, style: style,
                      identifier: "camera-deck-leveler", label: String(localized: "水平仪"),
                      value: model.leveler ? String(localized: "开") : String(localized: "关"), selected: model.leveler) { model.toggleLeveler() }
    }
    /// 浓淡 − and ＋: a circle half dark and half light, the sign beside it.
    private func toyStrength(_ way: Int) -> some View {
        let glyph: ShellGlyph = way < 0 ? .toneDown : .toneUp
        return toyKey(glyph: glyph, size: 19, style: toyMoulded(22), identifier: way < 0 ? "camera-deck-strength-minus" : "camera-deck-strength-plus",
                      label: String(localized: "浓淡") + (way < 0 ? " −" : " +")) { model.stepBodyStrength(way) }
    }
    /// 照片: the last picture in a little window, as a sticker, and how many there are.
    private func toyPhotos() -> some View {
        let last = model.photos.first
        return Button { model.openAlbum() } label: {
            ZStack(alignment: .bottomTrailing) {
                RoundedRectangle(cornerRadius: 9, style: .continuous).fill(ToyPaint.white)
                if let last, let image = thumbnails.images[last.url] {
                    Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill())
                        .clipShape(RoundedRectangle(cornerRadius: 5, style: .continuous))
                        .padding(5)
                } else {
                    ShellGlyphView(glyph: .album, size: 18, ink: ToyPaint.ink.opacity(0.55))
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
                Text(verbatim: "\(model.photos.count)").font(.system(size: 10.5, weight: .black, design: .rounded)).foregroundStyle(ToyPaint.redInk)
                    .padding(.horizontal, 6).frame(minWidth: 22, minHeight: 16)
                    .background(Capsule().fill(ToyPaint.yellow))
                    .padding(4)
                RoundedRectangle(cornerRadius: 9, style: .continuous).strokeBorder(ToyPaint.shade.opacity(0.25), lineWidth: 1)
            }
        }
        .buttonStyle(ToyPressStyle(radius: 9))
        .onAppear { if let last { thumbnails.request(last.url) } }
        .onChange(of: last?.url) { _, url in if let url { thumbnails.request(url) } }
        .accessibilityLabel(String(localized: "照片"))
        .accessibilityValue(String(localized: "\(model.photos.count) 张"))
        .accessibilityIdentifier("camera-deck-album")
    }
    /// 内 / 外: the yellow dome on its red disc, a camera with two arrows
    /// turning round its lens on it.
    private func toyKnob() -> some View {
        Button { model.switchSide() } label: {
            GeometryReader { geo in
                let d = min(geo.size.width, geo.size.height), dome = d * 0.66
                ZStack {
                    Circle().fill(ToyPaint.red).overlay(Circle().strokeBorder(ToyPaint.redDeep, lineWidth: 1.4))
                    Circle().trim(from: 0.56, to: 0.92).stroke(Color.white.opacity(0.45), lineWidth: 2).padding(3)
                    Circle().fill(ToyPaint.redDeep).frame(width: dome + 2, height: dome + 2).offset(y: 2)
                    Circle().fill(RadialGradient(colors: [ToyPaint.yellowLight, ToyPaint.yellow, ToyPaint.yellowDeep], center: UnitPoint(x: 0.33, y: 0.3), startRadius: 1, endRadius: dome * 0.65))
                        .frame(width: dome, height: dome)
                    ShellGlyphView(glyph: .flip, size: dome * 0.5, ink: ToyPaint.redInk)
                }
                .frame(width: d, height: d)
                .frame(width: geo.size.width, height: geo.size.height)
            }
        }
        .buttonStyle(ToyPressStyle(round: true))
        .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
        .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
        .accessibilityValue(model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"))
        .accessibilityIdentifier("camera-deck-switch")
    }
    /// 拍照: the red block (a square pressed into it; for a video, what the deck's key shows).
    private func toyShutter() -> some View {
        Button { model.shutter() } label: {
            Image(systemName: model.mode == .video ? (model.recording ? "stop.fill" : "record.circle") : "circle.fill")
                .font(.system(size: 17, weight: .bold)).opacity(model.mode == .video ? 1 : 0)
        }
        .buttonStyle(ToyKeyStyle(color: ToyPaint.red, ink: .white, radius: 16, inset: model.mode != .video, sound: .keyMetal, haptic: .faceButton))
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
    }
    /// 镜头: a strip of stickers, each with its glyph (a pinned body, a small
    /// drawing of its kind of camera); the one in use a little larger, its
    /// name in red under it (upright).
    private func toyStickers(named: Bool) -> some View {
        let all = chips
        let strip = RoundedRectangle(cornerRadius: 10, style: .continuous)
        return GeometryReader { geo in
            let cell = geo.size.width / CGFloat(named ? 5 : 4)
            ScrollViewReader { reader in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 0) {
                        ForEach(Array(all.enumerated()), id: \.element) { index, item in
                            toySticker(item, index: index, named: named).frame(width: cell).id(item)
                        }
                    }
                }
                .onAppear { reader.scrollTo(Chip.lens(model.lens), anchor: .center) }
                .onChange(of: model.lens) { _, lens in
                    withAnimation(.easeOut(duration: 0.15)) { reader.scrollTo(Chip.lens(lens), anchor: .center) }
                }
            }
        }
        .background(strip.fill(ToyPaint.white))
        .clipShape(strip)
        .overlay(strip.strokeBorder(ToyPaint.shade.opacity(0.25), lineWidth: 1))
        .background(strip.fill(ToyPaint.shade.opacity(0.38)).offset(y: 3))
        .accessibilityIdentifier("camera-deck-lenses")
        .opacity(systemControlsUp ? 0 : 1)
        .allowsHitTesting(!systemControlsUp)
    }
    private func toySticker(_ item: Chip, index: Int, named: Bool) -> some View {
        let title: String, glyph: ShellGlyph, on: Bool, identifier: String
        switch item {
        case .lens(let lens):
            title = lens.title; glyph = .lens(lens); on = model.lens == lens; identifier = "camera-deck-lens-\(lens.rawValue)"
        case .body(let pinned):
            title = pinned.title; glyph = .body(pinned); on = model.body == pinned; identifier = "camera-deck-pinned-\(pinned.rawValue)"
        }
        let side: CGFloat = on ? (named ? 38 : 34) : (named ? 30 : 27)
        return Button {
            ConsoleSounds.shared.play(.keyRubber, scale: 0.6)
            switch item {
            case .lens(let lens): model.choose(lens)
            case .body(let pinned): model.tapPinned(pinned)
            }
        } label: {
            VStack(spacing: 3) {
                ShellGlyphView(glyph: glyph, size: side * 0.5, ink: Color.white)
                    .frame(width: side, height: side)
                    .background(RoundedRectangle(cornerRadius: side * 0.22, style: .continuous).fill(ToyPaint.stickers[index % ToyPaint.stickers.count]))
                    .background(RoundedRectangle(cornerRadius: side * 0.22, style: .continuous).fill(Color.black.opacity(0.18)).offset(y: 1.5))
                if named, on {
                    Text(title).font(.system(size: 10, weight: .black, design: .rounded)).foregroundStyle(ToyPaint.redInk)
                        .lineLimit(1).minimumScaleFactor(0.6).padding(.horizontal, 2)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .overlay(alignment: .leading) {
                if index > 0 { Rectangle().fill(ToyPaint.green.opacity(0.55)).frame(width: 2).padding(.vertical, 5) }
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(title)
        .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }

    /// The toy camera upright: under the lens 机型 on its plate, the red
    /// slide and the ring (变焦: a magnifying glass under it); the flash to
    /// press, 定时, 日期 and the green key (镜头: the filters' circles under
    /// it); moulded in the body's blue 主菜单, 画幅, 水平仪 and 浓淡, with
    /// 照片 in its window; the stickers (镜头). In the strip the knob (内 /
    /// 外) and the red block. Each key shows its glyph; nothing is printed
    /// under the others.
    @ViewBuilder func toyFace(_ plan: ShellPlan) -> some View {
        let strip = plan.back.strip, u = plan.u
        toyName().deckPlaced(CGRect(x: plan.x(40), y: plan.top - 2, width: 104 * u, height: 30))
        toyBodies().deckPlaced(plan.block(18, 6, 178, 44))
        toyModeSlide().deckPlaced(plan.block(204, 6, 82, 44))
        toyZoom().deckPlaced(plan.disc(340, 54, 46 * u))
        ShellGlyphView(glyph: .zoom, size: 14, ink: ToyPaint.ink).deckPlaced(plan.caption(340, 111))
        toyFlash().deckPlaced(plan.block(18, 60, 56, 46))
        toyTimer().deckPlaced(plan.block(82, 59, 48, 48))
        toyDate().deckPlaced(plan.block(138, 59, 48, 48))
        toyLensKey().deckPlaced(plan.block(194, 60, 92, 46))
        ToyLensMark(size: 14, ink: ToyPaint.ink).deckPlaced(plan.caption(240, 120))
        toyHome(25).deckPlaced(plan.block(18, 138, 62, 50))
        toyAspect().deckPlaced(plan.block(88, 140, 50, 46))
        toyPhotos().deckPlaced(plan.block(146, 132, 78, 58))
        toyLeveler(23).deckPlaced(plan.block(232, 140, 50, 46))
        toyStrength(-1).deckPlaced(plan.block(290, 141, 44, 44))
        toyStrength(1).deckPlaced(plan.block(342, 141, 44, 44))
        toyStickers(named: true).deckPlaced(plan.block(18, 218, 368, 68))
        toyKnob().deckPlaced(CGRect(x: strip.midX - 26, y: plan.top + 110, width: 52, height: 52))
        toyShutter().padding(5).deckPlaced(plan.shutter)
    }

    /// The toy camera on its side: the red block in the band's clear end;
    /// in the column 机型, the ring with the slide and the green key beside
    /// it, the flash, 定时, 日期 and the knob, the moulded keys with 照片,
    /// the stickers — each key with its glyph, nothing printed under them.
    @ViewBuilder func toyAcross(_ plan: ShellAcrossPlan) -> some View {
        let run = plan.back.run
        if run.width >= 104 { toyName().deckPlaced(CGRect(x: run.minX + 4, y: run.midY - 15, width: 100, height: 30)) }
        toyShutter().deckPlaced(plan.shutter)
        toyBodies().deckPlaced(plan.key(0, 0, 200, 44))
        toyZoom().deckPlaced(plan.key(0, 53, 88, 88))
        toyModeSlide().deckPlaced(plan.key(96, 50, 104, 44))
        toyLensKey().deckPlaced(plan.key(96, 100, 104, 44))
        toyFlash().deckPlaced(plan.key(0, 150, 48, 46))
        toyTimer().deckPlaced(plan.key(54, 150, 46, 46))
        toyDate().deckPlaced(plan.key(106, 150, 46, 46))
        toyKnob().deckPlaced(plan.key(154, 150, 46, 46))
        toyHome(22).deckPlaced(plan.key(0, 212, 62, 44))
        toyAspect().deckPlaced(plan.key(68, 212, 44, 44))
        toyPhotos().deckPlaced(plan.key(118, 212, 82, 44))
        toyLeveler(22).deckPlaced(plan.key(0, 262, 62, 44))
        toyStrength(-1).deckPlaced(plan.key(68, 262, 44, 44))
        toyStrength(1).deckPlaced(plan.key(118, 262, 44, 44))
        toyStickers(named: false).deckPlaced(plan.key(0, 312, 200, 44))
    }

    /// The toy camera's 照片, upright and across.
    @ViewBuilder func toyAlbum(lens: CGRect, band: CGFloat, keys: CGRect, back: CGRect, grip: CGRect, name: CGRect, hump: CGRect, stacked: Bool) -> some View {
        ToyViewer(model: model, thumbnails: thumbnails, hinge: hinge, lens: lens, band: band, keys: keys, back: back, grip: grip, name: name, hump: hump, stacked: stacked)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The toy camera's album: 照片

/// The toy camera's 照片: the same toy as a viewer. One picture is in the
/// lens; the ring under it turns to the one before or after (its middle
/// plays a video); round it the pictures lie on a reel of small discs, the
/// one in the lens larger — a touch on a disc brings that one. The red
/// block goes back to taking pictures.
private struct ToyViewer: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var hinge: CGRect
    var lens: CGRect
    var band: CGFloat
    var keys: CGRect
    var back: CGRect
    var grip: CGRect
    var name: CGRect
    var hump: CGRect
    /// The cover held across: the keys in their column.
    var stacked: Bool

    private func disc(_ index: Int, radius: CGFloat, on: Bool) -> some View {
        let photos = model.photos
        return Group {
            if photos.indices.contains(index) {
                let photo = photos[index]
                Button {
                    ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
                    model.chooseInAlbum(index, quiet: true)
                } label: {
                    ZStack {
                        Circle().fill(on ? ToyPaint.yellow : ToyPaint.white)
                        if let image = thumbnails.images[photo.url] {
                            Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill()).clipShape(Circle()).padding(5)
                        }
                        if photo.isVideo { Image(systemName: "play.fill").font(.system(size: radius * 0.5, weight: .bold)).foregroundStyle(.white).shadow(color: .black.opacity(0.5), radius: 2) }
                    }
                }
                .buttonStyle(ToyPressStyle(round: true))
                .onAppear { thumbnails.request(photo.url) }
                .accessibilityLabel(String(localized: "照片"))
                .accessibilityValue(photo.name)
                .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier("camera-deck-album-disc-\(index)")
            } else {
                Color.clear.accessibilityHidden(true)
            }
        }
        .frame(width: 2 * radius + 10, height: 2 * radius + 10)
    }

    var body: some View {
        let photos = model.photos, at = model.albumIndex
        let picture = lens.insetBy(dx: band, dy: band)
        let photo: CameraPhoto? = photos.indices.contains(at) ? photos[at] : nil
        let playing = photo != nil && model.playing == photo?.url
        ZStack(alignment: .topLeading) {
            ToyBackdrop(hinge: hinge, lens: lens, band: band, seam: stacked ? .zero : CGRect(x: keys.minX, y: lens.maxY + 9, width: keys.width + grip.width, height: 0),
                        hump: hump, dimples: grip, pad: back.insetBy(dx: stacked ? -5 : 0, dy: stacked ? -5 : 0))
                .equatable()
            if name.width > 0 {
                Text(verbatim: "ZERO").font(.system(size: 17, weight: .black, design: .rounded)).tracking(4).foregroundStyle(ToyPaint.redInk).fixedSize()
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(ToyKeyFace(style: ToyKeyStyle(make: .plate, radius: 9)))
                    .background(RoundedRectangle(cornerRadius: 9, style: .continuous).fill(ToyPaint.shade.opacity(0.38)).offset(y: 3))
                    .accessibilityHidden(true)
                    .deckPlaced(name)
            }
            // the picture in the lens
            ZStack {
                if let photo {
                    let sharp: CGImage? = (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
                    if let sharp { Image(decorative: sharp, scale: 1).resizable().scaledToFit() }
                    if photo.isVideo {
                        #if os(iOS)
                        if playing {
                            CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                                .accessibilityIdentifier("camera-album-player")
                        }
                        #endif
                        if !playing {
                            Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9)).shadow(color: .black.opacity(0.5), radius: 4)
                        }
                    }
                } else {
                    Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(.white.opacity(0.8))
                }
            }
            .frame(width: picture.width, height: picture.height)
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            .contentShape(Rectangle())
            .onTapGesture { if photo?.isVideo == true { model.togglePlay() } }
            .onAppear { if let photo { thumbnails.request(photo.url) } }
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(String(localized: "照片"))
            .accessibilityValue(photo?.name ?? "")
            .accessibilityIdentifier("camera-deck-album-picture")
            .position(x: picture.midX, y: picture.midY)
            Text(verbatim: photos.isEmpty ? "0" : "\(at + 1) / \(photos.count)")
                .font(.system(size: 12.5, weight: .black, design: .rounded)).monospacedDigit().foregroundStyle(ToyPaint.redInk).lineLimit(1)
                .padding(.horizontal, 10).frame(height: 28)
                .background(Capsule().fill(ToyPaint.yellow))
                .accessibilityIdentifier("camera-deck-album-position")
                .fixedSize()
                .position(x: picture.maxX - 44, y: picture.minY + 22)
            // the ring: the one before, the one after; its middle plays a video
            let ring: CGFloat = stacked ? 120 : 124
            let ringMiddle = CGPoint(x: keys.midX, y: keys.minY + (stacked ? 118 : 74))
            ToyRing(mid: photos.isEmpty ? "" : "\(at + 1)", symbol: photo?.isVideo == true ? (playing ? "stop.fill" : "play.fill") : nil,
                    signs: ("‹", "›"), labels: (String(localized: "上一张"), String(localized: "下一张")),
                    identifiers: ("camera-deck-album-previous", "camera-deck-album-next"),
                    centre: photo?.isVideo == true ? { model.togglePlay() } : nil,
                    centreLabel: playing ? String(localized: "停止") : String(localized: "播放"), centreIdentifier: "camera-deck-album-play") { way in
                model.moveInAlbum(way, quiet: true)
            }
            .frame(width: ring, height: ring)
            .position(ringMiddle)
            // 主菜单 (the camera closes: a house) and, beside it, 回去拍照
            // (back to taking pictures, as the red block does: its words kept).
            let half = (keys.width - 6) / 2
            Button { model.leave() } label: {
                ShellGlyphView(glyph: .home, size: 20, ink: ToyPaint.ink)
            }
            .buttonStyle(ToyKeyStyle(make: .moulded, ink: ToyPaint.ink, radius: 24))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckPlaced(stacked ? CGRect(x: keys.minX, y: keys.minY, width: half, height: 44) : CGRect(x: keys.minX + 4, y: keys.minY + 50, width: 84, height: 48))
            Button { model.closeAlbum() } label: {
                ShellGlyphLabel(glyph: .returnToShooting, words: String(localized: "回去拍照"), size: 14, wordSize: 12.5, ink: ToyPaint.redInk)
                    .padding(.horizontal, 4)
            }
            .buttonStyle(ToyKeyStyle(make: .moulded, ink: ToyPaint.redInk, radius: 24))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-return")
            .deckPlaced(stacked ? CGRect(x: keys.maxX - half, y: keys.minY, width: half, height: 44) : CGRect(x: keys.maxX - 88, y: keys.minY + 50, width: 84, height: 48))
            // the reel of pictures
            let reach = stacked ? 1 : 2
            let reelY = keys.minY + (stacked ? 250 : 222)
            let pitch = keys.width / CGFloat(2 * reach + 1)
            ForEach(-reach...reach, id: \.self) { offset in
                disc(at + offset, radius: offset == 0 ? (stacked ? 30 : 34) : (stacked ? 23 : 26), on: offset == 0)
                    .position(x: keys.midX + CGFloat(offset) * pitch, y: reelY)
            }
            // back to taking pictures: the red block
            Button { model.closeAlbum() } label: {
                Image(systemName: "camera.fill").font(.system(size: 22, weight: .bold))
            }
            .buttonStyle(ToyKeyStyle(color: ToyPaint.red, ink: .white, radius: 16, sound: .keyMetal))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-close")
            .padding(stacked ? 0 : 5)
            .deckPlaced(back)
        }
    }
}

// MARK: - The film camera's back, its roll and its light table

/// The film camera's body, drawn: black with a grain, the finder's panel
/// sunk in it, the little eyepiece with its two lamps, the patch under the
/// thumb, the grip where the Camera Control's overlay comes in. Drawn once.
private struct FilmBackdrop: View, Equatable {
    var hinge: CGRect
    var screen: CGRect
    var finder: CGRect
    var patch: CGRect
    var grip: CGRect
    var body: some View {
        Canvas { context, size in
            let whole = CGRect(origin: .zero, size: size)
            context.fill(Path(whole), with: .linearGradient(Gradient(colors: [Color(white: 0.22), Color(white: 0.17), Color(white: 0.13)]),
                                                            startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
            var seed: UInt32 = 0x2468_ACE1
            func next() -> CGFloat {
                seed = seed &* 1_664_525 &+ 1_013_904_223
                return CGFloat((seed >> 8) & 0xFFFF) / 65535
            }
            for _ in 0..<Int(size.width * size.height / 70) {
                let at = CGPoint(x: next() * size.width, y: next() * size.height), a = Double(next()) * 0.09
                context.fill(Path(CGRect(x: at.x, y: at.y, width: 1.2, height: 1.2)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
            }
            if hinge.width > 0, hinge.height > 0 {
                let tall = hinge.height > hinge.width
                let from = tall ? CGPoint(x: hinge.midX < size.width / 2 ? hinge.minX : hinge.maxX, y: 0) : CGPoint(x: 0, y: hinge.midY < size.height / 2 ? hinge.minY : hinge.maxY)
                let to = tall ? CGPoint(x: hinge.midX < size.width / 2 ? hinge.maxX + 2 : hinge.minX - 2, y: 0) : CGPoint(x: 0, y: hinge.midY < size.height / 2 ? hinge.maxY + 2 : hinge.minY - 2)
                context.fill(Path(hinge.insetBy(dx: -2, dy: -2)), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.5), Color.black.opacity(0)]), startPoint: from, endPoint: to))
            }
            let panel = Path(roundedRect: screen, cornerRadius: 18, style: .continuous)
            context.fill(panel, with: .color(Color(white: 0.095)))
            context.stroke(panel, with: .color(Color.black.opacity(0.8)), lineWidth: 1.5)
            context.stroke(Path(roundedRect: screen.insetBy(dx: 1, dy: 1).offsetBy(dx: 0, dy: 1.5), cornerRadius: 17, style: .continuous), with: .color(Color.white.opacity(0.1)), lineWidth: 1)
            if finder.width > 0 {
                context.fill(Path(roundedRect: finder, cornerRadius: 8, style: .continuous), with: .color(Color(red: 0.05, green: 0.08, blue: 0.09)))
                context.stroke(Path(roundedRect: finder, cornerRadius: 8, style: .continuous), with: .color(Color.black.opacity(0.8)), lineWidth: 1.5)
                context.stroke(Path(roundedRect: finder.offsetBy(dx: 0, dy: 1), cornerRadius: 8, style: .continuous), with: .color(Color.white.opacity(0.12)), lineWidth: 0.8)
                context.fill(Path(ellipseIn: CGRect(x: finder.maxX + 9, y: finder.minY + 5, width: 5.2, height: 5.2)), with: .color(Color(red: 0.35, green: 0.86, blue: 0.43)))
                context.fill(Path(ellipseIn: CGRect(x: finder.maxX + 9, y: finder.maxY - 10, width: 5.2, height: 5.2)), with: .color(Color(red: 1.0, green: 0.35, blue: 0.24)))
            }
            if patch.width > 0 {
                context.fill(Path(roundedRect: patch, cornerRadius: min(patch.width, patch.height) / 2.2, style: .continuous), with: .color(Color.black.opacity(0.38)))
            }
            if grip.width > 20, grip.height > 20 {
                let tall = grip.height > grip.width
                var at = (tall ? grip.minY : grip.minX) + 8
                while at < (tall ? grip.maxY : grip.maxX) - 8 {
                    let ridge = tall ? CGRect(x: grip.minX + 8, y: at, width: grip.width - 16, height: 2.4) : CGRect(x: at, y: grip.minY + 12, width: 2.4, height: grip.height - 24)
                    context.fill(Path(roundedRect: ridge, cornerRadius: 1.2), with: .color(Color.black.opacity(0.55)))
                    context.fill(Path(roundedRect: ridge.offsetBy(dx: tall ? 0 : 2.4, dy: tall ? 2.4 : 0), cornerRadius: 1.2), with: .color(Color.white.opacity(0.09)))
                    at += 8
                }
            }
            context.stroke(Path(whole.insetBy(dx: 0.75, dy: 0.75)), with: .color(Color.white.opacity(0.22)), lineWidth: 1.5)
        }
        .accessibilityHidden(true)
    }
}

/// 曝光 as a lens's ring: milled above, its engraving below — how it is set
/// under the red mark in orange (± in a circle before it), less to the left
/// of it and more to the right (each half of the ring turns it a step that way).
private struct FilmRing: View {
    var caption: String
    var step: (Int) -> Void
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        ZStack {
            ZStack {
            Canvas { context, size in
                let whole = CGRect(origin: .zero, size: size)
                context.fill(Path(roundedRect: whole, cornerRadius: 6), with: .color(Color(white: 0.05)))
                var milled = context
                milled.clip(to: Path(roundedRect: CGRect(x: 0, y: 0, width: size.width, height: size.height * 0.46), cornerRadius: 6))
                var x = -size.height
                while x < size.width + size.height {
                    var a = Path(), b = Path()
                    a.move(to: CGPoint(x: x, y: 0)); a.addLine(to: CGPoint(x: x + size.height * 0.46, y: size.height * 0.46))
                    b.move(to: CGPoint(x: x + size.height * 0.46, y: 0)); b.addLine(to: CGPoint(x: x, y: size.height * 0.46))
                    milled.stroke(a, with: .color(Color.white.opacity(0.16)), lineWidth: 1.2)
                    milled.stroke(b, with: .color(Color.white.opacity(0.16)), lineWidth: 1.2)
                    x += 7
                }
                context.fill(Path(CGRect(x: 0, y: size.height * 0.46, width: size.width, height: 1)), with: .color(Color.white.opacity(0.12)))
                var mark = Path()
                mark.move(to: CGPoint(x: size.width / 2 - 5, y: -7)); mark.addLine(to: CGPoint(x: size.width / 2 + 5, y: -7)); mark.addLine(to: CGPoint(x: size.width / 2, y: 0)); mark.closeSubpath()
                context.fill(mark, with: .color(Color(red: 1.0, green: 0.35, blue: 0.21)))
            }
            HStack {
                Text(verbatim: "−").foregroundStyle(Color(white: 0.9))
                Spacer(minLength: 0)
                HStack(spacing: 3) {
                    ShellGlyphView(glyph: .exposure(""), size: 14, ink: Color(red: 1.0, green: 0.60, blue: 0.18))
                    Text(caption).foregroundStyle(Color(red: 1.0, green: 0.60, blue: 0.18))
                }
                Spacer(minLength: 0)
                Text(verbatim: "+").foregroundStyle(Color(white: 0.9))
            }
            .font(.system(size: 12, weight: .heavy, design: .rounded))
            .padding(.horizontal, 16)
            .padding(.top, 16)
            }
            .padding(room)
            HStack(spacing: 0) {
                Color.clear.contentShape(Rectangle()).onTapGesture { ConsoleSounds.shared.play(.keyRatchet, scale: 0.8); step(-1) }
                    .accessibilityElement().accessibilityLabel(String(localized: "曝光") + " −").accessibilityAddTraits(.isButton).accessibilityIdentifier("camera-deck-ev-minus")
                Color.clear.contentShape(Rectangle()).onTapGesture { ConsoleSounds.shared.play(.keyRatchet, scale: 0.8); step(1) }
                    .accessibilityElement().accessibilityLabel(String(localized: "曝光") + " +").accessibilityAddTraits(.isButton).accessibilityIdentifier("camera-deck-ev-plus")
            }
        }
    }
}

/// One frame of the strip on the light table: the film's base with its
/// perforations, the frame's number, the picture as a negative; the chosen
/// one outlined.
private struct FilmFrame: View {
    var image: CGImage?
    var number: Int
    var chosen: Bool
    var body: some View {
        ZStack {
            Canvas { context, size in
                context.fill(Path(CGRect(origin: .zero, size: size)), with: .color(Color(red: 0.35, green: 0.18, blue: 0.07)))
                var x: CGFloat = 4
                while x < size.width - 4 {
                    for y in [CGFloat(4), size.height - 13] {
                        context.fill(Path(roundedRect: CGRect(x: x, y: y, width: 7, height: 9), cornerRadius: 2), with: .color(Color(red: 0.93, green: 0.945, blue: 0.96)))
                    }
                    x += 12
                }
            }
            ZStack {
                Color(red: 0.55, green: 0.30, blue: 0.14)
                if let image {
                    Image(decorative: image, scale: 1).resizable().scaledToFill().colorInvert().opacity(0.9)
                        .overlay(Color(red: 0.84, green: 0.46, blue: 0.14).opacity(0.45))
                }
            }
            .frame(width: 82, height: 58).clipped()
            .overlay(Rectangle().strokeBorder(Color.white.opacity(chosen ? 1 : 0), lineWidth: 3).padding(-3))
            Text(verbatim: "\(number)").font(.system(size: 8, weight: .bold, design: .rounded)).foregroundStyle(Color(red: 0.94, green: 0.63, blue: 0.29))
                .frame(maxHeight: .infinity, alignment: .top).padding(.top, 12)
        }
    }
}

/// The film camera's 底片: the light table. The developed pictures lie on it
/// as a strip of negatives (the newest first), the chosen frame printed
/// above; the frames still on the roll are not there — the table says how
/// many, and 冲洗这一卷 develops them.
private struct FilmTable: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var table: CGRect
    var keys: CGRect
    var back: CGRect
    var stacked: Bool

    /// A key of the table: its glyph, in the key's own ink (with its words
    /// beside it where they are kept: 回去拍照).
    private func key(_ glyph: ShellGlyph, _ words: String?, _ label: String, _ identifier: String, _ style: ShellKeyStyle, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Group {
                if let words {
                    ShellGlyphLabel(glyph: glyph, words: words, size: 15, wordSize: 11.5, ink: style.tone.ink)
                } else {
                    ShellGlyphView(glyph: glyph, size: 18, ink: style.tone.ink)
                }
            }
            .padding(.horizontal, 4)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .buttonStyle(style)
        .accessibilityLabel(label)
        .accessibilityIdentifier(identifier)
    }
    private func move(_ delta: Int) {
        ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
        model.moveInAlbum(delta, quiet: true)
    }

    var body: some View {
        let photos = model.photos, at = model.albumIndex, waiting = model.rollFrames.count
        let rubber = ShellKeyStyle(tone: ShellTone(r: 0.24, g: 0.245, b: 0.26), radius: 21, travel: 1.5, sound: .keyRubber, soft: true)
        let ink = Color(red: 0.29, green: 0.30, blue: 0.33)
        ZStack(alignment: .topLeading) {
            LinearGradient(colors: [Color(white: 0.20), Color(white: 0.13)], startPoint: .topLeading, endPoint: .bottomTrailing)
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .fill(RadialGradient(colors: [.white, Color(red: 0.90, green: 0.92, blue: 0.94)], center: .center, startRadius: 30, endRadius: 420))
                .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).strokeBorder(Color.black.opacity(0.6), lineWidth: 2))
                .deckPlaced(table)
                .accessibilityHidden(true)
            VStack(spacing: 6) {
                if photos.isEmpty {
                    Spacer(minLength: 0)
                    Text("底片还在机身里：拍完一卷，或者按「冲洗这一卷」").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(ink)
                        .multilineTextAlignment(.center).padding(.horizontal, 20)
                    Spacer(minLength: 0)
                } else if photos.indices.contains(at) {
                    let photo = photos[at]
                    let sharp: CGImage? = (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
                    ZStack {
                        if let sharp {
                            Image(decorative: sharp, scale: 1).resizable().scaledToFit().padding(7)
                                .background(Color(red: 0.985, green: 0.98, blue: 0.965))
                                .shadow(color: .black.opacity(0.35), radius: 6, y: 3)
                        }
                        if photo.isVideo {
                            #if os(iOS)
                            if model.playing == photo.url {
                                CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() }).padding(7)
                                    .accessibilityIdentifier("camera-album-player")
                            }
                            #endif
                            if model.playing != photo.url {
                                Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9)).shadow(color: .black.opacity(0.5), radius: 4)
                            }
                        }
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .contentShape(Rectangle())
                    .onTapGesture { if photo.isVideo { model.togglePlay() } }
                    .onAppear { thumbnails.request(photo.url) }
                    .accessibilityElement(children: .ignore)
                    .accessibilityLabel(String(localized: "底片"))
                    .accessibilityValue(photo.name)
                    .accessibilityIdentifier("camera-deck-album-frame")
                    Text(verbatim: "\(photos.count - at) · " + photo.date.formatted(.dateTime.locale(UILanguage.locale).year().month().day().hour().minute(.twoDigits)))
                        .font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(ink).lineLimit(1).minimumScaleFactor(0.6)
                    ScrollViewReader { proxy in
                        ScrollView(.horizontal, showsIndicators: false) {
                            LazyHStack(spacing: 0) {
                                ForEach(Array(photos.enumerated()), id: \.element.url) { index, one in
                                    FilmFrame(image: thumbnails.images[one.url], number: photos.count - index, chosen: index == at)
                                        .frame(width: 96, height: 92)
                                        .contentShape(Rectangle())
                                        .onTapGesture { ConsoleSounds.shared.play(.keyRatchet, scale: 0.8); model.chooseInAlbum(index, quiet: true) }
                                        .onAppear { thumbnails.request(one.url) }
                                        .accessibilityElement(children: .ignore)
                                        .accessibilityLabel(String(localized: "底片") + " \(photos.count - index)")
                                        .accessibilityAddTraits(index == at ? [.isButton, .isSelected] : .isButton)
                                        .accessibilityIdentifier("camera-deck-album-negative-\(photos.count - index)")
                                }
                            }
                        }
                        .frame(height: 92)
                        // (The strip is laid out again when a roll's frames come onto the table.)
                        .id(photos.count)
                        .onChange(of: at) { _, now in
                            guard photos.indices.contains(now) else { return }
                            withAnimation(.easeOut(duration: 0.2)) { proxy.scrollTo(photos[now].url, anchor: .center) }
                        }
                        .onAppear { if photos.indices.contains(at) { proxy.scrollTo(photos[at].url, anchor: .center) } }
                    }
                }
                if waiting > 0 {
                    HStack(spacing: 8) {
                        Text("这一卷拍了 \(waiting) 格，还没冲洗").font(.system(size: 11, weight: .bold, design: .rounded)).foregroundStyle(ink)
                            .lineLimit(2).minimumScaleFactor(0.7)
                        Spacer(minLength: 0)
                        Button { model.developRoll() } label: {
                            Text("冲洗这一卷").font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(.white)
                                .padding(.horizontal, 12).frame(height: 36)
                                .background(Capsule().fill(Color(red: 0.79, green: 0.42, blue: 0.12)))
                        }
                        .buttonStyle(MenuPressStyle())
                        .accessibilityIdentifier("camera-deck-develop")
                    }
                    .padding(.horizontal, 4)
                }
            }
            .padding(10)
            .frame(width: table.width, height: table.height)
            .position(x: table.midX, y: table.midY)
            // The keys: ‹ and ›, a house (主菜单), 回去拍照 (its words kept;
            // the key in the strip where the shutter is, a camera alone).
            let earlier = key(.previous, nil, String(localized: "上一格"), "camera-deck-album-previous", rubber) { move(-1) }
            let later = key(.next, nil, String(localized: "下一格"), "camera-deck-album-next", rubber) { move(1) }
            let count = Text(verbatim: photos.isEmpty ? "0" : "\(at + 1) / \(photos.count)")
                .font(.system(size: 12.5, weight: .heavy, design: .rounded)).monospacedDigit().foregroundStyle(Color(white: 0.85)).lineLimit(1).minimumScaleFactor(0.6)
                .accessibilityIdentifier("camera-deck-album-position")
            let home = key(.home, nil, String(localized: "camera.home.pill"), "camera-deck-home", rubber) { model.leave() }
            let cameraSign: ShellGlyph = stacked ? .returnToShooting : .photo(true)
            let camera = key(cameraSign, stacked ? String(localized: "回去拍照") : nil, String(localized: "回去拍照"), "camera-deck-album-close", rubber) { model.closeAlbum() }
            Group {
                if stacked {
                    VStack(spacing: 8) {
                        // (The album's glyph where its name was, in the room the name took.)
                        Text("底片").font(.system(size: 15, weight: .heavy, design: .rounded)).hidden()
                            .overlay(ShellGlyphView(glyph: .album, size: 18, ink: Color(white: 0.85)))
                            .accessibilityHidden(true)
                        count
                        HStack(spacing: 8) { earlier; later }.frame(height: 46)
                        Spacer(minLength: 0)
                        camera.frame(height: 46)
                        home.frame(height: 44)
                    }
                } else {
                    // 回去拍照 with its words (the key in the strip, where the
                    // shutter is, goes back too).
                    HStack(spacing: 6) {
                        earlier.frame(width: 54)
                        count.frame(maxWidth: .infinity)
                        later.frame(width: 54)
                        key(.returnToShooting, String(localized: "回去拍照"), String(localized: "回去拍照"), "camera-deck-album-return", rubber) { model.closeAlbum() }
                            .frame(width: 100)
                        home.frame(width: 76)
                    }
                }
            }
            .frame(width: keys.width, height: keys.height)
            .position(x: keys.midX, y: keys.midY)
            if !stacked, back.width > 0 { camera.deckPlaced(back) }
        }
    }
}

extension CameraDeckFace {
    func filmBackdrop(_ plan: ShellPlan) -> some View {
        let strip = plan.back.strip, zone = plan.back.overlay ?? .zero
        return FilmBackdrop(hinge: hinge, screen: plan.surround, finder: CGRect(x: plan.x(22), y: plan.top + 2, width: 78 * plan.u, height: 30),
                            patch: CGRect(x: strip.midX - 25, y: plan.top + 182, width: 50, height: 92),
                            grip: CGRect(x: strip.minX, y: zone.minY, width: strip.width, height: zone.height))
            .equatable()
    }
    func filmBackdrop(_ plan: ShellAcrossPlan) -> some View {
        let band = plan.back.band, zone = plan.back.overlay ?? .zero, run = plan.back.run
        return FilmBackdrop(hinge: hinge, screen: plan.back.screen, finder: run.width >= 120 ? CGRect(x: run.minX + 4, y: run.midY - 15, width: 78, height: 30) : .zero,
                            patch: .zero, grip: CGRect(x: zone.minX, y: band.minY, width: zone.width, height: band.height))
            .equatable()
    }

    private var filmRubber: ShellKeyStyle { ShellKeyStyle(tone: ShellTone(r: 0.24, g: 0.245, b: 0.26), radius: 23, travel: 1.5, sound: .keyRubber, soft: true) }
    private var filmChrome: ShellKeyStyle { ShellKeyStyle(tone: ShellTone(r: 0.80, g: 0.81, b: 0.83), radius: 200, travel: 1.2, sound: .keyRatchet, brushed: true) }
    /// The counter's little grey-green display: how many frames the roll has left.
    private func filmCounter() -> some View {
        VStack(spacing: 1) {
            Text("余 \(model.rollLeft) 张").font(.system(size: 13, weight: .heavy, design: .rounded)).monospacedDigit()
            Text(verbatim: model.rollFrames.isEmpty ? "—" : "\(model.rollFrames.count) / \(CameraAppModel.rollLength)").font(.system(size: 10.5, weight: .bold, design: .rounded)).monospacedDigit().opacity(0.8)
        }
        .foregroundStyle(Color(red: 0.12, green: 0.165, blue: 0.11))
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(RoundedRectangle(cornerRadius: 5, style: .continuous).fill(Color(red: 0.62, green: 0.68, blue: 0.56))
            .overlay(RoundedRectangle(cornerRadius: 5, style: .continuous).strokeBorder(Color.black.opacity(0.7), lineWidth: 2)))
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(String(localized: "底片"))
        .accessibilityValue("\(model.rollLeft)")
        .accessibilityIdentifier("camera-deck-roll")
    }
    /// The film's window in the door: the film's canister (400 on it) and
    /// two cameras traded (机型: 换机型).
    private func filmDoor() -> some View {
        Button {
            ConsoleSounds.shared.play(.keySlide, scale: 0.7)
            if model.bodiesOpen { model.closeBodies() } else { model.openBodies() }
        } label: {
            HStack(spacing: 8) {
                Text(verbatim: "400").font(.system(size: 10, weight: .heavy, design: .rounded)).foregroundStyle(Color(white: 0.1))
                    .frame(width: 32).frame(maxHeight: .infinity).background(RoundedRectangle(cornerRadius: 4).fill(Color(red: 0.79, green: 0.63, blue: 0.24))).padding(.vertical, 7)
                Spacer(minLength: 0)
                ShellGlyphView(glyph: .changeBody, size: 26, ink: Color(red: 0.95, green: 0.93, blue: 0.89))
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 8)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(RoundedRectangle(cornerRadius: 10, style: .continuous).fill(Color(white: 0.055))
                .overlay(RoundedRectangle(cornerRadius: 10, style: .continuous).strokeBorder(Color.black.opacity(0.7), lineWidth: 1))
                .shadow(color: Color.white.opacity(0.12), radius: 0, y: 1))
        }
        .buttonStyle(MenuPressStyle())
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityIdentifier("camera-deck-bodies")
    }
    /// W | T (a magnifying glass less and more). `reach`: room at each key's
    /// outer side that is touched with it (the pair is placed that much
    /// wider each way); `lift`: the same over and under both.
    private func filmZoom(reach: CGFloat = 0, lift: CGFloat = 0) -> some View {
        HStack(spacing: 3) {
            shellKey("W", glyph: .zoomOut, identifier: "camera-deck-zoom-out", style: filmRubber, label: String(localized: "变焦") + " −") { phoneNavigate(2) }
                .environment(\.deckKeyInset, EdgeInsets(top: lift, leading: reach, bottom: lift, trailing: 0))
            shellKey("T", glyph: .zoomIn, identifier: "camera-deck-zoom-in", style: filmRubber, label: String(localized: "变焦") + " +") { phoneNavigate(0) }
                .environment(\.deckKeyInset, EdgeInsets(top: lift, leading: 0, bottom: lift, trailing: reach))
        }
    }
    private func filmName() -> some View {
        Text(verbatim: "ZERO").font(.system(size: 12.5, weight: .heavy, design: .rounded)).tracking(3.2).foregroundStyle(Color(red: 0.83, green: 0.70, blue: 0.36)).fixedSize()
            .accessibilityHidden(true)
    }
    /// 底片: the album's glyph and how many there are.
    private func filmAlbumKey(_ size: CGFloat) -> some View {
        shellKey(String(localized: "底片"), glyph: .album, size: size, figures: "\(model.photos.count)", value: String(localized: "\(model.photos.count) 张"),
                 identifier: "camera-deck-album", style: filmRubber) { model.openAlbum() }
    }

    /// The film camera upright: two milled dials on the top plate (ISO,
    /// 白平衡: the letters a camera prints, what they are set to under them);
    /// under the finder the counter, the film's window and W | T; four
    /// rubber keys; the switch and the lens's ring (曝光); the lenses; 底片,
    /// 水平仪, 主菜单; in the strip the other camera's key and the shutter in
    /// its ring. Each key shows its glyph, drawn as what it sets stands.
    @ViewBuilder func filmFace(_ plan: ShellPlan) -> some View {
        let shooting = model.shooting, strip = plan.back.strip, u = plan.u, k = plan.keysTop
        shellKey("ISO", glyph: .iso(shooting.iso), size: 18, value: shooting.iso.title, identifier: "camera-deck-iso", style: filmChrome) { model.cycleISO() }
            .deckKey(CGRect(x: plan.x(196) - 19, y: plan.top - 1, width: 38, height: 38))
        shellKey("WB", glyph: .whiteBalance(shooting.whiteBalance), size: 18, value: shooting.whiteBalance.title, identifier: "camera-deck-wb", style: filmChrome,
                 label: String(localized: "白平衡")) { model.cycleWhiteBalance() }
            .deckKey(CGRect(x: plan.x(244) - 19, y: plan.top - 1, width: 38, height: 38))
        filmName().deckPlaced(CGRect(x: plan.x(296), y: plan.top + 6, width: 84 * u, height: 20))
        filmCounter().deckPlaced(CGRect(x: plan.x(20), y: k, width: 108 * u, height: 50))
        filmDoor().deckPlaced(CGRect(x: plan.x(138), y: k - 4, width: 154 * u, height: 58))
        filmZoom(reach: 7).deckPlaced(CGRect(x: plan.x(300) - 7, y: k + 3, width: 80 * u + 14, height: 44))
        shellKey(String(localized: "闪光"), glyph: .flash(shooting.flash), size: 20, value: shooting.flash.title, identifier: "camera-deck-flash", style: filmRubber) { model.cycleFlash() }
            .deckPlaced(CGRect(x: plan.x(20), y: k + 68, width: 85 * u, height: 46))
        shellKey(String(localized: "定时"), glyph: .timer(model.timer), size: 20, value: model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title,
                 identifier: "camera-deck-timer", style: filmRubber) { model.cycleTimer() }
            .deckPlaced(CGRect(x: plan.x(111), y: k + 68, width: 85 * u, height: 46))
        shellKey(String(localized: "日期"), glyph: .date(shooting.dateStamp), size: 20, value: shooting.dateStamp ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-date", style: filmRubber) { model.toggleDateStamp() }
            .deckPlaced(CGRect(x: plan.x(202), y: k + 68, width: 85 * u, height: 46))
        shellKey(String(localized: "画幅"), glyph: .shape(model.shape), size: 20, value: model.shape.title, identifier: "camera-deck-aspect", style: filmRubber) {
            withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        }
        .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
        .deckPlaced(CGRect(x: plan.x(293), y: k + 68, width: 87 * u, height: 46))
        shellModeSlide(ShellTone(r: 0.30, g: 0.305, b: 0.32), ink: Color(white: 0.85)).deckKey(CGRect(x: plan.x(20), y: k + 134, width: 116 * u, height: 36))
        FilmRing(caption: shooting.exposureTitle, step: { model.stepExposure($0) }).deckKey(CGRect(x: plan.x(146), y: k + 132, width: 234 * u, height: 42))
        shellLenses(ink: Color(white: 0.85), chosen: Color(red: 0.79, green: 0.63, blue: 0.24), chosenInk: Color(white: 0.1), radius: 19)
            .background(Capsule().fill(Color(white: 0.11)).overlay(Capsule().strokeBorder(Color.black.opacity(0.6), lineWidth: 1)))
            .clipShape(Capsule())
            .deckPlaced(CGRect(x: plan.x(18), y: k + 186, width: 364 * u, height: 44))
        filmAlbumKey(19).deckPlaced(CGRect(x: plan.x(20), y: k + 240, width: 116 * u, height: 44))
        shellKey(String(localized: "水平仪"), glyph: .level(model.leveler), size: 20, value: model.leveler ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-leveler", style: filmRubber, selected: model.leveler) { model.toggleLeveler() }
            .deckPlaced(CGRect(x: plan.x(142), y: k + 240, width: 116 * u, height: 44))
        shellBarKey(String(localized: "camera.home.pill"), glyph: .home, identifier: "camera-deck-home", style: filmRubber) { model.leave() }
            .deckPlaced(CGRect(x: plan.x(264), y: k + 240, width: 116 * u, height: 44))
        shellKey(model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), glyph: .flip, size: 20, identifier: "camera-deck-switch", style: filmRubber,
                 label: String(localized: "切换内侧、外侧相机")) { model.switchSide() }
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckPlaced(CGRect(x: strip.midX - 26, y: plan.top + 104, width: 52, height: 52))
        shellShutter(ShellKeyStyle(tone: ShellTone(r: 0.12, g: 0.12, b: 0.13), radius: 200, travel: 2.5, sound: .keyMetal, rings: true), ring: true)
            .deckPlaced(plan.shutter.insetBy(dx: 7, dy: 7))
    }

    /// The film camera on its side: the shutter on the top plate (the
    /// band's clear end); in the column the counter and W | T, the film's
    /// window, four rubber keys, ISO, 白平衡 and the other camera, the
    /// switch and the ring, the lenses, 底片, 水平仪, 主菜单 — each key with
    /// its glyph.
    @ViewBuilder func filmAcross(_ plan: ShellAcrossPlan) -> some View {
        let shooting = model.shooting, run = plan.back.run
        if run.width >= 170 { filmName().deckPlaced(CGRect(x: run.minX + 104, y: run.midY - 10, width: 70, height: 20)) }
        shellShutter(ShellKeyStyle(tone: ShellTone(r: 0.12, g: 0.12, b: 0.13), radius: 200, travel: 2.5, sound: .keyMetal, rings: true), ring: true)
            .deckPlaced(plan.shutter.insetBy(dx: 4, dy: 4))
        filmCounter().deckPlaced(plan.key(0, 0, 86, 44))
        filmZoom(lift: 2).deckPlaced(plan.key(94, 0, 106, 44))
        filmDoor().deckPlaced(plan.key(0, 52, 200, 48))
        shellKey(String(localized: "闪光"), glyph: .flash(shooting.flash), size: 18, value: shooting.flash.title, identifier: "camera-deck-flash", style: filmRubber) { model.cycleFlash() }
            .deckKey(plan.key(0, 108, 98, 40))
        shellKey(String(localized: "定时"), glyph: .timer(model.timer), size: 18, value: model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title,
                 identifier: "camera-deck-timer", style: filmRubber) { model.cycleTimer() }
            .deckKey(plan.key(102, 108, 98, 40))
        shellKey(String(localized: "日期"), glyph: .date(shooting.dateStamp), size: 18, value: shooting.dateStamp ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-date", style: filmRubber) { model.toggleDateStamp() }
            .deckKey(plan.key(0, 154, 98, 40))
        shellKey(String(localized: "画幅"), glyph: .shape(model.shape), size: 18, value: model.shape.title, identifier: "camera-deck-aspect", style: filmRubber) {
            withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        }
        .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
        .deckKey(plan.key(102, 154, 98, 40))
        shellKey("ISO", glyph: .iso(shooting.iso), size: 16, value: shooting.iso.title, identifier: "camera-deck-iso", style: filmRubber) { model.cycleISO() }
            .deckKey(plan.key(0, 200, 62, 36))
        shellKey("WB", glyph: .whiteBalance(shooting.whiteBalance), size: 16, value: shooting.whiteBalance.title, identifier: "camera-deck-wb", style: filmRubber,
                 label: String(localized: "白平衡")) { model.cycleWhiteBalance() }
            .deckKey(plan.key(69, 200, 62, 36))
        shellKey(model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), glyph: .flip, size: 16, identifier: "camera-deck-switch", style: filmRubber,
                 label: String(localized: "切换内侧、外侧相机")) { model.switchSide() }
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(plan.key(138, 200, 62, 36))
        shellModeSlide(ShellTone(r: 0.30, g: 0.305, b: 0.32), ink: Color(white: 0.85)).deckKey(plan.key(0, 242, 86, 32))
        FilmRing(caption: shooting.exposureTitle, step: { model.stepExposure($0) }).deckKey(plan.key(94, 246, 106, 28))
        shellLenses(ink: Color(white: 0.85), chosen: Color(red: 0.79, green: 0.63, blue: 0.24), chosenInk: Color(white: 0.1), radius: 17)
            .background(Capsule().fill(Color(white: 0.11)).overlay(Capsule().strokeBorder(Color.black.opacity(0.6), lineWidth: 1)))
            .clipShape(Capsule())
            .deckPlaced(plan.key(0, 278, 200, 42))
        filmAlbumKey(16).deckKey(plan.key(0, 324, 62, 32))
        shellKey(String(localized: "水平仪"), glyph: .level(model.leveler), size: 16, value: model.leveler ? String(localized: "开") : String(localized: "关"),
                 identifier: "camera-deck-leveler", style: filmRubber, selected: model.leveler) { model.toggleLeveler() }
            .deckKey(plan.key(69, 324, 62, 32))
        shellKey(String(localized: "camera.home.pill"), glyph: .home, size: 16, identifier: "camera-deck-home", style: filmRubber) { model.leave() }
            .deckKey(plan.key(138, 324, 62, 32))
    }

    /// The film camera's album: the light table (upright the keys under
    /// it and 回去拍照 in the strip; across the keys in their column).
    @ViewBuilder func filmAlbum(table: CGRect, keys: CGRect, back: CGRect, stacked: Bool) -> some View {
        FilmTable(model: model, thumbnails: thumbnails, table: table, keys: keys, back: back, stacked: stacked)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The pocket digital camera's back

/// The pocket digital camera's colours: the plate of brushed metal in one
/// bright colour, the chosen zoom stop's colour on its screen, what is
/// printed on the plate (and the same paler, for what waits). Five sets, the
/// same camera in each; the bright frame round it, the keys of aluminium,
/// the lit lens key and the shutter's chrome are the same on all of them.
struct DigiPaint: Equatable {
    var name: String
    var body: ShellTone
    var accent: Color
    var print: Color
    var dim: Color
    var light = false

    static let violet = DigiPaint(name: "violet", body: ShellTone(r: 0.471, g: 0.361, b: 0.816), accent: Color(red: 0.663, green: 0.545, blue: 1.0),
                                  print: Color.white.opacity(0.95), dim: Color.white.opacity(0.6))
    static let magenta = DigiPaint(name: "magenta", body: ShellTone(r: 0.839, g: 0.173, b: 0.502), accent: Color(red: 1.0, green: 0.435, blue: 0.694),
                                   print: Color.white.opacity(0.95), dim: Color.white.opacity(0.62))
    static let cyan = DigiPaint(name: "cyan", body: ShellTone(r: 0.118, g: 0.620, b: 0.808), accent: Color(red: 0.247, green: 0.816, blue: 1.0),
                                print: Color.white.opacity(0.96), dim: Color.white.opacity(0.64))
    static let black = DigiPaint(name: "black", body: ShellTone(r: 0.173, g: 0.176, b: 0.196), accent: Color(red: 0.357, green: 0.608, blue: 1.0),
                                 print: Color(red: 0.941, green: 0.949, blue: 0.965).opacity(0.92), dim: Color(red: 0.941, green: 0.949, blue: 0.965).opacity(0.55))
    static let silver = DigiPaint(name: "silver", body: ShellTone(r: 0.808, g: 0.820, b: 0.843), accent: Color(red: 0.231, green: 0.510, blue: 0.965),
                                  print: Color(red: 0.149, green: 0.161, blue: 0.196).opacity(0.88), dim: Color(red: 0.149, green: 0.161, blue: 0.196).opacity(0.55),
                                  light: true)
    /// Every colour the camera is made in, the one it comes in first.
    static let all: [DigiPaint] = [violet, magenta, cyan, black, silver]
    /// What is written on the keys of aluminium; the aluminium; the lens key's light.
    static let ink = Color(red: 0.149, green: 0.161, blue: 0.196)
    static let aluminium = ShellTone(r: 0.886, g: 0.894, b: 0.914)
    static let lit = Color(red: 1.0, green: 0.698, blue: 0.180)
    /// The lamp by ZERO: amber while taking pictures, red while a video is
    /// taken, green in 回放.
    static let amber = ShellTone(r: 1.0, g: 0.627, b: 0.235)
    static let red = ShellTone(r: 0.95, g: 0.25, b: 0.22)
    static let green = ShellTone(r: 0.275, g: 0.902, b: 0.471)

    /// What the colour is called.
    var title: String {
        switch name {
        case "magenta": return String(localized: "洋红")
        case "cyan": return String(localized: "青蓝")
        case "black": return String(localized: "黑")
        case "silver": return String(localized: "银")
        default: return String(localized: "紫")
        }
    }
    /// The colour as a back's (what is kept, and the dot that shows it).
    var tint: ShellTint { ShellTint(name: name, title: title, dot: body) }
    /// The paint of that name (none kept, or one not known: the one it comes in).
    static func named(_ name: String?) -> DigiPaint { all.first { $0.name == name } ?? violet }
    /// The thumb rest's rubber: the plate's colour, nearly black.
    var rubber: ShellTone {
        ShellTone(r: body.r * 0.154 + 0.046, g: body.g * 0.154 + 0.048, b: body.b * 0.154 + 0.055)
    }
}

/// One sticker on the plate: its shape, where it is, how far it reaches,
/// its colour and its lean.
struct DigiSticker: Equatable {
    enum Kind: Equatable { case star, spark, heart, bow, dot }
    var kind: Kind
    var at: CGPoint
    var size: CGFloat
    var colour: ShellTone
    var turn: Double = 0

    static let pink = ShellTone(r: 1.0, g: 0.518, b: 0.698)
    static let lemon = ShellTone(r: 1.0, g: 0.839, b: 0.329)
    static let sky = ShellTone(r: 0.439, g: 0.769, b: 0.980)
    static let mint = ShellTone(r: 0.471, g: 0.871, b: 0.745)
    static let lilac = ShellTone(r: 0.729, g: 0.588, b: 0.980)
    static let white = ShellTone(r: 1, g: 1, b: 1)
    static let rose = ShellTone(r: 0.980, g: 0.361, b: 0.502)

    /// Its outline round (0, 0), `s` how far it reaches.
    static func outline(_ kind: Kind, _ s: CGFloat) -> Path {
        var path = Path()
        switch kind {
        case .star, .spark:
            let points = kind == .star ? 10 : 8
            let inner: CGFloat = kind == .star ? s * 0.46 : s * 0.3
            for i in 0..<points {
                let a = -Double.pi / 2 + Double(i) * 2 * Double.pi / Double(points)
                let q: CGFloat = i % 2 == 1 ? inner : s
                let p = CGPoint(x: CGFloat(cos(a)) * q, y: CGFloat(sin(a)) * q)
                if i == 0 { path.move(to: p) } else { path.addLine(to: p) }
            }
        case .heart:
            path.move(to: CGPoint(x: 0, y: s * 0.82))
            path.addCurve(to: CGPoint(x: 0, y: -s * 0.42), control1: CGPoint(x: -s * 1.5, y: -s * 0.2), control2: CGPoint(x: -s * 0.7, y: -s * 1.15))
            path.addCurve(to: CGPoint(x: 0, y: s * 0.82), control1: CGPoint(x: s * 0.7, y: -s * 1.15), control2: CGPoint(x: s * 1.5, y: -s * 0.2))
        case .bow:
            path.move(to: .zero)
            path.addCurve(to: CGPoint(x: -s * 1.2, y: 0), control1: CGPoint(x: -s * 0.5, y: -s * 0.9), control2: CGPoint(x: -s * 1.3, y: -s * 0.8))
            path.addCurve(to: .zero, control1: CGPoint(x: -s * 1.3, y: s * 0.8), control2: CGPoint(x: -s * 0.5, y: s * 0.9))
            path.addCurve(to: CGPoint(x: s * 1.2, y: 0), control1: CGPoint(x: s * 0.5, y: -s * 0.9), control2: CGPoint(x: s * 1.3, y: -s * 0.8))
            path.addCurve(to: .zero, control1: CGPoint(x: s * 1.3, y: s * 0.8), control2: CGPoint(x: s * 0.5, y: s * 0.9))
        case .dot:
            path.addEllipse(in: CGRect(x: -s, y: -s, width: 2 * s, height: 2 * s))
        }
        path.closeSubpath()
        return path
    }

    /// The row along the plate's lower edge (upright; under the screen held
    /// across): from `origin` along `width`.
    static func row(from origin: CGPoint, width: CGFloat) -> [DigiSticker] {
        var list: [DigiSticker] = []
        func add(_ kind: Kind, _ along: CGFloat, _ down: CGFloat, _ size: CGFloat, _ colour: ShellTone, _ turn: Double = 0) {
            list.append(DigiSticker(kind: kind, at: CGPoint(x: origin.x + along * width, y: origin.y + down), size: size, colour: colour, turn: turn))
        }
        add(.bow, 0.161, 5, 10, pink, -0.1)
        add(.star, 0.263, 2, 8.5, lemon, 0.3)
        add(.dot, 0.328, 10, 4, sky)
        add(.heart, 0.392, 4, 8, rose, 0.2)
        add(.spark, 0.473, 6, 7, white)
        add(.dot, 0.532, 0, 3.4, mint)
        add(.heart, 0.640, 5, 7, lilac, -0.2)
        add(.star, 0.726, 4, 8, mint, -0.2)
        add(.dot, 0.790, 10, 4.2, lemon)
        add(.star, 0.860, 2, 7, pink, 0.1)
        return list
    }
}

/// Where the pocket digital camera's parts are on the cover, upright (from
/// a ShellPlan) or across (from a ShellAcrossPlan): the same parts both
/// ways, each laid out for its hold (mock/pocket3.js).
struct DigiLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    var u: CGFloat = 1
    /// The LCD's black glass, and the screen in it.
    var glass = CGRect.zero
    var screen = CGRect.zero
    /// ZERO (from its leading edge) and the lamp beside it (.zero: no room).
    var name = CGRect.zero
    var nameSize: CGFloat = 12.5
    var lamp = CGPoint.zero
    var lampRadius: CGFloat = 2.2
    /// 拍照 / 录像 (with the room over its slot for its two small pictures),
    /// ▶ 回放, W | T.
    var slide = CGRect.zero
    var slideHead: CGFloat = 28
    var play = CGRect.zero
    var zoom = CGRect.zero
    /// The four small keys: 菜单, 显示, 日期, 比例 (round ones held across).
    var keys: [CGRect] = []
    var roundKeys = false
    /// − 曝光 ＋.
    var exposure = CGRect.zero
    /// The ring: its place (all four sides are touched inside it), its
    /// middle and radius there, each side's place there (up, right, down,
    /// left), how far out the words stand and how large; the arrowheads.
    var ring = CGRect.zero
    var ringCentre = CGPoint.zero
    var ringRadius: CGFloat = 76
    var sides: [CGRect] = []
    var wordsAt: CGFloat = 49
    var wordSize: CGFloat = 11
    var marks = true
    /// SET in the ring's middle.
    var hub = CGRect.zero
    /// The lenses: the strip, one key, the gap between two, the lines, and
    /// how much taller the one in use stands.
    var lenses = CGRect.zero
    var lensSize = CGSize(width: 67.6, height: 48)
    var lensGap: CGFloat = 6
    var lensLines = 1
    var lensGrow: CGFloat = 4
    var lensPadding: CGFloat = 4
    /// 内 / 外 (round upright, its word printed under it), the speaker's
    /// holes (the first of them).
    var flip = CGRect.zero
    var flipCaption = CGRect.zero
    var grille = CGPoint.zero
    /// The rubber thumb rest where the Camera Control's overlay comes in.
    var pad = CGRect.zero
    /// The shutter, and the words under it in 回放.
    var shutter = CGRect.zero
    var shutterCaption = CGRect.zero
    /// The colour's dot and the sticker beside it (.zero: no room for them).
    var tint = CGRect.zero
    var sticker = CGRect.zero
    var screws: [CGPoint] = []
    var stickers: [DigiSticker] = []
}

extension ShellPlan {
    /// The pocket digital camera's parts, upright: ZERO and the lamp along
    /// the top edge, the LCD under its glass, the rows of keys under it
    /// (mock/pocket3.js's points from the keys' top), the lenses; in the
    /// strip 内 / 外, the speaker's holes, the colour's dot and the sticker,
    /// the thumb rest where the Camera Control's overlay comes in, and the
    /// shutter under it.
    var digi: DigiLayout {
        var l = DigiLayout()
        let k = keysTop, strip = back.strip, mid = strip.midX
        let floor = back.keepOut.map(\.maxY).max() ?? top
        l.canvas = back.canvas
        l.u = u
        l.glass = surround
        l.screen = box
        l.name = CGRect(x: x(34), y: top - 6, width: 110, height: 19)
        l.lamp = CGPoint(x: x(372), y: top + 3.5)
        l.slide = block(20, 0, 96, 62)
        l.play = block(126, 18, 86, 46)
        l.zoom = block(222, 18, 160, 46)
        l.keys = [block(20, 80, 94, 46), block(120, 80, 94, 46), block(20, 133, 94, 46), block(120, 133, 94, 46)]
        l.exposure = block(20, 186, 194, 46)
        // The ring: its sides as the drawing has them (their heights as they
        // are; on a narrower column never under 44 points across, nor over SET).
        let r: CGFloat = 76 * u
        let middle = CGPoint(x: x(300), y: k + 156)
        l.ring = CGRect(x: middle.x - r - 6, y: middle.y - 82, width: 2 * r + 12, height: 164)
        let c = CGPoint(x: r + 6, y: 82)
        l.ringCentre = c
        l.ringRadius = r
        let upWidth = max(44, 56 * u), sideWidth = max(44, 48 * u), sideGap = max(22.5, 28 * u)
        let up = CGRect(x: c.x - upWidth / 2, y: c.y - 76, width: upWidth, height: 48)
        let right = CGRect(x: c.x + sideGap, y: c.y - 22, width: sideWidth, height: 44)
        let down = CGRect(x: c.x - upWidth / 2, y: c.y + 28, width: upWidth, height: 48)
        let left = CGRect(x: c.x - sideGap - sideWidth, y: c.y - 22, width: sideWidth, height: 44)
        l.sides = [up, right, down, left]
        l.wordsAt = (28 + r) / 2 - 3
        l.hub = CGRect(x: middle.x - 22, y: middle.y - 22, width: 44, height: 44)
        l.lenses = CGRect(x: x(16), y: k + 244, width: 368 * u, height: 68)
        l.lensSize = CGSize(width: 67.6 * u, height: 48)
        l.lensGap = 6 * u
        l.lensPadding = 4 * u
        // The strip: 内 / 外 under the camera, its word, the holes.
        let flipY = max(top + 146, floor + 60)
        l.flip = CGRect(x: mid - 24, y: flipY - 24, width: 48, height: 48)
        l.flipCaption = CGRect(x: mid - 34, y: flipY + 30.5, width: 68, height: 13)
        l.grille = CGPoint(x: mid - 15, y: flipY + 72)
        if let zone = back.overlay {
            let w = min(61, strip.width)
            l.pad = CGRect(x: mid - w / 2, y: zone.minY + 6.5, width: w, height: max(0, zone.height - 11))
        }
        l.shutter = shutter
        l.shutterCaption = CGRect(x: mid - 40, y: shutter.midY + 38, width: 80, height: 14)
        // The colour's dot and the sticker, side by side under the holes (one
        // over the other where the strip is narrow).
        let rowTop = flipY + 94
        let rowFloor = (back.overlay?.minY ?? shutter.minY) - 1
        let reach = back.canvas.width - strip.minX
        if rowFloor - rowTop >= 44, reach >= 90 {
            let x0 = min(max(strip.minX, mid - 45), back.canvas.width - 90)
            l.tint = CGRect(x: x0 + 15, y: rowTop + 15, width: 14, height: 14)
            l.sticker = CGRect(x: x0 + 58, y: rowTop + 12, width: 20, height: 20)
        } else if rowFloor - rowTop >= 94, reach >= 44 {
            let x0 = min(max(strip.minX, mid - 22), back.canvas.width - 44)
            l.tint = CGRect(x: x0 + 15, y: rowTop + 15, width: 14, height: 14)
            l.sticker = CGRect(x: x0 + 12, y: rowTop + 62, width: 20, height: 20)
        }
        let low = min(keysBottom + 30, back.canvas.height - 6)
        l.screws = [CGPoint(x: x(30), y: low), CGPoint(x: x(372), y: low)]
        // The stickers, where the drawing puts them (the three in the strip
        // above the holes, the colour's dot and the sticker being under them).
        var list: [DigiSticker] = []
        func add(_ kind: DigiSticker.Kind, _ at: CGPoint, _ size: CGFloat, _ colour: ShellTone, _ turn: Double = 0) {
            list.append(DigiSticker(kind: kind, at: at, size: size, colour: colour, turn: turn))
        }
        add(.star, CGPoint(x: x(116), y: top + 3), 6.5, DigiSticker.lemon, 0.2)
        add(.dot, CGPoint(x: x(136), y: top + 5), 3.2, DigiSticker.pink)
        add(.heart, CGPoint(x: x(156), y: top + 3), 5.5, DigiSticker.rose, -0.15)
        add(.heart, CGPoint(x: mid - 20, y: flipY + 56), 7, DigiSticker.pink, -0.25)
        add(.star, CGPoint(x: mid + 20, y: flipY + 53), 7, DigiSticker.lemon, 0.25)
        add(.dot, CGPoint(x: mid + 1, y: flipY + 60), 3.4, DigiSticker.sky)
        add(.spark, CGPoint(x: x(236), y: k + 76), 5.5, DigiSticker.white)
        add(.dot, CGPoint(x: x(370), y: k + 78), 3.2, DigiSticker.pink)
        add(.dot, CGPoint(x: x(232), y: k + 236), 3.2, DigiSticker.sky)
        add(.heart, CGPoint(x: x(368), y: k + 236), 5.5, DigiSticker.pink, 0.2)
        l.stickers = list + DigiSticker.row(from: CGPoint(x: x(14), y: keysBottom + 24), width: 372 * u)
        return l
    }
}

extension ShellAcrossPlan {
    /// The pocket digital camera's parts with the cover held across: the
    /// LCD at the left; in the band ZERO, the colour's dot, the sticker and
    /// the lamp in its longer clear run, the thumb rest in the overlay's
    /// place, the shutter in the other run; in the keys' column W | T and
    /// ▶ 回放, the switch and − 曝光 ＋, the ring with a round key at each
    /// of its corners, two lines of lenses and a tall 内 / 外 beside them.
    var digi: DigiLayout {
        var l = DigiLayout()
        let run = back.run, band = back.band
        let cw: CGFloat = 188.0 / 3, c1: CGFloat = cw + 6, c2: CGFloat = 2 * cw + 12
        l.across = true
        l.canvas = back.canvas
        l.glass = surround
        l.screen = box
        l.nameSize = 15
        l.lampRadius = 2.4
        // The band: what the run has room for (the shutter takes its end
        // where the other run is too short for it).
        let room: CGFloat = back.spare.width >= 70 ? run.width : run.width - 96
        // Their line: the run's middle; higher where the band lies along the
        // lower edge (the colour's dot and the sticker clear of its last 34 points).
        let line: CGFloat = band.minY > 0 ? band.minY + 22 : run.midY
        if room >= 80 { l.name = CGRect(x: run.minX + 6, y: line - 9, width: 76, height: 22) }
        if room >= 100 { l.lamp = CGPoint(x: run.minX + room - 8.4, y: line + 2) }
        if room >= 172 {
            l.tint = CGRect(x: run.minX + 91, y: line - 7, width: 14, height: 14)
            l.sticker = CGRect(x: run.minX + 138, y: line - 10, width: 20, height: 20)
        }
        if let zone = back.overlay, zone.width > 30 {
            l.pad = CGRect(x: zone.minX + 4.6, y: band.minY + 8, width: max(0, zone.width - 8), height: 58)
        }
        l.shutter = shutter
        // The column (mock/pocket3.js's points from its corner).
        l.zoom = key(0, 0, 2 * cw + 6, 44)
        l.play = key(c2, 0, cw, 44)
        l.slide = key(0, 50, cw, 44)
        l.slideHead = 16
        l.exposure = key(c1, 50, 2 * cw + 6, 44)
        l.ring = key(0, 100, 200, 150)
        l.ringCentre = CGPoint(x: 100, y: 75)
        l.ringRadius = 57
        let up = CGRect(x: c1, y: 0, width: cw, height: 47)
        let right = CGRect(x: 128, y: 53, width: 72, height: 44)
        let down = CGRect(x: c1, y: 103, width: cw, height: 47)
        let left = CGRect(x: 0, y: 53, width: 72, height: 44)
        l.sides = [up, right, down, left]
        l.wordsAt = 42.5
        l.wordSize = 10
        l.marks = false
        l.hub = key(78, 153, 44, 44)
        l.keys = [key(9, 101, 44, 44), key(147, 101, 44, 44), key(9, 205, 44, 44), key(147, 205, 44, 44)]
        l.roundKeys = true
        l.lenses = key(0, 252, c1 + cw, 104)
        l.lensSize = CGSize(width: cw, height: 44)
        l.lensGap = 6
        l.lensLines = 2
        l.lensGrow = 3
        l.lensPadding = 0
        l.flip = key(c2, 257, cw, 94)
        // The stickers: a row under the screen, where there is room before
        // the band or the edge.
        let base = l.glass.maxY + 12
        let limit = (band.minY > l.glass.maxY ? band.minY : back.canvas.height) - 10
        if base + 10 <= limit { l.stickers = DigiSticker.row(from: CGPoint(x: l.glass.minX, y: base), width: l.glass.width) }
        return l
    }
}

/// Brushed metal's fine lines across a rect (a seed of its own for each
/// part: the same lines each time it is drawn).
private enum DigiMetal {
    static func brush(_ context: GraphicsContext, _ rect: CGRect, _ amount: Double, seed start: UInt32) {
        var seed = start
        for _ in 0..<max(0, Int(rect.height * 1.6)) {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            let y = rect.minY + CGFloat((seed >> 8) & 0xFFFF) / 65535 * rect.height
            seed = seed &* 1_664_525 &+ 1_013_904_223
            let a = Double((seed >> 8) & 0xFF) / 255 * amount
            let ink = (seed >> 20) & 1 == 0 ? Color.white : Color.black
            context.fill(Path(CGRect(x: rect.minX, y: y, width: rect.width, height: 0.5)), with: .color(ink.opacity(a)))
        }
    }
    /// Aluminium lit from above: brighter at the top, darker at the foot.
    static func lit(_ height: CGFloat) -> GraphicsContext.Shading {
        let al = DigiPaint.aluminium
        return .linearGradient(Gradient(colors: [al.color(0.7), al.color(0), al.color(-0.3)]), startPoint: .zero, endPoint: CGPoint(x: 0, y: height))
    }
}

/// The pocket digital camera's body, drawn as the picture of it was
/// (mock/pocket3.js, part for part): the bright frame all the way round,
/// the plate of brushed metal in its colour let into it (lit from above, a
/// sheen across it, the hinge's side in shade), the speaker's holes, the
/// rubber thumb rest with its ribs where the Camera Control's overlay comes
/// in, two screws, and the stickers while they are on. (The LCD's glass
/// lies over the picture's edge: DigiGlass.) Drawn once for a colour.
private struct DigiBackdrop: View, Equatable {
    var layout: DigiLayout
    var paint: DigiPaint
    var hinge: CGRect
    var stickers: Bool
    var body: some View {
        Canvas { context, size in
            Self.border(context, size)
            Self.plate(context, size, paint, hinge)
            if !layout.across, layout.grille != .zero { Self.grille(context, layout.grille) }
            Self.pad(context, layout, paint)
            for at in layout.screws { Self.screw(context, at) }
            if stickers {
                for one in layout.stickers { Self.sticker(context, one) }
            }
        }
        .accessibilityHidden(true)
    }

    /// The frame of bright metal round the plate: its outer edge lit, its rim dark.
    private static func border(_ context: GraphicsContext, _ size: CGSize) {
        let whole = CGRect(origin: .zero, size: size)
        context.fill(Path(whole), with: .linearGradient(ClamPaint.chrome, startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
        context.stroke(Path(roundedRect: whole.insetBy(dx: 1, dy: 1), cornerRadius: 45), with: .color(Color.white.opacity(0.7)), lineWidth: 1)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 0.5, dy: 0.5), cornerRadius: 46), with: .color(Color.black.opacity(0.5)), lineWidth: 1)
    }

    /// The plate in its colour, a dark line round it; brushed across, a sheen, the hinge's shade.
    private static func plate(_ context: GraphicsContext, _ size: CGSize, _ paint: DigiPaint, _ hinge: CGRect) {
        let rect = CGRect(x: 6, y: 6, width: max(0, size.width - 12), height: max(0, size.height - 12)), tone = paint.body
        let shape = Path(roundedRect: rect, cornerRadius: 40)
        context.fill(Path(roundedRect: rect.insetBy(dx: -1, dy: -1), cornerRadius: 41), with: .color(Color.black.opacity(0.5)))
        let fill = Gradient(stops: [Gradient.Stop(color: tone.color(0.2), location: 0), Gradient.Stop(color: tone.color(0.05), location: 0.2),
                                    Gradient.Stop(color: tone.color(0), location: 0.55), Gradient.Stop(color: tone.color(-0.2), location: 1)])
        context.fill(shape, with: .linearGradient(fill, startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height)))
        var inner = context
        inner.clip(to: shape)
        DigiMetal.brush(inner, rect, paint.light ? 0.07 : 0.11, seed: 0x5EED_0B0D)
        let sheen = Gradient(stops: [Gradient.Stop(color: Color.white.opacity(0.12), location: 0), Gradient.Stop(color: Color.white.opacity(0), location: 0.22),
                                     Gradient.Stop(color: Color.white.opacity(0.13), location: 0.5), Gradient.Stop(color: Color.white.opacity(0), location: 0.72),
                                     Gradient.Stop(color: Color.black.opacity(0.14), location: 1)])
        inner.fill(Path(CGRect(origin: .zero, size: size)), with: .linearGradient(sheen, startPoint: .zero, endPoint: CGPoint(x: size.width, y: 0)))
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let near = tall ? hinge.midX < size.width / 2 : hinge.midY < size.height / 2
            let edge: CGFloat = near ? 0 : (tall ? size.width : size.height)
            let inward: CGFloat = near ? 16 : -16
            let from = tall ? CGPoint(x: edge, y: 0) : CGPoint(x: 0, y: edge)
            let to = tall ? CGPoint(x: edge + inward, y: 0) : CGPoint(x: 0, y: edge + inward)
            let shade = tall ? CGRect(x: min(edge, edge + inward), y: 0, width: 16, height: size.height) : CGRect(x: 0, y: min(edge, edge + inward), width: size.width, height: 16)
            inner.fill(Path(shade), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.3), Color.black.opacity(0)]), startPoint: from, endPoint: to))
        }
        context.stroke(Path(roundedRect: rect.insetBy(dx: 0.7, dy: 0.7), cornerRadius: 39.3), with: .color(Color.white.opacity(0.3)), lineWidth: 1)
    }

    /// The speaker's holes: six across, four down.
    private static func grille(_ context: GraphicsContext, _ first: CGPoint) {
        for i in 0..<6 {
            for j in 0..<4 {
                let hole = CGRect(x: first.x + CGFloat(i) * 6 - 1.2, y: first.y + CGFloat(j) * 6 - 1.2, width: 2.4, height: 2.4)
                context.fill(Path(ellipseIn: hole), with: .color(Color.black.opacity(0.6)))
                context.stroke(Path(ellipseIn: hole.offsetBy(dx: 0, dy: 0.6)), with: .color(Color.white.opacity(0.18)), lineWidth: 0.5)
            }
        }
    }

    /// The thumb rest: rubber in the plate's colour nearly black, a light lip round it, its ribs.
    private static func pad(_ context: GraphicsContext, _ layout: DigiLayout, _ paint: DigiPaint) {
        let rect = layout.pad
        guard rect.width > 8, rect.height > 8 else { return }
        let rubber = paint.rubber
        context.fill(Path(roundedRect: CGRect(x: rect.minX - 1, y: rect.minY - 1, width: rect.width + 2, height: rect.height + 2.6), cornerRadius: 13),
                     with: .color(Color.white.opacity(0.22)))
        let shape = Path(roundedRect: rect, cornerRadius: 12)
        context.fill(shape, with: .linearGradient(Gradient(colors: [rubber.color(-0.2), rubber.color(0.06)]),
                                                  startPoint: CGPoint(x: 0, y: rect.minY), endPoint: CGPoint(x: 0, y: rect.maxY)))
        context.stroke(shape, with: .color(Color.black.opacity(0.7)), lineWidth: 1)
        let groove = Color.black.opacity(0.5), lip = Color.white.opacity(0.1)
        if layout.across {
            var x = rect.minX + 7
            while x < rect.maxX - 7 {
                context.fill(Path(roundedRect: CGRect(x: x, y: rect.minY + 4, width: 2.4, height: max(0, rect.height - 8)), cornerRadius: 1.2), with: .color(groove))
                context.fill(Path(roundedRect: CGRect(x: x + 2.4, y: rect.minY + 4, width: 1.4, height: max(0, rect.height - 8)), cornerRadius: 0.7), with: .color(lip))
                x += 8
            }
        } else {
            var y = rect.minY + 7
            while y < rect.maxY - 6 {
                context.fill(Path(roundedRect: CGRect(x: rect.minX + 4, y: y, width: max(0, rect.width - 7), height: 2.4), cornerRadius: 1.2), with: .color(groove))
                context.fill(Path(roundedRect: CGRect(x: rect.minX + 4, y: y + 2.4, width: max(0, rect.width - 7), height: 1.4), cornerRadius: 0.7), with: .color(lip))
                y += 8
            }
        }
    }

    private static func screw(_ context: GraphicsContext, _ at: CGPoint) {
        let r: CGFloat = 2.6
        let head = CGRect(x: at.x - r, y: at.y - r, width: 2 * r, height: 2 * r)
        context.fill(Path(ellipseIn: head), with: .radialGradient(Gradient(colors: [Color(white: 0.91), Color(red: 0.333, green: 0.345, blue: 0.365)]),
                                                                  center: CGPoint(x: at.x - 1, y: at.y - 1), startRadius: 0.5, endRadius: r * 1.3))
        context.stroke(Path(ellipseIn: head), with: .color(Color.black.opacity(0.6)), lineWidth: 0.6)
        var slot = Path()
        slot.move(to: CGPoint(x: at.x - r * 0.6, y: at.y - r * 0.3))
        slot.addLine(to: CGPoint(x: at.x + r * 0.6, y: at.y + r * 0.3))
        context.stroke(slot, with: .color(Color.black.opacity(0.65)), lineWidth: 0.9)
    }

    /// A sticker: its white border and shadow, its colour lighter above (a
    /// dot a little sphere), the bow's knot.
    static func sticker(_ context: GraphicsContext, _ one: DigiSticker) {
        let s = one.size, c = one.colour
        let place = CGAffineTransform(rotationAngle: CGFloat(one.turn)).concatenating(CGAffineTransform(translationX: one.at.x, y: one.at.y))
        let shape = DigiSticker.outline(one.kind, s).applying(place)
        let round = one.kind == .dot
        var lifted = context
        lifted.addFilter(.shadow(color: Color.black.opacity(0.35), radius: 1.5, x: 0, y: 1.4))
        if !round { lifted.stroke(shape, with: .color(Color.white), style: StrokeStyle(lineWidth: 3.2, lineJoin: .round)) }
        lifted.fill(shape, with: .color(c.color()))
        if round {
            let sphere = Gradient(stops: [Gradient.Stop(color: Color.white, location: 0), Gradient.Stop(color: c.color(0.35), location: 0.35), Gradient.Stop(color: c.color(-0.2), location: 1)])
            context.fill(shape, with: .radialGradient(sphere, center: CGPoint(x: one.at.x - s * 0.35, y: one.at.y - s * 0.4), startRadius: s * 0.1, endRadius: s * 1.2))
            context.stroke(shape, with: .color(Color.white.opacity(0.8)), lineWidth: 0.9)
        } else {
            context.fill(shape, with: .linearGradient(Gradient(colors: [c.color(0.4), c.color()]),
                                                      startPoint: CGPoint(x: one.at.x, y: one.at.y - s), endPoint: CGPoint(x: one.at.x, y: one.at.y + s)))
        }
        if one.kind == .bow {
            let knot = Path(ellipseIn: CGRect(x: one.at.x - s * 0.3, y: one.at.y - s * 0.3, width: s * 0.6, height: s * 0.6))
            context.fill(knot, with: .color(c.color(0.5)))
            context.stroke(knot, with: .color(Color.white), lineWidth: 1.2)
        }
    }
}

/// What lies over the picture's edge: the LCD's surround of bright metal
/// and the black glass round the picture (over the picture's own bezel).
/// Nothing is pressed through it.
private struct DigiGlass: View, Equatable {
    var glass: CGRect
    /// The picture, seen through the glass.
    var hole: CGRect
    var body: some View {
        Canvas { context, size in
            guard glass.width > 0, glass.height > 0 else { return }
            let ring = glass.insetBy(dx: -1.6, dy: -1.6)
            let pane = Path(roundedRect: glass, cornerRadius: 9)
            var surround = Path(roundedRect: ring, cornerRadius: 10.6)
            surround.addPath(pane)
            context.fill(surround, with: .linearGradient(ClamPaint.chrome, startPoint: ring.origin, endPoint: CGPoint(x: ring.maxX, y: ring.maxY)), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: ring, cornerRadius: 10.6), with: .color(Color.black.opacity(0.45)), lineWidth: 0.8)
            var rim = pane
            if hole.width > 0, hole.height > 0 { rim.addPath(Path(roundedRect: hole, cornerRadius: 3, style: .continuous)) }
            context.fill(rim, with: .linearGradient(Gradient(colors: [Color(red: 0.090, green: 0.098, blue: 0.118), Color(red: 0.027, green: 0.031, blue: 0.039)]),
                                                    startPoint: CGPoint(x: 0, y: glass.minY), endPoint: CGPoint(x: 0, y: glass.maxY)), style: FillStyle(eoFill: true))
            context.stroke(pane, with: .color(Color.black.opacity(0.9)), lineWidth: 1)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// What the LCD shows over the picture while taking pictures, in its own
/// letters: P and the picture's shape, the battery; the body's name and how
/// many pictures are left. (VoiceOver and the tests read the picture's own.)
private struct DigiReadout: View {
    var shape: String
    var body: some View {
        // Only the mode, the shape and the battery: the body's name and
        // what is left are in the picture's own chips just under this line,
        // and the lower right corner is where a body's printed date goes.
        VStack(spacing: 0) {
            HStack(spacing: 20) {
                Text(verbatim: "P").font(.system(size: 13.5, weight: .heavy, design: .monospaced))
                Text(verbatim: shape).font(.system(size: 11.5, weight: .heavy, design: .monospaced))
                Spacer(minLength: 0)
                ClamBattery()
            }
            .padding(.leading, 10)
            .padding(.trailing, 14)
            .padding(.top, 8)
            Spacer(minLength: 0)
        }
        .foregroundStyle(Color.white)
        .shadow(color: Color.black.opacity(0.9), radius: 2)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// What the LCD shows over the picture in 回放, in its own letters: the
/// green ▶ and the picture's number (多张 over the nine), its place — read
/// by VoiceOver and the tests — when it was taken, its shape.
private struct DigiPlayReadout: View {
    var number: String
    var place: String
    var when: String
    var shape: String
    var many: Bool
    var body: some View {
        VStack(spacing: 0) {
            HStack(spacing: many ? 6 : 8) {
                ClamArrow(way: 1).fill(Color(red: 0.239, green: 0.863, blue: 0.518))
                    .frame(width: many ? 9 : 12, height: many ? 12 : 14)
                    .accessibilityHidden(true)
                Text(verbatim: number).accessibilityHidden(true)
                Spacer(minLength: 0)
                Text(verbatim: place).monospacedDigit()
                    .accessibilityIdentifier("camera-deck-album-position")
            }
            .font(.system(size: many ? 11 : 11.5, weight: .heavy, design: .monospaced))
            .padding(.leading, 11)
            .padding(.trailing, 12)
            .padding(.top, many ? 5 : 9)
            Spacer(minLength: 0)
            if !many {
                HStack(spacing: 8) {
                    Text(verbatim: when)
                    Spacer(minLength: 0)
                    Text(verbatim: shape)
                }
                .font(.system(size: 11, weight: .heavy, design: .monospaced))
                .padding(.horizontal, 12)
                .padding(.bottom, 7)
                .accessibilityHidden(true)
            }
        }
        .foregroundStyle(Color.white)
        .shadow(color: Color.black.opacity(0.9), radius: 2)
        .lineLimit(1)
        .allowsHitTesting(false)
    }
}

/// ZERO printed on the plate, and the lamp beside it.
private struct DigiMarks: View {
    var digi: DigiLayout
    var paint: DigiPaint
    var lamp: ShellTone
    var body: some View {
        ZStack(alignment: .topLeading) {
            if digi.name.width > 0 {
                Text(verbatim: "ZERO").font(.system(size: digi.nameSize, weight: .black, design: .rounded)).tracking(digi.nameSize * (digi.across ? 0.4 : 0.32))
                    .foregroundStyle(paint.print)
                    .lineLimit(1).fixedSize()
                    .frame(width: digi.name.width, height: digi.name.height, alignment: .leading)
                    .position(x: digi.name.midX, y: digi.name.midY)
            }
            if digi.lamp.x > 0 {
                DigiLamp(tone: lamp, radius: digi.lampRadius).frame(width: 14, height: 14).position(digi.lamp)
            }
        }
        .frame(width: digi.canvas.width, height: digi.canvas.height, alignment: .topLeading)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A small lamp in its dark ring, glowing.
private struct DigiLamp: View {
    var tone: ShellTone
    var radius: CGFloat
    var body: some View {
        ZStack {
            Circle().fill(Color.black.opacity(0.6)).frame(width: 2 * radius + 2.4, height: 2 * radius + 2.4)
            Circle().fill(RadialGradient(colors: [Color.white, tone.color(), tone.color(-0.3)], center: UnitPoint(x: 0.35, y: 0.35), startRadius: 0.2, endRadius: radius))
                .frame(width: 2 * radius, height: 2 * radius)
                .shadow(color: tone.color(), radius: 3)
        }
    }
}

/// A key's face of brushed aluminium: brighter at its top, its fine lines,
/// a bright rim and a faint line inside it; darker while down.
private struct DigiKeyFace: View, Equatable {
    var radius: CGFloat
    var pressed: Bool
    var body: some View {
        Canvas { context, size in
            let rect = CGRect(origin: .zero, size: size)
            let r = min(radius, min(size.width, size.height) / 2)
            let shape = Path(roundedRect: rect, cornerRadius: r, style: .continuous)
            context.fill(shape, with: DigiMetal.lit(size.height))
            var inner = context
            inner.clip(to: shape)
            DigiMetal.brush(inner, rect, 0.08, seed: 41)
            context.stroke(Path(roundedRect: rect.insetBy(dx: 0.7, dy: 0.7), cornerRadius: max(0, r - 0.7), style: .continuous),
                           with: .color(Color.white.opacity(pressed ? 0.35 : 0.8)), lineWidth: 1)
            context.stroke(Path(roundedRect: rect.insetBy(dx: 2.6, dy: 2.6), cornerRadius: max(2, r - 2.6), style: .continuous),
                           with: .color(Color.black.opacity(0.07)), lineWidth: 0.8)
            if pressed { context.fill(shape, with: .color(Color.black.opacity(0.12))) }
        }
    }
}

/// A round key's face: aluminium turned on a lathe, the light going round
/// it and flat in its middle, its fine circles, a bright rim.
private struct DigiRoundFace: View, Equatable {
    var turn: Double
    var body: some View {
        ZStack {
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(turn)))
            Canvas { context, size in
                let r = min(size.width, size.height) / 2, c = CGPoint(x: size.width / 2, y: size.height / 2)
                func circle(_ k: CGFloat) -> Path { Path(ellipseIn: CGRect(x: c.x - k, y: c.y - k, width: 2 * k, height: 2 * k)) }
                let al = DigiPaint.aluminium.color()
                let flat = Gradient(stops: [Gradient.Stop(color: al, location: 0), Gradient.Stop(color: al.opacity(0.85), location: 0.35), Gradient.Stop(color: al.opacity(0), location: 1)])
                context.fill(circle(r), with: .radialGradient(flat, center: c, startRadius: 0, endRadius: r))
                var k = r - 2.5
                while k > 2 {
                    context.stroke(circle(k), with: .color(Color.black.opacity(0.04)), lineWidth: 0.7)
                    k -= 2.5
                }
                context.stroke(circle(r - 0.7), with: .color(Color.white.opacity(0.8)), lineWidth: 1)
            }
        }
    }
}

/// A key of brushed aluminium, or a round one of turned aluminium, in its
/// well: it goes down under the finger with a metal key's click (and as
/// it goes, not when it is let go).
struct DigiKeyStyle: ButtonStyle {
    var radius: CGFloat = 14
    var round = false
    /// Where the light starts round a turned key.
    var turn: Double = -2.2
    var travel: CGFloat = 1.5
    var sound: ConsoleSound = .keyMetal
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View { DigiKeyBody(configuration: configuration, style: self) }
}
private struct DigiKeyBody: View {
    let configuration: ButtonStyle.Configuration
    let style: DigiKeyStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .foregroundStyle(DigiPaint.ink)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(face(down))
            .offset(y: down ? style.travel : 0)
            // The well it sits in (which does not go down with it).
            .background(well)
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
    @ViewBuilder private func face(_ down: Bool) -> some View {
        if style.round {
            DigiRoundFace(turn: style.turn).equatable()
                .brightness(down ? -0.07 : 0)
                .shadow(color: Color.black.opacity(down ? 0.2 : 0.5), radius: down ? 0.6 : 1.75, y: down ? 0.5 : 1.8)
        } else {
            DigiKeyFace(radius: style.radius, pressed: down).equatable()
                .shadow(color: Color.black.opacity(down ? 0.2 : 0.5), radius: down ? 0.6 : 1.75, y: down ? 0.5 : 1.8)
        }
    }
    @ViewBuilder private var well: some View {
        if style.round {
            Circle().fill(Color.black.opacity(0.5)).padding(-1.8).offset(y: 0.8)
        } else {
            RoundedRectangle(cornerRadius: style.radius + 1.6, style: .continuous).fill(Color.black.opacity(0.5))
                .padding(EdgeInsets(top: -1.3, leading: -1.6, bottom: -2.7, trailing: -1.6))
        }
    }
}

/// A part of a key that is drawn round it (the rocker's ends, the ring's
/// sides): pressed as a key, with its click and its feel; it tells the key
/// it belongs to that it is down.
struct DigiTouchStyle: ButtonStyle {
    var sound: ConsoleSound = .keyMetal
    var haptic: HapticPart = .sliderNotch
    var press: (Bool) -> Void = { _ in }
    func makeBody(configuration: Configuration) -> some View { DigiTouchBody(configuration: configuration, style: self) }
}
private struct DigiTouchBody: View {
    let configuration: ButtonStyle.Configuration
    let style: DigiTouchStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .padding(room)
            .contentShape(Rectangle())
            .onChange(of: down) { _, now in
                style.press(now)
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// A lens as a small key of smoked plastic; the one in use lit amber from
/// behind. It goes down with a plastic key's knock.
private struct DigiLensStyle: ButtonStyle {
    var on: Bool
    /// What is printed on a lens key: dark on the lit one, pale on the smoked ones.
    static func ink(_ on: Bool) -> Color { on ? Color(red: 0.227, green: 0.141, blue: 0.0) : Color(red: 0.925, green: 0.933, blue: 0.953).opacity(0.9) }
    func makeBody(configuration: Configuration) -> some View { DigiLensBody(configuration: configuration, on: on) }
}
private struct DigiLensBody: View {
    let configuration: ButtonStyle.Configuration
    let on: Bool
    var body: some View {
        let down = configuration.isPressed
        let r: CGFloat = on ? 13 : 11
        let shape = RoundedRectangle(cornerRadius: r, style: .continuous)
        let litFace = LinearGradient(stops: [Gradient.Stop(color: Color(red: 1.0, green: 0.953, blue: 0.812), location: 0), Gradient.Stop(color: Color(red: 1.0, green: 0.769, blue: 0.302), location: 0.16),
                                         Gradient.Stop(color: Color(red: 0.969, green: 0.604, blue: 0.071), location: 1)], startPoint: .top, endPoint: .bottom)
        let smokedFace = LinearGradient(stops: [Gradient.Stop(color: Color(red: 0.353, green: 0.365, blue: 0.400), location: 0), Gradient.Stop(color: Color(red: 0.173, green: 0.180, blue: 0.208), location: 0.14),
                                            Gradient.Stop(color: Color(red: 0.090, green: 0.094, blue: 0.110), location: 1)], startPoint: .top, endPoint: .bottom)
        let ink: Color = DigiLensStyle.ink(on)
        let glow: Color = on ? DigiPaint.lit.opacity(down ? 0.4 : 0.85) : Color.black.opacity(down ? 0.2 : 0.45)
        let blur: CGFloat = on ? 5 : (down ? 0.6 : 1.5)
        let drop: CGFloat = on ? 0 : (down ? 0.5 : 1.5)
        configuration.label
            .foregroundStyle(ink)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background {
                ZStack {
                    if on { shape.fill(litFace) } else { shape.fill(smokedFace) }
                    shape.strokeBorder(Color.white.opacity(on ? 0.75 : 0.22), lineWidth: 1)
                    if down { shape.fill(Color.black.opacity(0.14)) }
                }
                .shadow(color: glow, radius: blur, y: drop)
            }
            .offset(y: down ? 1.4 : 0)
            .background(RoundedRectangle(cornerRadius: r + 1.4, style: .continuous).fill(Color.black.opacity(0.5))
                .padding(EdgeInsets(top: -1.1, leading: -1.4, bottom: -2.5, trailing: -1.4)))
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.keyRubber, scale: 0.7)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// The shutter going down: the dished button sinks in its chrome collar
/// (the collar stays).
private struct DigiShutterStyle: ButtonStyle {
    var haptic: HapticPart = .faceButton
    func makeBody(configuration: Configuration) -> some View { DigiShutterBody(configuration: configuration, style: self) }
}
