                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}
/// The shutter's button: metal turned on a lathe, dished (lit at its upper
/// left), its fine circles, a bright rim.
private struct DigiShutterFace: View {
    var body: some View {
        ZStack {
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(0.9)))
            Canvas { context, size in
                let r = min(size.width, size.height) / 2, c = CGPoint(x: size.width / 2, y: size.height / 2)
                func circle(_ k: CGFloat) -> Path { Path(ellipseIn: CGRect(x: c.x - k, y: c.y - k, width: 2 * k, height: 2 * k)) }
                let light = Gradient(stops: [Gradient.Stop(color: Color.white.opacity(0.5), location: 0), Gradient.Stop(color: Color.white.opacity(0), location: 0.6),
                                             Gradient.Stop(color: Color.black.opacity(0.18), location: 1)])
                context.fill(circle(r), with: .radialGradient(light, center: CGPoint(x: c.x - r * 0.3, y: c.y - r * 0.35), startRadius: r * 0.1, endRadius: r * 1.1))
                var k = r - 3
                while k > 2 {
                    context.stroke(circle(k), with: .color(Color.black.opacity(0.07)), lineWidth: 0.7)
                    k -= 3
                }
                context.stroke(circle(r - 0.7), with: .color(Color.white.opacity(0.7)), lineWidth: 0.9)
            }
        }
    }
}

/// The shutter as a key: what it shows is the deck's own (a red dot for a
/// video, the square and the time while one runs); in 回放, nothing.
private struct DigiShutterKey: View {
    var video = false
    var recording = false
    var time = ""
    var haptic: HapticPart = .faceButton
    var action: () -> Void
    var body: some View {
        Button(action: action) {
            GeometryReader { geo in
                let d = min(geo.size.width, geo.size.height)
                ZStack {
                    if video, recording {
                        VStack(spacing: 2) {
                            RoundedRectangle(cornerRadius: d * 0.05, style: .continuous).fill(CameraShutterFace.red).frame(width: d * 0.22, height: d * 0.22)
                            Text(verbatim: time).font(.system(size: 10.5, weight: .heavy, design: .rounded)).monospacedDigit().foregroundStyle(DigiPaint.ink)
                        }
                    } else if video {
                        Circle().fill(CameraShutterFace.red).frame(width: d * 0.28, height: d * 0.28)
                    }
                }
                .frame(width: geo.size.width, height: geo.size.height)
            }
        }
        .buttonStyle(DigiShutterStyle(haptic: haptic))
    }
}

/// The sticker by the colour's dot, as a key: a small star sticker of its
/// own, stuck on while the stickers are on, only its outline while they are off.
private struct DigiStickerKey: View {
    var on: Bool
    var action: () -> Void
    var body: some View {
        Button(action: action) { DigiStarMark(on: on).equatable() }
            .buttonStyle(DigiStickerStyle())
            .accessibilityLabel(String(localized: "贴纸"))
            .accessibilityValue(on ? String(localized: "开") : String(localized: "关"))
            .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-stickers")
    }
}
private struct DigiStarMark: View, Equatable {
    var on: Bool
    var body: some View {
        Canvas { context, size in
            let s = max(2, min(size.width, size.height) / 2 - 2)
            let place = CGAffineTransform(rotationAngle: 0.2).concatenating(CGAffineTransform(translationX: size.width / 2, y: size.height / 2))
            let star = DigiSticker.outline(.star, s).applying(place)
            let lemon = DigiSticker.lemon
            if on {
                var lifted = context
                lifted.addFilter(.shadow(color: Color.black.opacity(0.35), radius: 1.5, x: 0, y: 1.2))
                lifted.stroke(star, with: .color(Color.white), style: StrokeStyle(lineWidth: 2.6, lineJoin: .round))
                lifted.fill(star, with: .color(lemon.color()))
                context.fill(star, with: .linearGradient(Gradient(colors: [lemon.color(0.4), lemon.color()]),
                                                         startPoint: CGPoint(x: size.width / 2, y: 2), endPoint: CGPoint(x: size.width / 2, y: size.height - 2)))
            } else {
                context.stroke(star, with: .color(Color.white.opacity(0.85)), style: StrokeStyle(lineWidth: 1.4, lineJoin: .round, dash: [2.2, 1.6]))
                context.stroke(star, with: .color(Color.black.opacity(0.25)), style: StrokeStyle(lineWidth: 0.6, lineJoin: .round))
            }
        }
    }
}
private struct DigiStickerStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View { DigiStickerBody(configuration: configuration) }
}
private struct DigiStickerBody: View {
    let configuration: ButtonStyle.Configuration
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .scaleEffect(down ? 0.86 : 1)
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: 0.08), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.keySlide, scale: 0.7)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// What ▶ 回放 shows: ▶ in a frame; in 回放, a camera and 回去拍照 (its
/// words kept), the green lamp on it lit.
