/// One of the four small keys: its glyph, drawn as what it sets stands.
private struct DigiSmallKey: View {
    var glyph: ShellGlyph
    var round = false
    var label: String
    var value = ""
    var selected = false
    var identifier: String
    var action: () -> Void
    var body: some View {
        Button(action: action) {
            ShellGlyphView(glyph: glyph, size: round ? 16 : 20, ink: DigiPaint.ink, stacked: round)
                .padding(.horizontal, round ? 5 : 4)
        }
        .buttonStyle(DigiKeyStyle(radius: round ? 200 : 14, round: round))
        .accessibilityLabel(label)
        .accessibilityValue(value)
        .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
}

/// 菜单 (主菜单: a house), 显示 (水平仪), 日期 and 比例 (its frame and its
/// figures, under it on the round keys held across): each glyph drawn as
/// what it sets stands. In 回放 only 菜单 works; the others wait, and say why.
private struct DigiSmallKeys: View {
    @ObservedObject var model: CameraAppModel
    var digi: DigiLayout
    var play = false
    var why = ""
    var body: some View {
        let on = String(localized: "开"), off = String(localized: "关"), level = String(localized: "水平仪")
        let round = digi.roundKeys
        let levelState = model.leveler ? on : off
        let dateState = model.shooting.dateStamp ? on : off
        let shapeWord = CameraShellSkin.digital.shapeTitle
        let shapeWhy = play ? why : String(localized: "这个模式或机型只拍 4:3")
        ZStack(alignment: .topLeading) {
            if digi.keys.count == 4 {
                DigiSmallKey(glyph: .home, round: round, label: String(localized: "camera.home.pill"), identifier: "camera-deck-home") {
                    model.leave()
                }
                .deckKey(digi.keys[0])
                DigiSmallKey(glyph: .level(model.leveler), round: round, label: level, value: levelState, selected: model.leveler, identifier: "camera-deck-leveler") {
                    if play { model.say(why) } else { model.toggleLeveler() }
                }
                .deckDimmed(play, why: why)
                .deckKey(digi.keys[1])
                DigiSmallKey(glyph: .date(model.shooting.dateStamp), round: round, label: String(localized: "日期"), value: dateState, selected: model.shooting.dateStamp,
                             identifier: "camera-deck-date") {
                    if play { model.say(why) } else { model.toggleDateStamp() }
                }
                .deckDimmed(play, why: why)
                .deckKey(digi.keys[2])
                DigiSmallKey(glyph: .shape(model.shape), round: round, label: shapeWord, value: model.shape.title, identifier: "camera-deck-aspect") {
                    if play { model.say(why) } else { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } }
                }
                .deckDimmed(play || !model.canShape, why: shapeWhy)
                .deckKey(digi.keys[3])
            }
        }
        .frame(width: digi.canvas.width, height: digi.canvas.height, alignment: .topLeading)
    }
}

/// 拍照 / 录像: the ribbed aluminium thumb in its sunk track, a camera and
/// a video camera over its ends (the one it is at filled, and brighter).
private struct DigiSlide: View {
    var on: Bool
    var head: CGFloat
    var across: Bool
    var ink: Color
    var faint: Color
    var set: (Bool) -> Void
    var body: some View {
        let mark: CGFloat = across ? 13 : 15
        ZStack(alignment: .top) {
            ShellSlide(on: on, tone: DigiPaint.aluminium, set: set, head: head, track: Color(red: 0.055, green: 0.059, blue: 0.071))
            HStack {
                ShellGlyphView(glyph: .photo(!on), size: mark, ink: on ? faint : ink)
                Spacer(minLength: 0)
                ShellGlyphView(glyph: .video(on), size: mark, ink: on ? ink : faint)
            }
            .padding(.horizontal, across ? 10 : 18)
            .frame(height: head)
            .allowsHitTesting(false)
        }
    }
}

/// 内 / 外: upright a round key of turned aluminium, held across a tall
