/// The colour's dot (the colour that comes next) and the sticker beside it.
private struct DigiColourKeys: View {
    @ObservedObject var model: CameraAppModel
    var digi: DigiLayout
    var body: some View {
        ZStack(alignment: .topLeading) {
            if digi.tint.width > 0, let now = model.tint(of: .digital), let next = model.nextTint(of: .digital) {
                ShellTintKey(now: now, next: next, sound: .keyMetal) {
                    withAnimation(.easeInOut(duration: 0.2)) { model.cycleTint(of: .digital) }
                }
                .deckKey(digi.tint)
            }
            if digi.sticker.width > 0 {
                DigiStickerKey(on: model.stickers(on: .digital)) {
                    withAnimation(.easeInOut(duration: 0.2)) { model.toggleStickers(on: .digital) }
                }
                .deckKey(digi.sticker)
            }
        }
        .frame(width: digi.canvas.width, height: digi.canvas.height, alignment: .topLeading)
    }
}

/// One end of a rocker: what VoiceOver calls it, how it stands, its name
/// for the tests, whether it waits (and why), what it does.
struct DigiRockerEnd {
    var label: String
    var value = ""
    var identifier: String
    var off = false
    var why = ""
    var action: () -> Void
}

/// The rocker's bar: brushed aluminium rounded at its ends, darker in its
/// middle where it pivots (two grooves there when no word is), a bright rim.
private struct DigiRockerFace: View, Equatable {
    var grooves: Bool
    var body: some View {
        Canvas { context, size in
            let rect = CGRect(origin: .zero, size: size), r = size.height / 2
            let bar = Path(roundedRect: rect, cornerRadius: r)
            var lifted = context
            lifted.addFilter(.shadow(color: Color.black.opacity(0.5), radius: 1.75, x: 0, y: 1.8))
            lifted.fill(bar, with: DigiMetal.lit(size.height))
            var inner = context
            inner.clip(to: bar)
            DigiMetal.brush(inner, rect, 0.08, seed: 59)
            let pivot = Gradient(stops: [Gradient.Stop(color: Color.white.opacity(0.3), location: 0), Gradient.Stop(color: Color.black.opacity(0), location: 0.3),
                                         Gradient.Stop(color: Color.black.opacity(0.17), location: 0.5), Gradient.Stop(color: Color.black.opacity(0), location: 0.7),
                                         Gradient.Stop(color: Color.white.opacity(0.22), location: 1)])
            inner.fill(Path(rect), with: .linearGradient(pivot, startPoint: .zero, endPoint: CGPoint(x: size.width, y: 0)))
            if grooves {
                for sx in [size.width / 2 - 3, size.width / 2 + 3] {
                    inner.fill(Path(CGRect(x: sx - 0.5, y: 9, width: 1, height: max(0, size.height - 18))), with: .color(Color.black.opacity(0.2)))
                    inner.fill(Path(CGRect(x: sx + 0.5, y: 9, width: 0.8, height: max(0, size.height - 18))), with: .color(Color.white.opacity(0.6)))
                }
            }
            context.stroke(Path(roundedRect: rect.insetBy(dx: 0.7, dy: 0.7), cornerRadius: max(0, r - 0.7)), with: .color(Color.white.opacity(0.8)), lineWidth: 1)
        }
    }
}

/// A bar of brushed aluminium that rocks: either end presses (the bar dips
/// that way, with a notch's click and its feel); its signs (or glyphs) at
/// the ends, a word or a glyph between them — or, with neither, two grooves
/// in the middle (and a word by each end, where it has words). An end that
/// waits is paler.
private struct DigiRocker: View {
    var signs: [String] = []
    /// Glyphs at the ends, in place of signs (`signSize` their size).
    var glyphs: [ShellGlyph] = []
    var mid = ""
    /// A glyph in the middle, in place of a word (`midSize` its size).
    var midGlyph: ShellGlyph? = nil
    var words: [String] = []
    var signSize: CGFloat = 16
    /// How far in from each end the signs stand; where the words stand
    /// (parts of the width, from the left).
    var signAt: CGFloat = 26
    var wordsAt: [CGFloat] = [0.3, 0.7]
    var midSize: CGFloat = 10.5
    var ends: [DigiRockerEnd]
    @State private var down = 0
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            ZStack(alignment: .topLeading) {
                ZStack(alignment: .topLeading) {
                    DigiRockerFace(grooves: mid.isEmpty && midGlyph == nil).equatable()
                    if down != 0 {
                        Capsule().fill(LinearGradient(colors: [Color.black.opacity(0.18), Color.black.opacity(0)],
                                                      startPoint: down < 0 ? .leading : .trailing, endPoint: .center))
                    }
                    legends(w, h)
                }
                .frame(width: w, height: h)
                .offset(y: down == 0 ? 0 : 0.8)
                .animation(.easeOut(duration: 0.05), value: down)
                .allowsHitTesting(false)
                HStack(spacing: 0) {
                    end(0)
                    end(1)
                }
                .frame(width: w, height: h)
            }
            .background(Capsule().fill(Color.black.opacity(0.5)).padding(EdgeInsets(top: -1.4, leading: -1.8, bottom: -2.8, trailing: -1.8)))
        }
    }
    private func waits(_ index: Int) -> Bool { ends.indices.contains(index) && ends[index].off }
    @ViewBuilder private func legends(_ w: CGFloat, _ h: CGFloat) -> some View {
        ForEach(0..<min(2, signs.count), id: \.self) { index in
            Text(verbatim: signs[index]).font(.system(size: signSize, weight: .black, design: .rounded))
                .foregroundStyle(DigiPaint.ink)
                .opacity(waits(index) ? 0.4 : 1)
                .fixedSize()
                .position(x: index == 0 ? signAt : w - signAt, y: h / 2 + 0.5)
        }
        ForEach(0..<min(2, glyphs.count), id: \.self) { index in
            ShellGlyphView(glyph: glyphs[index], size: signSize, ink: DigiPaint.ink)
                .opacity(waits(index) ? 0.4 : 1)
                .position(x: index == 0 ? signAt : w - signAt, y: h / 2 + 0.5)
        }
        if let midGlyph {
            ShellGlyphView(glyph: midGlyph, size: midSize, ink: DigiPaint.ink.opacity(waits(0) && waits(1) ? 0.35 : 0.82))
                .position(x: w / 2, y: h / 2 + 0.5)
        } else if !mid.isEmpty {
            Text(mid).font(.system(size: midSize, weight: .heavy, design: .rounded))
                .foregroundStyle(DigiPaint.ink.opacity(waits(0) && waits(1) ? 0.35 : 0.78))
                .lineLimit(1).fixedSize()
                .position(x: w / 2, y: h / 2 + 0.5)
        }
        ForEach(0..<min(2, words.count, wordsAt.count), id: \.self) { index in
            Text(words[index]).font(.system(size: 10.5, weight: .heavy, design: .rounded))
                .foregroundStyle(DigiPaint.ink.opacity(waits(index) ? 0.35 : 0.8))
                .lineLimit(1).fixedSize()
                .position(x: w * wordsAt[index], y: h / 2 + 0.5)
        }
    }
    @ViewBuilder private func end(_ index: Int) -> some View {
        if ends.indices.contains(index) {
            let one = ends[index]
            Button(action: one.action) { Color.clear }
                .buttonStyle(DigiTouchStyle(press: { now in
                    if now { down = index == 0 ? -1 : 1 } else if down == (index == 0 ? -1 : 1) { down = 0 }
                }))
                .accessibilityLabel(one.label)
                .accessibilityValue(one.value)
                .accessibilityIdentifier(one.identifier)
                .accessibilityHint(one.off ? one.why : "")
        }
    }
}

/// One side of the ring: its word or its glyph (neither: its arrowhead
/// alone), what VoiceOver calls it, how it stands, its name for the tests,
/// whether it waits (and why), what it does.
struct DigiRingSide {
    var word: String
    var glyph: ShellGlyph? = nil
    var label: String
    var value = ""
    var identifier: String
    var off = false
    var why = ""
    var action: () -> Void
}

/// The ring's face: turned aluminium, its fine circles, a bright rim, and
/// the dark groove SET sits in. Drawn once for a size.
private struct DigiRingFace: View, Equatable {
    var radius: CGFloat
    var body: some View {
        let r = radius
        ZStack {
            Circle().fill(Color.black.opacity(0.5)).frame(width: 2 * r + 5.2, height: 2 * r + 5.2).offset(y: 1)
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(-2.2)))
                .frame(width: 2 * r, height: 2 * r)
                .shadow(color: Color.black.opacity(0.5), radius: 2.5, y: 2.2)
            Canvas { context, size in
                let c = CGPoint(x: size.width / 2, y: size.height / 2)
                func circle(_ k: CGFloat) -> Path { Path(ellipseIn: CGRect(x: c.x - k, y: c.y - k, width: 2 * k, height: 2 * k)) }
                var k = r - 3
                while k > 30 {
                    context.stroke(circle(k), with: .color(Color.black.opacity(0.035)), lineWidth: 0.7)
                    k -= 3
                }
                context.stroke(circle(r - 0.8), with: .color(Color.white.opacity(0.85)), lineWidth: 1.1)
                context.stroke(circle(r - 3.4), with: .color(Color.black.opacity(0.1)), lineWidth: 0.8)
                let pit = circle(28)
                context.fill(pit, with: .linearGradient(Gradient(colors: [Color(red: 0.231, green: 0.243, blue: 0.275), Color(red: 0.427, green: 0.447, blue: 0.486),
                                                                          Color(red: 0.663, green: 0.682, blue: 0.714)]),
                                                        startPoint: CGPoint(x: 0, y: c.y - 28), endPoint: CGPoint(x: 0, y: c.y + 28)))
                context.stroke(pit, with: .color(Color.white.opacity(0.6)), lineWidth: 0.8)
            }
        }
    }
}

/// The ring of turned aluminium round SET: each of its four sides is a key
/// of its own; pressed, the ring dips that way with a notch's click and its
/// feel. (SET is a key of its own, laid over its middle.)
private struct DigiRing: View {
    var digi: DigiLayout
    var sides: [DigiRingSide]
    /// The arrowheads all dark (moving among pictures) though no side has a word.
    var arrows = false
    /// How large the words are and how far out they stand, where not as the layout has them.
    var wordSize: CGFloat? = nil
    var wordsAt: CGFloat? = nil
    @State private var down: Int? = nil

    private func way(_ index: Int) -> CGVector {
        switch index {
        case 0: return CGVector(dx: 0, dy: -1)
        case 1: return CGVector(dx: 1, dy: 0)
        case 2: return CGVector(dx: 0, dy: 1)
        default: return CGVector(dx: -1, dy: 0)
        }
    }
    private var lean: CGSize {
        guard let down else { return .zero }
        let v = way(down)
        return CGSize(width: v.dx * 1.2, height: v.dy * 1.2)
    }
    var body: some View {
        let r = digi.ringRadius
        ZStack(alignment: .topLeading) {
            ZStack {
                DigiRingFace(radius: r).equatable()
                if let down { shade(down).frame(width: 2 * r - 6, height: 2 * r - 6) }
            }
            .frame(width: 2 * r + 12, height: 2 * r + 12)
            .offset(lean)
            .position(digi.ringCentre)
            .animation(.easeOut(duration: 0.06), value: down)
            .allowsHitTesting(false)
            ForEach(0..<4, id: \.self) { index in
                if sides.indices.contains(index), digi.sides.indices.contains(index) {
                    key(index, sides[index], digi.sides[index])
                }
            }
        }
    }
    private func key(_ index: Int, _ one: DigiRingSide, _ rect: CGRect) -> some View {
        let c = digi.ringCentre, v = way(index)
        let out = wordsAt ?? digi.wordsAt, tipAt = digi.ringRadius - 6.5
        let wordAt = CGPoint(x: c.x + v.dx * out - rect.midX, y: c.y + v.dy * out - rect.midY)
        let tip = CGPoint(x: c.x + v.dx * tipAt - rect.midX, y: c.y + v.dy * tipAt - rect.midY)
        let dark = !one.word.isEmpty || one.glyph != nil || arrows
        let flat = index % 2 == 0
        let glyphSize: CGFloat = digi.across ? 16 : 19
        return Button(action: one.action) {
            ZStack {
                if digi.marks {
                    ClamArrow(way: index).fill(DigiPaint.ink.opacity(dark ? 0.75 : 0.25))
                        .frame(width: flat ? 6.4 : 5.1, height: flat ? 5.1 : 6.4)
                        .offset(x: tip.x, y: tip.y)
                }
                if let glyph = one.glyph {
                    ShellGlyphView(glyph: glyph, size: glyphSize, ink: DigiPaint.ink)
                        .shadow(color: Color.white.opacity(0.55), radius: 0, y: 0.8)
                        .offset(x: wordAt.x, y: wordAt.y)
                } else if !one.word.isEmpty {
                    Text(one.word).font(.system(size: wordSize ?? digi.wordSize, weight: .black, design: .rounded)).foregroundStyle(DigiPaint.ink)
                        .shadow(color: Color.white.opacity(0.55), radius: 0, y: 0.8)
                        .lineLimit(1).fixedSize()
                        .offset(x: wordAt.x, y: wordAt.y)
                }
            }
            .offset(lean)
        }
        .buttonStyle(DigiTouchStyle(press: { now in
            if now { down = index } else if down == index { down = nil }
        }))
        .accessibilityLabel(one.label)
        .accessibilityValue(one.value)
        .accessibilityIdentifier(one.identifier)
        .deckDimmed(one.off, why: one.why)
        .frame(width: rect.width, height: rect.height)
        .position(x: rect.midX, y: rect.midY)
    }
    private func shade(_ index: Int) -> some View {
        let from: UnitPoint = index == 0 ? .top : index == 1 ? .trailing : index == 2 ? .bottom : .leading
        let to: UnitPoint = index == 0 ? .bottom : index == 1 ? .leading : index == 2 ? .top : .trailing
        return Circle().fill(LinearGradient(colors: [Color.black.opacity(0.2), Color.black.opacity(0)], startPoint: from, endPoint: to))
    }
}

/// What SET (the key in the ring's middle) shows: its glyph, pressed into
/// the metal.
private struct DigiHubLabel: View {
    var glyph: ShellGlyph
    var size: CGFloat = 20
    var body: some View {
        ShellGlyphView(glyph: glyph, size: size, ink: DigiPaint.ink)
            .shadow(color: Color.white.opacity(0.6), radius: 0, y: 0.8)
    }
}

/// The lenses (and the bodies pinned among them) as small keys of smoked
/// plastic, the one in use lit amber from behind and a little taller: a row
/// that goes along (two lines held across), keeping that one in sight. Each
/// shows its glyph (a pinned body, a small drawing of its kind of camera);
/// only the lit one its name too. In 回放 none is lit, and they wait.
private struct DigiLenses: View {
    @ObservedObject var model: CameraAppModel
    var digi: DigiLayout
    var play = false
    var why = ""
    private enum Item: Hashable { case lens(CameraLens), body(CameraBody) }
    var body: some View {
        let items: [Item] = CameraLens.allCases.map(Item.lens) + model.pinnedBodies.map(Item.body)
        let lines = max(1, digi.lensLines)
        ScrollViewReader { reader in
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(alignment: .center, spacing: digi.lensGap) {
                    ForEach(Array(stride(from: 0, to: items.count, by: lines)), id: \.self) { first in
                        VStack(spacing: digi.lensGap) {
                            ForEach(first..<min(first + lines, items.count), id: \.self) { index in
                                key(items[index], row: index - first, lines: lines).id(items[index])
                            }
                        }
                    }
                }
                .padding(.horizontal, digi.lensPadding)
                .frame(height: digi.lenses.height)
            }
            .onAppear { reader.scrollTo(Item.lens(model.lens), anchor: .center) }
            .onChange(of: model.lens) { _, lens in
                withAnimation(.easeOut(duration: 0.15)) { reader.scrollTo(Item.lens(lens), anchor: .center) }
            }
        }
        .accessibilityIdentifier("camera-deck-lenses")
        .opacity(model.controlsShown ? 0 : 1)
        .allowsHitTesting(!model.controlsShown)
    }
    private func key(_ item: Item, row: Int, lines: Int) -> some View {
        let title: String, glyph: ShellGlyph, chosen: Bool, identifier: String
        switch item {
        case .lens(let lens):
            title = lens.title; glyph = .lens(lens); chosen = model.lens == lens; identifier = "camera-deck-lens-\(lens.rawValue)"
        case .body(let pinned):
            title = pinned.title; glyph = .body(pinned); chosen = model.body == pinned; identifier = "camera-deck-pinned-\(pinned.rawValue)"
        }
        let on = chosen && !play
        let size = digi.lensSize
        let tall: CGFloat = size.height + (lines == 1 ? 2 * digi.lensGrow : digi.lensGrow)
        let edge: Alignment = lines == 1 ? .center : (row == 0 ? .bottom : .top)
        return Button {
            if play {
                model.say(why)
            } else {
                switch item {
                case .lens(let lens): model.choose(lens)
                case .body(let pinned): model.tapPinned(pinned)
                }
            }
        } label: {
            VStack(spacing: 2) {
                ShellGlyphView(glyph: glyph, size: on ? 16 : 19, ink: DigiLensStyle.ink(on))
                if on {
                    Text(title).font(.system(size: 11.5, weight: .black, design: .rounded)).lineLimit(1).minimumScaleFactor(0.6)
                }
            }
            .padding(.horizontal, 3)
        }
        .buttonStyle(DigiLensStyle(on: on))
        .frame(width: size.width, height: on ? tall : size.height)
        .frame(width: size.width, height: tall, alignment: edge)
        .accessibilityLabel(title)
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
        .deckDimmed(play, why: why)
    }
}

extension CameraDeckFace {
    /// The colour the digital camera is worn in.
    var digiPaint: DigiPaint { DigiPaint.named(model.shellTints[CameraShellSkin.digital.rawValue]) }

    /// The digital camera's body under its keys (a new colour, the stickers
    /// put on or taken off: it fades in).
    func digiBackdrop(_ digi: DigiLayout) -> some View {
        let paint = digiPaint, stickers = model.stickers(on: .digital)
        return DigiBackdrop(layout: digi, paint: paint, hinge: hinge, stickers: stickers).equatable()
            .id(paint.name + (stickers ? " stickers" : ""))
            .transition(.opacity)
    }

    /// The LCD over the picture: its glass round the picture's edge, and its
    /// own line over the picture's top (the mode, the picture's shape, the battery).
    @ViewBuilder func digiScreen(_ digi: DigiLayout) -> some View {
        DigiGlass(glass: digi.glass, hole: layout.picture).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        DigiReadout(shape: model.shape.title)
            .deckPlaced(digi.screen)
    }

    /// The digital camera, upright or across (the same keys, each where its
    /// hold has it): ZERO and its lamp; 拍照 / 录像, ▶ 回放 and W | T;
    /// 菜单, 显示, 日期, 比例; − 曝光 ＋; the ring round SET (闪光 above,
    /// ISO at the right, 白平衡 below, 定时 at the left; SET opens 机型); the
    /// lenses; 内 / 外; the shutter; the colour's dot and the sticker.
    @ViewBuilder func digiFace(_ digi: DigiLayout) -> some View {
        let paint = digiPaint
        let lamp: ShellTone = model.recording ? DigiPaint.red : DigiPaint.amber
        DigiMarks(digi: digi, paint: paint, lamp: lamp)
        digiSlide(digi, paint)
        digiPlayKey(digi)
        digiZoom(digi)
        DigiSmallKeys(model: model, digi: digi)
        digiExposure(digi)
        digiRing(digi)
        DigiLenses(model: model, digi: digi).deckPlaced(digi.lenses)
        DigiFlip(digi: digi, value: model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"),
                 off: model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧")) { model.switchSide() }
        digiShutter(digi)
        DigiColourKeys(model: model, digi: digi)
    }

    private func digiSlide(_ digi: DigiLayout, _ paint: DigiPaint) -> some View {
        let video = model.mode == .video
        return DigiSlide(on: video, head: digi.slideHead, across: digi.across, ink: paint.print, faint: paint.dim) { next in model.setMode(next ? .video : .photo) }
            .accessibilityElement()
            .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
            .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
            .accessibilityAddTraits(.isButton)
            .accessibilityAction { model.setMode(video ? .photo : .video) }
            .accessibilityIdentifier("camera-deck-mode")
            .deckKey(digi.slide)
    }

    /// ▶ 回放: the album (in 回放 the same key goes back to taking pictures: DigiPlayback).
    private func digiPlayKey(_ digi: DigiLayout) -> some View {
        Button { model.openAlbum() } label: { DigiPlayLabel(back: false, across: digi.across) }
            .buttonStyle(DigiKeyStyle(radius: digi.play.height / 2))
            .accessibilityLabel(CameraShellSkin.digital.albumTitle)
            .accessibilityValue(String(localized: "\(model.photos.count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .deckKey(digi.play)
    }

    /// W | T: the zoom's stops out and in (a magnifying glass less and more
    /// at its ends, the grooves where it pivots between them).
    private func digiZoom(_ digi: DigiLayout) -> some View {
        let zoomWord = String(localized: "变焦"), factor = Self.zoomText(model.zoom)
        let out = DigiRockerEnd(label: zoomWord + " −", value: factor, identifier: "camera-deck-zoom-out") { phoneNavigate(2) }
        let closer = DigiRockerEnd(label: zoomWord + " +", value: factor, identifier: "camera-deck-zoom-in") { phoneNavigate(0) }
        return DigiRocker(glyphs: [.zoomOut, .zoomIn], signSize: digi.across ? 18 : 20, signAt: digi.across ? 20 : 26 * digi.u, ends: [out, closer])
            .deckPlaced(digi.zoom)
    }

    /// − 曝光 ＋: how it is set between the two ends (± in a circle, and its value).
    private func digiExposure(_ digi: DigiLayout) -> some View {
        let shooting = model.shooting, exposureWord = String(localized: "曝光")
        let less = DigiRockerEnd(label: exposureWord + " −", value: shooting.exposureTitle, identifier: "camera-deck-ev-minus") { model.stepExposure(-1) }
        let more = DigiRockerEnd(label: exposureWord + " +", value: shooting.exposureTitle, identifier: "camera-deck-ev-plus") { model.stepExposure(1) }
        return DigiRocker(signs: ["−", "+"], midGlyph: .exposure(shooting.exposureTitle), signSize: digi.across ? 18 : 19, signAt: digi.across ? 19 : 26 * digi.u,
                          midSize: digi.across ? 15 : 17, ends: [less, more])
            .deckPlaced(digi.exposure)
    }

    /// The ring round SET: 闪光 above, ISO at the right, 白平衡 below, 定时
    /// at the left, each glyph drawn as it stands (and each says how it
    /// stands to VoiceOver); SET opens 机型 (two cameras traded).
    @ViewBuilder private func digiRing(_ digi: DigiLayout) -> some View {
        DigiRing(digi: digi, sides: digiSides()).deckPlaced(digi.ring)
        Button { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } } label: {
            DigiHubLabel(glyph: .changeBody, size: 26)
        }
        .buttonStyle(DigiKeyStyle(radius: 22, round: true, turn: 0.6))
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
        .deckKey(digi.hub)
    }
    private func digiSides() -> [DigiRingSide] {
        let shooting = model.shooting
        let flashWord = String(localized: "闪光"), balanceWord = String(localized: "白平衡"), timerWord = String(localized: "定时")
        let timed = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
        let up = DigiRingSide(word: "", glyph: .flash(shooting.flash), label: flashWord, value: shooting.flash.title, identifier: "camera-deck-flash") { model.cycleFlash() }
        let right = DigiRingSide(word: "", glyph: .iso(shooting.iso), label: "ISO", value: shooting.iso.title, identifier: "camera-deck-iso") { model.cycleISO() }
        let down = DigiRingSide(word: "", glyph: .whiteBalance(shooting.whiteBalance), label: balanceWord, value: shooting.whiteBalance.title,
                                identifier: "camera-deck-wb") { model.cycleWhiteBalance() }
        let left = DigiRingSide(word: "", glyph: .timer(model.timer), label: timerWord, value: timed, identifier: "camera-deck-timer") { model.cycleTimer() }
        return [up, right, down, left]
    }

    /// 拍照: the shutter in its chrome collar.
    private func digiShutter(_ digi: DigiLayout) -> some View {
        DigiShutterKey(video: model.mode == .video, recording: model.recording, time: CameraAppModel.clock(model.recordedSeconds)) { model.shutter() }
            .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
            .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
            .accessibilityIdentifier("camera-deck-shutter")
            .deckPlaced(digi.across ? digi.shutter : digi.shutter.insetBy(dx: 2, dy: 2))
    }

    /// The digital camera's 回放, upright and across.
    @ViewBuilder func digiAlbum(_ digi: DigiLayout) -> some View {
        DigiPlayback(model: model, thumbnails: thumbnails, digi: digi, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The pocket digital camera's 回放

/// The pocket digital camera's 回放: the same camera, one picture filling
/// its LCD with its number, its place, when it was taken and its shape. The
/// ring's sides go to the one before and the one after; its middle plays a
/// video (drawing on a picture is the touch screen's: the album inside);
/// W shows nine at a time — the ring moves among them, the middle or T
/// opens the one chosen again (larger, in a white edge). T is not a closer
/// look here. The keys that set the camera wait, and say why; ▶ 回放 says
/// 回去拍照, and it and the shutter go back to taking pictures; 菜单, the
/// colour's dot and the sticker do what they always do.
private struct DigiPlayback: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var digi: DigiLayout
    var hinge: CGRect
    /// Nine at a time (W).
    @State private var many = false
    @State private var push: CGFloat = 0

    private static let page = 9
    private var waiting: String { String(localized: "回放里用不了，回去拍照再用") }
    private var video: Bool { !many && model.albumPhoto?.isVideo == true }
    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }

    /// The picture's number as the card has it ("100-0007"), else its name.
    static func number(_ photo: CameraPhoto) -> String {
        let folder = photo.url.deletingLastPathComponent().lastPathComponent
        if let first = CameraFileNames.folderNumber(folder), let second = CameraFileNames.fileNumber(photo.name) {
            return String(format: "%d-%04d", first, second)
        }
        return photo.url.deletingPathExtension().lastPathComponent
    }
    /// When it was taken, in the LCD's figures ("2026 11 20  01:24").
    static func stamp(_ date: Date) -> String {
        let c = Calendar.current.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return String(format: "%04d %02d %02d  %02d:%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0)
    }
    /// The shape nearest the picture's own ("" before it is read).
    static func shape(_ image: CGImage?) -> String {
        guard let image, image.height > 0 else { return "" }
        let ratio = Double(image.width) / Double(image.height)
        return CameraAspect.allCases.min { abs($0.ratio - ratio) < abs($1.ratio - ratio) }?.title ?? ""
    }
    private func sharp(_ photo: CameraPhoto?) -> CGImage? {
        guard let photo else { return nil }
        return (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }

    private func choose(_ next: Int) {
        guard model.photos.indices.contains(next), next != model.albumIndex, model.doodle == nil else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }
    /// The ring: 0 up, 1 right, 2 down, 3 left (up and down only among the nine).
    private func step(_ way: Int) {
        let at = model.albumIndex
        switch way {
        case 1: choose(at + 1)
        case 3: choose(at - 1)
        case 0: choose(at - 3)
        default: choose(at + 3)
        }
    }
    /// The nine (W), or the one chosen whole again.
    private func showMany(_ on: Bool) {
        guard on != many, !model.photos.isEmpty else { return }
        if on, model.playing != nil { model.togglePlay() }
        many = on
    }

    var body: some View {
        let paint = DigiPaint.named(model.shellTints[CameraShellSkin.digital.rawValue])
        let stickers = model.stickers(on: .digital)
        ZStack(alignment: .topLeading) {
            DigiBackdrop(layout: digi, paint: paint, hinge: hinge, stickers: stickers).equatable()
                .id(paint.name + (stickers ? " stickers" : ""))
                .transition(.opacity)
            screen
            DigiGlass(glass: digi.glass, hole: digi.screen).equatable()
            readout
            DigiMarks(digi: digi, paint: paint, lamp: DigiPaint.green)
            slide(paint)
            back
            zoom
            DigiSmallKeys(model: model, digi: digi, play: true, why: waiting)
            exposure
            DigiRing(digi: digi, sides: sides(), arrows: many, wordSize: 10, wordsAt: digi.across ? nil : digi.wordsAt - 2).deckPlaced(digi.ring)
            hub
            DigiLenses(model: model, digi: digi, play: true, why: waiting).deckPlaced(digi.lenses)
            DigiFlip(digi: digi, value: model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), off: true, why: waiting) { model.say(waiting) }
            shutter(paint)
            DigiColourKeys(model: model, digi: digi)
        }
    }

    /// What the LCD shows: one picture whole (a video plays there; a push to
    /// the side goes to the next), or the nine; while a picture is being drawn
    /// on inside, that it waits there; what the camera says, for a moment.
    private var screen: some View {
        let photos = model.photos, at = model.albumIndex
        return ZStack {
            Color.black
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
            } else if many {
                nine(photos, at: at)
            } else if photos.indices.contains(at) {
                picture(photos[at])
            }
            if model.doodle != nil {
                Text("正在编辑 · 打开 Duo，在下屏接着画").font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(Color.white)
                    .multilineTextAlignment(.center).lineLimit(2).minimumScaleFactor(0.7)
                    .padding(.horizontal, 12).padding(.vertical, 6)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 16)
            }
            if let toast = model.toast {
                Text(toast).font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(Color.white)
                    .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                    .padding(.horizontal, 10).padding(.vertical, 4)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 14)
                    .frame(maxHeight: .infinity, alignment: .bottom)
                    .padding(.bottom, many ? 8 : 28)
                    .allowsHitTesting(false)
                    .transition(.opacity)
            }
        }
        .frame(width: digi.screen.width, height: digi.screen.height)
        .clipShape(RoundedRectangle(cornerRadius: 3, style: .continuous))
        .position(x: digi.screen.midX, y: digi.screen.midY)
    }

    private func picture(_ photo: CameraPhoto) -> some View {
        let image = sharp(photo)
        return ZStack {
            if let image { Image(decorative: image, scale: 1).resizable().scaledToFit() }
            if photo.isVideo {
                #if os(iOS)
                if model.playing == photo.url {
                    CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                        .accessibilityIdentifier("camera-album-player")
                }
                #endif
                if model.playing != photo.url {
                    Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9))
                        .shadow(color: .black.opacity(0.5), radius: 4)
                }
            }
        }
        .frame(width: digi.screen.width, height: digi.screen.height)
        .offset(x: push)
        .contentShape(Rectangle())
        .gesture(DragGesture(minimumDistance: 8)
            .onChanged { push = $0.translation.width }
            .onEnded { value in
                let dx = value.translation.width
                withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                if abs(dx) > 60 { choose(model.albumIndex + (dx < 0 ? 1 : -1)) }
            })
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : CameraShellSkin.digital.albumTitle)
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    /// The nine the chosen picture is among: three across, under a line for
    /// the LCD's words; the chosen one larger, in a white edge.
    private func nine(_ photos: [CameraPhoto], at: Int) -> some View {
        let w = digi.screen.width, h = digi.screen.height, top: CGFloat = 22
        let gap: CGFloat = w * 15 / 360
        let cw: CGFloat = max(1, (w - 4 * gap) / 3)
        let ch: CGFloat = max(1, min(cw * 0.75, (h - top - 12) / 3))
        let gapY: CGFloat = max(2, (h - top - 3 * ch) / 4)
        let first = (at / Self.page) * Self.page
        let size = CGSize(width: cw, height: ch)
        return ZStack(alignment: .topLeading) {
            Color(red: 0.047, green: 0.051, blue: 0.063)
            ForEach(0..<Self.page, id: \.self) { slot in
                if photos.indices.contains(first + slot) {
                    cell(photos[first + slot], slot: slot, index: first + slot, chosen: first + slot == at, size: size,
                         middle: CGPoint(x: gap + cw / 2 + CGFloat(slot % 3) * (cw + gap), y: top + gapY + ch / 2 + CGFloat(slot / 3) * (ch + gapY)))
                }
            }
        }
        .frame(width: w, height: h, alignment: .topLeading)
    }
    private func cell(_ photo: CameraPhoto, slot: Int, index: Int, chosen: Bool, size: CGSize, middle: CGPoint) -> some View {
        let grown: CGFloat = chosen ? 1.12 : 1
        let shape = RoundedRectangle(cornerRadius: 2, style: .continuous)
        return Button {
            ConsoleSounds.shared.play(.keyMetal, scale: 0.6)
            if !chosen { model.chooseInAlbum(index, quiet: true) }
            many = false
        } label: {
            ZStack(alignment: .bottomLeading) {
                Color(white: 0.14)
                if let image = thumbnails.images[photo.url] {
                    Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill())
                }
                if !chosen { Color(red: 0.031, green: 0.039, blue: 0.063).opacity(0.25) }
                if photo.isVideo {
                    Image(systemName: "video.fill").font(.system(size: 10, weight: .bold)).foregroundStyle(.white)
                        .shadow(color: .black.opacity(0.7), radius: 2).padding(3)
                }
            }
            .frame(width: size.width * grown, height: size.height * grown)
            .clipShape(shape)
            .background {
                if chosen {
                    RoundedRectangle(cornerRadius: 3, style: .continuous).fill(Color.white).padding(-2.5)
                        .shadow(color: Color.black.opacity(0.7), radius: 4)
                }
            }
        }
        .buttonStyle(.plain)
        .zIndex(chosen ? 1 : 0)
        .position(middle)
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityLabel(photo.name)
        .accessibilityAddTraits(chosen ? .isSelected : [])
        .accessibilityIdentifier("camera-deck-album-cell-\(slot)")
    }

    /// The LCD's words: the number (多张 over the nine), the place, when, the shape.
    private var readout: some View {
        let photos = model.photos, photo = model.albumPhoto
        let place = photos.isEmpty ? "0" : "\(model.albumIndex + 1) / \(photos.count)"
        let title: String = many ? String(localized: "多张") : (photo.map { Self.number($0) } ?? "")
        let taken: String = many ? "" : (photo.map { Self.stamp($0.date) } ?? "")
        let form: String = many ? "" : Self.shape(sharp(photo))
        return DigiPlayReadout(number: title, place: place, when: taken, shape: form, many: many)
            .deckPlaced(digi.screen)
    }

    /// 拍照 / 录像 waits.
    private func slide(_ paint: DigiPaint) -> some View {
        let video = model.mode == .video
        return DigiSlide(on: video, head: digi.slideHead, across: digi.across, ink: paint.dim, faint: paint.dim) { _ in model.say(waiting) }
            .accessibilityElement()
            .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
            .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
            .accessibilityAddTraits(.isButton)
            .deckDimmed(true, why: waiting)
            .deckKey(digi.slide)
    }

    /// ▶ 回放's key: 回去拍照, its green lamp lit.
    private var back: some View {
        Button { backToCamera() } label: { DigiPlayLabel(back: true, across: digi.across) }
            .buttonStyle(DigiKeyStyle(radius: digi.play.height / 2))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-return")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(digi.play)
    }

    /// W 多张 | 放大 T (nine squares, the magnifying glass more): W the
    /// nine; T the chosen one whole again from the nine (with one whole, no
    /// closer look: it waits).
    private var zoom: some View {
        let none = model.photos.isEmpty
        let manyWord = String(localized: "多张"), closer = String(localized: "放大"), open = String(localized: "看这张")
        let wWhy = none ? String(localized: "还没有照片") : String(localized: "已经在看多张")
        let tWhy = String(localized: "回放里不能放大")
        let wide = DigiRockerEnd(label: manyWord, identifier: "camera-deck-album-index", off: none || many, why: wWhy) {
            if none || many { model.say(wWhy) } else { showMany(true) }
        }
        let near = DigiRockerEnd(label: many ? open : closer, identifier: "camera-deck-album-zoom", off: !many, why: tWhy) {
            if many { showMany(false) } else { model.say(tWhy) }
        }
        return DigiRocker(glyphs: [.grid, .zoomIn], signSize: digi.across ? 18 : 20, signAt: digi.across ? 20 : 26 * digi.u, ends: [wide, near])
            .deckPlaced(digi.zoom)
    }

    /// − 曝光 ＋ waits.
    private var exposure: some View {
        let shooting = model.shooting, word = String(localized: "曝光")
        let less = DigiRockerEnd(label: word + " −", value: shooting.exposureTitle, identifier: "camera-deck-ev-minus", off: true, why: waiting) { model.say(waiting) }
        let more = DigiRockerEnd(label: word + " +", value: shooting.exposureTitle, identifier: "camera-deck-ev-plus", off: true, why: waiting) { model.say(waiting) }
        return DigiRocker(signs: ["−", "+"], midGlyph: .exposure(shooting.exposureTitle), signSize: digi.across ? 18 : 19, signAt: digi.across ? 19 : 26 * digi.u,
                          midSize: digi.across ? 15 : 17, ends: [less, more])
            .deckPlaced(digi.exposure)
    }

    /// The ring's sides: among the nine all four move; with one whole the
    /// left and right go to the one before and after, up and down wait.
    private func sides() -> [DigiRingSide] {
        let none = model.photos.isEmpty, empty = String(localized: "还没有照片")
        let upWord = String(localized: "向上"), rightWord = String(localized: "向右"), downWord = String(localized: "向下"), leftWord = String(localized: "向左")
        if many {
            let up = DigiRingSide(word: "", label: upWord, identifier: "camera-deck-album-up", off: none, why: empty) { step(0) }
            let right = DigiRingSide(word: "", label: rightWord, identifier: "camera-deck-album-next", off: none, why: empty) { step(1) }
            let down = DigiRingSide(word: "", label: downWord, identifier: "camera-deck-album-down", off: none, why: empty) { step(2) }
            let left = DigiRingSide(word: "", label: leftWord, identifier: "camera-deck-album-previous", off: none, why: empty) { step(3) }
            return [up, right, down, left]
        }
        let quiet = String(localized: "看一张时上下不用")
        let earlier = String(localized: "上一张"), later = String(localized: "下一张")
        let above = DigiRingSide(word: "", label: upWord, identifier: "camera-deck-album-up", off: true, why: quiet) { model.say(quiet) }
        let after = DigiRingSide(word: "", glyph: .next, label: later, identifier: "camera-deck-album-next", off: none, why: empty) { step(1) }
        let below = DigiRingSide(word: "", label: downWord, identifier: "camera-deck-album-down", off: true, why: quiet) { model.say(quiet) }
        let before = DigiRingSide(word: "", glyph: .previous, label: earlier, identifier: "camera-deck-album-previous", off: none, why: empty) { step(3) }
        return [above, after, below, before]
    }

    /// SET: among the nine 看这张 (the magnifying glass more, as T there);
    /// with one whole, a video's 播放 / 停止 (▶ or the square; a picture's waits).
    @ViewBuilder private var hub: some View {
        if many {
            Button { showMany(false) } label: { DigiHubLabel(glyph: .zoomIn, size: 19) }
                .buttonStyle(DigiKeyStyle(radius: 22, round: true, turn: 0.6))
                .accessibilityLabel(String(localized: "看这张"))
                .accessibilityIdentifier("camera-deck-album-view")
                .deckKey(digi.hub)
        } else {
            let word = model.playing != nil ? String(localized: "停止") : String(localized: "播放")
            let sign: ShellGlyph = model.playing != nil ? .stop : .play
            let why = model.photos.isEmpty ? String(localized: "还没有照片") : String(localized: "照片不能播放；要在上面画，展开后用相册的「编辑」")
            Button { if video { model.togglePlay() } else { model.say(why) } } label: { DigiHubLabel(glyph: sign, size: 18) }
                .buttonStyle(DigiKeyStyle(radius: 22, round: true, turn: 0.6))
                .accessibilityLabel(word)
                .accessibilityIdentifier("camera-deck-album-play")
                .deckDimmed(!video, why: why)
                .deckKey(digi.hub)
        }
    }

    /// The shutter: back to taking pictures (a camera and 回去拍照 under it,
    /// upright: its words kept).
    @ViewBuilder private func shutter(_ paint: DigiPaint) -> some View {
        DigiShutterKey(haptic: .smallButton) { backToCamera() }
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-close")
            .deckDimmed(drawing, why: drawingWhy)
            .deckPlaced(digi.across ? digi.shutter : digi.shutter.insetBy(dx: 2, dy: 2))
        if digi.shutterCaption.width > 0 {
            ShellGlyphLabel(glyph: .returnToShooting, words: String(localized: "回去拍照"), size: 12, wordSize: 10, ink: paint.print)
                .fixedSize()
                .deckPlaced(digi.shutterCaption)
        }
    }
}

// MARK: - The instant camera's print, coming out as the Duo is opened

/// The instant camera's print coming out as the Duo is opened: on the inner
/// screen, out of a slot near the top — as far out as the hinge is open
/// (never faster than it can be fed, never back in; where the hinge does not
/// say, by the clock), and then the picture comes up on it. A touch puts it
/// away, and the camera is there as ever.
struct InstantPrintOut: View {
    @ObservedObject var model: CameraAppModel
    var url: URL
    @State private var image: CGImage?
    @State private var out: Double = 0
    @State private var blank: Double = 1

    var body: some View {
        GeometryReader { geo in
            let tone = CameraShellSkin.instant.tone
            let w = geo.size.width, h = geo.size.height
            let side: CGFloat = 14, foot: CGFloat = 54
            let aspect: CGFloat = image.map { CGFloat($0.width) / CGFloat(max(1, $0.height)) } ?? 4.0 / 3
            let pw = max(60, min(w * 0.78, (h * 0.62 - side - foot) * aspect)), ph = pw / aspect
            let card = CGSize(width: pw + 2 * side, height: ph + side + foot)
            let slot = h * 0.14
            let top = slot + 26 - CGFloat(1 - out) * (card.height + 30)
            ZStack(alignment: .topLeading) {
                LinearGradient(colors: [tone.color(0.22), tone.color(0), tone.color(-0.28)], startPoint: .topLeading, endPoint: .bottomTrailing)
                ZStack {
                    ZStack(alignment: .top) {
                        RoundedRectangle(cornerRadius: 4, style: .continuous).fill(Color(red: 0.985, green: 0.975, blue: 0.955))
                            .shadow(color: .black.opacity(0.35), radius: 8, y: 4)
                        ZStack {
                            Color(red: 0.16, green: 0.16, blue: 0.15)
                            if let image {
                                Image(decorative: image, scale: 1).resizable().scaledToFill().frame(width: pw, height: ph).clipped()
                            }
                            Color(red: 0.80, green: 0.82, blue: 0.78).opacity(blank)
                        }
                        .frame(width: pw, height: ph)
                        .padding(.top, side)
                    }
                    .frame(width: card.width, height: card.height)
                    .position(x: w / 2, y: top + card.height / 2)
                }
                .frame(width: w, height: h)
                .mask(VStack(spacing: 0) { Color.clear.frame(height: slot + 5); Color.black })
                Capsule().fill(LinearGradient(colors: [Color(white: 0.04), Color(white: 0.17)], startPoint: .top, endPoint: .bottom))
                    .overlay(Capsule().strokeBorder(Color.white.opacity(0.35), lineWidth: 1).offset(y: 1))
                    .frame(width: min(w * 0.92, card.width + 56), height: 14)
                    .position(x: w / 2, y: slot)
                Text(verbatim: "ZERO").font(.system(size: 14, weight: .heavy, design: .rounded)).tracking(4).foregroundStyle(tone.ink.opacity(0.5)).fixedSize()
                    .position(x: w / 2, y: max(20, slot - 30))
                Text("点一下，放回那一叠").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(tone.ink.opacity(0.75))
                    .opacity(out >= 1 ? 1 : 0)
                    .position(x: w / 2, y: h - 44)
            }
            .contentShape(Rectangle())
            .onTapGesture { if out >= 1 { model.printIsOut() } }
        }
        .ignoresSafeArea()
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(String(localized: "相片"))
        .accessibilityValue(out >= 1 ? "out" : "coming")
        .accessibilityAddTraits(.isButton)
        .accessibilityAction { if out >= 1 { model.printIsOut() } }
        .accessibilityIdentifier("camera-print-out")
        .task(id: url) {
            image = await Task.detached(priority: .userInitiated) { CameraRoll.image(at: url, maxPixel: 900) }.value
        }
        .task { @MainActor in
            let began = Date()
            ConsoleSounds.shared.play(.instantEject)
            while !Task.isCancelled, out < 1 {
                let hinge = HingePosture.shared
                // How far the hinge is open: from a quarter of the way to
                // nearly flat is the print's whole way out.
                let byHinge: Double = hinge.status == .fullyOpen ? 1 : hinge.angle.map { min(1, max(0, ($0 - 25) / 140)) } ?? 1
                let next = min(byHinge, Date().timeIntervalSince(began) / 0.9)
                if next > out { out = next }
                try? await Task.sleep(nanoseconds: 16_000_000)
            }
            withAnimation(.easeIn(duration: 5)) { blank = 0 }
        }
    }
}

// MARK: - The retro computer's back, and its 图片盘

/// The retro computer's colours (mock/shells_pc.js): the beige plastic and
/// the darker beige of its tube's surround and of a few keys, the
/// keyboard's sunk tray, the tube's dark surround and its glass, the paper
/// of what the tube shows and its ink, what is printed on the plastic, the
/// drive's slot and the disk in it, the ridged wheel, the power lamp.
enum RetroPaint {
    static let plastic = ShellTone(r: 0.878, g: 0.847, b: 0.776)
    static let darker = ShellTone(r: 0.784, g: 0.749, b: 0.675)
    static let tray = ShellTone(r: 0.690, g: 0.655, b: 0.580)
    static let surround = ShellTone(r: 0.204, g: 0.212, b: 0.196)
    static let glass = Color(red: 0.078, green: 0.086, blue: 0.071)
    static let paper = Color(red: 0.957, green: 0.949, blue: 0.918)
    static let ink = Color(red: 0.086, green: 0.086, blue: 0.059)
    static let legend = Color(red: 0.290, green: 0.263, blue: 0.220)
    static let desktop = Color(red: 0.604, green: 0.639, blue: 0.604)
    static let slot = ShellTone(r: 0.102, g: 0.102, b: 0.094)
    static let disk = Color(red: 0.184, green: 0.302, blue: 0.525)
    static let diskShutter = Color(red: 0.788, green: 0.800, blue: 0.824)
    static let label = Color(red: 0.847, green: 0.824, blue: 0.761)
    static let wheel = ShellTone(r: 0.588, g: 0.557, b: 0.486)
    /// The power lamp: green, red while a video is taken.
    static let green = ShellTone(r: 0.431, g: 0.902, b: 0.471)
    static let red = ShellTone(r: 0.95, g: 0.25, b: 0.22)
}

/// The retro computer's keys while taking pictures (each one's place is
/// kept in RetroLayout by its name).
enum RetroKey: Hashable {
    case flash, balance, iso, date, flip, home, bodies, mode, shape, zoomOut, zoomIn, lensBack, lensOn, lighter, stronger, timer, level
}

/// Its keys in 图片盘.
enum RetroAlbumKey: Hashable {
    case home, bodies, back, close, up, left, down, right, enter
}

/// Where the retro computer's parts are on the cover, upright (from a
/// ShellPlan) or across (from a ShellAcrossPlan), taking pictures and in
/// 图片盘 (mock/shells_pc.js, mock/albums.js).
struct RetroLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    /// The tube: its surround, its face (the menu bar over the picture), the menu bar.
    var bezel = CGRect.zero
    var face = CGRect.zero
    var menu = CGRect.zero
    /// The slots along the top edge (upright), ZERO and the power lamp,
    /// PERSONAL COMPUTER, 64K (.zero: no room for it).
    var vents = CGRect.zero
    var name = CGRect.zero
    var nameSize: CGFloat = 12
    var lamp = CGPoint.zero
    var tagline = CGRect.zero
    var badge = CGRect.zero
    /// The slots where the Camera Control's overlay comes in.
    var grille = CGRect.zero
    /// The drive (the album); the wheel (曝光) — where it is touched, and
    /// the room in that round the wheel itself — the sun printed by it,
    /// how it is set.
    var drive = CGRect.zero
    var wheel = CGRect.zero
    var wheelRoom = EdgeInsets()
    var sun = CGPoint.zero
    var wheelCaption = CGRect.zero
    /// The keyboard's sunk tray, and the keys.
    var tray = CGRect.zero
    var keys: [RetroKey: CGRect] = [:]
    /// 拍照: the Enter key under the thumb, and the space bar (upright).
    var shutter = CGRect.zero
    var space = CGRect.zero
    /// 图片盘: the tube (taller upright), its face and menu bar, the drive
    /// and the words beside it, the tray, the keys, 定时 and 水平仪 (they
    /// wait there), the words under the Enter key, how many files to a row.
    var albumBezel = CGRect.zero
    var albumFace = CGRect.zero
    var albumMenu = CGRect.zero
    var albumDrive = CGRect.zero
    var albumNote = CGRect.zero
    var albumTray = CGRect.zero
    var albumKeys: [RetroAlbumKey: CGRect] = [:]
    var albumTimer = CGRect.zero
    var albumLevel = CGRect.zero
    var closeCaption = CGRect.zero
    var fileColumns = 2
    /// 11-22: held across as a desk computer (ShellAcrossPlan.retroDesk): the space bar is 拍照 (no Enter key of
    /// its own, none in 图片盘 either); the speaker's slots under the drive, the word printed under them.
    var desk = false
    var speaker = CGRect.zero
    var speakerCaption = CGRect.zero

    func rect(_ key: RetroKey) -> CGRect { keys[key] ?? .zero }
    func albumRect(_ key: RetroAlbumKey) -> CGRect { albumKeys[key] ?? .zero }
    /// A part of the tube inside its surround, as the drawings have them:
    /// 1 the dark surround in it, 2 the black, 3 the face.
    static func inset(_ bezel: CGRect, step: Int, across: Bool) -> CGRect {
        let dx: [CGFloat] = across ? [6, 11, 17] : [7, 13, 19]
        let dy: [CGFloat] = [6, 11, 17]
        let i = min(2, max(0, step - 1))
        return CGRect(x: bezel.minX + dx[i], y: bezel.minY + dy[i], width: max(0, bezel.width - 2 * dx[i]), height: max(0, bezel.height - 2 * dy[i]))
    }
}

extension ShellPlan {
    /// The retro computer's tube at its full height: the picture 4:3 across
    /// its face (the column less the surround's 38), the menu bar over it,
    /// the surround round both (296 on the Duo's cover, as drawn).
    var retroTubeHeight: CGFloat { max(0, back.column.width - 38) * 0.75 + 57.5 }
    /// The drive's row and the keyboard under the tube: as tall as the
    /// drawing has them (296) where the column has the room, down to 266.
    var retroKeysHeight: CGFloat {
        let room = back.column.maxY - (top + 28) - retroTubeHeight - 8
        return min(296, max(266, room))
    }

    /// The retro computer's parts, upright: along the top edge three slots,
    /// the lamp and ZERO; the tube; under it the drive and the wheel; the
    /// keyboard (mock/shells_pc.js's points, the column 356 wide there); in
    /// the strip 定时 and 水平仪 under the camera, 64K, the slots where the
    /// Camera Control's overlay comes in, the Enter key under them. In
    /// 图片盘 the tube is taller and the keyboard is mock/albums.js's.
    var retro: RetroLayout {
        var l = RetroLayout()
        let c = back.column, s = back.strip
        let k = c.width / 356
        let k0 = keysTop, run = retroKeysHeight
        let squeeze = (run - 266) / 30
        let floor = back.keepOut.map(\.maxY).max() ?? top
        func px(_ at: CGFloat) -> CGFloat { c.minX + (at - 14) * k }
        l.canvas = back.canvas
        l.vents = CGRect(x: px(26), y: top + 1, width: 150 * k, height: 19)
        l.name = CGRect(x: px(356) - 64, y: top + 3, width: 64, height: 18)
        l.lamp = CGPoint(x: px(296), y: top + 12)
        l.bezel = surround
        l.face = RetroLayout.inset(surround, step: 3, across: false)
        l.menu = CGRect(x: l.face.minX, y: l.face.minY, width: l.face.width, height: 20)
        // Under the tube the drive and the wheel; the keyboard, its rows as
        // tall as the room lets them be (54 as drawn, never under 47).
        let driveHeight: CGFloat = 32 + 4 * squeeze
        let middle = k0 + driveHeight / 2
        l.drive = CGRect(x: px(16), y: k0, width: 150 * k, height: driveHeight)
        l.wheel = CGRect(x: px(204), y: middle - 22, width: 96 * k, height: 44)
        l.wheelRoom = EdgeInsets(top: 10, leading: 0, bottom: 10, trailing: 0)
        l.sun = CGPoint(x: px(190), y: middle)
        l.wheelCaption = CGRect(x: px(304), y: middle - 7, width: max(0, c.maxX - px(304)), height: 14)
        let trayTop = k0 + driveHeight + 8, trayHeight = run - driveHeight - 8
        l.tray = CGRect(x: px(12), y: trayTop, width: 360 * k, height: trayHeight)
        let left = px(19), span = 346 * k, gap: CGFloat = 6
        let row = (trayHeight - 36) / 4
        let five = (span - 4 * gap) / 5, four = (span - 3 * gap) / 4, side = 60 * k
        let rowTops: [CGFloat] = [trayTop + 7, trayTop + 13 + row, trayTop + 19 + 2 * row, trayTop + 25 + 3 * row]
        let first: [RetroKey] = [.flash, .balance, .iso, .date, .flip]
        for (i, name) in first.enumerated() {
            l.keys[name] = CGRect(x: left + CGFloat(i) * (five + gap), y: rowTops[0], width: five, height: row)
        }
        let second: [RetroKey] = [.home, .bodies, .mode, .shape]
        let third: [RetroKey] = [.zoomOut, .zoomIn, .lensBack, .lensOn]
        for j in 0..<4 {
            l.keys[second[j]] = CGRect(x: left + CGFloat(j) * (four + gap), y: rowTops[1], width: four, height: row)
            l.keys[third[j]] = CGRect(x: left + CGFloat(j) * (four + gap), y: rowTops[2], width: four, height: row)
        }
        l.keys[.lighter] = CGRect(x: left, y: rowTops[3], width: side, height: row + 4)
        l.space = CGRect(x: left + side + gap, y: rowTops[3], width: max(0, span - 2 * side - 2 * gap), height: row + 4)
        l.keys[.stronger] = CGRect(x: left + span - side, y: rowTops[3], width: side, height: row + 4)
        if c.maxY - (trayTop + trayHeight) >= 34 {
            l.tagline = CGRect(x: c.minX, y: trayTop + trayHeight + 14, width: c.width, height: 12)
        }
        // The strip: 定时 and 水平仪 under the camera, 64K, the slots, the Enter key.
        let width = min(72, max(44, s.width - 8))
        let below = (back.overlay?.minY ?? shutter.minY) - 8
        let tall = min(54, max(44, (below - floor - 14) / 2))
        l.keys[.timer] = CGRect(x: s.midX - width / 2, y: floor + 8, width: width, height: tall)
        l.keys[.level] = CGRect(x: s.midX - width / 2, y: floor + 14 + tall, width: width, height: tall)
        let foot = floor + 14 + 2 * tall
        if let zone = back.overlay {
            let w = min(62, max(0, s.width - 16))
            l.grille = CGRect(x: s.midX - w / 2, y: zone.minY + 12, width: w, height: max(0, zone.height - 20))
            if zone.minY - foot >= 30 { l.badge = CGRect(x: s.midX - 30, y: (foot + zone.minY) / 2 - 7, width: 60, height: 14) }
        }
        l.shutter = shutter
        // 图片盘 (mock/albums.js): the tube down to 32 under the keys' top,
        // the drive and its words, three rows of keys.
        l.albumBezel = CGRect(x: surround.minX, y: surround.minY, width: surround.width, height: max(0, k0 + 32 - surround.minY))
        l.albumFace = RetroLayout.inset(l.albumBezel, step: 3, across: false)
        l.albumMenu = CGRect(x: l.albumFace.minX, y: l.albumFace.minY, width: l.albumFace.width, height: 20)
        l.albumDrive = CGRect(x: px(16), y: k0 + 40, width: 150 * k, height: driveHeight)
        l.albumNote = CGRect(x: px(176), y: k0 + 40 + driveHeight / 2 - 7, width: max(0, c.maxX - px(176)), height: 14)
        let albumTop = k0 + 48 + driveHeight, albumHeight = run - 48 - driveHeight
        l.albumTray = CGRect(x: px(12), y: albumTop, width: 360 * k, height: albumHeight)
        let line = (albumHeight - 32) / 3, f = (span - 18) / 328
        let x1 = left + 110 * f + gap, x2 = x1 + 72 * f + gap, x3 = x2 + 72 * f + gap
        let y1 = albumTop + 7, y2 = y1 + line + gap, y3 = y2 + line + gap
        l.albumKeys[.home] = CGRect(x: left, y: y1, width: 110 * f, height: line)
        l.albumKeys[.up] = CGRect(x: x1, y: y1, width: 72 * f, height: line)
        l.albumKeys[.bodies] = CGRect(x: x2, y: y1, width: 72 * f, height: line)
        l.albumKeys[.back] = CGRect(x: x3, y: y1, width: 74 * f, height: line)
        l.albumKeys[.left] = CGRect(x: left + 38 * f, y: y2, width: 72 * f, height: line)
        l.albumKeys[.down] = CGRect(x: x1, y: y2, width: 72 * f, height: line)
        l.albumKeys[.right] = CGRect(x: x2, y: y2, width: 72 * f, height: line)
        l.albumKeys[.close] = CGRect(x: x3, y: y2, width: 74 * f, height: line)
        l.albumKeys[.enter] = CGRect(x: left, y: y3, width: span, height: line + 6)
        l.albumTimer = l.rect(.timer)
        l.albumLevel = l.rect(.level)
        l.closeCaption = CGRect(x: s.midX - 40, y: shutter.maxY + 3, width: 80, height: 14)
        l.fileColumns = 2
        return l
    }
}

extension ShellAcrossPlan {
    /// 拍照 held across: a keycap by itself in the band's other clear run
    /// (at the end of the longer one where that one is too short).
    var retroShutter: CGRect {
        if let desk = retroDesk { return desk.shutter }
        let spare = back.spare, run = back.run
        if spare.width >= 112 {
            let w = min(104, spare.width - 12)
            return CGRect(x: spare.midX - w / 2, y: spare.midY - 26, width: w, height: 52)
        }
        let w = min(104, max(44, run.width - 12))
        return CGRect(x: run.maxX - w - 6, y: run.midY - 26, width: w, height: 52)
    }

    /// The retro computer's parts with the cover held across: the tube at
    /// the left; in the band ZERO, the lamp, PERSONAL COMPUTER and 64K in
    /// its longer clear run, the slots in the overlay's place, the Enter key
    /// in the other run; in the keys' column seven rows of three — the drive
    /// and 机型, the wheel and 主菜单, then the drawing's keycaps on their
    /// tray. In 图片盘 the column has the album's keys, the drive, 机型 and
    /// 主菜单 where they were.
    var retro: RetroLayout {
        if let desk = retroDesk { return desk }
        var l = RetroLayout()
        let run = back.run, band = back.band, column = back.keys
        l.across = true
        l.canvas = back.canvas
        l.bezel = surround
        l.face = RetroLayout.inset(surround, step: 3, across: true)
        l.menu = CGRect(x: l.face.minX, y: l.face.minY, width: l.face.width, height: 20)
        // The band (less what the Enter key takes of the longer run where it shares it).
        let room: CGFloat = back.spare.width >= 112 ? run.width : run.width - 116
        if room >= 80 {
            l.name = CGRect(x: run.minX + 4, y: run.midY - 16, width: 64, height: 20)
            l.nameSize = 13
            l.lamp = CGPoint(x: run.minX + 74, y: run.midY - 6)
        }
        if room >= 150 { l.tagline = CGRect(x: run.minX + 4, y: run.midY + 6, width: min(160, room - 8), height: 12) }
        if room >= 200 { l.badge = CGRect(x: run.minX + room - 44, y: run.midY - 13, width: 40, height: 14) }
        if let zone = back.overlay, zone.width > 30 {
            l.grille = CGRect(x: zone.minX + 10, y: band.minY + 12, width: max(0, zone.width - 18), height: max(0, band.height - 28))
        }
        l.shutter = shutter
        // The column: seven rows of three.
        let cw = (column.width - 12) / 3, pitch = (column.height - 44) / 6
        func slot(_ col: Int, _ line: Int, _ span: Int = 1) -> CGRect {
            key(CGFloat(col) * (cw + 6), CGFloat(line) * pitch, CGFloat(span) * cw + CGFloat(span - 1) * 6, 44)
        }
        let wheelSlot = slot(0, 1, 2)
        l.drive = slot(0, 0, 2).insetBy(dx: 0, dy: 3)
        l.keys[.bodies] = slot(2, 0)
        l.wheel = wheelSlot
        l.wheelRoom = EdgeInsets(top: 4, leading: 22, bottom: 20, trailing: 4)
        l.sun = CGPoint(x: wheelSlot.minX + 11, y: wheelSlot.minY + 14)
        l.wheelCaption = CGRect(x: wheelSlot.minX, y: wheelSlot.minY + 28, width: wheelSlot.width, height: 14)
        l.keys[.home] = slot(2, 1)
        let rows: [[RetroKey]] = [[.flash, .balance, .iso], [.date, .timer, .shape], [.flip, .level, .mode], [.zoomOut, .zoomIn, .lighter], [.lensBack, .lensOn, .stronger]]
        for (r, names) in rows.enumerated() {
            for (n, name) in names.enumerated() { l.keys[name] = slot(n, r + 2) }
        }
        l.tray = CGRect(x: column.minX - 6, y: column.minY + 2 * pitch - 6, width: column.width + 12, height: column.height - 2 * pitch + 12)
        // 图片盘.
        l.albumBezel = l.bezel
        l.albumFace = l.face
        l.albumMenu = l.menu
        l.albumDrive = l.drive
        l.albumKeys[.bodies] = slot(2, 0)
        l.albumKeys[.back] = wheelSlot
        l.albumKeys[.home] = slot(2, 1)
        l.albumKeys[.close] = slot(0, 2)
        l.albumKeys[.up] = slot(1, 2)
        l.albumKeys[.left] = slot(0, 3)
        l.albumKeys[.down] = slot(1, 3)
        l.albumKeys[.right] = slot(2, 3)
        l.albumKeys[.enter] = slot(0, 4, 3)
        l.albumTimer = slot(0, 5)
        l.albumLevel = slot(1, 5)
        l.albumTray = l.tray
        l.fileColumns = 3
        return l
    }
}

extension ShellAcrossPlan {
    /// 11-22: the retro computer held across as a desk computer, as its drawing has it (mock/shells_pc.js's
    /// computerLand, the Duo's cover 678 x 466 with the band along its top): the monitor in the middle; at its
    /// left the drive, the speaker and 机型; at its right the wheel (曝光), 变焦 − +, ‹ 镜头 › and 主菜单; under
    /// them the keyboard's two rows the whole width (闪光 … 录像; 浓淡 −, the space bar — 拍照 — and 浓淡 +). In
    /// the band ZERO, the lamp and PERSONAL COMPUTER in its longer clear run, the slots where the overlay comes
    /// in, 64K in the other run; the band lies along whichever long edge the camera is on, the rest in the same
    /// order from the top. In 图片盘 the monitor has the files, the drive, 机型 and 主菜单 stay, the arrows take
    /// 变焦's and 镜头's place (↑ over ↓, ← and → beside it), the first row has 回去拍照, 关窗口, 定时 and 水平仪
    /// (they wait), the second 回车. Nil where it has no room: the keys go in their column then.
    var retroDesk: RetroLayout? {
        guard skin == .computer else { return nil }
        let band = back.band, area = back.area
        guard area.width > 0, area.height > 0 else { return nil }
        let atTop = band.minY < 1
        // Across, the drawing's points (8 to 670) to the room there is; up and down, the drawing's own.
        let lo = area.minX - 2, hi = area.maxX + 4
        let k = (hi - lo) / 662
        guard k >= 0.92 else { return nil }
        func x(_ at: CGFloat) -> CGFloat { lo + (at - 8) * k }
        // The block (the monitor 262 high, a gap of 4, the keyboard 100) from the band's edge, or from the top;
        // squeezed a little where the room is short (the monitor down to 255, the keyboard to 96), else none.
        // Down where the camera is, its corner (deeper than the band) is kept out of the keyboard.
        let top = area.minY
        var lowest = area.maxY
        if !atTop {
            let keyboard = CGRect(x: x(8), y: top, width: 662 * k, height: area.height)
            for kept in back.keepOut where kept.minX < keyboard.maxX && kept.maxX > keyboard.minX && kept.minY > top + 200 {
                lowest = min(lowest, kept.minY - 2)
            }
        }
        let short = max(0, 366 - (lowest - top))
        guard short <= 11 else { return nil }
        let squeezeMonitor = min(7, short), squeezeKeys = short - squeezeMonitor
        let t = top
        var l = RetroLayout()
        l.across = true
        l.desk = true
        l.canvas = back.canvas
        l.bezel = CGRect(x: x(168), y: t, width: 342 * k, height: 262 - squeezeMonitor)
        l.face = RetroLayout.inset(l.bezel, step: 3, across: true)
        l.menu = CGRect(x: l.face.minX, y: l.face.minY, width: l.face.width, height: 20)
        // The band.
        let run = back.run, spare = back.spare
        if run.width >= 80 {
            l.name = CGRect(x: run.minX + 14, y: run.midY - 15, width: 64, height: 20)
            l.nameSize = 13
            l.lamp = CGPoint(x: run.minX + 82, y: run.midY - 5)
        }
        if run.width >= 150 { l.tagline = CGRect(x: run.minX + 14, y: run.midY + 8, width: min(170, run.width - 20), height: 12) }
        if spare.width >= 48 { l.badge = CGRect(x: spare.midX - 20, y: spare.midY - 7, width: 40, height: 14) }
        if let zone = back.overlay, zone.width > 30 {
            l.grille = CGRect(x: zone.minX + 10, y: band.minY + 12, width: max(0, zone.width - 18), height: max(0, band.height - 28))
        }
        // At the monitor's left: the drive, the speaker, the word printed under it, 机型 — under the camera's
        // corner where it reaches past the band there.
        var leftTop = t + 18
        for kept in back.keepOut where kept.minX < x(158) && kept.maxX > x(12) && kept.maxY < t + 60 { leftTop = max(leftTop, kept.maxY + 4) }
        let drop = min(leftTop - (t + 18), max(0, l.bezel.maxY - (t + 228)))
        guard leftTop - (t + 18) <= drop + 0.5 else { return nil }
        l.drive = CGRect(x: x(12), y: t + 18 + drop, width: 146 * k, height: 38)
        l.speaker = CGRect(x: x(22), y: t + 72 + drop, width: 126 * k, height: 67.2)
        l.speakerCaption = CGRect(x: x(12), y: t + 147 + drop, width: 146 * k, height: 14)
        l.keys[.bodies] = CGRect(x: x(16), y: t + 178 + drop, width: 142 * k, height: 50)
        // At its right: the wheel (touched over its height of 44, drawn 24 high), its sun and how it is set; 变焦
        // − +, ‹ 镜头 ›, 主菜单.
        l.wheel = CGRect(x: x(556), y: t + 12, width: 100 * k, height: 44)
        l.wheelRoom = EdgeInsets(top: 10, leading: 0, bottom: 10, trailing: 0)
        l.sun = CGPoint(x: x(540), y: t + 34)
        l.wheelCaption = CGRect(x: x(556), y: t + 53, width: 100 * k, height: 14)
        l.keys[.zoomOut] = CGRect(x: x(522), y: t + 82, width: 70 * k, height: 48)
        l.keys[.zoomIn] = CGRect(x: x(598), y: t + 82, width: 70 * k, height: 48)
        l.keys[.lensBack] = CGRect(x: x(522), y: t + 136, width: 70 * k, height: 48)
        l.keys[.lensOn] = CGRect(x: x(598), y: t + 136, width: 70 * k, height: 48)
        l.keys[.home] = CGRect(x: x(522), y: t + 190, width: 146 * k, height: 50)
        // The keyboard: its tray, the first row of nine, the second (浓淡 −, the space bar, 浓淡 +).
        let trayHeight: CGFloat = 100 - squeezeKeys
        l.tray = CGRect(x: x(8), y: l.bezel.maxY + 4, width: 662 * k, height: trayHeight)
        let extra = trayHeight - 88
        let first = l.tray.minY + extra * 5 / 12, second = first + 44 + extra * 4 / 12
        let row: [RetroKey] = [.flash, .balance, .iso, .date, .timer, .shape, .flip, .level, .mode]
        for (i, name) in row.enumerated() {
            l.keys[name] = CGRect(x: x(14 + CGFloat(i) * 72.9), y: first, width: 67 * k, height: 44)
        }
        l.keys[.lighter] = CGRect(x: x(14), y: second, width: 96 * k, height: 44)
        l.shutter = CGRect(x: x(116), y: second, width: 446 * k, height: 44)
        l.keys[.stronger] = CGRect(x: x(568), y: second, width: 96 * k, height: 44)
        // 图片盘.
        l.albumBezel = l.bezel
        l.albumFace = l.face
        l.albumMenu = l.menu
        l.albumDrive = l.drive
        l.albumTray = l.tray
        l.albumKeys[.bodies] = l.rect(.bodies)
        l.albumKeys[.home] = l.rect(.home)
        let pad = CGRect(x: x(522), y: t + 82, width: 146 * k, height: 102)
        let w3 = max(44, (pad.width - 12) / 3), gap = max(0, (pad.width - 3 * w3) / 2)
        l.albumKeys[.up] = CGRect(x: pad.minX + w3 + gap, y: pad.minY, width: w3, height: 48)
        l.albumKeys[.left] = CGRect(x: pad.minX, y: pad.minY + 54, width: w3, height: 48)
        l.albumKeys[.down] = CGRect(x: pad.minX + w3 + gap, y: pad.minY + 54, width: w3, height: 48)
        l.albumKeys[.right] = CGRect(x: pad.minX + 2 * (w3 + gap), y: pad.minY + 54, width: w3, height: 48)
        let line = CGRect(x: x(14), y: first, width: 650 * k, height: 44)
        let w4 = (line.width - 18) / 4
        l.albumKeys[.back] = CGRect(x: line.minX, y: first, width: w4, height: 44)
        l.albumKeys[.close] = CGRect(x: line.minX + (w4 + 6), y: first, width: w4, height: 44)
        l.albumTimer = CGRect(x: line.minX + 2 * (w4 + 6), y: first, width: w4, height: 44)
        l.albumLevel = CGRect(x: line.minX + 3 * (w4 + 6), y: first, width: w4, height: 44)
        l.albumKeys[.enter] = CGRect(x: line.minX, y: second, width: line.width, height: 44)
        l.fileColumns = 2
        // Nothing pressed may lie under the camera's corner or the overlay, nor over the picture.
        func crosses(_ a: CGRect, _ b: CGRect) -> Bool {
            a.minX < b.maxX - 0.5 && b.minX < a.maxX - 0.5 && a.minY < b.maxY - 0.5 && b.minY < a.maxY - 0.5
        }
        let pressed = Array(l.keys.values) + Array(l.albumKeys.values) + [l.shutter, l.drive, l.wheel, l.albumTimer, l.albumLevel]
        let blockers = back.keepOut + (back.overlay.map { [$0] } ?? [])
        let picture = CGRect(x: l.bezel.minX + 17, y: l.bezel.minY + 37.6, width: l.bezel.width - 34, height: l.bezel.height - 54.6)
        guard !blockers.contains(where: { b in crosses(b, picture) || pressed.contains { crosses(b, $0) } }) else { return nil }
        return l
    }
}

/// The retro computer's body, drawn as the pictures of it were
/// (mock/shells_pc.js, mock/albums.js, part for part): the beige plastic and
/// its fine grain, the hinge's side in shade, the slots along its top edge
/// and where the Camera Control's overlay comes in, the tube sunk in its
/// surround, the keyboard's sunk tray, the sun printed by the wheel. (The
/// drive, the wheel and the keys are drawn as they go down.) Drawn once.
private struct RetroBackdrop: View, Equatable {
    var layout: RetroLayout
    var hinge: CGRect
    var album = false
    var body: some View {
        Canvas { context, size in
            Self.plastic(context, size, hinge)
            Self.vents(context, layout.vents)
            Self.grille(context, layout.grille, across: layout.across)
            Self.tube(context, album ? layout.albumBezel : layout.bezel, across: layout.across)
            Self.speaker(context, layout.speaker)
            Self.sunk(context, album ? layout.albumTray : layout.tray, radius: layout.across ? 10 : 12, tone: RetroPaint.tray)
            if !album { Self.sun(context, layout.sun) }
            let whole = CGRect(origin: .zero, size: size)
            context.stroke(Path(whole.insetBy(dx: 1.5, dy: 1.5)), with: .color(Color.white.opacity(0.35)), lineWidth: 1.2)
            context.stroke(Path(whole.insetBy(dx: 0.5, dy: 0.5)), with: .color(Color.black.opacity(0.5)), lineWidth: 1)
        }
        .accessibilityHidden(true)
    }

    /// The plastic lit from the upper left, its fine grain, the hinge's side in shade.
    private static func plastic(_ context: GraphicsContext, _ size: CGSize, _ hinge: CGRect) {
        let whole = CGRect(origin: .zero, size: size), tone = RetroPaint.plastic
        let light = Gradient(stops: [Gradient.Stop(color: tone.color(0.22), location: 0), Gradient.Stop(color: tone.color(0), location: 0.35),
                                     Gradient.Stop(color: tone.color(-0.28), location: 1)])
        context.fill(Path(whole), with: .linearGradient(light, startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
        var seed: UInt32 = 0x2468_ACE1
        func next() -> CGFloat {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            return CGFloat((seed >> 8) & 0xFFFF) / 65535
        }
        for _ in 0..<Int(size.width * size.height / 30) {
            let at = CGPoint(x: next() * size.width, y: next() * size.height)
            let pale = next() < 0.5
            let a = Double(next()) * (pale ? 0.035 : 0.05)
            context.fill(Path(CGRect(x: at.x, y: at.y, width: 1, height: 1)), with: .color((pale ? Color.white : Color.black).opacity(a)))
        }
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let near: Bool = tall ? hinge.midX < size.width / 2 : hinge.midY < size.height / 2
            let from: CGPoint = tall ? CGPoint(x: near ? hinge.minX : hinge.maxX, y: 0) : CGPoint(x: 0, y: near ? hinge.minY : hinge.maxY)
            let to: CGPoint = tall ? CGPoint(x: near ? hinge.maxX : hinge.minX, y: 0) : CGPoint(x: 0, y: near ? hinge.maxY : hinge.minY)
            context.fill(Path(hinge), with: .linearGradient(Gradient(colors: [Color.black.opacity(0.45), Color.black.opacity(0)]), startPoint: from, endPoint: to))
        }
    }

    /// A slot cut in the plastic: dark, its far lip catching the light.
    private static func slot(_ context: GraphicsContext, _ rect: CGRect, down: Bool) {
        let r = min(rect.width, rect.height) / 2
        context.fill(Path(roundedRect: rect, cornerRadius: r), with: .color(Color.black.opacity(0.42)))
        let lip = down ? rect.offsetBy(dx: 0, dy: 1) : rect.offsetBy(dx: 1, dy: 0)
        context.stroke(Path(roundedRect: lip, cornerRadius: r), with: .color(Color.white.opacity(0.3)), lineWidth: 0.6)
    }

    /// Three slots along the top edge (upright).
    private static func vents(_ context: GraphicsContext, _ rect: CGRect) {
        guard rect.width > 4 else { return }
        for i in 0..<3 {
            slot(context, CGRect(x: rect.minX, y: rect.minY + CGFloat(i) * 7.5, width: rect.width, height: 3.2), down: true)
        }
    }

    /// 11-22: the speaker under the drive (the desk): slots one under another.
    private static func speaker(_ context: GraphicsContext, _ rect: CGRect) {
        guard rect.width > 4, rect.height > 4 else { return }
        var y = rect.minY
        while y + 3.2 <= rect.maxY {
            slot(context, CGRect(x: rect.minX, y: y, width: rect.width, height: 3.2), down: true)
            y += 8
        }
    }

    /// The slots where the overlay comes in: across the strip upright, down the band across.
    private static func grille(_ context: GraphicsContext, _ rect: CGRect, across: Bool) {
        guard rect.width > 4, rect.height > 4 else { return }
        if across {
            var x = rect.minX
            while x + 3.2 <= rect.maxX {
                slot(context, CGRect(x: x, y: rect.minY, width: 3.2, height: rect.height), down: false)
                x += 8
            }
        } else {
            var y = rect.minY
            while y + 3.2 <= rect.maxY {
                slot(context, CGRect(x: rect.minX, y: y, width: rect.width, height: 3.2), down: true)
                y += 7.5
            }
        }
    }

    /// A plate sunk in the plastic: darker at its upper edge, a dark line round it, a light one inside its foot.
    private static func sunk(_ context: GraphicsContext, _ rect: CGRect, radius: CGFloat, tone: ShellTone) {
        guard rect.width > 0, rect.height > 0 else { return }
        let r = min(radius, rect.width / 2, rect.height / 2)
        let shape = Path(roundedRect: rect, cornerRadius: r)
        let fill = Gradient(stops: [Gradient.Stop(color: tone.color(-0.25), location: 0), Gradient.Stop(color: tone.color(0), location: 0.3),
                                    Gradient.Stop(color: tone.color(0.08), location: 1)])
        context.fill(shape, with: .linearGradient(fill, startPoint: CGPoint(x: 0, y: rect.minY), endPoint: CGPoint(x: 0, y: rect.maxY)))
        context.stroke(shape, with: .color(Color.black.opacity(0.5)), lineWidth: 1)
        context.stroke(Path(roundedRect: rect.insetBy(dx: 0.5, dy: 0.5).offsetBy(dx: 0, dy: 0.7), cornerRadius: r), with: .color(Color.white.opacity(0.14)), lineWidth: 1)
    }

    /// The tube: the beige surround, the dark surround sunk in it, the black.
    private static func tube(_ context: GraphicsContext, _ bezel: CGRect, across: Bool) {
        sunk(context, bezel, radius: 16, tone: RetroPaint.darker)
        sunk(context, RetroLayout.inset(bezel, step: 1, across: across), radius: 24, tone: RetroPaint.surround)
        let black = RetroLayout.inset(bezel, step: 2, across: across)
        guard black.width > 0, black.height > 0 else { return }
        context.fill(Path(roundedRect: black, cornerRadius: min(20, black.width / 2, black.height / 2)), with: .color(RetroPaint.glass))
    }

    /// The sun printed by the wheel.
    private static func sun(_ context: GraphicsContext, _ at: CGPoint) {
        guard at != .zero else { return }
        let ink = RetroPaint.legend
        context.fill(Path(ellipseIn: CGRect(x: at.x - 2.4, y: at.y - 2.4, width: 4.8, height: 4.8)), with: .color(ink))
        var rays = Path()
        for i in 0..<8 {
            let a = Double(i) * Double.pi / 4
            let dx = CGFloat(cos(a)), dy = CGFloat(sin(a))
            rays.move(to: CGPoint(x: at.x + dx * 4, y: at.y + dy * 4))
            rays.addLine(to: CGPoint(x: at.x + dx * 5.8, y: at.y + dy * 5.8))
        }
        context.stroke(rays, with: .color(ink), style: StrokeStyle(lineWidth: 1.3, lineCap: .round))
    }
}

/// What lies round the picture: the tube's black up to the picture's edge
/// (over the picture's own bezel), and the face's dark edge outside it.
/// Nothing lies over the picture, and nothing is pressed through it.
private struct RetroGlass: View, Equatable {
    var black: CGRect
    var face: CGRect
    var hole: CGRect
    var body: some View {
        Canvas { context, _ in
            guard black.width > 0, black.height > 0 else { return }
            var glass = Path(roundedRect: black, cornerRadius: min(20, black.width / 2, black.height / 2))
            if hole.width > 0, hole.height > 0 { glass.addPath(Path(roundedRect: hole, cornerRadius: 5, style: .continuous)) }
            context.fill(glass, with: .color(RetroPaint.glass), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: face.insetBy(dx: -1, dy: -1), cornerRadius: 13), with: .color(Color.black.opacity(0.7)), lineWidth: 2)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The tube's menu bar: paper-white, its upper corners round, a line of ink under it.
private struct RetroMenuPlate: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let radii = RectangleCornerRadii(topLeading: 12, bottomLeading: 0, bottomTrailing: 0, topTrailing: 12)
            context.fill(Path(roundedRect: CGRect(origin: .zero, size: size), cornerRadii: radii, style: .circular), with: .color(RetroPaint.paper))
            context.fill(Path(CGRect(x: 0, y: size.height - 1.2, width: size.width, height: 1.2)), with: .color(RetroPaint.ink))
        }
    }
}

/// What the menu bar says, as an old computer's does: its menus along the
/// left (the first of them bolder), at the right how many pictures are left
/// (in 图片盘 which picture of how many, read by VoiceOver and the tests).
private struct RetroMenuBar: View {
    var items: [String]
    var trailing: String
    var counts = false
    var body: some View {
        ZStack {
            RetroMenuPlate().equatable()
            HStack(spacing: 12) {
                ForEach(Array(items.enumerated()), id: \.offset) { index, item in
                    Text(item).font(.system(size: 10.5, weight: index == 0 ? .black : .heavy, design: .monospaced))
                        .lineLimit(1).minimumScaleFactor(0.7)
                        .accessibilityHidden(true)
                }
                Spacer(minLength: 4)
                Text(trailing).font(.system(size: 10.5, weight: .heavy, design: .monospaced)).monospacedDigit()
                    .lineLimit(1).minimumScaleFactor(0.7)
                    .accessibilityHidden(!counts)
                    .accessibilityIdentifier(counts ? "camera-deck-album-position" : "")
            }
            .foregroundStyle(RetroPaint.ink)
            .padding(.leading, 10)
            .padding(.trailing, 9)
            .padding(.bottom, 1)
        }
        .allowsHitTesting(false)
    }
}

/// A small lamp in its dark ring, glowing (it does not blink).
private struct RetroLamp: View {
    var tone: ShellTone
    var body: some View {
        ZStack {
            Circle().fill(Color.black.opacity(0.6)).frame(width: 7.2, height: 7.2)
            Circle().fill(RadialGradient(colors: [Color.white, tone.color(), tone.color(-0.3)], center: UnitPoint(x: 0.35, y: 0.35), startRadius: 0.2, endRadius: 2.4))
                .frame(width: 4.8, height: 4.8)
                .shadow(color: tone.color(), radius: 3)
        }
    }
}

/// ZERO and the power lamp, PERSONAL COMPUTER and 64K, printed on the plastic.
private struct RetroMarks: View {
    var layout: RetroLayout
    var lamp: ShellTone
    var body: some View {
        ZStack(alignment: .topLeading) {
            if layout.name.width > 0 {
                Text(verbatim: "ZERO").font(.system(size: layout.nameSize, weight: .heavy)).tracking(3)
                    .foregroundStyle(RetroPaint.legend.opacity(0.75))
                    .shadow(color: Color.white.opacity(0.7), radius: 0, y: 0.8)
                    .lineLimit(1).fixedSize()
                    .frame(width: layout.name.width, height: layout.name.height, alignment: layout.across ? .leading : .trailing)
                    .position(x: layout.name.midX, y: layout.name.midY)
            }
            if layout.lamp != .zero {
                RetroLamp(tone: lamp).frame(width: 12, height: 12).position(layout.lamp)
            }
            if layout.tagline.width > 0 {
                Text(verbatim: "PERSONAL COMPUTER").font(.system(size: 10, weight: .bold)).tracking(1.4)
                    .foregroundStyle(RetroPaint.legend.opacity(0.6))
                    .lineLimit(1).minimumScaleFactor(0.7)
                    .frame(width: layout.tagline.width, height: layout.tagline.height, alignment: layout.across ? .leading : .center)
                    .position(x: layout.tagline.midX, y: layout.tagline.midY)
            }
            if layout.badge.width > 0 {
                Text(verbatim: "64K").font(.system(size: 10, weight: .bold)).tracking(2)
                    .foregroundStyle(RetroPaint.legend.opacity(0.6))
                    .lineLimit(1).fixedSize()
                    .position(x: layout.badge.midX, y: layout.badge.midY)
            }
            if layout.speakerCaption.width > 0 {
                Text(verbatim: CameraShellSkin.computer.albumTitle).font(.system(size: 10, weight: .bold))
                    .foregroundStyle(RetroPaint.legend.opacity(0.7))
                    .lineLimit(1).fixedSize()
                    .position(x: layout.speakerCaption.midX, y: layout.speakerCaption.midY)
            }
        }
        .frame(width: layout.canvas.width, height: layout.canvas.height, alignment: .topLeading)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A sculpted keycap of an old desktop keyboard: its skirt darker toward the
/// foot, the dished top set a little up and back, lighter, a fine light rim,
/// a faint grain; darker while down.
private struct RetroCapFace: View, Equatable {
    var tone: ShellTone
    var radius: CGFloat
    var pressed: Bool
    var body: some View {
        Canvas { context, size in
            let rect = CGRect(origin: .zero, size: size)
            let r = min(radius, min(size.width, size.height) / 2)
            let skirt = Path(roundedRect: rect, cornerRadius: r, style: .continuous)
            context.fill(skirt, with: .linearGradient(Gradient(colors: [tone.color(-0.1), tone.color(-0.3)]), startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height)))
            let top = CGRect(x: 4, y: 2, width: max(0, size.width - 8), height: max(0, size.height - 9))
            let face = Path(roundedRect: top, cornerRadius: max(0, r - 1), style: .continuous)
            let dish = Gradient(stops: [Gradient.Stop(color: tone.color(0.2), location: 0), Gradient.Stop(color: tone.color(0), location: 0.5),
                                        Gradient.Stop(color: tone.color(0.1), location: 1)])
            context.fill(face, with: .linearGradient(dish, startPoint: CGPoint(x: 0, y: top.minY), endPoint: CGPoint(x: 0, y: top.maxY)))
            context.stroke(Path(roundedRect: top.insetBy(dx: 0.5, dy: 0.5), cornerRadius: max(0, r - 1.5), style: .continuous),
                           with: .color(Color.white.opacity(pressed ? 0.3 : 0.55)), lineWidth: 1)
            var inner = context
            inner.clip(to: face)
            var seed: UInt32 = 0x0C0F_FEE5
            for _ in 0..<Int(top.width * top.height / 14) {
                seed = seed &* 1_664_525 &+ 1_013_904_223
                let x = top.minX + CGFloat((seed >> 8) & 0xFFFF) / 65535 * top.width
                seed = seed &* 1_664_525 &+ 1_013_904_223
                let y = top.minY + CGFloat((seed >> 8) & 0xFFFF) / 65535 * top.height
                let ink = (seed >> 20) & 1 == 0 ? Color.white : Color.black
                inner.fill(Path(CGRect(x: x, y: y, width: 1, height: 1)), with: .color(ink.opacity(0.03)))
            }
            if pressed { context.fill(skirt, with: .color(Color.black.opacity(0.1))) }
        }
    }
}

/// A key of the retro computer: the keycap goes down in its well under the
/// finger (the well stays), with a key's click and its feel as it goes —
/// not when it is let go.
struct RetroKeyStyle: ButtonStyle {
    var tone: ShellTone = RetroPaint.plastic
    var radius: CGFloat = 6
    var travel: CGFloat = 2
    var sound: ConsoleSound = .keySlide
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View { RetroKeyBody(configuration: configuration, style: self) }
}
private struct RetroKeyBody: View {
    let configuration: ButtonStyle.Configuration
    let style: RetroKeyStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .foregroundStyle(RetroPaint.legend)
            .padding(EdgeInsets(top: 2, leading: 4, bottom: 7, trailing: 4))
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(RetroCapFace(tone: style.tone, radius: style.radius, pressed: down).equatable())
            .offset(y: down ? style.travel : 0)
            // The well it sits in (which does not go down with it).
            .background(RoundedRectangle(cornerRadius: style.radius + 1, style: .continuous).fill(Color.black.opacity(0.42))
                .padding(EdgeInsets(top: -1, leading: -1, bottom: -3, trailing: -1)))
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.09), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: 0.8)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// What is on a keycap: its glyph in the middle, as a keyboard's symbol
/// keys carry theirs, drawn as what it sets stands; under it, small, the
/// figures that go with it (the zoom's) or 浓淡's step as a row of cells.
private struct RetroCapLabel: View {
    var glyph: ShellGlyph
    var figures: String = ""
    var cells: ShellGlyph? = nil
    var size: CGFloat = 20
    var stacked = false
    var body: some View {
        VStack(spacing: 2) {
            ShellGlyphView(glyph: glyph, size: size, ink: RetroPaint.legend, stacked: stacked)
            if let cells {
                ShellGlyphView(glyph: cells, size: size * 0.7, ink: RetroPaint.legend)
            } else if !figures.isEmpty {
                Text(verbatim: figures).font(.system(size: 10, weight: .semibold)).monospacedDigit().opacity(0.72)
                    .lineLimit(1).minimumScaleFactor(0.6)
            }
        }
        .padding(.horizontal, 3)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

/// A keycap's word in its middle (a small picture beside it, or over it).
private struct RetroWordLabel: View {
    var word: String
    var symbol: String? = nil
    var size: CGFloat = 12
    var stacked = false
    var body: some View {
        let stack = stacked ? AnyLayout(VStackLayout(spacing: 3)) : AnyLayout(HStackLayout(spacing: 5))
        stack {
            if let symbol { Image(systemName: symbol).font(.system(size: size, weight: .bold)) }
            Text(word).font(.system(size: size, weight: .bold)).lineLimit(1).minimumScaleFactor(0.6)
        }
        .padding(.horizontal, 4)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

/// ⏎, drawn: down the right side, back along the foot, its head at the left.
private struct RetroReturnMark: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        let foot = rect.minY + rect.height * 0.62
        path.move(to: CGPoint(x: rect.maxX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: foot))
        path.addLine(to: CGPoint(x: rect.minX + 1, y: foot))
        path.move(to: CGPoint(x: rect.minX + rect.width * 0.36, y: foot - rect.height * 0.36))
        path.addLine(to: CGPoint(x: rect.minX + 1, y: foot))
        path.addLine(to: CGPoint(x: rect.minX + rect.width * 0.36, y: foot + rect.height * 0.36))
        return path
    }
}

/// What 拍照 shows: a camera (the return mark after it on the Enter key) —
/// for a video a red dot, the square and the time while one is taken.
private struct RetroShutterLabel: View {
    var video = false
    var recording = false
    /// How long the video being taken has run.
    var clock = ""
    var ready = true
    var enter = false
    var size: CGFloat = 20
    var body: some View {
        HStack(spacing: 5) {
            mark
            if video, recording {
                Text(verbatim: clock).font(.system(size: 12.5, weight: .heavy)).monospacedDigit().lineLimit(1).minimumScaleFactor(0.6)
            }
            if enter {
                RetroReturnMark().stroke(style: StrokeStyle(lineWidth: 1.6, lineCap: .round, lineJoin: .round)).frame(width: 11, height: 9)
            }
        }
        .padding(.horizontal, 6)
        .padding(.vertical, 4)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .opacity(ready || video ? 1 : 0.45)
    }
    @ViewBuilder private var mark: some View {
        if video {
            if recording {
                RoundedRectangle(cornerRadius: 2.5, style: .continuous).fill(CameraShutterFace.red).frame(width: 12, height: 12)
            } else {
                Circle().fill(CameraShutterFace.red).frame(width: 13, height: 13)
            }
        } else {
            ShellGlyphView(glyph: .photo(true), size: size, ink: RetroPaint.legend)
        }
    }
}

/// What the Enter key shows in 图片盘: a camera and the return mark (回去拍照
/// printed under it, upright), or a camera and 回去拍照 (held across) — its
/// words kept either way.
private struct RetroCloseLabel: View {
    var words: Bool
    var body: some View {
        Group {
            if words {
                ShellGlyphLabel(glyph: .returnToShooting, words: String(localized: "回去拍照"), size: 16, wordSize: 12.5, ink: RetroPaint.legend)
            } else {
                HStack(spacing: 6) {
                    ShellGlyphView(glyph: .returnToShooting, size: 18, ink: RetroPaint.legend)
                    RetroReturnMark().stroke(style: StrokeStyle(lineWidth: 1.6, lineCap: .round, lineJoin: .round)).frame(width: 11, height: 9)
                }
            }
        }
        .padding(.horizontal, 5)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

/// 关窗口: a cross, as on a window's close box (at the weight and the size
/// the other keys' glyphs are drawn at; no glyph of ShellGlyph says it).
private struct RetroCloseGlyph: View {
    var size: CGFloat
    var body: some View {
        Image(systemName: "xmark").font(.system(size: size * 0.9, weight: ShellGlyphView.weight)).foregroundStyle(RetroPaint.legend)
            .accessibilityHidden(true)
    }
}

/// The drive's slot sunk in the plastic, and the disk half in it (further
/// in while it is pressed).
private struct RetroDriveFace: View, Equatable {
    var pressed: Bool
    var body: some View {
        Canvas { context, size in
            let rect = CGRect(origin: .zero, size: size), tone = RetroPaint.slot
            let plate = Path(roundedRect: rect, cornerRadius: 6)
            let fill = Gradient(stops: [Gradient.Stop(color: tone.color(-0.25), location: 0), Gradient.Stop(color: tone.color(0), location: 0.3),
                                        Gradient.Stop(color: tone.color(0.08), location: 1)])
            context.fill(plate, with: .linearGradient(fill, startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height)))
            context.stroke(plate, with: .color(Color.black.opacity(0.5)), lineWidth: 1)
            context.stroke(Path(roundedRect: rect.insetBy(dx: 0.5, dy: 0.5).offsetBy(dx: 0, dy: 1.2), cornerRadius: 6), with: .color(Color.white.opacity(0.14)), lineWidth: 1)
            let slot = CGRect(x: 8, y: 7, width: max(0, size.width - 16), height: 5)
            context.fill(Path(roundedRect: slot, cornerRadius: 2.5), with: .color(Color(white: 0.02)))
            context.stroke(Path(roundedRect: slot.offsetBy(dx: 0, dy: 0.8), cornerRadius: 2.5), with: .color(Color.white.opacity(0.25)), lineWidth: 0.8)
            let wide = min(70, size.width * 0.45)
            let disk = CGRect(x: 14, y: 13 - (pressed ? 2 : 0), width: wide, height: max(0, size.height - 15))
            var inner = context
            inner.clip(to: Path(CGRect(x: 0, y: slot.maxY, width: size.width, height: max(0, size.height - slot.maxY))))
            inner.fill(Path(roundedRect: disk, cornerRadius: 2), with: .color(RetroPaint.disk))
            let shutter = CGRect(x: disk.minX + wide * 0.26, y: disk.minY, width: wide * 0.46, height: 10)
            inner.fill(Path(roundedRect: shutter, cornerRadius: 1), with: .color(RetroPaint.diskShutter))
            inner.fill(Path(CGRect(x: shutter.minX + shutter.width * 0.62, y: shutter.minY + 2, width: 7, height: 6)), with: .color(RetroPaint.disk))
            if pressed { context.fill(plate, with: .color(Color.black.opacity(0.12))) }
        }
    }
}

/// What the drive's label shows: the album's glyph and how many pictures
/// are on the disk.
private struct RetroDriveLabel: View {
    var count: Int
    var body: some View {
        HStack(spacing: 4) {
            ShellGlyphView(glyph: .album, size: 13, ink: RetroPaint.label)
            Text(verbatim: "\(count)").font(.system(size: 10.5, weight: .bold)).monospacedDigit()
        }
        .foregroundStyle(RetroPaint.label)
        .lineLimit(1).minimumScaleFactor(0.7)
        .padding(.trailing, 10)
        .padding(.bottom, 4)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomTrailing)
    }
}

/// The drive as a key: pressed, the disk goes in with a click.
struct RetroDriveStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View { RetroDriveBody(configuration: configuration) }
}
private struct RetroDriveBody: View {
    let configuration: ButtonStyle.Configuration
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(RetroDriveFace(pressed: down).equatable())
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.click, scale: 0.8)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// The exposure wheel seen edge-on: its ridges, darker toward its ends as it
/// curves away, a dark well round it. `turn` moves the ridges along.
private struct RetroWheelFace: View, Equatable {
    var turn: CGFloat
    var body: some View {
        Canvas { context, size in
            let rect = CGRect(origin: .zero, size: size), tone = RetroPaint.wheel
            context.fill(Path(roundedRect: rect.insetBy(dx: -2, dy: -2), cornerRadius: 6), with: .color(Color.black.opacity(0.55)))
            let wheel = Path(roundedRect: rect, cornerRadius: 5)
            let shade = Gradient(stops: [Gradient.Stop(color: tone.color(-0.6), location: 0), Gradient.Stop(color: tone.color(0.15), location: 0.3),
                                         Gradient.Stop(color: tone.color(0), location: 0.6), Gradient.Stop(color: tone.color(-0.65), location: 1)])
            context.fill(wheel, with: .linearGradient(shade, startPoint: .zero, endPoint: CGPoint(x: size.width, y: 0)))
            var inner = context
            inner.clip(to: wheel)
            let count = max(4, Int((size.width / 4.2).rounded()))
            let spacing = 1 / CGFloat(count)
            var phase = (turn / 7).truncatingRemainder(dividingBy: 1)
            if phase < 0 { phase += 1 }
            for i in -1...count {
                let t = (CGFloat(i) + phase) * spacing
                guard t >= 0, t <= 1 else { continue }
                let x = size.width * (0.5 - 0.5 * CGFloat(cos(Double(t) * Double.pi)))
                inner.fill(Path(CGRect(x: x, y: 0, width: 1.1, height: size.height)), with: .color(Color.black.opacity(0.5)))
                inner.fill(Path(CGRect(x: x + 1.1, y: 0, width: 0.7, height: size.height)), with: .color(Color.white.opacity(0.22)))
            }
        }
    }
}

/// The exposure wheel: drawn along, a notch (half a stop) at a time, each
/// with its click and its feel; touched on its left or right half, one
/// notch that way. (With Reduce Motion it does not spin back after a drag.)
private struct RetroWheel: View {
    /// −2 … 2.
    var value: Double
    var step: (Int) -> Void
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var pull: CGFloat = 0
    @State private var used: CGFloat = 0
    @State private var turning = false
    /// Points of drag to a notch.
    static let notch: CGFloat = 16
    var body: some View {
        GeometryReader { geo in
            RetroWheelFace(turn: CGFloat(value) * 2 * Self.notch + pull).equatable()
                .padding(room)
                .frame(width: geo.size.width, height: geo.size.height)
                .contentShape(Rectangle())
                .gesture(DragGesture(minimumDistance: 0)
                    .onChanged { drag in
                        let dx = drag.translation.width
                        if abs(dx) > 6 { turning = true }
                        guard turning else { return }
                        var left = dx - used
                        while abs(left) >= Self.notch {
                            let way: CGFloat = left > 0 ? 1 : -1
                            used += way * Self.notch
                            left -= way * Self.notch
                            ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
                            ConsoleHaptics.shared.play(.sliderNotch, .press)
                            step(way > 0 ? 1 : -1)
                        }
                        pull = left
                    }
                    .onEnded { drag in
                        if !turning {
                            ConsoleSounds.shared.play(.keyRatchet, scale: 0.8)
                            ConsoleHaptics.shared.play(.sliderNotch, .press)
                            step(drag.location.x < geo.size.width / 2 ? -1 : 1)
                        }
                        turning = false
                        used = 0
                        if reduceMotion { pull = 0 } else { withAnimation(.easeOut(duration: 0.12)) { pull = 0 } }
                    })
        }
    }
}

/// A window on the tube's desktop: its title bar of ink with the title in
/// paper-white and the small box at its left, a paper-white inside, an ink
/// edge, the shadow it throws.
private struct RetroWindow<Content: View>: View {
    var title: String
    @ViewBuilder var content: () -> Content
    var body: some View {
        VStack(spacing: 0) {
            ZStack {
                RetroPaint.ink
                Text(title).font(.system(size: 10, weight: .heavy, design: .monospaced)).foregroundStyle(RetroPaint.paper)
                    .lineLimit(1).minimumScaleFactor(0.6)
                    .padding(.horizontal, 20)
                HStack {
                    Rectangle().fill(RetroPaint.paper).frame(width: 9, height: 9)
                    Spacer(minLength: 0)
                }
                .padding(.leading, 5)
            }
            .frame(height: 17)
            .accessibilityHidden(true)
            content()
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
        .background(RetroPaint.paper)
        .overlay(Rectangle().strokeBorder(RetroPaint.ink, lineWidth: 1.5))
        .background(Rectangle().fill(Color.black.opacity(0.35)).offset(x: 3, y: 3))
    }
}

/// A notice on the desktop, in a small box of its own.
private struct RetroNotice: View {
    var text: String
    var body: some View {
        Text(text).font(.system(size: 11, weight: .bold)).foregroundStyle(RetroPaint.ink)
            .multilineTextAlignment(.center).lineLimit(2).minimumScaleFactor(0.7)
            .padding(.horizontal, 10).padding(.vertical, 6)
            .background(RetroPaint.paper)
            .overlay(Rectangle().strokeBorder(RetroPaint.ink, lineWidth: 1.5))
            .background(Rectangle().fill(Color.black.opacity(0.35)).offset(x: 3, y: 3))
    }
}

/// The retro computer's 图片盘: the same computer, its tube showing the
/// disk's window — the pictures as files, a small picture over each name
/// (the place in the album: ZERO0007.JPG), the chosen one's name in
/// reverse. The arrow keys move the choice (left and right one, up and down
/// a row); 回车 opens the chosen one in a window of its own over the list (a
/// video plays there), and plays or stops a video open; 关窗口 shuts that
/// window. 回去拍照 and the Enter key under the thumb (its words under it)
/// go back to taking pictures; 机型 goes back to them with the bodies'
/// cards open; 主菜单 does what it always does. 定时 and 水平仪 wait, and
/// say why.
private struct RetroDisk: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var retro: RetroLayout
    var hinge: CGRect
    /// The chosen picture's window is open over the list.
    @State private var open = false

    private var waiting: String { String(localized: "图片盘里用不了，回去拍照再用") }
    /// While a picture is being drawn on inside, the ways back wait (and say where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private var video: Bool { open && model.albumPhoto?.isVideo == true }

    /// A picture's name on the disk: the name it is kept under on the card
    /// ("ZERO0042.JPG"), the number the digital camera's 回放 and the saved
    /// notice show too.
    static func fileName(_ photo: CameraPhoto) -> String {
        photo.name.uppercased()
    }
    /// When it was taken: year.month.day hour:minute, as a camera stamps it.
    static func stamp(_ date: Date) -> String {
        let c = Calendar.current.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return String(format: "%04d.%02d.%02d %02d:%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0)
    }
    /// The shape nearest the picture's own ("" before it is read).
    static func shape(_ image: CGImage?) -> String {
        guard let image, image.height > 0 else { return "" }
        let ratio = Double(image.width) / Double(image.height)
        return CameraAspect.allCases.min { abs($0.ratio - ratio) < abs($1.ratio - ratio) }?.title ?? ""
    }
    private func sharp(_ photo: CameraPhoto) -> CGImage? {
        (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }

    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    private func toBodies() {
        if drawing { model.say(drawingWhy); return }
        model.closeAlbum()
        model.openBodies()
    }
    private func choose(_ next: Int) {
        guard model.photos.indices.contains(next), next != model.albumIndex, model.doodle == nil else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }
    /// 0 up, 1 right, 2 down, 3 left (up and down a row of the list).
    private func move(_ way: Int) {
        let at = model.albumIndex, columns = max(1, retro.fileColumns)
        switch way {
        case 0: choose(at - columns)
        case 1: choose(at + 1)
        case 2: choose(at + columns)
        default: choose(at - 1)
        }
    }
    /// 回车: the chosen one opened; with a video open, 播放 or 停止.
    private func enter() {
        if model.photos.isEmpty {
            model.say(String(localized: "还没有照片"))
        } else if !open {
            open = true
        } else if video {
            model.togglePlay()
        } else {
            model.say(String(localized: "已经在看这一张"))
        }
    }
    /// 关窗口: back from the picture to the list.
    private func shut() {
        guard open else { model.say(String(localized: "没有打开的窗口")); return }
        if model.playing != nil { model.togglePlay() }
        open = false
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            RetroBackdrop(layout: retro, hinge: hinge, album: true).equatable()
            screen
            menu
            RetroMarks(layout: retro, lamp: RetroPaint.green)
            disk
            commandKeys
            arrowKeys
            waitingKeys
            // (the desk has no Enter key of its own: 回去拍照 is on the keyboard, the space bar's row is 回车)
            if !retro.desk { closeKey }
        }
    }

    /// The menu bar: the disk's menus, which picture of how many.
    private var menu: some View {
        let photos = model.photos
        let place = photos.isEmpty ? "0" : "\(model.albumIndex + 1) / \(photos.count)"
        let items = [String(localized: "相机"), CameraShellSkin.computer.albumTitle, String(localized: "机型")]
        return RetroMenuBar(items: items, trailing: place, counts: true)
            .deckPlaced(retro.albumMenu)
    }

    /// What the tube shows: the desktop, the disk's window, the chosen
    /// picture's window over it; while a picture is being drawn on inside,
    /// that it waits there; what the camera says, for a moment.
    private var screen: some View {
        let face = retro.albumFace
        let desk = CGRect(x: 0, y: 20.6, width: face.width, height: max(0, face.height - 20.6))
        return ZStack(alignment: .topLeading) {
            RetroPaint.glass
            RetroPaint.desktop.frame(width: desk.width, height: desk.height).offset(y: desk.minY)
            list(desk)
            if open, let photo = model.albumPhoto { window(photo, desk) }
            notices(desk)
        }
        .frame(width: face.width, height: face.height, alignment: .topLeading)
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 13, style: .continuous).stroke(Color.black.opacity(0.7), lineWidth: 2).padding(-1))
        .position(x: face.midX, y: face.midY)
    }

    private func list(_ desk: CGRect) -> some View {
        let wide: CGFloat = min(retro.across ? 230 : 150, desk.width * 0.55)
        let high: CGFloat = max(60, desk.height - 22)
        return RetroWindow(title: CameraShellSkin.computer.albumTitle) {
            files(CGSize(width: wide, height: high - 17))
        }
        .frame(width: wide, height: high)
        .position(x: desk.minX + 8 + wide / 2, y: desk.minY + 9 + high / 2)
    }

    /// The files of the page the chosen one is on.
    private func files(_ size: CGSize) -> some View {
        let photos = model.photos, at = model.albumIndex
        let columns = max(1, retro.fileColumns)
        let cell: CGFloat = max(30, (size.width - 24 - CGFloat(columns - 1) * 16) / CGFloat(columns))
        let thumb: CGFloat = (cell * 0.68).rounded()
        let pitch: CGFloat = thumb + 22
        let rows = max(1, Int((size.height - 1) / pitch))
        let page = columns * rows
        let first = (at / page) * page
        return ZStack(alignment: .topLeading) {
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 11, weight: .bold)).foregroundStyle(RetroPaint.ink.opacity(0.7))
                    .frame(width: size.width, height: size.height)
            }
            ForEach(0..<page, id: \.self) { slot in
                if photos.indices.contains(first + slot) {
                    file(photos[first + slot], slot: slot, index: first + slot, chosen: first + slot == at, cell: cell, thumb: thumb,
                         origin: CGPoint(x: 12 + CGFloat(slot % columns) * (cell + 16), y: 8 + CGFloat(slot / columns) * pitch))
                }
            }
        }
        .frame(width: size.width, height: size.height, alignment: .topLeading)
    }

    private func file(_ photo: CameraPhoto, slot: Int, index: Int, chosen: Bool, cell: CGFloat, thumb: CGFloat, origin: CGPoint) -> some View {
        let name = Self.fileName(photo)
        return Button {
            ConsoleSounds.shared.play(.tick, scale: 0.6)
            if !chosen { model.chooseInAlbum(index, quiet: true) }
            open = true
        } label: {
            VStack(spacing: 3) {
                ZStack(alignment: .bottomLeading) {
                    Color(white: 0.72)
                    if let image = thumbnails.images[photo.url] {
                        Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill())
                    }
                    if photo.isVideo {
                        Image(systemName: "video.fill").font(.system(size: 9, weight: .bold)).foregroundStyle(.white)
                            .shadow(color: .black.opacity(0.7), radius: 2).padding(3)
                    }
                }
                .frame(width: cell, height: thumb)
                .clipped()
                .overlay(Rectangle().strokeBorder(RetroPaint.ink, lineWidth: chosen ? 3 : 1))
                Text(verbatim: name).font(.system(size: 10, weight: .bold)).lineLimit(1).minimumScaleFactor(0.6)
                    .foregroundStyle(chosen ? RetroPaint.paper : RetroPaint.ink)
                    .frame(width: cell + 10, height: 12)
                    .background(chosen ? RetroPaint.ink : Color.clear)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .position(x: origin.x + cell / 2, y: origin.y + (thumb + 15) / 2)
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityLabel(name)
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-album-cell-\(slot)")
    }

    /// The chosen picture in a window of its own: its name over it, when it
    /// was taken and its shape under it.
    private func window(_ photo: CameraPhoto, _ desk: CGRect) -> some View {
        let fraction: CGFloat = retro.across ? 0.3 : 0.36
        let start = desk.minX + desk.width * fraction
        let most = max(40, desk.height - 56)
        let tall = min((desk.maxX - 8 - start - 12) * 0.75, most)
        let wide = tall / 0.75 + 12
        let high = tall + 40
        let top = desk.minY + max(8, min(30, (desk.height - high) / 2))
        let image = sharp(photo)
        let kind = photo.isVideo ? String(localized: "录像") : Self.shape(image)
        let caption = Self.stamp(photo.date) + " · " + kind
        return RetroWindow(title: Self.fileName(photo)) {
            VStack(spacing: 0) {
                picture(photo, image: image, size: CGSize(width: wide - 12, height: tall))
                    .padding(.top, 5)
                Text(verbatim: caption).font(.system(size: 10, weight: .bold)).foregroundStyle(RetroPaint.ink)
                    .lineLimit(1).minimumScaleFactor(0.7)
                    .frame(height: 18)
                    .accessibilityHidden(true)
            }
            .frame(maxWidth: .infinity)
        }
        .frame(width: wide, height: high)
        .position(x: desk.maxX - 8 - wide / 2, y: top + high / 2)
    }

    private func picture(_ photo: CameraPhoto, image: CGImage?, size: CGSize) -> some View {
        ZStack {
            Color.black
            if let image { Image(decorative: image, scale: 1).resizable().scaledToFit() }
            if photo.isVideo {
                #if os(iOS)
                if model.playing == photo.url {
                    CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                        .accessibilityIdentifier("camera-album-player")
                }
                #endif
                if model.playing != photo.url {
                    Image(systemName: "play.circle.fill").font(.system(size: 34)).foregroundStyle(.white.opacity(0.9))
                        .shadow(color: .black.opacity(0.5), radius: 4)
                }
            }
        }
        .frame(width: size.width, height: size.height)
        .clipped()
        .contentShape(Rectangle())
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : CameraShellSkin.computer.albumTitle)
        .accessibilityValue(Self.fileName(photo))
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    @ViewBuilder private func notices(_ desk: CGRect) -> some View {
        if model.doodle != nil {
            RetroNotice(text: drawingWhy)
                .frame(width: max(0, desk.width - 40))
                .position(x: desk.midX, y: desk.midY)
        }
        if let toast = model.toast {
            RetroNotice(text: toast)
                .frame(width: max(0, desk.width - 40))
                .position(x: desk.midX, y: desk.maxY - 28)
                .allowsHitTesting(false)
                .transition(.opacity)
        }
    }

    /// The drive with the disk in it, and the words beside it (upright).
    @ViewBuilder private var disk: some View {
        RetroDriveFace(pressed: false).equatable()
            .overlay { RetroDriveLabel(count: model.photos.count) }
            .accessibilityHidden(true)
            .deckPlaced(retro.albumDrive)
        if retro.albumNote.width > 0 {
            Text("图片都在这张盘里").font(.system(size: 10.5, weight: .bold)).foregroundStyle(RetroPaint.legend.opacity(0.8))
                .lineLimit(1).minimumScaleFactor(0.7)
                .accessibilityHidden(true)
                .deckPlaced(retro.albumNote)
        }
    }

    private func key(_ word: String, symbol: String? = nil, size: CGFloat = 12, stacked: Bool = false, tone: ShellTone = RetroPaint.plastic,
                     label: String? = nil, value: String = "", identifier: String, action: @escaping () -> Void) -> some View {
        Button(action: action) { RetroWordLabel(word: word, symbol: symbol, size: size, stacked: stacked) }
            .buttonStyle(RetroKeyStyle(tone: tone))
            .accessibilityLabel(label ?? word)
            .accessibilityValue(value)
            .accessibilityIdentifier(identifier)
    }
    /// A key with a glyph printed on it (`face`) in place of its word;
    /// VoiceOver says `label`, as it said the word.
    private func glyphKey<Face: View>(label: String, value: String = "", tone: ShellTone = RetroPaint.plastic, identifier: String,
                                      action: @escaping () -> Void, @ViewBuilder face: () -> Face) -> some View {
        Button(action: action) { face() }
            .buttonStyle(RetroKeyStyle(tone: tone))
            .accessibilityLabel(label)
            .accessibilityValue(value)
            .accessibilityIdentifier(identifier)
    }

    /// 主菜单 (a house), 机型 (two cameras traded), 回去拍照 (its words
    /// kept), 关窗口 (a cross), 回车 (the return mark, and what it does now:
    /// the magnifying glass to open the chosen one, ▶ or ■ for a video open).
    @ViewBuilder private var commandKeys: some View {
        let none = model.photos.isEmpty
        let opening: String = !open ? String(localized: "打开") : (model.playing != nil ? String(localized: "停止") : String(localized: "播放"))
        let idle = none || (open && !video)
        let idleWhy: String = none ? String(localized: "还没有照片") : String(localized: "已经在看这一张")
        let shutWord = String(localized: "关窗口")
        let back = String(localized: "回去拍照")
        let size: CGFloat = retro.across ? 16 : 20
        let doing: ShellGlyph = !open ? .zoomIn : (model.playing != nil ? .stop : .play)
        glyphKey(label: String(localized: "camera.home.pill"), identifier: "camera-deck-home", action: { model.leave() }) {
            ShellGlyphView(glyph: .home, size: size, ink: RetroPaint.legend)
        }
        .deckKey(retro.albumRect(.home))
        glyphKey(label: String(localized: "切换机型"), value: model.body.title, identifier: "camera-deck-bodies", action: { toBodies() }) {
            ShellGlyphView(glyph: .changeBody, size: retro.across ? 20 : 24, ink: RetroPaint.legend)
        }
        .deckDimmed(drawing, why: drawingWhy)
        .deckKey(retro.albumRect(.bodies))
        glyphKey(label: back, tone: RetroPaint.darker, identifier: "camera-deck-album-return", action: { backToCamera() }) {
            ShellGlyphLabel(glyph: .returnToShooting, words: back, size: 15, wordSize: 12, ink: RetroPaint.legend, stacked: !retro.across)
                .padding(.horizontal, 4)
        }
        .deckDimmed(drawing, why: drawingWhy)
        .deckKey(retro.albumRect(.back))
        glyphKey(label: shutWord, tone: RetroPaint.darker, identifier: "camera-deck-album-back", action: { shut() }) {
            RetroCloseGlyph(size: retro.across ? 15 : 18)
        }
        .deckDimmed(!open, why: String(localized: "没有打开的窗口"))
        .deckKey(retro.albumRect(.close))
        glyphKey(label: opening, identifier: open ? "camera-deck-album-play" : "camera-deck-album-view", action: { enter() }) {
            HStack(spacing: 8) {
                RetroReturnMark().stroke(style: StrokeStyle(lineWidth: 1.8, lineCap: .round, lineJoin: .round)).frame(width: 14, height: 11)
                ShellGlyphView(glyph: doing, size: 18, ink: RetroPaint.legend)
            }
        }
        .deckDimmed(idle, why: idleWhy)
        .deckKey(retro.albumRect(.enter))
    }

    /// ↑ ↓ ← →: the choice among the files.
    @ViewBuilder private var arrowKeys: some View {
        let none = model.photos.isEmpty, empty = String(localized: "还没有照片")
        key("↑", size: 18, label: String(localized: "向上"), identifier: "camera-deck-album-up") { move(0) }
            .deckDimmed(none, why: empty)
            .deckKey(retro.albumRect(.up))
        key("→", size: 18, label: String(localized: "下一张"), identifier: "camera-deck-album-next") { move(1) }
            .deckDimmed(none, why: empty)
            .deckKey(retro.albumRect(.right))
        key("↓", size: 18, label: String(localized: "向下"), identifier: "camera-deck-album-down") { move(2) }
            .deckDimmed(none, why: empty)
            .deckKey(retro.albumRect(.down))
        key("←", size: 18, label: String(localized: "上一张"), identifier: "camera-deck-album-previous") { move(3) }
            .deckDimmed(none, why: empty)
            .deckKey(retro.albumRect(.left))
    }

    /// 定时 and 水平仪: they set the camera, and wait for it.
    @ViewBuilder private var waitingKeys: some View {
        let on = String(localized: "开"), off = String(localized: "关")
        let levelState: String = model.leveler ? on : off
        let size: CGFloat = retro.across ? 16 : 20
        Button { model.say(waiting) } label: { RetroCapLabel(glyph: .timer(model.timer), size: size) }
            .buttonStyle(RetroKeyStyle())
            .accessibilityLabel(String(localized: "定时"))
            .accessibilityValue(model.timer.title)
            .accessibilityIdentifier("camera-deck-timer")
            .deckDimmed(true, why: waiting)
            .deckKey(retro.albumTimer)
        Button { model.say(waiting) } label: { RetroCapLabel(glyph: .level(model.leveler), size: size) }
            .buttonStyle(RetroKeyStyle())
            .accessibilityLabel(String(localized: "水平仪"))
            .accessibilityValue(levelState)
            .accessibilityIdentifier("camera-deck-leveler")
            .deckDimmed(true, why: waiting)
            .deckKey(retro.albumLevel)
    }

    /// The Enter key under the thumb: back to taking pictures (回去拍照 under it, upright).
    @ViewBuilder private var closeKey: some View {
        Button { backToCamera() } label: { RetroCloseLabel(words: retro.across) }
            .buttonStyle(RetroKeyStyle(tone: RetroPaint.darker, sound: .keyMetal))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-close")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(retro.shutter)
        if retro.closeCaption.width > 0 {
            Text(String(localized: "回去拍照")).font(.system(size: 10, weight: .heavy)).foregroundStyle(RetroPaint.legend)
                .lineLimit(1).fixedSize()
                .accessibilityHidden(true)
                .deckPlaced(retro.closeCaption)
        }
    }
}

extension CameraDeckFace {
    /// The retro computer's body under its keys, upright and across.
    func retroBackdrop(_ retro: RetroLayout) -> some View {
        RetroBackdrop(layout: retro, hinge: hinge).equatable()
    }

    /// The tube over the picture: its black round the picture, and the menu
    /// bar along the face's top (the lens, the picture's shape, what is left).
    @ViewBuilder func retroScreen(_ retro: RetroLayout) -> some View {
        RetroGlass(black: RetroLayout.inset(retro.bezel, step: 2, across: retro.across), face: retro.face, hole: layout.picture).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        RetroMenuBar(items: retroMenu, trailing: retroStatus)
            .accessibilityHidden(true)
            .deckPlaced(retro.menu)
    }
    private var retroMenu: [String] {
        [String(localized: "相机"), String(localized: "镜头") + " " + model.lens.title, String(localized: "机型"), model.shape.title]
    }
    /// The menu bar's right end: a video's time while one is taken, the
    /// self-timer's seconds while it counts; else how many pictures are left.
    private var retroStatus: String {
        if model.mode == .video, model.recording {
            return String(localized: "录像") + " " + CameraAppModel.clock(model.recordedSeconds)
        }
        if let left = model.countdown {
            let seconds = String(localized: "\(left) 秒")
            return String(localized: "定时 \(seconds)")
        }
        return String(localized: "余 \(CameraFileNames.remainingText(model.remaining))")
    }

    /// The retro computer, upright or across (the same keys, each where its
    /// hold has it): ZERO and the lamp; the drive (相册); the wheel (曝光);
    /// 闪光, 白平衡, ISO, 日期, 翻转; 主菜单, 机型, 录像, 比例; 变焦 − +,
    /// ‹ 镜头 ›; 浓淡 − +; 定时, 水平仪; the Enter key under the thumb and
    /// the space bar, both 拍照.
    @ViewBuilder func retroFace(_ retro: RetroLayout) -> some View {
        RetroMarks(layout: retro, lamp: model.recording ? RetroPaint.red : RetroPaint.green)
        retroDrive(retro)
        retroWheel(retro)
        retroSettingKeys(retro)
        retroSideKeys(retro)
        retroMoveKeys(retro)
        retroShutters(retro)
    }

    /// The retro computer's 图片盘, upright and across.
    @ViewBuilder func retroAlbum(_ retro: RetroLayout) -> some View {
        RetroDisk(model: model, thumbnails: thumbnails, retro: retro, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }

    /// A keycap: its glyph, drawn as what it sets stands (the figures or the
    /// cells that go with it under it). VoiceOver says its name (`title`,
    /// or `label`), as it said the words printed on it.
    private func retroCap(_ title: String, glyph: ShellGlyph, figures: String = "", cells: ShellGlyph? = nil, size: CGFloat = 20, stacked: Bool = false,
                          label: String? = nil, value: String = "", selected: Bool = false,
                          identifier: String, tone: ShellTone = RetroPaint.plastic, action: @escaping () -> Void) -> some View {
        Button(action: action) { RetroCapLabel(glyph: glyph, figures: figures, cells: cells, size: size, stacked: stacked) }
            .buttonStyle(RetroKeyStyle(tone: tone))
            .accessibilityLabel(label ?? title)
            .accessibilityValue(value)
            .accessibilityAddTraits(selected ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier(identifier)
    }

    /// The drive: the album, how many pictures are on the disk on its label.
    private func retroDrive(_ retro: RetroLayout) -> some View {
        Button { model.openAlbum() } label: { RetroDriveLabel(count: model.photos.count) }
            .buttonStyle(RetroDriveStyle())
            .accessibilityLabel(CameraShellSkin.computer.albumTitle)
            .accessibilityValue(String(localized: "\(model.photos.count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .deckKey(retro.drive)
    }

    /// The wheel (曝光), and how it is set printed by it (± in a circle, and
    /// its figures).
    @ViewBuilder private func retroWheel(_ retro: RetroLayout) -> some View {
        let shooting = model.shooting, word = String(localized: "曝光")
        RetroWheel(value: shooting.exposure) { model.stepExposure($0) }
            .accessibilityElement()
            .accessibilityLabel(word)
            .accessibilityValue(shooting.exposureTitle)
            .accessibilityAdjustableAction { direction in model.stepExposure(direction == .increment ? 1 : -1) }
            .accessibilityIdentifier("camera-deck-ev")
            .environment(\.deckKeyInset, retro.wheelRoom)
            .deckPlaced(retro.wheel)
        ShellGlyphView(glyph: .exposure(shooting.exposureTitle), size: retro.across ? 15 : 17, ink: RetroPaint.legend.opacity(0.85))
            .allowsHitTesting(false)
            .accessibilityHidden(true)
            .deckPlaced(retro.wheelCaption)
    }

    /// 闪光, 白平衡, ISO, 日期, 翻转, 录像, 比例: each glyph drawn as it is set
    /// (ISO and WB keep the letters a camera prints, 比例 its figures).
    @ViewBuilder private func retroSettingKeys(_ retro: RetroLayout) -> some View {
        let shooting = model.shooting
        let on = String(localized: "开"), off = String(localized: "关")
        let dateState: String = shooting.dateStamp ? on : off
        let sideWord: String = model.side == .inner ? String(localized: "内侧") : String(localized: "外侧")
        let video = model.mode == .video
        let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
        let size: CGFloat = retro.across ? 16 : 20
        retroCap(String(localized: "闪光"), glyph: .flash(shooting.flash), size: size, value: shooting.flash.title, identifier: "camera-deck-flash") { model.cycleFlash() }
            .deckKey(retro.rect(.flash))
        retroCap(String(localized: "白平衡"), glyph: .whiteBalance(shooting.whiteBalance), size: size, value: shooting.whiteBalance.title,
                 identifier: "camera-deck-wb") { model.cycleWhiteBalance() }
            .deckKey(retro.rect(.balance))
        retroCap("ISO", glyph: .iso(shooting.iso), size: size, value: shooting.iso.title, identifier: "camera-deck-iso") { model.cycleISO() }
            .deckKey(retro.rect(.iso))
        retroCap(String(localized: "日期"), glyph: .date(shooting.dateStamp), size: size, value: dateState,
                 selected: shooting.dateStamp, identifier: "camera-deck-date") { model.toggleDateStamp() }
            .deckKey(retro.rect(.date))
        retroCap(String(localized: "翻转"), glyph: .flip, size: size, label: String(localized: "切换内侧、外侧相机"), value: sideWord,
                 identifier: "camera-deck-switch") { model.switchSide() }
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(retro.rect(.flip))
        retroCap(videoWord, glyph: .video(video), size: size, label: photoWord + " / " + videoWord, value: video ? videoWord : photoWord,
                 selected: video, identifier: "camera-deck-mode") { model.setMode(video ? .photo : .video) }
            .deckKey(retro.rect(.mode))
        retroCap(CameraShellSkin.computer.shapeTitle, glyph: .shape(model.shape), size: size, stacked: retro.across, value: model.shape.title,
                 identifier: "camera-deck-aspect") {
            withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
        }
        .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
        .deckKey(retro.rect(.shape))
    }

    /// 主菜单 (a house), 机型 (two cameras traded); 定时 and 水平仪 (in the
    /// strip upright), drawn as they are set.
    @ViewBuilder private func retroSideKeys(_ retro: RetroLayout) -> some View {
        let on = String(localized: "开"), off = String(localized: "关")
        let timed: String = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
        let levelState: String = model.leveler ? on : off
        let size: CGFloat = retro.across ? 16 : 20
        retroCap(String(localized: "camera.home.pill"), glyph: .home, size: size, identifier: "camera-deck-home") { model.leave() }
            .deckKey(retro.rect(.home))
        retroCap(String(localized: "机型"), glyph: .changeBody, size: retro.across ? 20 : 24, label: String(localized: "切换机型"), value: model.body.title,
                 selected: model.bodiesOpen, identifier: "camera-deck-bodies") {
            if model.bodiesOpen { model.closeBodies() } else { model.openBodies() }
        }
        .deckKey(retro.rect(.bodies))
        retroCap(String(localized: "定时"), glyph: .timer(model.timer), size: size, value: timed, selected: model.timer != .off, identifier: "camera-deck-timer") { model.cycleTimer() }
            .deckKey(retro.rect(.timer))
        retroCap(String(localized: "水平仪"), glyph: .level(model.leveler), size: size, value: levelState, selected: model.leveler,
                 identifier: "camera-deck-leveler") { model.toggleLeveler() }
            .deckKey(retro.rect(.level))
    }

    /// 变焦 − + (the magnifying glass less and more, the zoom's figures
    /// under it), ‹ 镜头 › (the filters' circles and an arrow; the lens in
    /// use is on the menu bar), 浓淡 − + (its step as a row of cells under
    /// it; 原生 has none: a dash).
    @ViewBuilder private func retroMoveKeys(_ retro: RetroLayout) -> some View {
        let zoomWord = String(localized: "变焦"), lensWord = String(localized: "镜头"), strengthWord = String(localized: "浓淡")
        let factor = Self.zoomText(model.zoom)
        let shown = model.shownBody
        let step = model.strengthStep(of: shown)
        let share = CameraBodyStrength.title(step)
        let lit = step - CameraBodyStrength.range.lowerBound + 1
        let cells: ShellGlyph? = shown == .native ? nil : ShellGlyph.tone(step: lit, of: CameraBodyStrength.values.count)
        let dash = shown == .native ? "—" : ""
        let lens = model.lens.title
        let size: CGFloat = retro.across ? 16 : 20
        retroCap(zoomWord + " −", glyph: .zoomOut, figures: factor, size: size, value: factor, identifier: "camera-deck-zoom-out") { phoneNavigate(2) }
            .deckKey(retro.rect(.zoomOut))
        retroCap(zoomWord + " +", glyph: .zoomIn, figures: factor, size: size, value: factor, identifier: "camera-deck-zoom-in") { phoneNavigate(0) }
            .deckKey(retro.rect(.zoomIn))
        retroCap("‹ " + lensWord, glyph: .lensPrevious, size: size, label: lensWord + " ‹", value: lens, identifier: "camera-deck-lens-previous") { retroStepLens(-1) }
            .deckKey(retro.rect(.lensBack))
        retroCap(lensWord + " ›", glyph: .lensNext, size: size, label: lensWord + " ›", value: lens, identifier: "camera-deck-lens-next") { retroStepLens(1) }
            .deckKey(retro.rect(.lensOn))
        retroCap(strengthWord + " −", glyph: .toneDown, figures: dash, cells: cells, size: size, value: share, identifier: "camera-deck-strength-minus",
                 tone: RetroPaint.darker) { model.stepBodyStrength(-1) }
            .deckKey(retro.rect(.lighter))
        retroCap(strengthWord + " +", glyph: .toneUp, figures: dash, cells: cells, size: size, value: share, identifier: "camera-deck-strength-plus",
                 tone: RetroPaint.darker) { model.stepBodyStrength(1) }
            .deckKey(retro.rect(.stronger))
    }

    /// ‹ 镜头 / 镜头 ›: the lenses one by one (with a video, only those that
    /// take one); past the last of them the first body pinned among them,
    /// as a pinned chip does it (the body changes, and with it the back).
    private func retroStepLens(_ delta: Int) {
        let lenses = CameraLens.allCases
        guard let at = lenses.firstIndex(of: model.lens) else { return }
        var next = at + delta
        while lenses.indices.contains(next), model.mode == .video, !lenses[next].records { next += delta }
        if lenses.indices.contains(next) {
            model.choose(lenses[next])
        } else if delta > 0, let pinned = model.pinnedBodies.first(where: { $0 != model.body }) {
            model.tapPinned(pinned)
        } else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
        }
    }

    /// 拍照: the Enter key under the thumb (a camera and the return mark),
    /// and the space bar (upright: a camera); for a video a red dot, the
    /// square and the time while one runs.
    @ViewBuilder private func retroShutters(_ retro: RetroLayout) -> some View {
        let video = model.mode == .video
        let clock = CameraAppModel.clock(model.recordedSeconds)
        let said: String = video ? (model.recording ? String(localized: "停止录像") : String(localized: "开始录像")) : String(localized: "拍照")
        let state: String = model.canShoot ? (video ? String(localized: "可以录") : String(localized: "可以拍")) : String(localized: "等一下")
        // (the desk, 11-22: the space bar is 拍照, and the only one)
        Button { model.shutter() } label: {
            RetroShutterLabel(video: video, recording: model.recording, clock: clock, ready: model.canShoot, enter: !retro.desk, size: retro.desk ? 22 : 18)
        }
        .buttonStyle(RetroKeyStyle(tone: retro.desk ? RetroPaint.plastic : RetroPaint.darker, sound: .keyMetal, haptic: .faceButton))
        .accessibilityLabel(said)
        .accessibilityValue(state)
        .accessibilityIdentifier("camera-deck-shutter")
        .deckKey(retro.shutter)
        if retro.space.width > 0 {
            Button { model.shutter() } label: {
                RetroShutterLabel(video: video, recording: model.recording, clock: clock, ready: model.canShoot, size: 22)
            }
            .buttonStyle(RetroKeyStyle(sound: .keyMetal, haptic: .faceButton))
            .accessibilityLabel(said)
            .accessibilityValue(state)
            .accessibilityIdentifier("camera-deck-shutter-space")
            .deckKey(retro.space)
        }
    }
}

// MARK: - The soda cooler's back

/// The soda cooler's colours (mock/sd7.js): the mint enamel, the teal of
/// its trim and of the price tags' heads, the orange of the big cap and the
/// cream of its print; what is printed — the ink, the softer ink, the grey
/// of a setting that is off, the warm brown of one that is on — the chosen
/// zoom stop's teal, the shade the cabinet casts, the tags' paper, the
/// door's rubber seal and the red of a video. White enamel and bright metal
/// besides, and nothing else.
enum SodaPaint {
    static let mint = ShellTone(r: 0.620, g: 0.855, b: 0.769)
    static let teal = ShellTone(r: 0.102, g: 0.549, b: 0.502)
    static let orange = ShellTone(r: 0.941, g: 0.510, b: 0.196)
    static let cream = ShellTone(r: 1.0, g: 0.973, b: 0.902)
    static let ink = Color(red: 0.071, green: 0.247, blue: 0.231)
    static let soft = Color(red: 0.231, green: 0.396, blue: 0.380)
    static let grey = Color(red: 0.510, green: 0.576, blue: 0.561)
    static let warm = Color(red: 0.604, green: 0.290, blue: 0.0)
    static let on = Color(red: 0.110, green: 0.604, blue: 0.541)
    static let shade = Color(red: 0.0, green: 0.157, blue: 0.118)
    static let paper = Color(red: 1.0, green: 0.992, blue: 0.969)
    static let seal = Color(red: 0.086, green: 0.106, blue: 0.118)
    static let red = Color(red: 0.851, green: 0.227, blue: 0.169)
}

/// How a price tag's lower line reads: a setting that is off (grey), a
/// value (the softer ink), one that is on (warm, bolder).
enum SodaTagTone { case off, value, on }

/// What the big cap's print shows: a camera; for a video a red dot, the
/// square while one is taken.
enum SodaCapSign { case camera, record, stop }

/// One bottle on the shelf: its glass, the drink in it (none: the glass
/// alone, coloured), its crown cap, its label and what is printed on it,
/// the lens's glyph on the label (a 机型 pinned among the lenses: a small
/// drawing of its kind of camera), and bubbles in a clear one. Straight
/// bottles of the cooler's own, no maker's.
struct SodaBottleLook: Equatable {
    var glass: Color
    var drink: Color?
    var cap: Color
    var label: Color
    var ink: Color
    var symbol: String
    var fizz = false
    var pinnedBody: CameraBody? = nil

    private static func rgb(_ r: Double, _ g: Double, _ b: Double) -> Color { Color(red: r / 255, green: g / 255, blue: b / 255) }
    /// The lens's bottle.
    static func of(_ lens: CameraLens) -> SodaBottleLook {
        let clear = rgb(226, 240, 236), steel = rgb(212, 216, 222)
        switch lens {
        case .normal:
            return SodaBottleLook(glass: clear, drink: rgb(247, 146, 44), cap: steel, label: rgb(255, 244, 214), ink: rgb(110, 54, 6), symbol: lens.symbol)
        case .sparkle:
            return SodaBottleLook(glass: rgb(224, 242, 246), drink: rgb(206, 236, 236), cap: rgb(72, 158, 214), label: rgb(228, 243, 255), ink: rgb(29, 90, 136), symbol: lens.symbol, fizz: true)
        case .merge:
            return SodaBottleLook(glass: rgb(92, 170, 110), drink: nil, cap: steel, label: rgb(250, 248, 236), ink: rgb(36, 88, 47), symbol: lens.symbol)
        case .dream:
            return SodaBottleLook(glass: rgb(230, 238, 246), drink: rgb(196, 178, 238), cap: rgb(244, 244, 246), label: rgb(250, 246, 255), ink: rgb(85, 58, 148), symbol: lens.symbol)
        case .lowLight:
            return SodaBottleLook(glass: rgb(120, 76, 40), drink: nil, cap: rgb(62, 68, 84), label: rgb(242, 230, 204), ink: rgb(74, 46, 16), symbol: lens.symbol)
        case .pinhole:
            return SodaBottleLook(glass: clear, drink: rgb(246, 210, 92), cap: rgb(232, 190, 70), label: rgb(255, 251, 234), ink: rgb(118, 86, 0), symbol: lens.symbol)
        case .mystery:
            return SodaBottleLook(glass: rgb(232, 236, 246), drink: rgb(214, 128, 190), cap: rgb(150, 96, 172), label: rgb(255, 255, 255), ink: rgb(104, 42, 102), symbol: lens.symbol)
        case .pair:
            return SodaBottleLook(glass: clear, drink: rgb(156, 210, 120), cap: steel, label: rgb(246, 252, 236), ink: rgb(62, 106, 30), symbol: lens.symbol)
        case .quad:
            return SodaBottleLook(glass: clear, drink: rgb(124, 196, 230), cap: rgb(72, 120, 190), label: rgb(240, 248, 255), ink: rgb(30, 79, 122), symbol: lens.symbol)
        }
    }
    /// A pinned 机型's bottle: its card's two colours, its kind of camera on the label.
    static func pinned(_ body: CameraBody) -> SodaBottleLook {
        let pair = body.swatch
        return SodaBottleLook(glass: rgb(230, 240, 238), drink: pair.0, cap: pair.1, label: Color.white, ink: pair.1, symbol: "", pinnedBody: body)
    }
}

/// Where the soda cooler's parts are on the cover, upright (from a
/// ShellPlan) or across (from a ShellAcrossPlan): the same parts both ways,
/// each laid out for its hold (mock/sd7.js).
struct SodaLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    var u: CGFloat = 1
    /// The white enamel (along the top and the foot upright; the band and
    /// the other edge across) and the bright trim along each one's inner edge.
    var bands: [CGRect] = []
    var trims: [CGFloat] = []
    /// The light box with ZERO on it; held across, the vent where the
    /// Camera Control's overlay comes in.
    var lightBox = CGRect.zero
    var grille = CGRect.zero
    /// The glass door: its chrome frame, the glass the picture is behind,
    /// the hinges at its side.
    var door = CGRect.zero
    var glass = CGRect.zero
    var hinges: [CGRect] = []
    /// The clear channel (two held across, and on a narrow column), the
    /// seven tags (闪光, 定时, 日期, 画幅, 水平仪, 浓淡 −, 浓淡 +) and the
    /// album's four (上一张, 播放, 下一张, 回去拍照).
    var channels: [CGRect] = []
    var tags: [CGRect] = []
    var albumTags: [CGRect] = []
    /// The lower window and how far in its glass begins; the shelf (the
    /// row that goes along) and the line the bottles stand on; one bottle's
    /// place, how large it is drawn, how far the one in use is lifted, the
    /// gap between two and the room before the first; a small print's place.
    var window = CGRect.zero
    var windowRim: CGFloat = 8.5
    var shelf = CGRect.zero
    var shelfLine: CGFloat = 0
    var bottle = CGSize(width: 44, height: 80)
    var bottleScale: CGFloat = 1
    var bottleLift: CGFloat = 5
    var bottleGap: CGFloat = 6
    var bottlePad: CGFloat = 4
    var printCell: CGFloat = 50
    /// The control plate: the light's toggle (拍照 / 录像), the enamel
    /// plate (机型), the thermostat (变焦: where it is touched — the knob in
    /// the middle of that — and the knob's radius).
    var panel = CGRect.zero
    var toggle = CGRect.zero
    var plate = CGRect.zero
    var knob = CGRect.zero
    var knobRadius: CGFloat = 32
    /// The kick plate's 主菜单 key (its sign over its word held across), the
    /// louvres, the feet.
    var home = CGRect.zero
    var homeStacked = false
    var louvres: [CGRect] = []
    var feet: [CGPoint] = []
    /// The flip card (内 / 外), the picture under its magnet (相册), the
    /// door's handle where the Camera Control's overlay comes in (upright),
    /// the big cap (拍照) and where its word stands: under it, or beside it
    /// (−1: to its left, +1: to its right).
    var flip = CGRect.zero
    var magnet = CGRect.zero
    var handle = CGRect.zero
    var shutter = CGRect.zero
    var capRadius: CGFloat = 31
    var caption = CGPoint.zero
    var captionSide: CGFloat = 0

    /// The shelf's front wire, over the bottles' feet.
    var rail: CGRect {
        guard window.width > 0 else { return .zero }
        let inner = window.insetBy(dx: windowRim, dy: windowRim)
        return CGRect(x: inner.minX, y: shelfLine, width: inner.width, height: 3.2)
    }
    /// The cap's word: centred under it, or ending (or beginning) beside it.
    var captionFrame: CGRect {
        if captionSide < 0 { return CGRect(x: caption.x - 80, y: caption.y - 8, width: 80, height: 16) }
        if captionSide > 0 { return CGRect(x: caption.x, y: caption.y - 8, width: 80, height: 16) }
        return CGRect(x: caption.x - 40, y: caption.y - 8, width: 80, height: 16)
    }
    var captionAlignment: Alignment {
        if captionSide < 0 { return .trailing }
        if captionSide > 0 { return .leading }
        return .center
    }

    /// `count` price tags along a channel: each `width` across (nil: as wide
    /// as the channel shares out), 6 or more between two, 2 to 4 in from its
    /// ends; `height` high, 3 under its top.
    static func tagRow(_ channel: CGRect, count: Int, width: CGFloat?, height: CGFloat) -> [CGRect] {
        guard count > 0 else { return [] }
        let n = CGFloat(count)
        let each: CGFloat = width ?? (channel.width - 8 - (n - 1) * 6) / n
        let end: CGFloat = min(4, max(2, (channel.width - n * each - (n - 1) * 6) / 2))
        let gap: CGFloat = count > 1 ? (channel.width - 2 * end - n * each) / (n - 1) : 0
        return (0..<count).map { index in
            CGRect(x: channel.minX + end + CGFloat(index) * (each + gap), y: channel.minY + 3, width: each, height: height)
        }
    }
}

extension ShellPlan {
    /// Seven price tags in one row (each at least 44 across, 6 between two,
    /// a little room at the channel's ends); a narrower column has them in
    /// two rows, four over three.
    var sodaTwoRows: Bool { 366 * u < 7 * max(44, 46 * u) + 40 }
    /// From the price tags' channel down to the 主菜单 key's foot.
    var sodaKeysHeight: CGFloat { sodaTwoRows ? 369 : 313 }

    /// The soda cooler's parts, upright (mock/sd7.js's points from the
    /// column's corner and from the keys' top): the light box along the top,
    /// the glass door (the picture), the price tags on the rail under it,
    /// the lower window with the shelf of bottles; at the foot the control
    /// plate (the light's toggle, the enamel plate, the thermostat) over the
    /// kick plate with 主菜单 — what height is left goes between the shelf
    /// and the plate. Down the strip: the flip card under the camera, the
    /// picture under its magnet, the door's handle where the Camera
    /// Control's overlay comes in, the big cap under the thumb.
    var soda: SodaLayout {
        var l = SodaLayout()
        let c = back.column, strip = back.strip, k = keysTop
        let w = back.canvas.width, h = back.canvas.height
        let two = sodaTwoRows
        let row: CGFloat = two ? 56 : 0
        l.canvas = back.canvas
        l.u = u
        l.lightBox = CGRect(x: x(24), y: top - 3, width: 356 * u, height: 36)
        l.door = surround
        l.glass = box
        l.hinges = [CGRect(x: surround.minX - 7.5, y: surround.minY + 29.5, width: 8, height: 22),
                    CGRect(x: surround.minX - 7.5, y: surround.maxY - 35.5, width: 8, height: 22)]
        // The price tags: seven in a row, or four over three.
        let first = CGRect(x: x(18), y: k, width: 366 * u, height: 54)
        let second = first.offsetBy(dx: 0, dy: 56)
        if two {
            l.channels = [first, second]
            let upper = SodaLayout.tagRow(first, count: 4, width: nil, height: 48)
            let lower = SodaLayout.tagRow(second, count: 3, width: nil, height: 48)
            l.tags = upper + lower
            let albumUpper = SodaLayout.tagRow(first, count: 3, width: nil, height: 48)
            let albumLower = SodaLayout.tagRow(second, count: 1, width: nil, height: 48)
            l.albumTags = albumUpper + albumLower
        } else {
            l.channels = [first]
            l.tags = SodaLayout.tagRow(first, count: 7, width: max(44, 46 * u), height: 48)
            l.albumTags = SodaLayout.tagRow(first, count: 4, width: nil, height: 48)
        }
        // The base at the column's foot; a third of what is left over the window.
        let kick = max(k + 266 + row, c.maxY - 48)
        let slack = kick - (k + 266 + row)
        l.window = CGRect(x: x(29.5), y: k + 59.5 + row + (slack * 0.35).rounded(), width: 343 * u, height: 99)
        l.windowRim = 8.5
        let inner = l.window.insetBy(dx: 8.5, dy: 8.5)
        l.shelf = CGRect(x: inner.minX, y: inner.minY, width: inner.width, height: 80)
        l.shelfLine = inner.minY + 77
        l.bottle = CGSize(width: 44, height: 80)
        let pk = kick - 102
        let q = min(1, u)
        l.panel = CGRect(x: x(18), y: pk, width: 366 * u, height: 96)
        l.toggle = CGRect(x: x(26), y: pk + 3, width: max(48, 62 * u), height: 90)
        l.plate = CGRect(x: x(100), y: pk + 20, width: 150 * u, height: 52)
        l.knobRadius = 32 * q
        l.knob = CGRect(x: x(322) - 40 * q, y: pk + 9, width: 80 * q, height: 80)
        l.bands = [CGRect(x: 0, y: 0, width: w, height: top + 44), CGRect(x: 0, y: kick, width: w, height: max(0, h - kick))]
        l.trims = [top + 44, kick]
        l.home = CGRect(x: x(150), y: kick + 3, width: 102 * u, height: 44)
        l.louvres = [CGRect(x: x(30), y: kick + 11, width: 106 * u, height: 33), CGRect(x: x(266), y: kick + 11, width: 106 * u, height: 33)]
        l.feet = [CGPoint(x: x(70), y: h - 12), CGPoint(x: x(332), y: h - 12)]
        // Down the strip.
        let side = min(strip.midX + 4, w - 37)
        let floor = back.keepOut.map(\.maxY).max() ?? top
        let flipTop = max(floor + 2, top + 88)
        let zone = back.overlay
        let zoneTop = zone?.minY ?? (flipTop + 168)
        let fit = min(1, max(0, zoneTop - 6 - flipTop) / 162)
        let flipHeight = max(44, 74 * fit), magnetHeight = max(44, 80 * fit)
        l.flip = CGRect(x: side - 30, y: flipTop, width: 60, height: flipHeight)
        l.magnet = CGRect(x: side - 30, y: l.flip.maxY + max(6, 8 * fit), width: 60, height: magnetHeight)
        if let zone { l.handle = CGRect(x: zone.midX - 9, y: zone.minY + 12, width: 13, height: max(0, zone.height - 24)) }
        let capY = max((zone?.maxY ?? 0) + 50, c.maxY - 54)
        l.capRadius = 31
        l.shutter = CGRect(x: side - 33, y: capY - 33, width: 66, height: 66)
        l.caption = CGPoint(x: side, y: capY + 44)
        l.captionSide = 0
        return l
    }
}

extension ShellAcrossPlan {
    /// 拍照 held across: the big cap at the far end of the band's shorter
    /// clear run (of the longer one where that is too short).
    var sodaShutter: CGRect {
        let end = back.spare.width >= 100 ? back.spare : back.run
        return CGRect(x: end.maxX - 91, y: end.midY - 30, width: 64, height: 64)
    }

    /// The soda cooler's parts with the cover held across: the door at the
    /// left; in the band the light box in its longer clear run, the cooler's
    /// top vent where the Camera Control's overlay comes in, the big cap;
    /// in the keys' column (mock/sd7.js's points from its corner) the price
    /// tags in two rows, the shelf of bottles, and the control plate with
    /// the thermostat, the toggle, the picture under its magnet, the flip
    /// card, the enamel plate and 主菜单.
    var soda: SodaLayout {
        var l = SodaLayout()
        let band = back.band, run = back.run, keys = back.keys
        let w = back.canvas.width, h = back.canvas.height
        let atTop = band.minY < 1
        l.across = true
        l.canvas = back.canvas
        // The white enamel along the band (its trim on the inner edge), and
        // along the other edge where there is room.
        var bands: [CGRect] = [band]
        var trims: [CGFloat] = [atTop ? band.maxY - 2 : band.minY + 2]
        if atTop {
            let foot = max(back.screen.maxY, keys.maxY) + 8
            if h - foot >= 12 {
                bands.append(CGRect(x: 0, y: foot, width: w, height: h - foot))
                trims.append(foot)
            }
        } else {
            let head = min(back.screen.minY, keys.minY) - 8
            if head >= 12 {
                bands.append(CGRect(x: 0, y: 0, width: w, height: head))
                trims.append(head)
            }
        }
        l.bands = bands
        l.trims = trims
        // The band: the light box in what the cap leaves of the longer run,
        // the vent in the overlay's place, the cap and its word beside it.
        let shutter = sodaShutter
        let room = back.spare.width >= 100 ? run : CGRect(x: run.minX, y: run.minY, width: max(0, run.width - 112), height: run.height)
        if room.width >= 110 { l.lightBox = CGRect(x: room.minX + 4, y: room.midY - 21, width: min(220, room.width - 8), height: 40) }
        if let zone = back.overlay, zone.width > 60 { l.grille = CGRect(x: zone.minX + 14, y: band.minY + 15, width: zone.width - 28, height: 48) }
        l.shutter = shutter
        l.capRadius = 30
        if shutter.minX - 4 >= 50 {
            l.caption = CGPoint(x: shutter.minX - 4, y: shutter.midY)
            l.captionSide = -1
        } else {
            l.caption = CGPoint(x: shutter.maxX + 4, y: shutter.midY)
            l.captionSide = 1
        }
        // The door at the left, the hinges at its side, louvres under it.
        l.door = surround
        l.glass = box
        l.hinges = [CGRect(x: surround.minX - 6.5, y: surround.minY + 37.5, width: 8, height: 22),
                    CGRect(x: surround.minX - 6.5, y: surround.maxY - 66.5, width: 8, height: 22)]
        if atTop, bands.count > 1 {
            l.louvres = [CGRect(x: surround.minX + 25.5, y: bands[1].minY + 4, width: max(0, surround.width - 59), height: 8)]
        }
        // The keys' column.
        let first = key(-4, -3, 208, 52), second = key(-4, 51, 208, 52)
        l.channels = [first, second]
        let upper = SodaLayout.tagRow(first, count: 4, width: nil, height: 46)
        let lower = SodaLayout.tagRow(second, count: 3, width: nil, height: 46)
        l.tags = upper + lower
        let albumUpper = SodaLayout.tagRow(first, count: 3, width: nil, height: 46)
        let albumLower = SodaLayout.tagRow(second, count: 1, width: nil, height: 46)
        l.albumTags = albumUpper + albumLower
        l.window = key(-2, 107, 204, 85)
        l.windowRim = 8
        let inner = l.window.insetBy(dx: 8, dy: 8)
        l.shelf = CGRect(x: inner.minX, y: inner.minY, width: inner.width, height: 68)
        l.shelfLine = inner.minY + 66
        l.bottle = CGSize(width: 44, height: 68)
        l.bottleScale = 0.88
        l.bottleLift = 3.5
        l.bottlePad = 16
        l.printCell = 44
        l.panel = key(-4, 196, 208, 164)
        l.knob = key(6, 206, 80, 80)
        l.knobRadius = 30
        l.toggle = key(100, 200, 48, 96)
        l.magnet = key(154, 200, 46, 45)
        l.flip = key(154, 251, 46, 45)
        l.plate = key(0, 302, 136, 54)
        l.home = key(145, 305, 52, 48)
        l.homeStacked = true
        return l
    }
}

/// The cooler's body, drawn as the picture of it was (mock/sd7.js, part for
/// part): mint enamel with an even sheen and fine pores, the white enamel
/// with its bright trims, the hinge's side in shade, the light box's chrome
/// case and lit acrylic (ZERO on it: SodaLightBoxMark), the top vent held
/// across, the door's chrome frame and seal and its hinges, the clear
/// channels for the price tags, the lower window lit from inside with the
/// shelf's back wires, the brushed control plate with its screws, the
/// louvres, the feet, and the door's handle where the Camera Control's
/// overlay comes in (nothing to press there). Drawn once (it is the same
/// until the deck is another size or the picture another shape).
private struct SodaBackdrop: View, Equatable {
    var layout: SodaLayout
    var hinge: CGRect
    var body: some View {
        Canvas { context, size in
            Self.cabinet(context, size)
            for (band, trim) in zip(layout.bands, layout.trims) { Self.enamel(context, band, trim: trim) }
            Self.edges(context, size, hinge)
            if layout.lightBox.width > 0 { Self.lightBox(context, layout.lightBox) }
            if layout.grille.width > 0 { Self.grille(context, layout.grille) }
            Self.door(context, layout.door, rim: 9, radius: 18)
            for one in layout.hinges { Self.doorHinge(context, one) }
            for one in layout.channels { Self.channel(context, one) }
            Self.window(context, layout)
            Self.panel(context, layout.panel)
            for one in layout.louvres { Self.louvres(context, one, step: layout.across ? 6 : 7) }
            for at in layout.feet { Self.foot(context, at) }
            if layout.handle.width > 0 { Self.handle(context, layout.handle) }
        }
        .accessibilityHidden(true)
    }

    private static let chromeCase = Gradient(stops: [Gradient.Stop(color: Color(red: 0.984, green: 0.988, blue: 0.992), location: 0),
                                                     Gradient.Stop(color: Color(red: 0.788, green: 0.804, blue: 0.827), location: 0.3),
                                                     Gradient.Stop(color: Color(red: 0.957, green: 0.961, blue: 0.965), location: 0.55),
                                                     Gradient.Stop(color: Color(red: 0.561, green: 0.584, blue: 0.620), location: 1)])
    private static let trimLight = Gradient(stops: [Gradient.Stop(color: Color.white, location: 0),
                                                    Gradient.Stop(color: Color(red: 0.624, green: 0.651, blue: 0.682), location: 0.35),
                                                    Gradient.Stop(color: Color(red: 0.933, green: 0.941, blue: 0.949), location: 0.62),
                                                    Gradient.Stop(color: Color(red: 0.525, green: 0.549, blue: 0.580), location: 1)])
    private static let barLight = Gradient(stops: [Gradient.Stop(color: Color(red: 0.553, green: 0.576, blue: 0.612), location: 0),
                                                   Gradient.Stop(color: Color(red: 0.984, green: 0.988, blue: 0.992), location: 0.3),
                                                   Gradient.Stop(color: Color(red: 0.788, green: 0.804, blue: 0.827), location: 0.55),
                                                   Gradient.Stop(color: Color(red: 0.490, green: 0.514, blue: 0.549), location: 1)])

    /// Mint enamel lit from the upper left: an even sheen, fine pores.
    private static func cabinet(_ context: GraphicsContext, _ size: CGSize) {
        let whole = CGRect(origin: .zero, size: size), far = max(size.width, size.height), mint = SodaPaint.mint
        let enamel = Gradient(stops: [Gradient.Stop(color: mint.color(0.16), location: 0), Gradient.Stop(color: mint.color(0), location: 0.5),
                                      Gradient.Stop(color: mint.color(-0.1), location: 1)])
        context.fill(Path(whole), with: .linearGradient(enamel, startPoint: .zero, endPoint: CGPoint(x: size.width * 0.4, y: size.height)))
        var seed: UInt32 = 0x50DA_C001
        func next() -> CGFloat {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            return CGFloat((seed >> 8) & 0xFFFF) / 65535
        }
        for _ in 0..<Int(size.width * size.height / 70) {
            let at = CGPoint(x: next() * size.width, y: next() * size.height), a = Double(next()) * 0.025
            context.fill(Path(CGRect(x: at.x, y: at.y, width: 1, height: 1)), with: .color((next() < 0.5 ? Color.white : Color.black).opacity(a)))
        }
        let sheen = Gradient(stops: [Gradient.Stop(color: Color.white.opacity(0.16), location: 0), Gradient.Stop(color: Color.white.opacity(0.02), location: 0.6),
                                     Gradient.Stop(color: SodaPaint.shade.opacity(0.07), location: 1)])
        context.fill(Path(whole), with: .radialGradient(sheen, center: CGPoint(x: size.width * 0.28, y: size.height * 0.16), startRadius: 10, endRadius: far * 0.85))
    }

    /// A band of white enamel right across, a bright trim along its inner edge.
    private static func enamel(_ context: GraphicsContext, _ band: CGRect, trim: CGFloat) {
        guard band.width > 0, band.height > 0 else { return }
        let white = Gradient(colors: [Color(red: 0.992, green: 0.996, blue: 0.992), Color(red: 0.898, green: 0.922, blue: 0.910)])
        context.fill(Path(band), with: .linearGradient(white, startPoint: CGPoint(x: 0, y: band.minY), endPoint: CGPoint(x: 0, y: band.maxY)))
        context.fill(Path(CGRect(x: band.minX, y: trim - 2, width: band.width, height: 4)),
                     with: .linearGradient(trimLight, startPoint: CGPoint(x: 0, y: trim - 2), endPoint: CGPoint(x: 0, y: trim + 2)))
        context.fill(Path(CGRect(x: band.minX, y: trim + 2, width: band.width, height: 1)), with: .color(SodaPaint.shade.opacity(0.16)))
    }

    /// The hinge's side in shade, the rim all round.
    private static func edges(_ context: GraphicsContext, _ size: CGSize, _ hinge: CGRect) {
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let near = tall ? hinge.midX < size.width / 2 : hinge.midY < size.height / 2
            let edge: CGFloat = near ? 0 : (tall ? size.width : size.height)
            let inward: CGFloat = near ? 14 : -14
            let from = tall ? CGPoint(x: edge, y: 0) : CGPoint(x: 0, y: edge)
            let to = tall ? CGPoint(x: edge + inward, y: 0) : CGPoint(x: 0, y: edge + inward)
            let strip = tall ? CGRect(x: min(edge, edge + inward), y: 0, width: 14, height: size.height) : CGRect(x: 0, y: min(edge, edge + inward), width: size.width, height: 14)
            context.fill(Path(strip), with: .linearGradient(Gradient(colors: [SodaPaint.shade.opacity(0.42), SodaPaint.shade.opacity(0)]), startPoint: from, endPoint: to))
        }
        let whole = CGRect(origin: .zero, size: size)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 1.5, dy: 1.5), cornerRadius: 44.5), with: .color(Color.white.opacity(0.45)), lineWidth: 1.2)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 0.5, dy: 0.5), cornerRadius: 46), with: .color(SodaPaint.shade.opacity(0.55)), lineWidth: 1)
    }

    /// The light box: a chrome case, white acrylic lit evenly from inside.
    private static func lightBox(_ context: GraphicsContext, _ r: CGRect) {
        let frame = r.insetBy(dx: -3.5, dy: -3.5)
        var lifted = context
        lifted.addFilter(.shadow(color: SodaPaint.shade.opacity(0.32), radius: 2.5, x: 0, y: 2))
        lifted.fill(Path(roundedRect: frame, cornerRadius: 12), with: .linearGradient(chromeCase, startPoint: CGPoint(x: 0, y: frame.minY), endPoint: CGPoint(x: 0, y: frame.maxY)))
        context.stroke(Path(roundedRect: r.insetBy(dx: -2.7, dy: -2.7), cornerRadius: 11.3), with: .color(Color.white.opacity(0.85)), lineWidth: 0.8)
        let face = Path(roundedRect: r, cornerRadius: 9)
        let acrylic = Gradient(stops: [Gradient.Stop(color: Color(red: 0.933, green: 0.973, blue: 0.957), location: 0), Gradient.Stop(color: Color.white, location: 0.45),
                                       Gradient.Stop(color: Color(red: 0.902, green: 0.953, blue: 0.933), location: 1)])
        context.fill(face, with: .linearGradient(acrylic, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        var inner = context
        inner.clip(to: face)
        inner.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 1.6)), with: .color(SodaPaint.shade.opacity(0.14)))
        context.stroke(face, with: .color(SodaPaint.shade.opacity(0.35)), lineWidth: 1)
    }

    /// The cooler's top vent: a shallow recess in the enamel with louvres.
    private static func grille(_ context: GraphicsContext, _ r: CGRect) {
        let well = Path(roundedRect: r, cornerRadius: 10)
        let recess = Gradient(colors: [Color(red: 0.827, green: 0.863, blue: 0.847), Color(red: 0.933, green: 0.949, blue: 0.941)])
        context.fill(well, with: .linearGradient(recess, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        context.stroke(well, with: .color(SodaPaint.shade.opacity(0.3)), lineWidth: 1)
        context.stroke(Path(roundedRect: CGRect(x: r.minX + 0.5, y: r.minY + 1.2, width: r.width - 1, height: r.height - 1.5), cornerRadius: 10), with: .color(Color.white.opacity(0.7)), lineWidth: 0.8)
        louvres(context, CGRect(x: r.minX + 12, y: r.minY + 9, width: max(0, r.width - 24), height: max(0, r.height - 16)), step: 6.5)
    }

    /// Dark slats, each with a light lip under it.
    private static func louvres(_ context: GraphicsContext, _ r: CGRect, step: CGFloat) {
        var y = r.minY
        while y + 3.4 <= r.maxY {
            context.fill(Path(roundedRect: CGRect(x: r.minX, y: y, width: r.width, height: 3.4), cornerRadius: 1.7), with: .color(Color(red: 0.145, green: 0.188, blue: 0.180)))
            context.fill(Path(CGRect(x: r.minX + 2, y: y + 3.7, width: max(0, r.width - 4), height: 0.9)), with: .color(Color.white.opacity(0.85)))
            y += step
        }
    }

    /// A chrome frame (lit across, its shadow on the enamel) and the dark
    /// rubber seal `rim` inside it.
    private static func door(_ context: GraphicsContext, _ r: CGRect, rim: CGFloat, radius: CGFloat) {
        guard r.width > 0, r.height > 0 else { return }
        var lifted = context
        lifted.addFilter(.shadow(color: SodaPaint.shade.opacity(0.4), radius: 3, x: 0, y: 2.5))
        lifted.fill(Path(roundedRect: r, cornerRadius: radius), with: .linearGradient(ClamPaint.chrome, startPoint: r.origin, endPoint: CGPoint(x: r.maxX, y: r.maxY)))
        context.stroke(Path(roundedRect: r.insetBy(dx: 0.7, dy: 0.7), cornerRadius: radius - 0.7), with: .color(Color.white.opacity(0.9)), lineWidth: 1)
        context.stroke(Path(roundedRect: r.insetBy(dx: rim * 0.45, dy: rim * 0.45), cornerRadius: radius - rim * 0.45), with: .color(Color.black.opacity(0.13)), lineWidth: 0.8)
        let seal = r.insetBy(dx: rim, dy: rim)
        context.fill(Path(roundedRect: seal, cornerRadius: max(3, radius - rim)), with: .color(SodaPaint.seal))
        context.stroke(Path(roundedRect: seal.insetBy(dx: 0.8, dy: 0.8), cornerRadius: max(3, radius - rim - 0.8)), with: .color(Color.white.opacity(0.09)), lineWidth: 1)
    }

    /// One of the door's hinges: a bright barrel, its joint across the middle.
    private static func doorHinge(_ context: GraphicsContext, _ r: CGRect) {
        let barrel = Path(roundedRect: r, cornerRadius: 3)
        let lit = Gradient(stops: [Gradient.Stop(color: Color(red: 0.561, green: 0.584, blue: 0.620), location: 0), Gradient.Stop(color: Color(red: 0.965, green: 0.969, blue: 0.973), location: 0.35),
                                   Gradient.Stop(color: Color(red: 0.761, green: 0.780, blue: 0.804), location: 0.7), Gradient.Stop(color: Color(red: 0.490, green: 0.514, blue: 0.549), location: 1)])
        context.fill(barrel, with: .linearGradient(lit, startPoint: CGPoint(x: r.minX, y: 0), endPoint: CGPoint(x: r.maxX, y: 0)))
        context.stroke(barrel, with: .color(Color.black.opacity(0.35)), lineWidth: 0.7)
        context.fill(Path(CGRect(x: r.minX, y: r.midY - 0.5, width: r.width, height: 1)), with: .color(Color.black.opacity(0.3)))
    }

    /// The clear channel along the rail (the tags go in it; its lips over
    /// their edges are SodaLips).
    private static func channel(_ context: GraphicsContext, _ r: CGRect) {
        context.fill(Path(roundedRect: CGRect(x: r.minX - 1, y: r.minY - 0.5, width: r.width + 2, height: r.height + 2.5), cornerRadius: 5), with: .color(SodaPaint.shade.opacity(0.2)))
        let clear = Path(roundedRect: r, cornerRadius: 4)
        let tint = Gradient(colors: [Color(red: 0.925, green: 0.965, blue: 0.949).opacity(0.9), Color(red: 0.831, green: 0.898, blue: 0.875).opacity(0.9)])
        context.fill(clear, with: .linearGradient(tint, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        context.stroke(clear, with: .color(Color(red: 0.0, green: 0.196, blue: 0.157).opacity(0.35)), lineWidth: 0.9)
    }

    /// The lower window: frame and seal as the door's; inside, lit by a
    /// tube along the top, ribbed, the shelf's two back wires.
    private static func window(_ context: GraphicsContext, _ layout: SodaLayout) {
        let r = layout.window, t = layout.windowRim
        guard r.width > 0, r.height > 0 else { return }
        door(context, r, rim: t - 2.5, radius: 14)
        let inner = r.insetBy(dx: t, dy: t)
        var lit = context
        lit.clip(to: Path(roundedRect: inner, cornerRadius: 5))
        let light = Gradient(stops: [Gradient.Stop(color: Color(red: 0.933, green: 0.973, blue: 0.976), location: 0), Gradient.Stop(color: Color(red: 0.839, green: 0.914, blue: 0.925), location: 0.55),
                                     Gradient.Stop(color: Color(red: 0.737, green: 0.835, blue: 0.855), location: 1)])
        lit.fill(Path(inner), with: .linearGradient(light, startPoint: CGPoint(x: 0, y: inner.minY), endPoint: CGPoint(x: 0, y: inner.maxY)))
        var x = inner.minX + 6
        while x < inner.maxX {
            lit.fill(Path(CGRect(x: x, y: inner.minY, width: 1, height: inner.height)), with: .color(Color(red: 0.0, green: 0.235, blue: 0.275).opacity(0.05)))
            lit.fill(Path(CGRect(x: x + 1, y: inner.minY, width: 0.8, height: inner.height)), with: .color(Color.white.opacity(0.35)))
            x += 9
        }
        lit.fill(Path(roundedRect: CGRect(x: inner.minX + 8, y: inner.minY + 1.4, width: max(0, inner.width - 16), height: 3.2), cornerRadius: 1.6), with: .color(Color.white))
        lit.fill(Path(CGRect(x: inner.minX, y: inner.minY, width: inner.width, height: 16)),
                 with: .linearGradient(Gradient(colors: [Color.white.opacity(0.5), Color.white.opacity(0)]), startPoint: CGPoint(x: 0, y: inner.minY), endPoint: CGPoint(x: 0, y: inner.minY + 16)))
        let wire = Color(red: 0.275, green: 0.353, blue: 0.376).opacity(0.35)
        lit.fill(Path(CGRect(x: inner.minX, y: layout.shelfLine - 7, width: inner.width, height: 1)), with: .color(wire))
        lit.fill(Path(CGRect(x: inner.minX, y: layout.shelfLine - 3.5, width: inner.width, height: 1)), with: .color(wire))
    }

    /// Brushed aluminium let into the cabinet, a screw at each corner.
    private static func panel(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 0, r.height > 0 else { return }
        context.fill(Path(roundedRect: CGRect(x: r.minX - 1.5, y: r.minY - 1.5, width: r.width + 3, height: r.height + 3.5), cornerRadius: 9.5), with: .color(SodaPaint.shade.opacity(0.3)))
        let plate = Path(roundedRect: r, cornerRadius: 8)
        let metal = Gradient(stops: [Gradient.Stop(color: Color(red: 0.835, green: 0.855, blue: 0.867), location: 0), Gradient.Stop(color: Color(red: 0.914, green: 0.925, blue: 0.933), location: 0.5),
                                     Gradient.Stop(color: Color(red: 0.804, green: 0.824, blue: 0.839), location: 1)])
        context.fill(plate, with: .linearGradient(metal, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        var inner = context
        inner.clip(to: plate)
        DigiMetal.brush(inner, r, 0.06, seed: 0x50DA_B12E)
        inner.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 6)),
                   with: .linearGradient(Gradient(colors: [Color.black.opacity(0.16), Color.black.opacity(0)]), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.minY + 6)))
        context.stroke(Path(roundedRect: r.insetBy(dx: 0.5, dy: 0.5), cornerRadius: 8), with: .color(SodaPaint.shade.opacity(0.35)), lineWidth: 1)
        for at in [CGPoint(x: r.minX + 7, y: r.minY + 7), CGPoint(x: r.maxX - 7, y: r.minY + 7), CGPoint(x: r.minX + 7, y: r.maxY - 7), CGPoint(x: r.maxX - 7, y: r.maxY - 7)] {
            screw(context, at, 2.3)
        }
    }

    /// A screw's head, lit from the upper left, its slot.
    static func screw(_ context: GraphicsContext, _ at: CGPoint, _ r: CGFloat) {
        let head = CGRect(x: at.x - r, y: at.y - r, width: 2 * r, height: 2 * r)
        context.fill(Path(ellipseIn: head), with: .radialGradient(Gradient(colors: [Color(white: 0.91), Color(red: 0.333, green: 0.345, blue: 0.365)]),
                                                                  center: CGPoint(x: at.x - 1, y: at.y - 1), startRadius: 0.5, endRadius: r * 1.3))
        context.stroke(Path(ellipseIn: head), with: .color(Color.black.opacity(0.6)), lineWidth: 0.6)
        var slot = Path()
        slot.move(to: CGPoint(x: at.x - r * 0.6, y: at.y - r * 0.3))
        slot.addLine(to: CGPoint(x: at.x + r * 0.6, y: at.y + r * 0.3))
        context.stroke(slot, with: .color(Color.black.opacity(0.65)), lineWidth: 0.9)
    }

    private static func foot(_ context: GraphicsContext, _ at: CGPoint) {
        let r = CGRect(x: at.x - 14, y: at.y, width: 28, height: 7)
        let rubber = Gradient(colors: [Color(red: 0.290, green: 0.318, blue: 0.337), Color(red: 0.114, green: 0.133, blue: 0.145)])
        context.fill(Path(roundedRect: r, cornerRadius: 2.5), with: .linearGradient(rubber, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
    }

    /// The door's handle: a bright bar on two posts over a shallow recess.
    private static func handle(_ context: GraphicsContext, _ r: CGRect) {
        let t = r.width
        let recess = Path(roundedRect: r.insetBy(dx: -5, dy: -6), cornerRadius: t / 2 + 5)
        context.fill(recess, with: .color(Color(red: 0.0, green: 0.196, blue: 0.157).opacity(0.13)))
        context.stroke(recess, with: .color(SodaPaint.shade.opacity(0.2)), lineWidth: 1)
        var lifted = context
        lifted.addFilter(.shadow(color: SodaPaint.shade.opacity(0.35), radius: 1.5, x: 0, y: 1.5))
        for post in [CGRect(x: r.minX - 3, y: r.minY + 7, width: t + 6, height: 13), CGRect(x: r.minX - 3, y: r.maxY - 20, width: t + 6, height: 13)] {
            lifted.fill(Path(roundedRect: post, cornerRadius: 3.5), with: .linearGradient(ClamPaint.chrome, startPoint: CGPoint(x: post.minX, y: 0), endPoint: CGPoint(x: post.maxX, y: 0)))
        }
        var bar = context
        bar.addFilter(.shadow(color: SodaPaint.shade.opacity(0.4), radius: 2.5, x: 0, y: 2.5))
        bar.fill(Path(roundedRect: r, cornerRadius: t / 2), with: .linearGradient(barLight, startPoint: CGPoint(x: r.minX, y: 0), endPoint: CGPoint(x: r.maxX, y: 0)))
        context.stroke(Path(roundedRect: r.insetBy(dx: 0.6, dy: 0.6), cornerRadius: t / 2), with: .color(Color.white.opacity(0.7)), lineWidth: 0.8)
    }
}

/// What lies over the picture's edge: the door's chrome frame and the
/// rubber seal round the picture (over the picture's own bezel), and a
/// little frost in the corners — on the frame and the seal only, none over
/// the picture. Nothing is pressed through it.
private struct SodaDoorRim: View, Equatable {
    var door: CGRect
    /// The picture, seen through the glass.
    var hole: CGRect
    var body: some View {
        Canvas { context, size in
            guard door.width > 0, door.height > 0 else { return }
            let rim: CGFloat = 9, radius: CGFloat = 18
            let outer = Path(roundedRect: door, cornerRadius: radius)
            let seal = door.insetBy(dx: rim, dy: rim)
            let inner = Path(roundedRect: seal, cornerRadius: radius - rim)
            var frame = outer
            frame.addPath(inner)
            context.fill(frame, with: .linearGradient(ClamPaint.chrome, startPoint: door.origin, endPoint: CGPoint(x: door.maxX, y: door.maxY)), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: door.insetBy(dx: 0.7, dy: 0.7), cornerRadius: radius - 0.7), with: .color(Color.white.opacity(0.9)), lineWidth: 1)
            context.stroke(Path(roundedRect: door.insetBy(dx: rim * 0.45, dy: rim * 0.45), cornerRadius: radius - rim * 0.45), with: .color(Color.black.opacity(0.13)), lineWidth: 0.8)
            let open = hole.width > 0 && hole.height > 0
            let picture = Path(roundedRect: hole, cornerRadius: 6.5, style: .continuous)
            var rubber = inner
            if open { rubber.addPath(picture) }
            context.fill(rubber, with: .color(SodaPaint.seal), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: seal.insetBy(dx: 0.8, dy: 0.8), cornerRadius: radius - rim - 0.8), with: .color(Color.white.opacity(0.09)), lineWidth: 1)
            // The frost, kept off the picture.
            var cold = outer
            if open { cold.addPath(picture) }
            var frosty = context
            frosty.clip(to: cold, style: FillStyle(eoFill: true))
            Self.frost(frosty, seal)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    /// A haze in each corner of the glass and a few fern-like strokes, more
    /// low down: along the seal and out over the frame's corner.
    private static func frost(_ context: GraphicsContext, _ glass: CGRect) {
        var seed: UInt32 = 0xF057_0007
        func next() -> CGFloat {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            return CGFloat((seed >> 8) & 0xFFFF) / 65535
        }
        let haze = Gradient(stops: [Gradient.Stop(color: Color(red: 0.933, green: 0.973, blue: 0.988).opacity(0.62), location: 0),
                                    Gradient.Stop(color: Color(red: 0.925, green: 0.969, blue: 0.988).opacity(0.24), location: 0.45),
                                    Gradient.Stop(color: Color(red: 0.925, green: 0.969, blue: 0.988).opacity(0), location: 1)])
        let corners: [(CGPoint, CGFloat, CGFloat, CGFloat)] = [(CGPoint(x: glass.minX, y: glass.minY), 1, 1, 22), (CGPoint(x: glass.maxX, y: glass.minY), -1, 1, 22),
                                                                (CGPoint(x: glass.minX, y: glass.maxY), 1, -1, 28), (CGPoint(x: glass.maxX, y: glass.maxY), -1, -1, 28)]
        for corner in corners {
            let c = corner.0, sx = corner.1, sy = corner.2, reach = corner.3
            context.fill(Path(CGRect(x: c.x - reach, y: c.y - reach, width: 2 * reach, height: 2 * reach)), with: .radialGradient(haze, center: c, startRadius: 0, endRadius: reach))
            var ferns = Path()
            for j in 0..<5 {
                let a = Double((CGFloat(j) + 0.3 + next() * 0.4) / 5) * Double.pi / 2
                let length = reach * (0.6 + 0.35 * next())
                for outward in [false, true] {
                    let sign: CGFloat = outward ? -1 : 1
                    let run: CGFloat = outward ? length * 0.5 : length
                    let ux = sx * sign * CGFloat(cos(a)), uy = sy * sign * CGFloat(sin(a))
                    ferns.move(to: c)
                    ferns.addLine(to: CGPoint(x: c.x + ux * run, y: c.y + uy * run))
                    var q: CGFloat = 0.4
                    while q < 0.95 {
                        let b = CGPoint(x: c.x + ux * run * q, y: c.y + uy * run * q), twig = run * 0.2 * (1.1 - q)
                        for d in [0.75, -0.75] {
                            ferns.move(to: b)
                            ferns.addLine(to: CGPoint(x: b.x + sx * sign * CGFloat(cos(a + d)) * twig, y: b.y + sy * sign * CGFloat(sin(a + d)) * twig))
                        }
                        q += 0.2
                    }
                }
            }
            context.stroke(ferns, with: .color(Color.white.opacity(0.5)), style: StrokeStyle(lineWidth: 0.7, lineCap: .round))
        }
    }
}

/// ZERO and a snowflake on the light box (the only name on the body).
private struct SodaLightBoxMark: View, Equatable {
    var height: CGFloat
    var body: some View {
        let size = min(23, height * 0.62)
        HStack(spacing: size * 0.55) {
            SodaSnowflake()
                .stroke(Color(red: 0.227, green: 0.655, blue: 0.847), style: StrokeStyle(lineWidth: max(1.5, size * 0.066), lineCap: .round))
                .frame(width: size * 0.95, height: size * 0.95)
            Text(verbatim: "ZERO").font(.system(size: size, weight: .black)).tracking(size * 0.38)
                .foregroundStyle(Color(red: 0.059, green: 0.396, blue: 0.376))
                .lineLimit(1).fixedSize()
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A snowflake: six arms, two twigs on each, a dot in the middle.
private struct SodaSnowflake: Shape {
    func path(in rect: CGRect) -> Path {
        let c = CGPoint(x: rect.midX, y: rect.midY), s = min(rect.width, rect.height) / 2
        var path = Path()
        for i in 0..<6 {
            let a = Double(i) * Double.pi / 3
            let ca = CGFloat(cos(a)), sa = CGFloat(sin(a))
            // (`along` the arm from the middle, `across` it; the arm turned by `a` from straight up)
            let point = { (along: CGFloat, across: CGFloat) -> CGPoint in
                CGPoint(x: c.x + across * ca + along * sa, y: c.y + across * sa - along * ca)
            }
            path.move(to: point(s * 0.16, 0))
            path.addLine(to: point(s, 0))
            path.move(to: point(s * 0.5, 0))
            path.addLine(to: point(s * 0.76, -s * 0.27))
            path.move(to: point(s * 0.5, 0))
            path.addLine(to: point(s * 0.76, s * 0.27))
        }
        path.addEllipse(in: CGRect(x: c.x - s * 0.08, y: c.y - s * 0.08, width: s * 0.16, height: s * 0.16))
        return path
    }
}

/// The clear channels' lips over the price tags' edges, and the shelf's
/// front wire over the bottles' feet.
private struct SodaLips: View, Equatable {
    var channels: [CGRect]
    var rail: CGRect
    var body: some View {
        Canvas { context, size in
            let line = Color(red: 0.0, green: 0.196, blue: 0.157).opacity(0.3)
            for r in channels {
                for (index, y) in [r.minY, r.maxY - 6].enumerated() {
                    context.fill(Path(roundedRect: CGRect(x: r.minX, y: y, width: r.width, height: 6), cornerRadius: 3), with: .color(Color(red: 0.957, green: 0.984, blue: 0.976).opacity(0.6)))
                    context.fill(Path(CGRect(x: r.minX + 3, y: index == 1 ? y : y + 5.2, width: max(0, r.width - 6), height: 0.8)), with: .color(line))
                    context.fill(Path(CGRect(x: r.minX + 3, y: index == 1 ? y + 5 : y + 0.5, width: max(0, r.width - 6), height: 0.8)), with: .color(Color.white.opacity(0.75)))
                }
            }
            if rail.width > 0 {
                let wire = Gradient(stops: [Gradient.Stop(color: Color.white, location: 0), Gradient.Stop(color: Color(red: 0.725, green: 0.749, blue: 0.776), location: 0.45),
                                            Gradient.Stop(color: Color(red: 0.914, green: 0.922, blue: 0.933), location: 1)])
                context.fill(Path(CGRect(x: rail.minX, y: rail.minY + 3.2, width: rail.width, height: 1.2)), with: .color(Color(red: 0.0, green: 0.118, blue: 0.157).opacity(0.2)))
                context.fill(Path(CGRect(x: rail.minX, y: rail.minY, width: rail.width, height: 3.2)),
                             with: .linearGradient(wire, startPoint: CGPoint(x: 0, y: rail.minY), endPoint: CGPoint(x: 0, y: rail.minY + 3.2)))
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A key of the cooler that goes in under the finger — a price tag into
/// its channel, the enamel plate, the toggle's plate, the flip card — its
/// shadow shortening as it does; it sounds and is felt as it goes in, not
/// when it is let go (no sound: quiet, as while a video is taken).
private struct SodaPressStyle: ButtonStyle {
    var travel: CGFloat = 1.5
    /// How far its shadow falls while it is out.
    var rest: CGFloat = 1
    var sound: ConsoleSound? = .click
    var scale: Float = 0.55
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View { SodaPressBody(configuration: configuration, style: self) }
}
private struct SodaPressBody: View {
    let configuration: ButtonStyle.Configuration
    let style: SodaPressStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .shadow(color: SodaPaint.shade.opacity(0.3), radius: down ? 0.6 : 1.8, y: down ? 0.4 : style.rest)
            .offset(y: down ? style.travel : 0)
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                if let sound = style.sound { ConsoleSounds.shared.play(sound, scale: style.scale) }
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// A dotted line across (where a price would be written under it).
private struct SodaDots: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX, y: rect.midY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.midY))
        return path
    }
}

/// A paper price tag: its coloured head; under it the key's glyph (drawn as
/// what it sets stands) and, where the price would be written under a
/// dotted line, figures or a row of cells — or, with no price, the glyph in
/// the middle of the paper (and words beside it, where the key keeps them).
private struct SodaTagFace: View {
    var glyph: ShellGlyph
    var price: String
    var cells: ShellGlyph?
    var words: String
    var tone: SodaTagTone
    var height: CGFloat
    var head: Color
    var glyphInk: Color
    var body: some View {
        let paper = RoundedRectangle(cornerRadius: 2.5, style: .continuous)
        let priced = !price.isEmpty || cells != nil
        // (The paper under the head: from its foot, 10.3 points down, to the tag's own.)
        let middle = (10.3 + height) / 2
        ZStack(alignment: .top) {
            paper.fill(SodaPaint.paper)
            VStack(spacing: 0) {
                head.frame(height: 9.5)
                Color.white.opacity(0.35).frame(height: 0.8)
                Spacer(minLength: 0)
            }
            .clipShape(paper)
            paper.strokeBorder(SodaPaint.shade.opacity(0.18), lineWidth: 1)
            if priced {
                ShellGlyphView(glyph: glyph, size: 17, ink: glyphInk)
                    .frame(height: 20)
                    .offset(y: height * 0.43 - 10)
                SodaDots()
                    .stroke(SodaPaint.ink.opacity(0.3), style: StrokeStyle(lineWidth: 0.7, dash: [1.6, 1.6]))
                    .frame(height: 1)
                    .padding(.horizontal, 5)
                    .offset(y: height * 0.65 - 0.5)
                priceRow
                    .frame(height: 14)
                    .offset(y: height * 0.81 - 7)
            } else {
                nameRow
                    .frame(height: 24)
                    .offset(y: middle - 12)
            }
        }
        .frame(height: height)
    }
    /// The price: a row of cells, or figures (a setting that is off grey, a
    /// value in the softer ink, one that is on warm).
    @ViewBuilder private var priceRow: some View {
        if let cells {
            ShellGlyphView(glyph: cells, size: 18, ink: SodaPaint.ink)
        } else {
            let ink: Color = tone == .on ? SodaPaint.warm : (tone == .value ? SodaPaint.soft : SodaPaint.grey)
            Text(verbatim: price).font(.system(size: 11, weight: .heavy, design: .rounded)).monospacedDigit().foregroundStyle(ink)
                .lineLimit(1).minimumScaleFactor(0.7)
                .padding(.horizontal, 1.5)
        }
    }
    private var nameRow: some View {
        HStack(spacing: 4) {
            ShellGlyphView(glyph: glyph, size: words.isEmpty ? 20 : 15, ink: glyphInk)
            if !words.isEmpty {
                Text(words).font(.system(size: 12.5, weight: .black, design: .rounded)).foregroundStyle(SodaPaint.ink)
                    .lineLimit(1).minimumScaleFactor(0.7)
            }
        }
        .padding(.horizontal, 3)
    }
}

/// A price tag as a key. Pressed, it goes into the channel with the
/// channel's light tick; when how it stands (`state`: not written on it, the
/// key's glyph and price show it) changes, the old tag is drawn up out of
/// the channel and the new one drops in (at once with Reduce Motion), with a
/// paper's rustle (`rustle`: this tag's; none while quiet).
private struct SodaTag: View {
    var state: String
    var glyph: ShellGlyph
    var price = ""
    var cells: ShellGlyph? = nil
    var words = ""
    var tone: SodaTagTone = .off
    var height: CGFloat = 48
    var head: Color = SodaPaint.teal.color()
    var glyphInk: Color = SodaPaint.ink
    var quiet = false
    var rustle = true
    var action: () -> Void
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let swap: AnyTransition = reduceMotion ? .identity : .move(edge: .top)
        Button(action: action) {
            ZStack {
                SodaTagFace(glyph: glyph, price: price, cells: cells, words: words, tone: tone, height: height, head: head, glyphInk: glyphInk)
                    .id(state)
                    .transition(swap)
            }
            .clipped()
            .animation(reduceMotion ? nil : .easeOut(duration: 0.2), value: state)
        }
        .buttonStyle(SodaPressStyle(travel: 1.5, rest: 1, sound: quiet ? nil : .click, scale: 0.55))
        .onChange(of: state) { _, _ in
            if rustle, !quiet { ConsoleSounds.shared.play(.cardFlip, scale: 0.6) }
        }
    }
}

/// A bottle's glass, drawn: a plain cylinder, a round shoulder, a straight
/// neck with a lip; the drink in it and the air above, lit from the left;
/// bubbles in a clear one; the label round it; a glint; the crown cap.
/// Drawn once for a bottle (lifting the one in use moves it whole).
private struct SodaBottleGlass: View, Equatable {
    var look: SodaBottleLook
    var scale: CGFloat
    /// Where its foot is, from the top of its place.
    var base: CGFloat
    var body: some View {
        Canvas { context, size in
            let cx = size.width / 2, k = scale, b = base
            let bw = 17 * k, nw = 6 * k, bt = b - 37 * k, nb = bt - 11 * k, nt = nb - 12.5 * k
            let shape = Self.outline(cx, b, k)
            let x0 = cx - bw - 2, x1 = cx + bw + 2
            let lit = Gradient(stops: [Gradient.Stop(color: Color.black.opacity(0.3), location: 0), Gradient.Stop(color: Color.white.opacity(0.12), location: 0.3),
                                       Gradient.Stop(color: Color.white.opacity(0), location: 0.6), Gradient.Stop(color: Color.black.opacity(0.36), location: 1)])
            var inner = context
            inner.clip(to: shape)
            let whole = Path(CGRect(x: x0, y: nt - 2, width: x1 - x0, height: b - nt + 3))
            inner.fill(whole, with: .color(look.drink ?? look.glass))
            if look.drink != nil {
                let level = nb - 3.5 * k
                inner.fill(Path(CGRect(x: x0, y: nt - 2, width: x1 - x0, height: level - nt + 2)), with: .color(look.glass))
                inner.fill(Path(CGRect(x: x0, y: level - 0.5, width: x1 - x0, height: 1.1)), with: .color(Color.white.opacity(0.4)))
            }
            inner.fill(whole, with: .linearGradient(lit, startPoint: CGPoint(x: cx - bw, y: 0), endPoint: CGPoint(x: cx + bw, y: 0)))
            let l0 = b - 32 * k, l1 = b - 8.5 * k
            if look.fizz {
                var seed: UInt32 = 0xB0BB_1E50
                func next() -> CGFloat {
                    seed = seed &* 1_664_525 &+ 1_013_904_223
                    return CGFloat((seed >> 8) & 0xFFFF) / 65535
                }
                var bubbles = Path()
                for _ in 0..<16 {
                    let y = nb + 2 + next() * (b - nb - 6), x = cx + (next() - 0.5) * 1.6 * bw, r = 0.7 + next() * 0.9
                    if y > l0 - 1, y < l1 + 1 { continue }
                    bubbles.addEllipse(in: CGRect(x: x - r, y: y - r, width: 2 * r, height: 2 * r))
                }
                inner.stroke(bubbles, with: .color(Color.white.opacity(0.85)), lineWidth: 0.6)
            }
            let band = Path(CGRect(x: x0, y: l0, width: x1 - x0, height: l1 - l0))
            inner.fill(band, with: .color(look.label))
            inner.fill(band, with: .linearGradient(lit, startPoint: CGPoint(x: cx - bw, y: 0), endPoint: CGPoint(x: cx + bw, y: 0)))
            inner.fill(Path(CGRect(x: x0, y: l0 + 1.3, width: x1 - x0, height: 0.8)), with: .color(look.ink.opacity(0.3)))
            inner.fill(Path(CGRect(x: x0, y: l1 - 2.1, width: x1 - x0, height: 0.8)), with: .color(look.ink.opacity(0.3)))
            inner.fill(Path(CGRect(x: cx - bw * 0.62, y: nb + 4, width: 1.1 * k, height: max(0, l0 - nb - 6))), with: .color(Color.white.opacity(0.24)))
            inner.fill(Path(CGRect(x: cx - bw * 0.62, y: l1 + 2, width: 1.1 * k, height: max(0, b - l1 - 5.5))), with: .color(Color.white.opacity(0.24)))
            context.stroke(shape, with: .color(Color.black.opacity(0.32)), lineWidth: 0.8)
            Self.crown(context, cx, top: nt - 4.5 * k, width: (nw + 2.2 * k) * 2, height: 7 * k, colour: look.cap)
        }
    }

    /// The bottle's outline: `cx` its middle, `base` its foot, `k` how large.
    static func outline(_ cx: CGFloat, _ base: CGFloat, _ k: CGFloat) -> Path {
        let bw = 17 * k, nw = 6 * k, r = 4.5 * k, bt = base - 37 * k, nb = bt - 11 * k, nt = nb - 12.5 * k
        var path = Path()
        path.move(to: CGPoint(x: cx - bw + r, y: base))
        path.addLine(to: CGPoint(x: cx + bw - r, y: base))
        path.addQuadCurve(to: CGPoint(x: cx + bw, y: base - r), control: CGPoint(x: cx + bw, y: base))
        path.addLine(to: CGPoint(x: cx + bw, y: bt))
        path.addCurve(to: CGPoint(x: cx + nw, y: nb), control1: CGPoint(x: cx + bw, y: bt - 6.5 * k), control2: CGPoint(x: cx + nw, y: nb + 4.5 * k))
        path.addLine(to: CGPoint(x: cx + nw, y: nt + 3.4 * k))
        path.addLine(to: CGPoint(x: cx + nw + 1.4 * k, y: nt + 2.6 * k))
        path.addLine(to: CGPoint(x: cx + nw + 1.4 * k, y: nt + 0.8 * k))
        path.addLine(to: CGPoint(x: cx + nw, y: nt))
        path.addLine(to: CGPoint(x: cx - nw, y: nt))
        path.addLine(to: CGPoint(x: cx - nw - 1.4 * k, y: nt + 0.8 * k))
        path.addLine(to: CGPoint(x: cx - nw - 1.4 * k, y: nt + 2.6 * k))
        path.addLine(to: CGPoint(x: cx - nw, y: nt + 3.4 * k))
        path.addLine(to: CGPoint(x: cx - nw, y: nb))
        path.addCurve(to: CGPoint(x: cx - bw, y: bt), control1: CGPoint(x: cx - nw, y: nb + 4.5 * k), control2: CGPoint(x: cx - bw, y: bt - 6.5 * k))
        path.addLine(to: CGPoint(x: cx - bw, y: base - r))
        path.addQuadCurve(to: CGPoint(x: cx - bw + r, y: base), control: CGPoint(x: cx - bw, y: base))
        path.closeSubpath()
        return path
    }

    /// A crown cap from the side: a flat top, a crimped skirt.
    static func crown(_ context: GraphicsContext, _ cx: CGFloat, top: CGFloat, width w: CGFloat, height h: CGFloat, colour: Color) {
        let teeth = 8, x0 = cx - w / 2, tooth = w / CGFloat(teeth)
        var path = Path()
        path.move(to: CGPoint(x: x0, y: top + h - 1))
        path.addLine(to: CGPoint(x: x0, y: top + 1.5))
        path.addQuadCurve(to: CGPoint(x: x0 + 1.5, y: top), control: CGPoint(x: x0, y: top))
        path.addLine(to: CGPoint(x: x0 + w - 1.5, y: top))
        path.addQuadCurve(to: CGPoint(x: x0 + w, y: top + 1.5), control: CGPoint(x: x0 + w, y: top))
        path.addLine(to: CGPoint(x: x0 + w, y: top + h - 1))
        for i in 1...teeth {
            let xx = x0 + w - CGFloat(i) * tooth
            path.addLine(to: CGPoint(x: xx + tooth / 2, y: top + h + 0.6))
            path.addLine(to: CGPoint(x: xx, y: top + h - 1))
        }
        path.closeSubpath()
        let lit = Gradient(stops: [Gradient.Stop(color: Color.black.opacity(0.32), location: 0), Gradient.Stop(color: Color.white.opacity(0.35), location: 0.32),
                                   Gradient.Stop(color: Color.white.opacity(0), location: 0.6), Gradient.Stop(color: Color.black.opacity(0.4), location: 1)])
        context.fill(path, with: .color(colour))
        context.fill(path, with: .linearGradient(lit, startPoint: CGPoint(x: x0, y: 0), endPoint: CGPoint(x: x0 + w, y: 0)))
        context.stroke(path, with: .color(Color.black.opacity(0.35)), lineWidth: 0.6)
        for i in 1..<teeth {
            context.fill(Path(CGRect(x: x0 + CGFloat(i) * tooth - 0.3, y: top + 2, width: 0.6, height: max(0, h - 2.5))), with: .color(Color.black.opacity(0.18)))
        }
    }
}

/// A bottle on the shelf: its glass, the lens's glyph on its label (a
/// pinned 机型's: a small drawing of its kind of camera) — and the name
/// under it on the one in use alone — its shadow on the wire. The one in
/// use stands lifted off the shelf, a little larger and brighter (it rises
/// at once with Reduce Motion).
private struct SodaBottle: View {
    var look: SodaBottleLook
    var title: String
    var on: Bool
    var size: CGSize
    var scale: CGFloat
    var lift: CGFloat
    var base: CGFloat
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let k = scale, cx = size.width / 2
        let l0 = base - 32 * k, l1 = base - 8.5 * k
        let foot = UnitPoint(x: 0.5, y: size.height > 0 ? base / size.height : 1)
        ZStack(alignment: .topLeading) {
            Ellipse().fill(Color(red: 0.0, green: 0.118, blue: 0.157).opacity(on ? 0.16 : 0.26))
                .frame(width: 31 * k, height: 4.6 * k)
                .position(x: cx, y: base + 0.5)
            ZStack(alignment: .topLeading) {
                SodaBottleGlass(look: look, scale: k, base: base).equatable()
                if on {
                    mark(9 * k).position(x: cx, y: l0 + 6.6 * k)
                    Text(title).font(.system(size: title.count > 2 ? 10 : 11, weight: .black, design: .rounded))
                        .foregroundStyle(look.ink)
                        .lineLimit(1).minimumScaleFactor(0.6)
                        .frame(width: 38 * k)
                        .position(x: cx, y: l1 - 6.4 * k)
                } else {
                    mark(14 * k).position(x: cx, y: (l0 + l1) / 2)
                }
            }
            .frame(width: size.width, height: size.height)
            .brightness(on ? 0.06 : 0)
            .scaleEffect(on ? 1.06 : 1, anchor: foot)
            .offset(y: on ? -lift : 0)
        }
        .frame(width: size.width, height: size.height)
        .animation(reduceMotion ? nil : .spring(response: 0.3, dampingFraction: 0.72), value: on)
    }
    /// The glyph on the label, `points` high.
    @ViewBuilder private func mark(_ points: CGFloat) -> some View {
        if let pinned = look.pinnedBody {
            ShellGlyphView(glyph: .body(pinned), size: points * 1.15, ink: look.ink)
        } else {
            Image(systemName: look.symbol).font(.system(size: points, weight: .bold)).foregroundStyle(look.ink)
        }
    }
}

/// A bottle pressed: it gives a little, with the glass's ding on the wire.
private struct SodaBottleStyle: ButtonStyle {
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { SodaBottleBody(configuration: configuration, quiet: quiet) }
}
private struct SodaBottleBody: View {
    let configuration: ButtonStyle.Configuration
    let quiet: Bool
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .scaleEffect(down ? 0.96 : 1, anchor: .bottom)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                if !quiet { ConsoleSounds.shared.play(.beacon, scale: 0.4) }
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

/// The lenses (and the 机型 pinned among them) as bottles on the wire shelf:
/// a row that goes along, keeping the lens in use in sight (at once with
/// Reduce Motion). A new one taken up, the one put back knocks on the wire.
private struct SodaShelf: View {
    @ObservedObject var model: CameraAppModel
    var soda: SodaLayout
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    private enum Item: Hashable { case lens(CameraLens), body(CameraBody) }
    var body: some View {
        let items: [Item] = CameraLens.allCases.map(Item.lens) + model.pinnedBodies.map(Item.body)
        ScrollViewReader { reader in
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(alignment: .top, spacing: soda.bottleGap) {
                    ForEach(items, id: \.self) { item in
                        bottle(item).id(item)
                    }
                }
                .padding(.horizontal, soda.bottlePad)
                .frame(height: soda.shelf.height)
            }
            .accessibilityIdentifier("camera-deck-lenses")
            .onAppear { reader.scrollTo(Item.lens(model.lens), anchor: .center) }
            .onChange(of: model.lens) { _, lens in
                withAnimation(reduceMotion ? nil : .easeOut(duration: 0.15)) { reader.scrollTo(Item.lens(lens), anchor: .center) }
                guard !model.recording else { return }
                Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 130_000_000)
                    ConsoleSounds.shared.play(.keyRubber, scale: 0.3)
                }
            }
        }
        .opacity(model.controlsShown ? 0 : 1)
        .allowsHitTesting(!model.controlsShown)
    }
    private func bottle(_ item: Item) -> some View {
        let title: String, about: String, chosen: Bool, identifier: String, look: SodaBottleLook
        switch item {
        case .lens(let lens):
            title = lens.title; about = lens.blurb; chosen = model.lens == lens
            identifier = "camera-deck-lens-\(lens.rawValue)"; look = SodaBottleLook.of(lens)
        case .body(let pinned):
            title = pinned.title; about = pinned.blurb; chosen = model.body == pinned
            identifier = "camera-deck-pinned-\(pinned.rawValue)"; look = SodaBottleLook.pinned(pinned)
        }
        return Button {
            switch item {
            case .lens(let lens): model.choose(lens)
            case .body(let pinned): model.tapPinned(pinned)
            }
        } label: {
            SodaBottle(look: look, title: title, on: chosen, size: soda.bottle, scale: soda.bottleScale, lift: soda.bottleLift, base: soda.shelfLine - soda.shelf.minY)
        }
        .buttonStyle(SodaBottleStyle(quiet: model.recording))
        .frame(width: soda.bottle.width, height: soda.bottle.height)
        .accessibilityLabel(title)
        .accessibilityValue(chosen ? String(localized: "在用") : about)
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
}

/// The lamp before 录像: dark red, lit while the toggle is at 录像.
private struct SodaLamp: View {
    var lit: Bool
    var body: some View {
        let glow = Color(red: 1.0, green: 0.231, blue: 0.188)
        ZStack {
            Circle().fill(Color(red: 0.357, green: 0.165, blue: 0.149))
            Circle().fill(RadialGradient(colors: [Color(red: 1.0, green: 0.824, blue: 0.8), glow, Color(red: 0.722, green: 0.114, blue: 0.071)],
                                         center: UnitPoint(x: 0.36, y: 0.36), startRadius: 0.3, endRadius: 4))
                .opacity(lit ? 1 : 0)
            Circle().strokeBorder(Color.black.opacity(lit ? 0 : 0.4), lineWidth: 0.6)
        }
        .frame(width: 7.2, height: 7.2)
        .shadow(color: glow.opacity(lit ? 0.9 : 0), radius: 3)
        .accessibilityHidden(true)
    }
}

/// The toggle's bright hex nut, its dark middle.
private struct SodaToggleNut: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2)
            context.fill(Path(ellipseIn: CGRect(x: c.x - 10.5, y: c.y - 9.5, width: 21, height: 21)), with: .color(Color.black.opacity(0.22)))
            var nut = Path()
            for i in 0..<6 {
                let t = Double.pi / 6 + Double(i) * Double.pi / 3
                let p = CGPoint(x: c.x + CGFloat(cos(t)) * 9.5, y: c.y + CGFloat(sin(t)) * 9.5)
                if i == 0 { nut.move(to: p) } else { nut.addLine(to: p) }
            }
            nut.closeSubpath()
            context.fill(nut, with: .linearGradient(ClamPaint.chrome, startPoint: CGPoint(x: c.x - 9, y: c.y - 9), endPoint: CGPoint(x: c.x + 9, y: c.y + 9)))
            context.stroke(nut, with: .color(Color.black.opacity(0.3)), lineWidth: 0.7)
            context.fill(Path(ellipseIn: CGRect(x: c.x - 5.2, y: c.y - 5.2, width: 10.4, height: 10.4)), with: .color(Color(red: 0.227, green: 0.251, blue: 0.271)))
        }
        .frame(width: 24, height: 24)
        .allowsHitTesting(false)
    }
}

/// The toggle's chrome bat, from the nut (the middle of its place) up.
private struct SodaToggleBat: View, Equatable {
    var lever: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), length = lever
            var bat = Path()
            bat.move(to: CGPoint(x: c.x - 2.3, y: c.y))
            bat.addLine(to: CGPoint(x: c.x - 3.7, y: c.y - length))
            bat.addLine(to: CGPoint(x: c.x + 3.7, y: c.y - length))
            bat.addLine(to: CGPoint(x: c.x + 2.3, y: c.y))
            bat.closeSubpath()
            let bright = Gradient(stops: [Gradient.Stop(color: Color(red: 0.490, green: 0.514, blue: 0.549), location: 0), Gradient.Stop(color: Color.white, location: 0.35),
                                          Gradient.Stop(color: Color(red: 0.722, green: 0.741, blue: 0.769), location: 0.7), Gradient.Stop(color: Color(red: 0.435, green: 0.459, blue: 0.494), location: 1)])
            context.fill(bat, with: .linearGradient(bright, startPoint: CGPoint(x: c.x - 4, y: 0), endPoint: CGPoint(x: c.x + 4, y: 0)))
            let ball = CGRect(x: c.x - 4.7, y: c.y - length - 4.7, width: 9.4, height: 9.4)
            let round = Gradient(stops: [Gradient.Stop(color: Color.white, location: 0), Gradient.Stop(color: Color(red: 0.788, green: 0.804, blue: 0.827), location: 0.5),
                                         Gradient.Stop(color: Color(red: 0.490, green: 0.514, blue: 0.549), location: 1)])
            context.fill(Path(ellipseIn: ball), with: .radialGradient(round, center: CGPoint(x: c.x - 1.5, y: c.y - length - 1.5), startRadius: 0.4, endRadius: 5.5))
        }
        .frame(width: 16, height: 2 * lever + 12)
        .allowsHitTesting(false)
    }
}

/// The cooler light's toggle as 拍照 / 录像: a chrome bat on a white plate,
/// up for 拍照 (a camera over it), down for 录像 (a video camera under it):
/// the end it is at filled and darker, the lamp before 录像 lit. Thrown over
/// with a toggle's snap (at once with Reduce Motion).
private struct SodaToggle: View {
    var video: Bool
    var lit: Bool
    var across = false
    var quiet = false
    var action: () -> Void
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        Button(action: action) { face }
            .buttonStyle(SodaPressStyle(travel: 1, rest: 1.4, sound: quiet ? nil : .keySlide, scale: 0.75, haptic: .sliderNotch))
    }
    private var face: some View {
        let plate = RoundedRectangle(cornerRadius: 9, style: .continuous)
        let photoInk: Color = video ? SodaPaint.ink.opacity(0.42) : SodaPaint.ink
        let videoInk: Color = video ? SodaPaint.ink : SodaPaint.ink.opacity(0.42)
        return ZStack {
            plate.fill(LinearGradient(colors: [Color.white, Color(red: 0.886, green: 0.910, blue: 0.898)], startPoint: .top, endPoint: .bottom))
            plate.strokeBorder(SodaPaint.shade.opacity(0.25), lineWidth: 1)
            VStack(spacing: 0) {
                ShellGlyphView(glyph: .photo(!video), size: 16, ink: photoInk)
                    .padding(.top, 6)
                Spacer(minLength: 0)
                HStack(spacing: 4) {
                    SodaLamp(lit: lit)
                    ShellGlyphView(glyph: .video(video), size: 16, ink: videoInk)
                }
                .padding(.bottom, 5)
            }
            .padding(.horizontal, 2)
            SodaToggleNut().equatable()
            SodaToggleBat(lever: across ? 16 : 17).equatable()
                .scaleEffect(x: 1, y: video ? -1 : 1)
                .shadow(color: SodaPaint.shade.opacity(0.45), radius: 1.5, y: 2)
                .animation(reduceMotion ? nil : .easeInOut(duration: 0.12), value: video)
        }
        .padding(.horizontal, across ? 0 : 2)
        .padding(.vertical, 2)
    }
}

/// The thermostat's face: the wedge that thickens towards 4 (colder), the
/// four stops' figures round it (the one in use bolder; .5 faint without an
/// ultra wide), the white knob with its knurled edge. (The magnifying glass
/// under it, its name, is SodaKnob's.)
private struct SodaKnobFace: View, Equatable {
    var radius: CGFloat
    var at: Int
    var wide: Bool
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            func point(_ degrees: Double, _ q: CGFloat) -> CGPoint {
                let a = degrees * Double.pi / 180
                return CGPoint(x: c.x + CGFloat(sin(a)) * q, y: c.y - CGFloat(cos(a)) * q)
            }
            let a0 = SodaKnob.angles[0], a3 = SodaKnob.angles[3], w0 = r + 2.5
            var wedge = Path()
            for i in 0...48 {
                let p = point(a0 + (a3 - a0) * Double(i) / 48, w0)
                if i == 0 { wedge.move(to: p) } else { wedge.addLine(to: p) }
            }
            for i in stride(from: 48, through: 0, by: -1) {
                wedge.addLine(to: point(a0 + (a3 - a0) * Double(i) / 48, w0 + 1.2 + 4 * CGFloat(i) / 48))
            }
            wedge.closeSubpath()
            let cold = Gradient(colors: [Color(red: 0.749, green: 0.890, blue: 0.949), Color(red: 0.173, green: 0.525, blue: 0.769)])
            context.fill(wedge, with: .linearGradient(cold, startPoint: CGPoint(x: c.x - r, y: 0), endPoint: CGPoint(x: c.x + r, y: 0)))
            let figures = [".5", "1×", "2", "4"]
            for i in 0..<4 {
                let chosen = i == at
                let ink: Color = !wide && i == 0 ? SodaPaint.soft.opacity(0.4) : (chosen ? SodaPaint.ink : SodaPaint.soft)
                let figure = Text(verbatim: figures[i]).font(.system(size: chosen ? 12 : 11, weight: chosen ? .black : .heavy, design: .rounded)).foregroundColor(ink)
                context.draw(figure, at: point(SodaKnob.angles[i], r + 14))
            }
            context.fill(Path(ellipseIn: CGRect(x: c.x - r - 0.5, y: c.y - r + 1.5, width: 2 * r + 1, height: 2 * r + 1)), with: .color(SodaPaint.shade.opacity(0.38)))
            let disc = CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r)
            let white = Gradient(stops: [Gradient.Stop(color: Color.white, location: 0), Gradient.Stop(color: Color(red: 0.933, green: 0.949, blue: 0.937), location: 0.55),
                                         Gradient.Stop(color: Color(red: 0.765, green: 0.8, blue: 0.784), location: 1)])
            context.fill(Path(ellipseIn: disc), with: .radialGradient(white, center: CGPoint(x: c.x - r * 0.3, y: c.y - r * 0.4), startRadius: r * 0.1, endRadius: r * 1.3))
            var knurl = Path()
            for i in 0..<60 {
                let degrees = Double(i) * 6
                knurl.move(to: point(degrees, r - 2.8))
                knurl.addLine(to: point(degrees, r - 0.4))
            }
            context.stroke(knurl, with: .color(SodaPaint.shade.opacity(0.2)), lineWidth: 0.8)
            context.stroke(Path(ellipseIn: disc.insetBy(dx: 0.6, dy: 0.6)), with: .color(Color.white.opacity(0.9)), lineWidth: 1)
            context.stroke(Path(ellipseIn: disc.insetBy(dx: r * 0.2, dy: r * 0.2)), with: .color(SodaPaint.shade.opacity(0.12)), lineWidth: 1)
        }
        .allowsHitTesting(false)
    }
}

/// The knob's teal bar, the pointer: a white line at its top end.
private struct SodaKnobBar: View {
    var radius: CGFloat
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: 6.5, style: .continuous)
        let teal = LinearGradient(stops: [Gradient.Stop(color: Color(red: 0.059, green: 0.416, blue: 0.388), location: 0),
                                          Gradient.Stop(color: Color(red: 0.165, green: 0.647, blue: 0.588), location: 0.4),
                                          Gradient.Stop(color: Color(red: 0.043, green: 0.310, blue: 0.290), location: 1)], startPoint: .leading, endPoint: .trailing)
        ZStack(alignment: .top) {
            shape.fill(teal).shadow(color: SodaPaint.shade.opacity(0.42), radius: 1.5, y: 1.6)
            Capsule().fill(Color.white).frame(width: 2.2, height: 7.5).padding(.top, 3.5)
        }
        .frame(width: 13, height: max(0, 2 * radius - 8))
        .allowsHitTesting(false)
    }
}

/// The thermostat as the zoom (.5, 1×, 2, 4): turned a stop at a time, each
/// with a mechanical click; or touched on its left or right, one stop that
/// way. The bar goes to the stop in use (at once with Reduce Motion). Off
/// (in 相册) it only says why it waits.
private struct SodaKnob: View {
    @ObservedObject var model: CameraAppModel
    var radius: CGFloat
    /// How far under the knob's middle its name (the magnifying glass)
    /// stands, beyond its edge.
    var captionAt: CGFloat
    var off = false
    var why = ""
    var identifier = "camera-deck-zoom-dial"
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var from: Double? = nil
    @State private var turning = false
    @State private var slack: Double = 0
    /// The stops on the plate and where each stands (degrees from straight up).
    static let stops: [Double] = [0.5, 1, 2, 4]
    static let angles: [Double] = [-105, -35, 35, 105]
    /// Degrees of turn to a stop.
    static let notch = 36.0

    private func step(_ delta: Int) {
        if off { model.say(why); return }
        let stops = model.zoomStops
        let now = stops.lastIndex { $0 <= model.zoom + 0.05 } ?? 0
        let next = now + delta
        guard stops.indices.contains(next) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        if !model.recording { ConsoleSounds.shared.play(.keyRatchet, scale: 0.8) }
        ConsoleHaptics.shared.play(.sliderNotch, .press)
        model.setZoom(stops[next], sound: false)
    }
    var body: some View {
        let at = Self.stops.lastIndex { $0 <= model.zoom + 0.05 } ?? 0
        let wide = model.zoomStops.contains(0.5)
        let turned = Self.angles[at] + slack * 0.5
        GeometryReader { geo in
            let centre = CGPoint(x: geo.size.width / 2, y: geo.size.height / 2)
            // (The stops' figures and its name stand round the knob, past where it is touched.)
            let reach = radius + 30
            ZStack(alignment: .topLeading) {
                SodaKnobFace(radius: radius, at: at, wide: wide).equatable()
                    .frame(width: 2 * reach, height: 2 * reach)
                    .position(centre)
                ShellGlyphView(glyph: .zoom, size: 13, ink: SodaPaint.ink)
                    .position(x: centre.x, y: centre.y + radius + captionAt)
                SodaKnobBar(radius: radius)
                    .rotationEffect(.degrees(turned))
                    .position(centre)
                    .animation(reduceMotion ? nil : .spring(response: 0.25, dampingFraction: 0.75), value: at)
            }
            .frame(width: geo.size.width, height: geo.size.height)
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 0)
                .onChanged { value in
                    let angle = Double(atan2(value.location.y - centre.y, value.location.x - centre.x)) * 180 / .pi
                    guard let last = from else { from = angle; return }
                    if abs(value.translation.width) + abs(value.translation.height) > 8 { turning = true }
                    guard turning else { return }
                    var turn = angle - last
                    if turn > 180 { turn -= 360 }
                    if turn < -180 { turn += 360 }
                    if abs(turn) >= Self.notch {
                        from = angle
                        slack = 0
                        step(turn > 0 ? 1 : -1)
                    } else {
                        slack = turn
                    }
                }
                .onEnded { value in
                    if !turning { step(value.location.x < centre.x ? -1 : 1) }
                    from = nil
                    turning = false
                    withAnimation(.easeOut(duration: 0.12)) { slack = 0 }
                })
        }
        .accessibilityElement()
        .accessibilityLabel(String(localized: "变焦"))
        .accessibilityValue(CameraDeckFace.zoomText(model.zoom))
        .accessibilityAdjustableAction { direction in step(direction == .increment ? 1 : -1) }
        .accessibilityIdentifier(identifier)
    }
}

