/// The flip card's hook on the cabinet and the wire from it to the card's eyelets.
private struct SodaHanger: View, Equatable {
    var card: CGSize
    var hook: CGFloat
    var body: some View {
        Canvas { context, size in
            let cx = size.width / 2, top = hook + 9, x0 = cx - card.width / 2
            var wire = Path()
            wire.move(to: CGPoint(x: x0 + card.width * 0.22, y: top + 4.5))
            wire.addLine(to: CGPoint(x: cx, y: hook))
            wire.addLine(to: CGPoint(x: x0 + card.width * 0.78, y: top + 4.5))
            context.stroke(wire, with: .color(Color(red: 0.157, green: 0.235, blue: 0.227).opacity(0.75)), lineWidth: 1)
            for ex in [x0 + card.width * 0.22, x0 + card.width * 0.78] {
                context.fill(Path(ellipseIn: CGRect(x: ex - 1.6, y: top + 4.5 - 1.6, width: 3.2, height: 3.2)), with: .color(Color(red: 0.604, green: 0.627, blue: 0.659)))
            }
            let ball = CGRect(x: cx - 3.4, y: hook - 3.4, width: 6.8, height: 6.8)
            context.fill(Path(ellipseIn: ball), with: .radialGradient(Gradient(colors: [Color.white, Color(red: 0.490, green: 0.514, blue: 0.549)]),
                                                                      center: CGPoint(x: cx - 1, y: hook - 1), startRadius: 0.3, endRadius: 4.5))
            context.stroke(Path(ellipseIn: ball), with: .color(Color.black.opacity(0.4)), lineWidth: 0.6)
        }
        .allowsHitTesting(false)
    }
}

