/// 内 / 外 as a little enamel card on a hook. When the side changes, it
/// turns over on its hook (a half turn; not with Reduce Motion), with a hard
/// card's flick as it is pressed.
private struct SodaFlipCard: View {
    var side: String
    var small = false
    var quiet = false
    var action: () -> Void
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var turn: Double = 0
    var body: some View {
        let card = small ? CGSize(width: 42, height: 33) : CGSize(width: 54, height: 44)
        let hook: CGFloat = small ? 2 : 4
        Button(action: action) {
            ZStack(alignment: .top) {
                SodaFlipFace(small: small)
                    .frame(width: card.width, height: card.height)
                    .rotation3DEffect(.degrees(turn), axis: (x: 0, y: 1, z: 0), perspective: 0.5)
                    .padding(.top, hook + 9)
                SodaHanger(card: card, hook: hook).equatable()
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        }
        .buttonStyle(SodaPressStyle(travel: 1, rest: 1.6, sound: quiet ? nil : .cardFlip, scale: 0.7))
        .onChange(of: side) { _, _ in turnOver() }
    }
    /// Edge on, then round to face again from the other side.
    private func turnOver() {
        guard !reduceMotion else { return }
        withAnimation(.easeIn(duration: 0.12)) { turn = 90 }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 120_000_000)
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) { turn = -90 }
            withAnimation(.easeOut(duration: 0.14)) { turn = 0 }
        }
    }
}

/// The picture held to the cabinet's side by a yellow bar magnet with the
/// album's glyph on it; how many in a badge on the picture's corner.
private struct SodaMagnetFace: View {
    var image: CGImage?
    var count: Int
    var small: Bool
    var body: some View {
        let pw: CGFloat = small ? 40 : 54, ph: CGFloat = small ? 28 : 42
        let mw: CGFloat = small ? 36 : 40, mh: CGFloat = small ? 16 : 18
        let top: CGFloat = small ? 3 : 4
        ZStack(alignment: .top) {
            photo(pw, ph)
                .rotationEffect(.radians(small ? -0.07 : -0.06))
                .padding(.top, top + mh * 0.7)
            magnet(mw, mh).padding(.top, top)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
    }
    private func photo(_ pw: CGFloat, _ ph: CGFloat) -> some View {
        let badge: CGFloat = small ? 15 : 17
        return ZStack {
            Rectangle().fill(Color(red: 1.0, green: 0.996, blue: 0.976))
                .shadow(color: SodaPaint.shade.opacity(0.35), radius: 1.5, y: 1.5)
            ZStack {
                Color(white: 0.82)
                if let image {
                    Image(decorative: image, scale: 1).resizable().scaledToFill()
                } else {
                    Image(systemName: "photo").font(.system(size: small ? 11 : 13, weight: .bold)).foregroundStyle(SodaPaint.soft.opacity(0.6))
                }
            }
            .frame(width: pw - 6, height: ph - 6)
            .clipped()
        }
        .frame(width: pw, height: ph)
        .overlay(alignment: .bottomTrailing) {
            Text(verbatim: "\(count)").font(.system(size: small ? 10 : 10.5, weight: .black, design: .rounded)).monospacedDigit().foregroundStyle(Color.white)
                .lineLimit(1).fixedSize()
                .padding(.horizontal, 3)
                .frame(minWidth: badge, minHeight: badge)
                .background(Capsule().fill(SodaPaint.teal.color()).overlay(Capsule().strokeBorder(Color.white, lineWidth: 1.4)))
                .offset(x: badge / 2 - 5, y: badge / 2 - 5)
        }
    }
    private func magnet(_ mw: CGFloat, _ mh: CGFloat) -> some View {
        let yellow = LinearGradient(colors: [Color(red: 1.0, green: 0.898, blue: 0.541), Color(red: 0.969, green: 0.784, blue: 0.263), Color(red: 0.851, green: 0.635, blue: 0.110)],
                                    startPoint: .top, endPoint: .bottom)
        return ShellGlyphView(glyph: .album, size: small ? 12 : 13.5, ink: Color(red: 0.353, green: 0.227, blue: 0.0))
            .frame(width: mw, height: mh)
            .background(Capsule().fill(yellow).shadow(color: SodaPaint.shade.opacity(0.4), radius: 1.5, y: 1.8)
                .overlay(Capsule().strokeBorder(Color.white.opacity(0.6), lineWidth: 0.8)))
    }
}

