/// The big crown cap from above: 21 crimps round a flat top, each lit on
/// its upper left side, the inner ring, the cream print in the middle.
/// Drawn once for a size.
private struct SodaCapFace: View, Equatable {
    var radius: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius, crimps = 21
            let orange = SodaPaint.orange
            func polar(_ a: Double, _ q: CGFloat) -> CGPoint { CGPoint(x: c.x + CGFloat(cos(a)) * q, y: c.y + CGFloat(sin(a)) * q) }
            var rim = Path()
            let steps = crimps * 16
            for i in 0...steps {
                let a = Double(i) / Double(steps) * 2 * Double.pi
                let q = r - 2.4 + 2.4 * CGFloat(cos(a * Double(crimps)))
                if i == 0 { rim.move(to: polar(a, q)) } else { rim.addLine(to: polar(a, q)) }
            }
            rim.closeSubpath()
            let metal = Gradient(stops: [Gradient.Stop(color: orange.color(0.25), location: 0), Gradient.Stop(color: orange.color(0), location: 0.6),
                                         Gradient.Stop(color: orange.color(-0.3), location: 1)])
            context.fill(rim, with: .radialGradient(metal, center: CGPoint(x: c.x - r * 0.3, y: c.y - r * 0.35), startRadius: r * 0.2, endRadius: r * 1.2))
            context.stroke(rim, with: .color(orange.color(-0.45)), lineWidth: 0.8)
            let light = -2.3
            for i in 0..<crimps {
                let a = Double(i) / Double(crimps) * 2 * Double.pi, s = cos(a - light)
                var crimp = Path()
                crimp.move(to: polar(a - 0.05, r * 0.74))
                crimp.addLine(to: polar(a - 0.07, r - 1.5))
                crimp.addLine(to: polar(a + 0.07, r - 1.5))
                crimp.addLine(to: polar(a + 0.05, r * 0.74))
                crimp.closeSubpath()
                let tint: Color = s > 0 ? Color.white.opacity(0.32 * s) : Color(red: 0.314, green: 0.118, blue: 0.0).opacity(-0.3 * s)
                context.fill(crimp, with: .color(tint))
            }
            let r1 = r * 0.72
            context.fill(Path(ellipseIn: CGRect(x: c.x - r1 - 1.6, y: c.y - r1 - 1.6, width: 2 * r1 + 3.2, height: 2 * r1 + 3.2)), with: .color(orange.color(-0.28)))
            context.fill(Path(ellipseIn: CGRect(x: c.x - r1, y: c.y - r1, width: 2 * r1, height: 2 * r1)),
                         with: .radialGradient(Gradient(colors: [orange.color(0.3), orange.color(-0.06)]), center: CGPoint(x: c.x - r1 * 0.3, y: c.y - r1 * 0.4), startRadius: 1, endRadius: r1 * 1.3))
            let r2 = r1 * 0.74
            let print = Path(ellipseIn: CGRect(x: c.x - r2, y: c.y - r2, width: 2 * r2, height: 2 * r2))
            context.fill(print, with: .color(SodaPaint.cream.color()))
            context.stroke(print, with: .color(orange.color(-0.2)), lineWidth: 1)
        }
        .allowsHitTesting(false)
    }
}

