extension CameraDeckFace {
    /// The soda cooler's cabinet under its keys.
    func sodaBackdrop(_ soda: SodaLayout) -> some View {
        SodaBackdrop(layout: soda, hinge: hinge).equatable()
    }

    /// The glass door over the picture's edge: its chrome frame and the seal
    /// round the picture, a little frost on them (none over the picture).
    func sodaScreen(_ soda: SodaLayout) -> some View {
        SodaDoorRim(door: soda.door, hole: layout.picture).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
    }

    /// The soda cooler, upright or across (the same keys, each where its
    /// hold has it): ZERO on the light box; the seven price tags; the lenses
    /// as bottles on the shelf; the light's toggle (拍照 / 录像), the enamel
    /// plate (机型) and the thermostat (变焦); 主菜单 on the kick plate; the
    /// flip card (内 / 外), the picture under its magnet (相册) and the big cap
    /// (拍照). While a video is taken the keys make no sound of their own.
    @ViewBuilder func sodaFace(_ soda: SodaLayout) -> some View {
        let quiet = model.recording
        if soda.lightBox.width > 0 {
            SodaLightBoxMark(height: soda.lightBox.height).equatable()
                .deckPlaced(soda.lightBox)
        }
        sodaTags(soda, quiet: quiet)
        SodaShelf(model: model, soda: soda)
            .deckPlaced(soda.shelf)
        SodaLips(channels: soda.channels, rail: soda.rail).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        sodaToggle(soda, quiet: quiet)
        sodaPlate(soda, quiet: quiet)
        SodaKnob(model: model, radius: soda.knobRadius, captionAt: soda.across ? 8 : 9)
            .deckPlaced(soda.knob)
        sodaHome(soda, quiet: quiet)
        sodaFlip(soda, quiet: quiet)
        sodaMagnet(soda, quiet: quiet)
        sodaCap(soda)
    }

    /// The seven price tags (闪光, 定时, 日期, 画幅, 水平仪, 浓淡 −, 浓淡 +),
    /// each a glyph drawn as it is set; 画幅's figures and 浓淡's step (a row
    /// of cells) where a price would be written.
    @ViewBuilder private func sodaTags(_ soda: SodaLayout, quiet: Bool) -> some View {
        let rects = soda.tags
        if rects.count == 7 {
            let shooting = model.shooting
            let onWord = String(localized: "开"), offWord = String(localized: "关")
            let flashWord = String(localized: "闪光"), timerWord = String(localized: "定时"), dateWord = String(localized: "日期")
            let shapeWord = CameraShellSkin.soda.shapeTitle, levelWord = String(localized: "水平仪")
            let lessWord = String(localized: "浓淡") + " −", moreWord = String(localized: "浓淡") + " +"
            let video = model.mode == .video
            let timerWhy = String(localized: "录像时不用定时")
            let timed = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
            let dated = shooting.dateStamp ? onWord : offWord
            let levelled = model.leveler ? onWord : offWord
            let shown = model.shownBody
            let step = model.strengthStep(of: shown)
            let strength = CameraBodyStrength.title(step)
            let strengthState = shown == .native ? "—" : String(localized: "现 \(strength)")
            let strengthValue = shown == .native ? "" : strength
            // 浓淡's price: a cell for each step, as many filled as the step it is at (原生 has none: a dash).
            let lit = step - CameraBodyStrength.range.lowerBound + 1
            let cells: ShellGlyph? = shown == .native ? nil : ShellGlyph.tone(step: lit, of: CameraBodyStrength.values.count)
            let dash = shown == .native ? "—" : ""
            SodaTag(state: shooting.flash.title, glyph: .flash(shooting.flash), height: rects[0].height, quiet: quiet) {
                model.cycleFlash()
            }
            .accessibilityLabel(flashWord)
            .accessibilityValue(shooting.flash.title)
            .accessibilityIdentifier("camera-deck-flash")
            .deckKey(rects[0])
            SodaTag(state: model.timer.title, glyph: .timer(model.timer), height: rects[1].height, quiet: quiet) {
                if video { model.say(timerWhy) } else { model.cycleTimer() }
            }
            .accessibilityLabel(timerWord)
            .accessibilityValue(timed)
            .accessibilityIdentifier("camera-deck-timer")
            .deckDimmed(video, why: timerWhy)
            .deckKey(rects[1])
            SodaTag(state: dated, glyph: .date(shooting.dateStamp), height: rects[2].height, quiet: quiet) {
                model.toggleDateStamp()
            }
            .accessibilityLabel(dateWord)
            .accessibilityValue(dated)
            .accessibilityIdentifier("camera-deck-date")
            .deckKey(rects[2])
            SodaTag(state: model.shape.title, glyph: .shapeFrame(model.shape), price: model.shape.title, tone: .value, height: rects[3].height, quiet: quiet) {
                withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() }
            }
            .accessibilityLabel(shapeWord)
            .accessibilityValue(model.shape.title)
            .accessibilityIdentifier("camera-deck-aspect")
            .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
            .deckKey(rects[3])
            SodaTag(state: levelled, glyph: .level(model.leveler), height: rects[4].height, quiet: quiet) {
                model.toggleLeveler()
            }
            .accessibilityLabel(levelWord)
            .accessibilityValue(levelled)
            .accessibilityAddTraits(model.leveler ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-leveler")
            .deckKey(rects[4])
            // (Both say the same: only the second rustles as it changes.)
            SodaTag(state: strengthState, glyph: .toneDown, price: dash, cells: cells, tone: .value, height: rects[5].height, quiet: quiet, rustle: false) {
                model.stepBodyStrength(-1)
            }
            .accessibilityLabel(lessWord)
            .accessibilityValue(strengthValue)
            .accessibilityIdentifier("camera-deck-strength-minus")
            .deckKey(rects[5])
            SodaTag(state: strengthState, glyph: .toneUp, price: dash, cells: cells, tone: .value, height: rects[6].height, quiet: quiet) {
                model.stepBodyStrength(1)
            }
            .accessibilityLabel(moreWord)
            .accessibilityValue(strengthValue)
            .accessibilityIdentifier("camera-deck-strength-plus")
            .deckKey(rects[6])
        }
    }

    /// 拍照 / 录像: the light's toggle.
    private func sodaToggle(_ soda: SodaLayout, quiet: Bool) -> some View {
        let video = model.mode == .video
        return SodaToggle(video: video, lit: video, across: soda.across, quiet: quiet) {
            model.setMode(video ? .photo : .video)
        }
        .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
        .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
        .accessibilityIdentifier("camera-deck-mode")
        .deckKey(soda.toggle)
    }

    /// 机型: the enamel plate opens (or closes) the bodies' cards.
    private func sodaPlate(_ soda: SodaLayout, quiet: Bool) -> some View {
        Button {
            if model.bodiesOpen { model.closeBodies() } else { model.openBodies() }
        } label: {
            SodaPlateFace()
        }
        .buttonStyle(SodaPressStyle(travel: 1.5, rest: 1.6, sound: quiet ? nil : .keyMetal, scale: 0.5))
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
        .deckKey(soda.plate)
    }

    /// 主菜单: the kick plate's push button.
    private func sodaHome(_ soda: SodaLayout, quiet: Bool) -> some View {
        Button { model.leave() } label: { SodaHomeLabel(stacked: soda.homeStacked) }
            .buttonStyle(SodaHomeStyle(quiet: quiet))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(soda.home)
    }

    /// 内 / 外: the flip card on its hook (合体 changes the camera itself).
    private func sodaFlip(_ soda: SodaLayout, quiet: Bool) -> some View {
        let side = model.side.short
        return SodaFlipCard(side: side, small: soda.across || soda.flip.height < 70, quiet: quiet) { model.switchSide() }
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(side)
            .accessibilityIdentifier("camera-deck-switch")
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(soda.flip)
    }

    /// 相册: the newest picture under the magnet, how many on its corner.
    private func sodaMagnet(_ soda: SodaLayout, quiet: Bool) -> some View {
        let last = model.photos.first
        let image = last.flatMap { thumbnails.images[$0.url] }
        return SodaMagnetKey(image: image, count: model.photos.count, small: soda.across || soda.magnet.height < 76, quiet: quiet) {
            model.openAlbum()
        }
        .onAppear { if let last { thumbnails.request(last.url) } }
        .onChange(of: last?.url) { _, url in if let url { thumbnails.request(url) } }
        .accessibilityLabel(CameraShellSkin.soda.albumTitle)
        .accessibilityValue(String(localized: "\(model.photos.count) 张"))
        .accessibilityIdentifier("camera-deck-album")
        .deckKey(soda.magnet)
    }

    /// 拍照: the big cap (a camera on it; a red dot for a video, the square
    /// while one is taken — no word by it). A picture taken: the bottle's
    /// pop (the body's shutter), then its fizz.
    @ViewBuilder private func sodaCap(_ soda: SodaLayout) -> some View {
        let video = model.mode == .video
        let sign: SodaCapSign = video ? (model.recording ? .stop : .record) : .camera
        SodaCapKey(radius: soda.capRadius, sign: sign, ready: model.canShoot || model.recording) { model.shutter() }
            .onChange(of: model.flash) { _, _ in
                guard model.mode == .photo else { return }
                Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 140_000_000)
                    ConsoleSounds.shared.play(.sodaFizz, scale: 0.45)
                }
            }
            .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
            .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
            .accessibilityIdentifier("camera-deck-shutter")
            .deckKey(soda.shutter)
    }

    /// The soda cooler's 相册, upright and across.
    @ViewBuilder func sodaAlbum(_ soda: SodaLayout) -> some View {
        SodaAlbumView(model: model, thumbnails: thumbnails, soda: soda, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The soda cooler's album: 相册

/// The soda cooler's 相册: one picture held to the inside of the glass door
/// by two magnets, which one it is on a small price tag in its corner (a
/// video: ▶ over it and how long it is; touched, it plays there). The price
/// tags turn to ‹ (the one before's number), ▶ (a video's length), › (the
/// one after's) and 回去拍照 (its words kept); the shelf holds the pictures
/// in a row, each with its number, the one looked at larger and lifted (one
/// touched is looked at). The knob, the toggle, the enamel plate, the flip
/// card and the magnet wait, and say why; 主菜单 is as ever; the cap goes
/// back to taking pictures too.
private struct SodaAlbumView: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var soda: SodaLayout
    var hinge: CGRect
    /// How far the picture on the door is pushed aside (a turn, or a finger).
    @State private var push: CGFloat = 0
    @State private var turning = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    private var waiting: String { String(localized: "相册里用不了，回去拍照再用") }
    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    private func sharp(_ photo: CameraPhoto?) -> CGImage? {
        guard let photo else { return nil }
        return (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }
    /// The video's length ("00:12"), once it is known.
    private var length: String? {
        guard let photo = model.albumPhoto, photo.isVideo, model.albumImageURL == photo.url, let seconds = model.albumDuration else { return nil }
        return CameraAppModel.clock(Int(seconds.rounded()))
    }
    private var videoWord: String { length.map { String(localized: "视频 \($0)") } ?? String(localized: "录像") }

    /// The one before (−1) or after (+1): the picture slides out that way,
    /// the next comes in from the other side and the magnets catch it (at
    /// once with Reduce Motion).
    private func turn(_ delta: Int) {
        guard !drawing else { model.say(drawingWhy); return }
        let next = model.albumIndex + delta
        guard model.photos.indices.contains(next) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            if model.photos.isEmpty {
                model.say(String(localized: "还没有照片"))
            } else {
                model.say(delta < 0 ? String(localized: "已经是第一张") : String(localized: "已经是最后一张"))
            }
            withAnimation(.easeOut(duration: 0.15)) { push = 0 }
            return
        }
        guard !turning else { return }
        guard !reduceMotion else {
            push = 0
            model.chooseInAlbum(next, quiet: true)
            ConsoleSounds.shared.play(.magnet, scale: 0.7)
            return
        }
        turning = true
        let far = soda.glass.width
        let out: CGFloat = delta > 0 ? -far : far
        withAnimation(.easeIn(duration: 0.12)) { push = out }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 120_000_000)
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) {
                if model.phase == .album { model.chooseInAlbum(next, quiet: true) }
                push = -out
            }
            withAnimation(.easeOut(duration: 0.16)) { push = 0 }
            try? await Task.sleep(nanoseconds: 160_000_000)
            turning = false
            if model.phase == .album { ConsoleSounds.shared.play(.magnet, scale: 0.7) }
        }
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            SodaBackdrop(layout: soda, hinge: hinge).equatable()
            door
            SodaDoorRim(door: soda.door, hole: soda.glass).equatable()
            if soda.lightBox.width > 0 {
                SodaLightBoxMark(height: soda.lightBox.height).equatable()
                    .deckPlaced(soda.lightBox)
            }
            tags
            prints.deckPlaced(soda.shelf)
            SodaLips(channels: soda.channels, rail: soda.rail).equatable()
            waitingKeys
            Button { model.leave() } label: { SodaHomeLabel(stacked: soda.homeStacked) }
                .buttonStyle(SodaHomeStyle())
                .accessibilityLabel(String(localized: "camera.home.pill"))
                .accessibilityIdentifier("camera-deck-home")
                .deckKey(soda.home)
            cap
        }
    }

    /// The glass: the dark inside of the cooler, the picture held to it
    /// (a push to the side goes to the next one; a video plays where it is
    /// touched); while a picture is being drawn on inside, that it waits
    /// there; what the camera says, for a moment.
    private var door: some View {
        let g = soda.glass
        let photos = model.photos, at = model.albumIndex
        return ZStack {
            LinearGradient(colors: [Color(red: 0.173, green: 0.235, blue: 0.243), Color(red: 0.102, green: 0.141, blue: 0.149)], startPoint: .top, endPoint: .bottom)
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
            } else if photos.indices.contains(at) {
                doorPrint(photos[at], index: at, count: photos.count)
            }
            if model.doodle != nil {
                Text("正在编辑 · 打开 Duo，在下屏接着画").font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(Color.white)
                    .multilineTextAlignment(.center).lineLimit(2).minimumScaleFactor(0.7)
                    .padding(.horizontal, 12).padding(.vertical, 6)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 16)
            }
            if let toast = model.toast {
                Text(toast).font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(Color.white)
                    .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                    .padding(.horizontal, 10).padding(.vertical, 4)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 14)
                    .frame(maxHeight: .infinity, alignment: .bottom)
                    .padding(.bottom, 36)
                    .allowsHitTesting(false)
                    .transition(.opacity)
            }
        }
        .frame(width: g.width, height: g.height)
        .clipShape(RoundedRectangle(cornerRadius: 6.5, style: .continuous))
        .position(x: g.midX, y: g.midY)
    }

    /// The print on the glass: its white edge, the picture (as it was taken,
    /// in its own shape), a video's ▶ and its length, which one it is on a
    /// small tag, the two magnets over its top edge.
    private func doorPrint(_ photo: CameraPhoto, index: Int, count: Int) -> some View {
        let g = soda.glass
        let image = sharp(photo)
        let aspect: CGFloat = image.map { CGFloat($0.width) / CGFloat(max(1, $0.height)) } ?? 4.0 / 3
        let roomWidth = max(40, g.width - 16), roomHeight = max(40, g.height - 6)
        let iw = max(20, min(roomWidth - 10, (roomHeight - 10) * aspect)), ih = iw / aspect
        let playing = model.playing == photo.url
        return ZStack {
            Rectangle().fill(Color(red: 1.0, green: 0.996, blue: 0.976))
                .shadow(color: Color.black.opacity(0.5), radius: 3, y: 2)
                .frame(width: iw + 10, height: ih + 10)
            ZStack {
                Color(white: 0.14)
                if let image { Image(decorative: image, scale: 1).resizable().scaledToFill() }
                if photo.isVideo {
                    #if os(iOS)
                    if playing {
                        CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                            .accessibilityIdentifier("camera-album-player")
                    }
                    #endif
                    if !playing {
                        SodaPlaySign()
                            .accessibilityHidden(true)
                    }
                }
            }
            .frame(width: iw, height: ih)
            .clipped()
            .overlay(alignment: .topTrailing) {
                SodaPlaceTag(text: "\(index + 1) / \(count)")
                    .padding(8)
            }
            .overlay(alignment: .bottomLeading) {
                if photo.isVideo, !playing {
                    SodaVideoBadge(word: length ?? "")
                        .padding(8)
                        .accessibilityHidden(true)
                }
            }
            SodaDoorMagnets(width: iw + 10)
                .frame(width: iw + 10, height: ih + 10, alignment: .top)
        }
        .frame(width: g.width, height: g.height)
        .offset(x: push)
        .contentShape(Rectangle())
        .gesture(DragGesture(minimumDistance: 8)
            .onChanged { value in if !turning { push = value.translation.width } }
            .onEnded { value in
                let dx = value.translation.width
                if abs(dx) > 60 {
                    turn(dx < 0 ? 1 : -1)
                } else {
                    withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                }
            })
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .contain)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : CameraShellSkin.soda.albumTitle)
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    /// The album's price tags: ‹ and the one before's number, ▶ (the square
    /// while it plays) and a video's length (a picture's waits), › and the
    /// one after's number, and the orange-headed 回去拍照, its words kept
    /// (VoiceOver still hears 按瓶盖也行: the cap goes back too).
    @ViewBuilder private var tags: some View {
        let rects = soda.albumTags
        if rects.count == 4 {
            let photos = model.photos, at = model.albumIndex
            let none = photos.isEmpty, empty = String(localized: "还没有照片")
            let video = model.albumPhoto?.isVideo == true
            let earlier = String(localized: "上一张"), later = String(localized: "下一张")
            let hasBefore = !none && at > 0, hasAfter = at + 1 < photos.count
            let before = hasBefore ? String(localized: "第 \(at) 张") : "—"
            let after = hasAfter ? String(localized: "第 \(at + 2) 张") : "—"
            let beforeFigure = hasBefore ? "\(at)" : "—"
            let afterFigure = hasAfter ? "\(at + 2)" : "—"
            let firstWhy = none ? empty : String(localized: "已经是第一张")
            let lastWhy = none ? empty : String(localized: "已经是最后一张")
            let playing = model.playing != nil
            let playWord = playing ? String(localized: "停止") : String(localized: "播放")
            let playWhy = none ? empty : String(localized: "照片不能播放；要在上面画，展开后用相册的「编辑」")
            let playState = video ? videoWord : String(localized: "照片")
            let playFigure = video ? (length ?? "—") : ""
            let back = String(localized: "回去拍照")
            let alsoCap = String(localized: "按瓶盖也行")
            SodaTag(state: before, glyph: .previous, price: beforeFigure, tone: .value, height: rects[0].height, quiet: true, rustle: false) {
                turn(-1)
            }
            .accessibilityLabel(earlier)
            .accessibilityValue(hasBefore ? before : "")
            .accessibilityIdentifier("camera-deck-album-previous")
            .deckDimmed(!hasBefore, why: firstWhy)
            .deckKey(rects[0])
            SodaTag(state: playState, glyph: playing ? .stop : .play, price: playFigure, tone: video ? .on : .off, height: rects[1].height, rustle: false) {
                if video { model.togglePlay() } else { model.say(playWhy) }
            }
            .accessibilityLabel(playWord)
            .accessibilityValue(playState)
            .accessibilityIdentifier("camera-deck-album-play")
            .deckDimmed(!video, why: playWhy)
            .deckKey(rects[1])
            SodaTag(state: after, glyph: .next, price: afterFigure, tone: .value, height: rects[2].height, quiet: true, rustle: false) {
                turn(1)
            }
            .accessibilityLabel(later)
            .accessibilityValue(hasAfter ? after : "")
            .accessibilityIdentifier("camera-deck-album-next")
            .deckDimmed(!hasAfter, why: lastWhy)
            .deckKey(rects[2])
            SodaTag(state: alsoCap, glyph: .returnToShooting, words: back, tone: .value, height: rects[3].height, head: SodaPaint.orange.color(),
                    glyphInk: Color(red: 0.722, green: 0.337, blue: 0.051), rustle: false) {
                backToCamera()
            }
            .accessibilityLabel(back)
            .accessibilityValue(alsoCap)
            .accessibilityIdentifier("camera-deck-album-return")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(rects[3])
        }
    }

    /// The pictures standing on the shelf, the newest first, each with its
    /// number over it: the one looked at larger, lifted, in a teal edge; one
    /// touched is looked at.
    private var prints: some View {
        let photos = model.photos, at = model.albumIndex
        let base = soda.shelfLine - soda.shelf.minY
        let tilts: [Double] = [-0.05, 0.04, 0, -0.04, 0.05, -0.03]
        return ScrollViewReader { reader in
            ScrollView(.horizontal, showsIndicators: false) {
                LazyHStack(alignment: .top, spacing: 6) {
                    ForEach(Array(photos.enumerated()), id: \.element.url) { index, photo in
                        Button {
                            if index != at { model.chooseInAlbum(index, quiet: true) }
                        } label: {
                            SodaPrint(image: thumbnails.images[photo.url], video: photo.isVideo, number: "\(index + 1)",
                                      chosen: index == at, tilt: tilts[index % tilts.count], base: base)
                        }
                        .buttonStyle(SodaPrintStyle())
                        .frame(width: soda.printCell, height: soda.shelf.height)
                        .onAppear { thumbnails.request(photo.url) }
                        .accessibilityLabel(String(localized: "第 \(index + 1) 张"))
                        .accessibilityValue(photo.isVideo ? String(localized: "录像") : String(localized: "照片"))
                        .accessibilityAddTraits(index == at ? [.isButton, .isSelected] : .isButton)
                        .accessibilityIdentifier("camera-deck-album-cell-\(index)")
                    }
                }
                .padding(.horizontal, max(3, soda.bottlePad - 1))
                .frame(height: soda.shelf.height)
            }
            .onChange(of: at) { _, now in
                guard photos.indices.contains(now) else { return }
                withAnimation(reduceMotion ? nil : .easeOut(duration: 0.2)) { reader.scrollTo(photos[now].url, anchor: .center) }
            }
            .onAppear { if photos.indices.contains(at) { reader.scrollTo(photos[at].url, anchor: .center) } }
        }
    }

    /// The knob, the toggle, the enamel plate, the flip card and the magnet:
    /// paler, quiet, and pressed they say why they wait.
    @ViewBuilder private var waitingKeys: some View {
        let video = model.mode == .video
        let side = model.side.short
        SodaToggle(video: video, lit: video, across: soda.across, quiet: true) { model.say(waiting) }
            .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
            .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
            .deckDimmed(true, why: waiting)
            .deckKey(soda.toggle)
        Button { model.say(waiting) } label: { SodaPlateFace() }
            .buttonStyle(SodaPressStyle(travel: 1.5, rest: 1.6, sound: nil))
            .accessibilityLabel(String(localized: "切换机型"))
            .accessibilityValue(model.body.title)
            .deckDimmed(true, why: waiting)
            .deckKey(soda.plate)
        SodaKnob(model: model, radius: soda.knobRadius, captionAt: soda.across ? 8 : 9, off: true, why: waiting, identifier: "")
            .deckDimmed(true, why: waiting)
            .deckPlaced(soda.knob)
        SodaFlipCard(side: side, small: soda.across || soda.flip.height < 70, quiet: true) { model.say(waiting) }
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(side)
            .deckDimmed(true, why: waiting)
            .deckKey(soda.flip)
        SodaMagnetKey(image: sharp(model.albumPhoto), count: model.photos.count, small: soda.across || soda.magnet.height < 76, quiet: true) { model.say(waiting) }
            .accessibilityLabel(CameraShellSkin.soda.albumTitle)
            .accessibilityValue(String(localized: "\(model.photos.count) 张"))
            .deckDimmed(true, why: waiting)
            .deckKey(soda.magnet)
    }

    /// The cap: back to taking pictures (回去拍照 by it).
    @ViewBuilder private var cap: some View {
        SodaCapKey(radius: soda.capRadius, sign: .camera, haptic: .smallButton, sound: .keyMetal) { backToCamera() }
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-close")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(soda.shutter)
        SodaCaption(word: String(localized: "回去拍照"), alignment: soda.captionAlignment)
            .deckPlaced(soda.captionFrame)
    }
}

/// ▶ over a video on the door: a dark disc, its white ring.
private struct SodaPlaySign: View {
    var body: some View {
        ZStack {
            Circle().fill(Color.black.opacity(0.45))
            Circle().strokeBorder(Color.white.opacity(0.9), lineWidth: 2)
            Image(systemName: "play.fill").font(.system(size: 22, weight: .black)).foregroundStyle(Color.white).offset(x: 2)
        }
        .frame(width: 52, height: 52)
        .allowsHitTesting(false)
    }
}

/// A video camera and the video's length (once it is known), in a dark
/// capsule at the picture's lower corner.
private struct SodaVideoBadge: View {
    var word: String
    var body: some View {
        HStack(spacing: 4) {
            Image(systemName: "video.fill").font(.system(size: 11, weight: .bold))
            if !word.isEmpty {
                Text(word).font(.system(size: 11.5, weight: .black, design: .rounded)).monospacedDigit()
                    .lineLimit(1).fixedSize()
            }
        }
        .foregroundStyle(Color.white)
        .padding(.horizontal, 9)
        .frame(height: 22)
        .background(Capsule().fill(Color.black.opacity(0.55)))
        .allowsHitTesting(false)
    }
}

/// Which picture it is and of how many ("7 / 12"), on a small price tag
/// (a teal strip down its left) in the picture's corner.
private struct SodaPlaceTag: View {
    var text: String
    var body: some View {
        let paper = RoundedRectangle(cornerRadius: 3, style: .continuous)
        Text(verbatim: text).font(.system(size: 13, weight: .black, design: .rounded)).monospacedDigit().foregroundStyle(SodaPaint.ink)
            .lineLimit(1).minimumScaleFactor(0.7)
            .padding(.leading, 9).padding(.trailing, 6)
            .frame(minWidth: 62, minHeight: 26)
            .background {
                ZStack(alignment: .leading) {
                    paper.fill(SodaPaint.paper)
                    SodaPaint.teal.color().frame(width: 5)
                }
                .clipShape(paper)
                .shadow(color: Color.black.opacity(0.3), radius: 1.5, y: 1)
            }
            .fixedSize()
            .accessibilityIdentifier("camera-deck-album-position")
    }
}

/// The two round magnets (blue, pink) holding the print up by its top edge.
private struct SodaDoorMagnets: View {
    var width: CGFloat
    var body: some View {
        HStack(spacing: 0) {
            magnet([Color(red: 0.839, green: 0.949, blue: 1.0), Color(red: 0.424, green: 0.769, blue: 0.933), Color(red: 0.176, green: 0.525, blue: 0.722)])
            Spacer(minLength: 0)
            magnet([Color(red: 1.0, green: 0.839, blue: 0.878), Color(red: 0.961, green: 0.541, blue: 0.651), Color(red: 0.769, green: 0.314, blue: 0.431)])
        }
        .padding(.horizontal, 13)
        .frame(width: width)
        .offset(y: -7)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
    private func magnet(_ colours: [Color]) -> some View {
        Circle().fill(RadialGradient(colors: colours, center: UnitPoint(x: 0.36, y: 0.33), startRadius: 0.5, endRadius: 11))
            .frame(width: 18, height: 18)
            .background(Circle().fill(Color.black.opacity(0.35)).frame(width: 19, height: 19).offset(y: 1.5))
    }
}

/// A small print stood on the shelf: a white edge round the picture (▶ on a
/// video's), leaning a little; the one looked at upright, larger, lifted,
/// in a teal edge (at once with Reduce Motion). Its number over it.
private struct SodaPrint: View {
    var image: CGImage?
    var video: Bool
    var number: String
    var chosen: Bool
    var tilt: Double
    /// Where it stands, from the top of its place.
    var base: CGFloat
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let k: CGFloat = chosen ? 1.12 : 1, w = 46 * k, h = 36 * k, lift: CGFloat = chosen ? 4 : 0
        let margin: CGFloat = chosen ? 5 : 2.6
        GeometryReader { geo in
            let cx = geo.size.width / 2
            ZStack(alignment: .topLeading) {
                ZStack {
                    Rectangle().fill(chosen ? SodaPaint.teal.color() : SodaPaint.paper)
                        .shadow(color: Color(red: 0.0, green: 0.118, blue: 0.157).opacity(0.35), radius: 1.5, y: 1.5)
                    if chosen { Rectangle().fill(SodaPaint.paper).padding(2.5) }
                    ZStack {
                        Color(white: 0.82)
                        if let image { Image(decorative: image, scale: 1).resizable().scaledToFill() }
                    }
                    .frame(width: w - 2 * margin, height: h - 2 * margin)
                    .clipped()
                    if video {
                        ZStack {
                            Circle().fill(Color.black.opacity(0.5))
                            Image(systemName: "play.fill").font(.system(size: 7, weight: .black)).foregroundStyle(Color.white).offset(x: 0.8)
                        }
                        .frame(width: 15, height: 15)
                    }
                }
                .frame(width: w, height: h)
                .rotationEffect(.radians(chosen ? 0 : tilt))
                .position(x: cx, y: base - h / 2 - lift)
                Text(number).font(.system(size: 10, weight: .black, design: .rounded)).foregroundStyle(chosen ? SodaPaint.ink : SodaPaint.soft)
                    .lineLimit(1).fixedSize()
                    .position(x: cx, y: base + 0.5 - h - lift - 7)
            }
            .frame(width: geo.size.width, height: geo.size.height)
        }
        .animation(reduceMotion ? nil : .spring(response: 0.3, dampingFraction: 0.75), value: chosen)
    }
}

/// A print touched: it gives a little, with the photo paper's rustle.
private struct SodaPrintStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View { SodaPrintBody(configuration: configuration) }
}
private struct SodaPrintBody: View {
    let configuration: ButtonStyle.Configuration
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .scaleEffect(down ? 0.96 : 1, anchor: .bottom)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.04 : 0.1), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.cardFlip, scale: 0.6)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

