/// Where the photo-sticker booth's parts are on the cover, upright (from a
/// ShellPlan) or across (from a ShellAcrossPlan): the same parts both ways,
/// each laid out for its hold (mock/bt7.js).
struct BoothLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    var u: CGFloat = 1
    /// The lit sign (its corners' radii from the upper left round), its
    /// word's size, how far in its bulbs stand, the two stars on it.
    var sign = CGRect.zero
    var signCorners: [CGFloat] = [16, 16, 16, 16]
    var signWord: CGFloat = 22
    var signInset: CGFloat = 8
    var signStars = false
    /// The striped awning under the sign (.zero: none).
    var valance = CGRect.zero
    /// The screen's moulded frame, the picture's 4:3 place in it, how far
    /// down the pieces stuck at its upper corners sit.
    var frame = CGRect.zero
    var box = CGRect.zero
    var decoTop: CGFloat = 0
    /// The lace trim along the foot (.zero: no room for it).
    var foot = CGRect.zero
    /// The hood round the phone's own camera; the curtain where the Camera
    /// Control's overlay comes in (hung along the top held across).
    var hood = CGRect.zero
    var curtain = CGRect.zero
    /// 选边框: its words, the strip of thumbnails, ◀ and ▶, their domes.
    var title = CGRect.zero
    var strip = CGRect.zero
    var previous = CGRect.zero
    var next = CGRect.zero
    var arcade: CGFloat = 23
    /// The enamel plate: 闪光, 日期, 水平仪, 画幅, 浓淡 (its − and ＋ and
    /// their caps; narrow: no dots between them).
    var plate = CGRect.zero
    var plateRadius: CGFloat = 14
    var switches: [CGRect] = []
    var aspect = CGRect.zero
    var tone = CGRect.zero
    var toneMinus = CGRect.zero
    var tonePlus = CGRect.zero
    var toneMinusCap = CGRect.zero
    var tonePlusCap = CGRect.zero
    var narrow = false
    /// The sticker outlet (相册), 拍照 / 录像, 主菜单 (and its cap), the
    /// door with 换机型.
    var outlet = CGRect.zero
    var mode = CGRect.zero
    var home = CGRect.zero
    var homeCap = CGRect.zero
    var door = CGRect.zero
    /// 内 / 外 (its cap, and the words of the side under it), the countdown
    /// lamps, the shutter and its dome.
    var flip = CGRect.zero
    var flipCap = CGRect.zero
    var flipWords = CGRect.zero
    var timer = CGRect.zero
    var shutter = CGRect.zero
    var shutterRadius: CGFloat = 27
    /// 相册: the outlet the sheet hangs from, where the sheet may be, ◀ ▶
    /// (their domes), the lamps' sign between them, 回去拍照, 播放 (its cap
    /// and its window), 主菜单 (its cap).
    var sheetOutlet = CGRect.zero
    var sheet = CGRect.zero
    var albumPrevious = CGRect.zero
    var albumNext = CGRect.zero
    var albumArcade: CGFloat = 25
    var albumSign = CGRect.zero
    var albumBack = CGRect.zero
    var albumPlay = CGRect.zero
    var albumPlayCap = CGRect.zero
    var albumPlayWindow = CGRect.zero
    var albumHome = CGRect.zero
    var albumHomeCap = CGRect.zero

    /// Where a candy key's collar is in its place: its cap grown by the
    /// collar's 3 points, as insets from the place's edges.
    static func collar(_ key: CGRect, _ cap: CGRect) -> EdgeInsets {
        EdgeInsets(top: max(0, cap.minY - 3 - key.minY), leading: max(0, cap.minX - 3 - key.minX),
                   bottom: max(0, key.maxY - cap.maxY - 3), trailing: max(0, key.maxX - cap.maxX - 3))
    }
}

extension ShellPlan {
    /// The booth's parts, upright: the sign and its awning over the screen's
    /// frame at the head of the column; under it 选边框 between ◀ and ▶, the
    /// plate of switches and small keys, the outlet, the slide, 主菜单 and the
    /// door (mock/bt7.js's points from the keys' top); in the strip the hood
    /// round the camera, 内 / 外, the countdown lamps, the curtain where the
    /// Camera Control's overlay comes in, the shutter under it. 相册: the
    /// outlet across the top, the sheet hanging from it, the keys under it.
    var booth: BoothLayout {
        var l = BoothLayout()
        let c = back.column, k = keysTop, strip = back.strip
        let floor = back.keepOut.map(\.maxY).max() ?? top
        let zone = back.overlay
        l.canvas = back.canvas
        l.u = u
        l.sign = CGRect(x: x(12), y: top - 6, width: 374 * u, height: 48)
        l.signCorners = [34, 16, 14, 14]
        l.signStars = true
        l.valance = CGRect(x: x(16), y: top + 42, width: 368 * u, height: 6)
        l.frame = surround
        l.box = box
        l.decoTop = 4
        l.foot = CGRect(x: c.minX + 6, y: c.maxY + 7, width: max(0, c.width - 10), height: 6)
        // (The camera's own place, as the hardware has it, is the last one kept out.)
        if let camera = back.keepOut.last { l.hood = camera.insetBy(dx: 0, dy: -1) }
        // 选边框: the strip between the two lit keys.
        l.title = CGRect(x: c.minX + 20, y: k, width: max(0, c.width - 40), height: 15)
        l.previous = CGRect(x: c.minX + 4, y: k + 23, width: 56, height: 56)
        l.next = CGRect(x: c.maxX - 60, y: k + 23, width: 56, height: 56)
        l.strip = CGRect(x: c.minX + 68, y: k + 16, width: max(0, c.width - 136), height: 70)
        // The plate of small things: its cells across it, each as wide as it is
        // drawn at this scale and never under 44 to touch; the gaps between them
        // share what is left (6 at least while there is room), the dots between
        // 浓淡's − and ＋ giving way first.
        l.plate = CGRect(x: c.minX, y: k + 94, width: c.width, height: 66)
        let row = CGRect(x: c.minX + 4 * u, y: k + 96, width: max(0, c.width - 8 * u), height: 62)
        let cell = max(44, 52 * u), key = max(44, 44 * u)
        let spare = row.width - 4 * cell - 2 * key
        let gap: CGFloat, dots: CGFloat
        if spare - 40 * u >= 24 {
            gap = (spare - 40 * u) / 4
            dots = 40 * u
        } else if spare >= 30 {
            gap = 6
            dots = spare - 24
        } else {
            gap = max(0, spare / 5)
            dots = gap
        }
        let pitch = cell + gap
        l.switches = [0, 1, 2].map { CGRect(x: row.minX + CGFloat($0) * pitch, y: row.minY, width: cell, height: row.height) }
        l.aspect = CGRect(x: row.minX + 3 * pitch, y: row.minY, width: cell, height: row.height)
        l.toneMinus = CGRect(x: row.minX + 4 * pitch, y: row.minY, width: key, height: row.height)
        l.tonePlus = CGRect(x: l.toneMinus.maxX + dots, y: row.minY, width: key, height: row.height)
        l.tone = CGRect(x: l.toneMinus.minX, y: row.minY, width: l.tonePlus.maxX - l.toneMinus.minX, height: row.height)
        l.narrow = dots < 30
        let capWidth: CGFloat = l.narrow ? 26 : 30
        l.toneMinusCap = CGRect(x: l.toneMinus.midX - capWidth / 2, y: row.minY + 16, width: capWidth, height: 22)
        l.tonePlusCap = CGRect(x: l.tonePlus.midX - capWidth / 2, y: row.minY + 16, width: capWidth, height: 22)
        // The outlet, the slide, 主菜单, the door.
        l.outlet = block(14, 168, 146, 132)
        l.mode = block(168, 168, 128, 48)
        l.home = block(304, 168, 82, 48)
        l.homeCap = block(307, 171, 76, 42)
        l.door = block(168, 222, 218, 78)
        // The grip's side: its parts against the outer edge.
        let gx = max(strip.midX, strip.maxX - 29)
        let flipTop = max(top, floor) + 6
        l.flip = CGRect(x: gx - 29, y: flipTop, width: 58, height: 60)
        l.flipCap = CGRect(x: gx - 24, y: flipTop + 4, width: 48, height: 34)
        l.flipWords = CGRect(x: gx - 21, y: flipTop + 43, width: 42, height: 16)
        let timerTop = flipTop + 68
        let timerFloor: CGFloat = (zone?.minY ?? (c.maxY - 120)) - 6
        l.timer = CGRect(x: gx - 31, y: timerTop, width: 62, height: max(0, min(120, timerFloor - timerTop)))
        if let zone { l.curtain = CGRect(x: gx - 32, y: zone.minY, width: 66, height: max(0, zone.height - 2)) }
        let under: CGFloat = (zone?.maxY ?? (timerTop + 120)) + 10
        let shutterTop = max(under, c.maxY - 84)
        let d = max(0, min(66, c.maxY - 2 - shutterTop))
        l.shutter = CGRect(x: gx - d / 2, y: shutterTop, width: d, height: d)
        l.shutterRadius = max(12, d / 2 - 6)
        // 相册.
        l.sheetOutlet = CGRect(x: x(16), y: top + 48, width: 368 * u, height: 40)
        l.sheet = CGRect(x: c.minX + 32, y: top + 74, width: max(0, c.width - 64), height: max(0, c.maxY - 218 - (top + 74)))
        l.albumPrevious = CGRect(x: c.minX + 16, y: c.maxY - 202, width: 56, height: 56)
        l.albumNext = CGRect(x: c.maxX - 72, y: c.maxY - 202, width: 56, height: 56)
        l.albumArcade = 25
        let signWidth = max(0, min(168, c.width - 160))
        l.albumSign = CGRect(x: c.midX - signWidth / 2, y: c.maxY - 198, width: signWidth, height: 48)
        l.albumBack = CGRect(x: c.minX + 2, y: c.maxY - 132, width: max(0, c.width - 2), height: 56)
        let half = max(0, (c.width - 10) / 2)
        l.albumPlay = CGRect(x: c.minX + 2, y: c.maxY - 68, width: half, height: 68)
        l.albumPlayCap = CGRect(x: c.minX + 5, y: c.maxY - 65, width: max(0, half - 6), height: 38)
        l.albumPlayWindow = CGRect(x: c.minX + 2 + half / 2 - 40, y: c.maxY - 22, width: 80, height: 16)
        l.albumHome = CGRect(x: c.minX + 10 + half, y: c.maxY - 68, width: half, height: 68)
        l.albumHomeCap = CGRect(x: c.minX + 13 + half, y: c.maxY - 65, width: max(0, half - 6), height: 62)
        return l
    }
}

extension ShellAcrossPlan {
    /// The booth's parts with the cover held across: the screen's frame at
