    /// its keys in the column.
    var booth: BoothLayout {
        var l = BoothLayout()
        let band = back.band, run = back.run, s = back.screen
        l.across = true
        l.canvas = back.canvas
        l.signCorners = [16, 16, 16, 16]
        l.signWord = 24
        l.signInset = 9
        // (Where the shutter has to share the longer run, what is left of it.)
        let room: CGFloat = back.spare.width >= 70 ? run.width : run.width - 96
        if room >= 120 {
            let w = min(188, room + 2)
            l.sign = CGRect(x: run.minX - 1, y: band.minY + 10, width: w, height: 56)
            // (The awning hangs under the sign: only where the band is along the top.)
            if band.minY < 1 { l.valance = CGRect(x: run.minX + 3, y: band.minY + 64, width: max(0, w - 8), height: 5) }
        }
        if let zone = back.overlay, zone.width > 30 {
            l.curtain = CGRect(x: zone.minX + 6, y: band.minY + 4, width: max(0, zone.width - 8), height: 62)
        }
        if let camera = back.keepOut.last { l.hood = camera.insetBy(dx: -1, dy: -1) }
        l.frame = surround
        l.box = box
        l.decoTop = 0
        let foot = CGRect(x: l.frame.minX + 8, y: l.frame.maxY + 10, width: max(0, l.frame.width - 12), height: 6)
        if !foot.intersects(band), foot.maxY <= back.canvas.height - 2 { l.foot = foot }
        l.shutter = shutter
        l.shutterRadius = 25
        // The column (mock/bt7.js's points from its corner).
        l.previous = key(0, 2, 46, 46)
        l.next = key(154, 2, 46, 46)
        l.arcade = 19
        l.title = key(48, 6, 104, 40)
        l.strip = key(0, 54, 200, 66)
        l.plate = key(-3, 123, 152, 124)
        l.plateRadius = 12
        l.switches = [key(0, 126, 44, 56), key(51, 126, 44, 56), key(102, 126, 44, 56)]
        l.aspect = key(0, 188, 44, 56)
        l.tone = key(51, 188, 95, 56)
        l.toneMinus = key(51, 188, 44, 56)
        l.tonePlus = key(102, 188, 44, 56)
        l.toneMinusCap = key(56, 204, 26, 22)
        l.tonePlusCap = key(115, 204, 26, 22)
        l.narrow = true
        l.timer = key(154, 124, 46, 120)
        l.mode = key(0, 254, 96, 44)
        l.door = key(102, 254, 98, 44)
        l.outlet = key(0, 306, 90, 50)
        l.home = key(96, 306, 52, 50)
        l.homeCap = key(99, 309, 46, 44)
        l.flip = key(154, 306, 46, 50)
        l.flipCap = key(157, 309, 40, 26)
        l.flipWords = key(154, 341, 46, 14)
        // 相册: the sheet where the screen is, the keys in the column.
        l.sheetOutlet = CGRect(x: s.minX + 4, y: s.minY + 2, width: max(0, s.width - 8), height: 34)
        l.sheet = CGRect(x: s.minX + 20, y: s.minY + 26, width: max(0, s.width - 40), height: max(0, s.height - 30))
        l.albumPrevious = key(0, 2, 46, 46)
        l.albumNext = key(154, 2, 46, 46)
        l.albumArcade = 19
        l.albumSign = key(52, 5, 96, 40)
        l.albumBack = key(0, 58, 200, 62)
        l.albumPlay = key(0, 130, 146, 120)
        l.albumPlayCap = key(3, 133, 140, 60)
        l.albumPlayWindow = key(28, 212, 90, 20)
        l.albumHome = key(0, 296, 146, 60)
        l.albumHomeCap = key(3, 299, 140, 54)
        return l
    }
}

/// One piece of a rounded rectangle's edge (a side or a corner), for
/// placing things evenly round it.
private struct BoothEdgePiece {
    var line: Bool
    /// A side: from `a` to `b`. A corner: round `a`, `radius` out, from the
    /// angle `from` to `to`.
    var a: CGPoint
    var b = CGPoint.zero
    var radius: CGFloat = 0
    var from = 0.0
    var to = 0.0
    var length: CGFloat { line ? hypot(b.x - a.x, b.y - a.y) : radius * CGFloat(to - from) }
    func point(_ along: CGFloat) -> CGPoint {
        if line {
            let k = length > 0 ? along / length : 0
            return CGPoint(x: a.x + (b.x - a.x) * k, y: a.y + (b.y - a.y) * k)
        }
        let angle = from + (radius > 0 ? Double(along / radius) : 0)
        return CGPoint(x: a.x + CGFloat(cos(angle)) * radius, y: a.y + CGFloat(sin(angle)) * radius)
    }
}

/// The booth's drawing, part for part as the pictures of it were
/// (mock/bt7.js): the candy plastic, the sign and its bulbs, the awning,
/// the screen's frame and its lace, the shapes printed or stuck on it, the
/// plate, the outlet, the door, the hood, the curtain, the lace trim.
private enum BoothArt {
    static func round(_ r: CGRect, _ radius: CGFloat) -> Path {
        Path(roundedRect: r, cornerRadius: max(0, min(radius, r.width / 2, r.height / 2)))
    }
    /// A rounded rectangle with its own radius at each corner (upper left,
    /// upper right, lower right, lower left).
    static func round(_ r: CGRect, corners: [CGFloat]) -> Path {
        let cap = max(0, min(r.width, r.height) / 2)
        func q(_ i: Int) -> CGFloat { corners.indices.contains(i) ? max(0, min(corners[i], cap)) : 0 }
        let radii = RectangleCornerRadii(topLeading: q(0), bottomLeading: q(3), bottomTrailing: q(2), topTrailing: q(1))
        return Path(roundedRect: r, cornerRadii: radii, style: .circular)
    }
    static func disc(_ c: CGPoint, _ r: CGFloat) -> Path {
        Path(ellipseIn: CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r))
    }
    /// A disc's lower half under `c` (a scallop of an awning, a hem, a trim).
    static func scallop(_ c: CGPoint, _ r: CGFloat) -> Path {
        let radii = RectangleCornerRadii(topLeading: 0, bottomLeading: r, bottomTrailing: r, topTrailing: 0)
        return Path(roundedRect: CGRect(x: c.x - r, y: c.y, width: 2 * r, height: r), cornerRadii: radii, style: .circular)
    }
    static func vertical(_ stops: [Gradient.Stop], _ r: CGRect) -> GraphicsContext.Shading {
        .linearGradient(Gradient(stops: stops), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY))
    }
    static func stop(_ colour: Color, _ at: CGFloat) -> Gradient.Stop { Gradient.Stop(color: colour, location: at) }

    /// Points evenly round a rounded rectangle with its own radius at each
    /// corner (upper left, upper right, lower right, lower left).
    static func walk(_ r: CGRect, _ corners: [CGFloat], step: CGFloat) -> [CGPoint] {
        guard corners.count == 4, r.width > 0, r.height > 0, step > 0 else { return [] }
        let a = corners[0], b = corners[1], c = corners[2], d = corners[3], q = Double.pi / 2
        let pieces: [BoothEdgePiece] = [
            BoothEdgePiece(line: true, a: CGPoint(x: r.minX + a, y: r.minY), b: CGPoint(x: r.maxX - b, y: r.minY)),
            BoothEdgePiece(line: false, a: CGPoint(x: r.maxX - b, y: r.minY + b), radius: b, from: -q, to: 0),
            BoothEdgePiece(line: true, a: CGPoint(x: r.maxX, y: r.minY + b), b: CGPoint(x: r.maxX, y: r.maxY - c)),
            BoothEdgePiece(line: false, a: CGPoint(x: r.maxX - c, y: r.maxY - c), radius: c, from: 0, to: q),
            BoothEdgePiece(line: true, a: CGPoint(x: r.maxX - c, y: r.maxY), b: CGPoint(x: r.minX + d, y: r.maxY)),
            BoothEdgePiece(line: false, a: CGPoint(x: r.minX + d, y: r.maxY - d), radius: d, from: q, to: 2 * q),
            BoothEdgePiece(line: true, a: CGPoint(x: r.minX, y: r.maxY - d), b: CGPoint(x: r.minX, y: r.minY + a)),
            BoothEdgePiece(line: false, a: CGPoint(x: r.minX + a, y: r.minY + a), radius: a, from: 2 * q, to: 3 * q)
        ]
        let total = pieces.reduce(CGFloat(0)) { $0 + $1.length }
        guard total > 0 else { return [] }
        let n = max(4, Int((total / step).rounded()))
        var out: [CGPoint] = []
        for i in 0..<n {
            var along = (CGFloat(i) + 0.5) * total / CGFloat(n)
            for piece in pieces {
                let length = piece.length
                if along > length { along -= length; continue }
                out.append(piece.point(along))
                break
            }
        }
        return out
    }

    /// Dots in rows, every other row half a step along.
    static func dots(_ context: GraphicsContext, _ r: CGRect, step: CGFloat, radius: CGFloat, colour: Color) {
        guard step > 0, r.width > 0, r.height > 0 else { return }
        var all = Path()
        var row = 0
        var y = r.minY
        while y < r.maxY + step {
            var x = r.minX - step + (row % 2 == 1 ? step / 2 : 0)
            while x < r.maxX + step {
                all.addEllipse(in: CGRect(x: x - radius, y: y - radius, width: 2 * radius, height: 2 * radius))
                x += step
            }
            y += step * 0.866
            row += 1
        }
        context.fill(all, with: .color(colour))
    }

    // The shapes printed or stuck on the booth, round (0, 0), `s` how far they reach.
    static func heart(_ s: CGFloat) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: 0, y: s * 0.9))
        path.addCurve(to: CGPoint(x: 0, y: -s * 0.4), control1: CGPoint(x: -s * 1.5, y: -s * 0.1), control2: CGPoint(x: -s * 0.75, y: -s * 1.15))
        path.addCurve(to: CGPoint(x: 0, y: s * 0.9), control1: CGPoint(x: s * 0.75, y: -s * 1.15), control2: CGPoint(x: s * 1.5, y: -s * 0.1))
        path.closeSubpath()
        return path
    }
    /// A five-pointed star, or a four-pointed sparkle.
    static func star(_ s: CGFloat, spark: Bool = false) -> Path {
        let points = spark ? 8 : 10
        let inner: CGFloat = spark ? s * 0.28 : s * 0.47
        var path = Path()
        for i in 0..<points {
            let a = -Double.pi / 2 + Double(i) * 2 * Double.pi / Double(points)
            let reach: CGFloat = i % 2 == 1 ? inner : s
            let p = CGPoint(x: CGFloat(cos(a)) * reach, y: CGFloat(sin(a)) * reach)
            if i == 0 { path.move(to: p) } else { path.addLine(to: p) }
        }
        path.closeSubpath()
        return path
    }
    /// A shape at `c`, turned: printed flat, or stuck on (a white edge and a
    /// shadow, lighter above, its gloss).
    static func stick(_ context: GraphicsContext, _ outline: Path, at c: CGPoint, size s: CGFloat, colour: ShellTone,
                      turn: Double = 0, sticker: Bool = false, edge: CGFloat = 3) {
        let place = CGAffineTransform(rotationAngle: CGFloat(turn)).concatenating(CGAffineTransform(translationX: c.x, y: c.y))
        let shape = outline.applying(place)
        guard sticker else {
            context.fill(shape, with: .color(colour.color()))
            return
        }
        var lifted = context
        lifted.addFilter(.shadow(color: BoothPaint.wine.opacity(0.35), radius: 1.5, x: 0, y: 1.5))
        lifted.stroke(shape, with: .color(Color.white), style: StrokeStyle(lineWidth: edge, lineJoin: .round))
        lifted.fill(shape, with: .color(colour.color()))
        let face = Gradient(stops: [stop(colour.color(0.45), 0), stop(colour.color(), 0.55), stop(colour.color(-0.12), 1)])
        context.fill(shape, with: .linearGradient(face, startPoint: CGPoint(x: c.x, y: c.y - s), endPoint: CGPoint(x: c.x, y: c.y + s)))
        var gloss = context
        gloss.clip(to: shape)
        let tilt = CGAffineTransform(rotationAngle: -0.5).concatenating(CGAffineTransform(translationX: -s * 0.25, y: -s * 0.42))
        let shine = Path(ellipseIn: CGRect(x: -s * 0.42, y: -s * 0.2, width: s * 0.84, height: s * 0.4)).applying(tilt.concatenating(place))
        gloss.fill(shine, with: .color(Color.white.opacity(0.6)))
    }
    /// A flower of five petals stuck on, its yellow middle.
    static func flower(_ context: GraphicsContext, at c: CGPoint, size s: CGFloat, colour: ShellTone) {
        var backs = Path(), petals = Path()
        for i in 0..<5 {
            let a = -Double.pi / 2 + Double(i) * 2 * Double.pi / 5
            let p = CGPoint(x: c.x + CGFloat(cos(a)) * s * 0.55, y: c.y + CGFloat(sin(a)) * s * 0.55)
            backs.addPath(disc(p, s * 0.5))
            petals.addPath(disc(p, s * 0.4))
        }
        var lifted = context
        lifted.addFilter(.shadow(color: BoothPaint.wine.opacity(0.32), radius: 1.5, x: 0, y: 1.4))
        lifted.fill(backs, with: .color(Color.white))
        context.fill(petals, with: .radialGradient(Gradient(colors: [colour.color(0.5), colour.color()]), center: c, startRadius: s * 0.2, endRadius: s))
        let core = Gradient(colors: [Color(red: 1, green: 0.965, blue: 0.784), Color(red: 1, green: 0.839, blue: 0.275)])
        context.fill(disc(c, s * 0.34), with: .radialGradient(core, center: CGPoint(x: c.x - s * 0.1, y: c.y - s * 0.12), startRadius: 0.3, endRadius: s * 0.4))
    }
    /// A soap bubble: clear, a blue rim, a bright spot.
    static func bubble(_ context: GraphicsContext, at c: CGPoint, radius r: CGFloat) {
        let blue = ShellTone(r: 0.549, g: 0.808, b: 1)
        let ball = disc(c, r)
        let fill = Gradient(stops: [stop(Color.white.opacity(0.9), 0), stop(blue.color(0.5).opacity(0.45), 0.4), stop(blue.color().opacity(0.75), 1)])
        context.fill(ball, with: .radialGradient(fill, center: CGPoint(x: c.x - r * 0.3, y: c.y - r * 0.35), startRadius: r * 0.1, endRadius: r * 1.1))
        context.stroke(ball, with: .color(blue.color(-0.12).opacity(0.8)), lineWidth: 0.9)
        context.fill(disc(CGPoint(x: c.x - r * 0.36, y: c.y - r * 0.38), r * 0.22), with: .color(Color.white.opacity(0.95)))
    }
    /// Words drawn on the body.
    static func word(_ context: GraphicsContext, _ words: String, at p: CGPoint, size: CGFloat, colour: Color, weight: Font.Weight = .heavy) {
        context.draw(Text(words).font(.system(size: size, weight: weight, design: .rounded)).foregroundColor(colour), at: p)
    }

    // MARK: the body

    /// Glossy candy plastic: white polka dots, a little glitter, a sheen, the
    /// hinge's side in shade, a light edge.
    static func body(_ context: GraphicsContext, _ size: CGSize, _ hinge: CGRect) {
        let whole = CGRect(origin: .zero, size: size), tone = BoothPaint.body
        let plastic = Gradient(stops: [stop(tone.color(0.28), 0), stop(tone.color(), 0.45), stop(tone.color(-0.12), 1)])
        context.fill(Path(whole), with: .linearGradient(plastic, startPoint: .zero, endPoint: CGPoint(x: size.width * 0.5, y: size.height)))
        dots(context, whole, step: 16, radius: 1.7, colour: Color.white.opacity(0.3))
        var seed: UInt32 = 0x0B07_7A11
        func next() -> CGFloat {
            seed = seed &* 1_664_525 &+ 1_013_904_223
            return CGFloat((seed >> 8) & 0xFFFF) / 65535
        }
        for _ in 0..<Int(size.width * size.height / 260) {
            let p = CGPoint(x: next() * size.width, y: next() * size.height), s = 0.8 + next() * 1.8
            let ink = Color.white.opacity(0.25 + Double(next()) * 0.5)
            context.fill(Path(CGRect(x: p.x - s / 2, y: p.y - 0.3, width: s, height: 0.6)), with: .color(ink))
            context.fill(Path(CGRect(x: p.x - 0.3, y: p.y - s / 2, width: 0.6, height: s)), with: .color(ink))
        }
        let sheen = Gradient(stops: [stop(Color.white.opacity(0.3), 0), stop(Color.white.opacity(0.05), 0.5), stop(BoothPaint.wine.opacity(0.1), 1)])
        context.fill(Path(whole), with: .radialGradient(sheen, center: CGPoint(x: size.width * 0.18, y: size.height * 0.06), startRadius: 6,
                                                        endRadius: max(size.width, size.height) * 0.85))
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let near = tall ? hinge.midX < size.width / 2 : hinge.midY < size.height / 2
            let edge: CGFloat = near ? 0 : (tall ? size.width : size.height)
            let inward: CGFloat = near ? 14 : -14
            let from = tall ? CGPoint(x: edge, y: 0) : CGPoint(x: 0, y: edge)
            let to = tall ? CGPoint(x: edge + inward, y: 0) : CGPoint(x: 0, y: edge + inward)
            let shade = tall ? CGRect(x: min(edge, edge + inward), y: 0, width: 14, height: size.height)
                : CGRect(x: 0, y: min(edge, edge + inward), width: size.width, height: 14)
            context.fill(Path(shade), with: .linearGradient(Gradient(colors: [BoothPaint.wine.opacity(0.35), BoothPaint.wine.opacity(0)]), startPoint: from, endPoint: to))
        }
        context.stroke(Path(roundedRect: whole.insetBy(dx: 1.5, dy: 1.5), cornerRadius: 44.5), with: .color(Color.white.opacity(0.6)), lineWidth: 1.4)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 0.5, dy: 0.5), cornerRadius: 46), with: .color(Color(red: 0.471, green: 0.078, blue: 0.275).opacity(0.55)), lineWidth: 1)
    }

    // MARK: the sign

    /// The sign's bulbs, where they stand.
    static func bulbs(_ l: BoothLayout) -> [CGPoint] {
        guard l.sign.width > 20, l.sign.height > 20 else { return [] }
        let b = l.signInset
        return walk(l.sign.insetBy(dx: b, dy: b), l.signCorners.map { max(1.5, $0 - b) }, step: 12)
    }
    /// The eight ways round a letter, for its outline.
    static let ring: [CGPoint] = [CGPoint(x: 1, y: 0), CGPoint(x: 0.707, y: 0.707), CGPoint(x: 0, y: 1), CGPoint(x: -0.707, y: 0.707),
                                  CGPoint(x: -1, y: 0), CGPoint(x: -0.707, y: -0.707), CGPoint(x: 0, y: -1), CGPoint(x: 0.707, y: -0.707)]
    /// ZERO in bubble letters: a deep extrusion, a pink edge, a white face
    /// that glows a little.
    static func lettering(_ context: GraphicsContext, at p: CGPoint, size: CGFloat, spacing: CGFloat) {
        func zero(_ colour: Color) -> Text {
            Text(verbatim: "ZERO").font(.system(size: size, weight: .black, design: .rounded)).tracking(spacing).foregroundColor(colour)
        }
        let at = CGPoint(x: p.x + spacing / 2, y: p.y)
        let deep = Color(red: 0.361, green: 0.024, blue: 0.212), edge = Color(red: 1, green: 0.624, blue: 0.808)
        for drop in [CGFloat(3.2), 2.2, 1.2] {
            for d in ring { context.draw(zero(deep), at: CGPoint(x: at.x + d.x * 3, y: at.y + drop + d.y * 3)) }
        }
        for d in ring { context.draw(zero(edge), at: CGPoint(x: at.x + d.x * 2.6, y: at.y + d.y * 2.6)) }
        var glow = context
        glow.addFilter(.shadow(color: Color.white.opacity(0.85), radius: 3))
        glow.draw(zero(Color.white), at: at)
    }
    /// The lit sign: a white moulded box, its magenta face glowing in the
    /// middle, the bulbs round it (unlit: the lamps over them light them),
    /// ZERO, two stars stuck on it.
    static func sign(_ context: GraphicsContext, _ l: BoothLayout) {
        let r = l.sign
        guard r.width > 20, r.height > 20 else { return }
        let box = round(r, corners: l.signCorners)
        var lifted = context
        lifted.addFilter(.shadow(color: Color(red: 0.392, green: 0.039, blue: 0.235).opacity(0.42), radius: 3.5, x: 0, y: 3))
        lifted.fill(box, with: vertical([stop(Color.white, 0), stop(Color(red: 0.992, green: 0.941, blue: 0.965), 0.6), stop(Color(red: 0.925, green: 0.788, blue: 0.851), 1)], r))
        let faceRect = r.insetBy(dx: 4, dy: 4)
        let face = round(faceRect, corners: l.signCorners.map { max(1.5, $0 - 4) })
        context.fill(face, with: vertical([stop(BoothPaint.sign.color(0.2), 0), stop(BoothPaint.sign.color(), 0.5), stop(BoothPaint.signDeep.color(), 1)], faceRect))
        var glow = context
        glow.clip(to: face)
        let light = Color(red: 1, green: 0.667, blue: 0.863)
        glow.fill(Path(r), with: .radialGradient(Gradient(colors: [light.opacity(0.6), light.opacity(0)]), center: CGPoint(x: r.midX, y: r.midY), startRadius: 2, endRadius: r.width * 0.5))
        context.stroke(face, with: .color(Color(red: 0.314, green: 0, blue: 0.180).opacity(0.6)), lineWidth: 1)
        var sockets = Path()
        let points = bulbs(l)
        for p in points { sockets.addPath(disc(CGPoint(x: p.x, y: p.y + 0.4), 4.1)) }
        context.fill(sockets, with: .color(Color(red: 0.275, green: 0.024, blue: 0.157).opacity(0.55)))
        let unlit = Gradient(stops: [stop(Color.white.opacity(0.8), 0), stop(Color(red: 0.914, green: 0.776, blue: 0.831), 0.5), stop(Color(red: 0.655, green: 0.482, blue: 0.553), 1)])
        for p in points {
            context.fill(disc(p, 2.6), with: .radialGradient(unlit, center: CGPoint(x: p.x - 0.78, y: p.y - 0.91), startRadius: 0.2, endRadius: 3))
        }
        lettering(context, at: CGPoint(x: r.midX, y: r.midY - 0.5), size: l.signWord, spacing: 7)
        if l.signStars {
            stick(context, star(6.5), at: CGPoint(x: r.minX + 60, y: r.midY), size: 6.5, colour: BoothPaint.lemon, turn: -0.2, sticker: true, edge: 2)
            stick(context, star(6.5), at: CGPoint(x: r.maxX - 58, y: r.midY), size: 6.5, colour: BoothPaint.lemon, turn: 0.2, sticker: true, edge: 2)
        }
    }
    /// Bulbs lit: a warm glow round them all, each glass bright in the middle.
    static func litBulbs(_ context: GraphicsContext, _ points: [CGPoint]) {
        guard !points.isEmpty else { return }
        var all = Path()
        for p in points { all.addPath(disc(p, 2.6)) }
        var glow = context
        glow.addFilter(.shadow(color: Color(red: 1, green: 0.839, blue: 0.471), radius: 3.5))
        glow.fill(all, with: .color(Color(red: 1, green: 0.918, blue: 0.651)))
        let lit = Gradient(stops: [stop(Color(red: 1, green: 1, blue: 0.965), 0), stop(Color(red: 1, green: 0.918, blue: 0.651), 0.45), stop(Color(red: 1, green: 0.710, blue: 0.239), 1)])
        for p in points {
            context.fill(disc(p, 2.6), with: .radialGradient(lit, center: CGPoint(x: p.x - 0.78, y: p.y - 0.91), startRadius: 0.2, endRadius: 3))
        }
    }

    /// The striped awning: each stripe ends in a round scallop; the rod over it.
    static func valance(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 20, r.height > 0 else { return }
        let n = max(2, Int((r.width / 19).rounded())), sw = r.width / CGFloat(n), half = sw / 2
        let radii = RectangleCornerRadii(topLeading: 0, bottomLeading: half, bottomTrailing: half, topTrailing: 0)
        func tongue(_ i: Int, _ drop: CGFloat) -> Path {
            Path(roundedRect: CGRect(x: r.minX + CGFloat(i) * sw, y: r.minY, width: sw, height: r.height + drop + half), cornerRadii: radii, style: .circular)
        }
        var shade = Path()
        for i in 0..<n { shade.addPath(tongue(i, 2.2)) }
        context.fill(shade, with: .color(BoothPaint.wine.opacity(0.26)))
        for i in 0..<n {
            let left = r.minX + CGFloat(i) * sw
            let c = i % 2 == 1 ? BoothPaint.white : BoothPaint.stripe
            let cloth = Gradient(stops: [stop(c.color(-0.1), 0), stop(c.color(0.3), 0.45), stop(c.color(-0.15), 1)])
            context.fill(tongue(i, 0), with: .linearGradient(cloth, startPoint: CGPoint(x: left, y: 0), endPoint: CGPoint(x: left + sw, y: 0)))
        }
        let rod = CGRect(x: r.minX - 2, y: r.minY - 3, width: r.width + 4, height: 5)
        context.fill(round(rod, 2.5), with: vertical([stop(Color.white, 0), stop(Color(red: 0.886, green: 0.714, blue: 0.792), 1)], rod))
    }

    // MARK: the screen's frame

    /// The screen's white moulded frame: its pale polka, a pink rim.
    static func frame(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 40, r.height > 40 else { return }
        var lifted = context
        lifted.addFilter(.shadow(color: BoothPaint.wine.opacity(0.38), radius: 4, x: 0, y: 3))
        lifted.fill(round(r, 22), with: vertical([stop(Color.white, 0), stop(Color(red: 1, green: 0.957, blue: 0.976), 0.55), stop(Color(red: 0.965, green: 0.851, blue: 0.902), 1)], r))
        var inner = context
        inner.clip(to: round(r.insetBy(dx: 4, dy: 4), 18))
        dots(inner, r, step: 10, radius: 1.3, colour: Color(red: 1, green: 0.549, blue: 0.745).opacity(0.22))
        context.stroke(round(r.insetBy(dx: 3, dy: 3), 19), with: .color(BoothPaint.lace.color().opacity(0.75)), lineWidth: 1.6)
        context.stroke(round(r.insetBy(dx: 0.7, dy: 0.7), 22), with: .color(Color.white.opacity(0.95)), lineWidth: 1)
    }
    /// Pink lace round the picture: scallops with eyelets, a stitch; the
    /// screen's dark edge right round the picture.
    static func lace(_ context: GraphicsContext, _ p: CGRect) {
        guard p.width > 20, p.height > 20 else { return }
        let band = p.insetBy(dx: -7, dy: -7)
        let points = walk(band, [13, 13, 13, 13], step: 7.2)
        let pink = BoothPaint.lace.color()
        context.fill(round(band, 13), with: .color(pink))
        var scallops = Path(), eyelets = Path()
        for q in points {
            scallops.addPath(disc(q, 3.6))
            eyelets.addPath(disc(q, 1.05))
        }
        context.fill(scallops, with: .color(pink))
        context.fill(eyelets, with: .color(Color.white.opacity(0.95)))
        context.stroke(round(band.insetBy(dx: 3, dy: 3), 10), with: .color(Color.white.opacity(0.9)), style: StrokeStyle(lineWidth: 1, dash: [2.4, 2]))
        context.fill(round(p.insetBy(dx: -2, dy: -2), 9), with: .color(Color(red: 0.110, green: 0.067, blue: 0.094)))
    }
    /// What is printed down the frame's sides and stuck at its corners
    /// (`box`: the picture's 4:3 place; all of it outside that).
    static func decorations(_ context: GraphicsContext, frame f: CGRect, box p: CGRect, top: CGFloat) {
        let lx = (f.minX + 4 + p.minX - 11) / 2, rx = (f.maxX - 4 + p.maxX + 11) / 2
        var y = p.minY + 34
        var i = 0
        while y < p.maxY - 40 {
            if i % 2 == 1 {
                stick(context, star(3.6), at: CGPoint(x: lx, y: y), size: 3.6, colour: BoothPaint.gold)
                stick(context, heart(3.2), at: CGPoint(x: rx, y: y + 13), size: 3.2, colour: BoothPaint.lace)
            } else {
                stick(context, heart(3.2), at: CGPoint(x: lx, y: y), size: 3.2, colour: BoothPaint.lace)
                stick(context, star(3.6), at: CGPoint(x: rx, y: y + 13), size: 3.6, colour: BoothPaint.gold)
            }
            y += 27
            i += 1
        }
        stick(context, heart(11), at: CGPoint(x: f.minX + 10, y: f.minY + 13 + top), size: 11, colour: ShellTone(r: 1, g: 0.329, b: 0.627), turn: -0.32, sticker: true)
        flower(context, at: CGPoint(x: f.maxX - 10, y: f.minY + 12 + top), size: 9, colour: ShellTone(r: 0.729, g: 0.588, b: 1))
        stick(context, star(11.5), at: CGPoint(x: f.maxX - 10, y: f.maxY - 12), size: 11.5, colour: ShellTone(r: 1, g: 0.808, b: 0.180), turn: 0.2, sticker: true)
        bubble(context, at: CGPoint(x: f.minX + 9, y: f.maxY - 24), radius: 6.5)
        bubble(context, at: CGPoint(x: f.minX + 4, y: f.maxY - 39), radius: 4.2)
        bubble(context, at: CGPoint(x: f.minX + 15, y: f.maxY - 42), radius: 3)
        stick(context, star(5, spark: true), at: CGPoint(x: f.minX + 22, y: f.maxY - 9), size: 5, colour: BoothPaint.white, sticker: true, edge: 1.5)
        stick(context, heart(5), at: CGPoint(x: f.maxX - 6, y: f.minY + 40 + top), size: 5, colour: ShellTone(r: 0.471, g: 0.784, b: 1), turn: 0.3, sticker: true, edge: 2)
    }

    // MARK: the parts round the keys

    /// The enamel plate the small keys sit in, a stitched pink edge.
    static func plate(_ context: GraphicsContext, _ r: CGRect, radius: CGFloat) {
        guard r.width > 10, r.height > 10 else { return }
        var lifted = context
        lifted.addFilter(.shadow(color: BoothPaint.wine.opacity(0.3), radius: 2, x: 0, y: 1.5))
        lifted.fill(round(r, radius), with: vertical([stop(Color.white, 0), stop(Color(red: 0.992, green: 0.918, blue: 0.953), 1)], r))
        context.stroke(round(r.insetBy(dx: 2.5, dy: 2.5), radius - 2.5), with: .color(BoothPaint.lace.color().opacity(0.7)), style: StrokeStyle(lineWidth: 1.2, dash: [3, 2.5]))
    }
    /// The sticker outlet's white plate, its stitched edge.
    static func outletPlate(_ context: GraphicsContext, _ r: CGRect, radius: CGFloat = 14) {
        guard r.width > 20, r.height > 20 else { return }
        var lifted = context
        lifted.addFilter(.shadow(color: BoothPaint.wine.opacity(0.36), radius: 2.5, x: 0, y: 2))
        lifted.fill(round(r, radius), with: vertical([stop(Color.white, 0), stop(Color(red: 0.973, green: 0.890, blue: 0.933), 1)], r))
        context.stroke(round(r.insetBy(dx: 2.5, dy: 2.5), radius - 2.5), with: .color(BoothPaint.lace.color().opacity(0.7)), style: StrokeStyle(lineWidth: 1.2, dash: [3, 2.5]))
    }
    /// The outlet the sheet hangs from in 相册: its plate, two arrows pointing
    /// down (the album's glyph between them: BoothAlbum), its dark mouth.
    static func sheetOutlet(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 60, r.height > 30 else { return }
        outletPlate(context, r)
        let line = r.minY + 13
        for side in [CGFloat(-1), 1] {
            context.fill(ClamArrow(way: 2).path(in: CGRect(x: r.midX + side * 26 - 4.5, y: line - 3.5, width: 9, height: 7)), with: .color(BoothPaint.ink))
        }
        context.fill(round(mouth(r), 5), with: .color(BoothPaint.mouth))
    }
    /// The mouth of 相册's outlet.
    static func mouth(_ outlet: CGRect) -> CGRect {
        CGRect(x: outlet.minX + 16, y: outlet.minY + 22, width: max(0, outlet.width - 32), height: 10)
    }
    /// The door of bright metal 换机型's key is in.
    static func door(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 20, r.height > 20 else { return }
        let shape = round(r, 12)
        var lifted = context
        lifted.addFilter(.shadow(color: Color(red: 0.314, green: 0.039, blue: 0.196).opacity(0.4), radius: 2.5, x: 0, y: 2))
        lifted.fill(shape, with: .linearGradient(ClamPaint.chrome, startPoint: r.origin, endPoint: CGPoint(x: r.maxX, y: r.maxY)))
        var inner = context
        inner.clip(to: shape)
        DigiMetal.brush(inner, r, 0.05, seed: 0x0B0D_00C5)
        context.stroke(round(r.insetBy(dx: 0.7, dy: 0.7), 11.3), with: .color(Color.white.opacity(0.85)), lineWidth: 1)
    }
    /// The hood round the phone's own camera: white, a pink rim, a ring of
    /// small lamps (the booth's lights round its lens).
    static func hood(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 10, r.height > 10 else { return }
        let radius = min(r.width, r.height) / 2
        var lifted = context
        lifted.addFilter(.shadow(color: BoothPaint.wine.opacity(0.4), radius: 3, x: 0, y: 2))
        lifted.fill(round(r, radius), with: .linearGradient(Gradient(colors: [Color.white, Color(red: 0.945, green: 0.824, blue: 0.878)]), startPoint: r.origin, endPoint: CGPoint(x: r.maxX, y: r.maxY)))
        context.stroke(round(r.insetBy(dx: 2.2, dy: 2.2), radius - 2.2), with: .color(BoothPaint.lace.color().opacity(0.8)), lineWidth: 1.3)
        var lamps = Path()
        for p in hoodLamps(r) { lamps.addPath(disc(p, 1.25)) }
        var glow = context
        glow.addFilter(.shadow(color: Color(red: 1, green: 0.941, blue: 0.784).opacity(0.95), radius: 1.5))
        glow.fill(lamps, with: .color(Color(red: 1, green: 0.984, blue: 0.910)))
    }
    static func hoodLamps(_ r: CGRect) -> [CGPoint] {
        let k = max(0, min(r.width, r.height) / 2 - 4.6)
        return walk(r.insetBy(dx: 4.6, dy: 4.6), [k, k, k, k], step: 7.4)
    }
    /// The booth's curtain down the grip's side: pink and white stripes in
    /// soft folds, gathered at a ribbon with a bow, a scalloped top on its
    /// rod, a lace hem.
    static func curtain(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 20, r.height > 60 else { return }
        let x = r.minX, w = r.width, bend: CGFloat = 0.55, m = r.width * 0.2, top = r.minY + 9, run = r.height - 9
        func inset(_ t: CGFloat) -> CGFloat {
            if t <= bend { return m * CGFloat(pow(sin(Double.pi / 2 * Double(t / bend)), 1.3)) }
            return m * (1 - 0.8 * CGFloat(pow(Double((t - bend) / (1 - bend)), 0.85)))
        }
        func at(_ u: CGFloat, _ t: CGFloat) -> CGPoint {
            let left = x + inset(t), right = x + w - inset(t)
            return CGPoint(x: left + (right - left) * u, y: top + run * t)
        }
        let steps = 30, folds = 7
        func edge(_ u: CGFloat, down: Bool) -> [CGPoint] {
            let ks: [Int] = down ? Array(0...steps) : Array((0...steps).reversed())
            return ks.map { at(u, CGFloat($0) / CGFloat(steps)) }
        }
        var shadow = Path()
        shadow.addLines(edge(0, down: true).map { CGPoint(x: $0.x - 1, y: $0.y + 2.5) } + edge(1, down: false).map { CGPoint(x: $0.x + 1, y: $0.y + 2.5) })
        shadow.closeSubpath()
        context.fill(shadow, with: .color(BoothPaint.wine.opacity(0.25)))
        for i in 0..<folds {
            var stripe = Path()
            stripe.addLines(edge(CGFloat(i) / CGFloat(folds), down: true) + edge(CGFloat(i + 1) / CGFloat(folds), down: false))
            stripe.closeSubpath()
            context.fill(stripe, with: .color(i % 2 == 1 ? Color.white : BoothPaint.stripe.color()))
        }
        for i in 1..<(folds * 2) {
            var crease = Path()
            crease.addLines(edge(CGFloat(i) / CGFloat(folds * 2), down: true))
            if i % 2 == 1 {
                context.stroke(crease, with: .color(Color.white.opacity(0.45)), lineWidth: 1.6)
            } else {
                context.stroke(crease, with: .color(Color(red: 0.471, green: 0.078, blue: 0.275).opacity(0.16)), lineWidth: 2.2)
            }
        }
        for i in 0..<max(0, Int((w / 8).rounded())) {
            context.fill(scallop(CGPoint(x: x + 4 + CGFloat(i) * 8, y: top + 1), 4), with: .color(i % 2 == 1 ? Color.white : BoothPaint.stripe.color()))
        }
        rod(context, CGRect(x: x - 3, y: r.minY + 2, width: w + 6, height: 8), ends: [x - 1, x + w + 1], knob: 4.6)
        var u: CGFloat = 0.5 / 9
        while u < 1 {
            let hem = scallop(at(u, 1), 3.4)
            context.fill(hem, with: .color(Color.white))
            context.stroke(hem, with: .color(BoothPaint.lace.color().opacity(0.6)), lineWidth: 0.8)
            u += 1.0 / 9
        }
        bow(context, left: at(0, bend).x - 2, right: at(1, bend).x + 2, y: top + run * bend)
    }
    /// A curtain's rod and the knobs at its ends.
    static func rod(_ context: GraphicsContext, _ r: CGRect, ends: [CGFloat], knob: CGFloat) {
        let pole = round(r, 4)
        context.fill(pole, with: vertical([stop(Color.white, 0), stop(Color(red: 0.910, green: 0.761, blue: 0.827), 0.5), stop(Color(red: 0.784, green: 0.584, blue: 0.671), 1)], r))
        context.stroke(pole, with: .color(BoothPaint.wine.opacity(0.35)), lineWidth: 0.8)
        for end in ends {
            let c = CGPoint(x: end, y: r.midY)
            context.fill(disc(c, knob), with: .radialGradient(Gradient(colors: [Color.white, BoothPaint.lace.color()]), center: CGPoint(x: c.x - 1.4, y: c.y - 1.4), startRadius: 0.3, endRadius: knob + 0.8))
        }
    }
    /// The ribbon round the gathered curtain, and its bow.
    static func bow(_ context: GraphicsContext, left: CGFloat, right: CGFloat, y: CGFloat) {
        let ribbon = CGRect(x: left, y: y - 3.5, width: max(0, right - left), height: 7), bx = (left + right) / 2
        context.fill(round(ribbon, 3.5), with: vertical([stop(Color(red: 1, green: 0.898, blue: 0.541), 0), stop(Color(red: 0.949, green: 0.722, blue: 0.110), 1)], ribbon))
        let edge = Color(red: 0.627, green: 0.392, blue: 0)
        for side in [CGFloat(-1), 1] {
            let turn = CGAffineTransform(rotationAngle: side * -0.2).concatenating(CGAffineTransform(translationX: bx, y: y))
            let loop = Path(ellipseIn: CGRect(x: side * 9.5 - 9.5, y: -8, width: 19, height: 12)).applying(turn)
            let gold = Gradient(colors: [Color(red: 1, green: 0.914, blue: 0.561), Color(red: 0.941, green: 0.702, blue: 0.102)])
            context.fill(loop, with: .linearGradient(gold, startPoint: CGPoint(x: bx, y: y - 8), endPoint: CGPoint(x: bx, y: y + 4)))
            context.stroke(loop, with: .color(edge.opacity(0.45)), lineWidth: 0.8)
            var tail = Path()
            tail.addLines([CGPoint(x: bx + side * 2, y: y + 2), CGPoint(x: bx + side * 9, y: y + 17), CGPoint(x: bx + side * 4, y: y + 15), CGPoint(x: bx + side, y: y + 18)])
            tail.closeSubpath()
            context.fill(tail, with: .color(Color(red: 0.957, green: 0.741, blue: 0.133)))
        }
        let knot = disc(CGPoint(x: bx, y: y - 1), 3.6)
        context.fill(knot, with: .color(Color(red: 1, green: 0.847, blue: 0.290)))
        context.stroke(knot, with: .color(edge.opacity(0.5)), lineWidth: 0.8)
    }
    /// Held across: the curtain along the top where the system's control
    /// comes in — hung from a rod, pleats, a wavy lace hem.
    static func curtainTop(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 40, r.height > 20 else { return }
        let x = r.minX, y = r.minY, w = r.width, bottom = r.maxY
        let n = max(2, Int((w / 13).rounded())), sw = w / CGFloat(n)
        func wave(_ k: CGFloat) -> CGFloat { CGFloat(sin(Double(k) * Double.pi * 2 / 26)) * 2.2 }
        var shadow = Path()
        shadow.move(to: CGPoint(x: x, y: y + 8))
        shadow.addLine(to: CGPoint(x: x + w, y: y + 8))
        var k: CGFloat = 0
        while k <= w {
            shadow.addLine(to: CGPoint(x: x + w - k, y: bottom + wave(w - k) + 2.5))
            k += 2
        }
        shadow.closeSubpath()
        context.fill(shadow, with: .color(BoothPaint.wine.opacity(0.25)))
        for i in 0..<n {
            let left = x + CGFloat(i) * sw
            let c = i % 2 == 1 ? BoothPaint.white : BoothPaint.stripe
            var pleat = Path()
            pleat.move(to: CGPoint(x: left, y: y + 8))
            pleat.addLine(to: CGPoint(x: left + sw, y: y + 8))
            var j = sw
            while j >= 0 {
                pleat.addLine(to: CGPoint(x: left + j, y: bottom + wave(CGFloat(i) * sw + j)))
                j -= 1
            }
            pleat.closeSubpath()
            let cloth = Gradient(stops: [stop(c.color(-0.1), 0), stop(c.color(0.3), 0.5), stop(c.color(-0.13), 1)])
            context.fill(pleat, with: .linearGradient(cloth, startPoint: CGPoint(x: left, y: 0), endPoint: CGPoint(x: left + sw, y: 0)))
        }
        var along: CGFloat = 3
        while along < w {
            let hem = scallop(CGPoint(x: x + along, y: bottom + wave(along)), 3.2)
            context.fill(hem, with: .color(Color.white))
            context.stroke(hem, with: .color(BoothPaint.lace.color().opacity(0.55)), lineWidth: 0.8)
            along += 7
        }
        rod(context, CGRect(x: x - 4, y: y + 2, width: w + 8, height: 8), ends: [x - 2, x + w + 2], knob: 4.8)
    }
    /// The lace trim along the foot: a white line, scallops under it.
    static func foot(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 20 else { return }
        var scallops = Path()
        var x = r.minX + 4
        while x < r.maxX - 2 {
            scallops.addPath(scallop(CGPoint(x: x, y: r.minY + 2), 3))
            x += 8
        }
        context.fill(scallops, with: .color(Color.white.opacity(0.8)))
        context.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 2)), with: .color(Color.white.opacity(0.85)))
    }

    /// What a key that waits is made of: its colour gone most of the way to grey.
    static let grey = ShellTone(r: 0.784, g: 0.745, b: 0.769)
    static func mix(_ a: ShellTone, _ b: ShellTone, _ k: Double) -> ShellTone {
        ShellTone(r: a.r + (b.r - a.r) * k, g: a.g + (b.g - a.g) * k, b: a.b + (b.b - a.b) * k)
    }

    /// A candy key's white collar round `cap`: its shadow on the body, the
    /// collar, the dark gap round the cap.
    static func collar(_ context: GraphicsContext, _ cap: CGRect, radius r: CGFloat) {
        let outer = cap.insetBy(dx: -3, dy: -3)
        let drop = CGRect(x: outer.minX, y: outer.minY, width: outer.width, height: outer.height + 1)
        context.fill(round(drop, r + 3), with: .color(Color(red: 0.392, green: 0.039, blue: 0.235).opacity(0.28)))
        context.fill(round(outer, r + 3), with: vertical([stop(Color.white, 0), stop(Color(red: 0.918, green: 0.816, blue: 0.863), 1)], outer))
        context.fill(round(cap.insetBy(dx: -0.9, dy: -0.9), r + 0.9), with: .color(Color(red: 0.275, green: 0.039, blue: 0.176).opacity(0.5)))
    }
    /// A candy key's cap: the plastic lit from above, its shine (dimmer
    /// while it is down), its light rim.
    static func cap(_ context: GraphicsContext, _ rect: CGRect, radius r: CGFloat, tone: ShellTone, pressed: Bool) {
        let shape = round(rect, r)
        context.fill(shape, with: vertical([stop(tone.color(0.5), 0), stop(tone.color(), 0.45), stop(tone.color(-0.18), 1)], rect))
        var gloss = context
        gloss.clip(to: shape)
        let top = CGRect(x: rect.minX + 2, y: rect.minY + 1.5, width: max(0, rect.width - 4), height: rect.height * 0.45)
        let shine = Gradient(colors: [Color.white.opacity(pressed ? 0.28 : 0.55), Color.white.opacity(0)])
        gloss.fill(Path(top), with: .linearGradient(shine, startPoint: CGPoint(x: 0, y: rect.minY), endPoint: CGPoint(x: 0, y: rect.minY + rect.height * 0.5)))
        context.stroke(round(rect.insetBy(dx: 0.8, dy: 0.8), max(1, r - 0.8)), with: .color(Color.white.opacity(0.6)), lineWidth: 1)
    }
    /// A bat-handle toggle in its chrome nut, round `c`; the lever's ball
    /// `tip` above (−) or below (+) the middle.
    static func toggle(_ context: GraphicsContext, at c: CGPoint, tip: CGFloat) {
        let nut = CGRect(x: c.x - 8.5, y: c.y - 13, width: 17, height: 26)
        let plate = round(nut, 8.5)
        context.fill(plate, with: vertical([stop(Color(red: 0.235, green: 0.102, blue: 0.184), 0), stop(Color(red: 0.416, green: 0.212, blue: 0.333), 1)], nut))
        context.stroke(plate, with: .color(Color.white.opacity(0.6)), lineWidth: 0.8)
        var hex = Path()
        for i in 0..<6 {
            let a = Double(i) * Double.pi / 3 + Double.pi / 6
            let p = CGPoint(x: c.x + CGFloat(cos(a)) * 6, y: c.y + CGFloat(sin(a)) * 6)
            if i == 0 { hex.move(to: p) } else { hex.addLine(to: p) }
        }
        hex.closeSubpath()
        let steel = Gradient(stops: [stop(Color.white, 0), stop(Color(red: 0.718, green: 0.737, blue: 0.773), 0.5), stop(Color(red: 0.925, green: 0.933, blue: 0.945), 1)])
        context.fill(hex, with: .linearGradient(steel, startPoint: CGPoint(x: c.x - 6, y: c.y - 6), endPoint: CGPoint(x: c.x + 6, y: c.y + 6)))
        context.stroke(hex, with: .color(Color.black.opacity(0.35)), lineWidth: 0.6)
        let end = CGPoint(x: c.x, y: c.y + tip)
        var lever = Path()
        lever.move(to: c)
        lever.addLine(to: end)
        let rod = Gradient(stops: [stop(Color(red: 0.553, green: 0.576, blue: 0.612), 0), stop(Color.white, 0.5), stop(Color(red: 0.525, green: 0.549, blue: 0.584), 1)])
        context.stroke(lever, with: .linearGradient(rod, startPoint: CGPoint(x: c.x - 2.5, y: 0), endPoint: CGPoint(x: c.x + 2.5, y: 0)),
                       style: StrokeStyle(lineWidth: 3.6, lineCap: .round))
        let ball = disc(end, 3.2)
        context.fill(ball, with: .radialGradient(Gradient(colors: [Color.white, Color(red: 0.561, green: 0.588, blue: 0.627)]),
                                                 center: CGPoint(x: end.x - 1, y: end.y - 1.1), startRadius: 0.3, endRadius: 4))
        context.stroke(ball, with: .color(Color.black.opacity(0.3)), lineWidth: 0.5)
    }
    /// A small dark window round `c`, 16 high (what it says is drawn in it,
    /// or a glyph is set over it: BoothLampGlyph).
    static func lampWindow(_ context: GraphicsContext, center c: CGPoint, width w: CGFloat) {
        let box = CGRect(x: c.x - w / 2, y: c.y - 8, width: w, height: 16)
        context.fill(round(box, 5), with: .color(BoothPaint.window))
        context.stroke(round(box, 5), with: .color(Color(red: 0.157, green: 0, blue: 0.086).opacity(0.7)), lineWidth: 0.8)
        context.fill(Path(CGRect(x: box.minX + 4, y: box.maxY + 0.2, width: max(0, w - 8), height: 0.8)), with: .color(Color.white.opacity(0.6)))
    }
    /// A small dark window round `c` with how a part stands in words: lit
    /// when on (or when it says a value), dim when off.
    static func lamp(_ context: GraphicsContext, center c: CGPoint, width w: CGFloat, words: String, on: Bool) {
        lampWindow(context, center: c, width: w)
        let size = fit(words.count > 2 ? 10 : 10.5, words, w)
        let ink = on ? Color(red: 1, green: 0.902, blue: 0.949) : Color(red: 1, green: 0.839, blue: 0.918).opacity(0.66)
        var lit = context
        if on { lit.addFilter(.shadow(color: BoothPaint.pink.color(), radius: 2.5)) }
        lit.draw(Text(words).font(.system(size: size, weight: .black, design: .rounded)).foregroundColor(ink), at: CGPoint(x: c.x, y: c.y + 0.5))
    }
    /// A size for `words` to go across `room` at (a wide letter an em, a
    /// figure or a Latin letter some 0.62 of one), never over `size`.
    static func fit(_ size: CGFloat, _ words: String, _ room: CGFloat) -> CGFloat {
        let ems = words.unicodeScalars.reduce(CGFloat(0)) { $0 + ($1.value > 0x2E80 ? 1 : 0.62) }
        return ems > 0 ? min(size, max(1, room - 4) / ems) : size
    }

    // The countdown lamps' window: its small lamps, their glow, the grid over them.
    static func ledDots(_ context: GraphicsContext, _ w: CGRect) {
        var lamps = Path()
        var y = w.minY + 1.5
        while y < w.maxY {
            var x = w.minX + 1.5
            while x < w.maxX {
                lamps.addRect(CGRect(x: x, y: y, width: 1.8, height: 1.8))
                x += 3
            }
            y += 3
        }
        context.fill(lamps, with: .color(Color(red: 1, green: 0.471, blue: 0.314).opacity(0.08)))
    }
    static func ledGrid(_ context: GraphicsContext, _ w: CGRect, _ amount: Double) {
        var grid = Path()
        var x = w.minX
        while x < w.maxX {
            grid.addRect(CGRect(x: x, y: w.minY, width: 0.8, height: w.height))
            x += 3
        }
        var y = w.minY
        while y < w.maxY {
            grid.addRect(CGRect(x: w.minX, y: y, width: w.width, height: 0.8))
            y += 3
        }
        context.fill(grid, with: .color(Color(red: 0.114, green: 0.047, blue: 0.086).opacity(amount)))
    }
    /// Words in the lamps: hot in the middle, glowing orange round them.
    static func led(_ context: GraphicsContext, _ words: String, at p: CGPoint, size: CGFloat) {
        let text = Text(words).font(.system(size: size, weight: .black, design: .rounded)).foregroundColor(BoothPaint.ledHot)
        var glow = context
        glow.addFilter(.shadow(color: BoothPaint.led, radius: max(2.5, size * 0.11)))
        glow.draw(text, at: p)
        var near = context
        near.addFilter(.shadow(color: BoothPaint.led, radius: 1))
        near.draw(text, at: p)
    }
    /// A glyph in the lamps (one of the Canvas's symbols, drawn in the hot
    /// ink): glowing orange round it, as the words do.
    static func ledMark(_ context: GraphicsContext, _ mark: GraphicsContext.ResolvedSymbol?, at p: CGPoint, size: CGFloat) {
        guard let mark else { return }
        var glow = context
        glow.addFilter(.shadow(color: BoothPaint.led, radius: max(2.5, size * 0.11)))
        glow.draw(mark, at: p, anchor: .center)
        var near = context
        near.addFilter(.shadow(color: BoothPaint.led, radius: 1))
        near.draw(mark, at: p, anchor: .center)
    }

    // MARK: the thumbnails' pictures

    /// A small picture to show a lens or a body by: a sky, the sun, the
    /// hills, two people in front of them.
    static func scene(_ context: GraphicsContext, _ r: CGRect) {
        context.fill(Path(r), with: vertical([stop(Color(red: 0.62, green: 0.78, blue: 0.93), 0), stop(Color(red: 0.98, green: 0.90, blue: 0.82), 0.62)], r))
        context.fill(disc(CGPoint(x: r.minX + r.width * 0.76, y: r.minY + r.height * 0.26), r.height * 0.12), with: .color(Color(red: 1, green: 0.88, blue: 0.55)))
        var hills = Path()
        hills.move(to: CGPoint(x: r.minX, y: r.maxY))
        hills.addLine(to: CGPoint(x: r.minX, y: r.minY + r.height * 0.66))
        hills.addQuadCurve(to: CGPoint(x: r.minX + r.width * 0.55, y: r.minY + r.height * 0.7), control: CGPoint(x: r.minX + r.width * 0.25, y: r.minY + r.height * 0.48))
        hills.addQuadCurve(to: CGPoint(x: r.maxX, y: r.minY + r.height * 0.62), control: CGPoint(x: r.minX + r.width * 0.8, y: r.minY + r.height * 0.5))
        hills.addLine(to: CGPoint(x: r.maxX, y: r.maxY))
        hills.closeSubpath()
        context.fill(hills, with: .color(Color(red: 0.55, green: 0.70, blue: 0.50)))
        let people: [(CGFloat, Color)] = [(0.38, Color(red: 0.93, green: 0.45, blue: 0.55)), (0.6, Color(red: 0.42, green: 0.55, blue: 0.85))]
        for person in people {
            let x = r.minX + r.width * person.0, h = r.height
            context.fill(round(CGRect(x: x - h * 0.1, y: r.minY + h * 0.66, width: h * 0.2, height: h * 0.4), h * 0.08), with: .color(person.1))
            context.fill(disc(CGPoint(x: x, y: r.minY + h * 0.56), h * 0.085), with: .color(Color(red: 0.98, green: 0.84, blue: 0.72)))
        }
    }
    /// What a lens does to the small picture.
    static func lensMark(_ context: GraphicsContext, _ lens: CameraLens, _ r: CGRect) {
        switch lens {
        case .normal, .merge:
            break
        case .sparkle:
            context.fill(Path(r), with: .color(Color(red: 1, green: 0.925, blue: 0.667).opacity(0.18)))
            let at: [(CGFloat, CGFloat, CGFloat)] = [(0.18, 0.24, 4.4), (0.84, 0.3, 3.4), (0.72, 0.78, 4.8), (0.24, 0.8, 2.8)]
            for q in at {
                stick(context, star(q.2, spark: true), at: CGPoint(x: r.minX + r.width * q.0, y: r.minY + r.height * q.1), size: q.2, colour: ShellTone(r: 1, g: 0.941, b: 0.549))
            }
        case .dream:
            context.fill(Path(r), with: .color(Color(red: 1, green: 0.902, blue: 0.988).opacity(0.52)))
            cloud(context, at: CGPoint(x: r.minX + r.width * 0.22, y: r.minY + r.height * 0.8), size: 5.5)
            cloud(context, at: CGPoint(x: r.minX + r.width * 0.8, y: r.minY + r.height * 0.22), size: 4.5)
        case .lowLight:
            context.fill(Path(r), with: .color(Color(red: 0.047, green: 0.063, blue: 0.188).opacity(0.62)))
            moon(context, at: CGPoint(x: r.minX + r.width * 0.78, y: r.minY + r.height * 0.3), radius: 4.6)
            let at: [(CGFloat, CGFloat)] = [(0.2, 0.25), (0.4, 0.15), (0.3, 0.45)]
            for q in at {
                stick(context, star(2, spark: true), at: CGPoint(x: r.minX + r.width * q.0, y: r.minY + r.height * q.1), size: 2, colour: BoothPaint.white)
            }
        case .pinhole:
            let dark = Gradient(colors: [Color.black.opacity(0), Color.black.opacity(0.75)])
            context.fill(Path(r), with: .radialGradient(dark, center: CGPoint(x: r.midX, y: r.midY), startRadius: min(r.width, r.height) * 0.25,
                                                        endRadius: max(r.width, r.height) * 0.62))
        case .mystery:
            let wash = Gradient(colors: [Color(red: 0.6, green: 0.3, blue: 0.9).opacity(0.45), Color(red: 0.1, green: 0.8, blue: 0.7).opacity(0.45)])
            context.fill(Path(r), with: .linearGradient(wash, startPoint: r.origin, endPoint: CGPoint(x: r.maxX, y: r.maxY)))
        case .pair:
            context.fill(Path(CGRect(x: r.midX - 1, y: r.minY, width: 2, height: r.height)), with: .color(Color.white))
        case .quad:
            context.fill(Path(CGRect(x: r.midX - 1, y: r.minY, width: 2, height: r.height)), with: .color(Color.white))
            context.fill(Path(CGRect(x: r.minX, y: r.midY - 1, width: r.width, height: 2)), with: .color(Color.white))
        }
    }
    /// The small picture as a body pinned among the lenses makes it: an
    /// instant print's paper round it, the toy camera's two-coloured frame,
    /// else the body's own two colours round it and over it.
    static func bodyMark(_ context: GraphicsContext, _ body: CameraBody, _ r: CGRect) {
        switch body.shell {
        case .instant:
            context.fill(Path(r), with: .color(Color(red: 0.984, green: 0.961, blue: 0.902)))
            scene(context, CGRect(x: r.minX + 3, y: r.minY + 3, width: max(0, r.width - 6), height: max(0, r.height - 9)))
        case .toy:
            context.fill(Path(r), with: .color(Color(red: 0.22, green: 0.69, blue: 0.894)))
            context.fill(round(r.insetBy(dx: 2, dy: 2), 4), with: .color(Color(red: 0.98, green: 0.816, blue: 0.188)))
            var inner = context
            inner.clip(to: round(r.insetBy(dx: 5, dy: 5), 3))
            scene(inner, r.insetBy(dx: 5, dy: 5))
        default:
            let swatch = body.swatch
            context.fill(Path(r), with: .color(swatch.0))
            let inner = r.insetBy(dx: 3, dy: 3)
            scene(context, inner)
            context.fill(Path(inner), with: .color(swatch.1.opacity(0.28)))
        }
    }
    /// A small white cloud (each puff filled on its own: they overlap).
    static func cloud(_ context: GraphicsContext, at c: CGPoint, size s: CGFloat) {
        let puffs: [(CGFloat, CGFloat, CGFloat)] = [(-0.6, 0.15, 0.5), (0, -0.2, 0.68), (0.62, 0.12, 0.48)]
        for q in puffs { context.fill(disc(CGPoint(x: c.x + q.0 * s, y: c.y + q.1 * s), q.2 * s), with: .color(Color.white)) }
        context.fill(round(CGRect(x: c.x - s * 0.95, y: c.y + s * 0.05, width: s * 1.9, height: s * 0.55), s * 0.27), with: .color(Color.white))
    }
    /// A crescent moon.
    static func moon(_ context: GraphicsContext, at c: CGPoint, radius r: CGFloat) {
        var lit = context
        lit.clip(to: disc(c, r))
        var shape = Path(CGRect(x: c.x - r - 1, y: c.y - r - 1, width: 2 * r + 2, height: 2 * r + 2))
        shape.addPath(disc(CGPoint(x: c.x + r * 0.48, y: c.y - r * 0.32), r * 0.86))
        lit.fill(shape, with: .color(Color(red: 1, green: 0.898, blue: 0.541)), style: FillStyle(eoFill: true))
    }
}

/// The booth's body under its keys, drawn as the pictures of it were
/// (mock/bt7.js, part for part): the candy plastic, the sign with its
/// bulbs (lit by BoothSignLights over them), the hood round the camera, the
/// enamel plate, the outlet's plate, the door of bright metal, the curtain
/// where the Camera Control's overlay comes in, the lace trim. In 相册 the
/// outlet across the top in place of the plate and the door. (The screen's
/// frame lies over the picture's edge: BoothScreenFrame.) Drawn once.
private struct BoothBackdrop: View, Equatable {
    var layout: BoothLayout
    var hinge: CGRect
    var album: Bool
    var body: some View {
        Canvas { context, size in
            BoothArt.body(context, size, hinge)
            BoothArt.sign(context, layout)
            BoothArt.hood(context, layout.hood)
            if album {
                BoothArt.sheetOutlet(context, layout.sheetOutlet)
            } else {
                BoothArt.plate(context, layout.plate, radius: layout.plateRadius)
                BoothArt.outletPlate(context, layout.outlet, radius: layout.across ? 12 : 14)
                BoothArt.door(context, layout.door)
            }
            if layout.across { BoothArt.curtainTop(context, layout.curtain) } else { BoothArt.curtain(context, layout.curtain) }
            if layout.foot.width > 0, layout.foot.maxY <= size.height - 1 { BoothArt.foot(context, layout.foot) }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The screen round the picture: the white moulded frame, the pink lace
/// hugging the picture (over its own bezel), the awning over the frame's
/// top, the hearts, stars, bubbles and flower printed or stuck on the frame.
/// Nothing of it is drawn on the picture: it is all kept outside the
/// picture's own rounded edge. Drawn again only when the picture's shape changes.
private struct BoothScreenFrame: View, Equatable {
    var surround: CGRect
    var box: CGRect
    var picture: CGRect
    var valance: CGRect
    var top: CGFloat
    var body: some View {
        Canvas { context, size in
            guard surround.width > 40, surround.height > 40 else { return }
            let hole = picture.width > 12 && picture.height > 12 ? picture : box
            var keep = Path(CGRect(origin: .zero, size: size))
            keep.addPath(Path(roundedRect: hole, cornerRadius: 5, style: .continuous))
            var outside = context
            outside.clip(to: keep, style: FillStyle(eoFill: true))
            BoothArt.frame(outside, surround)
            BoothArt.lace(outside, hole)
            BoothArt.valance(outside, valance)
            BoothArt.decorations(outside, frame: surround, box: box, top: top)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The sign's bulbs lit: all of them, or every other one (`chase`, while
/// it counts down); `burst`, all of them white for the moment a picture is taken.
private struct BoothBulbs: View, Equatable {
    var layout: BoothLayout
    var chase: Int?
    var burst = false
    var body: some View {
        Canvas { context, _ in
            let points = BoothArt.bulbs(layout)
            guard !points.isEmpty else { return }
            if burst {
                var all = Path()
                for p in points { all.addPath(BoothArt.disc(p, 3.2)) }
                var glow = context
                glow.addFilter(.shadow(color: Color.white, radius: 5))
                glow.fill(all, with: .color(Color.white))
                return
            }
            var lit: [CGPoint] = []
            for (i, p) in points.enumerated() where chase == nil || i % 2 == chase { lit.append(p) }
            BoothArt.litBulbs(context, lit)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The sign's lights: steady while taking pictures; every other bulb by
/// turns while the self-timer counts (a step a second); all of them flash
/// once as a picture is taken. With 减弱动态效果 they stay steady.
private struct BoothSignLights: View {
    var layout: BoothLayout
    var countdown: Int?
    var flash: Int
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var burst = false
    var body: some View {
        let chase: Int? = reduceMotion ? nil : countdown.map { $0 % 2 }
        ZStack {
            BoothBulbs(layout: layout, chase: chase).equatable()
            BoothBulbs(layout: layout, chase: nil, burst: true).equatable()
                .opacity(burst ? 1 : 0)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
        .onChange(of: flash) { _, _ in
            guard !reduceMotion else { return }
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) { burst = true }
            Task { @MainActor in
                try? await Task.sleep(nanoseconds: 90_000_000)
                withAnimation(.easeOut(duration: 0.45)) { burst = false }
            }
        }
    }
}

/// The hood's ring of lamps, as a mask.
private struct BoothHoodDots: View, Equatable {
    var size: CGSize
    var body: some View {
        Canvas { context, _ in
            var lamps = Path()
            for p in BoothArt.hoodLamps(CGRect(origin: .zero, size: size)) { lamps.addPath(BoothArt.disc(p, 2.2)) }
            context.fill(lamps, with: .color(Color.white))
        }
    }
}

/// 内 / 外: a light runs once round the hood's lamps as the other camera
/// comes (not with 减弱动态效果).
private struct BoothHoodSweep: View {
    var size: CGSize
    var side: CameraSide
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var turn = 0.0
    @State private var shown = false
    var body: some View {
        let d = hypot(size.width, size.height)
        let warm = Color(red: 1, green: 0.96, blue: 0.8)
        AngularGradient(gradient: Gradient(colors: [warm.opacity(0), warm.opacity(0), warm, warm.opacity(0)]), center: .center, angle: .zero)
            .frame(width: d, height: d)
            .rotationEffect(.degrees(turn))
            .frame(width: size.width, height: size.height)
            .mask { BoothHoodDots(size: size).equatable() }
            .opacity(shown ? 1 : 0)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
            .onChange(of: side) { _, _ in
                guard !reduceMotion else { return }
                shown = true
                withAnimation(.easeInOut(duration: 0.7)) { turn += 360 }
                Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 700_000_000)
                    withAnimation(.easeOut(duration: 0.2)) { shown = false }
                }
            }
    }
}

// MARK: the booth's keys

/// The glow round a lit key, behind it.
private struct BoothHalo: View, Equatable {
    var tone: ShellTone
    var radius: CGFloat
    var strength: Double
    var body: some View {
        let reach = radius + 22
        Circle()
            .fill(RadialGradient(colors: [tone.color(0.3).opacity(min(1, 0.5 * strength)), tone.color().opacity(0)], center: .center,
                                 startRadius: radius + 4, endRadius: reach))
            .frame(width: 2 * reach, height: 2 * reach)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

/// The white collar a lit key sits in and the dark gap round its dome: it
/// stays put while the dome goes down.
private struct BoothCollar: View, Equatable {
    var radius: CGFloat
    var body: some View {
        let outer = 2 * (radius + 6)
        let white = LinearGradient(stops: [Gradient.Stop(color: Color.white, location: 0),
                                           Gradient.Stop(color: Color(red: 0.969, green: 0.910, blue: 0.937), location: 0.55),
                                           Gradient.Stop(color: Color(red: 0.863, green: 0.722, blue: 0.788), location: 1)],
                                   startPoint: .top, endPoint: .bottom)
        ZStack {
            Circle().fill(Color(red: 0.392, green: 0.039, blue: 0.235).opacity(0.32)).frame(width: outer, height: outer).offset(y: 2)
            Circle().fill(white).frame(width: outer, height: outer)
            Circle().strokeBorder(Color.white.opacity(0.9), lineWidth: 1).frame(width: outer - 0.2, height: outer - 0.2)
            Circle().fill(Color(red: 0.275, green: 0.039, blue: 0.176).opacity(0.65)).frame(width: 2 * (radius + 1.6), height: 2 * (radius + 1.6))
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A lit key's dome: the light inside it and its glow, its rim, the shine
/// on its top; brighter while it is down; greyed and unlit while it waits.
private struct BoothDome: View, Equatable {
    var tone: ShellTone
    var radius: CGFloat
    var off = false
    var pressed = false
    var body: some View {
        let reach = radius + 9
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            let face = off ? BoothArt.mix(tone, BoothArt.grey, 0.55) : tone
            let ball = BoothArt.disc(c, r)
            let stops: [Gradient.Stop] = off
                ? [BoothArt.stop(face.color(0.25), 0), BoothArt.stop(face.color(), 0.8), BoothArt.stop(face.color(-0.2), 1)]
                : [BoothArt.stop(tone.color(0.72), 0), BoothArt.stop(tone.color(0.25), 0.5), BoothArt.stop(tone.color(), 0.85), BoothArt.stop(tone.color(-0.22), 1)]
            var lit = context
            if !off { lit.addFilter(.shadow(color: tone.color(0.2).opacity(0.95), radius: 5)) }
            lit.fill(ball, with: .radialGradient(Gradient(stops: stops), center: CGPoint(x: c.x, y: c.y + r * 0.15), startRadius: r * 0.05, endRadius: r * 1.05))
            if pressed, !off { context.fill(ball, with: .color(Color.white.opacity(0.18))) }
            context.stroke(BoothArt.disc(c, r - 1), with: .color(face.color(0.55).opacity(0.8)), lineWidth: 1.4)
            let shine = CGRect(x: c.x - r * 0.6, y: c.y - r * 0.8, width: r * 1.2, height: r * 0.6)
            let gloss = Gradient(colors: [Color.white.opacity(pressed ? 0.5 : 0.72), Color.white.opacity(0)])
            context.fill(Path(ellipseIn: shine), with: .linearGradient(gloss, startPoint: CGPoint(x: 0, y: shine.minY), endPoint: CGPoint(x: 0, y: shine.maxY)))
        }
        .frame(width: 2 * reach, height: 2 * reach)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A big round key lit from inside (◀ ▶, 拍照): the dome goes down into its
/// collar, which stays put; it lights up more and its glow spreads while it
/// is down; it sounds and is felt as it goes down, not when it is let go.
/// (Drawn round the middle of its place; the place alone is touched.)
private struct BoothArcadeStyle: ButtonStyle {
    var tone: ShellTone
    var radius: CGFloat
    var halo: Double = 1
    var travel: CGFloat = 2.5
    var off = false
    /// Its light breathing slowly (a video being taken).
    var pulse = false
    var sound: ConsoleSound = .keyMetal
    var scale: Float = 0.8
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View {
        BoothArcadeBody(style: self, pressed: configuration.isPressed, label: AnyView(configuration.label))
    }
}

private struct BoothArcadeBody: View {
    var style: BoothArcadeStyle
    var pressed: Bool
    var label: AnyView
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let r = style.radius
        let glow = style.off ? 0 : style.halo * (pressed ? 1.35 : 1)
        let breathing = style.pulse && !style.off && !reduceMotion
        let sink: CGFloat = pressed ? style.travel : 0
        let ink = style.off ? BoothArt.mix(style.tone, BoothArt.grey, 0.55) : style.tone
        Color.clear
            .overlay {
                ZStack {
                    BoothCollar(radius: r).equatable()
                    BoothDome(tone: style.tone, radius: r, off: style.off, pressed: pressed).equatable()
                        .opacity(breathing ? 0.68 : 1)
                        .animation(breathing ? Animation.easeInOut(duration: 1.2).repeatForever(autoreverses: true) : .easeOut(duration: 0.2), value: breathing)
                        .offset(y: sink)
                    label
                        .foregroundStyle(Color.white.opacity(style.off ? 0.85 : 1))
                        .shadow(color: ink.color(-0.5).opacity(0.95), radius: 2)
                        .offset(y: sink)
                }
            }
            .background {
                if glow > 0 { BoothHalo(tone: style.tone, radius: r, strength: glow).equatable() }
            }
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: pressed ? 0.04 : 0.1), value: pressed)
            .onChange(of: pressed) { _, down in
                guard down else { return }
                ConsoleSounds.shared.play(style.sound, scale: style.scale)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// ◀ or ▶ on a lit key (its arrow alone: VoiceOver says which).
private struct BoothStepLabel: View {
    /// 1 ▶, 3 ◀ (ClamArrow's ways).
    var way: Int
    var radius: CGFloat
    var body: some View {
        let h = radius * 0.58
        ClamArrow(way: way).fill(Color.white)
            .frame(width: h * 0.86, height: h)
            .offset(x: way == 3 ? -1.5 : 1.5)
    }
}

/// 拍照's face: a camera; a white dot for a video, a stop square and the
/// time while one is taken; in 相册, a camera over 回去拍照 (its words kept).
private struct BoothShutterLabel: View {
    var video: Bool
    var recording: Bool
    var time: String
    var back: String? = nil
    var radius: CGFloat
    var body: some View {
        VStack(spacing: 2) {
            if let back {
                ShellGlyphLabel(glyph: .returnToShooting, words: back, size: radius * 0.6, wordSize: 10, ink: Color.white, stacked: true)
            } else if video, recording {
                RoundedRectangle(cornerRadius: 2.5, style: .continuous).fill(Color.white).frame(width: radius * 0.42, height: radius * 0.42)
                Text(time).font(.system(size: 10.5, weight: .heavy, design: .rounded)).monospacedDigit()
            } else if video {
                Circle().fill(Color.white).frame(width: radius * 0.52, height: radius * 0.52)
            } else {
                ShellGlyphView(glyph: .photo(true), size: radius * 0.8, ink: Color.white)
            }
        }
        .lineLimit(1)
        .minimumScaleFactor(0.7)
    }
}

/// A candy key's collar as shapes (its shadow falls outside it).
private struct BoothCandyCollar: View, Equatable {
    var radius: CGFloat
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: radius, style: .circular)
        ZStack {
            shape.fill(Color(red: 0.392, green: 0.039, blue: 0.235).opacity(0.28)).offset(y: 1)
            shape.fill(LinearGradient(colors: [Color.white, Color(red: 0.918, green: 0.816, blue: 0.863)], startPoint: .top, endPoint: .bottom))
            RoundedRectangle(cornerRadius: max(0, radius - 2.1), style: .circular)
                .fill(Color(red: 0.275, green: 0.039, blue: 0.176).opacity(0.5))
                .padding(2.1)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A candy key's cap, drawn.
private struct BoothCandyCap: View, Equatable {
    var tone: ShellTone
    var radius: CGFloat
    var pressed = false
    var body: some View {
        Canvas { context, size in
            BoothArt.cap(context, CGRect(origin: .zero, size: size), radius: radius, tone: tone, pressed: pressed)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A key of candy plastic in a white collar (主菜单, 内 / 外, 浓淡's − and
/// ＋, 回去拍照, 播放): the cap goes down into the collar and its shine
/// dims; a soft knock as it goes down. `inset`: where the collar is in the
/// key's place (the rest of the place is touched with it).
private struct BoothCandyStyle: ButtonStyle {
    var tone: ShellTone
    var radius: CGFloat
    var inset = EdgeInsets()
    var travel: CGFloat = 1.8
    var ink = Color.white
    var sound: ConsoleSound = .keyRubber
    var scale: Float = 0.8
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View {
        BoothCandyBody(style: self, pressed: configuration.isPressed, label: AnyView(configuration.label))
    }
}

private struct BoothCandyBody: View {
    var style: BoothCandyStyle
    var pressed: Bool
    var label: AnyView
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let sink: CGFloat = pressed ? style.travel : 0
        ZStack {
            BoothCandyCollar(radius: style.radius + 3).equatable()
            BoothCandyCap(tone: style.tone, radius: style.radius, pressed: pressed).equatable()
                .padding(3)
                .offset(y: sink)
            label
                .foregroundStyle(style.ink)
                .shadow(color: style.tone.color(-0.45).opacity(0.85), radius: 1.5)
                .padding(3)
                .offset(y: sink)
        }
        .padding(style.inset)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.12), value: pressed)
        .onChange(of: pressed) { _, down in
            guard down else { return }
            ConsoleSounds.shared.play(style.sound, scale: style.scale)
            ConsoleHaptics.shared.play(style.haptic, .press)
        }
    }
}

/// A small dark window with how a part stands in words: lit when on (or
/// when it says a value), dim when off.
private struct BoothLamp: View {
    var words: String
    var on: Bool
    var body: some View {
        Text(words)
            .font(.system(size: words.count > 2 ? 10 : 10.5, weight: .black, design: .rounded))
            .lineLimit(1)
            .minimumScaleFactor(0.8)
            .foregroundStyle(on ? Color(red: 1, green: 0.902, blue: 0.949) : Color(red: 1, green: 0.839, blue: 0.918).opacity(0.66))
            .shadow(color: on ? BoothPaint.pink.color() : Color.clear, radius: on ? 2.5 : 0)
            .padding(.horizontal, 3)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(BoothLampWindow().equatable())
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

private struct BoothLampWindow: View, Equatable {
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: 5, style: .continuous)
        shape.fill(BoothPaint.window)
            .overlay(shape.strokeBorder(Color(red: 0.157, green: 0, blue: 0.086).opacity(0.7), lineWidth: 0.8))
            .overlay(alignment: .bottom) {
                Rectangle().fill(Color.white.opacity(0.6)).frame(height: 0.8).padding(.horizontal, 4).offset(y: 1)
            }
    }
}

/// A glyph in a small dark window, drawn as how a part stands: lit when on
/// (or when it shows a value), dim when off — its shape says it too.
private struct BoothLampGlyph: View {
    var glyph: ShellGlyph
    var on: Bool
    var size: CGFloat = 13
    var body: some View {
        let lit = Color(red: 1, green: 0.902, blue: 0.949)
        let dim = Color(red: 1, green: 0.839, blue: 0.918).opacity(0.66)
        ShellGlyphView(glyph: glyph, size: size, ink: on ? lit : dim)
            .shadow(color: on ? BoothPaint.pink.color() : Color.clear, radius: on ? 2.5 : 0)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

/// A switch's cell on the plate: the bat-handle toggle in its chrome nut
/// (the lever up is on, down off; starting over while it is pressed), and
/// in the window under it its glyph, drawn as it stands.
private struct BoothSwitchFace: View, Equatable {
    var glyph: ShellGlyph
    var on: Bool
    var pressed = false
    var body: some View {
        Canvas { context, size in
            let cx = size.width / 2
            let reach: CGFloat = pressed ? 4 : 8.6
            BoothArt.toggle(context, at: CGPoint(x: cx, y: size.height / 2 - (size.height < 60 ? 1.5 : 1)), tip: on ? -reach : reach)
            BoothArt.lampWindow(context, center: CGPoint(x: cx, y: size.height - 8.5), width: min(36, size.width - 8))
        }
        // (The window is 16 high, its middle 8.5 over the cell's foot.)
        .overlay(alignment: .bottom) {
            BoothLampGlyph(glyph: glyph, on: on)
                .frame(height: 16)
                .padding(.bottom, 0.5)
        }
        .accessibilityHidden(true)
    }
}

