/// 浓淡's cell round its − and ＋: the steps as dots (the one it is at
/// larger; none where the cell is narrow), and in its window the step as a
/// row of cells, as many filled as the step it is at (原生 has none: a dash).
private struct BoothToneFace: View, Equatable {
    var step: Int?
    var narrow: Bool
    var body: some View {
        let count = CameraBodyStrength.values.count
        let lowest = CameraBodyStrength.range.lowerBound
        Canvas { context, size in
            let cx = size.width / 2
            if !narrow {
                let at: Int? = step.map { $0 - lowest }
                for i in 0..<count {
                    let p = CGPoint(x: cx + (CGFloat(i) - CGFloat(count - 1) / 2) * 6.5, y: 27)
                    let lit = at.map { i <= $0 } ?? false
                    context.fill(BoothArt.disc(p, i == at ? 3 : 2.3), with: .color(lit ? BoothPaint.pink.color() : BoothPaint.ink.opacity(0.22)))
                }
            }
            let window = CGPoint(x: cx, y: size.height - 8.5)
            if step == nil {
                BoothArt.lamp(context, center: window, width: 36, words: "—", on: true)
            } else {
                BoothArt.lampWindow(context, center: window, width: 36)
            }
        }
        .overlay(alignment: .bottom) {
            if let step {
                BoothLampGlyph(glyph: .tone(step: step - lowest + 1, of: count), on: true, size: 16)
                    .frame(height: 16)
                    .padding(.bottom, 0.5)
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// What the countdown lamps show.
private enum BoothCountShow: Equatable {
    case off
    case set(Int)
    case count(Int)
    case album(video: Bool, length: String)
}

/// The glyphs the countdown lamps draw (the Canvas's symbols, resolved):
/// the stopwatch large and small, the album, a video camera.
private struct BoothLedMarks {
    var watch: GraphicsContext.ResolvedSymbol?
    var smallWatch: GraphicsContext.ResolvedSymbol?
    var album: GraphicsContext.ResolvedSymbol?
    var video: GraphicsContext.ResolvedSymbol?
}

/// The countdown lamps: a white case, a black window of small lamps; the
/// stopwatch while 定时 is off, the seconds it is set to under a small one,
/// the count itself large as it counts down; in 相册, what is being looked
/// at (the album's glyph; a video's camera and its length).
private struct BoothCountFace: View, Equatable {
    var show: BoothCountShow
    var body: some View {
        Canvas { context, size in
            let whole = CGRect(origin: .zero, size: size)
            context.fill(BoothArt.round(whole, 12), with: BoothArt.vertical([BoothArt.stop(Color.white, 0), BoothArt.stop(Color(red: 0.969, green: 0.882, blue: 0.922), 1)], whole))
            context.stroke(BoothArt.round(whole.insetBy(dx: 0.7, dy: 0.7), 11.3), with: .color(Color.white.opacity(0.95)), lineWidth: 1)
            let win = whole.insetBy(dx: 5, dy: 5)
            let glass = BoothArt.round(win, 8)
            context.fill(glass, with: .color(BoothPaint.night))
            context.stroke(glass, with: .color(Color(red: 0.235, green: 0, blue: 0.118).opacity(0.9)), lineWidth: 1.2)
            let marks = BoothLedMarks(watch: context.resolveSymbol(id: 0), smallWatch: context.resolveSymbol(id: 1),
                                      album: context.resolveSymbol(id: 2), video: context.resolveSymbol(id: 3))
            var inside = context
            inside.clip(to: glass)
            BoothArt.ledDots(inside, win)
            Self.words(inside, show, win, marks)
            BoothArt.ledGrid(inside, win, 0.42)
        } symbols: {
            ShellGlyphView(glyph: .timer(.off), size: 30, ink: BoothPaint.ledHot).tag(0)
            ShellGlyphView(glyph: .timer(.off), size: 16, ink: BoothPaint.ledHot).tag(1)
            ShellGlyphView(glyph: .album, size: 22, ink: BoothPaint.ledHot).tag(2)
            ShellGlyphView(glyph: .video(true), size: 18, ink: BoothPaint.ledHot).tag(3)
        }
        .accessibilityHidden(true)
    }
    static func words(_ context: GraphicsContext, _ show: BoothCountShow, _ w: CGRect, _ marks: BoothLedMarks) {
        let cx = w.midX, ww = w.width, wh = w.height
        let tall = wh > ww * 1.3
        switch show {
        case .count(let n):
            let figure = String(n)
            let big = tall ? min(ww * 1.45, wh * 0.62) : wh * 0.62
            BoothArt.ledMark(context, marks.smallWatch, at: CGPoint(x: cx, y: w.minY + 12), size: 16)
            BoothArt.led(context, figure, at: CGPoint(x: cx, y: w.minY + wh * 0.56), size: BoothArt.fit(big, figure, ww))
        case .set(let n):
            let figure = String(n)
            BoothArt.ledMark(context, marks.smallWatch, at: CGPoint(x: cx, y: w.minY + wh * (tall ? 0.22 : 0.26)), size: 16)
            BoothArt.led(context, figure, at: CGPoint(x: cx, y: w.minY + wh * 0.6), size: BoothArt.fit(tall ? 40 : 30, figure, ww))
        case .album(let video, let length):
            if video {
                BoothArt.ledMark(context, marks.album, at: CGPoint(x: cx, y: w.minY + wh * 0.22), size: 22)
                BoothArt.ledMark(context, marks.video, at: CGPoint(x: cx, y: w.minY + wh * 0.5), size: 18)
                if !length.isEmpty {
                    BoothArt.led(context, length, at: CGPoint(x: cx, y: w.minY + wh * 0.76), size: BoothArt.fit(13, length, ww))
                }
            } else {
                BoothArt.ledMark(context, marks.album, at: CGPoint(x: cx, y: w.midY), size: 22)
            }
        case .off:
            BoothArt.ledMark(context, marks.watch, at: CGPoint(x: cx, y: w.midY), size: 30)
        }
    }
}

