/// The heart-shaped name plate on the door: chrome round pink enamel, a
/// little star on it. It is only the booth's plate.
private struct BoothNamePlate: View, Equatable {
    var small: Bool
    var body: some View {
        Canvas { context, size in
            let s: CGFloat = small ? 8 : 14
            let c = CGPoint(x: size.width / 2, y: size.height / 2 - s * 0.12)
            let place = CGAffineTransform(translationX: c.x, y: c.y)
            let rim = BoothArt.heart(s + 2).applying(place)
            let enamel = BoothArt.heart(s).applying(place)
            var lifted = context
            lifted.addFilter(.shadow(color: Color.black.opacity(0.3), radius: 1, x: 0, y: 1))
            lifted.fill(rim, with: .linearGradient(ClamPaint.chrome, startPoint: CGPoint(x: c.x - s, y: c.y - s), endPoint: CGPoint(x: c.x + s, y: c.y + s)))
            let pink = BoothPaint.pink
            context.fill(enamel, with: .linearGradient(Gradient(colors: [pink.color(0.45), pink.color(), pink.color(-0.18)]),
                                                       startPoint: CGPoint(x: c.x, y: c.y - s), endPoint: CGPoint(x: c.x, y: c.y + s)))
            var gloss = context
            gloss.clip(to: enamel)
            gloss.fill(Path(ellipseIn: CGRect(x: c.x - s * 0.95, y: c.y - s * 0.7, width: s * 0.85, height: s * 0.45)), with: .color(Color.white.opacity(0.45)))
            BoothArt.stick(context, BoothArt.star(s * 0.32), at: CGPoint(x: c.x, y: c.y + s * 0.08), size: s * 0.32, colour: BoothPaint.lemon)
            context.stroke(enamel, with: .color(Color.white.opacity(0.7)), lineWidth: 0.8)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

