/// 拍照 / 录像: a pink slider whose candy thumb sits on the one in use and
/// carries its glyph, filled (a camera; a video camera, red), the other
/// end's glyph in outline and dim in the track. Dragged it stays at the
/// nearer end, touched it goes over; a notch is felt half way, and it
/// clicks as it arrives.
private struct BoothModeSlide: View {
    var video: Bool
    var set: (Bool) -> Void
    @Environment(\.deckKeyInset) private var room
    @State private var pull: CGFloat? = nil
    @State private var past: Bool? = nil
    var body: some View {
        GeometryReader { geo in
            let w = max(0, geo.size.width - room.leading - room.trailing)
            let h = max(0, geo.size.height - room.top - room.bottom)
            let thumb = w / 2 + 6
            let run = max(0, w - 6 - thumb)
            let rest: CGFloat = video ? run : 0
            let at = min(run, max(0, pull ?? rest))
            ZStack(alignment: .topLeading) {
                BoothSlideTrack(video: video, small: w < 110).equatable()
                    .frame(width: w, height: h)
                BoothSlideThumb(video: video, small: w < 110, width: thumb)
                    .frame(width: thumb, height: max(0, h - 6))
                    .offset(x: 3 + at, y: 3)
            }
            .frame(width: w, height: h)
            .padding(room)
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 0)
                .onChanged { value in
                    pull = rest + value.translation.width
                    let beyond = rest + value.translation.width > run / 2
                    if beyond != (past ?? video) {
                        past = beyond
                        ConsoleHaptics.shared.play(.sliderNotch, .press)
                    }
                }
                .onEnded { value in
                    let next = abs(value.translation.width) < 5 ? !video : (rest + value.translation.width > run / 2)
                    withAnimation(.easeOut(duration: 0.12)) { pull = nil }
                    past = nil
                    guard next != video else { return }
                    ConsoleSounds.shared.play(.keySlide, scale: 0.8)
                    ConsoleHaptics.shared.play(.sliderNotch, .press)
                    withAnimation(.easeOut(duration: 0.12)) { set(next) }
                })
        }
    }
}

/// The slider's sunk track, and the glyph of the end it is not at there,
/// in outline and dim (a camera, or a video camera).
private struct BoothSlideTrack: View, Equatable {
    var video: Bool
    var small: Bool
    var body: some View {
        let end: ShellGlyph = video ? .photo(false) : .video(false)
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size), radius = size.height / 2
            let track = BoothArt.round(r, radius)
            context.fill(track, with: BoothArt.vertical([BoothArt.stop(Color(red: 0.290, green: 0.114, blue: 0.220), 0), BoothArt.stop(Color(red: 0.471, green: 0.220, blue: 0.361), 1)], r))
            context.stroke(BoothArt.round(r.insetBy(dx: 0.5, dy: 0.5), radius - 0.5), with: .color(Color(red: 0.235, green: 0, blue: 0.118).opacity(0.8)), lineWidth: 1)
            context.stroke(BoothArt.round(CGRect(x: 0.5, y: 1.4, width: max(0, size.width - 1), height: max(0, size.height - 1.9)), radius),
                           with: .color(Color.white.opacity(0.4)), lineWidth: 0.8)
        }
        .overlay {
            GeometryReader { geo in
                let other = max(0, geo.size.width - (geo.size.width / 2 + 6) - 6)
                let x = video ? 3 + other / 2 : geo.size.width - 3 - other / 2
                ShellGlyphView(glyph: end, size: small ? 15 : 16, ink: Color(red: 1, green: 0.839, blue: 0.918).opacity(0.66))
                    .position(x: x, y: geo.size.height / 2 + 0.5)
            }
        }
        .accessibilityHidden(true)
    }
}

/// The slider's candy thumb, the glyph of the end it is at on it (filled:
/// a camera, or a video camera).
private struct BoothSlideThumb: View {
    var video: Bool
    var small: Bool
    var width: CGFloat
    var body: some View {
        let tone = video ? BoothPaint.cherry : BoothPaint.pink
        let mark: ShellGlyph = video ? .video(true) : .photo(true)
        let most: CGFloat = small ? 17 : 19
        let face = LinearGradient(stops: [Gradient.Stop(color: tone.color(0.45), location: 0), Gradient.Stop(color: tone.color(), location: 0.5),
                                          Gradient.Stop(color: tone.color(-0.15), location: 1)], startPoint: .top, endPoint: .bottom)
        Capsule().fill(face)
            .shadow(color: Color(red: 0.157, green: 0, blue: 0.078).opacity(0.5), radius: 1.5, y: 1.5)
            .overlay(Capsule().strokeBorder(Color.white.opacity(0.65), lineWidth: 1))
            .overlay {
                ShellGlyphView(glyph: mark, size: min(most, width * 0.32), ink: Color.white)
                    .shadow(color: tone.color(-0.45), radius: 1.5)
            }
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

// MARK: 选边框's strip

/// What a thumbnail shows: a small picture in that lens, or in that body.
private enum BoothThumbLook: Equatable {
    case lens(CameraLens)
    case body(CameraBody)
}

/// A thumbnail's small picture: in that lens (its sparkles, its two faces,
/// its dream, its night, its dark corners, its colours, its two halves or
/// four), or as that body makes it (its paper, its frame, its colours).
private struct BoothThumbArt: View, Equatable {
    var look: BoothThumbLook
    var body: some View {
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size)
            switch look {
            case .lens(let lens):
                if lens == .merge {
                    BoothArt.scene(context, r.offsetBy(dx: -size.width * 0.15, dy: 0))
                    var ghost = context
                    ghost.opacity = 0.55
                    BoothArt.scene(ghost, r.offsetBy(dx: size.width * 0.15, dy: 0))
                } else {
                    BoothArt.scene(context, r)
                }
                BoothArt.lensMark(context, lens, r)
            case .body(let pinned):
                BoothArt.bodyMark(context, pinned, r)
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A push pin: this body was pinned among the lenses.
private struct BoothPin: View, Equatable {
    var body: some View {
        Canvas { context, size in
            var pin = context
            pin.translateBy(x: size.width / 2, y: 6)
            pin.rotate(by: .radians(0.5))
            var needle = Path()
            needle.move(to: CGPoint(x: 0, y: 3))
            needle.addLine(to: CGPoint(x: 0, y: 10))
            pin.stroke(needle, with: .color(Color(red: 0.490, green: 0.514, blue: 0.549)), style: StrokeStyle(lineWidth: 1.4, lineCap: .round))
            pin.fill(BoothArt.round(CGRect(x: -2.6, y: 1.2, width: 5.2, height: 3.2), 1.2), with: .color(Color(red: 0.761, green: 0.094, blue: 0.247)))
            let head = BoothArt.disc(CGPoint(x: 0, y: -1), 4.6)
            var lifted = pin
            lifted.addFilter(.shadow(color: Color(red: 0.314, green: 0, blue: 0.078).opacity(0.4), radius: 1, x: 0, y: 1))
            lifted.fill(head, with: .radialGradient(Gradient(colors: [Color(red: 1, green: 0.690, blue: 0.741), Color(red: 0.847, green: 0.118, blue: 0.290)]),
                                                    center: CGPoint(x: -1.3, y: -2.4), startRadius: 0.3, endRadius: 5.2))
            pin.stroke(head, with: .color(Color.white.opacity(0.9)), lineWidth: 0.9)
        }
        .frame(width: 14, height: 18)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A thumbnail: a white card, the small picture, and under it the name of
/// the one in use alone (left off too while the card is only partly in
/// the strip: no word is cut); the one in use ringed in pink; a pinned body
/// with its pin.
private struct BoothThumb: View {
    var title: String
    var look: BoothThumbLook
    var on: Bool
    var pinned: Bool
    var named: Bool
    var body: some View {
        let card = RoundedRectangle(cornerRadius: 9, style: .continuous)
        let inner = RoundedRectangle(cornerRadius: 4, style: .continuous)
        VStack(spacing: 0) {
            BoothThumbArt(look: look).equatable()
                .clipShape(inner)
                .overlay(inner.strokeBorder(Color(red: 0.431, green: 0.078, blue: 0.275).opacity(0.25), lineWidth: 0.8))
                .padding(.horizontal, 4)
                .padding(.top, 4)
            Text(title)
                .font(.system(size: on ? 11 : 10, weight: on ? .black : .heavy, design: .rounded))
                .foregroundStyle(on ? BoothPaint.ink : BoothPaint.ink.opacity(0.84))
                .lineLimit(1)
                .minimumScaleFactor(0.6)
                .padding(.horizontal, 3)
                .frame(height: on ? 15 : 13)
                .opacity(named && on ? 1 : 0)
                .padding(.bottom, 2)
        }
        .background(card.fill(Color.white)
            .shadow(color: on ? BoothPaint.pink.color().opacity(0.75) : Color(red: 0.431, green: 0.078, blue: 0.275).opacity(0.28),
                    radius: on ? 4.5 : 1.5, y: on ? 0 : 1.4))
        .overlay {
            if on {
                RoundedRectangle(cornerRadius: 10.5, style: .continuous).stroke(BoothPaint.pink.color(), lineWidth: 2.6).padding(-1.5)
            }
        }
        .overlay(alignment: .topTrailing) {
            if pinned { BoothPin().equatable() }
        }
    }
}

