/// Where the strip's row of thumbnails begins, as it is scrolled.
private struct BoothStripOffsetKey: PreferenceKey {
    static let defaultValue: CGFloat = 0
    static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) { value = nextValue() }
}

/// The strip's sunk track.
private struct BoothTrack: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size)
            let track = BoothArt.round(r, 13)
            context.fill(track, with: BoothArt.vertical([BoothArt.stop(Color(red: 0.914, green: 0.757, blue: 0.831), 0),
                                                         BoothArt.stop(Color(red: 0.973, green: 0.898, blue: 0.933), 0.14),
                                                         BoothArt.stop(Color(red: 1, green: 0.980, blue: 0.988), 1)], r))
            var inner = context
            inner.clip(to: track)
            let shade = CGRect(x: 0, y: 0, width: size.width, height: 7)
            inner.fill(Path(shade), with: BoothArt.vertical([BoothArt.stop(BoothPaint.wine.opacity(0.22), 0), BoothArt.stop(BoothPaint.wine.opacity(0), 1)], shade))
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// Over the strip: the fades at an end where there are more, its edge, and
/// the thin bar that says how far along it is (from `start` to `end`).
private struct BoothStripEnds: View, Equatable {
    var before: Bool
    var after: Bool
    var start: CGFloat
    var end: CGFloat
    var body: some View {
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size)
            let track = BoothArt.round(r, 13)
            var inner = context
            inner.clip(to: track)
            let paper = Color(red: 0.992, green: 0.941, blue: 0.965)
            if after {
                inner.fill(Path(CGRect(x: size.width - 16, y: 0, width: 16, height: size.height)),
                           with: .linearGradient(Gradient(colors: [paper.opacity(0), paper]), startPoint: CGPoint(x: size.width - 16, y: 0), endPoint: CGPoint(x: size.width, y: 0)))
            }
            if before {
                inner.fill(Path(CGRect(x: 0, y: 0, width: 12, height: size.height)),
                           with: .linearGradient(Gradient(colors: [paper, paper.opacity(0)]), startPoint: .zero, endPoint: CGPoint(x: 12, y: 0)))
            }
            context.stroke(BoothArt.round(r.insetBy(dx: 0.5, dy: 0.5), 12.5), with: .color(Color(red: 0.471, green: 0.078, blue: 0.275).opacity(0.42)), lineWidth: 1)
            let bar = CGRect(x: 14, y: size.height - 6.2, width: max(0, size.width - 28), height: 2.4)
            context.fill(BoothArt.round(bar, 1.2), with: .color(BoothPaint.ink.opacity(0.14)))
            let seen = CGRect(x: bar.minX + bar.width * start, y: size.height - 6.5, width: max(3, bar.width * (end - start)), height: 3)
            context.fill(BoothArt.round(seen, 1.5), with: .color(BoothPaint.pink.color().opacity(0.8)))
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// 选边框's strip: the lenses (and the bodies pinned among them) as
/// thumbnails in a sunk track that scrolls, the one in use larger and kept
/// in sight; a touch chooses one.
private struct BoothStrip: View {
    @ObservedObject var model: CameraAppModel
    var size: CGSize
    @State private var offset: CGFloat = 0
    private enum Item: Hashable { case lens(CameraLens), body(CameraBody) }

    private func on(_ item: Item) -> Bool {
        switch item {
        case .lens(let lens): return model.lens == lens
        case .body(let pinned): return model.body == pinned
        }
    }
    /// Where each thumbnail begins along the row.
    private static func starts(_ sizes: [CGFloat]) -> [CGFloat] {
        var out: [CGFloat] = []
        var x: CGFloat = 7
        for s in sizes {
            out.append(x)
            x += s + 6
        }
        return out
    }

    var body: some View {
        let items: [Item] = CameraLens.allCases.map(Item.lens) + model.pinnedBodies.map(Item.body)
        let big = max(0, size.height - 13), small = max(0, big - 8)
        let sizes: [CGFloat] = items.map { on($0) ? big : small }
        let starts = Self.starts(sizes)
        let content = (starts.last ?? 7) + (sizes.last ?? 0) + 7
        let seen = max(0, -offset)
        let width = max(1, size.width)
        ZStack(alignment: .topLeading) {
            BoothTrack().equatable()
            ScrollViewReader { reader in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(alignment: .center, spacing: 6) {
                        ForEach(Array(items.enumerated()), id: \.element) { index, item in
                            let whole = starts[index] - seen >= 0 && starts[index] - seen + sizes[index] <= width - 4
                            thumb(item, size: sizes[index], named: whole).id(item)
                        }
                    }
                    .padding(.horizontal, 7)
                    .frame(height: big)
                    .padding(.top, 4)
                    .frame(height: size.height, alignment: .top)
                    .background(GeometryReader { g in
                        Color.clear.preference(key: BoothStripOffsetKey.self, value: g.frame(in: .named("booth-strip")).minX)
                    })
                }
                .coordinateSpace(name: "booth-strip")
                .onPreferenceChange(BoothStripOffsetKey.self) { offset = $0 }
                .onAppear { reader.scrollTo(Item.lens(model.lens), anchor: .center) }
                .onChange(of: model.lens) { _, lens in
                    withAnimation(.easeOut(duration: 0.2)) { reader.scrollTo(Item.lens(lens), anchor: .center) }
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
            BoothStripEnds(before: seen > 1, after: seen + width < content - 1,
                           start: min(1, seen / max(1, content)), end: min(1, (seen + width) / max(1, content))).equatable()
        }
        .frame(width: size.width, height: size.height)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("camera-deck-lenses")
    }

    private func thumb(_ item: Item, size s: CGFloat, named: Bool) -> some View {
        let title: String, look: BoothThumbLook, chosen: Bool, pinned: Bool, identifier: String
        switch item {
        case .lens(let lens):
            title = lens.title; look = .lens(lens); chosen = model.lens == lens; pinned = false; identifier = "camera-deck-lens-\(lens.rawValue)"
        case .body(let pinnedBody):
            title = pinnedBody.title; look = .body(pinnedBody); chosen = model.body == pinnedBody; pinned = true; identifier = "camera-deck-pinned-\(pinnedBody.rawValue)"
        }
        return Button {
            switch item {
            case .lens(let lens): model.choose(lens)
            case .body(let pinnedBody): model.tapPinned(pinnedBody)
            }
        } label: {
            BoothThumb(title: title, look: look, on: chosen, pinned: pinned, named: named)
        }
        .buttonStyle(BoothThumbStyle())
        .frame(width: s, height: s)
        .accessibilityLabel(title)
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
}

// MARK: the sticker outlet and the sheets

/// A sheet's backing paper: lilac, white dots, its shadow, a light edge.
private struct BoothPaper: View {
    var radius: CGFloat
    var dot: CGFloat
    var dotRadius: CGFloat
    var shadow: CGFloat
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: radius, style: .continuous)
        shape.fill(Color(red: 0.957, green: 0.910, blue: 1))
            .shadow(color: Color(red: 0.314, green: 0.031, blue: 0.196).opacity(0.38), radius: shadow, y: shadow * 0.75)
            .overlay(BoothDots(step: dot, radius: dotRadius).equatable().clipShape(shape))
            .overlay(shape.strokeBorder(Color.white.opacity(0.9), lineWidth: 1))
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

private struct BoothDots: View, Equatable {
    var step: CGFloat
    var radius: CGFloat
    var body: some View {
        Canvas { context, size in
            BoothArt.dots(context, CGRect(origin: .zero, size: size), step: step, radius: radius, colour: Color.white.opacity(0.85))
        }
    }
}

/// A video's mark on a sticker.
private struct BoothPlayBadge: View {
    var size: CGFloat
    var body: some View {
        Image(systemName: "play.fill")
            .font(.system(size: size * 0.9, weight: .bold))
            .foregroundStyle(Color.white)
            .offset(x: size * 0.12)
            .frame(width: 2 * size, height: 2 * size)
            .background(Circle().fill(Color(red: 0.118, green: 0.031, blue: 0.094).opacity(0.55))
                .overlay(Circle().strokeBorder(Color.white.opacity(0.9), lineWidth: 1)))
            .accessibilityHidden(true)
    }
}

/// One sticker of a sheet: the cut line round it (dashed), its white edge,
/// the picture with round corners (blank until it is read); a video's mark.
private struct BoothSticker: View {
    var image: CGImage?
    var radius: CGFloat
    var cut = true
    var badge: CGFloat = 0
    var body: some View {
        let shape = RoundedRectangle(cornerRadius: radius, style: .continuous)
        ZStack {
            Color(red: 0.86, green: 0.83, blue: 0.87)
            if let image { Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill()) }
        }
        .clipShape(shape)
        .background {
            RoundedRectangle(cornerRadius: radius + 1.8, style: .continuous).fill(Color.white)
                .padding(-1.8)
                .shadow(color: Color(red: 0.314, green: 0.031, blue: 0.196).opacity(0.2), radius: 0.8, y: 0.6)
        }
        .background {
            if cut {
                RoundedRectangle(cornerRadius: radius + 3.2, style: .continuous)
                    .stroke(Color(red: 0.471, green: 0.251, blue: 0.502).opacity(0.72), style: StrokeStyle(lineWidth: 0.9, dash: [2.4, 1.8]))
                    .padding(-3.2)
            }
        }
        .overlay {
            if badge > 0 { BoothPlayBadge(size: badge) }
        }
        .allowsHitTesting(false)
    }
}

/// The newest picture hanging out of the outlet: four of it as stickers on
/// a sheet (smaller held across).
private struct BoothOutletSheet: View {
    var image: CGImage?
    var small: Bool
    var width: CGFloat
    var body: some View {
        let m: CGFloat = small ? 3.5 : 8
        let top: CGFloat = small ? 7 : 10
        let cw: CGFloat = small ? 11.5 : max(0, (width - 3 * m) / 2)
        let ch: CGFloat = small ? 8.6 : cw * 0.75
        let stepX: CGFloat = small ? 13.5 : cw + m
        let stepY: CGFloat = small ? 13 : ch + m
        ZStack(alignment: .topLeading) {
            BoothPaper(radius: small ? 3 : 4, dot: small ? 6 : 7, dotRadius: small ? 0.9 : 1.1, shadow: small ? 1.5 : 2)
            ForEach(0..<4, id: \.self) { i in
                BoothSticker(image: image, radius: small ? 2 : 4, cut: !small)
                    .frame(width: cw, height: ch)
                    .offset(x: m + CGFloat(i % 2) * stepX, y: top + CGFloat(i / 2) * stepY)
            }
        }
    }
}

/// The outlet's dark mouth (the album's glyph over it, or beside it held
/// across: BoothOutletBody).
private struct BoothOutletFace: View, Equatable {
    var small: Bool
    var body: some View {
        Canvas { context, size in
            let w = size.width
            if small {
                context.fill(BoothArt.round(CGRect(x: 6, y: 8, width: 38, height: 7), 3.5), with: .color(BoothPaint.mouth))
            } else {
                context.fill(BoothArt.round(CGRect(x: 12, y: 23, width: max(0, w - 24), height: 9), 4.5), with: .color(BoothPaint.mouth))
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// Over the sheet: the mouth's lower lip, the clear pink tray under it.
private struct BoothOutletLip: View, Equatable {
    var small: Bool
    var body: some View {
        Canvas { context, size in
            let w = size.width, h = size.height
            let lip = small ? CGRect(x: 6, y: 11, width: 38, height: 3.4) : CGRect(x: 12, y: 27.5, width: max(0, w - 24), height: 4.2)
            context.fill(BoothArt.round(lip, lip.height / 2), with: BoothArt.vertical([BoothArt.stop(Color.white, 0), BoothArt.stop(Color(red: 0.902, green: 0.765, blue: 0.827), 1)], lip))
            let tray = small ? CGRect(x: 4, y: h - 12, width: 42, height: 9) : CGRect(x: 7, y: h - 31, width: max(0, w - 14), height: 24)
            let shape = BoothArt.round(tray, small ? 4 : 9)
            context.fill(shape, with: .color(Color(red: 1, green: 0.831, blue: 0.914).opacity(0.92)))
            context.stroke(shape, with: .color(Color.white.opacity(0.95)), lineWidth: small ? 0.8 : 1)
            if !small {
                context.fill(Path(CGRect(x: 16, y: tray.minY + 3, width: max(0, w - 32), height: 1.2)), with: .color(Color.white.opacity(0.75)))
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The outlet as 相册's key: pressed, the sheet is pulled out a little (and
/// 相册 opens, with a paper's slide). `out`: how far a new sheet still is in
/// the mouth (−1 all of it, 0 out).
private struct BoothOutletStyle: ButtonStyle {
    var small: Bool
    var size: CGSize
    var image: CGImage?
    var count: Int
    var out: CGFloat
    func makeBody(configuration: Configuration) -> some View {
        BoothOutletBody(style: self, pressed: configuration.isPressed)
    }
}

private struct BoothOutletBody: View {
    var style: BoothOutletStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let w = style.size.width, h = style.size.height, small = style.small
        let sheet = small ? CGRect(x: 9, y: 11, width: 32, height: max(0, h - 18)) : CGRect(x: 22, y: 27, width: max(0, w - 44), height: max(0, h - 38))
        let mouth: CGFloat = small ? 11.5 : 27.5
        let pull = style.out * sheet.height + (pressed ? (small ? 4 : 10) : 0)
        ZStack(alignment: .topLeading) {
            BoothOutletFace(small: small).equatable()
            // The album's glyph where the outlet's name was printed: over its
            // mouth, or beside it held across.
            ShellGlyphView(glyph: .album, size: small ? 16 : 15, ink: BoothPaint.ink)
                .frame(width: small ? max(0, w - 44) : w, height: 20)
                .offset(x: small ? 44 : 0, y: small ? h / 2 - 10 : 3)
            BoothOutletSheet(image: style.image, small: small, width: sheet.width)
                .frame(width: sheet.width, height: sheet.height)
                .offset(x: sheet.minX, y: sheet.minY - mouth + pull)
                .frame(width: w, height: max(0, h - mouth), alignment: .topLeading)
                .clipped()
                .offset(y: mouth)
            BoothOutletLip(small: small).equatable()
            if !small {
                // How many there are: the figures alone.
                Text(verbatim: "\(style.count)")
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .monospacedDigit()
                    .foregroundStyle(BoothPaint.ink)
                    .lineLimit(1)
                    .minimumScaleFactor(0.7)
                    .frame(width: max(0, w - 20), height: 20)
                    .offset(x: 10, y: h - 29)
                    .accessibilityHidden(true)
            }
        }
        .frame(width: w, height: h, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.08 : 0.2), value: pressed)
        .onChange(of: pressed) { _, down in
            guard down else { return }
            ConsoleSounds.shared.play(.cardFlip, scale: 0.5)
            ConsoleHaptics.shared.play(.smallButton, .press)
        }
    }
}

/// The sticker outlet, 相册's key: the newest picture hangs out of it as a
/// sheet of stickers, how many there are on its tray. A picture just taken
/// comes out of the mouth with the printer's whirr.
private struct BoothOutlet: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var small: Bool
    var size: CGSize
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var out: CGFloat = 0
    var body: some View {
        let latest = model.photos.first
        let image: CGImage? = latest.flatMap { thumbnails.images[$0.url] }
        Button { model.openAlbum() } label: { Color.clear }
            .buttonStyle(BoothOutletStyle(small: small, size: size, image: image, count: model.photos.count, out: out))
            .accessibilityLabel(CameraShellSkin.booth.albumTitle)
            .accessibilityValue(String(localized: "\(model.photos.count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .onAppear { if let latest { thumbnails.request(latest.url) } }
            .onChange(of: model.photos.first?.url) { old, url in
                guard let url else { return }
                thumbnails.request(url)
                // (Only a picture just taken comes out: one more than there was.)
                guard old != url, model.phase == .live else { return }
                ConsoleSounds.shared.play(.instantEject, scale: 0.6)
                guard !reduceMotion else { return }
                var still = Transaction()
                still.disablesAnimations = true
                withTransaction(still) { out = -1 }
                Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 60_000_000)
                    withAnimation(.easeOut(duration: 0.5)) { out = 0 }
                }
            }
    }
}

/// 相册's sheet: the picture looked at as a sheet of stickers — four large,
/// four small, each with its cut line — on lilac paper, the date and the
/// place printed at its foot; a video's large stickers marked ▶, and while
/// it plays one of them plays it (the others hold its still).
private struct BoothSheet: View {
    var photo: CameraPhoto?
    var image: CGImage?
    var playing: Bool
    var place: String
    var width: CGFloat
    var height: CGFloat
    var ended: () -> Void
    /// The sheet's rows: the large stickers' width and two rows, the small
    /// ones' width and their row.
    static func rows(_ w: CGFloat) -> (cw: CGFloat, ch: CGFloat, mw: CGFloat, mh: CGFloat, y2: CGFloat, y3: CGFloat) {
        let cw = max(0, (w - 40) / 2), ch = cw * 0.75
        let mw = max(0, (w - 58) / 4), mh = mw * 0.75
        let y2 = 16 + ch + 12
        return (cw, ch, mw, mh, y2, y2 + ch + 14)
    }
    /// The date as the booth prints it.
    static func printed(_ date: Date) -> String {
        let c = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d.%02d.%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }
    var body: some View {
        let r = Self.rows(width)
        let video = photo?.isVideo == true
        let badge = max(6, min(r.cw, r.ch) * 0.2)
        ZStack(alignment: .topLeading) {
            BoothPaper(radius: 10, dot: 10, dotRadius: 1.6, shadow: 4)
            BoothSheetBits().equatable()
            ForEach(0..<4, id: \.self) { i in
                large(i, video: video, badge: badge)
                    .frame(width: r.cw, height: r.ch)
                    .offset(x: 14 + CGFloat(i % 2) * (r.cw + 12), y: i < 2 ? 16 : r.y2)
            }
            ForEach(0..<4, id: \.self) { i in
                BoothSticker(image: image, radius: 6)
                    .frame(width: r.mw, height: r.mh)
                    .offset(x: 14 + CGFloat(i) * (r.mw + 10), y: r.y3)
            }
            if photo == nil {
                Text(String(localized: "还没有照片"))
                    .font(.system(size: 13, weight: .heavy, design: .rounded))
                    .foregroundStyle(BoothPaint.ink.opacity(0.7))
                    .frame(width: width, height: r.y3)
            }
            HStack(spacing: 4) {
                Text(verbatim: photo.map { Self.printed($0.date) } ?? "")
                Spacer(minLength: 4)
                Text(verbatim: place)
            }
            .font(.system(size: 10.5, weight: .heavy, design: .rounded))
            .foregroundStyle(Color(red: 0.541, green: 0.290, blue: 0.541))
            .lineLimit(1)
            .minimumScaleFactor(0.7)
            .padding(.leading, 34)
            .padding(.trailing, 46)
            .frame(width: width, height: 16)
            .offset(y: height - 26)
        }
        .frame(width: width, height: height, alignment: .topLeading)
    }
    @ViewBuilder private func large(_ i: Int, video: Bool, badge: CGFloat) -> some View {
        let plays = i == 0 && playing
        BoothSticker(image: image, radius: 9, badge: video && !plays ? badge : 0)
            .overlay {
                if plays, let photo {
                    BoothPlayer(url: photo.url, ended: ended)
                        .clipShape(RoundedRectangle(cornerRadius: 9, style: .continuous))
                }
            }
    }
}

/// The one player on a sheet whose video plays (the phone's; a still in its
/// place elsewhere).
private struct BoothPlayer: View {
    var url: URL
    var ended: () -> Void
    var body: some View {
        #if os(iOS)
        CameraVideoPlayer(url: url, ended: ended)
            .accessibilityIdentifier("camera-album-player")
        #else
        Color.black
        #endif
    }
}

/// The bits printed at the sheet's foot: two hearts and a star.
private struct BoothSheetBits: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let y = size.height - 18
            BoothArt.stick(context, BoothArt.heart(4.5), at: CGPoint(x: 22, y: y), size: 4.5, colour: BoothPaint.lace)
            BoothArt.stick(context, BoothArt.star(5), at: CGPoint(x: size.width - 22, y: y), size: 5, colour: BoothPaint.gold)
            BoothArt.stick(context, BoothArt.heart(3.4), at: CGPoint(x: size.width - 36, y: y), size: 3.4, colour: ShellTone(r: 0.549, g: 0.769, b: 1))
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

