/// 内 / 外 under the hood: a mint candy key (the side in use is on the
/// screen, not by the key). In 相册 it is grey and waits.
private struct BoothFlipKey: View {
    var layout: BoothLayout
    var side: String
    var off: Bool
    var waits = false
    var why: String
    var action: () -> Void
    var body: some View {
        let l = layout
        let tone = waits ? ShellTone(r: 0.839, g: 0.808, b: 0.831) : BoothPaint.mint
        let ink = Color.white.opacity(waits ? 0.9 : 1)
        ZStack(alignment: .topLeading) {
            Button(action: action) { BoothFlipLabel(across: l.across, ink: ink) }
                .buttonStyle(BoothCandyStyle(tone: tone, radius: l.across ? 9 : 12, inset: BoothLayout.collar(l.flip, l.flipCap),
                                             ink: ink))
                .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
                .accessibilityValue(side)
                .accessibilityIdentifier("camera-deck-switch")
                .deckDimmed(off, why: why)
                .deckKey(l.flip)
        }
        .frame(width: l.canvas.width, height: l.canvas.height, alignment: .topLeading)
    }
