/// The lamps' sign between ◀ and ▶ in 相册: which one it is of how many,
/// in figures (7 / 12).
private struct BoothCountSign: View, Equatable {
    var figures: String
    var small: Bool
    var body: some View {
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size)
            let box = BoothArt.round(r.insetBy(dx: 1, dy: 1), 11)
            context.fill(box, with: .color(BoothPaint.night))
            var inside = context
            inside.clip(to: box)
            BoothArt.ledDots(inside, r)
            BoothArt.led(inside, figures, at: CGPoint(x: r.midX, y: r.midY), size: BoothArt.fit(small ? 17 : 21, figures, r.width))
            BoothArt.ledGrid(inside, r, 0.3)
            context.stroke(box, with: .color(Color.white.opacity(0.9)), lineWidth: 2)
        }
    }
}

/// The photo-sticker booth's 相册: the picture looked at hangs out of the
/// outlet as a sheet of stickers (◀ ▶ send it back in and the one before or
/// after out, a swipe on it too; a touch plays a video); the lamps' sign
/// says which it is of how many; 回去拍照 and the shutter go back to taking
/// pictures; 播放 plays a video (a picture's waits, and says why); 主菜单 as
/// ever. 内 / 外 waits; the countdown lamps say what is looked at.
private struct BoothAlbum: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var booth: BoothLayout
    var hinge: CGRect
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    /// How far the sheet still is in the mouth (−1 all of it), and how far
    /// a finger has pushed it aside.
    @State private var out: CGFloat = 0
    @State private var push: CGFloat = 0

    private var waiting: String { String(localized: "相册里用不了，回去拍照再用") }
    private var video: Bool { model.albumPhoto?.isVideo == true }
    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private var length: String { model.albumDuration.map { CameraAppModel.clock(Int($0.rounded())) } ?? "" }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    private func choose(_ next: Int) {
        guard model.photos.indices.contains(next), next != model.albumIndex, model.doodle == nil else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }
    private func sharp(_ photo: CameraPhoto?) -> CGImage? {
        guard let photo else { return nil }
        return (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }
    /// Another sheet out of the outlet: in the mouth at once, then out, with
    /// the printer's whirr.
    private func comeOut() {
        if let photo = model.albumPhoto { thumbnails.request(photo.url) }
        guard !model.photos.isEmpty else { return }
        ConsoleSounds.shared.play(.instantEject, scale: 0.5)
        guard !reduceMotion else { return }
        var still = Transaction()
        still.disablesAnimations = true
        withTransaction(still) { out = -1 }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 40_000_000)
            withAnimation(.easeOut(duration: 0.4)) { out = 0 }
        }
    }

    var body: some View {
        let l = booth
        let outlet = l.sheetOutlet
        ZStack(alignment: .topLeading) {
            BoothBackdrop(layout: l, hinge: hinge, album: true).equatable()
            BoothBulbs(layout: l, chase: nil).equatable()
            // The album's glyph between the outlet's two arrows, where its name was printed.
            if outlet.width > 60, outlet.height > 30 {
                ShellGlyphView(glyph: .album, size: 14, ink: BoothPaint.ink)
                    .allowsHitTesting(false)
                    .deckPlaced(CGRect(x: outlet.minX, y: outlet.minY + 3, width: outlet.width, height: 20))
            }
            sheet
            RoundedRectangle(cornerRadius: 2.5, style: .continuous)
                .fill(LinearGradient(colors: [Color.white, Color(red: 0.902, green: 0.765, blue: 0.827)], startPoint: .top, endPoint: .bottom))
                .allowsHitTesting(false)
                .accessibilityHidden(true)
                .deckPlaced(CGRect(x: outlet.minX + 16, y: outlet.minY + 27, width: max(0, outlet.width - 32), height: 5))
            notes
            steps
            sign
            keys
            BoothFlipKey(layout: l, side: model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), off: true, waits: true, why: waiting) {
                model.say(waiting)
            }
            BoothCountFace(show: .album(video: video, length: length)).equatable()
                .background(RoundedRectangle(cornerRadius: 12, style: .continuous).fill(BoothPaint.wine.opacity(0.35)).blur(radius: 3).offset(y: 2))
                .allowsHitTesting(false)
                .deckPlaced(l.timer)
            shutter
        }
        .frame(width: l.canvas.width, height: l.canvas.height, alignment: .topLeading)
        .onAppear { comeOut() }
        .onChange(of: model.albumIndex) { _, _ in comeOut() }
    }

    /// The sheet, from the outlet's mouth down (what is in the mouth is not seen).
    private var sheet: some View {
        let area = booth.sheet
        let w = max(0, min(area.width, (area.height - 49.25) / 0.9375))
        let h = w * 0.9375 + 49.25
        let top = BoothArt.mouth(booth.sheetOutlet).midY
        let photo = model.albumPhoto
        let kind = video ? String(localized: "视频") + " " + length + "  ·  " : ""
        let place = photo == nil ? "" : kind + "No.\(model.albumIndex + 1) / \(model.photos.count)"
        let label = photo == nil ? String(localized: "还没有照片") : (video ? String(localized: "录像") : CameraShellSkin.booth.albumTitle)
        return BoothSheet(photo: photo, image: sharp(photo), playing: photo.map { model.playing == $0.url } ?? false, place: place,
                          width: w, height: h, ended: { model.playedToEnd() })
            .frame(width: w, height: h)
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 8)
                .onChanged { push = $0.translation.width }
                .onEnded { value in
                    let dx = value.translation.width
                    withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                    if abs(dx) > 60 { choose(model.albumIndex + (dx < 0 ? 1 : -1)) }
                })
            .onTapGesture { if video { model.togglePlay() } }
            .accessibilityElement(children: .ignore)
            .accessibilityLabel(label)
            .accessibilityValue(photo?.name ?? "")
            .accessibilityIdentifier("camera-deck-album-picture")
            .offset(x: push, y: area.minY - top + out * h)
            .frame(width: area.width + 32, height: max(0, booth.canvas.height - top), alignment: .top)
            .clipped()
            .offset(x: area.minX - 16, y: top)
    }

    /// What the booth says over the sheet: that the picture is being drawn
    /// on inside; a moment's message.
    @ViewBuilder private var notes: some View {
        let area = booth.sheet
        if model.doodle != nil {
            Text(drawingWhy)
                .font(.system(size: 12, weight: .heavy, design: .rounded))
                .foregroundStyle(Color.white)
                .multilineTextAlignment(.center)
                .lineLimit(2)
                .minimumScaleFactor(0.7)
                .padding(.horizontal, 12)
                .padding(.vertical, 6)
                .background(Capsule().fill(Color.black.opacity(0.62)))
                .padding(.horizontal, 16)
                .accessibilityIdentifier("camera-deck-editing")
                .frame(width: area.width)
                .position(x: area.midX, y: area.midY)
        }
        if let toast = model.toast {
            Text(toast)
                .font(.system(size: 10.5, weight: .bold, design: .rounded))
                .foregroundStyle(Color.white)
                .lineLimit(2)
                .multilineTextAlignment(.center)
                .minimumScaleFactor(0.7)
                .padding(.horizontal, 10)
                .padding(.vertical, 4)
                .background(Capsule().fill(Color.black.opacity(0.62)))
                .padding(.horizontal, 14)
                .allowsHitTesting(false)
                .frame(width: area.width)
                .position(x: area.midX, y: area.maxY - 34)
                .transition(.opacity)
        }
    }

    /// ◀ 上一张 and 下一张 ▶ (their arrows alone).
    @ViewBuilder private var steps: some View {
        let l = booth, none = model.photos.isEmpty
        let empty = String(localized: "还没有照片")
        let earlier = String(localized: "上一张"), later = String(localized: "下一张")
        Button { choose(model.albumIndex - 1) } label: { BoothStepLabel(way: 3, radius: l.albumArcade) }
            .buttonStyle(BoothArcadeStyle(tone: BoothPaint.sky, radius: l.albumArcade))
            .accessibilityLabel(earlier)
            .accessibilityIdentifier("camera-deck-album-previous")
            .deckDimmed(none, why: empty)
            .deckKey(l.albumPrevious)
        Button { choose(model.albumIndex + 1) } label: { BoothStepLabel(way: 1, radius: l.albumArcade) }
            .buttonStyle(BoothArcadeStyle(tone: BoothPaint.sky, radius: l.albumArcade))
            .accessibilityLabel(later)
            .accessibilityIdentifier("camera-deck-album-next")
            .deckDimmed(none, why: empty)
            .deckKey(l.albumNext)
    }

    /// The lamps' sign: "7 / 12" (a dash with none), read by VoiceOver and
    /// the tests as "7 / 12".
    private var sign: some View {
        let count = model.photos.count
        let place = count == 0 ? "0" : "\(model.albumIndex + 1) / \(count)"
        let figures = count == 0 ? "—" : place
        return BoothCountSign(figures: figures, small: booth.across).equatable()
            .accessibilityElement()
            .accessibilityLabel(place)
            .accessibilityIdentifier("camera-deck-album-position")
            .deckPlaced(booth.albumSign)
    }

    /// 回去拍照 across the row (its words kept); 播放 (▶, ■ while it plays)
    /// and its window (a video's length; for a picture a video camera, dim:
    /// it plays videos only), 主菜单 (a house) under it.
    @ViewBuilder private var keys: some View {
        let l = booth
        let word = model.playing != nil ? String(localized: "停止") : String(localized: "播放")
        let why = model.photos.isEmpty ? String(localized: "还没有照片") : String(localized: "照片不能播放；要在上面画，展开后用相册的「编辑」")
        Button { backToCamera() } label: { BoothBackLabel(size: l.across ? 14 : 16.5) }
            .buttonStyle(BoothCandyStyle(tone: BoothPaint.pink, radius: l.across ? 14 : 16))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-return")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(l.albumBack)
        if video {
            BoothLamp(words: length, on: true)
                .deckPlaced(l.albumPlayWindow)
        } else {
            BoothLampGlyph(glyph: .video(false), on: false, size: 14)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(BoothLampWindow().equatable())
                .deckPlaced(l.albumPlayWindow)
        }
        Button { if video { model.togglePlay() } else { model.say(why) } } label: { BoothPlayLabel(stop: model.playing != nil, size: l.across ? 22 : 20) }
            .buttonStyle(BoothCandyStyle(tone: video ? BoothPaint.mint : ShellTone(r: 0.769, g: 0.729, b: 0.761), radius: 12,
                                         inset: BoothLayout.collar(l.albumPlay, l.albumPlayCap), scale: video ? 0.8 : 0.4))
            .accessibilityLabel(word)
            .accessibilityValue(video ? length : "")
            .accessibilityIdentifier("camera-deck-album-play")
            .deckDimmed(!video, why: why)
            .deckKey(l.albumPlay)
        Button { model.leave() } label: { BoothHomeLabel(size: l.across ? 20 : 24) }
            .buttonStyle(BoothCandyStyle(tone: BoothPaint.lilac, radius: 14, inset: BoothLayout.collar(l.albumHome, l.albumHomeCap)))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(l.albumHome)
    }

    /// The shutter says 回去拍照 here, and goes back.
    private var shutter: some View {
        let l = booth
        return Button { backToCamera() } label: {
            BoothShutterLabel(video: false, recording: false, time: "", back: String(localized: "回去拍照"), radius: l.shutterRadius)
        }
        .buttonStyle(BoothArcadeStyle(tone: BoothPaint.pink, radius: l.shutterRadius, travel: 4, sound: .keyRubber, scale: 0.9))
        .accessibilityLabel(String(localized: "回去拍照"))
        .accessibilityIdentifier("camera-deck-album-close")
        .deckDimmed(drawing, why: drawingWhy)
        .deckKey(l.shutter)
    }
}

extension CameraDeckFace {
    /// The photo-sticker booth taking pictures, upright or across: its body,
    /// the picture in its screen's frame (nothing over the picture but the
    /// zoom stops), the sign's lights and the hood's, 选边框, the plate, the
    /// outlet, the slide, 主菜单 and the door, 内 / 外, the countdown lamps,
    /// the shutter.
    @ViewBuilder func boothLive(_ booth: BoothLayout) -> some View {
        let l = layout
        BoothBackdrop(layout: booth, hinge: hinge, album: false).equatable()
            .frame(width: l.canvas.width, height: l.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: l.keepOut, control: control, canvas: l.canvas) }
        viewfinder.deckPlaced(l.viewfinder)
        BoothScreenFrame(surround: booth.frame, box: booth.box, picture: l.picture, valance: booth.valance, top: booth.decoTop).equatable()
            .frame(width: l.canvas.width, height: l.canvas.height)
        if l.zoomBar.width > 0 {
            zoomBar.deckPlaced(l.zoomBar)
                .opacity(systemControlsUp ? 0 : 1)
                .allowsHitTesting(!systemControlsUp)
        }
        BoothSignLights(layout: booth, countdown: model.countdown, flash: model.flash)
            .frame(width: l.canvas.width, height: l.canvas.height)
        if booth.hood.width > 0 {
            BoothHoodSweep(size: booth.hood.size, side: model.side).deckPlaced(booth.hood)
        }
        boothLenses(booth)
        boothPlate(booth)
        boothLower(booth)
        boothGrip(booth)
        if model.bodiesOpen {
            bodyMenu.deckPlaced(l.bodyMenu).transition(.opacity)
        }
        if model.countdown != nil, model.side == .inner, let camera = l.keepOut.first {
            LookHereBadge(camera: camera, canvas: l.canvas)
        }
    }

    /// The booth's 相册, upright or across.
    @ViewBuilder func boothAlbum(_ booth: BoothLayout) -> some View {
        BoothAlbum(model: model, thumbnails: thumbnails, booth: booth, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }

    /// 选边框: the strip (the name of the one in use under it alone), ◀ and
    /// ▶ (they step back while the system's Camera Control menu is up, as
    /// the lenses do on every back).
    @ViewBuilder private func boothLenses(_ booth: BoothLayout) -> some View {
        let hidden = systemControlsUp
        BoothStrip(model: model, size: booth.strip.size)
            .deckPlaced(booth.strip)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
        boothStep(-1, booth.previous, radius: booth.arcade)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
        boothStep(1, booth.next, radius: booth.arcade)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
    }
    private func boothStep(_ way: Int, _ rect: CGRect, radius: CGFloat) -> some View {
        Button { model.stepLens(way) } label: { BoothStepLabel(way: way < 0 ? 3 : 1, radius: radius) }
            .buttonStyle(BoothArcadeStyle(tone: BoothPaint.sky, radius: radius))
            .accessibilityLabel(way < 0 ? String(localized: "上一个边框") : String(localized: "下一个边框"))
            .accessibilityValue(model.lens.title)
            .accessibilityIdentifier(way < 0 ? "camera-deck-lens-previous" : "camera-deck-lens-next")
            .deckKey(rect)
    }

    /// The plate: 闪光, 日期 and 水平仪 as switches (each glyph in its window,
    /// drawn as it stands), 画幅 (its frame on the key, its figures in the
    /// window), 浓淡's − and ＋.
    @ViewBuilder private func boothPlate(_ booth: BoothLayout) -> some View {
        let shooting = model.shooting
        let on = String(localized: "开"), off = String(localized: "关")
        if booth.switches.count == 3 {
            boothSwitch(String(localized: "闪光"), glyph: .flash(shooting.flash), on: shooting.flash != .off, state: shooting.flash.title,
                        identifier: "camera-deck-flash") { model.cycleFlash() }
                .deckKey(booth.switches[0])
            boothSwitch(String(localized: "日期"), glyph: .date(shooting.dateStamp), on: shooting.dateStamp, state: shooting.dateStamp ? on : off,
                        identifier: "camera-deck-date") { model.toggleDateStamp() }
                .deckKey(booth.switches[1])
            boothSwitch(String(localized: "水平仪"), glyph: .level(model.leveler), on: model.leveler, state: model.leveler ? on : off,
                        identifier: "camera-deck-leveler") { model.toggleLeveler() }
                .deckKey(booth.switches[2])
        }
        Button { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } } label: { Color.clear }
            .buttonStyle(BoothPushStyle(shape: model.shape, state: model.shape.title))
            .accessibilityLabel(CameraShellSkin.booth.shapeTitle)
            .accessibilityValue(model.shape.title)
            .accessibilityIdentifier("camera-deck-aspect")
            .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
            .deckKey(booth.aspect)
        boothTone(booth)
    }
    private func boothSwitch(_ name: String, glyph: ShellGlyph, on: Bool, state: String, identifier: String, action: @escaping () -> Void) -> some View {
        Button(action: action) { Color.clear }
            .buttonStyle(BoothSwitchStyle(glyph: glyph, on: on))
            .accessibilityLabel(name)
            .accessibilityValue(state)
            .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier(identifier)
    }
    /// 浓淡: − and ＋ round the dots, its step in the window as a row of
    /// cells (the body shown's).
    @ViewBuilder private func boothTone(_ booth: BoothLayout) -> some View {
        let target = model.shownBody
        let step: Int? = target == .native ? nil : model.strengthStep(of: target)
        let words = step.map { CameraBodyStrength.title($0) } ?? "—"
        let word = String(localized: "浓淡")
        BoothToneFace(step: step, narrow: booth.narrow).equatable()
            .deckPlaced(booth.tone)
        Button { model.stepBodyStrength(-1) } label: { Text(verbatim: "−").font(.system(size: 17, weight: .black, design: .rounded)) }
            .buttonStyle(BoothCandyStyle(tone: BoothPaint.lilac, radius: 11, inset: BoothLayout.collar(booth.toneMinus, booth.toneMinusCap)))
            .accessibilityLabel(word + " −")
            .accessibilityValue(words)
            .accessibilityIdentifier("camera-deck-strength-minus")
            .deckKey(booth.toneMinus)
        Button { model.stepBodyStrength(1) } label: { Text(verbatim: "＋").font(.system(size: 15, weight: .black, design: .rounded)) }
            .buttonStyle(BoothCandyStyle(tone: BoothPaint.lilac, radius: 11, inset: BoothLayout.collar(booth.tonePlus, booth.tonePlusCap)))
            .accessibilityLabel(word + " +")
            .accessibilityValue(words)
            .accessibilityIdentifier("camera-deck-strength-plus")
            .deckKey(booth.tonePlus)
    }

    /// The outlet (相册), 拍照 / 录像, 主菜单, and the door with 换机型.
    @ViewBuilder private func boothLower(_ booth: BoothLayout) -> some View {
        BoothOutlet(model: model, thumbnails: thumbnails, small: booth.across, size: booth.outlet.size)
            .deckKey(booth.outlet)
        boothModeSlide(booth)
        Button { model.leave() } label: { BoothHomeLabel(size: booth.across ? 18 : 21) }
            .buttonStyle(BoothCandyStyle(tone: BoothPaint.lilac, radius: booth.across ? 12 : 14, inset: BoothLayout.collar(booth.home, booth.homeCap)))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(booth.home)
        Button { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } } label: { Color.clear }
            .buttonStyle(BoothDoorStyle(small: booth.across, open: model.bodiesOpen))
            .accessibilityLabel(String(localized: "切换机型"))
            .accessibilityValue(model.body.title)
            .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-bodies")
            .deckKey(booth.door)
    }
    private func boothModeSlide(_ booth: BoothLayout) -> some View {
        let video = model.mode == .video
        return BoothModeSlide(video: video) { next in model.setMode(next ? .video : .photo) }
            .accessibilityElement()
            .accessibilityLabel(String(localized: "拍照") + " / " + String(localized: "录像"))
            .accessibilityValue(video ? String(localized: "录像") : String(localized: "拍照"))
            .accessibilityAddTraits(.isButton)
            .accessibilityAction { model.setMode(video ? .photo : .video) }
            .accessibilityIdentifier("camera-deck-mode")
            .deckKey(booth.mode)
    }

    /// The grip's side: 内 / 外, the countdown lamps, the shutter.
    @ViewBuilder private func boothGrip(_ booth: BoothLayout) -> some View {
        BoothFlipKey(layout: booth, side: model.side == .inner ? String(localized: "内侧") : String(localized: "外侧"), off: model.lens == .merge,
                     why: String(localized: "合体时相机会自己换：先外侧，再内侧")) { model.switchSide() }
        boothTimer(booth)
        boothShutter(booth)
    }
    private func boothTimer(_ booth: BoothLayout) -> some View {
        let show: BoothCountShow
        if let left = model.countdown {
            show = .count(left)
        } else if model.timer == .off {
            show = .off
        } else {
            show = .set(model.timer.rawValue)
        }
        return Button { model.cycleTimer() } label: { Color.clear }
            .buttonStyle(BoothBoxStyle(show: show))
            .accessibilityLabel(String(localized: "定时"))
            .accessibilityValue(model.countdown.map { String(localized: "还有 \($0) 秒") } ?? model.timer.title)
            .accessibilityIdentifier("camera-deck-timer")
            .deckKey(booth.timer)
    }
    /// 拍照: pink (red for a video, breathing while one is taken); its glow
    /// spreads while the self-timer counts. (Pressed while it counts, it does
    /// what the shutter does on every back.)
    private func boothShutter(_ booth: BoothLayout) -> some View {
        let video = model.mode == .video
        let halo: Double = model.countdown != nil ? 1.35 : (model.canShoot || model.recording ? 1 : 0.45)
        let style = BoothArcadeStyle(tone: video ? BoothPaint.cherry : BoothPaint.pink, radius: booth.shutterRadius, halo: halo, travel: 4,
                                     pulse: model.recording, sound: .keyRubber, scale: 0.9, haptic: .faceButton)
        return Button { model.shutter() } label: {
            BoothShutterLabel(video: video, recording: model.recording, time: CameraAppModel.clock(model.recordedSeconds), radius: booth.shutterRadius)
        }
        .buttonStyle(style)
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
        .deckKey(booth.shutter)
    }
}

// MARK: - The VCD set's back

/// The VCD set's colours (mock/vc7.js): the walnut of the cabinet it all
/// stands on, the television's silver, the disc player's champagne gold and
/// its keys', the remote's black and its rubber keys' grey, the yellow 机型
/// key and the red ones, the fluorescent display's cyan-green and its red,
/// the set's own on-screen green, the chosen zoom stop's teal, the disc
/// menu's blue, its yellow words and the chosen picture's frame, the lamps.
enum VcdPaint {
    static let wood = ShellTone(r: 0.408, g: 0.251, b: 0.157)
    static let silver = ShellTone(r: 0.796, g: 0.808, b: 0.827)
    static let gold = ShellTone(r: 0.851, g: 0.761, b: 0.580)
    static let goldKey = ShellTone(r: 0.898, g: 0.824, b: 0.655)
    static let goldInk = Color(red: 0.231, green: 0.165, blue: 0.063)
    static let remote = ShellTone(r: 0.133, g: 0.137, b: 0.157)
    static let rubber = ShellTone(r: 0.808, g: 0.820, b: 0.839)
    static let rubberInk = Color(red: 0.114, green: 0.125, blue: 0.149)
    static let rubberSoft = Color(red: 0.310, green: 0.337, blue: 0.380)
    static let yellow = ShellTone(r: 0.965, g: 0.788, b: 0.290)
    static let yellowInk = Color(red: 0.227, green: 0.149, blue: 0.0)
    static let red = ShellTone(r: 0.839, g: 0.196, b: 0.165)
    static let glow = Color(red: 0.494, green: 0.965, blue: 0.867)
    static let glowRed = Color(red: 1.0, green: 0.365, blue: 0.294)
    static let glowInk = Color(red: 0.020, green: 0.129, blue: 0.106)
    static let osd = Color(red: 0.612, green: 1.0, blue: 0.439)
    static let chip = Color(red: 0.059, green: 0.620, blue: 0.545)
    static let menuTop = Color(red: 0.165, green: 0.275, blue: 0.651)
    static let menuFoot = Color(red: 0.055, green: 0.106, blue: 0.337)
    static let menuWord = Color(red: 1.0, green: 0.890, blue: 0.416)
    static let picked = Color(red: 1.0, green: 0.847, blue: 0.290)
    static let power = ShellTone(r: 0.353, g: 0.882, b: 0.471)
    static let play = ShellTone(r: 0.314, g: 0.902, b: 0.431)
