        let size: CGFloat = small ? 16 : 19
        let faint: Color = paint.soft.color().opacity(0.6)
        let photoInk: Color = video ? faint : paint.ink.color()
        let videoInk: Color = video ? Mp4Paint.red : faint
        HStack(spacing: small ? 4 : 6) {
            ShellGlyphView(glyph: .photo(!video), size: size, ink: photoInk)
            ShellGlyphView(glyph: .video(video), size: size, ink: videoInk)
