/// ▸ 相册 (two pictures); in 相册 a camera over 回去拍照 (its words kept).
private struct Mp4AlbumLabel: View {
    var back: Bool
    var small: Bool
    var paint: Mp4Paint
    var body: some View {
        if back {
            ShellGlyphLabel(glyph: .returnToShooting, words: String(localized: "回去拍照"), size: small ? 14 : 17, wordSize: small ? 12 : 14,
                            ink: paint.ink.color(), stacked: true)
                .padding(.horizontal, 4)
        } else {
            ShellGlyphView(glyph: .album, size: small ? 19 : 23, ink: paint.ink.color())
        }
