    var body: some View {
        ShellGlyphView(glyph: .changeBody, size: small ? 22 : 27, ink: paint.ink.color())
    }
}

/// The sign on a petal of the five-way key.
private enum Mp4Sign: Equatable { case plus, minus, back, forward, up, down }

/// One petal of the five-way key: its sign and its glyph (either may be
/// left out), what VoiceOver calls it, how it stands, its name for the
/// tests, whether it waits (and why), what it does.
private struct Mp4PadPart {
    var sign: Mp4Sign? = nil
    var mark: Mp4PetalMark? = nil
    var label: String
    var value = ""
    var identifier: String
    var off = false
    var why = ""
    var action: () -> Void
}

/// The five-way key's middle (OK): a small line over its glyph (OK while
/// taking pictures; none in 相册), the glyph red to stop a video, and the
/// rest as a petal's.
private struct Mp4PadMiddle {
    var top = ""
    var glyph: ShellGlyph
    var red = false
    var label: String
    var value = ""
    var identifier: String
    var off = false
    var why = ""
    var haptic: HapticPart = .faceButton
    var action: () -> Void
}

/// A part of the five-way key or of VOL as a key: it tells the key it
/// belongs to that it is down, and sounds and is felt as it goes down.
private struct Mp4TouchStyle: ButtonStyle {
    var sound: ConsoleSound = .phoneSoft
    var scale: Float = 0.7
    var haptic: HapticPart = .dpad
    var press: (Bool) -> Void = { _ in }
    func makeBody(configuration: Configuration) -> some View { Mp4TouchBody(configuration: configuration, style: self) }
}
private struct Mp4TouchBody: View {
    let configuration: ButtonStyle.Configuration
    let style: Mp4TouchStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .padding(room)
            .contentShape(Rectangle())
            .onChange(of: down) { _, now in
                style.press(now)
                guard now else { return }
                ConsoleSounds.shared.play(style.sound, scale: style.scale)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// What is on a petal: its sign and its glyph (the glyph over the sign on
/// the lower petal); a sign with no glyph by it a little larger.
private struct Mp4PetalMarks: View {
    var sign: Mp4Sign?
    var mark: Mp4PetalMark?
    var under: Bool
    var ink: Color
    var body: some View {
        VStack(spacing: 2) {
            if under {
                glyph
                arrows
            } else {
                arrows
                glyph
            }
        }
        .fixedSize()
    }
    /// How much larger a sign stands with no glyph by it (◀◀ ▶▶ in 相册).
    private var grow: CGFloat { mark == nil ? 1.35 : 1 }
    @ViewBuilder private var glyph: some View {
        if let mark {
            Mp4MarkView(mark: mark, size: 17, ink: ink)
        }
    }
    @ViewBuilder private var arrows: some View {
        if let sign {
            switch sign {
            case .plus:
                Text(verbatim: "＋").font(.system(size: 14 * grow, weight: .black, design: .rounded)).foregroundStyle(ink)
            case .minus:
                Text(verbatim: "－").font(.system(size: 14 * grow, weight: .black, design: .rounded)).foregroundStyle(ink)
            case .back:
                HStack(spacing: -1) {
                    ClamArrow(way: 3).fill(ink).frame(width: 7 * grow, height: 8 * grow)
                    ClamArrow(way: 3).fill(ink).frame(width: 7 * grow, height: 8 * grow)
                }
            case .forward:
                HStack(spacing: -1) {
                    ClamArrow(way: 1).fill(ink).frame(width: 7 * grow, height: 8 * grow)
                    ClamArrow(way: 1).fill(ink).frame(width: 7 * grow, height: 8 * grow)
                }
            case .up:
                ClamArrow(way: 0).fill(ink).frame(width: 9 * grow, height: 7 * grow)
            case .down:
                ClamArrow(way: 2).fill(ink).frame(width: 9 * grow, height: 7 * grow)
            }
        }
    }
}

/// What OK shows: OK over its glyph (a camera; a dot in a ring for a video,
/// the square — red — to stop one); in 相册 the glyph alone, larger.
private struct Mp4MiddleLabel: View {
    var top: String
    var glyph: ShellGlyph
    var red: Bool
    var paint: Mp4Paint
    var small: Bool
    var body: some View {
        let size: CGFloat = top.isEmpty ? (small ? 18 : 20) : (small ? 15 : 17)
        let ink: Color = red ? Mp4Paint.red : paint.ink.color()
        VStack(spacing: 1) {
            if !top.isEmpty {
                Text(verbatim: top).font(.system(size: 10, weight: .black, design: .rounded)).foregroundStyle(paint.soft.color())
                    .lineLimit(1)
            }
            ShellGlyphView(glyph: glyph, size: size, ink: ink)
        }
        .padding(.horizontal, 2)
    }
}

/// The five-way key's face: its ring of light, its well, the four petals
/// and OK, the part held down drawn down. Drawn once for each way it stands.
private struct Mp4PadFace: View, Equatable {
    var radius: CGFloat
    var ring: CGFloat
    var paint: Mp4Paint
    var glow: Mp4Glow
    /// The part held down: 0 up, 1 right, 2 down, 3 left, 4 OK.
    var held: Int?
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2)
            let light = Mp4Art.light(glow, paint)
            Mp4Art.padRing(context, c, radius, ring, paint, light)
            for index in 0..<4 {
                Mp4Art.petal(context, c, radius, ring, index, paint, light, held: held == index)
            }
            Mp4Art.ok(context, c, radius, paint, light, down: held == 4)
        }
    }
}

/// The five-way key: four separate petals round a round OK, in a soft ring
/// of light. Each petal is a key of its own; pressed, it sinks and the light
/// on its side flares, with a plastic tick and the player's beep; OK sinks
/// whole, its glow turning cream.
private struct Mp4Pad: View {
    var layout: Mp4Layout
    var paint: Mp4Paint
    var glow: Mp4Glow
    var parts: [Mp4PadPart]
    var middle: Mp4PadMiddle
    @State private var down: Int? = nil

    private static func way(_ index: Int) -> CGVector {
        switch index {
        case 0: return CGVector(dx: 0, dy: -1)
        case 1: return CGVector(dx: 1, dy: 0)
        case 2: return CGVector(dx: 0, dy: 1)
        default: return CGVector(dx: -1, dy: 0)
        }
    }
    var body: some View {
        let l = layout
        ZStack(alignment: .topLeading) {
            Mp4PadFace(radius: l.padRadius, ring: l.padRing, paint: paint, glow: glow, held: down).equatable()
                .frame(width: l.pad.width, height: l.pad.height)
                .allowsHitTesting(false)
                .accessibilityHidden(true)
            ForEach(0..<4, id: \.self) { index in
                if parts.indices.contains(index), l.petals.indices.contains(index) {
                    petal(index, parts[index], l.petals[index])
                }
            }
            if l.petals.count > 4 {
                centre(l.petals[4])
            }
        }
        .frame(width: l.pad.width, height: l.pad.height, alignment: .topLeading)
    }
    private func petal(_ index: Int, _ part: Mp4PadPart, _ rect: CGRect) -> some View {
        let c = layout.padCentre, r = layout.padRadius, v = Self.way(index)
        let mark: CGPoint = index % 2 == 0 ? CGPoint(x: c.x, y: c.y + v.dy * (r - 25)) : CGPoint(x: c.x + v.dx * r * 0.69, y: c.y + 0.75)
        let held = down == index
        let lean = CGSize(width: held ? v.dx * 1.5 : 0, height: held ? v.dy * 1.5 : 0)
        return Button(action: part.action) {
            Mp4PetalMarks(sign: part.sign, mark: part.mark, under: index == 2, ink: paint.ink.color())
                .offset(x: mark.x - rect.midX + lean.width, y: mark.y - rect.midY + lean.height)
        }
        .buttonStyle(Mp4TouchStyle(sound: .phoneSoft, scale: 0.7, haptic: .dpad, press: { now in
            if now { down = index } else if down == index { down = nil }
        }))
        .accessibilityLabel(part.label)
        .accessibilityValue(part.value)
        .accessibilityIdentifier(part.identifier)
        .deckDimmed(part.off, why: part.why)
        .frame(width: rect.width, height: rect.height)
        .position(x: rect.midX, y: rect.midY)
    }
    private func centre(_ rect: CGRect) -> some View {
        let m = middle
        let sink: CGFloat = down == 4 ? 1.3 : 0
        return Button(action: m.action) {
            Mp4MiddleLabel(top: m.top, glyph: m.glyph, red: m.red, paint: paint, small: layout.across)
                .offset(y: sink)
        }
        .buttonStyle(Mp4TouchStyle(sound: .keyRubber, scale: 0.6, haptic: m.haptic, press: { now in
            if now { down = 4 } else if down == 4 { down = nil }
        }))
        .accessibilityLabel(m.label)
        .accessibilityValue(m.value)
        .accessibilityIdentifier(m.identifier)
        .deckDimmed(m.off, why: m.why)
        .frame(width: rect.width, height: rect.height)
        .position(x: rect.midX, y: rect.midY)
    }
}

/// The five steps of 浓淡 on VOL (as many filled as it is strong).
private struct Mp4Steps: View {
    var level: Int
    var on: Color
    var off: Color
    var body: some View {
        HStack(alignment: .bottom, spacing: 3) {
            ForEach(0..<5, id: \.self) { index in
                let tall = 4 + 2.2 * CGFloat(index)
                if index < level {
                    RoundedRectangle(cornerRadius: 1.2).fill(on).frame(width: 5, height: tall)
                } else {
                    RoundedRectangle(cornerRadius: 1.2).strokeBorder(off, lineWidth: 1).frame(width: 5, height: tall)
                }
            }
        }
        .frame(height: 14, alignment: .bottom)
    }
}

/// VOL: one bar of jelly plastic whose either end presses (浓淡 − and ＋,
/// its glyphs at the ends): the end pressed goes down and darker, the other
/// comes up a little, with a beep a step lower or higher and a notch's
/// feel. 浓淡's steps between the ends.
private struct Mp4Rocker: View {
    var layout: Mp4Layout
    var paint: Mp4Paint
    var level: Int
    var off: Bool
    var ends: [DigiRockerEnd]
    @State private var tip = 0
    var body: some View {
        let w = layout.rocker.width, h = layout.rocker.height
        ZStack(alignment: .topLeading) {
            face(w, h)
            ForEach(0..<2, id: \.self) { index in
                if ends.indices.contains(index), layout.rockerEnds.indices.contains(index) {
                    end(index, ends[index], layout.rockerEnds[index])
                }
            }
        }
        .frame(width: w, height: h, alignment: .topLeading)
    }
    private func face(_ w: CGFloat, _ h: CGFloat) -> some View {
        let shade = Mp4Art.darker(paint.glow, 0.3).color().opacity(0.3)
        let strength: Double = off ? 0.25 : (tip != 0 ? 1.3 : 0.8)
        return ZStack {
            Mp4JellyFace(radius: h / 2, tone: paint.key, glow: paint.glow, down: false, lit: false).equatable()
            if tip != 0 {
                Capsule().fill(LinearGradient(colors: [shade, Color.clear, Color.white.opacity(0.35)],
                                              startPoint: tip < 0 ? .leading : .trailing, endPoint: tip < 0 ? .trailing : .leading))
            }
            legends(w, h).opacity(off ? 0.45 : 1)
        }
        .frame(width: w, height: h)
        .background(Mp4KeyBed(radius: h / 2, glow: paint.glow, strength: strength, plastic: paint.body))
        .animation(.easeOut(duration: 0.06), value: tip)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
    private func legends(_ w: CGFloat, _ h: CGFloat) -> some View {
        let ink = paint.ink.color(), soft = paint.soft.color(), e = layout.rockerInset
        let size: CGFloat = layout.across ? 18 : 20
        return ZStack(alignment: .topLeading) {
            ShellGlyphView(glyph: .toneDown, size: size, ink: ink).fixedSize().position(x: e, y: h / 2)
            ShellGlyphView(glyph: .toneUp, size: size, ink: ink).fixedSize().position(x: w - e, y: h / 2)
            Mp4Steps(level: level, on: paint.accent.color(), off: soft).position(x: w / 2, y: h / 2)
        }
        .frame(width: w, height: h, alignment: .topLeading)
        .accessibilityHidden(true)
    }
    private func end(_ index: Int, _ one: DigiRockerEnd, _ rect: CGRect) -> some View {
        let way = index == 0 ? -1 : 1
        return Button(action: one.action) { Color.clear }
            .buttonStyle(Mp4TouchStyle(sound: index == 0 ? .move : .tick, scale: 0.6, haptic: .sliderNotch, press: { now in
                if now { tip = way } else if tip == way { tip = 0 }
            }))
            .accessibilityLabel(one.label)
            .accessibilityValue(one.value)
            .accessibilityIdentifier(one.identifier)
            .deckDimmed(one.off, why: one.why)
            .frame(width: rect.width, height: rect.height)
            .position(x: rect.midX, y: rect.midY)
    }
}

/// The slide (内 / 外) in its sunk track: a glossy thumb that carries the
/// word for where it sits, the other word showing in the track at the far
/// end; upright a tall slide, held across a short one lying on its side.
private struct Mp4SlideFace: View {
    var paint: Mp4Paint
    var inner: Bool
    var down: Bool
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            let tall = h > w
            let at: CGFloat = inner ? 1 : 0
            let tw: CGFloat = tall ? w - 4 : w * 0.56
            let th: CGFloat = tall ? h * 0.56 : h - 4
            let nudge: CGFloat = down ? (inner ? -3 : 3) : 0
            let tx: CGFloat = tall ? 2 : 2 + (w - 4 - tw) * at + nudge
            let ty: CGFloat = tall ? 2 + (h - 4 - th) * at + nudge : 2
            let farX: CGFloat = tall ? w / 2 : (inner ? (w - tw) / 2 : w - (w - tw) / 2)
            let farY: CGFloat = tall ? (inner ? (h - th) / 2 : h - (h - th) / 2) : h / 2
            let outerWord = String(localized: "外"), innerWord = String(localized: "内")
            ZStack(alignment: .topLeading) {
                Capsule().fill(LinearGradient(colors: [Mp4Art.darker(paint.body, 0.38).color(), Mp4Art.darker(paint.body, 0.18).color()], startPoint: .top, endPoint: .bottom))
                    .overlay(Capsule().strokeBorder(Mp4Paint.shade.opacity(0.45), lineWidth: 1))
                    .overlay(Capsule().stroke(Color.white.opacity(0.55), lineWidth: 0.8).offset(y: 0.7))
                    .frame(width: w, height: h)
                Text(inner ? outerWord : innerWord).font(.system(size: tall ? 11 : 10, weight: .black, design: .rounded))
                    .foregroundStyle(Color.white.opacity(0.85))
                    .fixedSize()
                    .position(x: farX, y: farY + 0.5)
                Mp4JellyFace(radius: min(tw, th) / 2, tone: paint.key, glow: paint.glow, down: false, lit: false).equatable()
                    .overlay {
                        Text(inner ? innerWord : outerWord).font(.system(size: tall ? 12 : 10.5, weight: .black, design: .rounded))
                            .foregroundStyle(paint.ink.color())
                    }
                    .frame(width: tw, height: th)
                    .shadow(color: Mp4Paint.shade.opacity(0.28), radius: 1.5, y: 1.5)
                    .offset(x: tx, y: ty)
            }
            .frame(width: w, height: h, alignment: .topLeading)
        }
    }
}

/// 内 / 外 going over: the thumb nudged toward the other end while held,
/// over at the other end once the camera has changed (at once with Reduce
/// Motion), with the slide's click and a notch's feel. Held across it is a
/// key of its own, a camera turning on it over the slide lying in it (the
/// slide keeps its 外 and 内).
private struct Mp4FlipStyle: ButtonStyle {
    var paint: Mp4Paint
    /// The slide's track, within the key's place.
    var slot: CGRect
    var inner: Bool
    var plate: Bool
    var radius: CGFloat
    func makeBody(configuration: Configuration) -> some View { Mp4FlipBody(configuration: configuration, style: self) }
}
private struct Mp4FlipBody: View {
    let configuration: ButtonStyle.Configuration
    let style: Mp4FlipStyle
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let down = configuration.isPressed
        let paint = style.paint
        ZStack(alignment: .topLeading) {
            if style.plate {
                Mp4JellyFace(radius: style.radius, tone: paint.key, glow: paint.glow, down: false, lit: false).equatable()
                    .background(Mp4KeyBed(radius: style.radius, glow: paint.glow, strength: 0.5, plastic: paint.body))
                ShellGlyphView(glyph: .flip, size: 14, ink: paint.ink.color())
                    .frame(maxWidth: .infinity)
                    .padding(.top, 5)
            }
            Mp4SlideFace(paint: paint, inner: style.inner, down: down)
                .frame(width: style.slot.width, height: style.slot.height)
                .offset(x: style.slot.minX, y: style.slot.minY)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(reduceMotion ? nil : .easeOut(duration: 0.12), value: style.inner)
        .animation(.easeOut(duration: 0.07), value: down)
        .onChange(of: down) { _, now in
            guard now else { return }
            ConsoleSounds.shared.play(.keySlide, scale: 0.8)
            ConsoleHaptics.shared.play(.sliderNotch, .press)
        }
    }
}

/// 内 / 外 as a key (placed and dimmed where it is used).
private struct Mp4FlipKey: View {
    var layout: Mp4Layout
    var paint: Mp4Paint
    var inner: Bool
    var action: () -> Void
    var body: some View {
        let l = layout
        let slot = CGRect(x: l.slide.minX - l.flip.minX, y: l.slide.minY - l.flip.minY, width: l.slide.width, height: l.slide.height)
        Button(action: action) { Color.clear }
            .buttonStyle(Mp4FlipStyle(paint: paint, slot: slot, inner: inner, plate: l.across, radius: l.pebbleRadius))
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(inner ? String(localized: "内侧") : String(localized: "外侧"))
            .accessibilityIdentifier("camera-deck-switch")
    }
}

/// What the big round key shows: a camera; a red dot for a video, a red
/// square while one is taken.
private enum Mp4ShutterSign: Equatable { case camera, record, stop }

/// The big round key's face: a halo of light, a pearl collar, a jelly dome
/// in its well; down, the dome sinks and the halo turns cream, thicker and
/// brighter. (Drawn larger than the key, for its halo.)
private struct Mp4ShutterFace: View, Equatable {
    var paint: Mp4Paint
    var radius: CGFloat
    var light: ShellTone
    var down: Bool
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            let glow: ShellTone = down ? Mp4Paint.lamp : light
            func circle(_ q: CGFloat, _ dy: CGFloat = 0) -> Path { Path(ellipseIn: CGRect(x: c.x - q, y: c.y + dy - q, width: 2 * q, height: 2 * q)) }
            var halo = context
            halo.addFilter(.shadow(color: glow.color().opacity(0.95), radius: down ? 12 : 7.5))
            halo.stroke(circle(r + 4.5), with: .color(glow.color(0.3).opacity(0.9)), lineWidth: down ? 4 : 3)
            context.stroke(circle(r + 4.5), with: .color(Color.white.opacity(0.75)), lineWidth: 0.9)
            var collar = context
            collar.addFilter(.shadow(color: Mp4Paint.shade.opacity(0.35), radius: 2, x: 0, y: 1.5))
            collar.fill(circle(r + 2.2), with: .linearGradient(Mp4Paint.pearl, startPoint: CGPoint(x: c.x - r, y: c.y - r), endPoint: CGPoint(x: c.x + r, y: c.y + r)))
            context.fill(circle(r - 2, 0.5), with: .color(Mp4Art.darker(paint.body, 0.36).color()))
            let q = max(4, r - 4 - (down ? 1.2 : 0)), dy: CGFloat = down ? 1.4 : 0
            let tone = paint.shutter
            let middle: ShellTone = down ? Mp4Art.darker(tone, 0.04) : tone
            let fill = Gradient(stops: [Mp4Art.stop(Mp4Art.mix(tone, glow, down ? 0.5 : 0.3).color(), 0), Mp4Art.stop(middle.color(), 0.65),
                                        Mp4Art.stop(Mp4Art.darker(tone, 0.1).color(), 1)])
            var dome = context
            dome.addFilter(.shadow(color: Mp4Paint.shade.opacity(0.3), radius: down ? 0.5 : 1.5, x: 0, y: down ? 0.4 : 1.5))
            dome.fill(circle(q, dy), with: .radialGradient(fill, center: CGPoint(x: c.x, y: c.y + dy + q * 0.4), startRadius: q * 0.1, endRadius: q * 1.15))
            let shine = Path(ellipseIn: CGRect(x: c.x - q * 0.72, y: c.y + dy - q * 0.85, width: q * 1.44, height: q * 0.84))
            context.fill(shine, with: .linearGradient(Gradient(colors: [Color.white.opacity(down ? 0.6 : 0.92), Color.white.opacity(0.05)]),
                                                      startPoint: CGPoint(x: 0, y: c.y + dy - q * 0.86), endPoint: CGPoint(x: 0, y: c.y + dy)))
            context.stroke(circle(q - 0.6, dy), with: .color(Color.white.opacity(0.9)), lineWidth: 1)
        }
    }
}

private struct Mp4ShutterStyle: ButtonStyle {
    var paint: Mp4Paint
    var radius: CGFloat
    var light: ShellTone
    var haptic: HapticPart
    func makeBody(configuration: Configuration) -> some View { Mp4ShutterBody(configuration: configuration, style: self) }
}
private struct Mp4ShutterBody: View {
    let configuration: ButtonStyle.Configuration
    let style: Mp4ShutterStyle
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .offset(y: down ? 1.4 : 0)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(Mp4ShutterFace(paint: style.paint, radius: style.radius, light: style.light, down: down).equatable().padding(-14))
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.07 : 0.12), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.keyRubber, scale: 0.9)
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// What is on the big round key.
private struct Mp4ShutterMark: View {
    var sign: Mp4ShutterSign
    var ink: Color
    var size: CGFloat
    var body: some View {
        switch sign {
        case .camera:
            Image(systemName: "camera.fill").font(.system(size: size * 0.62, weight: .bold)).foregroundStyle(ink)
        case .record:
            Circle().fill(Mp4Paint.red).frame(width: size * 0.5, height: size * 0.5)
        case .stop:
            RoundedRectangle(cornerRadius: 2.2, style: .continuous).fill(Mp4Paint.red).frame(width: size * 0.45, height: size * 0.45)
        }
    }
}

/// The big round key as a key (placed, named and dimmed where it is used).
private struct Mp4ShutterKey: View {
    var paint: Mp4Paint
    var radius: CGFloat
    var sign: Mp4ShutterSign
    var light: ShellTone
    var ready = true
    var haptic: HapticPart = .faceButton
    var action: () -> Void
    var body: some View {
        Button(action: action) {
            Mp4ShutterMark(sign: sign, ink: paint.ink.color(), size: radius).opacity(ready ? 1 : 0.45)
        }
        .buttonStyle(Mp4ShutterStyle(paint: paint, radius: radius, light: light, haptic: haptic))
    }
}

/// The big round key's word, printed under it (beside it held across).
private struct Mp4Caption: View {
    var word: String
    var colour: Color
    var side: CGFloat
    var body: some View {
        let alignment: Alignment = side < 0 ? .trailing : (side > 0 ? .leading : .center)
        let lines: TextAlignment = side < 0 ? .trailing : (side > 0 ? .leading : .center)
        Text(word).font(.system(size: 11, weight: .black, design: .rounded)).foregroundStyle(colour)
            .multilineTextAlignment(lines)
            .lineLimit(2)
            .minimumScaleFactor(0.7)
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: alignment)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

extension CameraDeckFace {
    /// The colour the MP4 player is worn in.
    var mp4Paint: Mp4Paint { Mp4Paint.named(model.shellTints[CameraShellSkin.mp4.rawValue]) }
    /// What its lights show now.
    private var mp4Glow: Mp4Glow { model.recording ? .recording : (model.countdown != nil ? .counting : .plain) }

    /// The MP4 player's body under its keys (a new colour fades in), and the
    /// light round its edge.
    func mp4Backdrop(_ mp4: Mp4Layout) -> some View {
        let paint = mp4Paint
        return ZStack {
            Mp4Backdrop(layout: mp4, paint: paint, hinge: hinge).equatable()
                .id(paint.name)
                .transition(.opacity)
            Mp4EdgeLight(paint: paint, glow: mp4Glow, beat: model.countdown)
        }
    }

    /// The glass over the picture's edge; the screen's status bar over the
    /// picture and its keys' hints under it (nothing lies on the picture but
    /// the zoom stops); the lamp in the glass's corner.
    @ViewBuilder func mp4Screen(_ mp4: Mp4Layout) -> some View {
        let paint = mp4Paint
        Mp4Glass(glass: mp4.glass, radius: mp4.glassRadius, hole: layout.picture).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        mp4LiveBars(mp4, paint)
            .deckPlaced(mp4.screen)
        DigiLamp(tone: model.recording ? Mp4Paint.recordLight : Mp4Paint.lamp, radius: 1.7)
            .frame(width: 8, height: 8)
            .position(mp4.lamp)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }

    private func mp4LiveBars(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        let video = model.mode == .video
        let target = model.shownBody
        let level = target == .native ? 0 : min(5, max(0, model.strengthStep(of: target) + 3))
        let seconds: String = model.countdown.map { String($0) } ?? (model.timer == .off || video ? "" : String(model.timer.rawValue))
        let status = Mp4LiveStatus(video: video, recording: model.recording, time: CameraAppModel.clock(model.recordedSeconds), lens: model.lens.title,
                                   timer: seconds, level: level, ink: paint.barInk.color())
        return Mp4LiveBars(paint: paint, status: status, hints: mp4LiveHints(video: video, wide: mp4.screen.width >= 300))
    }

    /// The lower bar's hints, each keycap with the glyph its key shows: OK a
    /// camera (a dot in a ring for a video, the square to stop one), ◀▶ the
    /// lenses' circles, ▲▼ a magnifying glass, MENU a house; while the
    /// self-timer counts, how long it still waits.
    private func mp4LiveHints(video: Bool, wide: Bool) -> [Mp4Hint] {
        let menu = Mp4Hint(cap: .word("MENU"), words: "", mark: .glyph(.home))
        if let left = model.countdown {
            let seconds = String(localized: "\(left) 秒")
            return [Mp4Hint(cap: nil, words: String(localized: "定时 · \(seconds)后拍照")), menu]
        }
        let shoot: ShellGlyph = video ? (model.recording ? .stop : .record) : .photo(true)
        let ok = Mp4Hint(cap: .word("OK"), words: "", mark: .glyph(shoot))
        let lens = Mp4Hint(cap: .sides, words: "", mark: .lenses)
        let zoom = Mp4Hint(cap: .ends, words: "", mark: .glyph(.zoom))
        return model.recording || !wide ? [ok, lens, zoom] : [ok, lens, zoom, menu]
    }

    /// The MP4 player, upright or across (the same keys, each where its hold
    /// has it): the five small lit keys (定时, 日期, 画幅, 水平仪, 闪光);
    /// MENU (主菜单), M (拍照 / 录像), ▸ 相册 and 机型; the five-way key (up
    /// and down the zoom, left and right the lenses, OK takes the picture);
    /// VOL (浓淡); 内 / 外; the big round key; the colour's dot.
    @ViewBuilder func mp4Face(_ mp4: Mp4Layout) -> some View {
        let paint = mp4Paint
        mp4LitKeys(mp4, paint)
        mp4Pebbles(mp4, paint)
        mp4Pad(mp4, paint)
        mp4Rocker(mp4, paint)
        mp4Flip(mp4, paint)
        mp4Shutter(mp4, paint)
        mp4Tint(mp4)
    }

    /// The five lit keys, each glyph drawn as it stands (VoiceOver hears its
    /// name and how it stands).
    @ViewBuilder private func mp4LitKeys(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        if mp4.lit.count == 5 {
            let shooting = model.shooting
            let on = String(localized: "开"), off = String(localized: "关")
            let video = model.mode == .video
            let timerWhy = String(localized: "录像时不用定时")
            let timerState: String = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
            let timed = model.timer != .off || model.countdown != nil
            let dated = shooting.dateStamp ? on : off
            let levelled = model.leveler ? on : off
            Mp4LitKey(paint: paint, rect: mp4.lit[0], glyph: .timer(model.timer), name: String(localized: "定时"), state: timerState, on: timed,
                      identifier: "camera-deck-timer") {
                if video { model.say(timerWhy) } else { model.cycleTimer() }
            }
            .deckDimmed(video, why: timerWhy)
            .deckKey(mp4.lit[0])
            Mp4LitKey(paint: paint, rect: mp4.lit[1], glyph: .date(shooting.dateStamp), name: String(localized: "日期"), state: dated,
                      on: shooting.dateStamp, identifier: "camera-deck-date") { model.toggleDateStamp() }
                .deckKey(mp4.lit[1])
            Mp4LitKey(paint: paint, rect: mp4.lit[2], glyph: .shape(model.shape), name: CameraShellSkin.mp4.shapeTitle, state: model.shape.title, on: false,
                      identifier: "camera-deck-aspect") { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } }
                .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
                .deckKey(mp4.lit[2])
            Mp4LitKey(paint: paint, rect: mp4.lit[3], glyph: .level(model.leveler), name: String(localized: "水平仪"), state: levelled,
                      on: model.leveler, identifier: "camera-deck-leveler") { model.toggleLeveler() }
                .deckKey(mp4.lit[3])
            Mp4LitKey(paint: paint, rect: mp4.lit[4], glyph: .flash(shooting.flash), name: String(localized: "闪光"), state: shooting.flash.title,
                      on: shooting.flash != .off, identifier: "camera-deck-flash") { model.cycleFlash() }
                .deckKey(mp4.lit[4])
        }
    }

    /// MENU (主菜单), M (拍照 / 录像: a camera and a video camera), ▸ 相册
    /// (two pictures), 机型 (two cameras traded).
    @ViewBuilder private func mp4Pebbles(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        let small = mp4.across, radius = mp4.pebbleRadius
        let video = model.mode == .video
        let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
        Button { model.leave() } label: { Mp4MenuLabel(small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(mp4.menu)
        Button { model.setMode(video ? .photo : .video) } label: { Mp4ModeLabel(video: video, small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
            .accessibilityLabel(photoWord + " / " + videoWord)
            .accessibilityValue(video ? videoWord : photoWord)
            .accessibilityIdentifier("camera-deck-mode")
            .deckKey(mp4.mode)
        Button { model.openAlbum() } label: { Mp4AlbumLabel(back: false, small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
            .accessibilityLabel(CameraShellSkin.mp4.albumTitle)
            .accessibilityValue(String(localized: "\(model.photos.count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .deckKey(mp4.album)
        Button { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } } label: {
            Mp4BodiesLabel(small: small, paint: paint)
        }
        .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
        .deckKey(mp4.bodies)
    }

    /// The five-way key: up and down the zoom's stops (a magnifying glass
    /// more and less), left and right the lenses (◀◀ ▶▶ by the filters'
    /// circles; round to the first again), OK takes the picture (a video's
    /// start and stop).
    private func mp4Pad(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        let zoomWord = String(localized: "变焦"), lensWord = String(localized: "镜头")
        let factor = Self.zoomText(model.zoom), lens = model.lens.title
        let up = Mp4PadPart(mark: .glyph(.zoomIn), label: zoomWord + " +", value: factor, identifier: "camera-deck-zoom-in") { phoneNavigate(0) }
        let right = Mp4PadPart(sign: .forward, mark: .lenses, label: lensWord + " ›", value: lens, identifier: "camera-deck-lens-next") { mp4StepLens(1) }
        let down = Mp4PadPart(mark: .glyph(.zoomOut), label: zoomWord + " −", value: factor, identifier: "camera-deck-zoom-out") { phoneNavigate(2) }
        let left = Mp4PadPart(sign: .back, mark: .lenses, label: lensWord + " ‹", value: lens, identifier: "camera-deck-lens-previous") { mp4StepLens(-1) }
        let video = model.mode == .video, recording = model.recording
        let shown: ShellGlyph = video ? (recording ? .stop : .record) : .photo(true)
        let said: String = video ? (recording ? String(localized: "停止录像") : String(localized: "开始录像")) : String(localized: "拍照")
        let ready: String = model.canShoot ? (video ? String(localized: "可以录") : String(localized: "可以拍")) : String(localized: "等一下")
        let middle = Mp4PadMiddle(top: "OK", glyph: shown, red: video && recording, label: said, value: ready, identifier: "camera-deck-shutter-centre") { model.shutter() }
        return Mp4Pad(layout: mp4, paint: paint, glow: mp4Glow, parts: [up, right, down, left], middle: middle)
            .deckPlaced(mp4.pad)
    }

    /// The next or the previous lens, round to the first again (only those
    /// that can take a video while 录像 is chosen).
    private func mp4StepLens(_ delta: Int) {
        let all = CameraLens.allCases
        let usable: [CameraLens] = model.mode == .video ? all.filter { $0.records } : Array(all)
        guard !usable.isEmpty else { return }
        let at = usable.firstIndex(of: model.lens) ?? 0
        model.choose(usable[(at + delta % usable.count + usable.count) % usable.count])
    }

    /// VOL: 浓淡 − and ＋ (the body shown's), its steps between them.
    private func mp4Rocker(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        let target = model.shownBody
        let step: Int? = target == .native ? nil : model.strengthStep(of: target)
        let words = step.map { CameraBodyStrength.title($0) } ?? "—"
        let word = String(localized: "浓淡")
        let less = DigiRockerEnd(label: word + " −", value: words, identifier: "camera-deck-strength-minus") { model.stepBodyStrength(-1) }
        let more = DigiRockerEnd(label: word + " +", value: words, identifier: "camera-deck-strength-plus") { model.stepBodyStrength(1) }
        let level = step.map { min(5, max(0, $0 + 3)) } ?? 0
        return Mp4Rocker(layout: mp4, paint: paint, level: level, off: false, ends: [less, more])
            .deckPlaced(mp4.rocker)
    }

    /// 内 / 外 (合体 changes the camera itself; the slide keeps its 外 and 内),
    /// a camera turning under it upright.
    @ViewBuilder private func mp4Flip(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        Mp4FlipKey(layout: mp4, paint: paint, inner: model.side == .inner) { model.switchSide() }
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(mp4.flip)
        if mp4.flipCaption.width > 0 {
            ShellGlyphView(glyph: .flip, size: 14, ink: paint.ink.color())
                .allowsHitTesting(false)
                .deckPlaced(mp4.flipCaption)
        }
    }

    /// 拍照: the big round key (a camera; a red dot for a video, the square
    /// while one is taken — no word by it).
    @ViewBuilder private func mp4Shutter(_ mp4: Mp4Layout, _ paint: Mp4Paint) -> some View {
        let video = model.mode == .video, recording = model.recording
        let sign: Mp4ShutterSign = video ? (recording ? .stop : .record) : .camera
        Mp4ShutterKey(paint: paint, radius: mp4.shutterRadius, sign: sign, light: Mp4Art.light(mp4Glow, paint), ready: model.canShoot || recording) { model.shutter() }
            .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
            .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
            .accessibilityIdentifier("camera-deck-shutter")
            .deckKey(mp4.shutter)
    }

    /// The colour's dot: the player's next colour.
    @ViewBuilder private func mp4Tint(_ mp4: Mp4Layout) -> some View {
        if mp4.tint.width > 0, let now = model.tint(of: .mp4), let next = model.nextTint(of: .mp4) {
            ShellTintKey(now: now, next: next, sound: .phoneSoft) {
                withAnimation(.easeInOut(duration: 0.2)) { model.cycleTint(of: .mp4) }
            }
            .deckKey(mp4.tint)
        }
    }

    /// The MP4 player's 相册, upright and across.
    @ViewBuilder func mp4Album(_ mp4: Mp4Layout) -> some View {
        Mp4Viewer(model: model, thumbnails: thumbnails, mp4: mp4, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The MP4 player's 相册

/// The MP4 player's 相册, as such a player's picture viewer: one picture at
/// a time filling the screen between its bars, the file's name as it is kept
/// on the card and its place over it. The five-way key's sides go to the one
/// before and the one after, ▼ shows nine at a time (九宫格: the sides move
/// among them, ▲ or OK — 看这张 — opens the one chosen whole again), OK
/// plays a video (a picture's waits, and says why) — how far it has played
/// on the lower bar. ▸ 相册 says 回去拍照, lit cream, and it and the big
/// round key go back to taking pictures; MENU and the colour's dot do what
/// they always do; the keys that set the camera wait, and say why.
private struct Mp4Viewer: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var mp4: Mp4Layout
    var hinge: CGRect
    /// Nine at a time (九宫格).
    @State private var many = false
    @State private var push: CGFloat = 0
    /// How long the video has played (counted by the second).
    @State private var elapsed = 0

    private static let page = 9
    private var waiting: String { String(localized: "相册里用不了，回去拍照再用") }
    private var video: Bool { !many && model.albumPhoto?.isVideo == true }
    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private var length: Int { model.albumDuration.map { Int($0.rounded()) } ?? 0 }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    private func sharp(_ photo: CameraPhoto?) -> CGImage? {
        guard let photo else { return nil }
        return (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }
    private func choose(_ next: Int) {
        guard model.photos.indices.contains(next), next != model.albumIndex, model.doodle == nil else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }
    /// The nine, or the one chosen whole again.
    private func showMany(_ on: Bool) {
        guard on != many, !model.photos.isEmpty else { return }
        if on, model.playing != nil { model.togglePlay() }
        many = on
    }

    var body: some View {
        let paint = Mp4Paint.named(model.shellTints[CameraShellSkin.mp4.rawValue])
        ZStack(alignment: .topLeading) {
            Mp4Backdrop(layout: mp4, paint: paint, hinge: hinge).equatable()
                .id(paint.name)
                .transition(.opacity)
            Mp4EdgeLight(paint: paint, glow: .plain, beat: nil)
            screen(paint)
            Mp4Glass(glass: mp4.glass, radius: mp4.glassRadius, hole: mp4.box).equatable()
            bars(paint)
            DigiLamp(tone: Mp4Paint.lamp, radius: 1.7)
                .frame(width: 8, height: 8)
                .position(mp4.lamp)
                .allowsHitTesting(false)
                .accessibilityHidden(true)
            litKeys(paint)
            pebbles(paint)
            pad(paint)
            lower(paint)
        }
        .frame(width: mp4.canvas.width, height: mp4.canvas.height, alignment: .topLeading)
        .task(id: model.playing) { @MainActor in
            elapsed = 0
            guard model.playing != nil else { return }
            while !Task.isCancelled {
                try? await Task.sleep(nanoseconds: 1_000_000_000)
                guard !Task.isCancelled else { return }
                elapsed += 1
            }
        }
    }

    /// What the screen shows between its bars: one picture whole (a video
    /// plays there; a push to the side goes to the next), or the nine;
    /// while a picture is being drawn on inside, that it waits there; what
    /// the player says, for a moment.
    private func screen(_ paint: Mp4Paint) -> some View {
        let photos = model.photos, at = model.albumIndex
        return ZStack {
            Color.black
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
            } else if many {
                nine(photos, at: at, paint: paint)
            } else if photos.indices.contains(at) {
                picture(photos[at])
            }
            if model.doodle != nil {
                Text("正在编辑 · 打开 Duo，在下屏接着画").font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(Color.white)
                    .multilineTextAlignment(.center).lineLimit(2).minimumScaleFactor(0.7)
                    .padding(.horizontal, 12).padding(.vertical, 6)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 16)
                    .accessibilityIdentifier("camera-deck-editing")
            }
            if let toast = model.toast {
                Text(toast).font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(Color.white)
                    .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                    .padding(.horizontal, 10).padding(.vertical, 4)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 14)
                    .frame(maxHeight: .infinity, alignment: .bottom)
                    .padding(.bottom, 8)
                    .allowsHitTesting(false)
                    .transition(.opacity)
            }
        }
        .frame(width: mp4.box.width, height: mp4.box.height)
        .clipped()
        .position(x: mp4.box.midX, y: mp4.box.midY)
    }

    private func picture(_ photo: CameraPhoto) -> some View {
        let image = sharp(photo)
        return ZStack {
            if let image { Image(decorative: image, scale: 1).resizable().scaledToFit() }
            if photo.isVideo {
                #if os(iOS)
                if model.playing == photo.url {
                    CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                        .accessibilityIdentifier("camera-album-player")
                }
                #endif
                if model.playing != photo.url {
                    Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9))
                        .shadow(color: .black.opacity(0.5), radius: 4)
                }
            }
        }
        .frame(width: mp4.box.width, height: mp4.box.height)
        .offset(x: push)
        .contentShape(Rectangle())
        .gesture(DragGesture(minimumDistance: 8)
            .onChanged { push = $0.translation.width }
            .onEnded { value in
                let dx = value.translation.width
                withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                if abs(dx) > 60 { choose(model.albumIndex + (dx < 0 ? 1 : -1)) }
            })
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : CameraShellSkin.mp4.albumTitle)
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    /// 九宫格: the nine the chosen picture is among, three across; the chosen
    /// one larger, in a lit edge; a video's sign (and how long it is) on its corner.
    private func nine(_ photos: [CameraPhoto], at: Int, paint: Mp4Paint) -> some View {
        let w = mp4.box.width, h = mp4.box.height, m: CGFloat = 8
        let cw: CGFloat = max(1, (w - 4 * m) / 3), ch: CGFloat = max(1, (h - 4 * m) / 3)
        let first = (at / Self.page) * Self.page
        let size = CGSize(width: cw, height: ch)
        return ZStack(alignment: .topLeading) {
            LinearGradient(colors: [Color(red: 0.165, green: 0.125, blue: 0.220), Color(red: 0.094, green: 0.071, blue: 0.122)], startPoint: .top, endPoint: .bottom)
            ForEach(0..<Self.page, id: \.self) { slot in
                if photos.indices.contains(first + slot) {
                    cell(photos[first + slot], slot: slot, index: first + slot, chosen: first + slot == at, size: size, paint: paint,
                         middle: CGPoint(x: m + cw / 2 + CGFloat(slot % 3) * (cw + m), y: m + ch / 2 + CGFloat(slot / 3) * (ch + m)))
                }
            }
        }
        .frame(width: w, height: h, alignment: .topLeading)
    }
    private func cell(_ photo: CameraPhoto, slot: Int, index: Int, chosen: Bool, size: CGSize, paint: Mp4Paint, middle: CGPoint) -> some View {
        let grown: CGFloat = chosen ? 1.1 : 1
        let w = size.width * grown, h = size.height * grown
        let box = mp4.box
        let place = CGPoint(x: min(max(middle.x, w / 2 + 3), box.width - w / 2 - 3), y: min(max(middle.y, h / 2 + 3), box.height - h / 2 - 3))
        let shape = RoundedRectangle(cornerRadius: 3, style: .continuous)
        let time: String = chosen && length > 0 ? CameraAppModel.clock(length) : ""
        return Button {
            ConsoleSounds.shared.play(.phoneSoft, scale: 0.6)
            if !chosen { model.chooseInAlbum(index, quiet: true) }
            many = false
        } label: {
            ZStack(alignment: .bottomLeading) {
                Color(white: 0.14)
                if let image = thumbnails.images[photo.url] {
                    Color.clear.overlay(Image(decorative: image, scale: 1).resizable().scaledToFill())
                }
                if photo.isVideo {
                    HStack(spacing: 2) {
                        Image(systemName: "play.fill").font(.system(size: 8, weight: .bold))
                        if !time.isEmpty { Text(verbatim: time).font(.system(size: 10, weight: .bold, design: .monospaced)) }
                    }
                    .foregroundStyle(Color.white)
                    .padding(.horizontal, 5)
                    .frame(height: 15)
                    .background(Capsule().fill(Color(red: 0.078, green: 0.055, blue: 0.118).opacity(0.72)))
                    .padding(3)
                }
            }
            .frame(width: w, height: h)
            .clipShape(shape)
            .background {
                if chosen {
                    ZStack {
                        shape.fill(paint.glow.color(0.45)).padding(-3).shadow(color: paint.glow.color(), radius: 6)
                        shape.fill(Color.white).padding(-1.2)
                    }
                }
            }
        }
        .buttonStyle(.plain)
        .zIndex(chosen ? 1 : 0)
        .position(place)
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityLabel(photo.name)
        .accessibilityAddTraits(chosen ? .isSelected : [])
        .accessibilityIdentifier("camera-deck-album-cell-\(slot)")
    }

    /// The bars: the album, the file's name (九宫格 over the nine), its
    /// place; under it the hints, or how far a video has played.
    private func bars(_ paint: Mp4Paint) -> some View {
        let photos = model.photos, photo = model.albumPhoto
        let place = photos.isEmpty ? "0" : "\(model.albumIndex + 1) / \(photos.count)"
        let title: String = many ? String(localized: "九宫格") : (photo?.name ?? "")
        return Mp4AlbumBars(paint: paint, title: title, mono: !many, place: place, many: many, lead: photo?.name ?? "",
                            playing: model.playing != nil && !many, elapsed: elapsed, length: length, wide: mp4.screen.width >= 300)
            .deckPlaced(mp4.screen)
    }

    /// The five lit keys wait (each glyph still drawn as it is set).
    @ViewBuilder private func litKeys(_ paint: Mp4Paint) -> some View {
        if mp4.lit.count == 5 {
            let shooting = model.shooting
            let on = String(localized: "开"), off = String(localized: "关")
            let names = [String(localized: "定时"), String(localized: "日期"), CameraShellSkin.mp4.shapeTitle, String(localized: "水平仪"), String(localized: "闪光")]
            let states = [model.timer.title, shooting.dateStamp ? on : off, model.shape.title, model.leveler ? on : off, shooting.flash.title]
            let glyphs: [ShellGlyph] = [.timer(model.timer), .date(shooting.dateStamp), .shape(model.shape), .level(model.leveler), .flash(shooting.flash)]
            let identifiers = ["camera-deck-timer", "camera-deck-date", "camera-deck-aspect", "camera-deck-leveler", "camera-deck-flash"]
            ForEach(0..<5, id: \.self) { index in
                Mp4LitKey(paint: paint, rect: mp4.lit[index], glyph: glyphs[index], name: names[index], state: states[index], on: false,
                          identifier: identifiers[index]) { model.say(waiting) }
                    .deckDimmed(true, why: waiting)
                    .deckKey(mp4.lit[index])
            }
        }
    }

    /// MENU as ever; M and 机型 wait; ▸ 相册 is 回去拍照 (a camera, its words
    /// kept), lit cream.
    @ViewBuilder private func pebbles(_ paint: Mp4Paint) -> some View {
        let small = mp4.across, radius = mp4.pebbleRadius
        let video = model.mode == .video
        let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
        Button { model.leave() } label: { Mp4MenuLabel(small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(mp4.menu)
        Button { model.say(waiting) } label: { Mp4ModeLabel(video: video, small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
            .accessibilityLabel(photoWord + " / " + videoWord)
            .accessibilityValue(video ? videoWord : photoWord)
            .accessibilityIdentifier("camera-deck-mode")
            .deckDimmed(true, why: waiting)
            .deckKey(mp4.mode)
        Button { backToCamera() } label: { Mp4AlbumLabel(back: true, small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius, lit: true))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-return")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(mp4.album)
        Button { model.say(waiting) } label: { Mp4BodiesLabel(small: small, paint: paint) }
            .buttonStyle(Mp4PebbleStyle(paint: paint, radius: radius))
            .accessibilityLabel(String(localized: "切换机型"))
            .accessibilityValue(model.body.title)
            .accessibilityIdentifier("camera-deck-bodies")
            .deckDimmed(true, why: waiting)
            .deckKey(mp4.bodies)
    }

    /// The five-way key in 相册: one at a time ◀◀ 上一张, ▶▶ 下一张, ▼ 九宫格
    /// (the nine; ▲ 整张, a magnifying glass, waits), OK 播放 / 停止 (▶ or
    /// the square; a picture's waits); among the nine the sides move, ▲ and
    /// OK (看这张) open the one chosen (▼ waits).
    private func pad(_ paint: Mp4Paint) -> some View {
        let none = model.photos.isEmpty, empty = String(localized: "还没有照片")
        let wholeWord = String(localized: "整张"), gridWord = String(localized: "九宫格")
        let earlier = String(localized: "上一张"), later = String(localized: "下一张")
        let at = model.albumIndex
        let left = Mp4PadPart(sign: .back, label: earlier, identifier: "camera-deck-album-previous", off: none, why: empty) { choose(at - 1) }
        let right = Mp4PadPart(sign: .forward, label: later, identifier: "camera-deck-album-next", off: none, why: empty) { choose(at + 1) }
        let up: Mp4PadPart, down: Mp4PadPart, middle: Mp4PadMiddle
        if many {
            up = Mp4PadPart(sign: .up, mark: .glyph(.zoomIn), label: wholeWord, identifier: "camera-deck-album-up", off: none, why: empty) { showMany(false) }
            let already = String(localized: "已经在看九宫格")
            down = Mp4PadPart(sign: .down, mark: .glyph(.grid), label: gridWord, identifier: "camera-deck-album-index", off: true, why: already) { model.say(already) }
            let view = String(localized: "看这张")
            middle = Mp4PadMiddle(glyph: .zoomIn, label: view, identifier: "camera-deck-album-view", haptic: .smallButton) { showMany(false) }
        } else {
            let whole = String(localized: "已经在看整张")
            up = Mp4PadPart(sign: .up, mark: .glyph(.zoomIn), label: wholeWord, identifier: "camera-deck-album-up", off: true, why: whole) { model.say(whole) }
            down = Mp4PadPart(sign: .down, mark: .glyph(.grid), label: gridWord, identifier: "camera-deck-album-index", off: none, why: empty) {
                if none { model.say(empty) } else { showMany(true) }
            }
            let stop = model.playing != nil
            let word = stop ? String(localized: "停止") : String(localized: "播放")
            let sign: ShellGlyph = stop ? .stop : .play
            let why = none ? empty : String(localized: "照片不能播放；要在上面画，展开后用相册的「编辑」")
            middle = Mp4PadMiddle(glyph: sign, label: word, identifier: "camera-deck-album-play", off: !video, why: why, haptic: .smallButton) {
                if video { model.togglePlay() } else { model.say(why) }
            }
        }
        return Mp4Pad(layout: mp4, paint: paint, glow: .plain, parts: [up, right, down, left], middle: middle)
            .deckPlaced(mp4.pad)
    }

    /// VOL, 内 / 外 wait; the big round key goes back to taking pictures
    /// (回去拍照 by it); the colour's dot as ever.
    @ViewBuilder private func lower(_ paint: Mp4Paint) -> some View {
        let target = model.shownBody
        let step: Int? = target == .native ? nil : model.strengthStep(of: target)
        let words = step.map { CameraBodyStrength.title($0) } ?? "—"
        let word = String(localized: "浓淡")
        let less = DigiRockerEnd(label: word + " −", value: words, identifier: "camera-deck-strength-minus", off: true, why: waiting) { model.say(waiting) }
        let more = DigiRockerEnd(label: word + " +", value: words, identifier: "camera-deck-strength-plus", off: true, why: waiting) { model.say(waiting) }
        Mp4Rocker(layout: mp4, paint: paint, level: step.map { min(5, max(0, $0 + 3)) } ?? 0, off: true, ends: [less, more])
            .deckPlaced(mp4.rocker)
        Mp4FlipKey(layout: mp4, paint: paint, inner: model.side == .inner) { model.say(waiting) }
            .deckDimmed(true, why: waiting)
            .deckKey(mp4.flip)
        if mp4.flipCaption.width > 0 {
            ShellGlyphView(glyph: .flip, size: 14, ink: paint.dim)
                .allowsHitTesting(false)
                .deckPlaced(mp4.flipCaption)
        }
        Mp4ShutterKey(paint: paint, radius: mp4.shutterRadius, sign: .camera, light: Mp4Paint.lamp, haptic: .smallButton) { backToCamera() }
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-close")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(mp4.shutter)
        Mp4Caption(word: String(localized: "回去拍照"), colour: paint.ink.color(), side: mp4.captionSide)
            .deckPlaced(mp4.shutterCaption)
        if mp4.tint.width > 0, let now = model.tint(of: .mp4), let next = model.nextTint(of: .mp4) {
            ShellTintKey(now: now, next: next, sound: .phoneSoft) {
                withAnimation(.easeInOut(duration: 0.2)) { model.cycleTint(of: .mp4) }
            }
            .deckKey(mp4.tint)
        }
    }
}

// MARK: - The bicycle handlebar's back

/// The bicycle's colours: the frame's mint enamel and what is
/// printed on it (softer, and paler for what waits), the caramel grips, the
/// cream of the lamp's shell, the red of the bell's lever and of the needle,
/// the sky-blue pencil box and what is printed on it, the kraft envelope, the
/// brass key, the tin plate's green, the paper tape, the chosen zoom stop's
/// red, the red of 停止, the dark of the road's frame, the shade the parts
/// throw on the enamel. Bright metal besides.
enum BikePaint {
    static let paint = ShellTone(r: 0.588, g: 0.827, b: 0.737)
    static let ink = Color(red: 0.110, green: 0.290, blue: 0.243)
    static let soft = Color(red: 0.110, green: 0.290, blue: 0.243).opacity(0.8)
    static let dim = Color(red: 0.110, green: 0.290, blue: 0.243).opacity(0.34)
    static let grip = ShellTone(r: 0.722, g: 0.502, b: 0.322)
    static let cream = ShellTone(r: 0.973, g: 0.953, b: 0.902)
    static let red = ShellTone(r: 0.886, g: 0.298, b: 0.235)
    static let box = ShellTone(r: 0.502, g: 0.753, b: 0.933)
    static let boxInk = Color(red: 0.090, green: 0.247, blue: 0.420)
    static let boxSoft = Color(red: 0.090, green: 0.247, blue: 0.420).opacity(0.76)
    static let kraft = ShellTone(r: 0.867, g: 0.733, b: 0.525)
    static let brass = ShellTone(r: 0.902, g: 0.745, b: 0.384)
    static let plate = ShellTone(r: 0.173, g: 0.439, b: 0.361)
    static let tape = ShellTone(r: 0.980, g: 0.945, b: 0.816)
    static let accent = Color(red: 0.878, green: 0.333, blue: 0.243)
    static let alarm = Color(red: 0.784, green: 0.196, blue: 0.122)
    static let frame = Color(red: 0.106, green: 0.161, blue: 0.145)
    static let shade = Color(red: 0.0, green: 0.157, blue: 0.118)
}

/// A little star on the pencil box's lid.
struct BikeStar: Equatable {
    var at: CGPoint
    var radius: CGFloat
    var tint: Color
}

/// Where the bicycle's parts are on the cover, upright (from a ShellPlan)
/// or across (from a ShellAcrossPlan): the same parts both ways, each laid
/// out for its hold.
struct BikeLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    var u: CGFloat = 1
    /// The road ahead: the picture's place.
    var road = CGRect.zero
    /// Held across: the band along the edge with the phone's own camera, the
    /// rubber pad where the Camera Control's overlay comes in, where ZERO
    /// begins on the frame (its middle line; .zero: no room for it).
    var band = CGRect.zero
    var pad = CGRect.zero
    var name = CGPoint.zero
    /// The frame's top tube, from under the bar towards the saddle: its
    /// middle, where it begins and ends, how wide at each end, where ZERO
    /// stands on it (0: nowhere).
    var tubeX: CGFloat = 0
    var tubeTop: CGFloat = 0
    var tubeBottom: CGFloat = 0
    var tubeNarrow: CGFloat = 30
    var tubeWide: CGFloat = 64
    var tubeName: CGFloat = 0
    /// The wire basket from the saddle: its front rim's ends, its near rim's
    /// (wider and lower), how many wires along it and across it.
    var front0 = CGPoint.zero
    var front1 = CGPoint.zero
    var near0 = CGPoint.zero
    var near1 = CGPoint.zero
    var wires = 22
    var hoops = 7
    /// The tin plate (机型): the plate, the rim its wires hang from, how large
    /// ZERO is pressed out of it; the tape under it and its words' size; its place.
    var plate = CGRect.zero
    var plateHook: CGFloat = 0
    var plateWord: CGFloat = 20
    var plateTape = CGRect.zero
    var plateTapeSize: CGFloat = 11
    var plateKey = CGRect.zero
    /// The headlamp (闪光): its middle, its glass's radius, where its bracket
    /// begins; its tape (two lines upright, one across); its place, and the
    /// narrower one it has in 相册 (the envelope grows over its tape there).
    var lamp = CGPoint.zero
    var lampRadius: CGFloat = 21
    var lampBracket: CGFloat = 0
    var lampTape = CGRect.zero
    var lampTapeLines = 2
    var lampKey = CGRect.zero
    var lampAlbumKey = CGRect.zero
    /// The photo envelope (相册): the kraft envelope (the newest prints out of
    /// its mouth, up held across, beside it upright), its place; in 相册 the
    /// envelope that says 回去拍照, and its place.
    var envelope = CGRect.zero
    var envelopeUp = false
    var envelopeKey = CGRect.zero
    var backEnvelope = CGRect.zero
    var backKey = CGRect.zero
    /// The pencil box in the basket: the box, its LCD (the date and the time)
    /// and how large it writes, the pencil on its lid (its eraser at the
    /// leading end), the stars on it, its six buttons.
    var box = CGRect.zero
    var lcd = CGRect.zero
    var lcdSize: CGFloat = 11
    var pencil = CGRect.zero
    var stars: [BikeStar] = []
    var buttons: [CGRect] = []
    /// 相册's prints laid in the basket (the one looked at in `printsMiddle`,
    /// larger and raised), and the tape under them.
    var prints: [CGRect] = []
    var printsMiddle = 2
    var printsTape = CGRect.zero
    /// The rear-view mirror (内 / 外): its middle and radius, its stalk (from
    /// the mirror round to the bar: its start, a bend's control and end, the
    /// straight run's end, a bend's control and end) and how thick, its place,
    /// its words (under it on the body upright; on a tape in its place across).
    var mirror = CGPoint.zero
    var mirrorRadius: CGFloat = 23
    var stalk: [CGPoint] = []
    var stalkWidth: CGFloat = 5
    var mirrorKey = CGRect.zero
    var mirrorWords = CGRect.zero
    var mirrorTape = false
    /// The paper pinwheel (拍照 / 录像): its middle and radius, where its stick
    /// ends, its tape, its place.
    var pinwheel = CGPoint.zero
    var pinwheelRadius: CGFloat = 27
    var stickFoot: CGFloat = 0
    var pinwheelTape = CGRect.zero
    var pinwheelKey = CGRect.zero
    /// The speedometer (变焦): its middle and radius, how far out its two
    /// studs are and how large; the halves touched (− and ＋); its stem.
    var speedo = CGPoint.zero
    var speedoRadius: CGFloat = 38
    var studReach: CGFloat = 52
    var studRadius: CGFloat = 10.5
    var zoomOut = CGRect.zero
    var zoomIn = CGRect.zero
    var stem = CGRect.zero
    /// The gear shifter (镜头): its window, its two thumb levers, its foot on
    /// the bar, how large the window writes its name.
    var shifterWindow = CGRect.zero
    var leverBack = CGRect.zero
    var leverOn = CGRect.zero
    var shifterFoot = CGRect.zero
    var shifterName: CGFloat = 12.5
    /// The handlebar: its run (the left end, the left bend's start, control
    /// and end, the straight run's end, the right bend's control and end, the
    /// right end) and how thick; the clamps on it; the grips (each from its
    /// inner end to its outer one) and how thick.
    var bar: [CGPoint] = []
    var barWidth: CGFloat = 13
    var clamps: [CGRect] = []
    var grips: [CGPoint] = []
    var gripWidth: CGFloat = 24
    /// The house key (主菜单): its split ring's middle round the bar, its place.
    var ring = CGPoint.zero
    var homeKey = CGRect.zero
    /// The bell (快门): its middle, radius and its lever's angle; its place;
    /// its word; the tin bracket under it held across.
    var bell = CGPoint.zero
    var bellRadius: CGFloat = 26
    var bellLever: Double = 2.05
    var bellKey = CGRect.zero
    var bellWord = CGRect.zero
    var bellBracket = CGRect.zero

    /// Where the plate hangs from, as a share of its height down from its top.
    var plateHang: CGFloat { plate.height > 0 ? (plateHook - plate.minY) / plate.height : 0 }
    /// The middle of the speedometer's − stud (way < 0) or ＋ stud.
    func stud(_ way: Int) -> CGPoint {
        let a = (way < 0 ? 145.0 : 35.0) * Double.pi / 180
        return CGPoint(x: speedo.x + CGFloat(cos(a)) * studReach, y: speedo.y + CGFloat(sin(a)) * studReach)
    }
    /// The speedometer's place, with its studs' arms.
    var dial: CGRect {
        let half = studReach + 14
        return CGRect(x: speedo.x - half, y: speedo.y - half, width: 2 * half, height: 2 * half)
    }
    /// A part's place, from the corner of the key it is drawn in.
    static func local(_ r: CGRect, in key: CGRect) -> CGRect { r.offsetBy(dx: -key.minX, dy: -key.minY) }
    static func local(_ p: CGPoint, in key: CGRect) -> CGPoint { CGPoint(x: p.x - key.minX, y: p.y - key.minY) }
}

extension ShellPlan {
    /// The bicycle's parts, upright (across from the column's corner,
    /// scaled with it; down from the keys' top and from the bar): the road
    /// at the head of the column; the basket under it (the plate, the lamp
    /// and the envelope on its front rim, the pencil box in it); the bar
    /// along the column's foot with the pinwheel, the speedometer, the
    /// shifter and the key on it — what height is left goes between the
    /// basket and the bar. Down the strip: the mirror under the camera on its
    /// tall stalk, and the bell under the Camera Control's overlay, by the
    /// right grip.
    var bike: BikeLayout {
        var l = BikeLayout()
        let c = back.column, strip = back.strip, k = keysTop
        let floor = back.keepOut.map(\.maxY).max() ?? top
        let bar = c.maxY - 52
        let sx = strip.minX, sm = strip.midX, se = strip.maxX
        l.canvas = back.canvas
        l.u = u
        l.road = box
        // The frame's top tube, from under the bar past the foot.
        l.tubeX = x(233)
        l.tubeTop = bar + 6
        l.tubeBottom = back.canvas.height + 6
        l.tubeNarrow = 30
        l.tubeWide = 64
        l.tubeName = bar + 58
        // The basket: its front rim along the road's foot, its near rim over the bar.
        l.front0 = CGPoint(x: c.minX + 8, y: k)
        l.front1 = CGPoint(x: se - 12, y: k)
        l.near0 = CGPoint(x: c.minX - 6, y: k + 182)
        l.near1 = CGPoint(x: se, y: k + 182)
        l.wires = 22
        l.hoops = 7
        // On its front rim: the plate, the lamp, the envelope.
        l.plate = CGRect(x: x(28), y: k + 10, width: 136 * u, height: 44)
        l.plateHook = k
        l.plateWord = 20
        l.plateTape = CGRect(x: x(96) - 62 * u, y: k + 57, width: 124 * u, height: 18)
        l.plateTapeSize = 11
        l.plateKey = CGRect(x: x(26), y: k + 6, width: 140 * u, height: 70)
        l.lamp = CGPoint(x: x(205), y: k + 34)
        l.lampRadius = 21 * min(1, max(0.8, u))
        l.lampBracket = k
        l.lampTape = CGRect(x: x(259) - 22, y: k + 17, width: 44, height: 34)
        l.lampTapeLines = 2
        // (Its place 6 short of the envelope's, and in 相册 of 回去拍照's.)
        l.lampKey = CGRect(x: x(176), y: k + 6, width: 112 * u - 6, height: 54)
        l.lampAlbumKey = CGRect(x: x(176), y: k + 6, width: max(44, 64 * u - 6), height: 54)
        l.envelope = CGRect(x: x(288), y: k + 9, width: 60 * u, height: 64)
        l.envelopeUp = false
        l.envelopeKey = CGRect(x: x(288), y: k + 6, width: 100 * u, height: 70)
        l.backEnvelope = CGRect(x: x(240), y: k + 8, width: 148 * u, height: 66)
        l.backKey = CGRect(x: x(240), y: k + 6, width: 148 * u, height: 70)
        // The pencil box; its six buttons each as wide as drawn, never under
        // 44, 6 apart while there is room in the box.
        l.box = CGRect(x: x(20), y: k + 84, width: 370 * u, height: 92)
        l.lcd = CGRect(x: x(30), y: k + 91, width: 120 * u, height: 18)
        l.lcdSize = 11
        l.pencil = CGRect(x: x(166), y: k + 95.75, width: 132 * u, height: 8.5)
        l.stars = [BikeStar(at: CGPoint(x: x(316), y: k + 101), radius: 4.5, tint: Color(red: 1.0, green: 0.965, blue: 0.761)),
                   BikeStar(at: CGPoint(x: x(338), y: k + 97), radius: 3, tint: Color.white),
                   BikeStar(at: CGPoint(x: x(360), y: k + 102), radius: 4, tint: Color(red: 1.0, green: 0.843, blue: 0.902))]
        let each: CGFloat = max(44, 54 * u)
        let span: CGFloat = min(366 * u, max(354 * u, 6 * each + 30))
        let gap: CGFloat = max(0, (span - 6 * each) / 5)
        let left: CGFloat = x(205) - span / 2
        var buttons: [CGRect] = []
        for slot in 0..<6 {
            buttons.append(CGRect(x: left + CGFloat(slot) * (each + gap), y: k + 116, width: each, height: 46))
        }
        l.buttons = buttons
        // 相册: five prints in the basket, the one looked at in the middle
        // (each at least 6 short of the next).
        let printAt: [CGFloat] = [26, 98, 166, 242, 314, 390]
        let printWide: [CGFloat] = [62, 62, 70, 62, 62]
        var prints: [CGRect] = []
        for spot in 0..<5 {
            let w = min(printWide[spot] * u, x(printAt[spot + 1]) - 6 - x(printAt[spot]))
            let down: CGFloat = spot == 2 ? 86 : 94
            prints.append(CGRect(x: x(printAt[spot]), y: k + down, width: w, height: max(48, w * 0.8 + 4)))
        }
        l.prints = prints
        l.printsMiddle = 2
        l.printsTape = CGRect(x: x(204) - 83 * u, y: k + 156, width: 166 * u, height: 18)
        // The mirror under the camera, its stalk down the strip to the bar.
        let my = max(floor + 36, top + 40)
        l.mirror = CGPoint(x: sm + 3, y: my)
        l.mirrorRadius = min(23, max(14, (strip.width - 18) / 2))
        l.stalk = [CGPoint(x: sm + 15, y: my + 14), CGPoint(x: se - 1, y: my + 24), CGPoint(x: se - 1, y: my + 62),
                   CGPoint(x: se - 1, y: bar - 36), CGPoint(x: se - 1, y: bar - 8), CGPoint(x: se - 18, y: bar + 2)]
        l.stalkWidth = 5
        l.mirrorKey = CGRect(x: sm - 21, y: my - 24, width: 48, height: 48)
        l.mirrorWords = CGRect(x: sm - 35, y: my + 36, width: 68, height: 32)
        l.mirrorTape = false
        // The bar's row: the pinwheel, the speedometer, the shifter, at least
        // 6 apart, all further left together where the column is narrow.
        var p0 = x(82)
        var s0 = max(x(176), p0 + 74)
        var f0 = max(x(294), s0 + 118)
        let over = f0 + 94 - (c.maxX + 2)
        if over > 0 {
            let slide = min(over, max(0, p0 - c.minX - 2))
            p0 -= slide
            s0 -= slide
            f0 -= slide
        }
        l.pinwheel = CGPoint(x: p0 + 34, y: bar - 80)
        l.pinwheelRadius = 27
        l.stickFoot = bar + 2
        l.pinwheelTape = CGRect(x: p0 - 2, y: bar - 45, width: 72, height: 32)
        l.pinwheelKey = CGRect(x: p0, y: bar - 110, width: 68, height: 96)
        l.speedo = CGPoint(x: s0 + 56, y: bar - 68)
        l.speedoRadius = 38
        l.studReach = 52
        l.studRadius = 10.5
        l.zoomOut = CGRect(x: s0, y: bar - 112, width: 53, height: 90)
        l.zoomIn = CGRect(x: s0 + 59, y: bar - 112, width: 53, height: 90)
        l.stem = CGRect(x: s0 + 51, y: bar - 32, width: 10, height: 32)
        l.shifterWindow = CGRect(x: f0, y: bar - 114, width: 94, height: 46)
        l.leverBack = CGRect(x: f0, y: bar - 62, width: 44, height: 44)
        l.leverOn = CGRect(x: f0 + 50, y: bar - 62, width: 44, height: 44)
        l.shifterFoot = CGRect(x: f0 + 41, y: bar - 26, width: 12, height: 28)
        l.shifterName = 12.5
        // The handlebar, swept back: the grips at both ends coming towards the saddle.
        l.bar = [CGPoint(x: c.minX + 22, y: bar + 48), CGPoint(x: c.minX + 26, y: bar + 24), CGPoint(x: c.minX + 32, y: bar),
                 CGPoint(x: c.minX + 60, y: bar), CGPoint(x: sx, y: bar), CGPoint(x: sx + 28, y: bar),
                 CGPoint(x: sx + 34, y: bar + 24), CGPoint(x: sx + 38, y: bar + 48)]
        l.barWidth = 13
        l.clamps = [CGRect(x: p0 + 29, y: bar - 9, width: 10, height: 18), CGRect(x: s0 + 43, y: bar - 10, width: 26, height: 20),
                    CGRect(x: f0 + 40, y: bar - 9.5, width: 14, height: 19), CGRect(x: sx + 6.5, y: bar - 9.5, width: 11, height: 19)]
        l.grips = [CGPoint(x: sx + 34.5, y: bar + 22), CGPoint(x: sx + 47, y: bar + 77),
                   CGPoint(x: c.minX + 25.5, y: bar + 22), CGPoint(x: c.minX + 13, y: bar + 77)]
        l.gripWidth = 24
        // The house key on its ring round the bar.
        l.ring = CGPoint(x: x(100), y: bar + 2)
        l.homeKey = CGRect(x: x(100) - 26, y: bar + 2, width: 52, height: 48)
        // The bell by the right grip, under the Camera Control's overlay
        // (its place no wider than the strip leaves).
        let by = max((back.overlay?.maxY ?? 0) + 30, bar - 22)
        let bw: CGFloat = min(62, strip.width - 4)
        l.bell = CGPoint(x: sm, y: by)
        l.bellRadius = min(26, max(16, (strip.width - 12) / 2))
        l.bellLever = 2.05
        l.bellKey = CGRect(x: se - bw, y: by - 26, width: bw, height: 58)
        l.bellWord = CGRect(x: sm - 40, y: by - 46, width: 80, height: 16)
        return l
    }
}

extension ShellAcrossPlan {
    /// 拍照 held across: the bell alone in the band, in its shorter clear run
    /// (the longer one where that is too short), at the end of it nearer the
    /// cover's edge; its word beside it, on the inner side, in the same run.
    var bikeShutter: CGRect {
        let end = bikeBellRun
        let x: CGFloat = bikeBellOuter ? end.maxX - 62 : end.minX + 6
        return CGRect(x: x, y: end.midY - 27, width: 56, height: 56)
    }
    /// The clear run the bell is in, and whether it stands at its right end.
    var bikeBellRun: CGRect { back.spare.width >= 100 ? back.spare : back.run }
    var bikeBellOuter: Bool { bikeBellRun.midX > back.canvas.width / 2 }

    /// The bicycle's parts with the cover held across (from the keys'
    /// corner): the road at the left, the handlebar under everything; in the
    /// band ZERO on the frame, the rubber pad where the Camera Control's
    /// overlay comes in, and the bell; in the keys' column the basket — the
    /// plate, the key and the lamp on its front rim, the pencil box in it,
    /// the envelope, the pinwheel and the mirror on its stalk — and on the
    /// bar the speedometer and the shifter.
    var bike: BikeLayout {
        var l = BikeLayout()
        let band = back.band, run = back.run, keys = back.keys, s = back.screen
        let w = back.canvas.width, h = back.canvas.height
        let onTop = band.minY < 1
        let kx = keys.minX, ky = keys.minY
        l.across = true
        l.canvas = back.canvas
        l.u = 1
        l.road = box
        l.band = band
        if let zone = back.overlay, zone.width > 40 {
            l.pad = CGRect(x: zone.minX + 8, y: band.minY + 16, width: zone.width - 16, height: 46)
        }
        // ZERO on the frame in what the bell leaves of the longer run (at its
        // other end where the bell shares it), level with the phone's own
        // camera where that is in the band.
        let shared = back.spare.width < 100
        let room: CGFloat = shared ? run.width - 124 : run.width
        if room >= 90 {
            let camera = back.keepOut.first { $0.intersects(band) }
            let start: CGFloat = shared && !bikeBellOuter ? run.maxX - 78 : run.minX + 8
            l.name = CGPoint(x: start, y: camera?.midY ?? run.midY)
        }
        // The handlebar under the road and the keys (its ends and grips
        // shorter where the band is along the foot), the top tube under it.
        let barY = ky + 334
        let barLeft = s.minX + 50, barRight = kx + 152
        let fall: CGFloat = onTop ? 1 : min(1, max(0.3, (band.minY - 6 - barY) / 50))
        l.tubeX = (barLeft + barRight) / 2
        l.tubeTop = barY + 6
        l.tubeBottom = onTop ? h + 6 : max(barY + 6, band.minY - 2)
        l.tubeNarrow = 28
        l.tubeWide = 46
        l.tubeName = 0
        l.bar = [CGPoint(x: barLeft, y: barY + 34 * fall), CGPoint(x: barLeft + 4, y: barY + 16 * fall), CGPoint(x: barLeft + 10, y: barY),
                 CGPoint(x: barLeft + 38, y: barY), CGPoint(x: kx + 114, y: barY), CGPoint(x: kx + 142, y: barY),
                 CGPoint(x: kx + 148, y: barY + 16 * fall), CGPoint(x: barRight, y: barY + 34 * fall)]
        l.barWidth = 12
        l.clamps = [CGRect(x: l.tubeX - 12, y: barY - 9, width: 24, height: 18), CGRect(x: barRight - 6, y: barY - 8.5, width: 12, height: 17)]
        l.grips = [CGPoint(x: kx + 148.5, y: barY + 15 * fall), CGPoint(x: kx + 181, y: barY + 44 * fall),
                   CGPoint(x: barLeft + 3.5, y: barY + 15 * fall), CGPoint(x: barLeft - 29, y: barY + 44 * fall)]
        l.gripWidth = 21
        // The basket in the keys' column.
        l.front0 = CGPoint(x: kx - 4, y: ky)
        l.front1 = CGPoint(x: min(w, kx + 206), y: ky)
        l.near0 = CGPoint(x: kx - 10, y: ky + 266)
        l.near1 = CGPoint(x: min(w, kx + 210), y: ky + 266)
        l.wires = 12
        l.hoops = 6
        // On its front rim: the plate, the key, the lamp.
        l.plate = CGRect(x: kx + 2, y: ky + 7, width: 88, height: 36)
        l.plateHook = ky
        l.plateWord = 16
        l.plateTape = CGRect(x: kx, y: ky + 46.5, width: 92, height: 17)
        l.plateTapeSize = 10
        l.plateKey = key(0, 2, 92, 62)
        l.ring = CGPoint(x: kx + 123, y: ky + 2)
        l.homeKey = key(98, 2, 46, 62)
        l.lamp = CGPoint(x: kx + 175, y: ky + 23)
        l.lampRadius = 13.5
        l.lampBracket = ky
        l.lampTape = CGRect(x: kx + 150, y: ky + 46.5, width: 50, height: 17)
        l.lampTapeLines = 1
        l.lampKey = key(150, 2, 50, 62)
        l.lampAlbumKey = key(150, 2, 50, 62)
        // The pencil box: two rows of three buttons.
        l.box = key(0, 70, 200, 126)
        l.lcd = key(8, 76, 104, 16)
        l.lcdSize = 10
        l.pencil = key(120, 80.5, 72, 7)
        l.stars = []
        var buttons: [CGRect] = []
        for index in 0..<6 {
            buttons.append(key(4 + CGFloat(index % 3) * 66, 98 + CGFloat(index / 3) * 50, 60, 44))
        }
        l.buttons = buttons
        // 相册: three prints where the pencil box was.
        l.prints = [key(4, 86, 58, 50.4), key(68, 80, 64, 55.2), key(138, 86, 58, 50.4)]
        l.printsMiddle = 1
        l.printsTape = key(25, 150, 150, 17)
        // The envelope, the pinwheel stuck in the basket, the mirror on its stalk.
        l.envelope = key(4, 216, 54, 42)
        l.envelopeUp = true
        l.envelopeKey = key(0, 202, 62, 60)
        l.backEnvelope = key(4, 216, 54, 42)
        l.backKey = key(0, 202, 62, 60)
        l.pinwheel = CGPoint(x: kx + 99, y: ky + 218)
        l.pinwheelRadius = 15
        l.stickFoot = ky + 266
        l.pinwheelTape = key(68, 235, 62, 26)
        l.pinwheelKey = key(68, 202, 62, 60)
        l.mirror = CGPoint(x: kx + 168, y: ky + 217)
        l.mirrorRadius = 14
        l.stalk = [CGPoint(x: kx + 179, y: ky + 224), CGPoint(x: kx + 204, y: ky + 228), CGPoint(x: kx + 204, y: ky + 256),
                   CGPoint(x: kx + 204, y: ky + 320), CGPoint(x: kx + 204, y: ky + 342), CGPoint(x: kx + 174, y: ky + 348)]
        l.stalkWidth = 4
        l.mirrorKey = key(136, 202, 64, 60)
        l.mirrorWords = key(138, 235, 60, 26)
        l.mirrorTape = true
        // On the bar: the speedometer and the shifter.
        l.speedo = CGPoint(x: kx + 49, y: ky + 317)
        l.speedoRadius = 34
        l.studReach = 44
        l.studRadius = 9
        l.zoomOut = key(0, 272, 46, 84)
        l.zoomIn = key(52, 272, 46, 84)
        l.stem = CGRect(x: kx + 44.5, y: ky + 312, width: 9, height: 22)
        l.shifterWindow = key(104, 268, 96, 38)
        l.leverBack = key(104, 312, 45, 44)
        l.leverOn = key(155, 312, 45, 44)
        l.shifterFoot = CGRect(x: kx + 146, y: ky + 308, width: 12, height: 26)
        l.shifterName = 11.5
        // The bell alone in the band on its tin bracket, its word beside it
        // on the inner side (in the same clear run).
        let bell = bikeShutter, end = bikeBellRun
        l.bell = CGPoint(x: bell.midX, y: bell.minY + 26)
        l.bellRadius = 25
        l.bellLever = 2.25
        l.bellKey = bell
        let wordLeft: CGFloat = bikeBellOuter ? max(end.minX + 2, bell.minX - 64) : bell.maxX + 4
        let wordRight: CGFloat = bikeBellOuter ? bell.minX - 4 : min(end.maxX - 2, bell.maxX + 64)
        l.bellWord = CGRect(x: wordLeft, y: bell.midY - 9, width: max(0, wordRight - wordLeft), height: 18)
        l.bellBracket = CGRect(x: bell.midX - 17, y: bell.minY + 44, width: 34, height: 10)
        return l
    }
}

/// The bicycle's drawing, part for part: the enamel, the chrome tubes, the
/// frame's top tube, the wire basket, the pencil box and what lies on it,
/// the stalks and posts, the clamps, the grips, the rubber pad.
private enum BikeArt {
    static func stop(_ colour: Color, _ at: CGFloat) -> Gradient.Stop { Gradient.Stop(color: colour, location: at) }
    static func rgb(_ r: Double, _ g: Double, _ b: Double, _ a: Double = 1) -> Color {
        Color(red: r / 255, green: g / 255, blue: b / 255).opacity(a)
    }
    static func rr(_ r: CGRect, _ radius: CGFloat) -> Path {
        Path(roundedRect: r, cornerRadius: max(0, min(radius, r.width / 2, r.height / 2)))
    }
    static func disc(_ c: CGPoint, _ r: CGFloat) -> Path {
        Path(ellipseIn: CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r))
    }
    static func segment(_ a: CGPoint, _ b: CGPoint) -> Path {
        var path = Path()
        path.move(to: a)
        path.addLine(to: b)
        return path
    }
    static func vertical(_ stops: [Gradient.Stop], _ y0: CGFloat, _ y1: CGFloat) -> GraphicsContext.Shading {
        .linearGradient(Gradient(stops: stops), startPoint: CGPoint(x: 0, y: y0), endPoint: CGPoint(x: 0, y: y1))
    }
    static func across(_ stops: [Gradient.Stop], _ x0: CGFloat, _ x1: CGFloat) -> GraphicsContext.Shading {
        .linearGradient(Gradient(stops: stops), startPoint: CGPoint(x: x0, y: 0), endPoint: CGPoint(x: x1, y: 0))
    }
    /// Points along an ellipse's arc from `from` to `to` (radians, y down).
    static func arc(_ c: CGPoint, _ rx: CGFloat, _ ry: CGFloat, from: Double, to: Double, steps: Int = 24) -> [CGPoint] {
        var points: [CGPoint] = []
        for index in 0...max(1, steps) {
            let a = from + (to - from) * Double(index) / Double(max(1, steps))
            points.append(CGPoint(x: c.x + CGFloat(cos(a)) * rx, y: c.y + CGFloat(sin(a)) * ry))
        }
        return points
    }
    static func polyline(_ points: [CGPoint]) -> Path {
        var path = Path()
        guard let first = points.first else { return path }
        path.move(to: first)
        for point in points.dropFirst() { path.addLine(to: point) }
        return path
    }
    /// The handlebar's run from its eight points (BikeLayout.bar).
    static func run(_ points: [CGPoint]) -> Path {
        var path = Path()
        guard points.count == 8 else { return path }
        path.move(to: points[0])
        path.addLine(to: points[1])
        path.addQuadCurve(to: points[3], control: points[2])
        path.addLine(to: points[4])
        path.addQuadCurve(to: points[6], control: points[5])
        path.addLine(to: points[7])
        return path
    }
    /// The mirror's stalk from its six points (BikeLayout.stalk).
    static func stalk(_ points: [CGPoint]) -> Path {
        var path = Path()
        guard points.count == 6 else { return path }
        path.move(to: points[0])
        path.addQuadCurve(to: points[2], control: points[1])
        path.addLine(to: points[3])
        path.addQuadCurve(to: points[5], control: points[4])
        return path
    }

    /// Chrome along a path, lit from above (the handlebar, the basket's rims,
    /// the mirror's stalk), its shadow under it.
    static func tube(_ context: GraphicsContext, _ path: Path, _ t: CGFloat, drop: CGFloat = 3) {
        func style(_ width: CGFloat) -> StrokeStyle { StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round) }
        if drop != 0 {
            context.stroke(path.offsetBy(dx: 0, dy: drop), with: .color(BikePaint.shade.opacity(0.26)), style: style(t + 1.5))
        }
        context.stroke(path, with: .color(rgb(104, 110, 119)), style: style(t))
        context.stroke(path, with: .color(rgb(169, 175, 183)), style: style(t * 0.8))
        context.stroke(path.offsetBy(dx: 0, dy: t * 0.2), with: .color(rgb(123, 129, 138)), style: style(t * 0.24))
        context.stroke(path.offsetBy(dx: 0, dy: -t * 0.13), with: .color(rgb(232, 235, 238)), style: style(t * 0.42))
        context.stroke(path.offsetBy(dx: 0, dy: -t * 0.19), with: .color(Color.white), style: style(max(0.7, t * 0.13)))
    }

    /// The frame's mint enamel lit from the upper left, an even sheen, the
    /// hinge's side in shade, a light edge all round.
    static func body(_ context: GraphicsContext, _ size: CGSize, _ hinge: CGRect) {
        let whole = CGRect(origin: .zero, size: size), c = BikePaint.paint
        let enamel = Gradient(stops: [stop(c.color(0.24), 0), stop(c.color(), 0.5), stop(c.color(-0.1), 1)])
        context.fill(Path(whole), with: .linearGradient(enamel, startPoint: .zero, endPoint: CGPoint(x: size.width * 0.35, y: size.height)))
        let far = max(size.width, size.height)
        let sheen = Gradient(stops: [stop(Color.white.opacity(0.28), 0), stop(Color.white.opacity(0.04), 0.5), stop(rgb(0, 50, 40, 0.1), 1)])
        context.fill(Path(whole), with: .radialGradient(sheen, center: CGPoint(x: size.width * 0.22, y: size.height * 0.1), startRadius: 10, endRadius: far * 0.85))
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let near: Bool = tall ? hinge.midX < size.width / 2 : hinge.midY < size.height / 2
            let edge: CGFloat = near ? 0 : (tall ? size.width : size.height)
            let inward: CGFloat = near ? 14 : -14
            let from: CGPoint = tall ? CGPoint(x: edge, y: 0) : CGPoint(x: 0, y: edge)
            let to: CGPoint = tall ? CGPoint(x: edge + inward, y: 0) : CGPoint(x: 0, y: edge + inward)
            let low: CGFloat = min(edge, edge + inward)
            let strip: CGRect = tall ? CGRect(x: low, y: 0, width: 14, height: size.height) : CGRect(x: 0, y: low, width: size.width, height: 14)
            let fade = Gradient(colors: [BikePaint.shade.opacity(0.36), BikePaint.shade.opacity(0)])
            context.fill(Path(strip), with: .linearGradient(fade, startPoint: from, endPoint: to))
        }
        context.stroke(Path(roundedRect: whole.insetBy(dx: 2, dy: 2), cornerRadius: 44), with: .color(Color.white.opacity(0.55)), lineWidth: 1.6)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 0.5, dy: 0.5), cornerRadius: 46), with: .color(rgb(0, 50, 40, 0.5)), lineWidth: 1)
    }

    /// ZERO on the frame, held across (pressed into it: a light edge under it).
    static func bandName(_ context: GraphicsContext, at p: CGPoint) {
        let word = Text(verbatim: "ZERO").font(.system(size: 15, weight: .black, design: .rounded)).tracking(6)
        context.draw(word.foregroundColor(Color.white.opacity(0.6)), at: CGPoint(x: p.x, y: p.y + 0.8), anchor: .leading)
        context.draw(word.foregroundColor(BikePaint.ink), at: p, anchor: .leading)
    }

    /// Where the system's Camera Control comes in, held across: ribs pressed
    /// into the enamel, like a grip (nothing to press there).
    static func pad(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 0, r.height > 16 else { return }
        let c = BikePaint.paint, h = r.height
        let well = Path(roundedRect: r, cornerRadius: h / 2)
        context.fill(well, with: vertical([stop(c.color(-0.12), 0), stop(c.color(0.1), 1)], r.minY, r.maxY))
        context.stroke(Path(roundedRect: r.offsetBy(dx: 0, dy: 1), cornerRadius: h / 2), with: .color(Color.white.opacity(0.55)), lineWidth: 1)
        context.stroke(well, with: .color(rgb(0, 50, 40, 0.3)), lineWidth: 1)
        var ribs = context
        ribs.clip(to: well)
        var x = r.minX + h / 2
        while x < r.maxX - h / 2 {
            ribs.fill(rr(CGRect(x: x, y: r.minY + 8, width: 2.4, height: h - 16), 1.2), with: .color(rgb(0, 50, 40, 0.22)))
            ribs.fill(rr(CGRect(x: x + 2.4, y: r.minY + 8, width: 1.3, height: h - 16), 0.6), with: .color(Color.white.opacity(0.5)))
            x += 7
        }
    }

    /// The frame's top tube from under the bar towards the saddle (ZERO along it upright).
    static func topTube(_ context: GraphicsContext, _ l: BikeLayout) {
        let cx = l.tubeX, y0 = l.tubeTop, y1 = l.tubeBottom, w0 = l.tubeNarrow, w1 = l.tubeWide, c = BikePaint.paint
        guard y1 > y0, w1 > 0 else { return }
        var shape = Path()
        shape.move(to: CGPoint(x: cx - w0 / 2, y: y0))
        shape.addLine(to: CGPoint(x: cx + w0 / 2, y: y0))
        shape.addLine(to: CGPoint(x: cx + w1 / 2, y: y1))
        shape.addLine(to: CGPoint(x: cx - w1 / 2, y: y1))
        shape.closeSubpath()
        context.fill(shape.offsetBy(dx: 2.5, dy: 0), with: .color(BikePaint.shade.opacity(0.22)))
        let enamel = [stop(c.color(-0.32), 0), stop(c.color(), 0.22), stop(c.color(0.5), 0.42), stop(c.color(0.2), 0.52), stop(c.color(-0.08), 0.8), stop(c.color(-0.38), 1)]
        context.fill(shape, with: across(enamel, cx - w1 / 2, cx + w1 / 2))
        context.stroke(shape, with: .color(rgb(0, 50, 40, 0.35)), lineWidth: 0.8)
        if l.tubeName > 0 {
            var turned = context
            turned.translateBy(x: cx, y: l.tubeName)
            turned.rotate(by: .radians(-Double.pi / 2))
            let word = Text(verbatim: "ZERO").font(.system(size: 10, weight: .black, design: .rounded)).tracking(3).foregroundColor(BikePaint.ink.opacity(0.72))
            turned.draw(word, at: CGPoint(x: 1.5, y: 0.5))
        }
    }

    /// The wire basket from the saddle: the dark inside, the wires along and
    /// across it (lit along their tops), its side rims and its front rim.
    static func basket(_ context: GraphicsContext, _ l: BikeLayout) {
        let f0 = l.front0.x, f1 = l.front1.x, fy = l.front0.y, n0 = l.near0.x, n1 = l.near1.x, ny = l.near0.y
        guard ny > fy else { return }
        func at(_ t: CGFloat, _ y: CGFloat) -> CGFloat {
            let k = (y - fy) / (ny - fy)
            let a = f0 + (n0 - f0) * k, b = f1 + (n1 - f1) * k
            return a + (b - a) * t
        }
        var shape = Path()
        shape.move(to: CGPoint(x: f0, y: fy))
        shape.addLine(to: CGPoint(x: f1, y: fy))
        shape.addLine(to: CGPoint(x: n1, y: ny))
        shape.addLine(to: CGPoint(x: n0, y: ny))
        shape.closeSubpath()
        let inside = [stop(rgb(18, 58, 46, 0.34), 0), stop(rgb(18, 58, 46, 0.22), 0.3), stop(rgb(18, 58, 46, 0.1), 1)]
        context.fill(shape, with: vertical(inside, fy, ny))
        var mesh = context
        mesh.clip(to: shape)
        var dark = Path(), light = Path()
        let wires = max(2, l.wires), hoops = max(2, l.hoops)
        for strand in 1..<wires {
            let t = CGFloat(strand) / CGFloat(wires), xa = at(t, fy), xb = at(t, ny)
            dark.move(to: CGPoint(x: xa, y: fy))
            dark.addLine(to: CGPoint(x: xb, y: ny))
            light.move(to: CGPoint(x: xa - 0.5, y: fy))
            light.addLine(to: CGPoint(x: xb - 0.5, y: ny))
        }
        for hoop in 1..<hoops {
            let y = fy + (ny - fy) * CGFloat(pow(Double(hoop) / Double(hoops), 1.2))
            dark.move(to: CGPoint(x: at(0, y), y: y))
            dark.addLine(to: CGPoint(x: at(1, y), y: y))
            light.move(to: CGPoint(x: at(0, y), y: y - 0.5))
            light.addLine(to: CGPoint(x: at(1, y), y: y - 0.5))
        }
        mesh.stroke(dark, with: .color(rgb(66, 76, 82, 0.5)), style: StrokeStyle(lineWidth: 1.6, lineCap: .butt))
        mesh.stroke(light, with: .color(rgb(240, 244, 246, 0.72)), style: StrokeStyle(lineWidth: 0.7, lineCap: .butt))
        tube(context, segment(l.front0, l.near0), 5, drop: 2)
        tube(context, segment(l.front1, l.near1), 5, drop: 2)
        tube(context, segment(l.front0, l.front1), 7, drop: 2)
    }

    /// The two wires the tin plate hangs from on the basket's rim.
    static func plateWires(_ context: GraphicsContext, _ plate: CGRect, hook: CGFloat) {
        guard plate.width > 24, plate.minY + 8 > hook else { return }
        for hx in [plate.minX + 12, plate.maxX - 12] {
            context.stroke(segment(CGPoint(x: hx, y: plate.minY + 8), CGPoint(x: hx, y: hook)), with: .color(rgb(115, 122, 130)), lineWidth: 1.8)
            context.stroke(segment(CGPoint(x: hx - 0.6, y: plate.minY + 8), CGPoint(x: hx - 0.6, y: hook)), with: .color(Color.white.opacity(0.75)), lineWidth: 0.6)
        }
    }

    /// The lamp's bracket down from the basket's rim.
    static func bracket(_ context: GraphicsContext, x: CGFloat, from top: CGFloat, to bottom: CGFloat) {
        guard bottom > top else { return }
        let r = CGRect(x: x - 4, y: top - 3, width: 8, height: bottom - top + 3)
        context.fill(rr(r, 2), with: across([stop(rgb(122, 128, 137), 0), stop(rgb(241, 243, 245), 0.4), stop(rgb(110, 116, 124), 1)], r.minX, r.maxX))
    }

    /// The multi-function pencil box lying in the basket: sky-blue plastic,
    /// the LCD let into its lid (its words: BikeClock), a pencil, stars.
    static func pencilBox(_ context: GraphicsContext, _ l: BikeLayout) {
        let r = l.box, c = BikePaint.box
        guard r.width > 0, r.height > 8 else { return }
        var lifted = context
        lifted.addFilter(.shadow(color: BikePaint.shade.opacity(0.38), radius: 3, x: 0, y: 3))
        lifted.fill(rr(r, 12), with: .color(c.color(-0.3)))
        let lid = CGRect(x: r.minX, y: r.minY, width: r.width, height: r.height - 6)
        context.fill(rr(lid, 12), with: vertical([stop(c.color(0.4), 0), stop(c.color(), 0.5), stop(c.color(-0.06), 1)], r.minY, r.maxY))
        context.stroke(rr(CGRect(x: r.minX + 1, y: r.minY + 1, width: r.width - 2, height: r.height - 8), 11), with: .color(Color.white.opacity(0.75)), lineWidth: 1.2)
        for one in l.stars { star(context, one) }
        if l.pencil.width > 30 { pencil(context, l.pencil) }
        if l.lcd.width > 0 {
            context.fill(rr(l.lcd.insetBy(dx: -2, dy: -2), 5), with: .color(rgb(16, 52, 90, 0.5)))
            context.fill(rr(l.lcd, 3.5), with: vertical([stop(rgb(191, 203, 171), 0), stop(rgb(162, 178, 145), 1)], l.lcd.minY, l.lcd.maxY))
        }
    }
    static func star(_ context: GraphicsContext, _ one: BikeStar) {
        var path = Path()
        for index in 0..<10 {
            let a = -Double.pi / 2 + Double(index) * Double.pi / 5
            let q: CGFloat = index % 2 == 1 ? one.radius * 0.45 : one.radius
            let p = CGPoint(x: one.at.x + CGFloat(cos(a)) * q, y: one.at.y + CGFloat(sin(a)) * q)
            if index == 0 { path.move(to: p) } else { path.addLine(to: p) }
        }
        path.closeSubpath()
        context.fill(path, with: .color(one.tint))
    }
    /// A yellow pencil on the lid: the eraser at the leading end, the point at the trailing one.
    static func pencil(_ context: GraphicsContext, _ r: CGRect) {
        let x0 = r.minX, x1 = r.maxX, y = r.midY, h = r.height, length = r.width
        let bx = x0 + 13, bw = max(0, length - 25), top = y - h / 2
        context.fill(rr(CGRect(x: x0 + 0.8, y: top + 1.8, width: max(0, length - 6), height: h), 2.5), with: .color(rgb(16, 52, 90, 0.3)))
        context.fill(rr(CGRect(x: x0, y: top, width: 9, height: h), 2.5), with: vertical([stop(rgb(255, 194, 208), 0), stop(rgb(231, 127, 154), 1)], top, top + h))
        context.fill(Path(CGRect(x: x0 + 8, y: top, width: 5, height: h)), with: vertical([stop(rgb(244, 245, 247), 0), stop(rgb(169, 175, 183), 0.5), stop(rgb(110, 116, 124), 1)], top, top + h))
        context.fill(Path(CGRect(x: bx, y: top, width: bw, height: h)), with: .color(rgb(255, 216, 74)))
        context.fill(Path(CGRect(x: bx, y: top, width: bw, height: h * 0.3)), with: .color(rgb(255, 240, 160)))
        context.fill(Path(CGRect(x: bx, y: y + h * 0.2, width: bw, height: h * 0.3)), with: .color(rgb(226, 173, 28)))
        var wood = Path()
        wood.move(to: CGPoint(x: bx + bw, y: top))
        wood.addLine(to: CGPoint(x: x1, y: y))
        wood.addLine(to: CGPoint(x: bx + bw, y: y + h / 2))
        wood.closeSubpath()
        context.fill(wood, with: .color(rgb(240, 207, 156)))
        var lead = Path()
        lead.move(to: CGPoint(x: x1 - 4.5, y: y - 1.5))
        lead.addLine(to: CGPoint(x: x1, y: y))
        lead.addLine(to: CGPoint(x: x1 - 4.5, y: y + 1.5))
        lead.closeSubpath()
        context.fill(lead, with: .color(rgb(56, 56, 56)))
    }

    /// The pinwheel's wooden stick down to the bar.
    static func stick(_ context: GraphicsContext, x: CGFloat, from y0: CGFloat, to y1: CGFloat) {
        guard y1 > y0 else { return }
        context.fill(rr(CGRect(x: x - 0.6, y: y0 + 2, width: 3.2, height: y1 - y0), 1.6), with: .color(BikePaint.shade.opacity(0.22)))
        context.fill(rr(CGRect(x: x - 1.6, y: y0, width: 3.2, height: y1 - y0), 1.6),
                     with: across([stop(rgb(217, 196, 154), 0), stop(rgb(246, 234, 208), 0.5), stop(rgb(189, 165, 116), 1)], x - 1.6, x + 1.6))
    }
    /// A short upright chrome post (the speedometer's stem).
    static func post(_ context: GraphicsContext, _ r: CGRect) {
        guard r.width > 0, r.height > 0 else { return }
        context.fill(rr(r.offsetBy(dx: 1.5, dy: 2), r.width / 3), with: .color(BikePaint.shade.opacity(0.25)))
        let metal = [stop(rgb(106, 112, 121), 0), stop(rgb(243, 245, 247), 0.35), stop(rgb(179, 185, 193), 0.6), stop(rgb(95, 101, 109), 1)]
        context.fill(rr(r, r.width / 3), with: across(metal, r.minX, r.maxX))
    }
    /// A clamp round the bar.
    static func clamp(_ context: GraphicsContext, _ r: CGRect) {
        let shape = rr(r, 2.5)
        let metal = [stop(rgb(117, 123, 132), 0), stop(rgb(244, 245, 247), 0.35), stop(rgb(154, 160, 168), 0.7), stop(rgb(102, 108, 116), 1)]
        context.fill(shape, with: across(metal, r.minX, r.maxX))
        context.stroke(shape, with: .color(Color.black.opacity(0.35)), lineWidth: 0.6)
    }
    /// The little tin plate the bell stands on, held across.
    static func bellBracket(_ context: GraphicsContext, _ r: CGRect) {
        context.fill(rr(r, 3), with: across([stop(rgb(117, 123, 132), 0), stop(rgb(244, 245, 247), 0.4), stop(rgb(102, 108, 116), 1)], r.minX, r.maxX))
    }
    /// A caramel rubber grip from its inner end outwards: ribbed, lit along
    /// its top, its collar at the bar.
    static func grip(_ context: GraphicsContext, from a: CGPoint, to b: CGPoint, _ t: CGFloat) {
        let length = hypot(b.x - a.x, b.y - a.y), turn = Double(atan2(b.y - a.y, b.x - a.x)), c = BikePaint.grip
        guard length > 1 else { return }
        let radii = RectangleCornerRadii(topLeading: t * 0.22, bottomLeading: t * 0.22, bottomTrailing: t * 0.5, topTrailing: t * 0.5)
        let sleeve = Path(roundedRect: CGRect(x: 0, y: -t / 2, width: length, height: t), cornerRadii: radii, style: .circular)
        var shadow = context
        shadow.translateBy(x: a.x, y: a.y + 3.5)
        shadow.rotate(by: .radians(turn))
        shadow.fill(sleeve, with: .color(BikePaint.shade.opacity(0.28)))
        var g = context
        g.translateBy(x: a.x, y: a.y)
        g.rotate(by: .radians(turn))
        let rubber = [stop(c.color(0.32), 0), stop(c.color(0.08), 0.3), stop(c.color(), 0.68), stop(c.color(-0.4), 1)]
        g.fill(sleeve, with: vertical(rubber, -t / 2, t / 2))
        var ribs = g
        ribs.clip(to: sleeve)
        var s: CGFloat = 11
        while s < length {
            ribs.fill(Path(CGRect(x: s, y: -t / 2, width: 1.4, height: t)), with: .color(c.color(-0.34).opacity(0.5)))
            ribs.fill(Path(CGRect(x: s + 1.4, y: -t / 2, width: 0.9, height: t)), with: .color(c.color(0.4).opacity(0.45)))
            s += 4.4
        }
        ribs.fill(Path(CGRect(x: 0, y: -t * 0.32, width: length, height: t * 0.14)), with: .color(Color.white.opacity(0.2)))
        g.fill(rr(CGRect(x: -1, y: -t / 2 - 1.8, width: 9, height: t + 3.6), 3), with: vertical([stop(c.color(0.25), 0), stop(c.color(-0.42), 1)], -t / 2, t / 2))
        g.stroke(sleeve, with: .color(rgb(50, 24, 8, 0.35)), lineWidth: 0.8)
    }
}

/// The bicycle under its parts, drawn part for part: the frame's mint
/// enamel and its sheen, the hinge's side in shade; held across ZERO on the
/// frame and the rubber pad where the Camera Control's overlay comes in;
/// the top tube; the wire basket, the wires the plate hangs from, the
/// lamp's bracket, the pencil box with its LCD's glass, its pencil and its
/// stars (not in 相册: the prints lie there); the basket's near rim; the
/// mirror's stalk; the pinwheel's stick, the speedometer's stem, the
/// shifter's foot; the handlebar, its clamps, its grips; the bell's bracket
/// held across. Drawn once (it is the same until the deck is another size).
private struct BikeBackdrop: View, Equatable {
    var layout: BikeLayout
    var hinge: CGRect
    var album: Bool
    var body: some View {
        Canvas { context, size in
            let l = layout
            BikeArt.body(context, size, hinge)
            if l.name != .zero { BikeArt.bandName(context, at: l.name) }
            if l.pad.width > 0 { BikeArt.pad(context, l.pad) }
            BikeArt.topTube(context, l)
            BikeArt.basket(context, l)
            BikeArt.plateWires(context, l.plate, hook: l.plateHook)
            BikeArt.bracket(context, x: l.lamp.x, from: l.lampBracket, to: l.lamp.y)
            if !album { BikeArt.pencilBox(context, l) }
            BikeArt.tube(context, BikeArt.segment(l.near0, l.near1), 7, drop: 2.5)
            BikeArt.tube(context, BikeArt.stalk(l.stalk), l.stalkWidth, drop: 2)
            BikeArt.stick(context, x: l.pinwheel.x, from: l.pinwheel.y, to: l.stickFoot)
            BikeArt.post(context, l.stem)
            if l.shifterFoot.width > 0 { context.fill(BikeArt.rr(l.shifterFoot, 3), with: .color(BikeArt.rgb(42, 46, 51))) }
            BikeArt.tube(context, BikeArt.run(l.bar), l.barWidth)
            for one in l.clamps { BikeArt.clamp(context, one) }
            if l.grips.count == 4 {
                BikeArt.grip(context, from: l.grips[0], to: l.grips[1], l.gripWidth)
                BikeArt.grip(context, from: l.grips[2], to: l.grips[3], l.gripWidth)
            }
            if l.bellBracket.width > 0 { BikeArt.bellBracket(context, l.bellBracket) }
        }
        .accessibilityHidden(true)
    }
}

/// The road's slim dark frame round the picture (over the picture's own
/// bezel), a light edge round it. Nothing over the picture itself.
private struct BikeRoadFrame: View, Equatable {
    var hole: CGRect
    var body: some View {
        Canvas { context, size in
            guard hole.width > 0, hole.height > 0 else { return }
            var ring = Path(roundedRect: hole.insetBy(dx: -6, dy: -6), cornerRadius: 12, style: .continuous)
            ring.addPath(Path(roundedRect: hole, cornerRadius: 8, style: .continuous))
            context.fill(ring, with: .color(BikePaint.frame), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: hole.insetBy(dx: -5.6, dy: -5.6), cornerRadius: 11.6, style: .continuous), with: .color(Color.white.opacity(0.5)), lineWidth: 1)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The pencil box's LCD: the date and the time (11·20 17:05), turning over
/// with the minute.
private struct BikeClock: View {
    var size: CGFloat
    var body: some View {
        TimelineView(.everyMinute) { context in
            Text(verbatim: BikeClock.stamp(context.date))
                .font(.system(size: size, weight: .heavy, design: .monospaced))
                .foregroundStyle(Color(red: 0.078, green: 0.118, blue: 0.071).opacity(0.88))
                .lineLimit(1).minimumScaleFactor(0.6)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
    static func stamp(_ date: Date) -> String {
        let c = Calendar.current.dateComponents([.month, .day, .hour, .minute], from: date)
        return String(format: "%d·%02d %02d:%02d", c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0)
    }
}

/// A strip of paper tape, its ends torn in zigzags, its shadow under it.
private struct BikeTapePaper: View, Equatable {
    var width: CGFloat
    var height: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), w = width, h = height
            let z: CGFloat = 2
            let n = max(3, Int((h / 3.2).rounded()))
            var path = Path()
            path.move(to: CGPoint(x: c.x - w / 2, y: c.y - h / 2))
            path.addLine(to: CGPoint(x: c.x + w / 2, y: c.y - h / 2))
            for rise in 1...n {
                let right: CGFloat = rise % 2 == 1 ? z : 0
                path.addLine(to: CGPoint(x: c.x + w / 2 + right, y: c.y - h / 2 + h * CGFloat(rise) / CGFloat(n)))
            }
            path.addLine(to: CGPoint(x: c.x - w / 2, y: c.y + h / 2))
            for fall in stride(from: n - 1, through: 0, by: -1) {
                let left: CGFloat = fall % 2 == 1 ? z : 0
                path.addLine(to: CGPoint(x: c.x - w / 2 - left, y: c.y - h / 2 + h * CGFloat(fall) / CGFloat(n)))
            }
            path.closeSubpath()
            var lifted = context
            lifted.addFilter(.shadow(color: BikePaint.shade.opacity(0.28), radius: 1.2, x: 0, y: 1))
            lifted.fill(path, with: .color(BikePaint.tape.color().opacity(0.97)))
        }
        .frame(width: width + 8, height: height + 8)
        .allowsHitTesting(false)
    }
}

/// A strip of paper tape with what a part shows on it: its glyph (drawn as
/// the part stands), and the figures by it where it has them.
private struct BikeTape<Content: View>: View {
    var size: CGSize
    var content: Content
    var body: some View {
        ZStack {
            BikeTapePaper(width: size.width, height: size.height).equatable()
            content
                .padding(.horizontal, 3)
        }
        .frame(width: size.width, height: size.height)
        .allowsHitTesting(false)
    }
}

/// Words printed on the body by a part (the bell's, the mirror's): not touched.
private struct BikeCaption: View {
    var first: String
    var second: String? = nil
    var firstInk: Color = BikePaint.ink
    var secondInk: Color = BikePaint.soft
    var size: CGFloat = 11.5
    var body: some View {
        VStack(spacing: 1) {
            Text(first).font(.system(size: size, weight: .black, design: .rounded)).foregroundStyle(firstInk)
            if let second {
                Text(second).font(.system(size: 10.5, weight: .heavy, design: .rounded)).foregroundStyle(secondInk)
            }
        }
        .lineLimit(1).minimumScaleFactor(0.6)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The tin plate: a rolled edge, two holes for its wires, ZERO pressed out of it.
private struct BikePlateFace: View, Equatable {
    var word: CGFloat
    var body: some View {
        Canvas { context, size in
            let w = size.width, h = size.height, c = BikePaint.plate
            let whole = CGRect(origin: .zero, size: size)
            context.fill(BikeArt.rr(whole, 6), with: BikeArt.vertical([BikeArt.stop(c.color(0.14), 0), BikeArt.stop(c.color(-0.2), 1)], 0, h))
            context.stroke(BikeArt.rr(whole.insetBy(dx: 0.8, dy: 0.8), 5.2), with: .color(Color.white.opacity(0.55)), lineWidth: 1.2)
            context.stroke(BikeArt.rr(CGRect(x: 4, y: 4, width: w - 8, height: h - 8), 3.5), with: .color(Color.black.opacity(0.3)), lineWidth: 1.2)
            context.stroke(BikeArt.rr(CGRect(x: 4.8, y: 4.8, width: w - 8, height: h - 8), 3.5), with: .color(Color.white.opacity(0.28)), lineWidth: 0.8)
            for hx in [CGFloat(12), w - 12] {
                let hole = BikeArt.disc(CGPoint(x: hx, y: 8), 2.3)
                context.fill(hole, with: .color(BikeArt.rgb(19, 42, 36)))
                context.stroke(hole, with: .color(Color.white.opacity(0.5)), lineWidth: 0.6)
            }
            let spacing = word * 0.34
            let pressed = Text(verbatim: "ZERO").font(.system(size: word, weight: .black, design: .rounded)).tracking(spacing)
            context.draw(pressed.foregroundColor(Color.black.opacity(0.35)), at: CGPoint(x: w / 2 + spacing / 2 + 1, y: h / 2 + 2))
            context.draw(pressed.foregroundColor(BikeArt.rgb(244, 236, 210)), at: CGPoint(x: w / 2 + spacing / 2, y: h / 2 + 1))
        }
    }
}

/// The tin plate as 机型: wired to the basket's rim, it swings on its two
/// wires a moment when pressed (about 3°; it only goes down a point with
/// Reduce Motion), with a thin tin's clatter. The tape under it (which does
/// not swing) shows two cameras traded (换机型; nil: no tape).
private struct BikePlateStyle: ButtonStyle {
    var plate: CGRect
    var word: CGFloat
    var hang: CGFloat
    var tape: CGRect
    var tapeGlyph: ShellGlyph? = nil
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { BikePlateBody(style: self, pressed: configuration.isPressed) }
}
private struct BikePlateBody: View {
    var style: BikePlateStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let s = style, p = s.plate
        let swing: Double = pressed && !reduceMotion ? 3 : 0
        let sink: CGFloat = pressed && reduceMotion ? 1 : 0
        let settle: Animation = reduceMotion || pressed ? .easeOut(duration: 0.06) : .spring(response: 0.3, dampingFraction: 0.3)
        ZStack(alignment: .topLeading) {
            if let glyph = s.tapeGlyph {
                BikeTape(size: s.tape.size, content: ShellGlyphView(glyph: glyph, size: 18, ink: BikePaint.ink))
                    .position(x: s.tape.midX, y: s.tape.midY)
            }
            BikePlateFace(word: s.word).equatable()
                .frame(width: p.width, height: p.height)
                .shadow(color: BikePaint.shade.opacity(0.42), radius: 2, y: 2.5)
                .rotationEffect(.degrees(swing), anchor: UnitPoint(x: 0.5, y: s.hang))
                .offset(y: sink)
                .position(x: p.midX, y: p.midY)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(settle, value: pressed)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            if !s.quiet { ConsoleSounds.shared.play(.tinLid, scale: 0.4) }
            ConsoleHaptics.shared.play(.smallButton, .press)
        }
    }
}

/// How the headlamp stands: lit (闪光 开, or against red eye), its pilot
/// glowing (自动), dark (关).
private enum BikeLamp: Equatable {
    case lit, waiting, dark
    static func of(_ flash: CameraFlashMode) -> BikeLamp {
        switch flash {
        case .on, .redEye: return .lit
        case .auto: return .waiting
        case .off: return .dark
        }
    }
}

/// The headlamp's glow round it when lit (none of it reaches the road) and
/// its cream shell.
private struct BikeLampShell: View, Equatable {
    var radius: CGFloat
    var lit: Bool
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            if lit {
                let glow = Gradient(colors: [BikeArt.rgb(255, 214, 110, 0.62), BikeArt.rgb(255, 214, 110, 0)])
                context.fill(BikeArt.disc(c, r * 1.75), with: .radialGradient(glow, center: c, startRadius: r * 0.8, endRadius: r * 1.75))
            }
            var lifted = context
            lifted.addFilter(.shadow(color: BikePaint.shade.opacity(0.42), radius: 2.5, x: 0, y: 3))
            let cream = BikePaint.cream
            let shell = Gradient(stops: [BikeArt.stop(Color.white, 0), BikeArt.stop(cream.color(), 0.45), BikeArt.stop(cream.color(-0.24), 1)])
            lifted.fill(BikeArt.disc(c, r + 6.5), with: .radialGradient(shell, center: CGPoint(x: c.x - r * 0.45, y: c.y - r * 0.55), startRadius: 2, endRadius: r * 1.7))
        }
    }
}

/// The headlamp's glass with its rings and spokes, the bulb (white-hot when
/// lit, a small amber pilot on 自动, grey when off), the visor over its top.
private struct BikeLampGlass: View, Equatable {
    var radius: CGFloat
    var lamp: BikeLamp
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            let lit = lamp == .lit
            let glass = BikeArt.disc(c, r)
            if lit {
                let hot = Gradient(stops: [BikeArt.stop(BikeArt.rgb(255, 254, 248), 0), BikeArt.stop(BikeArt.rgb(255, 244, 200), 0.35),
                                           BikeArt.stop(BikeArt.rgb(255, 212, 106), 0.78), BikeArt.stop(BikeArt.rgb(242, 163, 58), 1)])
                context.fill(glass, with: .radialGradient(hot, center: c, startRadius: 0, endRadius: r))
            } else {
                let cold = Gradient(stops: [BikeArt.stop(BikeArt.rgb(230, 235, 238), 0), BikeArt.stop(BikeArt.rgb(170, 180, 187), 0.5), BikeArt.stop(BikeArt.rgb(111, 123, 132), 1)])
                context.fill(glass, with: .radialGradient(cold, center: CGPoint(x: c.x - r * 0.25, y: c.y - r * 0.3), startRadius: 1, endRadius: r * 1.15))
            }
            var lens = context
            lens.clip(to: glass)
            let ringInk: Color = lit ? BikeArt.rgb(232, 150, 40, 0.32) : BikeArt.rgb(40, 52, 60, 0.22)
            var k: CGFloat = 0.34
            while k < 1 {
                lens.stroke(BikeArt.disc(c, r * k), with: .color(ringInk), lineWidth: 1)
                k += 0.16
            }
            var spokes = Path()
            for index in 0..<12 {
                let a = Double(index) * Double.pi / 6 + 0.26
                let ca = CGFloat(cos(a)), sa = CGFloat(sin(a))
                spokes.move(to: CGPoint(x: c.x + ca * r * 0.34, y: c.y + sa * r * 0.34))
                spokes.addLine(to: CGPoint(x: c.x + ca * r, y: c.y + sa * r))
            }
            lens.stroke(spokes, with: .color(Color.white.opacity(lit ? 0.4 : 0.25)), lineWidth: 0.8)
            if lamp == .waiting {
                let pilot = Gradient(stops: [BikeArt.stop(BikeArt.rgb(255, 214, 120, 0.95), 0), BikeArt.stop(BikeArt.rgb(244, 170, 60, 0.55), 0.55), BikeArt.stop(BikeArt.rgb(244, 170, 60, 0), 1)])
                context.fill(BikeArt.disc(c, r * 0.42), with: .radialGradient(pilot, center: c, startRadius: 0, endRadius: r * 0.42))
            }
            let bulb = BikeArt.disc(c, r * 0.2)
            let filament: Color = lit ? BikeArt.rgb(255, 253, 240) : (lamp == .waiting ? BikeArt.rgb(255, 200, 97) : BikeArt.rgb(200, 206, 210))
            context.fill(bulb, with: .color(filament))
            context.stroke(bulb, with: .color(Color.black.opacity(0.2)), lineWidth: 0.6)
            context.stroke(glass, with: .color(Color.black.opacity(0.4)), lineWidth: 1)
            // The visor over the glass's top.
            let v0 = Double.pi * 1.1, v1 = Double.pi * 1.9
            var visor = BikeArt.polyline(BikeArt.arc(c, r + 7.5, r + 7.5, from: v0, to: v1))
            for point in BikeArt.arc(c, r + 0.5, r + 0.5, from: v1, to: v0) { visor.addLine(to: point) }
            visor.closeSubpath()
            var shaded = context
            shaded.addFilter(.shadow(color: Color.black.opacity(0.35), radius: 1.2, x: 0, y: 1.5))
            let metal = [BikeArt.stop(Color.white, 0), BikeArt.stop(BikeArt.rgb(213, 217, 222), 0.35), BikeArt.stop(BikeArt.rgb(125, 131, 139), 1)]
            shaded.fill(visor, with: BikeArt.vertical(metal, c.y - r - 7.5, c.y - r * 0.4))
            context.stroke(BikeArt.polyline(BikeArt.arc(c, r + 7, r + 7, from: v0 + 0.04, to: v1 - 0.04)), with: .color(Color.white.opacity(0.9)), lineWidth: 0.9)
        }
    }
}

/// The headlamp from the front: its shell and glow, the bright bezel, the glass.
private struct BikeLampFace: View, Equatable {
    var radius: CGFloat
    var lamp: BikeLamp
    var body: some View {
        let r = radius
        let side = 2 * (r * 1.75 + 2)
        ZStack {
            BikeLampShell(radius: r, lit: lamp == .lit).equatable()
                .frame(width: side, height: side)
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(-1.9)))
                .overlay(Circle().strokeBorder(Color.black.opacity(0.25), lineWidth: 0.6))
                .frame(width: 2 * (r + 3.2), height: 2 * (r + 3.2))
            BikeLampGlass(radius: r, lamp: lamp).equatable()
                .frame(width: side, height: side)
        }
        .frame(width: side, height: side)
    }
}

/// The headlamp as 闪光: pressed, its head nods down a point with its
/// switch's hard click; its glass lights up or goes dark (0.15 s), or its
/// pilot comes on for 自动. The tape by it shows the bolt, drawn as it is
/// set (nil: no tape).
private struct BikeLampStyle: ButtonStyle {
    var lamp: CGPoint
    var radius: CGFloat
    var state: BikeLamp
    var tape: CGRect
    var glyph: ShellGlyph? = nil
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { BikeLampBody(style: self, pressed: configuration.isPressed) }
}
private struct BikeLampBody: View {
    var style: BikeLampStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let s = style
        ZStack(alignment: .topLeading) {
            if let glyph = s.glyph {
                BikeTape(size: s.tape.size, content: ShellGlyphView(glyph: glyph, size: s.tape.height >= 30 ? 20 : 13, ink: BikePaint.ink))
                    .position(x: s.tape.midX, y: s.tape.midY)
            }
            ZStack {
                BikeLampFace(radius: s.radius, lamp: s.state).equatable()
                    .id(s.state)
                    .transition(.opacity)
            }
            .animation(.easeOut(duration: 0.15), value: s.state)
            .offset(y: pressed ? 1 : 0)
            .position(x: s.lamp.x, y: s.lamp.y)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.1), value: pressed)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            if !s.quiet { ConsoleSounds.shared.play(.click, scale: 0.6) }
            ConsoleHaptics.shared.play(.smallButton, .press)
        }
    }
}

/// A print with its white edge (a ▶ on a video's; the one looked at in a red edge).
private struct BikePrintView: View {
    var image: CGImage?
    var width: CGFloat
    var edge: Color? = nil
    var play = false
    var body: some View {
        let inner = max(1, width - 8)
        let tall = inner * 0.75 + 8
        ZStack(alignment: .top) {
            RoundedRectangle(cornerRadius: 2, style: .continuous).fill(Color(red: 0.984, green: 0.980, blue: 0.961))
                .shadow(color: BikePaint.shade.opacity(0.38), radius: 2, y: 2)
            ZStack {
                Color(white: 0.82)
                if let image { Image(decorative: image, scale: 1).resizable().scaledToFill() }
                if play {
                    ZStack {
                        Circle().fill(Color.black.opacity(0.5))
                        Image(systemName: "play.fill").font(.system(size: 7.5, weight: .black)).foregroundStyle(Color.white).offset(x: 0.8)
                    }
                    .frame(width: 16, height: 16)
                }
            }
            .frame(width: inner, height: inner * 0.75)
            .clipped()
            .padding(.top, 4)
        }
        .frame(width: width, height: tall)
        .overlay {
            if let edge {
                RoundedRectangle(cornerRadius: 3.5, style: .continuous).strokeBorder(edge, lineWidth: 2.6).padding(-1.5)
            }
        }
    }
}

/// The kraft envelope: its flap's crease, a light edge.
private struct BikeEnvelopeFace: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let w = size.width, h = size.height, c = BikePaint.kraft
            let whole = CGRect(origin: .zero, size: size)
            context.fill(BikeArt.rr(whole, 4), with: BikeArt.vertical([BikeArt.stop(c.color(0.2), 0), BikeArt.stop(c.color(-0.1), 1)], 0, h))
            var flap = Path()
            flap.move(to: CGPoint(x: 3, y: 3))
            flap.addLine(to: CGPoint(x: w * 0.5, y: h * 0.42))
            flap.addLine(to: CGPoint(x: w - 3, y: 3))
            context.stroke(flap, with: .color(c.color(-0.22)), lineWidth: 1.2)
            context.stroke(BikeArt.rr(whole.insetBy(dx: 0.7, dy: 0.7), 3.4), with: .color(Color.white.opacity(0.4)), lineWidth: 1)
        }
    }
}

/// The photo envelope as 相册: pressed, it goes down a point and its prints
/// slide a little further out, with paper's rustle; two pictures (相册) and
/// how many on it. In 相册 it shows a camera and 回去拍照, its words kept
/// (the prints put back in it).
private struct BikeEnvelopeStyle: ButtonStyle {
    var envelope: CGRect
    var up = false
    var newest: CGImage? = nil
    var older: CGImage? = nil
    var count = 0
    var back = false
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { BikeEnvelopeBody(style: self, pressed: configuration.isPressed) }
}
private struct BikeEnvelopeBody: View {
    var style: BikeEnvelopeStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let s = style, e = s.envelope
        let out: CGFloat = pressed ? 2 : 0
        ZStack(alignment: .topLeading) {
            if !s.back, s.count > 0 { prints(e, out: out) }
            BikeEnvelopeFace().equatable()
                .frame(width: e.width, height: e.height)
                .shadow(color: BikePaint.shade.opacity(0.36), radius: 2.5, y: 2.5)
                .position(x: e.midX, y: e.midY)
            words(e)
        }
        .offset(y: pressed ? 1 : 0)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.05 : 0.12), value: pressed)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            if !s.quiet { ConsoleSounds.shared.play(.pageFlip, scale: 0.5) }
            ConsoleHaptics.shared.play(.smallButton, .press)
        }
    }
    @ViewBuilder private func prints(_ e: CGRect, out: CGFloat) -> some View {
        let s = style
        if s.up {
            let upWide = e.width * 0.62
            BikePrintView(image: s.older ?? s.newest, width: upWide)
                .rotationEffect(.radians(-0.16))
                .position(x: e.minX + e.width * 0.38, y: e.minY + 2 - out)
            BikePrintView(image: s.newest, width: upWide)
                .rotationEffect(.radians(0.12))
                .position(x: e.minX + e.width * 0.62, y: e.minY - out)
        } else {
            let sideWide = e.height * 0.86
            BikePrintView(image: s.older ?? s.newest, width: sideWide)
                .rotationEffect(.radians(-0.16))
                .position(x: e.maxX + 6 + out, y: e.midY + 2)
            BikePrintView(image: s.newest, width: sideWide)
                .rotationEffect(.radians(0.1))
                .position(x: e.maxX + 12 + out, y: e.midY - 1)
        }
    }
    @ViewBuilder private func words(_ e: CGRect) -> some View {
        let small = e.height < 50
        let wide = max(10, e.width - 6)
        if style.back {
            ShellGlyphView(glyph: .returnToShooting, size: small ? 15 : 19, ink: BikePaint.ink)
                .position(x: e.midX, y: e.minY + e.height * 0.34)
            Text(String(localized: "回去拍照")).font(.system(size: small ? 11.5 : 15, weight: .black, design: .rounded)).foregroundStyle(BikePaint.ink)
                .lineLimit(1).minimumScaleFactor(0.6)
                .frame(width: wide)
                .position(x: e.midX, y: e.minY + e.height * 0.72)
        } else {
            let brown = Color(red: 0.290, green: 0.204, blue: 0.063)
            ShellGlyphView(glyph: .album, size: small ? 15 : 18, ink: brown)
                .position(x: e.midX, y: e.minY + e.height * 0.45)
            Text(verbatim: "\(style.count)").font(.system(size: 11, weight: .heavy, design: .rounded)).monospacedDigit()
                .foregroundStyle(brown.opacity(0.8))
                .lineLimit(1).minimumScaleFactor(0.6)
                .frame(width: wide)
                .position(x: e.midX, y: e.minY + e.height * 0.79)
        }
    }
}

/// A pencil-box button's candy plastic, standing proud in its dark well;
/// down 2.2 points while pressed or while it is on (pale yellow then).
private struct BikePressCap: View, Equatable {
    var size: CGSize
    var down: Bool
    var latched: Bool
    var body: some View {
        Canvas { context, _ in
            let x: CGFloat = 3, y: CGFloat = 2, w = size.width, h = size.height
            let c: ShellTone = latched ? ShellTone(r: 1.0, g: 0.910, b: 0.549) : ShellTone(r: 1, g: 1, b: 1)
            context.fill(BikeArt.rr(CGRect(x: x - 1.5, y: y - 1, width: w + 3, height: h + 4), 10), with: .color(BikeArt.rgb(16, 52, 90, 0.34)))
            let dy: CGFloat = down ? 2.2 : 0
            let cap = BikeArt.rr(CGRect(x: x, y: y + dy, width: w, height: h - dy), 9)
            let plastic = [BikeArt.stop(c.color(0.5), 0), BikeArt.stop(c.color(), 0.45), BikeArt.stop(c.color(-0.13), 1)]
            var lifted = context
            if !down { lifted.addFilter(.shadow(color: BikeArt.rgb(16, 52, 90, 0.42), radius: 1.5, x: 0, y: 2)) }
            lifted.fill(cap, with: BikeArt.vertical(plastic, y, y + h))
            context.stroke(BikeArt.rr(CGRect(x: x + 0.7, y: y + dy + 0.7, width: w - 1.4, height: h - dy - 1.4), 8.3), with: .color(Color.white.opacity(0.95)), lineWidth: 1)
        }
        .frame(width: size.width + 6, height: size.height + 8)
    }
}

/// One press-button of the pencil box as a key: its glyph, drawn as what
/// it sets stands (浓淡's with a row of cells under it, as many filled as
/// the step it is at; 原生's a dash). Pressed, it goes down with a plastic
/// snap; one that is on (定时, 日期, 水平仪 while they are) stays down,
/// pale yellow, and catches with a second small click as it does.
private struct BikePressStyle: ButtonStyle {
    var glyph: ShellGlyph
    var cells: ShellGlyph? = nil
    var figures = ""
    var latched = false
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { BikePressBody(style: self, pressed: configuration.isPressed) }
}
private struct BikePressBody: View {
    var style: BikePressStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let s = style
        let down = pressed || s.latched
        let sink: CGFloat = down ? 2.2 : 0
        GeometryReader { geo in
            let size: CGFloat = geo.size.width >= 52 ? 18 : 16
            ZStack {
                BikePressCap(size: geo.size, down: down, latched: s.latched).equatable()
                    .offset(y: 2)
                VStack(spacing: 3) {
                    ShellGlyphView(glyph: s.glyph, size: size, ink: BikePaint.boxInk)
                    if let cells = s.cells {
                        ShellGlyphView(glyph: cells, size: 15, ink: BikePaint.boxSoft)
                    } else if !s.figures.isEmpty {
                        Text(verbatim: s.figures).font(.system(size: 10.5, weight: .heavy, design: .rounded)).foregroundStyle(BikePaint.boxSoft)
                            .lineLimit(1)
                    }
                }
                .padding(.horizontal, 3)
                .offset(y: 1 + sink / 2)
            }
            .frame(width: geo.size.width, height: geo.size.height)
        }
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.1), value: down)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            if !s.quiet { ConsoleSounds.shared.play(.keySlide, scale: 0.55) }
            ConsoleHaptics.shared.play(.smallButton, .press)
        }
        .onChange(of: s.latched) { _, now in
            guard now else { return }
            if !s.quiet { ConsoleSounds.shared.play(.keyRatchet, scale: 0.35) }
            ConsoleHaptics.shared.play(.sliderNotch, .press)
        }
    }
}

/// The mirror's glass: the sky and the road behind (外侧), or the one taking
/// the picture (内侧).
private struct BikeMirrorGlass: View, Equatable {
    var inner: Bool
    var body: some View {
        Canvas { context, size in
            let r = min(size.width, size.height) / 2, c = CGPoint(x: size.width / 2, y: size.height / 2)
            let whole = CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r)
            if inner {
                context.fill(Path(whole), with: BikeArt.vertical([BikeArt.stop(BikeArt.rgb(246, 230, 208), 0), BikeArt.stop(BikeArt.rgb(214, 190, 160), 1)], whole.minY, whole.maxY))
                context.fill(Path(ellipseIn: CGRect(x: c.x - r * 0.75, y: c.y + r * 0.42, width: r * 1.5, height: r * 0.9)), with: .color(BikePaint.paint.color(-0.25)))
                let head = BikeArt.disc(CGPoint(x: c.x, y: c.y - r * 0.08), r * 0.34)
                context.fill(head, with: .color(BikeArt.rgb(234, 196, 160)))
                var hair = context
                hair.clip(to: head)
                hair.fill(Path(CGRect(x: c.x - r, y: c.y - r * 0.5, width: 2 * r, height: r * 0.3)), with: .color(BikeArt.rgb(88, 66, 50)))
            } else {
                let sky = [BikeArt.stop(BikeArt.rgb(188, 216, 234), 0), BikeArt.stop(BikeArt.rgb(232, 241, 240), 0.5), BikeArt.stop(BikeArt.rgb(169, 195, 159), 0.52), BikeArt.stop(BikeArt.rgb(134, 161, 131), 1)]
                context.fill(Path(whole), with: BikeArt.vertical(sky, whole.minY, whole.maxY))
                var road = Path()
                road.move(to: CGPoint(x: c.x - r * 0.62, y: c.y + r))
                road.addLine(to: CGPoint(x: c.x - r * 0.06, y: c.y + r * 0.04))
                road.addLine(to: CGPoint(x: c.x + r * 0.06, y: c.y + r * 0.04))
                road.addLine(to: CGPoint(x: c.x + r * 0.62, y: c.y + r))
                road.closeSubpath()
                context.fill(road, with: .color(BikeArt.rgb(182, 171, 150)))
            }
        }
        .clipShape(Circle())
    }
}

/// The rear-view mirror: a dark rim, the bright bezel, the glass.
private struct BikeMirrorFace: View {
    var radius: CGFloat
    var inner: Bool
    var body: some View {
        let r = radius
        ZStack {
            Circle().fill(BikeArt.rgb(43, 48, 54))
                .frame(width: 2 * (r + 4), height: 2 * (r + 4))
                .shadow(color: BikePaint.shade.opacity(0.42), radius: 2.5, y: 2.5)
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(-2.5)))
                .frame(width: 2 * (r + 3.4), height: 2 * (r + 3.4))
            BikeMirrorGlass(inner: inner).equatable()
                .frame(width: 2 * r, height: 2 * r)
            Circle().strokeBorder(Color.black.opacity(0.42), lineWidth: 1)
                .frame(width: 2 * r, height: 2 * r)
            Circle().strokeBorder(Color.white.opacity(0.75), lineWidth: 0.8)
                .frame(width: 2 * (r + 3.2), height: 2 * (r + 3.2))
        }
    }
}

/// A part of the bicycle pressed: it goes down a little (`travel`), or
/// swings on what it hangs from (`swing` degrees about `anchor`, settling
/// back with a spring; left out with Reduce Motion); it sounds and is felt as
/// it goes down (no sound: quiet, as while a video is taken), and felt once
/// more as it is let go where it jingles on (`twice`: the house key).
private struct BikeKeyStyle: ButtonStyle {
    var travel: CGFloat = 1
    var swing: Double = 0
    var anchor: UnitPoint = .top
    var sound: ConsoleSound? = .click
    var scale: Float = 0.6
    var haptic: HapticPart = .smallButton
    var twice = false
    func makeBody(configuration: Configuration) -> some View { BikeKeyBody(configuration: configuration, style: self) }
}
private struct BikeKeyBody: View {
    let configuration: ButtonStyle.Configuration
    let style: BikeKeyStyle
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let down = configuration.isPressed, s = style
        let swung: Double = down && !reduceMotion ? s.swing : 0
        let springy = !reduceMotion && s.swing != 0 && !down
        let settle: Animation = springy ? .spring(response: 0.34, dampingFraction: 0.3) : .easeOut(duration: down ? 0.05 : 0.1)
        configuration.label
            .rotationEffect(.degrees(swung), anchor: s.anchor)
            .offset(y: down ? s.travel : 0)
            .padding(room)
            .contentShape(Rectangle())
            .animation(settle, value: down)
            .onChange(of: down) { _, now in
                if now {
                    if let sound = s.sound { ConsoleSounds.shared.play(sound, scale: s.scale) }
                    ConsoleHaptics.shared.play(s.haptic, .press)
                } else if s.twice {
                    ConsoleHaptics.shared.play(s.haptic, .release)
                }
            }
    }
}

/// 内 / 外 as the rear-view mirror on its stalk: pressed it gives a little on
/// its ball joint with the joint's knock; when the other camera comes it
/// turns right round and back, the other view in its glass then (at once with
/// Reduce Motion). Held across a tape under it shows a camera turning (nil:
/// no tape; the glass shows which side).
private struct BikeMirrorKey: View {
    var mirror: CGPoint
    var radius: CGFloat
    var inner: Bool
    var tape: CGRect = .zero
    var tapeGlyph: ShellGlyph? = nil
    var quiet = false
    var action: () -> Void
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var shown: Bool? = nil
    @State private var turn: Double = 0
    var body: some View {
        Button(action: action) {
            ZStack(alignment: .topLeading) {
                if let tapeGlyph {
                    BikeTape(size: tape.size, content: ShellGlyphView(glyph: tapeGlyph, size: 16, ink: BikePaint.ink))
                        .position(x: tape.midX, y: tape.midY)
                }
                BikeMirrorFace(radius: radius, inner: shown ?? inner)
                    .rotation3DEffect(.degrees(turn), axis: (x: 0, y: 1, z: 0), perspective: 0.5)
                    .position(x: mirror.x, y: mirror.y)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
        .buttonStyle(BikeKeyStyle(travel: 0.8, sound: quiet ? nil : .click, scale: 0.55))
        .onAppear { shown = inner }
        .onChange(of: inner) { _, now in turnOver(to: now) }
    }
    private func turnOver(to now: Bool) {
        guard !reduceMotion else { shown = now; return }
        withAnimation(.easeIn(duration: 0.12)) { turn = 90 }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 120_000_000)
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) {
                shown = now
                turn = -90
            }
            withAnimation(.easeOut(duration: 0.14)) { turn = 0 }
        }
    }
}

/// The house key on its split ring round the bar: a little tag with a
/// house on it (主菜单), and the brass key hanging beside it. (`ring`: the
/// ring's middle.)
private struct BikeHomeFace: View, Equatable {
    var ring: CGPoint
    var body: some View {
        ZStack(alignment: .topLeading) {
            tagAndKey
            // The house on the tag, turned with it (its middle, from the ring's).
            ShellGlyphView(glyph: .home, size: 15, ink: BikePaint.ink)
                .rotationEffect(.radians(0.08))
                .position(x: ring.x - 8.3, y: ring.y + 22.9)
        }
    }
    private var tagAndKey: some View {
        Canvas { context, size in
            let cx = ring.x, top = ring.y - 4
            let wire = BikeArt.rgb(127, 133, 141)
            context.stroke(Path(ellipseIn: CGRect(x: cx - 6, y: top - 3.5, width: 12, height: 15)), with: .color(wire), lineWidth: 2.4)
            context.stroke(BikeArt.polyline(BikeArt.arc(CGPoint(x: cx, y: top + 4), 6, 7.5, from: 3.4, to: 5.8, steps: 12)), with: .color(BikeArt.rgb(242, 244, 246)), lineWidth: 1)
            // The tag.
            var tag = context
            tag.translateBy(x: cx - 6, y: top + 11)
            tag.rotate(by: .radians(0.08))
            var lifted = tag
            lifted.addFilter(.shadow(color: BikePaint.shade.opacity(0.32), radius: 1.5, x: 0, y: 1.5))
            lifted.fill(BikeArt.rr(CGRect(x: -23, y: 4, width: 44, height: 24), 6), with: .color(BikePaint.tape.color()))
            tag.stroke(BikeArt.rr(CGRect(x: -20.5, y: 6.5, width: 39, height: 19), 4.5), with: .color(BikePaint.ink.opacity(0.45)), lineWidth: 1)
            tag.stroke(BikeArt.segment(CGPoint(x: 4, y: 4), CGPoint(x: 6, y: -4)), with: .color(wire), lineWidth: 1.4)
            // The brass key.
            var key = context
            key.translateBy(x: cx + 9, y: top + 9)
            key.rotate(by: .radians(-0.5))
            let b = BikePaint.brass
            var blade = Path()
            blade.addEllipse(in: CGRect(x: -6.5, y: -0.5, width: 13, height: 13))
            blade.move(to: CGPoint(x: -2.2, y: 11))
            for point in [CGPoint(x: 2.2, y: 11), CGPoint(x: 2.2, y: 30), CGPoint(x: 5.5, y: 30), CGPoint(x: 5.5, y: 27), CGPoint(x: 2.2, y: 25),
                          CGPoint(x: 2.2, y: 22), CGPoint(x: 4.5, y: 22), CGPoint(x: 2.2, y: 19), CGPoint(x: -2.2, y: 19)] {
                blade.addLine(to: point)
            }
            blade.closeSubpath()
            var shaded = key
            shaded.addFilter(.shadow(color: BikePaint.shade.opacity(0.32), radius: 1, x: 0, y: 1.5))
            shaded.fill(blade, with: .linearGradient(Gradient(colors: [b.color(0.45), b.color(-0.25)]), startPoint: CGPoint(x: -6, y: 0), endPoint: CGPoint(x: 6, y: 12)))
            key.fill(BikeArt.disc(CGPoint(x: 0, y: 6), 2.2), with: .color(BikePaint.paint.color()))
        }
    }
}

/// The paper pinwheel: four vanes still, or a whirl of their colours while
/// it spins fast (a video being taken, or played in 相册).
private struct BikePinwheelFace: View, Equatable {
    var radius: CGFloat
    var whirl: Bool
    static let colours: [ShellTone] = [ShellTone(r: 0.925, g: 0.337, b: 0.275), ShellTone(r: 0.988, g: 0.776, b: 0.227),
                                       ShellTone(r: 0.329, g: 0.620, b: 0.902), ShellTone(r: 0.361, g: 0.761, b: 0.463)]
    var body: some View {
        Canvas { context, size in
            let g = context
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius, a0 = -0.35
            func point(_ angle: Double, _ q: CGFloat) -> CGPoint {
                CGPoint(x: c.x + CGFloat(cos(angle)) * q, y: c.y + CGFloat(sin(angle)) * q)
            }
            func vane(_ a: Double, _ tone: ShellTone, _ alpha: Double) {
                let tip = point(a, r), base = point(a + Double.pi / 2, r * 0.36), knee = point(a + 1.0, r * 0.98), fold = point(a + 0.42, r * 0.52)
                var sail = Path()
                sail.move(to: c)
                sail.addLine(to: tip)
                sail.addQuadCurve(to: base, control: knee)
                sail.closeSubpath()
                g.fill(sail, with: .color(tone.color().opacity(alpha)))
                var crease = Path()
                crease.move(to: c)
                crease.addLine(to: tip)
                crease.addLine(to: fold)
                crease.closeSubpath()
                g.fill(crease, with: .color(tone.color(-0.2).opacity(alpha)))
            }
            if whirl {
                g.fill(BikeArt.disc(c, r * 0.97), with: .color(BikeArt.rgb(255, 250, 240, 0.55)))
                for blur in 0..<7 {
                    for side in 0..<4 {
                        vane(a0 + Double(side) * Double.pi / 2 + Double(blur) * 0.22, Self.colours[side], blur == 6 ? 0.5 : 0.17)
                    }
                }
                for streak in 0..<3 {
                    let start = a0 + Double(streak) * 1.3
                    let q: CGFloat = r * (0.5 + CGFloat(streak) * 0.2)
                    g.stroke(BikeArt.polyline(BikeArt.arc(c, q, q, from: start, to: start + 1.7, steps: 16)), with: .color(Color.white.opacity(0.85)),
                             style: StrokeStyle(lineWidth: 1.5, lineCap: .round))
                }
            } else {
                for quarter in 0..<4 { vane(a0 + Double(quarter) * Double.pi / 2, Self.colours[quarter], 1) }
            }
            let pin = BikeArt.disc(c, 3.6)
            g.fill(pin, with: .color(Color.white))
            g.stroke(pin, with: .color(Color.black.opacity(0.3)), lineWidth: 0.8)
        }
    }
}

/// The pinwheel turning: it whirls while a video is taken (or played, in
/// 相册), turns slowly in 录像 while it waits, and is blown round a moment
/// when touched; it slows to a stop rather than stopping dead. Still with
/// Reduce Motion (the whirl then drawn without moving).
private struct BikePinwheel: View {
    var radius: CGFloat
    var whirl: Bool
    var breeze: Bool
    var kick: Int
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var phase: Double = 0
    @State private var since = Date()
    @State private var speed: Double = 0
    @State private var generation = 0
    /// Degrees a second.
    private var target: Double { whirl ? 900 : (breeze ? 120 : 0) }
    private func angle(at date: Date) -> Double { phase + speed * date.timeIntervalSince(since) }
    private func set(_ next: Double) {
        let now = Date()
        phase = angle(at: now).truncatingRemainder(dividingBy: 360)
        since = now
        speed = next
    }
    /// From `start` down to the speed it should have, a step at a time.
    private func settle(from start: Double) {
        generation += 1
        let mine = generation
        set(start)
        Task { @MainActor in
            for step in 1...8 {
                try? await Task.sleep(nanoseconds: 120_000_000)
                guard generation == mine else { return }
                let goal = target
                set(goal + (start - goal) * Double(8 - step) / 8)
            }
        }
    }
    var body: some View {
        let face = BikePinwheelFace(radius: radius, whirl: whirl).equatable()
        let side = 2 * radius + 4
        Group {
            if reduceMotion {
                face
            } else {
                TimelineView(.animation(minimumInterval: 1.0 / 30, paused: speed == 0)) { context in
                    face.rotationEffect(.degrees(angle(at: context.date)))
                }
            }
        }
        .frame(width: side, height: side)
        .shadow(color: BikePaint.shade.opacity(whirl ? 0.12 : 0.22), radius: 0.5, x: 1.5, y: 3)
        .onAppear { set(reduceMotion ? 0 : target) }
        .onChange(of: target) { old, now in
            guard !reduceMotion else { return }
            if now < old {
                settle(from: old)
            } else {
                generation += 1
                set(now)
            }
        }
        .onChange(of: kick) { _, _ in
            guard !reduceMotion else { return }
            settle(from: max(target, 1080))
        }
    }
}

/// What the pinwheel's tape shows: 拍照 / 录像's two glyphs (the one it is
/// set to filled and darker, the other paler), or one glyph and the figures
/// by it (a video camera and the time while one is taken; in 相册 ▶ or the
/// square, and a video's length once it is known).
private enum BikeWheelTape {
    case modes(video: Bool)
    case glyph(ShellGlyph, figures: String)
}

/// What is on the pinwheel's tape (red while a video is taken).
private struct BikeWheelMarks: View {
    var mark: BikeWheelTape
    var alarm: Bool
    var small: Bool
    var body: some View {
        let size: CGFloat = small ? 13 : 15
        let ink: Color = alarm ? BikePaint.alarm : BikePaint.ink
        switch mark {
        case .modes(let video):
            HStack(spacing: small ? 5 : 7) {
                ShellGlyphView(glyph: .photo(!video), size: size, ink: video ? BikePaint.dim : BikePaint.ink)
                ShellGlyphView(glyph: .video(video), size: size, ink: video ? BikePaint.ink : BikePaint.dim)
            }
        case .glyph(let shown, let figures):
            HStack(spacing: 3) {
                ShellGlyphView(glyph: shown, size: size, ink: ink)
                if !figures.isEmpty {
                    Text(verbatim: figures).font(.system(size: small ? 10 : 10.5, weight: .heavy, design: .rounded)).monospacedDigit()
                        .foregroundStyle(ink)
                        .lineLimit(1).minimumScaleFactor(0.6)
                        .accessibilityHidden(true)
                }
            }
        }
    }
}

/// The pinwheel as 拍照 / 录像 (in 相册, 播放): a touch blows it round with
/// its paper sails' whirr; the tape under it shows what it is set to (red
/// while a video is taken, with the time).
private struct BikePinwheelStyle: ButtonStyle {
    var pinwheel: CGPoint
    var radius: CGFloat
    var whirl: Bool
    var breeze: Bool
    var tape: CGRect
    var mark: BikeWheelTape
    var alarm = false
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { BikePinwheelBody(style: self, pressed: configuration.isPressed) }
}
private struct BikePinwheelBody: View {
    var style: BikePinwheelStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    @State private var kick = 0
    var body: some View {
        let s = style
        ZStack(alignment: .topLeading) {
            BikePinwheel(radius: s.radius, whirl: s.whirl, breeze: s.breeze, kick: kick)
                .position(x: s.pinwheel.x, y: s.pinwheel.y)
            BikeTape(size: s.tape.size, content: BikeWheelMarks(mark: s.mark, alarm: s.alarm, small: s.tape.height < 30))
                .offset(y: pressed ? 1 : 0)
                .position(x: s.tape.midX, y: s.tape.midY)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.1), value: pressed)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            kick += 1
            if !s.quiet { ConsoleSounds.shared.play(.pinwheel, scale: 0.5) }
            ConsoleHaptics.shared.play(.sliderNotch, .press)
        }
    }
}

/// The speedometer's two arms out to its studs (under its bezel).
private struct BikeSpeedoArms: View, Equatable {
    var radius: CGFloat
    var reach: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2)
            var arms = Path()
            for degrees in [145.0, 35.0] {
                let a = degrees * Double.pi / 180
                let ca = CGFloat(cos(a)), sa = CGFloat(sin(a))
                arms.move(to: CGPoint(x: c.x + ca * radius * 0.8, y: c.y + sa * radius * 0.8))
                arms.addLine(to: CGPoint(x: c.x + ca * reach, y: c.y + sa * reach))
            }
            context.stroke(arms, with: .color(BikeArt.rgb(79, 85, 93)), style: StrokeStyle(lineWidth: 9, lineCap: .round))
        }
    }
}

/// The speedometer's face: cream, its ticks, .5 1 2 4 over the top (.5
/// faint without an ultra wide; the one the needle is at is BikeSpeedoMark's),
/// the small dark window (the zoom; the time while a video is taken). (Its
/// name, a magnifying glass, is BikeSpeedoDial's.)
private struct BikeSpeedoFace: View, Equatable {
    var radius: CGFloat
    var at: Int
    var wide: Bool
    var window: String
    var alarm: Bool
    var dim: Bool
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            let ink: Color = dim ? BikeArt.rgb(38, 42, 48, 0.35) : BikeArt.rgb(38, 42, 48)
            let face = BikeArt.disc(c, r)
            let cream = Gradient(colors: [BikeArt.rgb(255, 253, 244), BikeArt.rgb(233, 225, 200)])
            context.fill(face, with: .radialGradient(cream, center: CGPoint(x: c.x, y: c.y - r * 0.3), startRadius: 2, endRadius: r * 1.2))
            context.stroke(face, with: .color(Color.black.opacity(0.35)), lineWidth: 1)
            var major = Path(), minor = Path()
            for k in 0...12 {
                let a = (180 + 15 * Double(k)) * Double.pi / 180
                let big = k % 4 == 0
                let r0: CGFloat = r * (big ? 0.74 : 0.82)
                let ca = CGFloat(cos(a)), sa = CGFloat(sin(a))
                let from = CGPoint(x: c.x + ca * r0, y: c.y + sa * r0), to = CGPoint(x: c.x + ca * r * 0.93, y: c.y + sa * r * 0.93)
                if big {
                    major.move(to: from)
                    major.addLine(to: to)
                } else {
                    minor.move(to: from)
                    minor.addLine(to: to)
                }
            }
            context.stroke(major, with: .color(BikeArt.rgb(38, 42, 48)), style: StrokeStyle(lineWidth: 2, lineCap: .round))
            context.stroke(minor, with: .color(BikeArt.rgb(38, 42, 48, 0.55)), style: StrokeStyle(lineWidth: 1, lineCap: .round))
            for index in 0..<4 {
                if index == at && !dim { continue }
                let faint = !wide && index == 0
                let colour: Color = faint ? ink.opacity(0.4) : ink
                let figure = Text(verbatim: BikeSpeedoDial.figures[index]).font(.system(size: max(10, r * 0.28), weight: .black, design: .rounded)).foregroundColor(colour)
                context.draw(figure, at: BikeSpeedoDial.figurePoint(index, c, r))
            }
            let ww: CGFloat = max(r * 0.92, window.count > 3 ? r * 1.3 : 0)
            let wh: CGFloat = max(13, r * 0.34)
            let wy: CGFloat = c.y + r * 0.48
            context.fill(BikeArt.rr(CGRect(x: c.x - ww / 2, y: wy, width: ww, height: wh), 2.5), with: .color(BikeArt.rgb(32, 36, 42)))
            let shownInk: Color = alarm ? BikeArt.rgb(255, 106, 85) : BikeArt.rgb(242, 239, 228)
            context.draw(Text(verbatim: window).font(.system(size: 10, weight: .heavy, design: .rounded)).foregroundColor(shownInk), at: CGPoint(x: c.x, y: wy + wh / 2))
        }
    }
}

/// The figure the needle is at: red, kept readable over the needle by a
/// cream edge round it.
private struct BikeSpeedoMark: View, Equatable {
    var radius: CGFloat
    var at: Int
    var body: some View {
        Canvas { context, size in
            guard BikeSpeedoDial.figures.indices.contains(at) else { return }
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            let p = BikeSpeedoDial.figurePoint(at, c, r)
            let figure = Text(verbatim: BikeSpeedoDial.figures[at]).font(.system(size: max(10, r * 0.32), weight: .black, design: .rounded))
            let edge = figure.foregroundColor(BikeArt.rgb(255, 253, 244))
            let around: [CGPoint] = [CGPoint(x: -1.4, y: 0), CGPoint(x: 1.4, y: 0), CGPoint(x: 0, y: -1.4), CGPoint(x: 0, y: 1.4),
                                     CGPoint(x: -1, y: -1), CGPoint(x: 1, y: -1), CGPoint(x: -1, y: 1), CGPoint(x: 1, y: 1)]
            for d in around { context.draw(edge, at: CGPoint(x: p.x + d.x, y: p.y + d.y)) }
            context.draw(figure.foregroundColor(BikePaint.accent), at: p)
        }
        .allowsHitTesting(false)
    }
}

/// The red needle, from a little behind the middle out towards the figures,
/// pointing right (turned to where it points).
private struct BikeNeedle: View, Equatable {
    var radius: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            var needle = Path()
            needle.move(to: CGPoint(x: c.x - r * 0.2, y: c.y - 1.8))
            needle.addLine(to: CGPoint(x: c.x + r * 0.86, y: c.y - 0.6))
            needle.addLine(to: CGPoint(x: c.x + r * 0.86, y: c.y + 0.6))
            needle.addLine(to: CGPoint(x: c.x - r * 0.2, y: c.y + 1.8))
            needle.closeSubpath()
            context.fill(needle, with: .color(BikePaint.red.color()))
        }
    }
}

/// The speedometer as the zoom's dial: the dark rim and the bright bezel,
/// the arms out to its studs, the face, the needle at the zoom (it swings to
/// a new stop and a little past it before it settles; at once with Reduce
/// Motion), the pivot. While a video is taken its window counts the seconds
/// (with Reduce Motion it only says 录像中; the pinwheel's tape keeps the
/// time). Paler and without its needle while it waits (相册).
private struct BikeSpeedoDial: View {
    var radius: CGFloat
    var reach: CGFloat
    var zoom: Double
    var wide: Bool
    var window: String
    var alarm = false
    var dim = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    static let figures = [".5", "1", "2", "4"]
    static let stops: [Double] = [0.5, 1, 2, 4]
    /// Where figure `index` stands on a face of radius `r` round `c`.
    static func figurePoint(_ index: Int, _ c: CGPoint, _ r: CGFloat) -> CGPoint {
        let a = (180 + 60 * Double(index)) * Double.pi / 180
        let q: CGFloat = r * (index == 0 || index == 3 ? 0.52 : 0.55)
        return CGPoint(x: c.x + CGFloat(cos(a)) * q, y: c.y + CGFloat(sin(a)) * q + 1)
    }
    /// Where the needle points for a zoom (degrees from the right, y down: .5 left, 4 right).
    static func angle(_ zoom: Double) -> Double { 240 + 60 * log2(min(4, max(0.5, zoom))) }
    var body: some View {
        let r = radius
        let at = Self.stops.lastIndex { $0 <= zoom + 0.05 } ?? 0
        let turn = Self.angle(zoom)
        let side = 2 * (reach + 14)
        let shown: String = reduceMotion && alarm ? "● " + String(localized: "录像中") : window
        let nameInk: Color = dim ? BikeArt.rgb(38, 42, 48, 0.35) : BikeArt.rgb(38, 42, 48, 0.72)
        ZStack {
            BikeSpeedoArms(radius: r, reach: reach).equatable()
                .frame(width: side, height: side)
            Circle().fill(BikeArt.rgb(43, 48, 53))
                .frame(width: 2 * (r + 6), height: 2 * (r + 6))
                .shadow(color: BikePaint.shade.opacity(0.45), radius: 3, y: 3)
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(-2.0)))
                .frame(width: 2 * (r + 5), height: 2 * (r + 5))
            Circle().strokeBorder(Color.white.opacity(0.85), lineWidth: 0.9)
                .frame(width: 2 * (r + 4.85), height: 2 * (r + 4.85))
            BikeSpeedoFace(radius: r, at: at, wide: wide, window: shown, alarm: alarm, dim: dim).equatable()
                .frame(width: 2 * r, height: 2 * r)
            // Its name on the face, under the needle: a magnifying glass.
            ShellGlyphView(glyph: .zoom, size: max(10, r * 0.3), ink: nameInk)
                .offset(y: r * 0.25)
            if !dim {
                BikeNeedle(radius: r).equatable()
                    .frame(width: 2 * r, height: 2 * r)
                    .rotationEffect(.degrees(turn))
                    .shadow(color: Color.black.opacity(0.35), radius: 1, x: 0, y: 1.2)
                    .animation(reduceMotion ? nil : .spring(response: 0.36, dampingFraction: 0.55), value: turn)
                BikeSpeedoMark(radius: r, at: at).equatable()
                    .frame(width: 2 * r, height: 2 * r)
            }
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(1)))
                .overlay(Circle().strokeBorder(Color.black.opacity(0.35), lineWidth: 0.6))
                .frame(width: r * 0.26, height: r * 0.26)
        }
        .frame(width: side, height: side)
        .opacity(dim ? 0.6 : 1)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// One of the speedometer's studs (− or ＋) as a key, the half of the dial
/// on its side touched with it: the stud goes down 1.5 points, felt as a
/// notch (the needle's tick is heard as it comes to rest: bikeZoom).
private struct BikeStudStyle: ButtonStyle {
    var stud: CGPoint
    var radius: CGFloat
    var sign: String
    func makeBody(configuration: Configuration) -> some View { BikeStudBody(style: self, pressed: configuration.isPressed) }
}
private struct BikeStudBody: View {
    var style: BikeStudStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let s = style, r = s.radius
        let sink: CGFloat = pressed ? 1.5 : 0
        ZStack(alignment: .topLeading) {
            ZStack {
                Circle().fill(BikePaint.shade.opacity(0.4))
                    .frame(width: 2 * (r + 1.6), height: 2 * (r + 1.6))
                    .offset(y: 1.6)
                Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(0.4)))
                    .overlay(Circle().strokeBorder(Color.white.opacity(0.85), lineWidth: 0.9))
                    .overlay(Circle().strokeBorder(Color.black.opacity(0.3), lineWidth: 0.6))
                    .frame(width: 2 * r, height: 2 * r)
                    .offset(y: sink)
                Text(verbatim: s.sign).font(.system(size: r * 1.5, weight: .black, design: .rounded)).foregroundStyle(BikeArt.rgb(38, 42, 48))
                    .offset(y: sink)
            }
            .position(x: s.stud.x, y: s.stud.y)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.1), value: pressed)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            ConsoleHaptics.shared.play(.sliderNotch, .press)
        }
    }
}

/// The shifter's housing and its window: a gear for each lens (and each 机型
/// pinned among them) — numbered, the one in use white on red, while nine or
/// fewer; a tick each, the one in use red, when there are more. (In 相册 the
/// pictures, the same way.)
private struct BikeShifterFace: View, Equatable {
    var count: Int
    var at: Int
    var body: some View {
        Canvas { context, size in
            let w = size.width, wh = size.height
            var lifted = context
            lifted.addFilter(.shadow(color: BikePaint.shade.opacity(0.4), radius: 2.5, x: 0, y: 2.5))
            lifted.fill(BikeArt.rr(CGRect(x: 0, y: 0, width: w, height: wh), 10), with: BikeArt.vertical([BikeArt.stop(BikeArt.rgb(77, 83, 91), 0), BikeArt.stop(BikeArt.rgb(35, 39, 44), 1)], 0, wh))
            context.stroke(BikeArt.rr(CGRect(x: 0.7, y: 0.7, width: w - 1.4, height: wh - 1.4), 9.3), with: .color(Color.white.opacity(0.3)), lineWidth: 1)
            let window = CGRect(x: 5, y: 5, width: w - 10, height: wh - 10)
            context.fill(BikeArt.rr(window, 6), with: BikeArt.vertical([BikeArt.stop(BikeArt.rgb(247, 244, 234), 0), BikeArt.stop(BikeArt.rgb(220, 213, 193), 1)], window.minY, window.maxY))
            guard count > 0 else { return }
            let t0 = window.minX + 7, t1 = window.maxX - 7
            if count <= 9 {
                let pitch: CGFloat = count > 1 ? (t1 - t0) / CGFloat(count - 1) : 0
                let tab: CGFloat = min(13, max(9, pitch + 3))
                for index in 0..<count {
                    let tx: CGFloat = count > 1 ? t0 + pitch * CGFloat(index) : (t0 + t1) / 2
                    let chosen = index == at
                    if chosen {
                        context.fill(BikeArt.rr(CGRect(x: tx - tab / 2, y: window.minY + 1.5, width: tab, height: 13), 3.5), with: .color(BikePaint.red.color()))
                    }
                    let digitInk: Color = chosen ? Color.white : BikeArt.rgb(30, 34, 38, 0.62)
                    let digit = Text(verbatim: "\(index + 1)").font(.system(size: 10, weight: .black, design: .rounded)).foregroundColor(digitInk)
                    context.draw(digit, at: CGPoint(x: tx, y: window.minY + 8.6))
                }
            } else {
                let ticks = 13
                let lit = Int((Double(at) / Double(max(1, count - 1)) * Double(ticks - 1)).rounded())
                for tick in 0..<ticks {
                    let px = t0 + (t1 - t0) * CGFloat(tick) / CGFloat(ticks - 1)
                    let on = tick == lit
                    let half: CGFloat = on ? 1.6 : 0.8
                    let tall: CGFloat = on ? 10 : 6
                    let mark = CGRect(x: px - half, y: window.minY + 3, width: 2 * half, height: tall)
                    let markInk: Color = on ? BikePaint.red.color() : BikeArt.rgb(38, 42, 48, 0.5)
                    context.fill(BikeArt.rr(mark, 1), with: .color(markInk))
                }
            }
        }
    }
}

/// The shifter's window with the name of the gear it is in under its gears
/// (the lens's own glyph before it; in 相册, of how many after it).
private struct BikeShifterWindow: View {
    var count: Int
    var at: Int
    var name: String
    var tag: ShellGlyph? = nil
    var tail: String = ""
    var nameSize: CGFloat = 12.5
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, wh = geo.size.height
            let inner: CGFloat = wh - 10
            let line: CGFloat = 5 + inner - (inner < 30 ? 6.5 : 9)
            let room: CGFloat = max(10, w - 10)
            let share: CGFloat = tag == nil && tail.isEmpty ? 0.9 : 0.6
            let middle: CGFloat = !tail.isEmpty ? 0.4 : (tag != nil ? 0.6 : 0.5)
            ZStack(alignment: .topLeading) {
                BikeShifterFace(count: count, at: at).equatable()
                    .frame(width: w, height: wh)
                if let tag {
                    ShellGlyphView(glyph: tag, size: 13, ink: BikeArt.rgb(30, 34, 38, 0.62))
                        .frame(width: 24, alignment: .leading)
                        .position(x: 21, y: line + 0.5)
                }
                Text(name).font(.system(size: nameSize, weight: .black, design: .rounded)).foregroundStyle(BikeArt.rgb(30, 34, 38))
                    .lineLimit(1).minimumScaleFactor(0.6)
                    .frame(width: room * share)
                    .position(x: 5 + room * middle, y: line)
                if !tail.isEmpty {
                    Text(verbatim: tail).font(.system(size: 10, weight: .heavy, design: .rounded)).foregroundStyle(BikeArt.rgb(30, 34, 38, 0.72))
                        .lineLimit(1).minimumScaleFactor(0.7)
                        .frame(width: 30, alignment: .trailing)
                        .position(x: w - 24, y: line + 0.5)
                }
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// One of the shifter's thumb levers as a key (its glyph: ‹ or › by the
/// filters' circles for the lens, ‹ or › alone in 相册): pushed in 3 points
/// and back, with the ratchet's one notch.
private struct BikeLeverStyle: ButtonStyle {
    var glyph: ShellGlyph
    var quiet = false
    func makeBody(configuration: Configuration) -> some View { BikeLeverBody(style: self, pressed: configuration.isPressed) }
}
private struct BikeLeverBody: View {
    var style: BikeLeverStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let s = style
        let shape = RoundedRectangle(cornerRadius: 10, style: .continuous)
        let metal = LinearGradient(stops: [Gradient.Stop(color: BikeArt.rgb(246, 247, 248), location: 0), Gradient.Stop(color: BikeArt.rgb(201, 205, 211), location: 0.45),
                                           Gradient.Stop(color: BikeArt.rgb(143, 149, 157), location: 1)], startPoint: .top, endPoint: .bottom)
        ShellGlyphView(glyph: s.glyph, size: 18, ink: BikeArt.rgb(38, 42, 48))
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background {
            shape.fill(metal)
                .overlay(RoundedRectangle(cornerRadius: 9.3, style: .continuous).strokeBorder(Color.white.opacity(0.9), lineWidth: 1).padding(0.7))
        }
        .offset(y: pressed ? 3 : 0)
        .background(RoundedRectangle(cornerRadius: 11, style: .continuous).fill(BikePaint.shade.opacity(0.32))
            .padding(.horizontal, -1).padding(.top, -0.5).padding(.bottom, -3.5))
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.12), value: pressed)
        .onChange(of: pressed) { _, now in
            guard now else { return }
            if !s.quiet { ConsoleSounds.shared.play(.keyRatchet, scale: 0.8) }
            ConsoleHaptics.shared.play(.sliderNotch, .press)
        }
    }
}

/// What the bell's cap shows: a camera; for a video a red dot, the square
/// while one is taken.
private enum BikeBellSign: Equatable { case camera, record, stop }

/// The bell's red thumb lever, pointing out from its middle (turned to where it points).
private struct BikeBellLever: View, Equatable {
    var radius: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius, red = BikePaint.red
            let lever = BikeArt.rr(CGRect(x: c.x + r * 0.5, y: c.y - 5.5, width: r * 1.02, height: 11), 5.5)
            context.fill(lever, with: BikeArt.vertical([BikeArt.stop(red.color(0.4), 0), BikeArt.stop(red.color(-0.25), 1)], c.y - 5.5, c.y + 5.5))
            for k in 0..<3 {
                context.fill(Path(CGRect(x: c.x + r * 1.08 + CGFloat(k) * 3.4, y: c.y - 3.5, width: 1.2, height: 7)), with: .color(BikeArt.rgb(120, 20, 10, 0.35)))
            }
        }
    }
}

/// The light on the bell's spun dome, its two pressed rings, its rim.
private struct BikeBellShine: View, Equatable {
    var radius: CGFloat
    var body: some View {
        Canvas { context, size in
            let c = CGPoint(x: size.width / 2, y: size.height / 2), r = radius
            let light = Gradient(stops: [BikeArt.stop(Color.white.opacity(0.85), 0), BikeArt.stop(Color.white.opacity(0.12), 0.4), BikeArt.stop(BikeArt.rgb(30, 36, 44, 0.3), 1)])
            context.fill(BikeArt.disc(c, r), with: .radialGradient(light, center: CGPoint(x: c.x - r * 0.32, y: c.y - r * 0.38), startRadius: r * 0.05, endRadius: r * 1.15))
            for k in [CGFloat(0.76), CGFloat(0.54)] {
                context.stroke(BikeArt.disc(CGPoint(x: c.x, y: c.y + 0.8), r * k), with: .color(Color.white.opacity(0.7)), lineWidth: 1)
                context.stroke(BikeArt.disc(c, r * k), with: .color(BikeArt.rgb(40, 46, 54, 0.26)), lineWidth: 1)
            }
            context.stroke(BikeArt.disc(c, r - 0.7), with: .color(Color.white.opacity(0.85)), lineWidth: 1)
            context.stroke(BikeArt.disc(c, r), with: .color(Color.black.opacity(0.35)), lineWidth: 0.8)
        }
    }
}

/// What the bell's cap shows.
private struct BikeBellMark: View {
    var sign: BikeBellSign
    var radius: CGFloat
    var body: some View {
        switch sign {
        case .camera:
            Image(systemName: "camera.fill").font(.system(size: radius * 0.42, weight: .bold)).foregroundStyle(BikeArt.rgb(36, 40, 46, 0.85))
        case .record:
            Circle().fill(CameraShutterFace.red).frame(width: radius * 0.42, height: radius * 0.42)
        case .stop:
            RoundedRectangle(cornerRadius: 2.5, style: .continuous).fill(CameraShutterFace.red).frame(width: radius * 0.38, height: radius * 0.38)
        }
    }
}

/// The bell's dome: spun chrome, the light on it, the cap in its middle and
/// what it shows (faint while the camera is not ready).
private struct BikeBellDome: View {
    var radius: CGFloat
    var sign: BikeBellSign
    var ready: Bool
    var body: some View {
        let r = radius
        ZStack {
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(-2.0)))
                .frame(width: 2 * r, height: 2 * r)
            BikeBellShine(radius: r).equatable()
                .frame(width: 2 * r + 4, height: 2 * r + 4)
            Circle().fill(AngularGradient(gradient: ClamPaint.turned, center: .center, angle: .radians(0.8)))
                .overlay(Circle().strokeBorder(Color.black.opacity(0.3), lineWidth: 0.7))
                .frame(width: r * 0.68, height: r * 0.68)
            BikeBellMark(sign: sign, radius: r)
                .opacity(ready ? 1 : 0.45)
        }
    }
}

/// The bell as the shutter (in 相册, 回去拍照): pressed, its red lever flicks
/// towards the dome and back and the dome goes down 1.5 points with the
/// bell's ring (as a video starts and as it stops too), felt as the shutter;
/// let go, it trembles twice (not with Reduce Motion).
private struct BikeBellStyle: ButtonStyle {
    var bell: CGPoint
    var radius: CGFloat
    var lever: Double
    var sign: BikeBellSign
    var ready = true
    var haptic: HapticPart = .faceButton
    func makeBody(configuration: Configuration) -> some View { BikeBellBody(style: self, pressed: configuration.isPressed) }
}
private struct BikeBellBody: View {
    var style: BikeBellStyle
    var pressed: Bool
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var shake: CGFloat = 0
    var body: some View {
        let s = style, r = s.radius
        let side = 2 * (r * 1.52 + 4)
        let flick: Double = pressed ? -0.4 : 0
        ZStack(alignment: .topLeading) {
            BikeBellLever(radius: r).equatable()
                .frame(width: side, height: side)
                .rotationEffect(.radians(s.lever + flick))
                .shadow(color: BikePaint.shade.opacity(0.3), radius: 0.5, x: 0, y: 2)
                .position(x: s.bell.x, y: s.bell.y)
            Circle().fill(BikePaint.shade.opacity(0.32))
                .frame(width: 2 * (r + 1), height: 2 * (r + 1))
                .position(x: s.bell.x + 1, y: s.bell.y + 4)
            BikeBellDome(radius: r, sign: s.sign, ready: s.ready)
                .offset(x: shake, y: pressed ? 1.5 : 0)
                .position(x: s.bell.x, y: s.bell.y)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(room)
        .contentShape(Rectangle())
        .animation(.easeOut(duration: pressed ? 0.04 : 0.12), value: pressed)
        .onChange(of: pressed) { _, now in
            if now {
                ConsoleSounds.shared.play(.phoneRing, scale: 0.5)
                ConsoleHaptics.shared.play(s.haptic, .press)
            } else if !reduceMotion {
                var still = Transaction()
                still.disablesAnimations = true
                withTransaction(still) { shake = 1.6 }
                withAnimation(.spring(response: 0.18, dampingFraction: 0.25)) { shake = 0 }
            }
        }
    }
}

/// A print in the basket touched (相册): it lifts a little, with photo
/// paper's rustle.
private struct BikePrintStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View { BikePrintBody(configuration: configuration) }
}
private struct BikePrintBody: View {
    let configuration: ButtonStyle.Configuration
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = configuration.isPressed
        configuration.label
            .offset(y: down ? -2 : 0)
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: down ? 0.05 : 0.12), value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                ConsoleSounds.shared.play(.cardFlip, scale: 0.6)
                ConsoleHaptics.shared.play(.smallButton, .press)
            }
    }
}

extension CameraDeckFace {
    /// The bicycle under its parts.
    func bikeBackdrop(_ bike: BikeLayout) -> some View {
        BikeBackdrop(layout: bike, hinge: hinge, album: false).equatable()
    }

    /// The road's slim dark frame round the picture (round it in the shape
    /// chosen); nothing over the picture itself.
    func bikeScreen(_ bike: BikeLayout) -> some View {
        BikeRoadFrame(hole: layout.picture).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
    }

    /// The bicycle, upright or across (the same parts, each where its hold
    /// has it): the LCD's clock; on the basket's rim the plate (机型), the
    /// lamp (闪光) and the envelope (相册); the pencil box's six buttons; the
    /// mirror (内 / 外); the key (主菜单); the pinwheel (拍照 / 录像); the
    /// speedometer (变焦); the shifter (镜头); the bell (拍照). While a video
    /// is taken the parts make no sound of their own but the bell's.
    @ViewBuilder func bikeFace(_ bike: BikeLayout) -> some View {
        let quiet = model.recording
        BikeClock(size: bike.lcdSize)
            .deckPlaced(bike.lcd)
        bikePlate(bike, quiet: quiet)
        bikeLamp(bike, quiet: quiet)
        bikeEnvelope(bike, quiet: quiet)
        bikeButtons(bike, quiet: quiet)
        bikeMirror(bike, quiet: quiet)
        bikeHome(bike, quiet: quiet)
        bikePinwheel(bike, quiet: quiet)
        bikeSpeedo(bike, quiet: quiet)
        bikeShifter(bike, quiet: quiet)
        bikeBell(bike)
    }

    /// 机型: the tin plate opens (or closes) the bodies' cards; its tape
    /// shows two cameras traded (VoiceOver hears the body worn).
    private func bikePlate(_ bike: BikeLayout, quiet: Bool) -> some View {
        let key = bike.plateKey
        let style = BikePlateStyle(plate: BikeLayout.local(bike.plate, in: key), word: bike.plateWord, hang: bike.plateHang,
                                   tape: BikeLayout.local(bike.plateTape, in: key), tapeGlyph: .changeBody, quiet: quiet)
        return Button {
            if model.bodiesOpen { model.closeBodies() } else { model.openBodies() }
        } label: { Color.clear }
        .buttonStyle(style)
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
        .deckKey(key)
    }

    /// 闪光: the headlamp goes round 关, 自动, 开 (and against red eye); its
    /// tape shows which (the bolt slashed, with a small A, whole, with an eye).
    private func bikeLamp(_ bike: BikeLayout, quiet: Bool) -> some View {
        let key = bike.lampKey
        let flash = model.shooting.flash
        let word = String(localized: "闪光")
        let style = BikeLampStyle(lamp: BikeLayout.local(bike.lamp, in: key), radius: bike.lampRadius, state: BikeLamp.of(flash),
                                  tape: BikeLayout.local(bike.lampTape, in: key), glyph: .flash(flash), quiet: quiet)
        return Button { model.cycleFlash() } label: { Color.clear }
            .buttonStyle(style)
            .accessibilityLabel(word)
            .accessibilityValue(flash.title)
            .accessibilityIdentifier("camera-deck-flash")
            .deckKey(key)
    }

    /// 相册: the photo envelope, the newest two prints out of it, two pictures
    /// and how many on it.
    private func bikeEnvelope(_ bike: BikeLayout, quiet: Bool) -> some View {
        let key = bike.envelopeKey
        let photos = model.photos
        let newest: CGImage? = photos.first.flatMap { thumbnails.images[$0.url] }
        let older: CGImage? = photos.count > 1 ? thumbnails.images[photos[1].url] : nil
        let style = BikeEnvelopeStyle(envelope: BikeLayout.local(bike.envelope, in: key), up: bike.envelopeUp, newest: newest, older: older,
                                      count: photos.count, quiet: quiet)
        return Button { model.openAlbum() } label: { Color.clear }
            .buttonStyle(style)
            .onAppear { for photo in photos.prefix(2) { thumbnails.request(photo.url) } }
            .onChange(of: photos.first?.url) { _, _ in
                for shot in model.photos.prefix(2) { thumbnails.request(shot.url) }
            }
            .accessibilityLabel(CameraShellSkin.bike.albumTitle)
            .accessibilityValue(String(localized: "\(photos.count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .deckKey(key)
    }

    /// The pencil box's six buttons, each a glyph drawn as it stands: 定时,
    /// 日期, 画幅, 水平仪, 浓淡 − and 浓淡 ＋ (a row of cells under them for its
    /// step); 定时, 日期 and 水平仪 stay down while they are on.
    @ViewBuilder private func bikeButtons(_ bike: BikeLayout, quiet: Bool) -> some View {
        let rects = bike.buttons
        if rects.count == 6 {
            let shooting = model.shooting
            let onWord = String(localized: "开"), offWord = String(localized: "关")
            let timerWord = String(localized: "定时"), dateWord = String(localized: "日期"), levelWord = String(localized: "水平仪")
            let shapeWord = CameraShellSkin.bike.shapeTitle, toneWord = String(localized: "浓淡")
            let video = model.mode == .video
            let timerWhy = String(localized: "录像时不用定时")
            let timed = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
            let dated = shooting.dateStamp ? onWord : offWord
            let levelled = model.leveler ? onWord : offWord
            let shown = model.shownBody
            let step = model.strengthStep(of: shown)
            let share: String = shown == .native ? "—" : CameraBodyStrength.title(step)
            // 浓淡's step: a cell for each step, as many filled as the step it is at (原生 has none: a dash).
            let lit = step - CameraBodyStrength.range.lowerBound + 1
            let cells: ShellGlyph? = shown == .native ? nil : ShellGlyph.tone(step: lit, of: CameraBodyStrength.values.count)
            let dash = shown == .native ? "—" : ""
            Button { if video { model.say(timerWhy) } else { model.cycleTimer() } } label: { Color.clear }
                .buttonStyle(BikePressStyle(glyph: .timer(model.timer), latched: model.timer != .off, quiet: quiet))
                .accessibilityLabel(timerWord)
                .accessibilityValue(timed)
                .accessibilityAddTraits(model.timer != .off ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier("camera-deck-timer")
                .deckDimmed(video, why: timerWhy)
                .deckKey(rects[0])
            Button { model.toggleDateStamp() } label: { Color.clear }
                .buttonStyle(BikePressStyle(glyph: .date(shooting.dateStamp), latched: shooting.dateStamp, quiet: quiet))
                .accessibilityLabel(dateWord)
                .accessibilityValue(dated)
                .accessibilityAddTraits(shooting.dateStamp ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier("camera-deck-date")
                .deckKey(rects[1])
            Button { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } } label: { Color.clear }
                .buttonStyle(BikePressStyle(glyph: .shape(model.shape), quiet: quiet))
                .accessibilityLabel(shapeWord)
                .accessibilityValue(model.shape.title)
                .accessibilityIdentifier("camera-deck-aspect")
                .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
                .deckKey(rects[2])
            Button { model.toggleLeveler() } label: { Color.clear }
                .buttonStyle(BikePressStyle(glyph: .level(model.leveler), latched: model.leveler, quiet: quiet))
                .accessibilityLabel(levelWord)
                .accessibilityValue(levelled)
                .accessibilityAddTraits(model.leveler ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier("camera-deck-leveler")
                .deckKey(rects[3])
            Button { model.stepBodyStrength(-1) } label: { Color.clear }
                .buttonStyle(BikePressStyle(glyph: .toneDown, cells: cells, figures: dash, quiet: quiet))
                .accessibilityLabel(toneWord + " −")
                .accessibilityValue(share)
                .accessibilityIdentifier("camera-deck-strength-minus")
                .deckKey(rects[4])
            Button { model.stepBodyStrength(1) } label: { Color.clear }
                .buttonStyle(BikePressStyle(glyph: .toneUp, cells: cells, figures: dash, quiet: quiet))
                .accessibilityLabel(toneWord + " +")
                .accessibilityValue(share)
                .accessibilityIdentifier("camera-deck-strength-plus")
                .deckKey(rects[5])
        }
    }

    /// 内 / 外: the mirror on its stalk (合体 changes the camera itself); a
    /// camera turning under it (on a tape held across), the glass showing
    /// which side.
    @ViewBuilder private func bikeMirror(_ bike: BikeLayout, quiet: Bool) -> some View {
        let key = bike.mirrorKey
        let side = model.side.short
        let tape: CGRect = bike.mirrorTape ? BikeLayout.local(bike.mirrorWords, in: key) : .zero
        let tapeGlyph: ShellGlyph? = bike.mirrorTape ? .flip : nil
        BikeMirrorKey(mirror: BikeLayout.local(bike.mirror, in: key), radius: bike.mirrorRadius, inner: model.side == .inner,
                      tape: tape, tapeGlyph: tapeGlyph, quiet: quiet) { model.switchSide() }
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(side)
            .accessibilityIdentifier("camera-deck-switch")
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(key)
        if !bike.mirrorTape {
            ShellGlyphView(glyph: .flip, size: 18, ink: BikePaint.ink)
                .allowsHitTesting(false)
                .deckPlaced(bike.mirrorWords)
        }
    }

    /// 主菜单: the house key on its ring (a house on its tag).
    private func bikeHome(_ bike: BikeLayout, quiet: Bool) -> some View {
        let key = bike.homeKey
        let ring = BikeLayout.local(bike.ring, in: key)
        let ax: CGFloat = key.width > 0 ? ring.x / key.width : 0.5
        let ay: CGFloat = key.height > 0 ? ring.y / key.height : 0
        let anchor = UnitPoint(x: ax, y: ay)
        let sound: ConsoleSound? = quiet ? nil : .tinRattle
        let word = String(localized: "camera.home.pill")
        return Button { model.leave() } label: {
            BikeHomeFace(ring: CGPoint(x: ring.x + 12, y: ring.y + 12)).equatable()
                .frame(width: key.width + 24, height: key.height + 24)
                .frame(width: key.width, height: key.height)
        }
        .buttonStyle(BikeKeyStyle(travel: 0, swing: 9, anchor: anchor, sound: sound, scale: 0.5, twice: true))
        .accessibilityLabel(word)
        .accessibilityIdentifier("camera-deck-home")
        .deckKey(key)
    }

    /// 拍照 / 录像: the pinwheel (it turns in 录像, whirls while a video is
    /// taken); its tape shows which (a camera and a video camera, the one it
    /// is set to filled; a video camera and the time while one runs).
    private func bikePinwheel(_ bike: BikeLayout, quiet: Bool) -> some View {
        let key = bike.pinwheelKey
        let video = model.mode == .video
        let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
        let running: BikeWheelTape = .glyph(.video(true), figures: CameraAppModel.clock(model.recordedSeconds))
        let waiting: BikeWheelTape = .modes(video: video)
        let style = BikePinwheelStyle(pinwheel: BikeLayout.local(bike.pinwheel, in: key), radius: bike.pinwheelRadius, whirl: model.recording, breeze: video,
                                      tape: BikeLayout.local(bike.pinwheelTape, in: key), mark: model.recording ? running : waiting,
                                      alarm: model.recording, quiet: quiet)
        return Button { model.setMode(video ? .photo : .video) } label: { Color.clear }
            .buttonStyle(style)
            .accessibilityLabel(photoWord + " / " + videoWord)
            .accessibilityValue(video ? videoWord : photoWord)
            .accessibilityIdentifier("camera-deck-mode")
            .deckKey(key)
    }

    /// 变焦: the speedometer, its needle at the zoom; its − stud a stop out,
    /// its ＋ stud a stop in. They step back while the system's Camera
    /// Control menu is up (it has its own zoom).
    @ViewBuilder private func bikeSpeedo(_ bike: BikeLayout, quiet: Bool) -> some View {
        let hidden = systemControlsUp
        let factor = Self.zoomText(model.zoom)
        let window: String = model.recording ? "● " + CameraAppModel.clock(model.recordedSeconds) : factor
        BikeSpeedoDial(radius: bike.speedoRadius, reach: bike.studReach, zoom: model.zoom, wide: model.zoomStops.contains(0.5), window: window, alarm: model.recording)
            .deckPlaced(bike.dial)
            .opacity(hidden ? 0 : 1)
        bikeStud(bike, way: -1, quiet: quiet)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
        bikeStud(bike, way: 1, quiet: quiet)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
    }
    private func bikeStud(_ bike: BikeLayout, way: Int, quiet: Bool) -> some View {
        let key = way < 0 ? bike.zoomOut : bike.zoomIn
        let word = String(localized: "变焦")
        let sign = way < 0 ? "−" : "＋"
        return Button { bikeZoom(way, quiet: quiet) } label: { Color.clear }
            .buttonStyle(BikeStudStyle(stud: BikeLayout.local(bike.stud(way), in: key), radius: bike.studRadius, sign: sign))
            .accessibilityLabel(word + (way < 0 ? " −" : " +"))
            .accessibilityValue(Self.zoomText(model.zoom))
            .accessibilityIdentifier(way < 0 ? "camera-deck-zoom-out" : "camera-deck-zoom-in")
            .deckKey(key)
    }
    /// The zoom a stop out or in (from between two stops, a pinch's, out to
    /// the stop under it), the needle's soft tick as it comes to rest; at
    /// either end a firm stop.
    private func bikeZoom(_ way: Int, quiet: Bool) {
        let stops = model.zoomStops
        guard !stops.isEmpty else { return }
        let now = stops.lastIndex { $0 <= model.zoom + 0.05 } ?? 0
        let between = model.zoom > stops[now] + 0.05
        let next = way < 0 && between ? now : now + way
        guard stops.indices.contains(next) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            return
        }
        model.setZoom(stops[next], sound: false)
        guard !quiet else { return }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 260_000_000)
            ConsoleSounds.shared.play(.keyRatchet, scale: 0.55)
        }
    }

    /// 镜头: the shifter's window (the gear in use, the lens's glyph and its
    /// name) and its two levers (‹ and › by the filters' circles). They step
    /// back while the system's Camera Control menu is up.
    @ViewBuilder private func bikeShifter(_ bike: BikeLayout, quiet: Bool) -> some View {
        let hidden = systemControlsUp
        let lenses = CameraLens.allCases
        let at = lenses.firstIndex(of: model.lens) ?? 0
        let gears = lenses.count + model.pinnedBodies.count
        let lensWord = String(localized: "镜头")
        BikeShifterWindow(count: gears, at: at, name: model.lens.title, tag: .lens(model.lens), nameSize: bike.shifterName)
            .deckPlaced(bike.shifterWindow)
            .opacity(hidden ? 0 : 1)
        Button { bikeStepLens(-1) } label: { Color.clear }
            .buttonStyle(BikeLeverStyle(glyph: .lensPrevious, quiet: quiet))
            .accessibilityLabel(lensWord + " ‹")
            .accessibilityValue(model.lens.title)
            .accessibilityIdentifier("camera-deck-lens-previous")
            .deckKey(bike.leverBack)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
        Button { bikeStepLens(1) } label: { Color.clear }
            .buttonStyle(BikeLeverStyle(glyph: .lensNext, quiet: quiet))
            .accessibilityLabel(lensWord + " ›")
            .accessibilityValue(model.lens.title)
            .accessibilityIdentifier("camera-deck-lens-next")
            .deckKey(bike.leverOn)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
    }
    /// One gear on or back: the lenses one by one (with a video, only those
    /// that take one); past the last of them the first 机型 pinned among them
    /// (as a pinned chip does it: the body changes, and with it the back).
    private func bikeStepLens(_ delta: Int) {
        let lenses = CameraLens.allCases
        guard let at = lenses.firstIndex(of: model.lens) else { return }
        var next = at + delta
        while lenses.indices.contains(next), model.mode == .video, !lenses[next].records { next += delta }
        if lenses.indices.contains(next) {
            model.choose(lenses[next])
        } else if delta > 0, let pinned = model.pinnedBodies.first(where: { $0 != model.body }) {
            model.tapPinned(pinned)
        } else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
        }
    }

    /// 拍照: the bell by the right grip (a camera; a red dot for a video, the
    /// square while one is taken); nothing printed by it but, while a video
    /// runs, the red square (停止).
    @ViewBuilder private func bikeBell(_ bike: BikeLayout) -> some View {
        let video = model.mode == .video
        let sign: BikeBellSign = video ? (model.recording ? .stop : .record) : .camera
        let style = BikeBellStyle(bell: BikeLayout.local(bike.bell, in: bike.bellKey), radius: bike.bellRadius, lever: bike.bellLever, sign: sign,
                                  ready: model.canShoot || model.recording)
        Button { model.shutter() } label: { Color.clear }
            .buttonStyle(style)
            .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
            .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
            .accessibilityIdentifier("camera-deck-shutter")
            .deckKey(bike.bellKey)
        if model.recording {
            ShellGlyphView(glyph: .stop, size: 14, ink: BikePaint.alarm)
                .allowsHitTesting(false)
                .deckPlaced(bike.bellWord)
        }
    }

    /// The bicycle's 照片袋, upright and across.
    @ViewBuilder func bikeAlbum(_ bike: BikeLayout) -> some View {
        BikeAlbumView(model: model, thumbnails: thumbnails, bike: bike, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

// MARK: - The bicycle handlebar's album: 照片袋

/// The bicycle's 照片袋: the picture looked at on the road (a video plays
/// where it is touched; a push to the side goes to the next), its place and
/// a video's length on small tags over it; the prints laid in the basket
/// round it (one touched is looked at); the shifter's levers to the one
/// before and after, its window saying which; the pinwheel plays a video (a
/// picture's waits, and says why); the envelope says 回去拍照 and the bell
/// goes back too; the key is 主菜单 as ever. The plate, the lamp, the mirror
/// and the speedometer wait, paler, and say why.
private struct BikeAlbumView: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var bike: BikeLayout
    var hinge: CGRect
    @State private var push: CGFloat = 0

    private var waiting: String { String(localized: "相册里用不了，回去拍照再用") }
    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private var video: Bool { model.albumPhoto?.isVideo == true }
    /// The video's length ("00:12"), once it is known.
    private var length: String? {
        guard let photo = model.albumPhoto, photo.isVideo, model.albumImageURL == photo.url, let seconds = model.albumDuration else { return nil }
        return CameraAppModel.clock(Int(seconds.rounded()))
    }
    private var videoWord: String { length.map { String(localized: "视频 \($0)") } ?? String(localized: "录像") }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    private func sharp(_ photo: CameraPhoto?) -> CGImage? {
        guard let photo else { return nil }
        return (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }
    /// The one before (−1) or after (+1); at either end a firm stop, and why.
    private func turn(_ delta: Int) {
        guard !drawing else { model.say(drawingWhy); return }
        let next = model.albumIndex + delta
        guard model.photos.indices.contains(next) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            if model.photos.isEmpty {
                model.say(String(localized: "还没有照片"))
            } else {
                model.say(delta < 0 ? String(localized: "已经是第一张") : String(localized: "已经是最后一张"))
            }
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            BikeBackdrop(layout: bike, hinge: hinge, album: true).equatable()
            road
            BikeRoadFrame(hole: bike.road).equatable()
            tags
            prints
            waitingKeys
            back
            home
            pinwheel
            shifter
            bell
        }
    }

    /// The road: the picture looked at, whole (a video plays where it is
    /// touched; a push to the side goes to the next one); while a picture is
    /// being drawn on inside, that it waits there; what the camera says, for
    /// a moment.
    private var road: some View {
        let r = bike.road
        let photos = model.photos, at = model.albumIndex
        return ZStack {
            BikePaint.frame
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
            } else if photos.indices.contains(at) {
                picture(photos[at])
            }
            if model.doodle != nil {
                Text("正在编辑 · 打开 Duo，在下屏接着画").font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(Color.white)
                    .multilineTextAlignment(.center).lineLimit(2).minimumScaleFactor(0.7)
                    .padding(.horizontal, 12).padding(.vertical, 6)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 16)
            }
            if let toast = model.toast {
                Text(toast).font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(Color.white)
                    .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                    .padding(.horizontal, 10).padding(.vertical, 4)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 14)
                    .frame(maxHeight: .infinity, alignment: .bottom)
                    .padding(.bottom, 12)
                    .allowsHitTesting(false)
                    .transition(.opacity)
            }
        }
        .frame(width: r.width, height: r.height)
        .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        .position(x: r.midX, y: r.midY)
    }
    private func picture(_ photo: CameraPhoto) -> some View {
        let r = bike.road
        let image = sharp(photo)
        return ZStack {
            if let shown = image { Image(decorative: shown, scale: 1).resizable().scaledToFit() }
            if photo.isVideo {
                #if os(iOS)
                if model.playing == photo.url {
                    CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                        .accessibilityIdentifier("camera-album-player")
                }
                #endif
                if model.playing != photo.url {
                    Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9))
                        .shadow(color: .black.opacity(0.5), radius: 4)
                }
            }
        }
        .frame(width: r.width, height: r.height)
        .offset(x: push)
        .contentShape(Rectangle())
        .gesture(DragGesture(minimumDistance: 8)
            .onChanged { push = $0.translation.width }
            .onEnded { value in
                let dx = value.translation.width
                withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                if abs(dx) > 60 { turn(dx < 0 ? 1 : -1) }
            })
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .contain)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : CameraShellSkin.bike.albumTitle)
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    /// Over the road's top: ▶ and a video's length (at the left), which one
    /// it is of how many (at the right).
    private var tags: some View {
        let r = bike.road
        let count = model.photos.count
        let place: String = count == 0 ? "0" : "\(model.albumIndex + 1) / \(count)"
        return ZStack(alignment: .top) {
            Color.clear
            HStack(spacing: 0) {
                if video, model.playing == nil {
                    BikeRoadTag(text: "▶ " + videoWord)
                        .accessibilityHidden(true)
                }
                Spacer(minLength: 0)
                BikeRoadTag(text: place)
                    .accessibilityElement()
                    .accessibilityLabel(place)
                    .accessibilityIdentifier("camera-deck-album-position")
            }
            .padding(10)
        }
        .frame(width: r.width, height: r.height)
        .position(x: r.midX, y: r.midY)
        .allowsHitTesting(false)
    }

    /// The prints laid in the basket round the one looked at (in the middle,
    /// larger, raised, in a red edge); one touched is looked at.
    @ViewBuilder private var prints: some View {
        let photos = model.photos, at = model.albumIndex
        let slots = bike.prints, middle = bike.printsMiddle
        let tilts: [Double] = bike.across ? [-0.04, 0, 0.05] : [-0.04, 0.03, 0, -0.03, 0.05]
        ForEach(slots.indices, id: \.self) { slot in
            let index = at - middle + slot
            if photos.indices.contains(index) {
                printKey(photos[index], index: index, chosen: index == at, place: slots[slot], tilt: tilts[slot % tilts.count])
            }
        }
    }
    private func printKey(_ photo: CameraPhoto, index: Int, chosen: Bool, place: CGRect, tilt: Double) -> some View {
        let w = place.width
        let number = String(localized: "第 \(index + 1) 张")
        let edge: Color? = chosen ? BikePaint.accent : nil
        return Button {
            if !chosen { model.chooseInAlbum(index, quiet: true) }
        } label: {
            BikePrintView(image: thumbnails.images[photo.url], width: w, edge: edge, play: photo.isVideo)
                .rotationEffect(.radians(chosen ? 0 : tilt))
                .position(x: w / 2, y: w * 0.4 + 2)
                .frame(width: place.width, height: place.height)
        }
        .buttonStyle(BikePrintStyle())
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityLabel(number)
        .accessibilityValue(photo.isVideo ? String(localized: "录像") : String(localized: "照片"))
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-album-cell-\(index)")
        .deckKey(place)
    }

    /// The plate, the lamp, the mirror and the speedometer: paler, quiet,
    /// and pressed they say why they wait.
    @ViewBuilder private var waitingKeys: some View {
        let plateKey = bike.plateKey, lampKey = bike.lampAlbumKey, mirrorKey = bike.mirrorKey
        let side = model.side.short
        let plateStyle = BikePlateStyle(plate: BikeLayout.local(bike.plate, in: plateKey), word: bike.plateWord, hang: bike.plateHang,
                                        tape: .zero, tapeGlyph: nil, quiet: true)
        let lampStyle = BikeLampStyle(lamp: BikeLayout.local(bike.lamp, in: lampKey), radius: bike.lampRadius, state: .dark, tape: .zero, glyph: nil, quiet: true)
        Button { model.say(waiting) } label: { Color.clear }
            .buttonStyle(plateStyle)
            .accessibilityLabel(String(localized: "切换机型"))
            .accessibilityValue(model.body.title)
            .deckDimmed(true, why: waiting)
            .deckKey(plateKey)
        Button { model.say(waiting) } label: { Color.clear }
            .buttonStyle(lampStyle)
            .accessibilityLabel(String(localized: "闪光"))
            .accessibilityValue(model.shooting.flash.title)
            .deckDimmed(true, why: waiting)
            .deckKey(lampKey)
        let mirrorPaper: CGRect = bike.mirrorTape ? BikeLayout.local(bike.mirrorWords, in: mirrorKey) : .zero
        let mirrorGlyph: ShellGlyph? = bike.mirrorTape ? .flip : nil
        BikeMirrorKey(mirror: BikeLayout.local(bike.mirror, in: mirrorKey), radius: bike.mirrorRadius, inner: model.side == .inner,
                      tape: mirrorPaper, tapeGlyph: mirrorGlyph, quiet: true) { model.say(waiting) }
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(side)
            .deckDimmed(true, why: waiting)
            .deckKey(mirrorKey)
        if !bike.mirrorTape {
            ShellGlyphView(glyph: .flip, size: 18, ink: BikePaint.dim)
                .allowsHitTesting(false)
                .deckPlaced(bike.mirrorWords)
        }
        BikeSpeedoDial(radius: bike.speedoRadius, reach: bike.studReach, zoom: model.zoom, wide: model.zoomStops.contains(0.5), window: "—", dim: true)
            .deckPlaced(bike.dial)
        ForEach([-1, 1], id: \.self) { way in
            let key = way < 0 ? bike.zoomOut : bike.zoomIn
            let sign = way < 0 ? "−" : "＋"
            Button { model.say(waiting) } label: { Color.clear }
                .buttonStyle(BikeStudStyle(stud: BikeLayout.local(bike.stud(way), in: key), radius: bike.studRadius, sign: sign))
                .accessibilityLabel(String(localized: "变焦") + (way < 0 ? " −" : " +"))
                .accessibilityValue(CameraDeckFace.zoomText(model.zoom))
                .deckDimmed(true, why: waiting)
                .deckKey(key)
        }
    }

    /// 回去拍照: the envelope (the prints put back in it; a camera and its words).
    private var back: some View {
        let key = bike.backKey
        return Button { backToCamera() } label: { Color.clear }
            .buttonStyle(BikeEnvelopeStyle(envelope: BikeLayout.local(bike.backEnvelope, in: key), up: bike.envelopeUp, back: true))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-return")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(key)
    }

    /// 主菜单: the house key, as ever.
    private var home: some View {
        let key = bike.homeKey
        let ring = BikeLayout.local(bike.ring, in: key)
        let ax: CGFloat = key.width > 0 ? ring.x / key.width : 0.5
        let ay: CGFloat = key.height > 0 ? ring.y / key.height : 0
        let anchor = UnitPoint(x: ax, y: ay)
        let word = String(localized: "camera.home.pill")
        return Button { model.leave() } label: {
            BikeHomeFace(ring: CGPoint(x: ring.x + 12, y: ring.y + 12)).equatable()
                .frame(width: key.width + 24, height: key.height + 24)
                .frame(width: key.width, height: key.height)
        }
        .buttonStyle(BikeKeyStyle(travel: 0, swing: 9, anchor: anchor, sound: .tinRattle, scale: 0.5, twice: true))
        .accessibilityLabel(word)
        .accessibilityIdentifier("camera-deck-home")
        .deckKey(key)
    }

    /// 播放: the pinwheel (it whirls while a video plays; its tape ▶, the
    /// square while it plays, and a video's length); a picture's waits.
    private var pinwheel: some View {
        let key = bike.pinwheelKey
        let playing = model.playing != nil
        let word = playing ? String(localized: "停止") : String(localized: "播放")
        let state = video ? videoWord : String(localized: "照片")
        let why = model.photos.isEmpty ? String(localized: "还没有照片") : String(localized: "照片不能播放；要在上面画，展开后用相册的「编辑」")
        let sign: ShellGlyph = playing ? .stop : .play
        let figures: String = video ? (length ?? "") : ""
        let style = BikePinwheelStyle(pinwheel: BikeLayout.local(bike.pinwheel, in: key), radius: bike.pinwheelRadius, whirl: playing, breeze: false,
                                      tape: BikeLayout.local(bike.pinwheelTape, in: key), mark: .glyph(sign, figures: figures))
        return Button { if video { model.togglePlay() } else { model.say(why) } } label: { Color.clear }
            .buttonStyle(style)
            .accessibilityLabel(word)
            .accessibilityValue(state)
            .accessibilityIdentifier("camera-deck-album-play")
            .deckDimmed(!video, why: why)
            .deckKey(key)
    }

    /// The shifter: its window says which picture of how many; its levers (‹
    /// and ›) go to the one before and the one after.
    @ViewBuilder private var shifter: some View {
        let photos = model.photos, at = model.albumIndex
        let none = photos.isEmpty
        let empty = String(localized: "还没有照片")
        let name = none ? empty : String(localized: "第 \(at + 1) 张")
        let earlier = String(localized: "上一张"), later = String(localized: "下一张")
        let hasBefore = !none && at > 0, hasAfter = at + 1 < photos.count
        let before: String = hasBefore ? String(localized: "第 \(at) 张") : ""
        let after: String = hasAfter ? String(localized: "第 \(at + 2) 张") : ""
        let firstWhy = none ? empty : String(localized: "已经是第一张")
        let lastWhy = none ? empty : String(localized: "已经是最后一张")
        BikeShifterWindow(count: photos.count, at: at, name: name, tail: none ? "" : "/\(photos.count)", nameSize: bike.shifterName)
            .deckPlaced(bike.shifterWindow)
        Button { turn(-1) } label: { Color.clear }
            .buttonStyle(BikeLeverStyle(glyph: .previous))
            .accessibilityLabel(earlier)
            .accessibilityValue(before)
            .accessibilityIdentifier("camera-deck-album-previous")
            .deckDimmed(!hasBefore, why: firstWhy)
            .deckKey(bike.leverBack)
        Button { turn(1) } label: { Color.clear }
            .buttonStyle(BikeLeverStyle(glyph: .next))
            .accessibilityLabel(later)
            .accessibilityValue(after)
            .accessibilityIdentifier("camera-deck-album-next")
            .deckDimmed(!hasAfter, why: lastWhy)
            .deckKey(bike.leverOn)
    }

    /// The bell: back to taking pictures (回去拍照 by it).
    @ViewBuilder private var bell: some View {
        let word = String(localized: "回去拍照")
        let style = BikeBellStyle(bell: BikeLayout.local(bike.bell, in: bike.bellKey), radius: bike.bellRadius, lever: bike.bellLever, sign: .camera, haptic: .smallButton)
        Button { backToCamera() } label: { Color.clear }
            .buttonStyle(style)
            .accessibilityLabel(word)
            .accessibilityIdentifier("camera-deck-album-close")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(bike.bellKey)
        BikeCaption(first: word)
            .deckPlaced(bike.bellWord)
    }
}

/// A small dark capsule over the road's top corner, white words in it.
private struct BikeRoadTag: View {
    var text: String
    var body: some View {
        Text(verbatim: text).font(.system(size: 12, weight: .heavy, design: .rounded)).monospacedDigit().foregroundStyle(Color.white)
            .lineLimit(1).fixedSize()
            .padding(.horizontal, 9)
            .frame(height: 22)
            .background(Capsule().fill(Color(red: 0.071, green: 0.118, blue: 0.102).opacity(0.62)))
    }
}

// MARK: - The cover keys' pictures

/// What a key on a body's back shows in place of words, for every back: a
/// glyph for each thing a key does, and where a key says how something is
/// set, a glyph whose shape changes with it — a slash, a small A, a tick,
/// filled or hollow, how many cells are filled, which end is filled — never
/// its colour alone. Figures stay figures (变焦's stops, how many pictures,
/// 曝光's ±0, the seconds, which picture), ISO and WB stay the letters a
/// camera prints, and 回去拍照 keeps its words beside its glyph
/// (ShellGlyphLabel). The glyphs are hidden from VoiceOver: a key says its
/// own name and how it stands (`accessibilityLabel`, `accessibilityValue`),
/// as it did while its words were printed on it. (glyphs-api.md has them all.)
enum ShellGlyph: Equatable {
    /// 闪光: a bolt; 关 slashed, 自动 a small A by it, 防红眼 a small eye by it.
    case flash(CameraFlashMode)
    /// 定时: a stopwatch; 3 or 10 small at its lower right.
    case timer(CameraTimer)
    /// 日期 (printed on the picture): a calendar; a tick on it while on.
    case date(Bool)
    /// 水平仪: hollow while off, filled while on.
    case level(Bool)
    /// 画幅 / 比例: a frame in the shape in use, its figures beside it (4:3).
    case shape(CameraAspect)
    /// The frame alone (its figures written elsewhere on the key).
    case shapeFrame(CameraAspect)
    /// 浓淡's step: a row of `of` cells, the first `step` of them filled.
    case tone(step: Int, of: Int)
    /// 浓淡 − and 浓淡 ＋: a circle half dark and half light, the sign beside
    /// it; 浓淡 on a key of its own: the circle alone.
    case toneDown
    case toneUp
    case toneMark
    /// 白平衡: the setting's own glyph (`CameraWhiteBalance.symbol`), WB over it.
    case whiteBalance(CameraWhiteBalance)
    /// ISO: the letters, the value under them (自动: a circled A).
    case iso(CameraISO)
    /// 曝光: ± in a circle, its value beside it (`CameraShooting.exposureTitle`;
    /// "": the glyph alone).
    case exposure(String)
    /// 变焦 (a knob's or a rocker's name): a magnifying glass; W less, T more.
    case zoom
    case zoomOut
    case zoomIn
    /// A lens: its own glyph (`CameraLens.symbol`).
    case lens(CameraLens)
    /// ‹ 镜头 and 镜头 ›: the filters' three circles, an arrow before or after them.
    case lensPrevious
    case lensNext
    /// A 机型 (one pinned among the lenses): a small drawing of its kind of
    /// camera in its own two colours (CameraShellIcon: the ink is not used).
    case body(CameraBody)
    /// 换机型: two cameras side by side, an arrow over them one way and one
    /// under them the other — a trade, not 内 / 外's turn (drawn: no system
    /// glyph says it).
    case changeBody
    /// 相册: two pictures, one before the other; 回放 (a card camera's): ▶ in a frame.
    case album
    case playback
    /// 主菜单: a house.
    case home
    /// 内 / 外: a camera, two arrows turning round its lens.
    case flip
    /// 拍照 / 录像's two ends: a camera, a video camera (filled: the end it is at).
    case photo(Bool)
    case video(Bool)
    /// A shutter's signs: a dot in a ring (ready for a video), a square (stop).
    case record
    case stop
    /// 回去拍照: a camera (its words go with it: ShellGlyphLabel).
    case returnToShooting
    /// In an album: ▶ (a video plays), ‹ and › (the one before, the one
    /// after), nine at a time.
    case play
    case previous
    case next
    case grid
}

/// A key's glyph, in the key's own ink (what its words were printed in).
/// `size` is how high it stands, as a system glyph's point size: a key
/// carries 16 to 22 (a drawn glyph fills a 24-point grid scaled to it). The
/// figures that go with 画幅 and 曝光 stand beside the glyph, or under it
/// with `stacked` (a round key, a narrow one). Hidden from VoiceOver: the
/// key says its own name and state.
struct ShellGlyphView: View {
    var glyph: ShellGlyph
    var size: CGFloat = 20
    var ink: Color
    var stacked = false

    /// The one weight of the system glyphs; a drawn glyph's lines match it.
    static let weight: Font.Weight = .semibold
    static func line(_ size: CGFloat) -> CGFloat { max(1, size * 0.08) }

    var body: some View {
        art.accessibilityHidden(true)
    }

    @ViewBuilder private var art: some View {
        switch glyph {
        case .flash(let mode):
            if mode == .redEye { redEye } else { symbol(mode.symbol) }
        case .timer(let timer):
            if timer == .off { symbol("stopwatch") } else { seconds(timer) }
        case .date(let on):
            symbol(on ? "calendar.badge.checkmark" : "calendar")
        case .level(let on):
            symbol(on ? "level.fill" : "level")
        case .shape(let aspect):
            ShellGlyphFigures(glyph: ShellGlyphFrame(aspect: aspect, size: size, ink: ink), figures: aspect.title, size: size, ink: ink, stacked: stacked)
        case .shapeFrame(let aspect):
            ShellGlyphFrame(aspect: aspect, size: size, ink: ink)
        case .tone(let step, let count):
            ShellGlyphCells(lit: step, count: count, size: size, ink: ink)
        case .toneDown:
            ShellGlyphToneSign(up: false, size: size, ink: ink)
        case .toneUp:
            ShellGlyphToneSign(up: true, size: size, ink: ink)
        case .toneMark:
            symbol("circle.lefthalf.filled")
        case .whiteBalance(let balance):
            ShellGlyphMarked(letters: "WB", symbol: balance.symbol, figures: "", size: size, ink: ink)
        case .iso(let iso):
            ShellGlyphMarked(letters: "ISO", symbol: iso == .auto ? "a.circle" : nil, figures: "\(iso.rawValue)", size: size, ink: ink)
        case .exposure(let title):
            ShellGlyphFigures(glyph: symbol("plusminus.circle"), figures: title, size: size, ink: ink, stacked: stacked)
        case .zoom:
            symbol("magnifyingglass")
        case .zoomOut:
            symbol("minus.magnifyingglass")
        case .zoomIn:
            symbol("plus.magnifyingglass")
        case .lens(let lens):
            symbol(lens.symbol)
        case .lensPrevious:
            ShellGlyphLensTurn(forward: false, size: size, ink: ink)
        case .lensNext:
            ShellGlyphLensTurn(forward: true, size: size, ink: ink)
        case .body(let pinned):
            CameraShellIcon(shell: pinned.shell, light: pinned.swatch.0, dark: pinned.swatch.1)
                .frame(width: size * 1.3, height: size * 0.85)
        case .changeBody:
            ShellGlyphSwap(size: size, ink: ink)
        case .album:
            symbol("photo.on.rectangle")
        case .playback:
            symbol("play.rectangle")
        case .home:
            symbol("house")
        case .flip:
            symbol("arrow.triangle.2.circlepath.camera")
        case .photo(let on):
            symbol(on ? "camera.fill" : "camera")
        case .video(let on):
            symbol(on ? "video.fill" : "video")
        case .record:
            symbol("record.circle")
        case .stop:
            symbol("stop.fill")
        case .returnToShooting:
            symbol("camera")
        case .play:
            symbol("play.fill")
        case .previous:
            symbol("chevron.left")
        case .next:
            symbol("chevron.right")
        case .grid:
            symbol("square.grid.3x3.fill")
        }
    }

    /// A system glyph at the glyph's size, in its ink.
    private func symbol(_ name: String) -> some View {
        Image(systemName: name).font(.system(size: size * 0.9, weight: Self.weight)).foregroundStyle(ink)
    }
    /// 防红眼: the bolt, a small eye at its lower right.
    private var redEye: some View {
        ShellGlyphCorner(symbol: "bolt.fill", size: size, ink: ink, mark: Image(systemName: "eye").font(.system(size: size * 0.38, weight: .bold)))
    }
    /// 3 秒, 10 秒: the stopwatch, the seconds at its lower right.
    private func seconds(_ timer: CameraTimer) -> some View {
        let points: CGFloat = timer.rawValue < 10 ? size * 0.5 : size * 0.44
        let figures = Text(verbatim: "\(timer.rawValue)").font(.system(size: points, weight: .heavy, design: .rounded))
        return ShellGlyphCorner(symbol: "stopwatch", size: size, ink: ink, mark: figures)
    }
}

/// A glyph with words beside it (or under it, `stacked`), for a key that
/// keeps its words — 回去拍照 above all (a glyph alone there was taken for
/// another key). Hidden from VoiceOver, as the glyph is: the key says its name.
struct ShellGlyphLabel: View {
    var glyph: ShellGlyph
    var words: String
    var size: CGFloat = 16
    var wordSize: CGFloat = 12
    var ink: Color
    /// The words' own ink (nil: the glyph's).
    var wordInk: Color? = nil
    var stacked = false
    var body: some View {
        Group {
            if stacked {
                VStack(spacing: size * 0.1) {
                    ShellGlyphView(glyph: glyph, size: size, ink: ink)
                    wordsView
                }
            } else {
                HStack(spacing: size * 0.3) {
                    ShellGlyphView(glyph: glyph, size: size, ink: ink)
                    wordsView
                }
            }
        }
        .accessibilityHidden(true)
    }
    private var wordsView: some View {
        Text(words).font(.system(size: wordSize, weight: .black, design: .rounded))
            .foregroundStyle(wordInk ?? ink)
            .lineLimit(1).minimumScaleFactor(0.6)
    }
}

/// A system glyph with a small mark at its lower right (the timer's
/// seconds, 防红眼's eye): the glyph a little smaller and up to the left, a
/// clear margin cut round the mark so that the two never run together.
private struct ShellGlyphCorner<Mark: View>: View {
    var symbol: String
    var size: CGFloat
    var ink: Color
    var mark: Mark
    var body: some View {
        let lift = CGSize(width: -size * 0.15, height: -size * 0.08)
        let corner = CGSize(width: size * 0.34, height: size * 0.27)
        ZStack {
            Image(systemName: symbol).font(.system(size: size * 0.74, weight: ShellGlyphView.weight))
                .offset(lift)
            // The margin: the mark's room, cleared out of the glyph under it.
            mark.foregroundStyle(Color.clear)
                .padding(size * 0.05)
                .background(RoundedRectangle(cornerRadius: size * 0.12, style: .continuous).fill(Color.black))
                .blendMode(.destinationOut)
                .offset(corner)
            mark.offset(corner)
        }
        .foregroundStyle(ink)
        .frame(width: size * 1.25, height: size * 1.05)
        .compositingGroup()
    }
}

/// Letters a camera prints (ISO, WB) over what they are set to: the
/// setting's glyph, or its figures.
private struct ShellGlyphMarked: View {
    var letters: String
    var symbol: String?
    var figures: String
    var size: CGFloat
    var ink: Color
    var body: some View {
        let lettersSize: CGFloat = letters.count > 2 ? size * 0.5 : size * 0.42
        VStack(spacing: size * 0.02) {
            Text(verbatim: letters).font(.system(size: lettersSize, weight: .heavy, design: .rounded))
            if let symbol {
                Image(systemName: symbol).font(.system(size: size * 0.6, weight: ShellGlyphView.weight))
            } else {
                Text(verbatim: figures).font(.system(size: size * 0.46, weight: .heavy, design: .rounded)).monospacedDigit()
            }
        }
        .foregroundStyle(ink)
        .lineLimit(1)
        .fixedSize()
    }
}

/// A glyph and its figures (画幅's 4:3, 曝光's ±0): beside it, or under it.
private struct ShellGlyphFigures<Glyph: View>: View {
    var glyph: Glyph
    var figures: String
    var size: CGFloat
    var ink: Color
    var stacked: Bool
    var body: some View {
        Group {
            if figures.isEmpty {
                glyph
            } else if stacked {
                VStack(spacing: size * 0.04) {
                    glyph
                    words(size * 0.44)
                }
            } else {
                HStack(spacing: size * 0.16) {
                    glyph
                    words(size * 0.56)
                }
            }
        }
        .foregroundStyle(ink)
        .lineLimit(1)
        .fixedSize()
    }
    private func words(_ points: CGFloat) -> some View {
        Text(verbatim: figures).font(.system(size: points, weight: .heavy, design: .rounded)).monospacedDigit()
    }
}

/// 画幅's frame, drawn in the shape in use (4:3, 1:1, 16:9, 3:4), two corner
/// marks inside it so that it never reads as an empty box.
private struct ShellGlyphFrame: View, Equatable {
    var aspect: CameraAspect
    var size: CGFloat
    var ink: Color
    /// Its width and height on the 24-point grid.
    static func box(_ aspect: CameraAspect) -> CGSize {
        switch aspect {
        case .full: return CGSize(width: 20.4, height: 15.3)
        case .square: return CGSize(width: 16, height: 16)
        case .wide: return CGSize(width: 21.6, height: 12.15)
        case .tall: return CGSize(width: 15.3, height: 20.4)
        }
    }
    var body: some View {
        let k = size / 24, line = ShellGlyphView.line(size)
        let box = Self.box(aspect)
        let w = box.width * k, h = box.height * k
        Canvas { context, area in
            let rect = CGRect(x: (area.width - w) / 2, y: (area.height - h) / 2, width: w, height: h)
            let shade = GraphicsContext.Shading.color(ink)
            context.stroke(Path(roundedRect: rect, cornerRadius: 2.6 * k), with: shade, lineWidth: line)
            let arm = min(w, h) * 0.27, inset = 3.5 * k
            var marks = Path()
            marks.move(to: CGPoint(x: rect.minX + inset, y: rect.minY + inset + arm))
            marks.addLine(to: CGPoint(x: rect.minX + inset, y: rect.minY + inset))
            marks.addLine(to: CGPoint(x: rect.minX + inset + arm, y: rect.minY + inset))
            marks.move(to: CGPoint(x: rect.maxX - inset, y: rect.maxY - inset - arm))
            marks.addLine(to: CGPoint(x: rect.maxX - inset, y: rect.maxY - inset))
            marks.addLine(to: CGPoint(x: rect.maxX - inset - arm, y: rect.maxY - inset))
            context.stroke(marks, with: shade, style: StrokeStyle(lineWidth: line * 0.9, lineCap: .round, lineJoin: .round))
        }
        .frame(width: w + line + 1, height: size)
    }
}

/// 浓淡's step as a row of cells: as many filled as the step it is at, the
/// rest hollow (their count tells it, not their colour).
private struct ShellGlyphCells: View, Equatable {
    var lit: Int
    var count: Int
    var size: CGFloat
    var ink: Color
    var body: some View {
        let n = max(1, count), cell = size * 0.22, gap = size * 0.11
        let width = CGFloat(n) * cell + CGFloat(n - 1) * gap
        Canvas { context, area in
            let y = (area.height - cell) / 2
            for i in 0..<n {
                let rect = CGRect(x: CGFloat(i) * (cell + gap), y: y, width: cell, height: cell)
                let shape = Path(roundedRect: rect.insetBy(dx: 0.45, dy: 0.45), cornerRadius: min(1.3, cell / 3))
                if i < lit {
                    context.fill(shape, with: .color(ink))
                } else {
                    context.stroke(shape, with: .color(ink.opacity(0.85)), lineWidth: 0.9)
                }
            }
        }
        .frame(width: width, height: cell + 2)
    }
}

/// 浓淡 − / ＋: a circle half dark and half light, the sign beside it.
private struct ShellGlyphToneSign: View {
    var up: Bool
    var size: CGFloat
    var ink: Color
    var body: some View {
        HStack(spacing: size * 0.06) {
            Image(systemName: "circle.lefthalf.filled").font(.system(size: size * 0.78, weight: ShellGlyphView.weight))
            Image(systemName: up ? "plus" : "minus").font(.system(size: size * 0.48, weight: .heavy))
        }
        .foregroundStyle(ink)
    }
}

/// ‹ 镜头 / 镜头 ›: the filters' three circles, an arrow before or after them.
private struct ShellGlyphLensTurn: View {
    var forward: Bool
    var size: CGFloat
    var ink: Color
    var body: some View {
        HStack(spacing: size * 0.04) {
            if !forward { chevron("chevron.left") }
            Image(systemName: "camera.filters").font(.system(size: size * 0.8, weight: ShellGlyphView.weight))
            if forward { chevron("chevron.right") }
        }
        .foregroundStyle(ink)
    }
    private func chevron(_ name: String) -> some View {
        Image(systemName: name).font(.system(size: size * 0.5, weight: .bold))
    }
}

/// 换机型, drawn (no system glyph says it): two cameras side by side, the
/// left one filled and the right one in outline, an arrow over them going
/// right and one under them going left — one camera traded for another, not
/// a turn (内 / 外's two arrows go round one camera).
private struct ShellGlyphSwap: View, Equatable {
    var size: CGFloat
    var ink: Color
    var body: some View {
        let k = size / 24, line = ShellGlyphView.line(size)
        Canvas { context, area in
            let c = CGPoint(x: area.width / 2, y: area.height / 2)
            let shade = GraphicsContext.Shading.color(ink)
            let stroke = StrokeStyle(lineWidth: line, lineCap: .round, lineJoin: .round)
            // The left camera, filled, its lens cut out and a dot left in it.
            let left = Self.camera(CGPoint(x: c.x - 6.3 * k, y: c.y + 0.1 * k), width: 11.4 * k)
            var solid = left.outline
            solid.addEllipse(in: Self.disc(left.lens, left.radius + 0.2 * k))
            solid.addEllipse(in: Self.disc(left.lens, left.radius * 0.5))
            context.fill(solid, with: shade, style: FillStyle(eoFill: true))
            // The right camera, in outline.
            let right = Self.camera(CGPoint(x: c.x + 6.3 * k, y: c.y + 0.1 * k), width: 11.4 * k)
            context.stroke(right.outline, with: shade, style: stroke)
            context.stroke(Path(ellipseIn: Self.disc(right.lens, right.radius)), with: shade, style: stroke)
            // Over them one way, under them the other.
            let over = Self.arrow(from: CGPoint(x: c.x - 4.8 * k, y: c.y - 8.5 * k), to: CGPoint(x: c.x + 4.8 * k, y: c.y - 8.5 * k), head: 2.9 * k)
            let under = Self.arrow(from: CGPoint(x: c.x + 4.8 * k, y: c.y + 8.5 * k), to: CGPoint(x: c.x - 4.8 * k, y: c.y + 8.5 * k), head: 2.9 * k)
            context.stroke(over, with: shade, style: stroke)
            context.stroke(under, with: shade, style: stroke)
        }
        // (A line wider than the grid: the right camera's outline reaches its edge.)
        .frame(width: size + line + 1, height: size)
    }

    static func disc(_ middle: CGPoint, _ radius: CGFloat) -> CGRect {
        CGRect(x: middle.x - radius, y: middle.y - radius, width: 2 * radius, height: 2 * radius)
    }

    /// A camera's outline (its body and the hump on its top as one line),
    /// `w` across, `middle` the middle of the whole; where its lens is, how large.
    static func camera(_ middle: CGPoint, width w: CGFloat) -> (outline: Path, lens: CGPoint, radius: CGFloat) {
        let tall = w * 0.6, hump = w * 0.15
        let top = middle.y - (tall + hump) / 2 + hump, bottom = top + tall
        let x0 = middle.x - w / 2, x1 = middle.x + w / 2, r = w * 0.15
        let cx = middle.x, a = w * 0.17, b = w * 0.12
        var path = Path()
        path.move(to: CGPoint(x: x0 + r, y: top))
        path.addLine(to: CGPoint(x: cx - a - b * 0.5, y: top))
        path.addLine(to: CGPoint(x: cx - a + b * 0.35, y: top - hump))
        path.addLine(to: CGPoint(x: cx + a - b * 0.35, y: top - hump))
        path.addLine(to: CGPoint(x: cx + a + b * 0.5, y: top))
        path.addLine(to: CGPoint(x: x1 - r, y: top))
        path.addQuadCurve(to: CGPoint(x: x1, y: top + r), control: CGPoint(x: x1, y: top))
        path.addLine(to: CGPoint(x: x1, y: bottom - r))
        path.addQuadCurve(to: CGPoint(x: x1 - r, y: bottom), control: CGPoint(x: x1, y: bottom))
        path.addLine(to: CGPoint(x: x0 + r, y: bottom))
        path.addQuadCurve(to: CGPoint(x: x0, y: bottom - r), control: CGPoint(x: x0, y: bottom))
        path.addLine(to: CGPoint(x: x0, y: top + r))
        path.addQuadCurve(to: CGPoint(x: x0 + r, y: top), control: CGPoint(x: x0, y: top))
        path.closeSubpath()
        return (path, CGPoint(x: cx, y: top + tall * 0.52), tall * 0.29)
    }

    /// A straight arrow with an open head (as arrow.right is drawn).
    static func arrow(from start: CGPoint, to end: CGPoint, head: CGFloat) -> Path {
        let angle = atan2(Double(end.y - start.y), Double(end.x - start.x))
        let c1 = CGFloat(cos(angle + 2.4)), s1 = CGFloat(sin(angle + 2.4))
        let c2 = CGFloat(cos(angle - 2.4)), s2 = CGFloat(sin(angle - 2.4))
        var path = Path()
        path.move(to: start)
        path.addLine(to: end)
        path.move(to: CGPoint(x: end.x + c1 * head, y: end.y + s1 * head))
        path.addLine(to: end)
        path.addLine(to: CGPoint(x: end.x + c2 * head, y: end.y + s2 * head))
        return path
    }
}

// MARK: - The birthday cake box's back

/// The birthday cake box's colours: the cream paperboard and the blush
/// stripes printed on it, the coral satin ribbon (its dark edges, its light
/// middle), the three frostings and the rose of the lace, the chocolate, the
/// gold of the number candles and the saucer, the gift box's rose, a wick's
/// brown, the coral of what is in use, the red of a video being taken, what
/// is printed on the box (and softer), the icing piped on the chocolate, the
/// cards' paper.
enum CakePaint {
    static let board = ShellTone(r: 0.992, g: 0.957, b: 0.914)
    static let stripe = ShellTone(r: 0.980, g: 0.882, b: 0.871)
    static let ribbon = ShellTone(r: 0.933, g: 0.478, b: 0.267)
    static let ribbonDark = ShellTone(r: 0.745, g: 0.290, b: 0.133)
    static let ribbonLight = ShellTone(r: 1.0, g: 0.745, b: 0.533)
    static let pink = ShellTone(r: 0.965, g: 0.659, b: 0.737)
    static let cream = ShellTone(r: 1.0, g: 0.941, b: 0.863)
    static let peach = ShellTone(r: 0.980, g: 0.745, b: 0.604)
    static let rose = ShellTone(r: 0.886, g: 0.376, b: 0.502)
    static let chocolate = ShellTone(r: 0.337, g: 0.184, b: 0.118)
    static let gold = ShellTone(r: 0.918, g: 0.690, b: 0.259)
    static let gift = ShellTone(r: 0.925, g: 0.471, b: 0.588)
    static let wick = Color(red: 0.227, green: 0.157, blue: 0.125)
    static let accent = Color(red: 0.910, green: 0.455, blue: 0.231)
    static let alarm = Color(red: 0.784, green: 0.196, blue: 0.122)
    static let ink = Color(red: 0.353, green: 0.157, blue: 0.090)
    static let soft = Color(red: 0.353, green: 0.157, blue: 0.090).opacity(0.76)
    static let icing = Color(red: 1.0, green: 0.973, blue: 0.933)
    static let paper = Color(red: 1.0, green: 0.980, blue: 0.949)
    /// The thin candles: a colour for each lens; the 机型 pinned among them go
    /// round `pinned`.
    static func lens(_ lens: CameraLens) -> ShellTone {
        switch lens {
        case .normal: return ShellTone(r: 0.925, g: 0.424, b: 0.580)
        case .sparkle: return ShellTone(r: 0.965, g: 0.769, b: 0.227)
        case .merge: return ShellTone(r: 0.361, g: 0.729, b: 0.612)
        case .dream: return ShellTone(r: 0.612, g: 0.525, b: 0.878)
        case .lowLight: return ShellTone(r: 0.275, g: 0.322, b: 0.573)
        case .pinhole: return ShellTone(r: 0.588, g: 0.486, b: 0.424)
        case .mystery: return ShellTone(r: 0.941, g: 0.541, b: 0.282)
        case .pair: return ShellTone(r: 0.416, g: 0.659, b: 0.894)
        case .quad: return ShellTone(r: 0.886, g: 0.329, b: 0.329)
        }
    }
    static let pinned: [ShellTone] = [ShellTone(r: 0.941, g: 0.541, b: 0.282), ShellTone(r: 0.416, g: 0.659, b: 0.894),
                                      ShellTone(r: 0.612, g: 0.525, b: 0.878), ShellTone(r: 0.361, g: 0.729, b: 0.612)]
}

/// Where the cake box's parts are on the cover, upright (from a ShellPlan)
/// or across (from a ShellAcrossPlan): the same parts both ways, each laid
/// out for its hold (canvas points).
struct CakeLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    var u: CGFloat = 1
    /// The lid's window: the picture's place (in 相册, the picture looked at).
    var window = CGRect.zero
    /// The satin ribbon round the box: its run across and its run down; the
    /// bow where it is tied (how large); the base's lace along the foot
    /// (where its top is; 0: none).
    var ribbonAcross = CGRect.zero
    var ribbonDown = CGRect.zero
    var bow = CGPoint.zero
    var bowScale: CGFloat = 1
    var rim: CGFloat = 0
    /// The box open in front, warm inside: its place, where the light on the
    /// cake is and how far it reaches.
    var opening = CGRect.zero
    var light = CGPoint.zero
    var lightReach: CGFloat = 300
    /// The turning stand's plate (its middle and its top, how wide) and the
    /// three tiers on it, the bottom one first.
    var plate = CGPoint.zero
    var plateWide: CGFloat = 188
    var tiers: [CGRect] = []
    /// 变焦: the number candles' places (.5, 1, 2, 4); where they stand in
    /// them and how tall their figures are; a flame's size.
    var numbers: [CGRect] = []
    var numberBase: CGFloat = 63
    var numberHeight: CGFloat = 31
    var numberFlame = CGSize(width: 9.5, height: 20)
    /// 定时, 日期, 画幅: the flags' places; how a flag sits on its pick (the
    /// pick's distance in, the flag's top and height), how large its glyph is
    /// (画幅's figures under its frame where the flag is narrow).
    var flags: [CGRect] = []
    var flagPick: CGFloat = 9
    var flagTop: CGFloat = 5
    var flagHeight: CGFloat = 36
    var flagGlyph: CGFloat = 18
    var flagStacked = false
    /// 闪光: the sparkler's place, its wire's distance in, where its coating
    /// ends (a share of its height), its burst's radius, its label's glyph.
    var sparkler = CGRect.zero
    var sparklerPick: CGFloat = 13
    var sparklerCoat: CGFloat = 0.44
    var sparks: CGFloat = 16
    var sparklerGlyph: CGFloat = 15
    /// 镜头: the ring of thin candles (with room over them for a flame); where
    /// they stand in it, how tall, where a name goes, the room before the
    /// first; a flame's size.
    var lenses = CGRect.zero
    var lensBase: CGFloat = 89
    var lensTall: CGFloat = 40
    var lensName: CGFloat = 100
    var lensPad: CGFloat = 11
    var lensFlame = CGSize(width: 9, height: 19)
    /// 浓淡 − / ＋: the macarons and their size; where the step is shown under them.
    var macarons: [CGRect] = []
    var macaronSize = CGSize(width: 38, height: 27)
    var macaronCaption = CGPoint.zero
    /// 拍照 | 录像: the chocolate plaque and its two halves (the glyph over its
    /// dot where they are narrow).
    var plaque = CGRect.zero
    var halves: [CGRect] = []
    var plaqueStacked = false
    /// The floor: the jelly (水平仪), the stand's drum (内 / 外), the card
    /// (吹气拍照), the gift box (相册).
    var jelly = CGRect.zero
    var drum = CGRect.zero
    var blow = CGRect.zero
    var gift = CGRect.zero
    /// 机型: the tag's place; the tag in it (its top middle and its size), how
    /// it hangs turned, the knot it hangs from, the glyph printed by it
    /// (.zero: none), how large its ZERO is.
    var tagKey = CGRect.zero
    var tag = CGRect.zero
    var tagTurn: Double = 0.05
    var knot = CGPoint.zero
    var tagMark = CGRect.zero
    var tagWord: CGFloat = 12
    /// 主菜单: the seal on the ribbon, its radius.
    var sealKey = CGRect.zero
    var sealRadius: CGFloat = 25
    /// 拍照: the big candle's place; its saucer's foot, its width and height,
    /// its flame, how high its smoke rises; the words on the base under it
    /// (.zero: none).
    var candleKey = CGRect.zero
    var candleFoot: CGFloat = 0
    var candleWide: CGFloat = 44
    var candleTall: CGFloat = 48
    var candleFlame = CGSize(width: 14, height: 30)
    var candleSmoke: CGFloat = 64
    var hint = CGRect.zero
    /// 相册: the label on the ribbon (which one of how many); the string the
    /// cards hang from (its ends, how far it sags); the cards' places (the
    /// one looked at in `cardsMiddle`); the three cookies; 回去拍照's plaque;
    /// the gift box opened.
    var label = CGRect.zero
    var string0 = CGPoint.zero
    var string1 = CGPoint.zero
    var sag: CGFloat = 14
    var cards: [CGRect] = []
    var cardsMiddle = 2
    var cookies: [CGRect] = []
    var backPlaque = CGRect.zero
    var openGift = CGRect.zero

    /// The zoom stops the number candles stand for.
    static let stops: [Double] = [0.5, 1, 2, 4]
    /// How far down the string hangs at `x`.
    func hang(_ x: CGFloat) -> CGFloat {
        let span = max(1, string1.x - string0.x)
        let t = min(1, max(0, (x - string0.x) / span))
        return string0.y + sag * CGFloat(sin(Double.pi * Double(t)))
    }
    /// A part's place, from the corner of the key it is drawn in.
    static func local(_ r: CGRect, in key: CGRect) -> CGRect { r.offsetBy(dx: -key.minX, dy: -key.minY) }
    static func local(_ p: CGPoint, in key: CGRect) -> CGPoint { CGPoint(x: p.x - key.minX, y: p.y - key.minY) }
}

extension ShellPlan {
    /// The cake box's parts, upright (across from the column's corner, scaled
    /// with it; down from the keys' top and from the column's foot): the
    /// lid's window at the column's head, the ribbon across under it; the box
    /// open in front under the ribbon, the cake on its turning stand on the
    /// box's floor (what height there is over the cake is the box's inside);
    /// between the column and the strip the ribbon's run down; down the strip
    /// the bow under the camera, the tag hanging from it (机型), the seal on
    /// the ribbon (主菜单), and the big candle under the Camera Control's
    /// overlay (拍照). The measures are the picture's of it on the Duo's cover.
    var cake: CakeLayout {
        var l = CakeLayout()
        let c = back.column, strip = back.strip, k = keysTop, b = c.maxY
        let floor = back.keepOut.map(\.maxY).max() ?? top
        let w = back.canvas.width
        func r(_ at: CGFloat, _ y: CGFloat, _ wide: CGFloat, _ high: CGFloat) -> CGRect {
            CGRect(x: x(at), y: y, width: wide * u, height: high)
        }
        l.canvas = back.canvas
        l.u = u
        l.window = box
        // The ribbon across under the window and down between the column and
        // the strip, the bow under the camera; the base along the foot.
        let ribbonX = c.maxX - 2
        l.ribbonAcross = CGRect(x: 0, y: k, width: w, height: 16)
        l.ribbonDown = CGRect(x: ribbonX, y: 0, width: 14, height: b + 2)
        l.bow = CGPoint(x: ribbonX + 7, y: floor + 17)
        l.bowScale = 1
        l.rim = b
        // The box open in front, the light on the cake.
        let left = x(12)
        l.opening = CGRect(x: left, y: k + 22, width: max(0, ribbonX - left), height: max(0, b - 2 - k - 22))
        l.light = CGPoint(x: l.opening.midX, y: b - 174)
        l.lightReach = 300 * max(0.8, u)
        // The stand and the cake on it, from the floor up.
        l.plate = CGPoint(x: x(199), y: b - 63)
        l.plateWide = 188 * u
        l.tiers = [r(16, b - 132, 366, 72), r(51, b - 204, 294, 72), r(81, b - 276, 234, 72)]
        var numbers: [CGRect] = []
        for index in 0..<4 { numbers.append(r(85 + 58 * CGFloat(index), b - 338, 52, 66)) }
        l.numbers = numbers
