        l.numberHeight = 31
        l.numberFlame = CGSize(width: 9.5, height: 20)
        var flags: [CGRect] = []
        for index in 0..<3 { flags.append(r(61 + 70 * CGFloat(index), b - 266, 64, 66)) }
        l.flags = flags
        l.flagPick = 9
        l.flagTop = 5
        l.flagHeight = 36
        l.flagGlyph = 18
        l.flagStacked = false
        l.sparkler = r(271, b - 266, 64, 66)
        l.sparklerPick = 13
