        l.macarons = [r(77, b - 108, 46, 44), r(129, b - 108, 46, 44)]
        l.macaronSize = CGSize(width: 38, height: 27)
        l.macaronCaption = CGPoint(x: x(126), y: b - 70.5)
        l.plaque = r(181, b - 108, 138, 44)
        l.halves = [r(181, b - 108, 66, 44), r(253, b - 108, 66, 44)]
        l.plaqueStacked = false
