        l.candleKey = CGRect(x: min(strip.midX - 27, w - 64), y: candleTop, width: 62, height: max(56, b - candleTop))
        l.candleFoot = l.candleKey.maxY - 3
        l.candleWide = 44
        l.candleTall = max(24, min(48, l.candleKey.height - 50))
        l.candleFlame = CGSize(width: 14, height: 30)
