        if back.canvas.height - b >= 20 {
            l.hint = CGRect(x: c.minX, y: b + 9, width: max(0, strip.maxX - 6 - c.minX), height: 16)
        }
        // 相册: the label on the ribbon, the cards on their string under it and
        // the cookies under them; the gift box opened and 回去拍照's plaque on
        // the floor.
        l.label = CGRect(x: x(192) - 52, y: k - 2, width: 104, height: 20)
        l.string0 = CGPoint(x: left, y: k + 34)
        l.string1 = CGPoint(x: ribbonX, y: k + 34)
