/// The same scatter every time it is drawn (sprinkles, glitter, sparks): a
/// small generator from a seed (above 0).
private struct CakeDice {
    var seed: Int
    mutating func next() -> CGFloat {
        seed = (seed * 16807) % 2147483647
        return CGFloat(seed) / 2147483647
    }
}

/// The cake box's drawing, part for part: the paperboard, the lid's lace, the
/// box's warm inside, the stand's plate, the tiers, the ribbon and its bow,
/// the base's lace, the edge.
private enum CakeArt {
    static func rgb(_ r: Double, _ g: Double, _ b: Double, _ a: Double = 1) -> Color {
        Color(red: r / 255, green: g / 255, blue: b / 255).opacity(a)
    }
    static func stop(_ colour: Color, _ at: CGFloat) -> Gradient.Stop { Gradient.Stop(color: colour, location: at) }
    static func rr(_ r: CGRect, _ radius: CGFloat) -> Path {
        Path(roundedRect: r, cornerRadius: max(0, min(radius, r.width / 2, r.height / 2)))
    }
    static func disc(_ c: CGPoint, _ r: CGFloat) -> Path {
        Path(ellipseIn: CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r))
    }
    static func oval(_ c: CGPoint, _ rx: CGFloat, _ ry: CGFloat) -> Path {
        Path(ellipseIn: CGRect(x: c.x - rx, y: c.y - ry, width: 2 * rx, height: 2 * ry))
    }
    static func vertical(_ stops: [Gradient.Stop], _ y0: CGFloat, _ y1: CGFloat) -> GraphicsContext.Shading {
        .linearGradient(Gradient(stops: stops), startPoint: CGPoint(x: 0, y: y0), endPoint: CGPoint(x: 0, y: y1))
    }
    static func across(_ stops: [Gradient.Stop], _ x0: CGFloat, _ x1: CGFloat) -> GraphicsContext.Shading {
        .linearGradient(Gradient(stops: stops), startPoint: CGPoint(x: x0, y: 0), endPoint: CGPoint(x: x1, y: 0))
    }
    static func glow(_ c: CGPoint, _ r: CGFloat, _ stops: [Gradient.Stop]) -> GraphicsContext.Shading {
        .radialGradient(Gradient(stops: stops), center: c, startRadius: 0, endRadius: max(1, r))
    }
    /// Points along an ellipse's arc from `from` to `to` (radians, y down).
    static func arc(_ c: CGPoint, _ rx: CGFloat, _ ry: CGFloat, from: Double, to: Double, steps: Int = 24) -> [CGPoint] {
        var points: [CGPoint] = []
        let n = max(1, steps)
        for index in 0...n {
            let a = from + (to - from) * Double(index) / Double(n)
            points.append(CGPoint(x: c.x + CGFloat(cos(a)) * rx, y: c.y + CGFloat(sin(a)) * ry))
        }
        return points
    }
    static func polyline(_ points: [CGPoint]) -> Path {
        var path = Path()
        guard let first = points.first else { return path }
        path.move(to: first)
        for point in points.dropFirst() { path.addLine(to: point) }
        return path
    }
    /// The satin's light across a ribbon, from one edge to the other.
    static var satin: [Gradient.Stop] {
        [stop(CakePaint.ribbonDark.color(), 0), stop(CakePaint.ribbon.color(), 0.15), stop(CakePaint.ribbonLight.color(), 0.42),
         stop(CakePaint.ribbon.color(0.12), 0.6), stop(CakePaint.ribbon.color(), 0.86), stop(CakePaint.ribbonDark.color(), 1)]
    }

    /// The cream paperboard printed with soft blush stripes, its grain, the
    /// light from the upper left, the hinge's side in shade.
    static func paperboard(_ context: GraphicsContext, _ size: CGSize, _ hinge: CGRect) {
        let whole = CGRect(origin: .zero, size: size)
        context.fill(Path(whole), with: .color(CakePaint.board.color()))
        var stripes = Path()
        var x: CGFloat = 9
        while x < size.width {
            stripes.addRect(CGRect(x: x, y: 0, width: 15, height: size.height))
            x += 30
        }
        context.fill(stripes, with: .color(CakePaint.stripe.color()))
        var dice = CakeDice(seed: 7)
        let grains = Int(size.width * size.height / 100)
        for _ in 0..<grains {
            let gx = dice.next() * size.width, gy = dice.next() * size.height
            let a = Double(dice.next()) * 0.05
            let ink: Color = dice.next() < 0.5 ? Color.white : rgb(122, 56, 24)
            context.fill(Path(CGRect(x: gx, y: gy, width: 1, height: 1)), with: .color(ink.opacity(a)))
        }
        let far = max(size.width, size.height)
        let light = Gradient(stops: [stop(Color.white.opacity(0.26), 0), stop(Color.white.opacity(0), 0.55), stop(rgb(122, 56, 24, 0.13), 1)])
        context.fill(Path(whole), with: .radialGradient(light, center: CGPoint(x: size.width * 0.3, y: size.height * 0.14), startRadius: 10, endRadius: far * 0.95))
        if hinge.width > 0, hinge.height > 0 {
            let tall = hinge.height > hinge.width
            let near: Bool = tall ? hinge.midX < size.width / 2 : hinge.midY < size.height / 2
            let edge: CGFloat = near ? 0 : (tall ? size.width : size.height)
            let inward: CGFloat = near ? 14 : -14
            let from: CGPoint = tall ? CGPoint(x: edge, y: 0) : CGPoint(x: 0, y: edge)
            let to: CGPoint = tall ? CGPoint(x: edge + inward, y: 0) : CGPoint(x: 0, y: edge + inward)
            let low: CGFloat = min(edge, edge + inward)
            let strip: CGRect = tall ? CGRect(x: low, y: 0, width: 14, height: size.height) : CGRect(x: 0, y: low, width: size.width, height: 14)
            let fade = Gradient(colors: [rgb(100, 44, 18, 0.24), rgb(100, 44, 18, 0)])
            context.fill(Path(strip), with: .linearGradient(fade, startPoint: from, endPoint: to))
        }
    }

    /// The lid's window round the picture: a plain margin of the board with a
    /// paper-lace edge (round bumps along it, as a doily's). Under the
    /// picture, which goes in untouched.
    static func lace(_ context: GraphicsContext, around hole: CGRect) {
        guard hole.width > 0, hole.height > 0 else { return }
        let edge = Path(roundedRect: hole.insetBy(dx: -10, dy: -10), cornerRadius: 19, style: .continuous)
        let board = CakePaint.board.color()
        context.fill(edge, with: .color(board))
        context.stroke(edge, with: .color(board), style: StrokeStyle(lineWidth: 8.8, lineCap: .round, dash: [0.01, 9.5]))
    }

    /// The box open in front: its cut edge, and its inside lit warm — bright
    /// on the cake, darker to the sides — its floor, the shade under the lid
    /// and down the two sides.
    static func opening(_ context: GraphicsContext, _ l: CakeLayout) {
        let r = l.opening
        guard r.width > 0, r.height > 0 else { return }
        let corner: CGFloat = l.across ? 16 : 18
        let rounder: CGFloat = corner + 2.5
        let radii: RectangleCornerRadii = l.across ? RectangleCornerRadii(topLeading: corner, bottomLeading: 0, bottomTrailing: 0, topTrailing: corner)
            : RectangleCornerRadii(topLeading: corner, bottomLeading: corner, bottomTrailing: 0, topTrailing: 0)
        let outer: RectangleCornerRadii = l.across ? RectangleCornerRadii(topLeading: rounder, bottomLeading: 0, bottomTrailing: 0, topTrailing: rounder)
            : RectangleCornerRadii(topLeading: rounder, bottomLeading: rounder, bottomTrailing: 0, topTrailing: 0)
        let cut = Path(roundedRect: r.insetBy(dx: -2.5, dy: -2.5), cornerRadii: outer, style: .circular)
        context.fill(cut, with: vertical([stop(rgb(154, 106, 76), 0), stop(rgb(201, 160, 131), 0.06), stop(rgb(226, 196, 168), 1)], r.minY, r.maxY))
        let inside = Path(roundedRect: r, cornerRadii: radii, style: .circular)
        var g = context
        g.clip(to: inside)
        let warm = Gradient(stops: [stop(rgb(255, 244, 228), 0), stop(rgb(247, 220, 188), 0.42), stop(rgb(226, 181, 140), 0.78), stop(rgb(197, 140, 98), 1)])
        g.fill(Path(r), with: .radialGradient(warm, center: l.light, startRadius: 6, endRadius: max(40, l.lightReach)))
        let floor = r.maxY - 34
        g.fill(Path(CGRect(x: r.minX, y: floor, width: r.width, height: r.maxY - floor)),
               with: vertical([stop(rgb(120, 60, 30, 0.16), 0), stop(rgb(255, 238, 216, 0.42), 0.08), stop(rgb(196, 140, 100, 0.45), 1)], floor, r.maxY))
        g.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 20)),
               with: vertical([stop(rgb(90, 38, 14, 0.34), 0), stop(rgb(90, 38, 14, 0), 1)], r.minY, r.minY + 20))
        g.fill(Path(CGRect(x: r.minX, y: r.minY, width: 14, height: r.height)),
               with: across([stop(rgb(90, 38, 14, 0.22), 0), stop(rgb(90, 38, 14, 0), 1)], r.minX, r.minX + 14))
        g.fill(Path(CGRect(x: r.maxX - 14, y: r.minY, width: 14, height: r.height)),
               with: across([stop(rgb(90, 38, 14, 0), 0), stop(rgb(90, 38, 14, 0.22), 1)], r.maxX - 14, r.maxX))
    }

    /// The turning stand's top: a white plate with its rim's edge under the cake.
    static func plate(_ context: GraphicsContext, _ c: CGPoint, _ rx: CGFloat) {
        guard rx > 0 else { return }
        let side = vertical([stop(rgb(236, 230, 221), 0), stop(rgb(183, 175, 164), 1)], c.y, c.y + 15)
        context.fill(oval(CGPoint(x: c.x, y: c.y + 8), rx, 7), with: side)
        context.fill(Path(CGRect(x: c.x - rx, y: c.y + 3, width: 2 * rx, height: 5)), with: side)
        let top = oval(CGPoint(x: c.x, y: c.y + 3), rx, 7)
        context.fill(top, with: .color(rgb(251, 248, 243)))
        context.stroke(top, with: .color(rgb(140, 120, 100, 0.4)), lineWidth: 0.8)
    }

    /// One tier seen from the front and a little above (index 0 the bottom
    /// one): its frosting's face and top, then the drips off its edge, and
    /// the bottom one's beads, the middle one's dots, the top one's sprinkles.
    static func tier(_ context: GraphicsContext, _ r: CGRect, _ index: Int) {
        guard r.width > 8, r.height > 8 else { return }
        let c: ShellTone = index == 0 ? CakePaint.peach : (index == 1 ? CakePaint.cream : CakePaint.pink)
        let ry: CGFloat = 6, cx = r.midX, top = r.minY, bottom = r.maxY, half = r.width / 2
        var face = Path()
        face.move(to: CGPoint(x: r.minX, y: top))
        face.addLine(to: CGPoint(x: r.minX, y: bottom))
        for point in arc(CGPoint(x: cx, y: bottom), half, ry, from: Double.pi, to: 0) { face.addLine(to: point) }
        face.addLine(to: CGPoint(x: r.maxX, y: top))
        for point in arc(CGPoint(x: cx, y: top), half, ry, from: 0, to: Double.pi) { face.addLine(to: point) }
        face.closeSubpath()
        var lifted = context
        lifted.addFilter(.shadow(color: rgb(110, 50, 20, 0.28), radius: 6, x: 0, y: 3))
        lifted.fill(face, with: .color(c.color()))
        context.fill(face, with: across([stop(c.color(-0.16), 0), stop(c.color(0.16), 0.3), stop(c.color(), 0.55), stop(c.color(-0.2), 1)], r.minX, r.maxX))
        var dice = CakeDice(seed: 11 + index * 97)
        var inside = context
        inside.clip(to: face)
        if index == 1 {
            var dots = Path()
            var row = 0
            var y = top + 18
            while y < bottom {
                var x = r.minX + 10 + CGFloat(row % 2) * 11
                while x < r.maxX {
                    dots.addEllipse(in: CGRect(x: x - 1.9, y: y - 1.9, width: 3.8, height: 3.8))
                    x += 22
                }
                y += 15
                row += 1
            }
            inside.fill(dots, with: .color(rgb(244, 150, 172, 0.7)))
        }
        if index == 2 {
            let palette: [Color] = [Color.white, rgb(255, 214, 92), rgb(120, 200, 236), rgb(150, 214, 150), rgb(236, 108, 148), rgb(186, 150, 240)]
            let count = Int(r.width * r.height / 70)
            for i in 0..<count {
                let px = r.minX + 4 + dice.next() * (r.width - 8)
                let py = top + 14 + dice.next() * (r.height - 20)
                let turn = Double(dice.next()) * Double.pi
                var bit = inside
                bit.translateBy(x: px, y: py)
                bit.rotate(by: .radians(turn))
                bit.fill(rr(CGRect(x: -2.2, y: -0.8, width: 4.4, height: 1.6), 0.8), with: .color(palette[i % palette.count]))
            }
        }
        context.fill(oval(CGPoint(x: cx, y: top), half, ry), with: vertical([stop(c.color(0.4), 0), stop(c.color(0.12), 1)], top - ry, top + ry))
        let drip: Color = index == 1 ? rgb(246, 164, 186) : rgb(255, 247, 236)
        let base: CGFloat = index == 0 ? 8 : (index == 1 ? 10 : 14)
        let length = base * min(1, r.height / 72)
        let upper = arc(CGPoint(x: cx, y: top), half, ry, from: 0, to: Double.pi)
        let lower = arc(CGPoint(x: cx, y: top + 4), half, ry, from: Double.pi, to: 0)
        var band = polyline(upper)
        for point in lower { band.addLine(to: point) }
        band.closeSubpath()
        var drips = band
        var x = r.minX + 5
        while x < r.maxX - 5 {
            let t = (x - cx) / half
            let y = top + ry * max(0, 1 - t * t).squareRoot() + 1
            let long = length * (0.35 + dice.next() * 0.75)
            let thick = 4 + dice.next() * 3
            drips.addPath(rr(CGRect(x: x - thick / 2, y: y, width: thick, height: long), thick / 2))
            x += 6 + dice.next() * 7
        }
        context.fill(drips, with: .color(drip))
        context.stroke(polyline(arc(CGPoint(x: cx, y: top + 1.2), half - 3, ry - 1, from: 0.35, to: Double.pi - 0.35, steps: 18)),
                       with: .color(Color.white.opacity(0.45)), lineWidth: 1)
        if index == 0 {
            var beads = Path(), shine = Path()
            var bx = r.minX + 4
            while bx < r.maxX - 2 {
                let t = (bx - cx) / half
                let y = bottom + ry * max(0, 1 - t * t).squareRoot() - 2.5
                beads.addEllipse(in: CGRect(x: bx - 3.3, y: y - 3.3, width: 6.6, height: 6.6))
                shine.addEllipse(in: CGRect(x: bx - 2, y: y - 2.1, width: 2, height: 2))
                bx += 7
            }
            context.fill(beads, with: .color(rgb(255, 248, 240)))
            context.fill(shine, with: .color(Color.white.opacity(0.8)))
        }
    }

    /// A satin ribbon: dark edges and a light middle, two woven lines, its shadow.
    static func ribbon(_ context: GraphicsContext, _ r: CGRect, down: Bool) {
        guard r.width > 0, r.height > 0 else { return }
        var lifted = context
        lifted.addFilter(.shadow(color: rgb(100, 30, 10, 0.32), radius: 3, x: down ? 1 : 0, y: 1.2))
        let sheen: GraphicsContext.Shading = down ? across(Self.satin, r.minX, r.maxX) : vertical(Self.satin, r.minY, r.maxY)
        lifted.fill(Path(r), with: sheen)
        var weave = Path()
        if down {
            weave.addRect(CGRect(x: r.minX + 1.8, y: r.minY, width: 0.8, height: r.height))
            weave.addRect(CGRect(x: r.maxX - 2.6, y: r.minY, width: 0.8, height: r.height))
        } else {
            weave.addRect(CGRect(x: r.minX, y: r.minY + 1.8, width: r.width, height: 0.8))
            weave.addRect(CGRect(x: r.minX, y: r.maxY - 2.6, width: r.width, height: 0.8))
        }
        context.fill(weave, with: .color(rgb(255, 240, 225, 0.5)))
    }

    /// The box's base along its foot: a rose band with a paper-lace top edge,
    /// small holes along it.
    static func rim(_ context: GraphicsContext, _ size: CGSize, top y: CGFloat) {
        guard y < size.height else { return }
        let lace = CakePaint.rose.color(0.5)
        var scallops = Path()
        var x: CGFloat = 0
        while x < size.width + 10 {
            scallops.addEllipse(in: CGRect(x: x - 5, y: y - 4, width: 10, height: 10))
            x += 10
        }
        context.fill(scallops, with: .color(lace))
        context.fill(Path(CGRect(x: 0, y: y + 1, width: size.width, height: max(0, size.height - y - 1))),
                     with: vertical([stop(lace, 0), stop(CakePaint.rose.color(0.36), 1)], y, size.height))
        var holes = Path()
        x = 5
        while x < size.width {
            holes.addEllipse(in: CGRect(x: x - 1.1, y: y + 3.9, width: 2.2, height: 2.2))
            x += 10
        }
        context.fill(holes, with: .color(Color.white.opacity(0.55)))
    }

    /// The bow: two V-cut tails, two loops, the shade inside them, the knot.
    static func bow(_ context: GraphicsContext, at c: CGPoint, scale s: CGFloat) {
        guard s > 0 else { return }
        func p(_ dx: CGFloat, _ dy: CGFloat) -> CGPoint { CGPoint(x: c.x + dx * s, y: c.y + dy * s) }
        func sheen(_ a: CGPoint, _ b: CGPoint) -> GraphicsContext.Shading {
            .linearGradient(Gradient(stops: [stop(CakePaint.ribbonDark.color(), 0), stop(CakePaint.ribbon.color(), 0.35),
                                             stop(CakePaint.ribbonLight.color(), 0.62), stop(CakePaint.ribbon.color(), 1)]),
                            startPoint: a, endPoint: b)
        }
        var lifted = context
        lifted.addFilter(.shadow(color: rgb(100, 30, 10, 0.35), radius: 4, x: 0, y: 2))
        for d in [CGFloat(-1), CGFloat(1)] {
            var tail = Path()
            tail.move(to: p(d * 2, 2))
            tail.addLine(to: p(d * 15, 36))
            tail.addLine(to: p(d * 9.5, 32))
            tail.addLine(to: p(d * 5, 39))
            tail.addLine(to: p(-d * 5, 5))
            tail.closeSubpath()
            lifted.fill(tail, with: sheen(c, p(d * 15, 36)))
        }
        for d in [CGFloat(-1), CGFloat(1)] {
            var loop = Path()
            loop.move(to: c)
            loop.addCurve(to: p(d * 32, -2), control1: p(d * 9, -23), control2: p(d * 37, -23))
            loop.addCurve(to: c, control1: p(d * 29, 14), control2: p(d * 11, 11))
            loop.closeSubpath()
            lifted.fill(loop, with: sheen(p(0, -22), p(0, 12)))
        }
        var folds = Path()
        for d in [CGFloat(-1), CGFloat(1)] {
            folds.move(to: p(d * 6, -2))
            folds.addCurve(to: p(d * 26, -3), control1: p(d * 13, -13), control2: p(d * 25, -12))
            folds.addCurve(to: p(d * 6, -2), control1: p(d * 19, -6.5), control2: p(d * 12, -5))
            folds.closeSubpath()
        }
        context.fill(folds, with: .color(CakePaint.ribbonDark.color().opacity(0.5)))
        var knotted = context
        knotted.addFilter(.shadow(color: rgb(100, 30, 10, 0.3), radius: 2, x: 0, y: 0))
        let knot = CGRect(x: c.x - 6.5 * s, y: c.y - 8 * s, width: 13 * s, height: 15 * s)
        knotted.fill(rr(knot, 5 * s), with: across([stop(CakePaint.ribbonDark.color(), 0), stop(CakePaint.ribbonLight.color(), 0.5), stop(CakePaint.ribbonDark.color(), 1)],
                                                   knot.minX, knot.maxX))
    }

    /// The edge all round: a light line inside a darker one.
    static func edge(_ context: GraphicsContext, _ size: CGSize) {
        let whole = CGRect(origin: .zero, size: size)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 1.5, dy: 1.5), cornerRadius: 44.5), with: .color(Color.white.opacity(0.7)), lineWidth: 1.4)
        context.stroke(Path(roundedRect: whole.insetBy(dx: 0.5, dy: 0.5), cornerRadius: 46), with: .color(rgb(130, 60, 30, 0.5)), lineWidth: 1)
    }
}

/// The cake box under its parts, drawn as the picture of it was, part for
/// part: the cream board and its blush stripes, its grain, the light from the
/// upper left, the hinge's side in shade; the lid's window — a plain margin
/// with a paper-lace edge round the picture (the picture itself is left as
/// it is); the box open in front, warm inside; the turning stand's plate and
/// the three tiers on it (not in 相册: the cards hang there); the ribbon round
/// it all, the base's lace along the foot, the bow. Drawn once (it is the
/// same until the deck is another size or the picture another shape).
private struct CakeBackdrop: View, Equatable {
    var layout: CakeLayout
    var window: CGRect
    var hinge: CGRect
    var album: Bool
    var body: some View {
        Canvas { context, size in
            let l = layout
            CakeArt.paperboard(context, size, hinge)
            CakeArt.lace(context, around: window)
            CakeArt.opening(context, l)
            if !album {
                CakeArt.plate(context, l.plate, l.plateWide)
                for index in l.tiers.indices { CakeArt.tier(context, l.tiers[index], index) }
            }
            CakeArt.ribbon(context, l.ribbonAcross, down: false)
            CakeArt.ribbon(context, l.ribbonDown, down: true)
            if l.rim > 0 { CakeArt.rim(context, size, top: l.rim) }
            CakeArt.bow(context, at: l.bow, scale: l.bowScale)
            CakeArt.edge(context, size)
        }
        .accessibilityHidden(true)
    }
}

/// The lid's window round the picture, over the picture's own bezel: the
/// board's margin, a dotted rose line in it, the board's cut edge going down
/// into the window. Nothing over the picture itself.
private struct CakeWindowFrame: View, Equatable {
    var hole: CGRect
    var body: some View {
        Canvas { context, size in
            guard hole.width > 0, hole.height > 0 else { return }
            var margin = Path(roundedRect: hole.insetBy(dx: -9, dy: -9), cornerRadius: 18, style: .continuous)
            margin.addPath(Path(roundedRect: hole, cornerRadius: 9, style: .continuous))
            context.fill(margin, with: .color(CakePaint.board.color()), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: hole.insetBy(dx: -5.5, dy: -5.5), cornerRadius: 14.5, style: .continuous),
                           with: .color(CakePaint.rose.color().opacity(0.55)), style: StrokeStyle(lineWidth: 1.2, lineCap: .round, dash: [0.1, 3.6]))
            var cut = Path(roundedRect: hole.insetBy(dx: -2.5, dy: -2.5), cornerRadius: 11.5, style: .continuous)
            cut.addPath(Path(roundedRect: hole, cornerRadius: 9, style: .continuous))
            let edge = [CakeArt.stop(CakeArt.rgb(147, 100, 74), 0), CakeArt.stop(CakeArt.rgb(195, 156, 128), 0.1),
                        CakeArt.stop(CakeArt.rgb(234, 214, 194), 0.9), CakeArt.stop(CakeArt.rgb(255, 247, 238), 1)]
            context.fill(cut, with: CakeArt.vertical(edge, hole.minY - 3, hole.maxY + 3), style: FillStyle(eoFill: true))
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A part of the cake box pressed: it goes down (`travel`), or squashes
/// (`squash`: its height while down), or leans (`swing` degrees about
/// `anchor`), settling back with a spring where it squashed or leaned (at
/// once with Reduce Motion, which leaves the squash and the lean out); it
/// sounds (no sound: quiet, as while a video is taken) and is felt as it goes down.
private struct CakeKeyStyle: ButtonStyle {
    var travel: CGFloat = 1
    var squash: CGFloat = 1
    var swing: Double = 0
    var anchor: UnitPoint = .bottom
    var sound: ConsoleSound? = .click
    var scale: Float = 0.5
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View { CakeKeyBody(configuration: configuration, style: self) }
}
private struct CakeKeyBody: View {
    let configuration: ButtonStyle.Configuration
    let style: CakeKeyStyle
    @Environment(\.deckKeyInset) private var room
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let down = configuration.isPressed, s = style
        let swung: Double = down && !reduceMotion ? s.swing : 0
        let squashed: CGFloat = down && !reduceMotion ? s.squash : 1
        let springy = !reduceMotion && !down && (s.swing != 0 || s.squash != 1)
        let settle: Animation = springy ? .spring(response: 0.3, dampingFraction: 0.3) : .easeOut(duration: down ? 0.05 : 0.1)
        configuration.label
            .scaleEffect(x: 1, y: squashed, anchor: s.anchor)
            .rotationEffect(.degrees(swung), anchor: s.anchor)
            .offset(y: down ? s.travel : 0)
            .padding(room)
            .contentShape(Rectangle())
            .animation(settle, value: down)
            .onChange(of: down) { _, now in
                guard now else { return }
                if let sound = s.sound { ConsoleSounds.shared.play(sound, scale: s.scale) }
                ConsoleHaptics.shared.play(s.haptic, .press)
            }
    }
}

extension CameraDeckFace {
    /// The cake box under its parts (the lid's window round the picture in
    /// the shape chosen).
    func cakeBackdrop(_ cake: CakeLayout) -> some View {
        CakeBackdrop(layout: cake, window: layout.picture, hinge: hinge, album: false).equatable()
    }

    /// The lid's window round the picture: its margin and the board's cut
    /// edge, over the picture's own bezel; nothing over the picture itself.
    func cakeScreen(_ cake: CakeLayout) -> some View {
        CakeWindowFrame(hole: layout.picture).equatable()
            .frame(width: layout.canvas.width, height: layout.canvas.height)
    }

    /// The cake box, upright or across (the same parts, each where its hold
    /// has it): the ring of thin candles (镜头); the number candles (变焦);
    /// the flags (定时, 日期, 画幅) and the sparkler (闪光); the macarons
    /// (浓淡) and the chocolate plaque (拍照 | 录像); on the floor the jelly
    /// (水平仪), the stand's drum (内 / 外), the card (吹气拍照) and the gift
    /// box (相册); the tag (机型), the seal (主菜单), the big candle (拍照).
    /// The microphone listens for a breath only while the box takes
    /// pictures (CakeBreathEar: not in 录像, not with the bodies' cards up,
    /// not with 闪闪, whose sparkles a breath blows). While a video is taken
    /// the parts make no sound of their own.
    @ViewBuilder func cakeFace(_ cake: CakeLayout) -> some View {
        let quiet = model.recording
        let shooting: Bool = model.phase == .live && model.mode == .photo
        let free: Bool = !model.recording && !model.savingVideo && !model.bodiesOpen
        let listens: Bool = shooting && free && model.lens != .sparkle
        cakeLenses(cake)
        cakeNumbers(cake, quiet: quiet)
        cakeFlags(cake, quiet: quiet)
        cakeSparkler(cake, quiet: quiet)
        cakeMacarons(cake, quiet: quiet)
        cakePlaque(cake, quiet: quiet)
        cakeFloor(cake, quiet: quiet)
        cakeStrip(cake, quiet: quiet)
        CakeBreathEar(camera: listens) { model.shutter() }
            .deckPlaced(CGRect(x: 0, y: 0, width: 1, height: 1))
    }

    /// 镜头: the ring of thin candles round the bottom tier.
    private func cakeLenses(_ cake: CakeLayout) -> some View {
        CakeLensRow(model: model, cake: cake)
            .deckPlaced(cake.lenses)
    }

    /// 变焦: the number candles on the top tier, the stop in use lit; .5 paler
    /// where the camera has no ultra wide. They step back while the system's
    /// Camera Control menu is up (it has its own zoom).
    @ViewBuilder private func cakeNumbers(_ cake: CakeLayout, quiet: Bool) -> some View {
        let stops = model.zoomStops
        let chosen = stops.last { $0 <= model.zoom + 0.05 } ?? stops.first ?? 1
        let hidden = systemControlsUp
        let word = String(localized: "变焦")
        let lacking = String(localized: "这边的相机没有超广角")
        let count = min(cake.numbers.count, CakeLayout.stops.count)
        let sound: ConsoleSound? = quiet ? nil : .sharpen
        ForEach(0..<count, id: \.self) { index in
            let z = CakeLayout.stops[index]
            let offered = stops.contains(z)
            let on = offered && z == chosen
            let spoken: String = z < 1 ? "0.5×" : "\(Int(z))×"
            Button { cakeZoom(z, lacking: lacking) } label: {
                CakeNumberCandle(figure: Self.stopText(z), height: cake.numberHeight, base: cake.numberBase, flame: cake.numberFlame, lit: on)
            }
            .buttonStyle(CakeKeyStyle(travel: 3, sound: sound, scale: 0.3))
            .accessibilityLabel(word + " " + spoken)
            .accessibilityValue(on ? Self.zoomText(model.zoom) : "")
            .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier(z < 1 ? "camera-deck-candle-05" : "camera-deck-candle-\(Int(z))")
            .deckDimmed(!offered, why: lacking)
            .deckKey(cake.numbers[index])
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
        }
    }
    /// The zoom at a candle's stop (a firm stop where the camera has none
    /// such, and why).
    private func cakeZoom(_ z: Double, lacking: String) {
        guard model.zoomStops.contains(z) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            model.say(lacking)
            return
        }
        model.setZoom(z, sound: false)
    }

    /// 定时, 日期, 画幅: the paper flags on the middle ledge, each with its
    /// glyph drawn as it is set (定时's flag counts the seconds down, bobbing
    /// at each); 定时 waits in 录像, 画幅 where only 4:3 is taken.
    @ViewBuilder private func cakeFlags(_ cake: CakeLayout, quiet: Bool) -> some View {
        if cake.flags.count == 3 {
            let shooting = model.shooting
            let onWord = String(localized: "开"), offWord = String(localized: "关")
            let video = model.mode == .video
            let timerWhy = String(localized: "录像时不用定时")
            let timed = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
            let counting: String? = model.countdown.map { "\($0)" }
            let sound: ConsoleSound? = quiet ? nil : .pageFlip
            let mint = ShellTone(r: 0.675, g: 0.871, b: 0.784)
            let butter = ShellTone(r: 1.0, g: 0.878, b: 0.502)
            let lilac = ShellTone(r: 0.831, g: 0.761, b: 0.965)
            Button { if video { model.say(timerWhy) } else { model.cycleTimer() } } label: {
                CakeFlag(colour: mint, pick: cake.flagPick, top: cake.flagTop, tall: cake.flagHeight, glyph: .timer(model.timer),
                         glyphSize: cake.flagGlyph, figures: counting, bounce: model.countdown ?? 0)
            }
            .buttonStyle(cakeFlagStyle(cake, cake.flags[0], sound: sound))
            .accessibilityLabel(String(localized: "定时"))
            .accessibilityValue(timed)
            .accessibilityAddTraits(model.timer != .off ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-timer")
            .deckDimmed(video, why: timerWhy)
            .deckKey(cake.flags[0])
            Button { model.toggleDateStamp() } label: {
                CakeFlag(colour: butter, pick: cake.flagPick, top: cake.flagTop, tall: cake.flagHeight, glyph: .date(shooting.dateStamp),
                         glyphSize: cake.flagGlyph)
            }
            .buttonStyle(cakeFlagStyle(cake, cake.flags[1], sound: sound))
            .accessibilityLabel(String(localized: "日期"))
            .accessibilityValue(shooting.dateStamp ? onWord : offWord)
            .accessibilityAddTraits(shooting.dateStamp ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-date")
            .deckKey(cake.flags[1])
            Button { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } } label: {
                CakeFlag(colour: lilac, pick: cake.flagPick, top: cake.flagTop, tall: cake.flagHeight, glyph: .shape(model.shape),
                         glyphSize: cake.flagGlyph - 2, stacked: cake.flagStacked)
            }
            .buttonStyle(cakeFlagStyle(cake, cake.flags[2], sound: sound))
            .accessibilityLabel(CameraShellSkin.cake.shapeTitle)
            .accessibilityValue(model.shape.title)
            .accessibilityIdentifier("camera-deck-aspect")
            .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
            .deckKey(cake.flags[2])
        }
    }
    /// How a flag goes down: 2 points, leaning on its pick, and springs back.
    private func cakeFlagStyle(_ cake: CakeLayout, _ place: CGRect, sound: ConsoleSound?) -> CakeKeyStyle {
        let ax: CGFloat = place.width > 0 ? cake.flagPick / place.width : 0.2
        return CakeKeyStyle(travel: 2, swing: 5, anchor: UnitPoint(x: ax, y: 1), sound: sound, scale: 0.4)
    }

    /// 闪光: the sparkler, lit as it is set; its label's bolt drawn the same way.
    private func cakeSparkler(_ cake: CakeLayout, quiet: Bool) -> some View {
        let flash = model.shooting.flash
        let sound: ConsoleSound? = quiet ? nil : .sodaFizz
        return Button { model.cycleFlash() } label: {
            CakeSparkler(pick: cake.sparklerPick, coat: cake.sparklerCoat, radius: cake.sparks, mode: flash, glyphSize: cake.sparklerGlyph)
        }
        .buttonStyle(CakeKeyStyle(travel: 2, sound: sound, scale: 0.3))
        .accessibilityLabel(String(localized: "闪光"))
        .accessibilityValue(flash.title)
        .accessibilityIdentifier("camera-deck-flash")
        .deckKey(cake.sparkler)
    }

    /// 浓淡 − / ＋: the two macarons on the bottom tier, and under them a half
    /// filled circle and a row of cells for the step (原生 has none: a dash).
    @ViewBuilder private func cakeMacarons(_ cake: CakeLayout, quiet: Bool) -> some View {
        if cake.macarons.count == 2 {
            let shown = model.shownBody
            let step = model.strengthStep(of: shown)
            let share: String = shown == .native ? "—" : CameraBodyStrength.title(step)
            let lit = step - CameraBodyStrength.range.lowerBound + 1
            let cells: ShellGlyph? = shown == .native ? nil : ShellGlyph.tone(step: lit, of: CameraBodyStrength.values.count)
            let toneWord = String(localized: "浓淡")
            let sound: ConsoleSound? = quiet ? nil : .keyRubber
            let spot = cake.macaronCaption
            CakeToneCaption(cells: cells)
                .deckPlaced(CGRect(x: spot.x - 45, y: spot.y - 9, width: 90, height: 18))
            Button { model.stepBodyStrength(-1) } label: {
                CakeMacaron(colour: ShellTone(r: 0.973, g: 0.588, b: 0.675), sign: "−", size: cake.macaronSize)
            }
            .buttonStyle(CakeKeyStyle(travel: 0, squash: 0.92, sound: sound, scale: 0.45))
            .accessibilityLabel(toneWord + " −")
            .accessibilityValue(share)
            .accessibilityIdentifier("camera-deck-strength-minus")
            .deckKey(cake.macarons[0])
            Button { model.stepBodyStrength(1) } label: {
                CakeMacaron(colour: ShellTone(r: 0.973, g: 0.659, b: 0.408), sign: "＋", size: cake.macaronSize)
            }
            .buttonStyle(CakeKeyStyle(travel: 0, squash: 0.92, sound: sound, scale: 0.45))
            .accessibilityLabel(toneWord + " +")
            .accessibilityValue(share)
            .accessibilityIdentifier("camera-deck-strength-plus")
            .deckKey(cake.macarons[1])
        }
    }

    /// 拍照 | 录像: the chocolate plaque in two halves, the one in use piped
    /// round in white with a dot under its glyph (filled), the other's paler.
    @ViewBuilder private func cakePlaque(_ cake: CakeLayout, quiet: Bool) -> some View {
        if cake.halves.count == 2 {
            let video = model.mode == .video
            let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
            let sound: ConsoleSound? = quiet ? nil : .click
            CakePlaqueArt(split: true).equatable()
                .allowsHitTesting(false)
                .accessibilityHidden(true)
                .deckPlaced(cake.plaque)
            Button { model.setMode(.photo) } label: {
                CakeHalf(glyph: .photo(!video), on: !video, stacked: cake.plaqueStacked)
            }
            .buttonStyle(CakeKeyStyle(travel: 2, sound: sound, scale: 0.5))
            .accessibilityLabel(photoWord)
            .accessibilityAddTraits(video ? .isButton : [.isButton, .isSelected])
            .accessibilityIdentifier("camera-deck-mode-photo")
            .deckKey(cake.halves[0])
            Button { model.setMode(.video) } label: {
                CakeHalf(glyph: .video(video), on: video, stacked: cake.plaqueStacked)
            }
            .buttonStyle(CakeKeyStyle(travel: 2, sound: sound, scale: 0.5))
            .accessibilityLabel(videoWord)
            .accessibilityAddTraits(video ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-mode-video")
            .deckKey(cake.halves[1])
        }
    }

    /// The floor: the jelly (水平仪: a bright line across it while on, a level
    /// on its card), the stand's drum (内 / 外; 合体 changes the camera
    /// itself), the card (吹气拍照), the gift box (相册: two pictures and how
    /// many on it).
    @ViewBuilder private func cakeFloor(_ cake: CakeLayout, quiet: Bool) -> some View {
        let onWord = String(localized: "开"), offWord = String(localized: "关")
        let photos = model.photos
        let wobble: ConsoleSound? = quiet ? nil : .twang
        let pop: ConsoleSound? = quiet ? nil : .corkPop
        Button { model.toggleLeveler() } label: { CakeJelly(on: model.leveler) }
            .buttonStyle(CakeKeyStyle(travel: 0, squash: 0.88, sound: wobble, scale: 0.35))
            .accessibilityLabel(String(localized: "水平仪"))
            .accessibilityValue(model.leveler ? onWord : offWord)
            .accessibilityAddTraits(model.leveler ? [.isButton, .isSelected] : .isButton)
            .accessibilityIdentifier("camera-deck-leveler")
            .deckKey(cake.jelly)
        CakeDrumKey(inner: model.side == .inner, quiet: quiet) { model.switchSide() }
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(model.side.short)
            .accessibilityIdentifier("camera-deck-switch")
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(cake.drum)
        CakeBlowKey(card: !cake.across, quiet: quiet) { model.say($0) }
            .deckKey(cake.blow)
        Button { model.openAlbum() } label: { CakeGift(count: photos.count, across: cake.across) }
            .buttonStyle(CakeKeyStyle(travel: 1.5, sound: pop, scale: 0.3))
            .accessibilityLabel(CameraShellSkin.cake.albumTitle)
            .accessibilityValue(String(localized: "\(photos.count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .deckKey(cake.gift)
    }

    /// Down the strip: the tag on its twine from the bow (机型: the bodies'
    /// cards), two cameras traded printed by it; the seal on the ribbon
    /// (主菜单); the big candle (拍照; a red dot's worth of a lamp for a video:
    /// its flame burns while one is taken).
    @ViewBuilder private func cakeStrip(_ cake: CakeLayout, quiet: Bool) -> some View {
        let key = cake.tagKey
        let knot = CakeLayout.local(cake.knot, in: key)
        let ax: CGFloat = key.width > 0 ? knot.x / key.width : 0.5
        let ay: CGFloat = key.height > 0 ? knot.y / key.height : 0
        let flick: ConsoleSound? = quiet ? nil : .cardFlip
        let peel: ConsoleSound? = quiet ? nil : .rip
        Button { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } } label: {
            CakeTag(tag: CakeLayout.local(cake.tag, in: key), turn: cake.tagTurn, knot: knot, word: cake.tagWord)
        }
        .buttonStyle(CakeKeyStyle(travel: 0, swing: 7, anchor: UnitPoint(x: ax, y: ay), sound: flick, scale: 0.45))
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
        .deckKey(key)
        if cake.tagMark.width > 0 {
            ShellGlyphView(glyph: .changeBody, size: cake.across ? 16 : 18, ink: CakePaint.ink)
                .allowsHitTesting(false)
                .deckPlaced(cake.tagMark)
        }
        Button { model.leave() } label: { CakeSeal(radius: cake.sealRadius) }
            .buttonStyle(CakeKeyStyle(travel: 0, swing: -8, anchor: .center, sound: peel, scale: 0.35))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(cake.sealKey)
        CakeCandleKey(cake: cake, shots: model.flash, video: model.mode == .video, recording: model.recording, seconds: model.recordedSeconds, album: false,
                      sparkle: model.lens == .sparkle) {
            model.shutter()
        }
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
        .deckKey(cake.candleKey)
    }

    /// The cake box's 相册, upright and across.
    @ViewBuilder func cakeAlbum(_ cake: CakeLayout) -> some View {
        CakeAlbumView(model: model, thumbnails: thumbnails, cake: cake, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

/// A candle's flame: a soft warm glow round it, the teardrop, its pale core,
/// the blue at its root. `size` is the teardrop's; it stands in the middle
/// of a square 2.5 times its height, its round foot half its height under
/// the square's middle.
private struct CakeFlameArt: View, Equatable {
    var size: CGSize
    var body: some View {
        let side = size.height * 2.5
        Canvas { context, area in
            let w = size.width, h = size.height
            let cx = area.width / 2, by = area.height / 2 + h * 0.5
            let glowAt = CGPoint(x: cx, y: by - h * 0.5)
            let halo = [CakeArt.stop(CakeArt.rgb(255, 196, 110, 0.42), 0), CakeArt.stop(CakeArt.rgb(255, 170, 80, 0.13), 0.5), CakeArt.stop(CakeArt.rgb(255, 160, 70, 0), 1)]
            context.fill(CakeArt.disc(glowAt, h * 1.25), with: CakeArt.glow(glowAt, h * 1.25, halo))
            let fire = [CakeArt.stop(CakeArt.rgb(255, 146, 40, 0.92), 0), CakeArt.stop(CakeArt.rgb(255, 177, 58), 0.45),
                        CakeArt.stop(CakeArt.rgb(255, 213, 110), 0.8), CakeArt.stop(CakeArt.rgb(255, 231, 164), 1)]
            context.fill(CakeFlameArt.drop(cx, by, w, h, 1), with: CakeArt.vertical(fire, by - h, by))
            let core = [CakeArt.stop(CakeArt.rgb(255, 240, 180), 0), CakeArt.stop(CakeArt.rgb(255, 253, 240), 1)]
            context.fill(CakeFlameArt.drop(cx, by - h * 0.02, w, h, 0.6), with: CakeArt.vertical(core, by - h * 0.6, by))
            context.fill(CakeArt.oval(CGPoint(x: cx, y: by - w * 0.26), w * 0.24, w * 0.18), with: .color(CakeArt.rgb(90, 120, 230, 0.42)))
        }
        .frame(width: side, height: side)
    }
    /// The teardrop, `k` of the flame's size, its round foot on `by`.
    static func drop(_ cx: CGFloat, _ by: CGFloat, _ w: CGFloat, _ h: CGFloat, _ k: CGFloat) -> Path {
        let r = w / 2 * k, hh = h * k
        var path = Path()
        path.move(to: CGPoint(x: cx, y: by - hh))
        path.addCurve(to: CGPoint(x: cx + r, y: by - r), control1: CGPoint(x: cx + r * 0.35, y: by - hh * 0.62), control2: CGPoint(x: cx + r * 1.08, y: by - r * 1.7))
        for point in CakeArt.arc(CGPoint(x: cx, y: by - r), r, r, from: 0, to: Double.pi, steps: 16) { path.addLine(to: point) }
        path.addCurve(to: CGPoint(x: cx, y: by - hh), control1: CGPoint(x: cx - r * 1.08, y: by - r * 1.7), control2: CGPoint(x: cx - r * 0.35, y: by - hh * 0.62))
        path.closeSubpath()
        return path
    }
}

/// A flame burning: it sways and stretches a little (still with Reduce Motion).
private struct CakeFlame: View {
    var size: CGSize
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        Group {
            if reduceMotion {
                CakeFlameArt(size: size).equatable()
            } else {
                TimelineView(.animation(minimumInterval: 1.0 / 15, paused: false)) { context in
                    let t = context.date.timeIntervalSinceReferenceDate
                    let stretch = CGFloat(sin(t * 8.3) * 0.5 + sin(t * 13.7) * 0.5)
                    let lean = sin(t * 5.9 + 1.3) * 2.5
                    CakeFlameArt(size: size).equatable()
                        .scaleEffect(x: 1 - 0.05 * stretch, y: 1 + 0.07 * stretch, anchor: UnitPoint(x: 0.5, y: 0.7))
                        .rotationEffect(.degrees(lean), anchor: UnitPoint(x: 0.5, y: 0.7))
                }
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A wick, `length` up from the middle of its lower edge (6 points over it);
/// its tip glowing red once the flame is gone.
private struct CakeWick: View, Equatable {
    var length: CGFloat
    var ember: Bool
    var body: some View {
        Canvas { context, area in
            let cx = area.width / 2, y0 = area.height - 6
            var wick = Path()
            wick.move(to: CGPoint(x: cx, y: y0))
            wick.addQuadCurve(to: CGPoint(x: cx + 0.6, y: y0 - length), control: CGPoint(x: cx + 1.6, y: y0 - length * 0.55))
            context.stroke(wick, with: .color(CakePaint.wick), style: StrokeStyle(lineWidth: 1.5, lineCap: .round))
            if ember {
                let tip = CGPoint(x: cx + 0.6, y: y0 - length)
                let heat = [CakeArt.stop(CakeArt.rgb(255, 140, 50, 0.75), 0), CakeArt.stop(CakeArt.rgb(255, 120, 40, 0), 1)]
                context.fill(CakeArt.disc(tip, 6), with: CakeArt.glow(tip, 6, heat))
                context.fill(CakeArt.disc(tip, 1.7), with: .color(CakeArt.rgb(255, 116, 38)))
            }
        }
        .frame(width: 14, height: length + 12)
        .allowsHitTesting(false)
    }
}

/// A curl of smoke rising off a wick just blown out, its foot at the middle
/// of its lower edge.
private struct CakeSmokeArt: View, Equatable {
    var height: CGFloat
    var body: some View {
        Canvas { context, area in
            let base = context
            let cx = area.width / 2, by = area.height, h = height
            func curl(_ s: CGFloat, _ width: CGFloat, _ strength: Double, _ dx: CGFloat) {
                var path = Path()
                path.move(to: CGPoint(x: cx, y: by))
                path.addCurve(to: CGPoint(x: cx + s + dx, y: by - h * 0.52), control1: CGPoint(x: cx + 7 * s + dx, y: by - h * 0.18), control2: CGPoint(x: cx - 8 * s + dx, y: by - h * 0.36))
                path.addCurve(to: CGPoint(x: cx + 6 * s + dx, y: by - h), control1: CGPoint(x: cx + 10 * s + dx, y: by - h * 0.68), control2: CGPoint(x: cx - 4 * s + dx, y: by - h * 0.86))
                let fade = [CakeArt.stop(CakeArt.rgb(104, 94, 90, 0.62 * strength), 0), CakeArt.stop(CakeArt.rgb(140, 130, 126, 0.34 * strength), 0.55),
                            CakeArt.stop(CakeArt.rgb(170, 160, 156, 0), 1)]
                base.stroke(path, with: CakeArt.vertical(fade, by, by - h), style: StrokeStyle(lineWidth: width, lineCap: .round))
            }
            curl(1, 3.4, 1, 0)
            curl(-1, 2.2, 0.62, 4)
        }
        .frame(width: 34, height: height + 2)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// Glitter scattered over gold: white specks and darker ones.
private struct CakeGlitter: View, Equatable {
    var tint: ShellTone
    var body: some View {
        Canvas { context, area in
            var dice = CakeDice(seed: 5)
            var light = Path(), dark = Path()
            let count = Int(area.width * area.height / 4.5)
            for _ in 0..<count {
                let x = dice.next() * area.width, y = dice.next() * area.height
                let speck = CGRect(x: x, y: y, width: 0.9, height: 0.9)
                if dice.next() < 0.62 { light.addRect(speck) } else { dark.addRect(speck) }
            }
            context.fill(light, with: .color(Color.white.opacity(0.72)))
            context.fill(dark, with: .color(tint.color(-0.32).opacity(0.55)))
        }
        .allowsHitTesting(false)
    }
}

/// A number candle's wax: the heavy figure in gold, a darker rim round it,
/// glitter only on the wax; .5's point a small gold ball of its own.
private struct CakeNumberWax: View, Equatable {
    var figure: String
    var height: CGFloat
    var body: some View {
        let digits = figure == ".5" ? "5" : figure
        let font = Font.system(size: height / 0.733, weight: .black, design: .rounded)
        let gold = CakePaint.gold
        let fill = LinearGradient(colors: [gold.color(0.52), gold.color(), gold.color(-0.16)], startPoint: .top, endPoint: .bottom)
        let rim = gold.color(-0.4)
        HStack(alignment: .lastTextBaseline, spacing: 1) {
            if figure == ".5" {
                Circle()
                    .fill(RadialGradient(colors: [gold.color(0.6), gold.color(), gold.color(-0.2)], center: UnitPoint(x: 0.35, y: 0.3), startRadius: 0.5, endRadius: 6))
                    .overlay(Circle().strokeBorder(rim, lineWidth: 1.4))
                    .frame(width: 10, height: 10)
            }
            Text(verbatim: digits).font(font).foregroundStyle(fill)
                .overlay {
                    CakeGlitter(tint: gold).equatable()
                        .mask { Text(verbatim: digits).font(font) }
                }
                .background {
                    ZStack {
                        Text(verbatim: digits).font(font).foregroundStyle(rim).offset(x: -1.3, y: -1.3)
                        Text(verbatim: digits).font(font).foregroundStyle(rim).offset(x: 1.3, y: -1.3)
                        Text(verbatim: digits).font(font).foregroundStyle(rim).offset(x: -1.3, y: 1.3)
                        Text(verbatim: digits).font(font).foregroundStyle(rim).offset(x: 1.3, y: 1.3)
                    }
                }
        }
        .fixedSize()
        .allowsHitTesting(false)
    }
}

/// A number candle standing on the top tier: its figure, the wick from its
/// top, lit while it is the zoom in use (the flame comes up from a bead and
/// goes again; at once with Reduce Motion).
private struct CakeNumberCandle: View {
    var figure: String
    var height: CGFloat
    var base: CGFloat
    var flame: CGSize
    var lit: Bool
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        GeometryReader { geo in
            let cx = geo.size.width / 2
            let shift: CGFloat = figure == ".5" ? 5 : (figure == "4" ? 3.5 : (figure == "1" ? 1 : 0))
            let wx = cx + shift
            let top = base - height + 1
            let flameIn: AnyTransition = reduceMotion ? .opacity : .scale(scale: 0.2, anchor: .bottom).combined(with: .opacity)
            ZStack(alignment: .topLeading) {
                CakeNumberWax(figure: figure, height: height).equatable()
                    .position(x: cx, y: base - height / 2)
                CakeWick(length: 6, ember: false).equatable()
                    .position(x: wx, y: top - 3)
                if lit {
                    CakeFlame(size: flame)
                        .position(x: wx + 0.6, y: top - 5 - flame.height * 0.5)
                        .transition(flameIn)
                }
            }
            .frame(width: geo.size.width, height: geo.size.height, alignment: .topLeading)
            .animation(.easeOut(duration: 0.22), value: lit)
        }
    }
}

/// A paper flag on a wooden pick, stuck in the cake: the pick `pick` in from
/// the left, the flag `tall` high from `top`, its free end cut in a V.
private struct CakeFlagArt: View, Equatable {
    var colour: ShellTone
    var pick: CGFloat
    var top: CGFloat
    var tall: CGFloat
    var body: some View {
        Canvas { context, area in
            let sx = pick, fy = top, fh = tall, fw = max(10, area.width - 2 - pick), base = area.height - 1
            let c = colour
            var flag = Path()
            flag.move(to: CGPoint(x: sx, y: fy))
            flag.addCurve(to: CGPoint(x: sx + fw, y: fy), control1: CGPoint(x: sx + fw * 0.35, y: fy - 2.5), control2: CGPoint(x: sx + fw * 0.65, y: fy + 2.5))
            flag.addLine(to: CGPoint(x: sx + fw - 7, y: fy + fh / 2))
            flag.addLine(to: CGPoint(x: sx + fw, y: fy + fh))
            flag.addCurve(to: CGPoint(x: sx, y: fy + fh), control1: CGPoint(x: sx + fw * 0.65, y: fy + fh + 2.5), control2: CGPoint(x: sx + fw * 0.35, y: fy + fh - 2.5))
            flag.closeSubpath()
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.28), radius: 3, x: 0, y: 1.5))
            lifted.fill(flag, with: .color(c.color()))
            let sheen = [CakeArt.stop(Color.black.opacity(0.06), 0), CakeArt.stop(Color.white.opacity(0.2), 0.3), CakeArt.stop(Color.black.opacity(0.04), 0.7), CakeArt.stop(Color.white.opacity(0.1), 1)]
            context.fill(flag, with: CakeArt.across(sheen, sx, sx + fw))
            context.stroke(flag, with: .color(c.color(-0.28).opacity(0.6)), lineWidth: 0.8)
            var stick = Path()
            stick.move(to: CGPoint(x: sx, y: fy - 3))
            stick.addLine(to: CGPoint(x: sx, y: base))
            context.stroke(stick, with: .color(CakeArt.rgb(212, 171, 120)), style: StrokeStyle(lineWidth: 2.4, lineCap: .round))
            var shine = Path()
            shine.move(to: CGPoint(x: sx - 0.6, y: fy - 2))
            shine.addLine(to: CGPoint(x: sx - 0.6, y: base - 1))
            context.stroke(shine, with: .color(Color.white.opacity(0.45)), lineWidth: 0.7)
            context.fill(CakeArt.disc(CGPoint(x: sx, y: fy - 4), 2.3), with: .color(CakeArt.rgb(195, 149, 95)))
        }
    }
}

/// A flag as a key's face (定时, 日期, 画幅): what it is for drawn on it as it
/// is set, or a countdown's seconds; it bobs up a little at each second.
private struct CakeFlag: View {
    var colour: ShellTone
    var pick: CGFloat
    var top: CGFloat
    var tall: CGFloat
    var glyph: ShellGlyph
    var glyphSize: CGFloat
    var stacked = false
    var figures: String? = nil
    var bounce = 0
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var hop: CGFloat = 0
    var body: some View {
        GeometryReader { geo in
            let fw = geo.size.width - 2 - pick
            let mid = CGPoint(x: pick + (fw - 7) / 2 + 1.5, y: top + tall / 2)
            ZStack(alignment: .topLeading) {
                CakeFlagArt(colour: colour, pick: pick, top: top, tall: tall).equatable()
                mark.position(mid)
            }
            .frame(width: geo.size.width, height: geo.size.height, alignment: .topLeading)
            .offset(y: -hop)
        }
        .onChange(of: bounce) { _, now in
            guard now > 0, !reduceMotion else { return }
            withAnimation(.easeOut(duration: 0.1)) { hop = 3 }
            Task { @MainActor in
                try? await Task.sleep(nanoseconds: 120_000_000)
                withAnimation(.easeIn(duration: 0.16)) { hop = 0 }
            }
        }
    }
    @ViewBuilder private var mark: some View {
        if let figures {
            Text(verbatim: figures).font(.system(size: glyphSize + 2, weight: .black, design: .rounded)).monospacedDigit()
                .foregroundStyle(CakePaint.ink)
        } else {
            ShellGlyphView(glyph: glyph, size: glyphSize, ink: CakePaint.ink, stacked: stacked)
        }
    }
}

/// The sparkler's wire and its grey coating (the coating burnt back a little
/// while it is lit).
private struct CakeSparklerStick: View, Equatable {
    var pick: CGFloat
    var crown: CGFloat
    var foot: CGFloat
    var base: CGFloat
    var body: some View {
        Canvas { context, area in
            var wire = Path()
            wire.move(to: CGPoint(x: pick, y: base))
            wire.addLine(to: CGPoint(x: pick, y: 5))
            context.stroke(wire, with: .color(CakeArt.rgb(164, 169, 174)), style: StrokeStyle(lineWidth: 1.6, lineCap: .round))
            let thick: CGFloat = 6.6
            let coat = CGRect(x: pick - thick / 2, y: crown, width: thick, height: max(1, foot - crown))
            let shape = CakeArt.rr(coat, thick / 2)
            let grey = [CakeArt.stop(CakeArt.rgb(62, 56, 52), 0), CakeArt.stop(CakeArt.rgb(142, 132, 126), 0.45), CakeArt.stop(CakeArt.rgb(52, 48, 44), 1)]
            context.fill(shape, with: CakeArt.across(grey, coat.minX, coat.maxX))
            var inside = context
            inside.clip(to: shape)
            var rings = Path()
            var y = crown + 3
            while y < foot - 2 {
                rings.addRect(CGRect(x: coat.minX + 0.6, y: y, width: thick - 1.2, height: 0.8))
                y += 3.2
            }
            inside.fill(rings, with: .color(CakeArt.rgb(20, 16, 14, 0.35)))
            var dice = CakeDice(seed: 3)
            var specks = Path()
            for _ in 0..<40 {
                specks.addRect(CGRect(x: coat.minX + dice.next() * thick, y: crown + dice.next() * coat.height, width: 0.8, height: 0.8))
            }
            inside.fill(specks, with: .color(Color.white.opacity(0.35)))
        }
    }
}

/// A lit sparkler's burst: a glow, thirty rays (forked at their ends), a
/// white-hot middle. `seed` changes which.
private struct CakeSparksBurst: View, Equatable {
    var radius: CGFloat
    var seed: Int
    var body: some View {
        Canvas { context, area in
            let c = CGPoint(x: area.width / 2, y: area.height / 2), big = radius
            let halo = [CakeArt.stop(CakeArt.rgb(255, 240, 190, 0.85), 0), CakeArt.stop(CakeArt.rgb(255, 206, 120, 0.35), 0.3), CakeArt.stop(CakeArt.rgb(255, 190, 100, 0), 1)]
            context.fill(CakeArt.disc(c, big * 1.5), with: CakeArt.glow(c, big * 1.5, halo))
            var dice = CakeDice(seed: max(1, seed))
            var gold = Path(), white = Path(), forks = Path()
            for i in 0..<30 {
                let a = Double(i) / 30 * Double.pi * 2 + Double(dice.next()) * 0.25
                let reach = big * (0.5 + dice.next() * 0.55)
                let ca = CGFloat(cos(a)), sa = CGFloat(sin(a))
                let start = CGPoint(x: c.x + ca * 2.5, y: c.y + sa * 2.5)
                let end = CGPoint(x: c.x + ca * reach, y: c.y + sa * reach)
                if i % 3 == 0 {
                    white.move(to: start)
                    white.addLine(to: end)
                } else {
                    gold.move(to: start)
                    gold.addLine(to: end)
                }
                if i % 2 == 1 {
                    let fork = 3 + dice.next() * 3
                    forks.move(to: end)
                    forks.addLine(to: CGPoint(x: end.x + CGFloat(cos(a + 0.55)) * fork, y: end.y + CGFloat(sin(a + 0.55)) * fork))
                    forks.move(to: end)
                    forks.addLine(to: CGPoint(x: end.x + CGFloat(cos(a - 0.55)) * fork, y: end.y + CGFloat(sin(a - 0.55)) * fork))
                }
            }
            context.stroke(gold, with: .color(CakeArt.rgb(255, 206, 104, 0.95)), style: StrokeStyle(lineWidth: 0.9, lineCap: .round))
            context.stroke(white, with: .color(CakeArt.rgb(255, 250, 230, 0.95)), style: StrokeStyle(lineWidth: 1.2, lineCap: .round))
            context.stroke(forks, with: .color(CakeArt.rgb(255, 206, 104, 0.95)), style: StrokeStyle(lineWidth: 0.7, lineCap: .round))
            context.fill(CakeArt.disc(c, 2.8), with: .color(CakeArt.rgb(255, 251, 234)))
        }
        .frame(width: radius * 3 + 4, height: radius * 3 + 4)
    }
}

/// The burst sparkling (still with Reduce Motion).
private struct CakeSparks: View {
    var radius: CGFloat
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        Group {
            if reduceMotion {
                CakeSparksBurst(radius: radius, seed: 11).equatable()
            } else {
                TimelineView(.animation(minimumInterval: 1.0 / 12, paused: false)) { context in
                    let beat = Int(context.date.timeIntervalSinceReferenceDate * 12) % 997
                    CakeSparksBurst(radius: radius, seed: 11 + beat).equatable()
                }
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// 闪光 as a sparkler stuck in the ledge: its wire, its coating, a burst of
/// sparks while it is lit (开, 防红眼; a small one for 自动), and the paper
/// label tied on under it with the bolt drawn as it is set.
private struct CakeSparkler: View {
    var pick: CGFloat
    var coat: CGFloat
    var radius: CGFloat
    var mode: CameraFlashMode
    var glyphSize: CGFloat
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            let base = h - 1, foot = h * coat
            let fy = foot + 3, fh = max(10, base - 4 - fy)
            let lit = mode != .off
            let crown: CGFloat = lit ? 11 : 5
            let fw = w - 2 - pick
            ZStack(alignment: .topLeading) {
                CakeFlagArt(colour: ShellTone(r: 1.0, g: 0.784, b: 0.839), pick: pick, top: fy, tall: fh).equatable()
                CakeSparklerStick(pick: pick, crown: crown, foot: foot, base: base).equatable()
                ShellGlyphView(glyph: .flash(mode), size: glyphSize, ink: CakePaint.ink)
                    .position(x: pick + (fw - 7) / 2 + 1.5, y: fy + fh / 2)
                if lit {
                    CakeSparks(radius: mode == .auto ? radius * 0.55 : radius)
                        .position(x: pick, y: crown + 1)
                }
            }
            .frame(width: w, height: h, alignment: .topLeading)
        }
    }
}

/// A thin spiral birthday candle in its little rosette holder (its flame is
/// CakeFlame's), its foot at `base`; a pushpin by it where it stands for a
/// 机型 pinned among the lenses.
private struct CakeThinArt: View, Equatable {
    var colour: ShellTone
    var tall: CGFloat
    var base: CGFloat
    var pinned: Bool
    var body: some View {
        Canvas { context, area in
            let cx = area.width / 2, w: CGFloat = 8, x = cx - w / 2, top = base - tall
            let c = colour
            let wax = CakeArt.rr(CGRect(x: x, y: top, width: w, height: tall), 2)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 40, 20, 0.25), radius: 2, x: 1, y: 0))
            lifted.fill(wax, with: .color(c.color()))
            var inside = context
            inside.clip(to: wax)
            let round = [CakeArt.stop(c.color(-0.2), 0), CakeArt.stop(c.color(0.3), 0.38), CakeArt.stop(c.color(-0.24), 1)]
            inside.fill(Path(CGRect(x: x, y: top, width: w, height: tall)), with: CakeArt.across(round, x, x + w))
            var stripes = Path()
            var y = top - 8
            while y < base + 8 {
                stripes.move(to: CGPoint(x: x - 1, y: y + 5.5))
                stripes.addLine(to: CGPoint(x: x + w + 1, y: y))
                y += 7.5
            }
            inside.stroke(stripes, with: .color(Color.white.opacity(0.72)), lineWidth: 2.1)
            context.fill(CakeArt.oval(CGPoint(x: cx, y: top + 0.6), w / 2 - 0.3, 1.3), with: .color(c.color(0.45)))
            var rosette = Path()
            for i in 0...48 {
                let a = Double(i) / 48 * Double.pi * 2
                let q = 7.5 + 1.2 * CGFloat(cos(a * 8))
                let p = CGPoint(x: cx + CGFloat(cos(a)) * q, y: base - 1 + CGFloat(sin(a)) * q * 0.34)
                if i == 0 { rosette.move(to: p) } else { rosette.addLine(to: p) }
            }
            rosette.closeSubpath()
            context.fill(rosette, with: .color(CakePaint.paper))
            context.stroke(rosette, with: .color(CakeArt.rgb(150, 90, 60, 0.35)), lineWidth: 0.7)
            var wick = Path()
            wick.move(to: CGPoint(x: cx, y: top))
            wick.addQuadCurve(to: CGPoint(x: cx + 0.6, y: top - 6), control: CGPoint(x: cx + 1.6, y: top - 3.3))
            context.stroke(wick, with: .color(CakePaint.wick), style: StrokeStyle(lineWidth: 1.5, lineCap: .round))
            if pinned {
                let px = cx + 6, py = base - 8
                var pin = Path()
                pin.move(to: CGPoint(x: px, y: py))
                pin.addLine(to: CGPoint(x: px + 3.5, y: py - 6))
                context.stroke(pin, with: .color(CakeArt.rgb(139, 143, 150)), lineWidth: 1.1)
                context.fill(CakeArt.disc(CGPoint(x: px + 4.2, y: py - 7.2), 2.6), with: .color(CakeArt.rgb(226, 71, 94)))
                context.fill(CakeArt.disc(CGPoint(x: px + 3.5, y: py - 8), 0.9), with: .color(Color.white.opacity(0.8)))
            }
        }
    }
}

/// One candle of 镜头's ring: pulled up 10 points out of the frosting and lit
/// while it is the one in use, its name under it then (the others show only
/// their glyph there). At once with Reduce Motion.
private struct CakeThinCandle: View {
    var colour: ShellTone
    var glyph: ShellGlyph
    var name: String
    var chosen: Bool
    var pinned: Bool
    var base: CGFloat
    var tall: CGFloat
    var nameLine: CGFloat
    var flame: CGSize
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, cx = geo.size.width / 2
            let lift: CGFloat = chosen ? 10 : 0
            let flameIn: AnyTransition = reduceMotion ? .opacity : .scale(scale: 0.2, anchor: .bottom).combined(with: .opacity)
            ZStack(alignment: .topLeading) {
                ZStack(alignment: .topLeading) {
                    CakeThinArt(colour: colour, tall: tall, base: base, pinned: pinned).equatable()
                        .frame(width: w, height: geo.size.height)
                    if chosen {
                        CakeFlame(size: flame)
                            .position(x: cx + 0.6, y: base - tall - 5.5 - flame.height * 0.5)
                            .transition(flameIn)
                    }
                }
                .offset(y: -lift)
                Group {
                    if chosen {
                        Text(name).font(.system(size: 11, weight: .black, design: .rounded)).foregroundStyle(CakePaint.ink)
                            .lineLimit(1).minimumScaleFactor(0.6)
                            .frame(width: w + 6)
                    } else {
                        ShellGlyphView(glyph: glyph, size: 13, ink: CakePaint.soft)
                    }
                }
                .position(x: cx, y: nameLine)
            }
            .frame(width: w, height: geo.size.height, alignment: .topLeading)
            .animation(reduceMotion ? nil : .spring(response: 0.3, dampingFraction: 0.62), value: chosen)
        }
    }
}

/// 镜头: the ring of thin candles round the bottom tier — the lenses, then
/// the 机型 pinned among them (a pushpin by each) — a row that goes along,
/// keeping the one in use in sight (at once with Reduce Motion), with cream's
/// soft pop as one is pulled up. It steps back while the system's Camera
/// Control menu is up.
private struct CakeLensRow: View {
    @ObservedObject var model: CameraAppModel
    var cake: CakeLayout
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    private enum Item: Hashable { case lens(CameraLens), body(CameraBody) }
    var body: some View {
        let items: [Item] = CameraLens.allCases.map(Item.lens) + model.pinnedBodies.map(Item.body)
        ScrollViewReader { reader in
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(alignment: .top, spacing: 6) {
                    ForEach(items, id: \.self) { item in
                        candle(item).id(item)
                    }
                }
                .padding(.horizontal, cake.lensPad)
                .frame(height: cake.lenses.height)
            }
            .accessibilityIdentifier("camera-deck-lenses")
            .onAppear { reader.scrollTo(Item.lens(model.lens), anchor: .center) }
            .onChange(of: model.lens) { _, lens in
                withAnimation(reduceMotion ? nil : .easeOut(duration: 0.15)) { reader.scrollTo(Item.lens(lens), anchor: .center) }
            }
        }
        .opacity(model.controlsShown ? 0 : 1)
        .allowsHitTesting(!model.controlsShown)
    }
    private func candle(_ item: Item) -> some View {
        let title: String, glyph: ShellGlyph, chosen: Bool, identifier: String, colour: ShellTone, pinned: Bool
        switch item {
        case .lens(let lens):
            title = lens.title; glyph = .lens(lens); chosen = model.lens == lens; identifier = "camera-deck-lens-\(lens.rawValue)"
            colour = CakePaint.lens(lens); pinned = false
        case .body(let fixed):
            title = fixed.title; glyph = .body(fixed); chosen = model.body == fixed; identifier = "camera-deck-pinned-\(fixed.rawValue)"
            let at = model.pinnedBodies.firstIndex(of: fixed) ?? 0
            colour = CakePaint.pinned[at % CakePaint.pinned.count]; pinned = true
        }
        let sound: ConsoleSound? = model.recording ? nil : .corkPop
        return Button {
            switch item {
            case .lens(let lens): model.choose(lens)
            case .body(let fixed): model.tapPinned(fixed)
            }
        } label: {
            CakeThinCandle(colour: colour, glyph: glyph, name: title, chosen: chosen, pinned: pinned, base: cake.lensBase, tall: cake.lensTall,
                           nameLine: cake.lensName, flame: cake.lensFlame)
        }
        .buttonStyle(CakeKeyStyle(travel: 1, sound: sound, scale: 0.25))
        .frame(width: 50, height: cake.lenses.height)
        .accessibilityLabel(title)
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier(identifier)
    }
}

/// A macaron pressed on the cake's side: two domed shells with frilly feet,
/// the cream between them, its sign piped on its top.
private struct CakeMacaronArt: View, Equatable {
    var colour: ShellTone
    var sign: String
    var body: some View {
        Canvas { context, area in
            let w = area.width, h = area.height, cx = w / 2, cy = h / 2
            let sh = h * 0.4, fl = h * 0.2, t = cy - fl / 2, b = cy + fl / 2
            let c = colour
            func shell(_ y0: CGFloat, up: Bool) -> Path {
                let rise: CGFloat = (up ? -1.3 : 1.15) * sh
                var path = Path()
                path.move(to: CGPoint(x: cx - w / 2, y: y0))
                path.addCurve(to: CGPoint(x: cx + w / 2, y: y0), control1: CGPoint(x: cx - w / 2, y: y0 + rise), control2: CGPoint(x: cx + w / 2, y: y0 + rise))
                path.closeSubpath()
                return path
            }
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 40, 20, 0.3), radius: 3, x: 0, y: 1.6))
            lifted.fill(shell(b, up: false), with: .color(c.color()))
            context.fill(shell(b, up: false), with: CakeArt.vertical([CakeArt.stop(c.color(0.1), 0), CakeArt.stop(c.color(-0.2), 1)], b, b + sh))
            context.fill(CakeArt.rr(CGRect(x: cx - w / 2 + 2.5, y: t - 0.5, width: w - 5, height: fl + 1), fl / 2), with: .color(CakeArt.rgb(255, 245, 232)))
            context.fill(shell(t, up: true), with: CakeArt.vertical([CakeArt.stop(c.color(0.38), 0), CakeArt.stop(c.color(), 1)], t - sh, t))
            var feet = Path()
            var x = cx - w / 2 + 2.5
            while x < cx + w / 2 - 1.5 {
                feet.addEllipse(in: CGRect(x: x - 1.3, y: t - 2.4, width: 2.6, height: 2.6))
                feet.addEllipse(in: CGRect(x: x - 1.3, y: b - 0.2, width: 2.6, height: 2.6))
                x += 3
            }
            context.fill(feet, with: .color(c.color(0.22)))
            let mark = Text(verbatim: sign).font(.system(size: 17, weight: .black, design: .rounded))
            context.draw(mark.foregroundColor(Color.white.opacity(0.55)), at: CGPoint(x: cx, y: t - sh * 0.5 + 0.8))
            context.draw(mark.foregroundColor(CakeArt.rgb(110, 36, 16)), at: CGPoint(x: cx, y: t - sh * 0.5))
        }
    }
}

/// A macaron as a key's face, in the upper part of its place.
private struct CakeMacaron: View {
    var colour: ShellTone
    var sign: String
    var size: CGSize
    var body: some View {
        GeometryReader { geo in
            let w = min(size.width, max(20, geo.size.width - 6))
            CakeMacaronArt(colour: colour, sign: sign).equatable()
                .frame(width: w, height: size.height)
                .position(x: geo.size.width / 2, y: size.height / 2 + 1.5)
        }
    }
}

/// Under the macarons: a circle half dark and half light (浓淡), the step as a
/// row of cells (a dash for 原生).
private struct CakeToneCaption: View {
    var cells: ShellGlyph?
    var body: some View {
        HStack(spacing: 4) {
            ShellGlyphView(glyph: .toneMark, size: 13, ink: CakePaint.ink)
            if let cells {
                ShellGlyphView(glyph: cells, size: 15, ink: CakePaint.ink)
            } else {
                Text(verbatim: "—").font(.system(size: 11, weight: .heavy, design: .rounded)).foregroundStyle(CakePaint.soft)
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A chocolate plaque: its lit top edge, its shadow; split by a groove into
/// two halves (`split`).
private struct CakePlaqueArt: View, Equatable {
    var split: Bool
    var body: some View {
        Canvas { context, area in
            let whole = CGRect(origin: .zero, size: area)
            let c = CakePaint.chocolate
            let shape = CakeArt.rr(whole, 9)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(60, 24, 10, 0.45), radius: 4, x: 0, y: 2))
            lifted.fill(shape, with: .color(c.color()))
            context.fill(shape, with: CakeArt.vertical([CakeArt.stop(c.color(0.24), 0), CakeArt.stop(c.color(), 0.16), CakeArt.stop(c.color(-0.25), 1)], 0, area.height))
            if split {
                let half = (area.width - 6) / 2
                context.fill(Path(CGRect(x: half + 2, y: 5, width: 2, height: max(0, area.height - 10))), with: .color(c.color(-0.45)))
                context.fill(Path(CGRect(x: half + 4, y: 5, width: 1, height: max(0, area.height - 10))), with: .color(CakeArt.rgb(255, 220, 190, 0.2)))
            }
        }
    }
}

/// One half of the plaque as a key's face: its glyph, filled and in white
/// with the piping round it and a dot under it while it is the one in use,
/// hollow and paler while not.
private struct CakeHalf: View {
    var glyph: ShellGlyph
    var on: Bool
    var stacked: Bool
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            let ink: Color = on ? CakePaint.icing : CakeArt.rgb(255, 226, 200, 0.6)
            let dot: CGFloat = stacked ? 3.2 : 3.8
            ZStack(alignment: .topLeading) {
                if on {
                    RoundedRectangle(cornerRadius: 6, style: .continuous)
                        .stroke(CakePaint.icing, style: StrokeStyle(lineWidth: 1.7, lineCap: .round, dash: [0.1, 3.3]))
                        .frame(width: max(0, w - 7), height: max(0, h - 8))
                        .position(x: w / 2, y: h / 2)
                }
                ShellGlyphView(glyph: glyph, size: stacked ? 16 : 19, ink: ink)
                    .position(x: w / 2, y: stacked ? h * 0.42 : h / 2 - 2)
                if on {
                    Circle().fill(ink)
                        .frame(width: dot, height: dot)
                        .position(x: w / 2, y: h - (stacked ? 6 : 7))
                }
            }
            .frame(width: w, height: h, alignment: .topLeading)
        }
    }
}

/// A little folded card stood in front of a sweet, as on a party's table.
private struct CakeTentArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let card = CGRect(origin: .zero, size: area).insetBy(dx: 1.5, dy: 1.5)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.28), radius: 2.5, x: 0, y: 1.2))
            lifted.fill(CakeArt.rr(card, 3), with: .color(CakePaint.paper))
            context.fill(Path(CGRect(x: card.minX + 2, y: card.minY + 2, width: max(0, card.width - 4), height: 1.2)), with: .color(CakeArt.rgb(160, 110, 80, 0.18)))
        }
    }
}

/// A folded card with something drawn on it.
private struct CakeTent<Content: View>: View {
    var width: CGFloat
    var height: CGFloat
    var content: Content
    var body: some View {
        ZStack {
            CakeTentArt().equatable()
            content
        }
        .frame(width: width, height: height)
        .allowsHitTesting(false)
    }
}

/// 水平仪 as a jelly bar on a little dish, made like a spirit level — a
/// bubble between two marks — a bright level line across it while it is on.
private struct CakeJellyArt: View, Equatable {
    var on: Bool
    var body: some View {
        Canvas { context, area in
            let w = area.width
            let jx: CGFloat = 8, jw = max(10, w - 16), jy: CGFloat = 3, jh: CGFloat = 15, mid = w / 2
            let dish = CakeArt.oval(CGPoint(x: mid, y: jy + jh + 2.5), max(4, w / 2 - 3), 4.2)
            context.fill(dish, with: .color(CakeArt.rgb(255, 250, 243)))
            context.stroke(dish, with: .color(CakeArt.rgb(150, 90, 60, 0.4)), lineWidth: 0.8)
            let bar = CakeArt.rr(CGRect(x: jx, y: jy, width: jw, height: jh), 6)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(150, 70, 20, 0.35), radius: 3, x: 0, y: 1.5))
            lifted.fill(bar, with: .color(CakeArt.rgb(246, 160, 56, 0.92)))
            let glaze = [CakeArt.stop(CakeArt.rgb(255, 232, 180, 0.75), 0), CakeArt.stop(CakeArt.rgb(255, 190, 90, 0.05), 0.45), CakeArt.stop(CakeArt.rgb(170, 74, 16, 0.3), 1)]
            context.fill(bar, with: CakeArt.vertical(glaze, jy, jy + jh))
            context.stroke(bar, with: .color(CakeArt.rgb(170, 80, 20, 0.55)), lineWidth: 0.9)
            var dice = CakeDice(seed: 13)
            var bits = Path()
            for _ in 0..<18 {
                bits.addRect(CGRect(x: jx + 2 + dice.next() * (jw - 4), y: jy + 1.5 + dice.next() * (jh - 3), width: 0.9, height: 0.9))
            }
            context.fill(bits, with: .color(Color.white.opacity(0.8)))
            if on {
                var level = Path()
                level.move(to: CGPoint(x: jx + 4, y: jy + jh / 2))
                level.addLine(to: CGPoint(x: jx + jw - 4, y: jy + jh / 2))
                context.stroke(level, with: .color(CakeArt.rgb(255, 250, 220, 0.6)), style: StrokeStyle(lineWidth: 4, lineCap: .round))
                context.stroke(level, with: .color(Color.white), style: StrokeStyle(lineWidth: 1.4, lineCap: .round))
            }
            var marks = Path()
            for mx in [mid - 7, mid + 7] {
                marks.move(to: CGPoint(x: mx, y: jy + 3))
                marks.addLine(to: CGPoint(x: mx, y: jy + jh - 3))
            }
            context.stroke(marks, with: .color(CakeArt.rgb(120, 50, 10, 0.7)), lineWidth: 1)
            let bubble = CakeArt.oval(CGPoint(x: mid, y: jy + jh / 2), 5, 3.6)
            context.fill(bubble, with: .color(CakeArt.rgb(255, 252, 240, 0.92)))
            context.stroke(bubble, with: .color(CakeArt.rgb(170, 90, 30, 0.5)), lineWidth: 0.7)
        }
    }
}

/// The jelly as a key's face: the jelly on its dish, its card in front with
/// a level on it (hollow while off, filled while on).
private struct CakeJelly: View {
    var on: Bool
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            ZStack(alignment: .topLeading) {
                CakeJellyArt(on: on).equatable()
                    .frame(width: w, height: 26)
                CakeTent(width: max(30, w - 6), height: 21, content: ShellGlyphView(glyph: .level(on), size: 15, ink: CakePaint.ink))
                    .position(x: w / 2, y: h - 12)
            }
            .frame(width: w, height: h, alignment: .topLeading)
        }
    }
}

/// The turning stand's base, the part that turns: a drum ridged all round,
/// a cream plate on its front.
private struct CakeDrumArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let w = area.width, h = area.height, cx = w / 2
            let t: CGFloat = 2, b = h - 8, ry: CGFloat = 4.5
            var drum = Path()
            drum.move(to: CGPoint(x: 0, y: t))
            drum.addLine(to: CGPoint(x: 0, y: b))
            for point in CakeArt.arc(CGPoint(x: cx, y: b), w / 2, ry, from: Double.pi, to: 0) { drum.addLine(to: point) }
            drum.addLine(to: CGPoint(x: w, y: t))
            drum.closeSubpath()
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 40, 15, 0.35), radius: 4, x: 0, y: 2))
            lifted.fill(drum, with: .color(CakeArt.rgb(242, 236, 228)))
            let steel = [CakeArt.stop(CakeArt.rgb(189, 180, 168), 0), CakeArt.stop(CakeArt.rgb(251, 248, 242), 0.3),
                         CakeArt.stop(CakeArt.rgb(236, 229, 220), 0.62), CakeArt.stop(CakeArt.rgb(174, 164, 151), 1)]
            context.fill(drum, with: CakeArt.across(steel, 0, w))
            var ridges = context
            ridges.clip(to: drum)
            var dark = Path(), light = Path()
            for i in 0...18 {
                let px = cx - CGFloat(cos(Double(i) / 18 * Double.pi)) * w / 2
                if abs(px - cx) < w * 0.3 { continue }
                dark.addRect(CGRect(x: px - 0.6, y: t, width: 1.2, height: b - t))
                light.addRect(CGRect(x: px + 0.6, y: t, width: 0.8, height: b - t))
            }
            ridges.fill(dark, with: .color(CakeArt.rgb(110, 90, 70, 0.28)))
            ridges.fill(light, with: .color(Color.white.opacity(0.55)))
            let plate = CakeArt.rr(CGRect(x: cx - w * 0.31, y: t + 3, width: w * 0.62, height: b - t), 5)
            context.fill(plate, with: .color(CakeArt.rgb(255, 252, 247)))
            context.stroke(plate, with: .color(CakeArt.rgb(150, 110, 80, 0.35)), lineWidth: 0.8)
        }
    }
}

/// 内 / 外 as the turning stand's drum, a camera turning drawn on its plate:
/// pressed, it gives a point with the stand's rumble; when the other camera
/// comes, the plate's camera turns right round (at once with Reduce Motion).
private struct CakeDrumKey: View {
    var inner: Bool
    var quiet = false
    var action: () -> Void
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var turn: Double = 0
    var body: some View {
        let sound: ConsoleSound? = quiet ? nil : .beads
        Button(action: action) {
            GeometryReader { geo in
                ZStack {
                    CakeDrumArt().equatable()
                        .frame(width: min(geo.size.width, 76), height: geo.size.height)
                    ShellGlyphView(glyph: .flip, size: 16, ink: CakePaint.ink)
                        .rotation3DEffect(.degrees(turn), axis: (x: 0, y: 1, z: 0), perspective: 0.5)
                }
                .frame(width: geo.size.width, height: geo.size.height)
            }
        }
        .buttonStyle(CakeKeyStyle(travel: 1, sound: sound, scale: 0.35))
        .onChange(of: inner) { _, _ in spin() }
    }
    private func spin() {
        guard !reduceMotion else { return }
        withAnimation(.easeIn(duration: 0.14)) { turn = 90 }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 140_000_000)
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) { turn = -90 }
            withAnimation(.easeOut(duration: 0.16)) { turn = 0 }
        }
    }
}

/// 吹气拍照's glyph, drawn (no system glyph says it): a mouth blowing, three
/// breaths out of it; struck through while it is off (the paper cleared round
/// the stroke).
private struct CakeBreathGlyph: View, Equatable {
    var size: CGFloat
    var ink: Color
    var paper: Color
    var off: Bool
    var body: some View {
        let k = size / 24, line = ShellGlyphView.line(size)
        Canvas { context, area in
            let ox = (area.width - 24 * k) / 2, oy = (area.height - 24 * k) / 2
            func p(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: ox + x * k, y: oy + y * k) }
            let shade = GraphicsContext.Shading.color(ink)
            let stroke = StrokeStyle(lineWidth: line, lineCap: .round, lineJoin: .round)
            context.stroke(Path(ellipseIn: CGRect(x: ox + 2.5 * k, y: oy + 7.5 * k, width: 7 * k, height: 9 * k)), with: shade, style: stroke)
            context.fill(Path(ellipseIn: CGRect(x: ox + 4.7 * k, y: oy + 10.6 * k, width: 2.6 * k, height: 2.8 * k)), with: shade)
            var breaths = Path()
            breaths.move(to: p(12.5, 7.6))
            breaths.addQuadCurve(to: p(20, 6.2), control: p(16.5, 8.6))
            breaths.move(to: p(12.5, 12))
            breaths.addQuadCurve(to: p(22, 12), control: p(17, 10.6))
            breaths.move(to: p(12.5, 16.4))
            breaths.addQuadCurve(to: p(20, 17.8), control: p(16.5, 15.4))
            context.stroke(breaths, with: shade, style: stroke)
            if off {
                var slash = Path()
                slash.move(to: p(3.5, 21))
                slash.addLine(to: p(21, 3.5))
                context.stroke(slash, with: .color(paper), style: StrokeStyle(lineWidth: line * 3, lineCap: .round))
                context.stroke(slash, with: shade, style: StrokeStyle(lineWidth: line * 1.1, lineCap: .round))
            }
        }
        .frame(width: size + line + 1, height: size)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// A little cream label stuck on the box, a rose line round inside it.
private struct CakeLabelArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let whole = CGRect(origin: .zero, size: area).insetBy(dx: 1.5, dy: 1.5)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.3), radius: 3, x: 0, y: 1.2))
            lifted.fill(CakeArt.rr(whole, 5), with: .color(CakePaint.paper))
            context.stroke(CakeArt.rr(whole.insetBy(dx: 2.5, dy: 2.5), 3.5), with: .color(CakePaint.rose.color().opacity(0.45)), lineWidth: 0.8)
        }
    }
}

/// 吹气拍照's face: a folded card on the floor (upright) or a label stuck on
/// the box (across), the mouth blowing on it.
private struct CakeBlowCard: View {
    var on: Bool
    var card: Bool
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            let middle: CGFloat = card ? h - 16 : h / 2
            ZStack(alignment: .topLeading) {
                if card {
                    CakeTentArt().equatable()
                        .frame(width: min(44, max(30, w - 2)), height: 30)
                        .position(x: w / 2, y: middle)
                } else {
                    CakeLabelArt().equatable()
                        .frame(width: min(60, max(30, w - 4)), height: 32)
                        .position(x: w / 2, y: middle)
                }
                CakeBreathGlyph(size: 20, ink: CakePaint.ink, paper: CakePaint.paper, off: !on).equatable()
                    .position(x: w / 2, y: middle)
