}

/// 吹气拍照: a touch turns blowing the big candle out on or off (kept); paler
/// where the microphone cannot be used (not allowed, or none here), and
/// VoiceOver is told why — a touch that turns it on then says it too.
private struct CakeBlowKey: View {
    var card: Bool
    var quiet = false
    var say: (String) -> Void
    @ObservedObject private var breath = CakeBreath.shared
    var body: some View {
        let onWord = String(localized: "开"), offWord = String(localized: "关")
        let blocked = breath.refused || breath.missing
        let why: String = breath.missing ? String(localized: "这里没有麦克风可用") : String(localized: "麦克风没打开：设置 › Zero EMU › 麦克风")
        let sound: ConsoleSound? = quiet ? nil : .cardFlip
        Button {
            breath.toggle()
            if breath.on, blocked { say(why) }
        } label: {
            CakeBlowCard(on: breath.on, card: card)
        }
        .buttonStyle(CakeKeyStyle(travel: 1.5, sound: sound, scale: 0.45))
        .accessibilityLabel(String(localized: "吹气拍照"))
        .accessibilityValue(breath.on ? onWord : offWord)
        .accessibilityAddTraits(breath.on ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-blow")
        .deckDimmed(blocked, why: why)
    }
}

/// The gift box: dotted rose paper, its lid, a coral ribbon down it and a
/// bow on the lid.
private struct CakeGiftArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let w = area.width, h = area.height, c = CakePaint.gift
            let lid: CGFloat = 13, by: CGFloat = 14, bh = max(lid + 6, h - 16), inset: CGFloat = 4
            let box = CGRect(x: inset, y: by + 6, width: max(0, w - 2 * inset), height: max(0, bh - 6))
            let shape = CakeArt.rr(box, 4)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.35), radius: 5, x: 0, y: 2.5))
            lifted.fill(shape, with: .color(c.color()))
            context.fill(shape, with: CakeArt.across([CakeArt.stop(c.color(-0.12), 0), CakeArt.stop(c.color(0.1), 0.4), CakeArt.stop(c.color(-0.16), 1)], 0, w))
            var wrapping = context
            wrapping.clip(to: shape)
            var dots = Path()
            var row = 0
            var y = by + 12
            while y < by + bh {
                var x = inset + 4 + CGFloat(row % 2) * 5
                while x < w {
                    dots.addEllipse(in: CGRect(x: x - 1.5, y: y - 1.5, width: 3, height: 3))
                    x += 10
                }
                y += 9
                row += 1
            }
            wrapping.fill(dots, with: .color(Color.white.opacity(0.7)))
            let top = CGRect(x: 0, y: by, width: w, height: lid)
            var shaded = context
            shaded.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.3), radius: 3, x: 0, y: 1.5))
            shaded.fill(CakeArt.rr(top, 3), with: .color(c.color(0.06)))
            context.fill(CakeArt.rr(top, 3), with: CakeArt.vertical([CakeArt.stop(c.color(0.25), 0), CakeArt.stop(c.color(-0.1), 1)], by, by + lid))
            let band = CGRect(x: w / 2 - 5, y: by, width: 10, height: bh)
            context.fill(Path(band), with: CakeArt.across(CakeArt.satin, band.minX, band.maxX))
            CakeArt.bow(context, at: CGPoint(x: w / 2, y: by - 1), scale: 0.42)
        }
    }
}

/// 相册 as the gift box: two pictures (the album's glyph) on its paper, how
/// many on a round sticker.
private struct CakeGift: View {
    var count: Int
    var across: Bool
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = geo.size.height
            let box: CGRect = across ? CGRect(x: 3, y: -4, width: max(30, w - 7), height: h + 4) : CGRect(x: 0, y: 0, width: w, height: h)
            let lid: CGFloat = 13
            let by = box.minY + 14
            let bh = max(lid + 6, box.height - 16)
            let line = by + lid + (bh - lid) / 2 + 2
            ZStack(alignment: .topLeading) {
                CakeGiftArt().equatable()
                    .frame(width: box.width, height: box.height)
                    .position(x: box.midX, y: box.midY)
                ShellGlyphView(glyph: .album, size: across ? 12 : 14, ink: Color.white)
                    .position(x: box.minX + box.width * 0.27, y: line)
                ZStack {
                    Circle().fill(CakePaint.paper)
                    Circle().strokeBorder(CakePaint.rose.color().opacity(0.7), lineWidth: 1)
                    Text(verbatim: "\(count)").font(.system(size: 10.5, weight: .heavy, design: .rounded)).monospacedDigit()
                        .foregroundStyle(CakePaint.ink)
                        .lineLimit(1).minimumScaleFactor(0.5)
                        .padding(.horizontal, 2)
                }
                .frame(width: 20, height: 20)
                .position(x: box.minX + box.width * 0.76, y: line)
            }
            .frame(width: w, height: h, alignment: .topLeading)
        }
    }
}

/// The hang tag on its twine: a card with its top corners clipped, a dashed
/// rose line round inside it, a punched hole ringed in coral, ZERO (the only
/// word on the box); the twine from the bow's knot through its hole.
private struct CakeTagArt: View, Equatable {
    var tag: CGRect
    var turn: Double
    var knot: CGPoint
    var word: CGFloat
    var body: some View {
        Canvas { context, area in
            let base = context
            let w = tag.width, h = tag.height, cx = tag.midX, top = tag.minY
            let hole: CGFloat = h < 50 ? 9 : 10
            let hx = cx - CGFloat(sin(turn)) * hole, hy = top + CGFloat(cos(turn)) * hole
            let twine = CakeArt.rgb(251, 243, 230)
            func strand(_ spread: CGFloat, _ pull: CGFloat) {
                var path = Path()
                path.move(to: knot)
                path.addQuadCurve(to: CGPoint(x: hx + spread, y: hy - 1), control: CGPoint(x: knot.x + (hx - knot.x) * pull, y: hy - 10))
                base.stroke(path, with: .color(twine), style: StrokeStyle(lineWidth: 1.6, lineCap: .round))
                base.stroke(path, with: .color(CakeArt.rgb(150, 90, 60, 0.45)), style: StrokeStyle(lineWidth: 0.5, lineCap: .round))
            }
            strand(-1.8, 0.25)
            strand(1.8, 0.6)
            var g = context
            g.translateBy(x: cx, y: top)
            g.rotate(by: .radians(turn))
            let corner = min(9, w * 0.2)
            var card = Path()
            card.move(to: CGPoint(x: -w / 2 + corner, y: 0))
            card.addLine(to: CGPoint(x: w / 2 - corner, y: 0))
            card.addLine(to: CGPoint(x: w / 2, y: corner))
            card.addLine(to: CGPoint(x: w / 2, y: h - 4))
            card.addQuadCurve(to: CGPoint(x: w / 2 - 4, y: h), control: CGPoint(x: w / 2, y: h))
            card.addLine(to: CGPoint(x: -w / 2 + 4, y: h))
            card.addQuadCurve(to: CGPoint(x: -w / 2, y: h - 4), control: CGPoint(x: -w / 2, y: h))
            card.addLine(to: CGPoint(x: -w / 2, y: corner))
            card.closeSubpath()
            var lifted = g
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.38), radius: 5, x: 0, y: 2.5))
            lifted.fill(card, with: .color(CakeArt.rgb(255, 250, 242)))
            g.fill(card, with: CakeArt.vertical([CakeArt.stop(CakeArt.rgb(255, 253, 248), 0), CakeArt.stop(CakeArt.rgb(244, 230, 212), 1)], 0, h))
            g.stroke(card, with: .color(CakeArt.rgb(140, 70, 40, 0.4)), lineWidth: 1)
            var inner = Path()
            inner.move(to: CGPoint(x: -w / 2 + corner + 1, y: 3.5))
            inner.addLine(to: CGPoint(x: w / 2 - corner - 1, y: 3.5))
            inner.addLine(to: CGPoint(x: w / 2 - 3.5, y: corner + 1.5))
            inner.addLine(to: CGPoint(x: w / 2 - 3.5, y: h - 3.5))
            inner.addLine(to: CGPoint(x: -w / 2 + 3.5, y: h - 3.5))
            inner.addLine(to: CGPoint(x: -w / 2 + 3.5, y: corner + 1.5))
            inner.closeSubpath()
            g.stroke(inner, with: .color(CakePaint.rose.color().opacity(0.5)), style: StrokeStyle(lineWidth: 0.8, dash: [2, 2]))
            g.fill(CakeArt.disc(CGPoint(x: 0, y: hole), 4.6), with: .color(CakePaint.ribbon.color()))
            g.fill(CakeArt.disc(CGPoint(x: 0, y: hole), 2.3), with: .color(CakeArt.rgb(201, 160, 131)))
            let spacing = word * 0.18
            let zero = Text(verbatim: "ZERO").font(.system(size: word, weight: .black, design: .rounded)).tracking(spacing)
            g.draw(zero.foregroundColor(CakePaint.ink), at: CGPoint(x: spacing / 2, y: hole + (h - hole) * 0.52))
            var loop = Path()
            loop.move(to: CGPoint(x: hx - 1.8, y: hy - 4))
            loop.addQuadCurve(to: CGPoint(x: hx + 1.8, y: hy - 4), control: CGPoint(x: hx, y: hy + 2))
            base.stroke(loop, with: .color(twine), style: StrokeStyle(lineWidth: 1.6, lineCap: .round))
        }
    }
}

/// The tag as a key's face: drawn in a room 40 points bigger all round than
/// its place (its twine goes up to the bow).
private struct CakeTag: View {
    var tag: CGRect
    var turn: Double
    var knot: CGPoint
    var word: CGFloat
    var body: some View {
        GeometryReader { geo in
            let m: CGFloat = 40
            CakeTagArt(tag: tag.offsetBy(dx: m, dy: m), turn: turn, knot: CGPoint(x: knot.x + m, y: knot.y + m), word: word).equatable()
                .frame(width: geo.size.width + 2 * m, height: geo.size.height + 2 * m)
                .position(x: geo.size.width / 2, y: geo.size.height / 2)
        }
    }
}

/// The round seal sticker on the ribbon: scalloped, a little light on it, a
/// dotted ring inside its edge.
private struct CakeSealArt: View, Equatable {
    var radius: CGFloat
    var body: some View {
        Canvas { context, area in
            let c = CGPoint(x: area.width / 2, y: area.height / 2), r = radius
            var seal = Path()
            for i in 0...144 {
                let a = Double(i) / 144 * Double.pi * 2
                let q = r - 1.5 + 1.5 * CGFloat(cos(a * 18))
                let p = CGPoint(x: c.x + CGFloat(cos(a)) * q, y: c.y + CGFloat(sin(a)) * q)
                if i == 0 { seal.move(to: p) } else { seal.addLine(to: p) }
            }
            seal.closeSubpath()
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 30, 12, 0.34), radius: 3, x: 0, y: 1.5))
            lifted.fill(seal, with: .color(CakePaint.rose.color()))
            let light = Gradient(colors: [Color.white.opacity(0.26), Color.white.opacity(0)])
            context.fill(seal, with: .radialGradient(light, center: CGPoint(x: c.x - r * 0.3, y: c.y - r * 0.35), startRadius: 1, endRadius: r * 1.2))
            context.stroke(CakeArt.disc(c, r - 4.5), with: .color(Color.white.opacity(0.85)), style: StrokeStyle(lineWidth: 1.1, lineCap: .round, dash: [0.1, 3]))
        }
    }
}

/// 主菜单 as the seal: a house on it, in white.
private struct CakeSeal: View {
    var radius: CGFloat
    var body: some View {
        ZStack {
            CakeSealArt(radius: radius).equatable()
            ShellGlyphView(glyph: .home, size: radius * 0.72, ink: Color.white)
        }
    }
}

/// The big candle on its gold saucer: ivory wax with a rose and coral spiral,
/// its top melted, drips down from it (its wick and its flame are
/// CakeBigCandle's). Its saucer's foot at `foot`.
private struct CakeBigArt: View, Equatable {
    var wide: CGFloat
    var tall: CGFloat
    var foot: CGFloat
    var body: some View {
        Canvas { context, area in
            let cx = area.width / 2, w = wide, sw = w * 0.74
            let gold = CakePaint.gold
            let saucer = CakeArt.oval(CGPoint(x: cx, y: foot - 5), sw, 6.5)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 40, 10, 0.38), radius: 4, x: 0, y: 2))
            lifted.fill(saucer, with: .color(gold.color()))
            context.fill(saucer, with: CakeArt.across([CakeArt.stop(gold.color(-0.28), 0), CakeArt.stop(gold.color(0.55), 0.38), CakeArt.stop(gold.color(-0.32), 1)], cx - sw, cx + sw))
            context.fill(CakeArt.oval(CGPoint(x: cx, y: foot - 7), max(2, sw - 6), 4), with: .color(gold.color(-0.1)))
            let left = cx - w / 2, bottom = foot - 7, top = bottom - tall
            let pillar = CGRect(x: left, y: top, width: w, height: tall)
            var wax = context
            wax.clip(to: CakeArt.rr(pillar, 3))
            wax.fill(Path(pillar), with: .color(CakeArt.rgb(251, 243, 230)))
            var pink = Path(), coral = Path()
            var y = top - w
            while y < bottom + w {
                pink.move(to: CGPoint(x: left - 2, y: y + w * 0.55))
                pink.addLine(to: CGPoint(x: left + w + 2, y: y))
                pink.addLine(to: CGPoint(x: left + w + 2, y: y + 6))
                pink.addLine(to: CGPoint(x: left - 2, y: y + w * 0.55 + 6))
                pink.closeSubpath()
                coral.move(to: CGPoint(x: left - 2, y: y + w * 0.55 + 8.5))
                coral.addLine(to: CGPoint(x: left + w + 2, y: y + 8.5))
                coral.addLine(to: CGPoint(x: left + w + 2, y: y + 11))
                coral.addLine(to: CGPoint(x: left - 2, y: y + w * 0.55 + 11))
                coral.closeSubpath()
                y += 15
            }
            wax.fill(pink, with: .color(CakePaint.rose.color(0.35)))
            wax.fill(coral, with: .color(CakePaint.ribbon.color().opacity(0.85)))
            let round = [CakeArt.stop(CakeArt.rgb(120, 70, 40, 0.28), 0), CakeArt.stop(Color.white.opacity(0.18), 0.32), CakeArt.stop(Color.clear, 0.6), CakeArt.stop(CakeArt.rgb(120, 70, 40, 0.32), 1)]
            wax.fill(Path(pillar), with: CakeArt.across(round, left, left + w))
            let rim = CakeArt.oval(CGPoint(x: cx, y: top), w / 2, 4)
            context.fill(rim, with: .color(CakeArt.rgb(255, 247, 236)))
            context.stroke(rim, with: .color(CakeArt.rgb(160, 110, 80, 0.35)), lineWidth: 0.8)
            context.fill(CakeArt.oval(CGPoint(x: cx, y: top + 0.4), max(2, w / 2 - 5), 2.4), with: .color(CakeArt.rgb(230, 200, 170, 0.5)))
            let shares: [CGFloat] = [0.12, 0.3, 0.78, 0.92], lengths: [CGFloat] = [9, 5, 12, 6]
            var drips = Path()
            for index in 0..<4 {
                drips.addPath(CakeArt.rr(CGRect(x: left + w * shares[index] - 2.6, y: top + 1, width: 5.2, height: lengths[index]), 2.6))
            }
            context.fill(drips, with: .color(CakeArt.rgb(255, 247, 236)))
        }
    }
}

/// The big candle as 拍照's face (in 相册, 回去拍照's): it stands lit, and a
/// picture taken blows it out — the flame goes, a curl of smoke rises off the
/// wick (about 0.8 s, not with Reduce Motion) and its tip glows red — and a
/// second later it lights itself again with a match's scrape. For a video it
/// stands out until one is taken, its flame the lamp that says one is being
/// taken; it goes out with a curl of smoke as the video stops. Under it on
/// the base (upright): what a touch or a breath does, that the picture is
/// taken, a video's time; in 相册 that it goes back.
private struct CakeBigCandle: View {
    var wide: CGFloat
    var tall: CGFloat
    var foot: CGFloat
    var flame: CGSize
    var smokeHeight: CGFloat
    var hint: CGRect
    var shots: Int
    var video: Bool
    var recording: Bool
    var seconds: Int
    var album: Bool
    var hears: Bool
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var blown = false
    @State private var smoke: Double = 0
    @State private var rise: CGFloat = 0
    @State private var stamp = 0
    var body: some View {
        GeometryReader { geo in
            let cx = geo.size.width / 2
            let top = foot - 7 - tall
            let lit: Bool = album || (video ? recording : !blown)
            let flameIn: AnyTransition = reduceMotion ? .opacity : .scale(scale: 0.15, anchor: .bottom).combined(with: .opacity)
            ZStack(alignment: .topLeading) {
                CakeBigArt(wide: wide, tall: tall, foot: foot).equatable()
                    .frame(width: geo.size.width, height: geo.size.height)
                CakeWick(length: 8, ember: blown && !lit).equatable()
                    .position(x: cx, y: top - 4)
                if lit {
                    CakeFlame(size: flame)
                        .position(x: cx + 0.6, y: top - 7 - flame.height * 0.5)
                        .transition(flameIn)
                }
                CakeSmokeArt(height: smokeHeight).equatable()
                    .position(x: cx + 0.6, y: top - 9 - (smokeHeight + 2) / 2)
                    .offset(y: rise)
                    .opacity(smoke)
                if hint.width > 0 {
                    words
                        .frame(width: hint.width, height: hint.height, alignment: .trailing)
                        .position(x: hint.midX, y: hint.midY)
                }
            }
            .frame(width: geo.size.width, height: geo.size.height, alignment: .topLeading)
            .animation(.easeOut(duration: 0.2), value: lit)
        }
        .onChange(of: shots) { _, _ in
            guard !album, !video else { return }
            blowOut()
        }
        .onChange(of: recording) { was, now in
            guard !album, was, !now else { return }
            puff()
        }
        .onChange(of: video) { _, _ in
            // Another mode: a picture's blowing out is over (and its match not struck).
            stamp += 1
            blown = false
        }
    }
    /// The words on the base under the candle (hidden from VoiceOver: the
    /// key says its own name, and a breath in its hint).
    @ViewBuilder private var words: some View {
        if recording {
            Text(verbatim: "● " + CameraAppModel.clock(seconds))
                .font(.system(size: 10.5, weight: .heavy, design: .rounded)).monospacedDigit()
                .foregroundStyle(CakePaint.alarm)
                .accessibilityHidden(true)
        } else if album {
            // (11-23: the hints only on a new console, the first time — OnceHintView; a picture taken says so always)
            OnceHintView("cake-album") { line(String(localized: "点大蜡烛也能回去拍照"), breath: false) }
        } else if blown {
            line(String(localized: "拍好了 · 1 秒后它自己再点着"), breath: false)
        } else if hears && !video {
            OnceHintView("cake", seconds: 6) { line(String(localized: "点一下或对着麦克风吹一口气"), breath: true) }
        }
    }
    private func line(_ said: String, breath: Bool) -> some View {
        HStack(spacing: 5) {
            if breath {
                CakeBreathGlyph(size: 13, ink: CakePaint.soft, paper: Color.clear, off: false).equatable()
            }
            Text(said)
                .font(.system(size: 10.5, weight: .heavy, design: .rounded))
                .foregroundStyle(CakePaint.ink)
                .lineLimit(1).minimumScaleFactor(0.7)
        }
        .accessibilityHidden(true)
    }
    /// A picture taken: the flame goes, the smoke rises, the tip glows; lit
    /// again a second later (a picture before then begins it all again).
    private func blowOut() {
        // (a picture taken: the line to blow has done its work)
        OnceHint.mark("cake")
        stamp += 1
        let mine = stamp
        withAnimation(.easeIn(duration: 0.12)) { blown = true }
        puff()
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 1_000_000_000)
            guard stamp == mine else { return }
            withAnimation(.easeOut(duration: 0.25)) { blown = false }
            ConsoleSounds.shared.play(.sharpen, scale: 0.3)
        }
    }
    /// A curl of smoke off the wick (none with Reduce Motion).
    private func puff() {
        guard !reduceMotion else { return }
        var still = Transaction()
        still.disablesAnimations = true
        withTransaction(still) {
            smoke = 1
            rise = 0
        }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 40_000_000)
            withAnimation(.easeOut(duration: 0.9)) {
                smoke = 0
                rise = -14
            }
        }
    }
}

/// 拍照 as the big candle (in 相册, 回去拍照): pressed, it sinks 2 points,
/// felt as the shutter (the shutter's own sound is the camera's). VoiceOver
/// is told that a breath on the microphone takes the picture too, while that
/// is so (not with 闪闪, whose sparkles a breath blows; else why it waits,
/// `why`, if it does).
private struct CakeCandleKey: View {
    var cake: CakeLayout
    var shots: Int
    var video: Bool
    var recording: Bool
    var seconds: Int
    var album: Bool
    var why = ""
    var sparkle = false
    var action: () -> Void
    @ObservedObject private var breath = CakeBreath.shared
    var body: some View {
        let key = cake.candleKey
        let hears = !album && !video && !sparkle && breath.usable
        let hint: CGRect = cake.hint.width > 0 ? CakeLayout.local(cake.hint, in: key) : .zero
        let felt: HapticPart = album ? .smallButton : .faceButton
        Button(action: action) {
            CakeBigCandle(wide: cake.candleWide, tall: cake.candleTall, foot: cake.candleFoot - key.minY, flame: cake.candleFlame,
                          smokeHeight: cake.candleSmoke, hint: hint, shots: shots, video: video, recording: recording, seconds: seconds,
                          album: album, hears: hears)
        }
        .buttonStyle(CakeKeyStyle(travel: 2, sound: nil, haptic: felt))
        .accessibilityHint(hears ? String(localized: "也可以对着麦克风吹气") : why)
    }
}

/// 吹气拍照: whether a breath on the microphone blows the big candle out
/// (kept; on unless it is turned off), whether the microphone can be used
/// (not allowed in 设置; none here), and the ears that want a breath. The
/// microphone listens, under one name, while one of them does and this is
/// on; the start of a breath, a second or more after the last one, presses
/// the big candle for the one that wants it.
@MainActor final class CakeBreath: ObservableObject {
    static let shared = CakeBreath()
    static let defaultsKey = "FoldArc.camera.cake.blow"
    static let reason = "camera-cake"
    /// The least time from one picture taken by a breath to the next.
    static let spacing: TimeInterval = 1.2
    @Published private(set) var on: Bool
    @Published private(set) var refused = false
    @Published private(set) var missing = false
    /// A breath can take a picture just now.
    var usable: Bool { on && !refused && !missing }
    private var ears: [UUID: () -> Void] = [:]
    private var listening = false
    private var last = Date.distantPast
    private var accessWatch: AnyCancellable?
    private var breathWatch: AnyCancellable?

    private init() {
        let kept = UserDefaults.standard
        on = kept.object(forKey: Self.defaultsKey) == nil ? true : kept.bool(forKey: Self.defaultsKey)
        accessWatch = MicListener.shared.$access.removeDuplicates().sink { [weak self] access in
            MainActor.assumeIsolated {
                self?.refused = access == .denied
                self?.missing = access == .unavailable
            }
        }
    }

    /// 吹气拍照 turned on or off (kept).
    func toggle() {
        on.toggle()
        UserDefaults.standard.set(on, forKey: Self.defaultsKey)
        refresh()
    }

    /// The ear `id` wants a breath (and what a breath does then), or no
    /// longer does.
    func ear(_ id: UUID, wants: Bool, heard: @escaping () -> Void) {
        ears[id] = wants ? heard : nil
        refresh()
    }

    private func refresh() {
        let wanted = on && !ears.isEmpty
        guard wanted != listening else { return }
        listening = wanted
        if wanted {
            breathWatch = MicListener.shared.$blowing.removeDuplicates().dropFirst().sink { [weak self] blowing in
                guard blowing else { return }
                MainActor.assumeIsolated { self?.blew() }
            }
        } else {
            breathWatch = nil
        }
        MicListener.shared.want(Self.reason, wanted)
    }

    /// A breath begins: one picture for it, and none again for a moment.
    private func blew() {
        let now = Date()
        guard listening, now.timeIntervalSince(last) >= Self.spacing, let heard = ears.values.first else { return }
        last = now
        heard()
    }
}

/// Nothing to see: while the box is on the cover taking pictures it wants a
/// breath on the microphone (CakeBreath), and a breath presses the big
/// candle; it no longer does once it is gone or not taking pictures.
private struct CakeBreathEar: View {
    var camera: Bool
    var heard: () -> Void
    @State private var id = UUID()
    var body: some View {
        Color.clear
            .allowsHitTesting(false)
            .accessibilityHidden(true)
            .onAppear { CakeBreath.shared.ear(id, wants: camera, heard: heard) }
            .onChange(of: camera) { _, now in CakeBreath.shared.ear(id, wants: now, heard: heard) }
            .onDisappear { CakeBreath.shared.ear(id, wants: false, heard: heard) }
    }
}

// MARK: - The birthday cake box's album: 相册

/// The cake box's 相册: the picture looked at in the lid's window (a video
/// plays where it is touched; a push to the side goes to the next), which
/// one of how many on a label on the ribbon; the cards pegged on their
/// string under it, the one looked at larger in a coral edge (one touched is
/// looked at); three iced cookies — the one before, ▶ (a video plays; a
/// picture's waits, and says why), the one after; the gift box opened on the
/// floor; 回去拍照 on a chocolate plaque, and the big candle goes back too;
/// the seal is 主菜单 as ever. The tag only hangs there.
private struct CakeAlbumView: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    var cake: CakeLayout
    var hinge: CGRect
    @State private var push: CGFloat = 0

    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    private var video: Bool { model.albumPhoto?.isVideo == true }
    /// The video's length ("00:12"), once it is known.
    private var length: String? {
        guard let photo = model.albumPhoto, photo.isVideo, model.albumImageURL == photo.url, let seconds = model.albumDuration else { return nil }
        return CameraAppModel.clock(Int(seconds.rounded()))
    }
    private var videoWord: String { length.map { String(localized: "视频 \($0)") } ?? String(localized: "录像") }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    private func sharp(_ photo: CameraPhoto?) -> CGImage? {
        guard let photo else { return nil }
        return (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }
    /// The one before (−1) or after (+1); at either end a firm stop, and why.
    private func turn(_ delta: Int) {
        guard !drawing else { model.say(drawingWhy); return }
        let next = model.albumIndex + delta
        guard model.photos.indices.contains(next) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            if model.photos.isEmpty {
                model.say(String(localized: "还没有照片"))
            } else {
                model.say(delta < 0 ? String(localized: "已经是第一张") : String(localized: "已经是最后一张"))
            }
            return
        }
        model.chooseInAlbum(next, quiet: true)
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            CakeBackdrop(layout: cake, window: cake.window, hinge: hinge, album: true).equatable()
            window
            CakeWindowFrame(hole: cake.window).equatable()
            ribbonLabel
            cards
            cookies
            openGift
            back
            hangTag
            home
            candle
        }
    }

    /// The lid's window: the picture looked at, whole (a video plays where it
    /// is touched; a push to the side goes to the next one); while a picture
    /// is being drawn on inside, that it waits there; what the camera says,
    /// for a moment.
    private var window: some View {
        let r = cake.window
        let photos = model.photos, at = model.albumIndex
        return ZStack {
            CakeArt.rgb(58, 40, 32)
            if photos.isEmpty {
                Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
            } else if photos.indices.contains(at) {
                picture(photos[at])
            }
            if model.doodle != nil {
                Text("正在编辑 · 打开 Duo，在下屏接着画").font(.system(size: 12, weight: .heavy, design: .rounded)).foregroundStyle(Color.white)
                    .multilineTextAlignment(.center).lineLimit(2).minimumScaleFactor(0.7)
                    .padding(.horizontal, 12).padding(.vertical, 6)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 16)
            }
            if let toast = model.toast {
                Text(toast).font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(Color.white)
                    .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                    .padding(.horizontal, 10).padding(.vertical, 4)
                    .background(Capsule().fill(Color.black.opacity(0.62)))
                    .padding(.horizontal, 14)
                    .frame(maxHeight: .infinity, alignment: .bottom)
                    .padding(.bottom, 12)
                    .allowsHitTesting(false)
                    .transition(.opacity)
            }
        }
        .frame(width: r.width, height: r.height)
        .clipShape(RoundedRectangle(cornerRadius: 9, style: .continuous))
        .position(x: r.midX, y: r.midY)
    }
    private func picture(_ photo: CameraPhoto) -> some View {
        let r = cake.window
        let image = sharp(photo)
        return ZStack {
            if let shown = image { Image(decorative: shown, scale: 1).resizable().scaledToFit() }
            if photo.isVideo {
                #if os(iOS)
                if model.playing == photo.url {
                    CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                        .accessibilityIdentifier("camera-album-player")
                }
                #endif
                if model.playing != photo.url {
                    Image(systemName: "play.circle.fill").font(.system(size: 40)).foregroundStyle(.white.opacity(0.9))
                        .shadow(color: .black.opacity(0.5), radius: 4)
                }
            }
        }
        .frame(width: r.width, height: r.height)
        .offset(x: push)
        .contentShape(Rectangle())
        .gesture(DragGesture(minimumDistance: 8)
            .onChanged { push = $0.translation.width }
            .onEnded { value in
                let dx = value.translation.width
                withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                if abs(dx) > 60 { turn(dx < 0 ? 1 : -1) }
            })
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityElement(children: .contain)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : CameraShellSkin.cake.albumTitle)
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
    }

    /// The label stuck on the ribbon: which one it is of how many.
    private var ribbonLabel: some View {
        let count = model.photos.count
        let place: String = count == 0 ? "0" : "\(model.albumIndex + 1) / \(count)"
        return CakeLabelTag(text: place)
            .allowsHitTesting(false)
            .accessibilityElement()
            .accessibilityLabel(place)
            .accessibilityIdentifier("camera-deck-album-position")
            .deckPlaced(cake.label)
    }

    /// The cards pegged on the string round the one looked at (in the
    /// middle, larger, straight, in a coral edge); one touched is looked at.
    @ViewBuilder private var cards: some View {
        let photos = model.photos, at = model.albumIndex
        let slots = cake.cards, middle = cake.cardsMiddle
        let tilts: [Double] = cake.across ? [-0.05, 0, 0.04] : [-0.05, 0.04, 0, -0.03, 0.05]
        CakeStringArt(from: cake.string0, to: cake.string1, sag: cake.sag, clip: cake.opening).equatable()
        ForEach(slots.indices, id: \.self) { slot in
            let index = at - middle + slot
            if photos.indices.contains(index) {
                cardKey(photos[index], index: index, chosen: index == at, place: slots[slot], tilt: tilts[slot % tilts.count])
            }
        }
    }
    private func cardKey(_ photo: CameraPhoto, index: Int, chosen: Bool, place: CGRect, tilt: Double) -> some View {
        let number = String(localized: "第 \(index + 1) 张")
        let peg = UnitPoint(x: 0.5, y: place.height > 0 ? 8 / place.height : 0)
        return Button {
            if !chosen { model.chooseInAlbum(index, quiet: true) }
        } label: {
            CakeCard(image: thumbnails.images[photo.url], figures: "\(index + 1)", video: photo.isVideo, chosen: chosen)
                .rotationEffect(.radians(chosen ? 0 : tilt), anchor: peg)
        }
        .buttonStyle(CakeKeyStyle(travel: -2, sound: .cardFlip, scale: 0.5))
        .onAppear { thumbnails.request(photo.url) }
        .accessibilityLabel(number)
        .accessibilityValue(photo.isVideo ? String(localized: "录像") : String(localized: "照片"))
        .accessibilityAddTraits(chosen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-album-cell-\(index)")
        .deckKey(place)
    }

    /// The three cookies: ‹ the one before; ▶ (a video's length by it; the
    /// square while it plays), a picture's paler and saying why; › the one after.
    @ViewBuilder private var cookies: some View {
        if cake.cookies.count == 3 {
            let photos = model.photos, at = model.albumIndex
            let none = photos.isEmpty
            let empty = String(localized: "还没有照片")
            let earlier = String(localized: "上一张"), later = String(localized: "下一张")
            let hasBefore = !none && at > 0, hasAfter = at + 1 < photos.count
            let before: String = hasBefore ? String(localized: "第 \(at) 张") : ""
            let after: String = hasAfter ? String(localized: "第 \(at + 2) 张") : ""
            let firstWhy = none ? empty : String(localized: "已经是第一张")
            let lastWhy = none ? empty : String(localized: "已经是最后一张")
            let playing = model.playing != nil
            let playWord = playing ? String(localized: "停止") : String(localized: "播放")
            let state = video ? videoWord : String(localized: "照片")
            let why = none ? empty : String(localized: "照片不能播放；要在上面画，展开后用相册的「编辑」")
            let sign: ShellGlyph = playing ? .stop : .play
            Button { turn(-1) } label: { CakeCookie(glyph: .previous, figures: "", orange: false) }
                .buttonStyle(CakeKeyStyle(travel: 2, sound: .pageFlip, scale: 0.35))
                .accessibilityLabel(earlier)
                .accessibilityValue(before)
                .accessibilityIdentifier("camera-deck-album-previous")
                .deckDimmed(!hasBefore, why: firstWhy)
                .deckKey(cake.cookies[0])
            Button { if video { model.togglePlay() } else { model.say(why) } } label: {
                CakeCookie(glyph: sign, figures: video ? (length ?? "") : "", orange: true)
            }
            .buttonStyle(CakeKeyStyle(travel: 2, sound: .click, scale: 0.4))
            .accessibilityLabel(playWord)
            .accessibilityValue(state)
            .accessibilityIdentifier("camera-deck-album-play")
            .deckDimmed(!video, why: why)
            .deckKey(cake.cookies[1])
            Button { turn(1) } label: { CakeCookie(glyph: .next, figures: "", orange: false) }
                .buttonStyle(CakeKeyStyle(travel: 2, sound: .pageFlip, scale: 0.35))
                .accessibilityLabel(later)
                .accessibilityValue(after)
                .accessibilityIdentifier("camera-deck-album-next")
                .deckDimmed(!hasAfter, why: lastWhy)
                .deckKey(cake.cookies[2])
        }
    }

    /// The gift box opened on the floor (not a key): tissue paper, the two
    /// oldest pictures still standing in it, how many on its front.
    private var openGift: some View {
        let photos = model.photos
        let first = photos.last.flatMap { thumbnails.images[$0.url] }
        let second: CGImage? = photos.count > 1 ? thumbnails.images[photos[photos.count - 2].url] : nil
        return CakeOpenGift(first: first, second: second, count: photos.count)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
            .onAppear { for photo in photos.suffix(2) { thumbnails.request(photo.url) } }
            .deckPlaced(cake.openGift)
    }

    /// 回去拍照: the big chocolate plaque (a camera and its words piped on it).
    private var back: some View {
        Button { backToCamera() } label: { CakeBackPlaque() }
            .buttonStyle(CakeKeyStyle(travel: 2, sound: .click, scale: 0.5))
            .accessibilityLabel(String(localized: "回去拍照"))
            .accessibilityIdentifier("camera-deck-album-return")
            .deckDimmed(drawing, why: drawingWhy)
            .deckKey(cake.backPlaque)
    }

    /// The tag on its twine, only hanging there here.
    private var hangTag: some View {
        let key = cake.tagKey
        return CakeTag(tag: CakeLayout.local(cake.tag, in: key), turn: cake.tagTurn, knot: CakeLayout.local(cake.knot, in: key), word: cake.tagWord)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
            .deckPlaced(key)
    }

    /// 主菜单: the seal, as ever.
    private var home: some View {
        Button { model.leave() } label: { CakeSeal(radius: cake.sealRadius) }
            .buttonStyle(CakeKeyStyle(travel: 0, swing: -8, anchor: .center, sound: .rip, scale: 0.35))
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(cake.sealKey)
    }

    /// The big candle, lit: back to taking pictures too.
    private var candle: some View {
        CakeCandleKey(cake: cake, shots: 0, video: false, recording: false, seconds: 0, album: true, why: drawing ? drawingWhy : "") {
            backToCamera()
        }
        .accessibilityLabel(String(localized: "回去拍照"))
        .accessibilityIdentifier("camera-deck-album-close")
        .opacity(drawing ? 0.5 : 1)
        .deckKey(cake.candleKey)
    }
}

/// The label stuck on the ribbon, its words in the middle.
private struct CakeLabelTag: View {
    var text: String
    var body: some View {
        Text(verbatim: text).font(.system(size: 12, weight: .heavy, design: .rounded)).monospacedDigit()
            .foregroundStyle(CakePaint.ink)
            .lineLimit(1).fixedSize()
            .padding(.horizontal, 11)
            .frame(height: 22)
            .background(CakeLabelArt().equatable())
    }
}

/// The string the cards hang from, sagging between its ends (inside the box).
private struct CakeStringArt: View, Equatable {
    var from: CGPoint
    var to: CGPoint
    var sag: CGFloat
    var clip: CGRect
    var body: some View {
        Canvas { context, _ in
            guard to.x > from.x else { return }
            var g = context
            if clip.width > 0, clip.height > 0 { g.clip(to: Path(clip)) }
            var path = Path()
            path.move(to: from)
            var x = from.x + 4
            while x < to.x {
                let t = (x - from.x) / (to.x - from.x)
                path.addLine(to: CGPoint(x: x, y: from.y + (to.y - from.y) * t + sag * CGFloat(sin(Double.pi * Double(t)))))
                x += 4
            }
            path.addLine(to: to)
            g.stroke(path, with: .color(CakeArt.rgb(251, 243, 230)), lineWidth: 1.6)
            g.stroke(path, with: .color(CakeArt.rgb(150, 90, 60, 0.45)), lineWidth: 0.5)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The wooden peg clipping a card to the string.
private struct CakePegArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let whole = CGRect(origin: .zero, size: area)
            let wood = [CakeArt.stop(CakeArt.rgb(201, 154, 98), 0), CakeArt.stop(CakeArt.rgb(236, 201, 150), 0.5), CakeArt.stop(CakeArt.rgb(185, 136, 80), 1)]
            context.fill(CakeArt.rr(whole, 1.5), with: CakeArt.across(wood, 0, area.width))
            context.fill(Path(CGRect(x: 0, y: area.height * 0.47, width: area.width, height: 1)), with: .color(CakeArt.rgb(90, 60, 30, 0.6)))
        }
        .allowsHitTesting(false)
    }
}

/// A party photo card on its peg: a white border, the picture, its number
/// on the bottom margin (▶ by it for a video); the one looked at in a coral
/// edge. The card's top is 8 points down in its place (the peg over it).
private struct CakeCard: View {
    var image: CGImage?
    var figures: String
    var video: Bool
    var chosen: Bool
    var body: some View {
        GeometryReader { geo in
            let w = geo.size.width, h = max(24, geo.size.height - 11)
            let ink: Color = chosen ? CakeArt.rgb(194, 80, 28) : CakePaint.soft
            ZStack(alignment: .topLeading) {
                VStack(spacing: 0) {
                    shot
                        .frame(width: max(0, w - 8), height: max(0, h - 21))
                        .clipped()
                        .padding(.top, 4)
                    HStack(spacing: 2) {
                        if video { ShellGlyphView(glyph: .play, size: 8, ink: ink) }
                        Text(verbatim: figures).font(.system(size: 10.5, weight: .black, design: .rounded)).monospacedDigit()
                            .foregroundStyle(ink)
                            .lineLimit(1).minimumScaleFactor(0.6)
                    }
                    .frame(height: 17)
                }
                .frame(width: w, height: h, alignment: .top)
                .background(Rectangle().fill(CakeArt.rgb(255, 253, 248)).shadow(color: CakeArt.rgb(80, 34, 12, 0.35), radius: 3, x: 0, y: 2.5))
                .overlay {
                    if chosen { Rectangle().stroke(CakePaint.accent, lineWidth: 2.6).padding(-1.3) }
                }
                .offset(y: 8)
                CakePegArt().equatable()
                    .frame(width: 7, height: 15)
                    .position(x: w / 2, y: 6.5)
            }
            .frame(width: w, height: geo.size.height, alignment: .topLeading)
        }
    }
    @ViewBuilder private var shot: some View {
        if let image {
            Image(decorative: image, scale: 1).resizable().scaledToFill()
        } else {
            LinearGradient(colors: [CakeArt.rgb(240, 214, 190), CakeArt.rgb(214, 170, 138)], startPoint: .top, endPoint: .bottom)
        }
    }
}

/// An iced sugar cookie: its golden edge, the icing's face (pink, or orange
/// for ▶), a dotted line of white piping round it.
private struct CakeCookieArt: View, Equatable {
    var orange: Bool
    var body: some View {
        Canvas { context, area in
            let whole = CGRect(origin: .zero, size: area), h = area.height
            let edge = CakeArt.rr(whole, h / 2.4)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 40, 15, 0.35), radius: 4, x: 0, y: 2.5))
            lifted.fill(edge, with: .color(CakeArt.rgb(226, 173, 116)))
            context.fill(edge, with: CakeArt.vertical([CakeArt.stop(CakeArt.rgb(240, 196, 142), 0), CakeArt.stop(CakeArt.rgb(201, 138, 82), 1)], 0, h))
            let c: ShellTone = orange ? ShellTone(r: 0.988, g: 0.698, b: 0.431) : ShellTone(r: 0.980, g: 0.769, b: 0.824)
            let face = whole.insetBy(dx: 4, dy: 4)
            context.fill(CakeArt.rr(face, face.height / 2.4), with: CakeArt.vertical([CakeArt.stop(c.color(0.3), 0), CakeArt.stop(c.color(), 1)], 0, h))
            let piping = whole.insetBy(dx: 7, dy: 7)
            context.stroke(CakeArt.rr(piping, piping.height / 2.4), with: .color(Color.white.opacity(0.75)),
                           style: StrokeStyle(lineWidth: 1.4, lineCap: .round, dash: [0.1, 3.4]))
        }
    }
}

/// A cookie as a key's face: its glyph piped on it, figures by it at need.
private struct CakeCookie: View {
    var glyph: ShellGlyph
    var figures: String
    var orange: Bool
    var body: some View {
        ZStack {
            CakeCookieArt(orange: orange).equatable()
            HStack(spacing: 5) {
                ShellGlyphView(glyph: glyph, size: 18, ink: CakePaint.ink)
                if !figures.isEmpty {
                    Text(verbatim: figures).font(.system(size: 13, weight: .black, design: .rounded)).monospacedDigit()
                        .foregroundStyle(CakePaint.ink)
                        .lineLimit(1).minimumScaleFactor(0.7)
                }
            }
            .padding(.horizontal, 10)
        }
    }
}

/// 回去拍照's face: the chocolate plaque whole, piped round in white, a
