}

/// Tissue paper puffing out of the opened gift box.
private struct CakeTissueArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let w = area.width
            let shares: [CGFloat] = [0.2, 0.5, 0.8], turns: [Double] = [-0.32, 0.05, 0.36]
            let paper: [Color] = [Color.white.opacity(0.96), CakeArt.rgb(255, 216, 228, 0.96), Color.white.opacity(0.96)]
            for index in 0..<3 {
                var g = context
                g.translateBy(x: w * shares[index], y: 50)
                g.rotate(by: .radians(turns[index]))
                var puff = Path()
                puff.move(to: CGPoint(x: -20, y: 12))
                puff.addQuadCurve(to: CGPoint(x: -4, y: -24), control: CGPoint(x: -18, y: -16))
                puff.addQuadCurve(to: CGPoint(x: 6, y: -26), control: CGPoint(x: 2, y: -18))
                puff.addQuadCurve(to: CGPoint(x: 20, y: 12), control: CGPoint(x: 18, y: -16))
                puff.closeSubpath()
                g.fill(puff, with: .color(paper[index]))
                g.stroke(puff, with: .color(CakeArt.rgb(200, 150, 140, 0.55)), lineWidth: 0.8)
            }
        }
        .allowsHitTesting(false)
    }
}

/// The opened gift box's front: the dotted rose paper, the coral band down it.
private struct CakeOpenBoxArt: View, Equatable {
    var body: some View {
        Canvas { context, area in
            let w = area.width, h = area.height, c = CakePaint.gift
            let by: CGFloat = 52, bh = max(10, h - 54)
            let box = CGRect(x: 6, y: by, width: max(0, w - 12), height: bh)
            let shape = CakeArt.rr(box, 4)
            var lifted = context
            lifted.addFilter(.shadow(color: CakeArt.rgb(90, 36, 14, 0.35), radius: 5, x: 0, y: 2.5))
            lifted.fill(shape, with: .color(c.color()))
            context.fill(shape, with: CakeArt.across([CakeArt.stop(c.color(-0.12), 0), CakeArt.stop(c.color(0.1), 0.4), CakeArt.stop(c.color(-0.16), 1)], 0, w))
            var wrapping = context
            wrapping.clip(to: shape)
            var dots = Path()
            var row = 0
            var y = by + 6
            while y < by + bh {
                var x = 10 + CGFloat(row % 2) * 5
                while x < w {
                    dots.addEllipse(in: CGRect(x: x - 1.5, y: y - 1.5, width: 3, height: 3))
                    x += 10
                }
                y += 9
                row += 1
            }
            wrapping.fill(dots, with: .color(Color.white.opacity(0.7)))
            context.fill(Path(CGRect(x: w / 2 - 6, y: by, width: 12, height: bh)), with: CakeArt.across(CakeArt.satin, w / 2 - 6, w / 2 + 6))
        }
        .allowsHitTesting(false)
    }
}

/// The gift box opened (a part of the floor in 相册, not a key): tissue
/// puffing out of it, two cards still standing in it, two pictures on its
/// front and how many (drawn as the picture of it was, scaled to its place;
/// the figures left off where that would be too small to read).
private struct CakeOpenGift: View {
    var first: CGImage?
    var second: CGImage?
    var count: Int
    var body: some View {
        GeometryReader { geo in
            let s = min(1, min(geo.size.width / 132, geo.size.height / 118))
            ZStack(alignment: .topLeading) {
                CakeTissueArt().equatable()
                    .frame(width: 132, height: 70)
                card(first)
                    .rotationEffect(.radians(-0.2), anchor: .top)
                    .position(x: 132 * 0.34, y: 38)
                card(second)
                    .rotationEffect(.radians(0.16), anchor: .top)
                    .position(x: 132 * 0.62, y: 38)
                CakeOpenBoxArt().equatable()
                    .frame(width: 132, height: 118)
                HStack(spacing: 3) {
                    ShellGlyphView(glyph: .album, size: 12, ink: Color.white)
                    if s >= 0.7 {
                        Text(verbatim: "\(count)").font(.system(size: 11, weight: .black, design: .rounded)).monospacedDigit()
                            .foregroundStyle(Color.white)
                    }
                }
                .shadow(color: CakeArt.rgb(120, 30, 50, 0.6), radius: 2)
                .position(x: 66, y: 85)
            }
            .frame(width: 132, height: 118, alignment: .topLeading)
            .scaleEffect(s)
            .frame(width: geo.size.width, height: geo.size.height)
        }
    }
    private func card(_ image: CGImage?) -> some View {
        ZStack(alignment: .top) {
            Rectangle().fill(CakeArt.rgb(255, 253, 248)).shadow(color: CakeArt.rgb(80, 34, 12, 0.3), radius: 2)
            Group {
                if let image {
                    Image(decorative: image, scale: 1).resizable().scaledToFill()
                } else {
                    LinearGradient(colors: [CakeArt.rgb(240, 214, 190), CakeArt.rgb(214, 170, 138)], startPoint: .top, endPoint: .bottom)
                }
            }
            .frame(width: 24, height: 22)
            .clipped()
            .padding(.top, 3)
        }
        .frame(width: 30, height: 36)
    }
}

// MARK: - The cash register's back

/// The cash register's colours (mock/cr7.js): the putty-grey plastic, the
/// dark brushed metal of the cash drawer, what is printed on the body and on
/// the keys (the ink, softer, and the light ink on a dark key), the green of
/// the little display and of the zoom stop in use, the keys' own plastics
/// (the setting keys' five pastels, the cream number keys, the grey keys,
/// the charcoal keys, the red of 合计), the thermal paper and the card in the
/// drawer's label holder. Bright metal besides.
enum RegisterPaint {
    static let body = ShellTone(r: 0.839, g: 0.827, b: 0.796)
    static let drawer = ShellTone(r: 0.259, g: 0.271, b: 0.298)
    static let ink = Color(red: 0.137, green: 0.149, blue: 0.173)
    static let soft = Color(red: 0.137, green: 0.149, blue: 0.173).opacity(0.62)
    static let print = Color(red: 0.259, green: 0.243, blue: 0.212).opacity(0.78)
    static let light = Color(red: 0.953, green: 0.957, blue: 0.965)
    static let vfd = Color(red: 0.427, green: 1.0, blue: 0.8)
    static let lit = Color(red: 0.106, green: 0.541, blue: 0.416)
    static let flash = ShellTone(r: 0.953, g: 0.780, b: 0.345)
    static let timer = ShellTone(r: 0.525, g: 0.733, b: 0.894)
    static let date = ShellTone(r: 0.596, g: 0.792, b: 0.573)
    static let aspect = ShellTone(r: 0.933, g: 0.627, b: 0.565)
    static let level = ShellTone(r: 0.737, g: 0.667, b: 0.886)
    static let number = ShellTone(r: 0.965, g: 0.949, b: 0.906)
    static let grey = ShellTone(r: 0.808, g: 0.812, b: 0.796)
    static let dark = ShellTone(r: 0.298, g: 0.314, b: 0.349)
    static let red = ShellTone(r: 0.831, g: 0.227, b: 0.180)
    static let paper = Color(red: 0.969, green: 0.961, blue: 0.937)
    static let card = Color(red: 0.965, green: 0.953, blue: 0.918)
}

/// Where the cash register's parts are on the cover, upright (from a
/// ShellPlan) or across (from a ShellAcrossPlan): the same parts both ways,
/// each laid out for its hold (mock/cr7.js).
struct RegisterLayout: Equatable {
    var across = false
    var canvas = CGSize.zero
    var u: CGFloat = 1
    /// The display's housing (a raised block of dark plastic) and its glass.
    var housing = CGRect.zero
    var glass = CGRect.zero
    /// Held across: the band along the edge with the phone's own camera, and
    /// the grip where the Camera Control's overlay comes in.
    var band = CGRect.zero
    var grip = CGRect.zero
    /// The printer's mouth (its slot's top edge and how wide), where ZERO is
    /// printed on the body, the printer's lamp; where a slip rises out of the
    /// mouth (across from its left, as wide) and how high it may go.
    var slot = CGRect.zero
    var name = CGRect.zero
    var lamp = CGPoint.zero
    var rise = CGRect.zero
    /// The keyboard's deck and its keys: ‹ 镜头, the little green display and
    /// 镜头 ›; the five setting keys (闪光, 定时, 日期, 画幅, 水平仪); the four
    /// number keys of 变焦; 浓淡 + and −; 主菜单 and 机型; 内 / 外; the mode
    /// lock — its place, its middle and radius, its glyphs over it (upright)
    /// or beside it (across).
    var deck = CGRect.zero
    var lensBack = CGRect.zero
    var plate = CGRect.zero
    var lensOn = CGRect.zero
    var settings: [CGRect] = []
    var zooms: [CGRect] = []
    var toneUp = CGRect.zero
    var toneDown = CGRect.zero
    var home = CGRect.zero
    var bodies = CGRect.zero
    var flip = CGRect.zero
    var lock = CGRect.zero
    var lockCentre = CGPoint.zero
    var lockRadius: CGFloat = 24
    var lockBeside = false
    /// The cash drawer: its front, the part of it touched (相册); upright, the
    /// paper roll's window and the grip's ribs down the strip.
    var drawer = CGRect.zero
    var drawerKey = CGRect.zero
    var roll = CGRect.zero
    var ribs = CGRect.zero
    /// 合计 (拍照).
    var total = CGRect.zero
    /// 相册, the drawer pulled out: its tray, the room the slip looked at is
    /// shown in (under the clip), the walls between it and the ones beside
    /// it, the paper tag saying which one it is, the hint, the empty coin
    /// cups and how large, the drawer's front and its four keys (上一张,
    /// 下一张, 回去拍照, 主菜单).
    var tray = CGRect.zero
    var paper = CGRect.zero
    var walls: [CGFloat] = []
    var place = CGRect.zero
    var hint = CGRect.zero
    var cups: [CGPoint] = []
    var cupRadius: CGFloat = 28
    var front = CGRect.zero
    var albumKeys: [CGRect] = []
}

extension ShellPlan {
    /// The cash register's parts, upright (mock/cr7.js's points from the
    /// column's corner, scaled across with it; down from the display's foot
    /// and from the column's): the display (the picture) at the head; under
    /// it the printer's mouth with its tear bar, ZERO and the lamp; the
    /// keyboard's deck in four rows; the cash drawer (相册) at the column's
    /// foot, what height is left between the deck and the drawer. Down the
    /// strip: 内 / 外 under the camera, the mode lock, the paper roll's window
    /// and the grip where the Camera Control's overlay comes in, 合计 under
    /// the thumb.
    var register: RegisterLayout {
        var l = RegisterLayout()
        let c = back.column, strip = back.strip, k = keysTop
        let floor = back.keepOut.map(\.maxY).max() ?? top
        let sm = strip.midX
        let zone = back.overlay
        l.canvas = back.canvas
        l.u = u
        l.housing = surround
        l.glass = surround.insetBy(dx: 6, dy: 6)
        // The printer's mouth under the display; ZERO and the lamp by it.
        let slotY = surround.maxY + 29
        l.slot = CGRect(x: x(38), y: slotY, width: 200 * u, height: 9)
        l.name = CGRect(x: x(250), y: slotY - 12, width: 96 * u, height: 24)
        l.lamp = CGPoint(x: x(364), y: slotY)
        l.rise = CGRect(x: x(55), y: surround.minY + 6, width: 166 * u, height: max(0, slotY - surround.minY - 6))
        // The keyboard's deck: four rows of keys, five to a row.
        l.deck = CGRect(x: c.minX, y: k, width: c.width, height: 240)
        let kw = 66 * u, kh: CGFloat = 50, pitch = 74 * u
        func key(_ column: Int, _ row: Int, span: Int = 1) -> CGRect {
            CGRect(x: x(22) + CGFloat(column) * pitch, y: k + 8 + 58 * CGFloat(row), width: kw + CGFloat(span - 1) * pitch, height: kh)
        }
        l.lensBack = key(0, 0)
        l.plate = key(1, 0, span: 3)
        l.lensOn = key(4, 0)
        l.settings = (0..<5).map { key($0, 1) }
        l.zooms = (0..<4).map { key($0, 2) }
        l.toneUp = key(4, 2)
        l.home = key(0, 3, span: 2)
        l.bodies = key(2, 3, span: 2)
        l.toneDown = key(4, 3)
        // The cash drawer at the column's foot.
        let drawerTop = max(k + 246, c.maxY - 46)
        l.drawer = CGRect(x: c.minX, y: drawerTop, width: c.width, height: max(46, back.canvas.height - 4 - drawerTop))
        l.drawerKey = CGRect(x: c.minX, y: drawerTop, width: c.width, height: 46)
        // Down the strip: 内 / 外, the lock (its glyphs over it), the roll and
        // the grip under the overlay, 合计.
        l.flip = CGRect(x: sm - 26, y: max(floor + 8, top), width: 52, height: 52)
        let lockLow = (zone?.minY ?? back.canvas.height) - 30
        let lockY = max(l.flip.maxY + 56, min(l.flip.maxY + 78, lockLow))
        l.lockRadius = min(24, max(16, (strip.width - 16) / 2))
        l.lockCentre = CGPoint(x: sm + 1, y: lockY)
        l.lock = CGRect(x: sm - 29, y: lockY - 50, width: 60, height: 76)
        l.lockBeside = false
        if let zone, zone.height > 60 {
            l.roll = CGRect(x: strip.minX + 4, y: zone.minY + 2, width: max(0, strip.width - 8), height: min(92, zone.height * 0.4))
            l.ribs = CGRect(x: strip.minX + 4, y: l.roll.maxY + 12, width: max(0, strip.width - 8), height: max(0, zone.maxY - 8 - (l.roll.maxY + 12)))
        }
        let foot = c.maxY - 2
        let tw = min(64, strip.width - 2)
        let ty = max((zone?.maxY ?? 0) + 8, foot - 94)
        l.total = CGRect(x: sm - tw / 2, y: ty, width: tw, height: max(56, foot - ty))
        // 相册: the drawer pulled out, its front staying where it was.
        l.front = l.drawer
        let gap = max(6, 6 * u)
        let aw = (c.width - 12 - 3 * gap) / 4
        l.albumKeys = (0..<4).map { CGRect(x: c.minX + 6 + CGFloat($0) * (aw + gap), y: drawerTop, width: aw, height: 46) }
        l.tray = CGRect(x: c.minX, y: top - 2, width: c.width, height: max(0, drawerTop - 4 - (top - 2)))
        l.place = CGRect(x: c.midX - 88 * u, y: drawerTop - 122, width: 176 * u, height: 22)
        l.hint = CGRect(x: c.minX + 8, y: drawerTop - 94, width: c.width - 16, height: 18)
        l.cups = (0..<5).map { CGPoint(x: c.minX + c.width * (0.12 + 0.19 * CGFloat($0)), y: drawerTop - 38) }
        l.cupRadius = min(28, 30 * u)
        l.paper = CGRect(x: c.minX + 62 * u, y: top + 16, width: 250 * u, height: max(0, l.place.minY - 10 - (top + 16)))
        l.walls = [c.minX + 50 * u, c.maxX - 54 * u]
        return l
    }
}

extension ShellAcrossPlan {
    /// 合计 held across: a long red key at the far end of the band's shorter
    /// clear run (of the longer one where that is too short).
    var registerShutter: CGRect {
        let end = back.spare.width >= 116 ? back.spare : back.run
        let w = min(110, max(44, end.width - 8))
        return CGRect(x: end.maxX - w - 4, y: end.midY - 30, width: w, height: 60)
    }

    /// The cash register's parts with the cover held across (mock/cr7.js's
    /// points from the keys' corner): the display at the left and the
    /// printer's mouth under it; in the band ZERO, the grip where the Camera
    /// Control's overlay comes in and 合计; in the keys' column the keyboard's
    /// deck in five rows, the mode lock lying on it, and the cash drawer at
    /// its foot.
    var register: RegisterLayout {
        var l = RegisterLayout()
        let band = back.band, keys = back.keys, run = back.run
        l.across = true
        l.canvas = back.canvas
        l.u = 1
        l.band = band
        if let zone = back.overlay, zone.width > 40 {
            l.grip = CGRect(x: zone.minX + 10, y: band.minY + 13, width: max(0, zone.width - 18), height: max(0, band.height - 26))
        }
        l.total = registerShutter
        // ZERO in what 合计 leaves of the band's longer run.
        let shared = back.spare.width < 116
        let room: CGFloat = shared ? run.width - 124 : run.width
        if room >= 100 {
            let start: CGFloat = shared && l.total.midX < run.midX ? run.maxX - room + 8 : run.minX + 8
            l.name = CGRect(x: start, y: run.midY - 12, width: min(150, room - 16), height: 24)
        }
        // The display at the left, the printer's mouth under it.
        l.housing = surround
        l.glass = surround.insetBy(dx: 6, dy: 6)
        let slotY = surround.maxY + 26
        l.slot = CGRect(x: surround.minX + 56, y: slotY, width: min(220, max(80, surround.width - 200)), height: 9)
        l.lamp = CGPoint(x: l.slot.maxX + 40, y: slotY)
        l.rise = CGRect(x: surround.minX + 50, y: surround.minY + 6, width: 150, height: max(0, slotY - surround.minY - 6))
        // The keyboard's deck: five rows of four keys; the drawer at its foot.
        l.deck = keys.insetBy(dx: -7, dy: -7)
        let kw: CGFloat = 45.2, kh: CGFloat = 46, pitch: CGFloat = 51.6
        func at(_ column: Int, _ row: Int) -> CGRect { key(pitch * CGFloat(column), 54 * CGFloat(row), kw, kh) }
        l.lensBack = at(0, 0)
        l.plate = key(pitch, 0, pitch + kw, kh)
        l.lensOn = at(3, 0)
        l.settings = [at(0, 1), at(1, 1), at(2, 1), at(3, 1), at(0, 2)]
        l.flip = at(1, 2)
        l.toneDown = at(2, 2)
        l.toneUp = at(3, 2)
        l.zooms = (0..<4).map { at($0, 3) }
        l.home = at(0, 4)
        l.bodies = at(1, 4)
        l.lock = key(106, 216, 94, kh)
        l.lockCentre = CGPoint(x: keys.minX + 153, y: keys.minY + 239)
        l.lockRadius = 16
        l.lockBeside = true
        l.drawer = key(0, 272, 200, 84)
        l.drawerKey = l.drawer
        // 相册: the tray where the display was; the tag, the hint and the cups
        // in the column, the drawer's front under them with its four keys.
        l.tray = back.screen.insetBy(dx: 2, dy: 2)
        l.paper = CGRect(x: l.tray.minX + 62, y: l.tray.minY + 14, width: max(0, l.tray.width - 124), height: max(0, l.tray.height - 28))
        l.walls = [l.tray.minX + 50, l.tray.maxX - 54]
        l.place = key(10, 6, 180, 26)
        l.hint = key(4, 40, 192, 36)
        l.cups = [CGPoint(x: keys.minX + 40, y: keys.minY + 138), CGPoint(x: keys.minX + 100, y: keys.minY + 138), CGPoint(x: keys.minX + 160, y: keys.minY + 138)]
        l.cupRadius = 24
        l.front = key(-4, 196, 208, 160)
        l.albumKeys = [key(0, 202, 97, 46), key(103, 202, 97, 46), key(0, 254, 200, 46), key(0, 306, 200, 46)]
        return l
    }
}

extension CameraDeckFace {
    /// The cash register under its keys.
    func registerBackdrop(_ register: RegisterLayout) -> some View {
        RegisterBackdrop(layout: register, hinge: hinge, album: false).equatable()
    }

    /// The display's glass round the picture (round it in the shape chosen;
    /// nothing over the picture itself); and, while the camera would show
    /// what it has just taken, what is in front of it instead: the slip is
    /// printed on paper, under its coat, not shown on the display.
    func registerScreen(_ register: RegisterLayout) -> some View {
        ZStack(alignment: .topLeading) {
            RegisterGlassRim(glass: register.glass, hole: layout.picture, radius: register.across ? 16 : 20).equatable()
            RegisterLiveCover(model: model, screen: model.screen, hole: layout.picture)
        }
        .frame(width: layout.canvas.width, height: layout.canvas.height, alignment: .topLeading)
        .allowsHitTesting(false)
    }

    /// The cash register, upright or across (the same keys, each where its
    /// hold has it): the printer (a slip rises out of it after each picture,
    /// its photo under a silver coat); ‹ 镜头 and 镜头 › round the little green
    /// display; the five setting keys; the number keys of 变焦; 浓淡 + and −;
    /// 主菜单 and 机型; 内 / 外; the mode lock (拍照 / 录像); the cash drawer
    /// (相册); 合计 (拍照, 叮). While a video is taken the keys make no sound
    /// of their own.
    @ViewBuilder func registerFace(_ register: RegisterLayout) -> some View {
        let quiet = model.recording
        RegisterPrinter(model: model, slips: RegisterSlips.shared, layout: register)
        registerLensKeys(register, quiet: quiet)
        registerSettings(register, quiet: quiet)
        registerZoom(register, quiet: quiet)
        registerTone(register, quiet: quiet)
        registerMenus(register, quiet: quiet)
        registerFlip(register, quiet: quiet)
        registerLock(register, quiet: quiet)
        registerDrawer(register, quiet: quiet)
        registerTotal(register)
    }

    /// 镜头: the little green display (the lens in use, which of how many)
    /// between its two keys (‹ and › by the filters' circles). They step back
    /// while the system's Camera Control menu is up.
    @ViewBuilder private func registerLensKeys(_ register: RegisterLayout, quiet: Bool) -> some View {
        let hidden = systemControlsUp
        let lenses = CameraLens.allCases
        let at = lenses.firstIndex(of: model.lens) ?? 0
        let count = lenses.count + model.pinnedBodies.count
        let lensWord = String(localized: "镜头")
        let size: CGFloat = register.across ? 16 : 18
        let style = RegisterKeyStyle(tone: RegisterPaint.grey, sound: quiet ? nil : .keyRubber)
        RegisterPlate(glyph: .lens(model.lens), name: model.lens.title, place: "\(at + 1)/\(count)", narrow: register.across)
            .deckPlaced(register.plate)
            .opacity(hidden ? 0 : 1)
        Button { registerStepLens(-1) } label: { ShellGlyphView(glyph: .lensPrevious, size: size, ink: RegisterPaint.ink) }
            .buttonStyle(style)
            .accessibilityLabel(lensWord + " ‹")
            .accessibilityValue(model.lens.title)
            .accessibilityIdentifier("camera-deck-lens-previous")
            .deckKey(register.lensBack)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
        Button { registerStepLens(1) } label: { ShellGlyphView(glyph: .lensNext, size: size, ink: RegisterPaint.ink) }
            .buttonStyle(style)
            .accessibilityLabel(lensWord + " ›")
            .accessibilityValue(model.lens.title)
            .accessibilityIdentifier("camera-deck-lens-next")
            .deckKey(register.lensOn)
            .opacity(hidden ? 0 : 1)
            .allowsHitTesting(!hidden)
    }
    /// One lens on or back (with a video, only those that take one); past
    /// the last of them the first 机型 pinned among them (as a pinned chip
    /// does it: the body changes, and with it the back).
    private func registerStepLens(_ delta: Int) {
        let lenses = CameraLens.allCases
        guard let at = lenses.firstIndex(of: model.lens) else { return }
        var next = at + delta
        while lenses.indices.contains(next), model.mode == .video, !lenses[next].records { next += delta }
        if lenses.indices.contains(next) {
            model.choose(lenses[next])
        } else if delta > 0, let pinned = model.pinnedBodies.first(where: { $0 != model.body }) {
            model.tapPinned(pinned)
        } else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
        }
    }

    /// The five setting keys, each in its own pastel, its glyph drawn as
    /// what it sets stands: 闪光, 定时, 日期, 画幅 (its figures under its
    /// frame), 水平仪.
    @ViewBuilder private func registerSettings(_ register: RegisterLayout, quiet: Bool) -> some View {
        let rects = register.settings
        if rects.count == 5 {
            let shooting = model.shooting
            let onWord = String(localized: "开"), offWord = String(localized: "关")
            let video = model.mode == .video
            let timerWhy = String(localized: "录像时不用定时")
            let timed = model.countdown.map { String(localized: "\($0) 秒") } ?? model.timer.title
            let dated = shooting.dateStamp ? onWord : offWord
            let levelled = model.leveler ? onWord : offWord
            let size: CGFloat = register.across ? 17 : 19
            let sound: ConsoleSound? = quiet ? nil : .keyRubber
            let ink = RegisterPaint.ink
            Button { model.cycleFlash() } label: { ShellGlyphView(glyph: .flash(shooting.flash), size: size, ink: ink) }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.flash, sound: sound))
                .accessibilityLabel(String(localized: "闪光"))
                .accessibilityValue(shooting.flash.title)
                .accessibilityIdentifier("camera-deck-flash")
                .deckKey(rects[0])
            Button { if video { model.say(timerWhy) } else { model.cycleTimer() } } label: { ShellGlyphView(glyph: .timer(model.timer), size: size, ink: ink) }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.timer, sound: sound))
                .accessibilityLabel(String(localized: "定时"))
                .accessibilityValue(timed)
                .accessibilityIdentifier("camera-deck-timer")
                .deckDimmed(video, why: timerWhy)
                .deckKey(rects[1])
            Button { model.toggleDateStamp() } label: { ShellGlyphView(glyph: .date(shooting.dateStamp), size: size, ink: ink) }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.date, sound: sound))
                .accessibilityLabel(String(localized: "日期"))
                .accessibilityValue(dated)
                .accessibilityIdentifier("camera-deck-date")
                .deckKey(rects[2])
            Button { withAnimation(.easeOut(duration: 0.18)) { model.cycleAspect() } } label: {
                ShellGlyphView(glyph: .shape(model.shape), size: size - 2, ink: ink, stacked: true)
            }
            .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.aspect, sound: sound))
            .accessibilityLabel(CameraShellSkin.register.shapeTitle)
            .accessibilityValue(model.shape.title)
            .accessibilityIdentifier("camera-deck-aspect")
            .deckDimmed(!model.canShape, why: String(localized: "这个模式或机型只拍 4:3"))
            .deckKey(rects[3])
            Button { model.toggleLeveler() } label: { ShellGlyphView(glyph: .level(model.leveler), size: size, ink: ink) }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.level, sound: sound))
                .accessibilityLabel(String(localized: "水平仪"))
                .accessibilityValue(levelled)
                .accessibilityAddTraits(model.leveler ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier("camera-deck-leveler")
                .deckKey(rects[4])
        }
    }

    /// 变焦: four cream number keys (.5×, 1×, 2×, 4×); the one in use stays
    /// down, as an old till's key locks down, and comes up when another goes
    /// down. .5× waits on a camera without an ultra wide. They step back
    /// while the system's Camera Control menu is up.
    @ViewBuilder private func registerZoom(_ register: RegisterLayout, quiet: Bool) -> some View {
        let rects = register.zooms
        if rects.count == 4 {
            let hidden = systemControlsUp
            let stops: [Double] = [0.5, 1, 2, 4]
            let have = model.zoomStops
            let chosen = have.last { $0 <= model.zoom + 0.05 } ?? have.first ?? 1
            let wideWhy = String(localized: "这边的相机没有超广角")
            let figuresSize: CGFloat = register.across ? 15 : 19
            let markSize: CGFloat = register.across ? 9 : 11
            ForEach(0..<4, id: \.self) { index in
                let z = stops[index]
                let on = z == chosen
                let figures = z < 1 ? ".5×" : "\(Int(z))×"
                let spoken: LocalizedStringKey = z < 1 ? "超广角 0.5 倍" : "放大 \(Int(z)) 倍"
                Button { model.setZoom(z, sound: false) } label: {
                    VStack(spacing: 0) {
                        Text(verbatim: figures).font(.system(size: figuresSize, weight: .black, design: .rounded)).monospacedDigit()
                            .foregroundStyle(RegisterPaint.ink)
                            .lineLimit(1).minimumScaleFactor(0.6)
                        ShellGlyphView(glyph: .zoom, size: markSize, ink: RegisterPaint.soft)
                    }
                }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.number, latched: on, sound: quiet ? nil : .click))
                .accessibilityLabel(spoken)
                .accessibilityValue(on ? Self.zoomText(model.zoom) : "")
                .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
                .accessibilityIdentifier(z < 1 ? "camera-deck-zoom-key-05" : "camera-deck-zoom-key-\(Int(z))")
                .deckDimmed(!have.contains(z), why: wideWhy)
                .deckKey(rects[index])
                .opacity(hidden ? 0 : 1)
                .allowsHitTesting(!hidden)
            }
        }
    }

    /// 浓淡 + and − (a thermal printer's own 印字浓淡): the half-dark circle
    /// and its sign, the step under it as a row of cells (原生: a dash).
    @ViewBuilder private func registerTone(_ register: RegisterLayout, quiet: Bool) -> some View {
        let shown = model.shownBody
        let step = model.strengthStep(of: shown)
        let share: String = shown == .native ? "—" : CameraBodyStrength.title(step)
        let lit = step - CameraBodyStrength.range.lowerBound + 1
        let cells: ShellGlyph? = shown == .native ? nil : ShellGlyph.tone(step: lit, of: CameraBodyStrength.values.count)
        let toneWord = String(localized: "浓淡")
        let size: CGFloat = register.across ? 15 : 17
        let style = RegisterKeyStyle(tone: RegisterPaint.grey, sound: quiet ? nil : .keyRubber)
        Button { model.stepBodyStrength(1) } label: { RegisterToneLabel(glyph: .toneUp, cells: cells, size: size) }
            .buttonStyle(style)
            .accessibilityLabel(toneWord + " +")
            .accessibilityValue(share)
            .accessibilityIdentifier("camera-deck-strength-plus")
            .deckKey(register.toneUp)
        Button { model.stepBodyStrength(-1) } label: { RegisterToneLabel(glyph: .toneDown, cells: cells, size: size) }
            .buttonStyle(style)
            .accessibilityLabel(toneWord + " −")
            .accessibilityValue(share)
            .accessibilityIdentifier("camera-deck-strength-minus")
            .deckKey(register.toneDown)
    }

    /// 主菜单 (a house) and 机型 (two cameras traded), the two charcoal keys.
    @ViewBuilder private func registerMenus(_ register: RegisterLayout, quiet: Bool) -> some View {
        let style = RegisterKeyStyle(tone: RegisterPaint.dark, sound: quiet ? nil : .keyRubber)
        Button { model.leave() } label: { ShellGlyphView(glyph: .home, size: register.across ? 18 : 21, ink: RegisterPaint.light) }
            .buttonStyle(style)
            .accessibilityLabel(String(localized: "camera.home.pill"))
            .accessibilityIdentifier("camera-deck-home")
            .deckKey(register.home)
        Button { if model.bodiesOpen { model.closeBodies() } else { model.openBodies() } } label: {
            ShellGlyphView(glyph: .changeBody, size: register.across ? 22 : 26, ink: RegisterPaint.light)
        }
        .buttonStyle(style)
        .accessibilityLabel(String(localized: "切换机型"))
        .accessibilityValue(model.body.title)
        .accessibilityAddTraits(model.bodiesOpen ? [.isButton, .isSelected] : .isButton)
        .accessibilityIdentifier("camera-deck-bodies")
        .deckKey(register.bodies)
    }

    /// 内 / 外: a grey key, a camera with its two arrows turning (合体
    /// changes the camera itself).
    private func registerFlip(_ register: RegisterLayout, quiet: Bool) -> some View {
        Button { model.switchSide() } label: { ShellGlyphView(glyph: .flip, size: register.across ? 17 : 20, ink: RegisterPaint.ink) }
            .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.grey, sound: quiet ? nil : .keyRubber))
            .accessibilityLabel(String(localized: "切换内侧、外侧相机"))
            .accessibilityValue(model.side.short)
            .accessibilityIdentifier("camera-deck-switch")
            .deckDimmed(model.lens == .merge, why: String(localized: "合体时相机会自己换：先外侧，再内侧"))
            .deckKey(register.flip)
    }

    /// 拍照 / 录像: the till's mode lock, its key turned to a camera or to a
    /// video camera (the one it points at filled, the other paler).
    private func registerLock(_ register: RegisterLayout, quiet: Bool) -> some View {
        let video = model.mode == .video
        let r = register.lock
        let centre = CGPoint(x: register.lockCentre.x - r.minX, y: register.lockCentre.y - r.minY)
        let photoWord = String(localized: "拍照"), videoWord = String(localized: "录像")
        return Button { model.setMode(video ? .photo : .video) } label: {
            RegisterLockView(video: video, centre: centre, radius: register.lockRadius, beside: register.lockBeside, onDeck: register.across)
        }
        .buttonStyle(RegisterTurnStyle(sound: quiet ? nil : .keyRatchet))
        .accessibilityLabel(photoWord + " / " + videoWord)
        .accessibilityValue(video ? videoWord : photoWord)
        .accessibilityIdentifier("camera-deck-mode")
        .deckKey(r)
    }

    /// 相册: the cash drawer; the card in its label holder shows the album's
    /// glyph and how many there are.
    private func registerDrawer(_ register: RegisterLayout, quiet: Bool) -> some View {
        let count = model.photos.count
        let key = register.drawerKey
        let holder = RegisterArt.holder(in: register.drawer, across: register.across).offsetBy(dx: -key.minX, dy: -key.minY)
        return Button { model.openAlbum() } label: { RegisterDrawerCard(count: count, holder: holder) }
            .buttonStyle(RegisterDrawerStyle(sound: quiet ? nil : .tinLid))
            .accessibilityLabel(CameraShellSkin.register.albumTitle)
            .accessibilityValue(String(localized: "\(count) 张"))
            .accessibilityIdentifier("camera-deck-album")
            .deckKey(key)
    }

    /// 合计: the shutter, the tall red key with the longest travel (a camera
    /// on it; a red dot's ring for a video, the square and the time while one
    /// is taken). Its thud as it goes down; then the body's own 叮.
    private func registerTotal(_ register: RegisterLayout) -> some View {
        let ready = model.canShoot || model.recording
        return Button { model.shutter() } label: {
            RegisterTotalLabel(video: model.mode == .video, recording: model.recording, seconds: model.recordedSeconds, timer: model.timer, across: register.across)
                .opacity(ready ? 1 : 0.45)
        }
        .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.red, radius: 9, depth: 10, sound: .keyRubber, scale: 0.9, haptic: .faceButton))
        .accessibilityLabel(model.mode == .video ? (model.recording ? "停止录像" : "开始录像") : "拍照")
        .accessibilityValue(model.canShoot ? (model.mode == .video ? "可以录" : "可以拍") : "等一下")
        .accessibilityIdentifier("camera-deck-shutter")
        .deckKey(register.total)
    }

    /// The cash register's 相册 (小票夹), upright and across.
    @ViewBuilder func registerAlbum(_ register: RegisterLayout) -> some View {
        RegisterAlbumView(model: model, thumbnails: thumbnails, slips: RegisterSlips.shared, register: register, hinge: hinge)
            .frame(width: layout.canvas.width, height: layout.canvas.height)
        if showsHardware { CoverHardwareMarks(cameras: layout.keepOut, control: control, canvas: layout.canvas) }
    }
}

/// The cash register's drawing, part for part (mock/cr7.js): the plastic
/// with its fine grain and its light from the upper left, the display's
/// housing and glass, the printer's mouth with its tear bar, ZERO printed on
/// the body, the keyboard's sunk deck, the paper roll's window and the grip's
/// ribs, the drawer's brushed metal with its label holder, its finger pull
/// and its lock; in 相册 the drawer's tray, the walls between the slips and
/// the empty coin cups. No glare, no streak of light over anything.
private enum RegisterArt {
    static func rgb(_ r: Double, _ g: Double, _ b: Double) -> Color { Color(red: r / 255, green: g / 255, blue: b / 255) }
    /// Bright metal (the lock's bezel, the clip, the label holder).
    static let silver = Gradient(stops: [Gradient.Stop(color: rgb(251, 252, 253), location: 0), Gradient.Stop(color: rgb(170, 176, 184), location: 0.22),
                                         Gradient.Stop(color: rgb(240, 242, 244), location: 0.46), Gradient.Stop(color: rgb(135, 141, 150), location: 0.74),
                                         Gradient.Stop(color: rgb(217, 220, 224), location: 1)])

    /// The drawer's label holder (the card in it is the drawer key's).
    static func holder(in drawer: CGRect, across: Bool) -> CGRect {
        let w: CGFloat = across ? 118 : min(150, drawer.width * 0.42)
        let h: CGFloat = across ? 36 : 34
        let cx: CGFloat = across ? drawer.midX - 8 : drawer.midX
        return CGRect(x: cx - w / 2, y: drawer.minY + (across ? 16 : 6), width: w, height: h)
    }

    /// Fine specks, a little lighter and a little darker, the same each time.
    static func speckle(_ g: GraphicsContext, _ r: CGRect, count: Int, alpha: Double, seed: UInt32) {
        var state = seed
        func next() -> CGFloat {
            state = state &* 1_664_525 &+ 1_013_904_223
            return CGFloat((state >> 8) & 0xFFFF) / 65535
        }
        var light = Path(), dark = Path()
        for _ in 0..<max(0, count) {
            let at = CGRect(x: r.minX + next() * r.width, y: r.minY + next() * r.height, width: 1, height: 1)
            if next() < 0.5 { light.addRect(at) } else { dark.addRect(at) }
        }
        g.fill(light, with: .color(Color.white.opacity(alpha)))
        g.fill(dark, with: .color(Color.black.opacity(alpha)))
    }

    /// The putty-grey plastic, the hinge's side in shade.
    static func body(_ g: GraphicsContext, _ size: CGSize, hinge: CGRect) {
        let whole = CGRect(origin: .zero, size: size)
        let tone = RegisterPaint.body
        g.fill(Path(whole), with: .linearGradient(Gradient(colors: [tone.color(0.2), tone.color(0), tone.color(-0.16)]),
                                                  startPoint: .zero, endPoint: CGPoint(x: size.width, y: size.height)))
        speckle(g, whole, count: Int(size.width * size.height / 30), alpha: 0.05, seed: 0x5EED_C0DE)
        let reach = max(size.width, size.height) * 0.85
        g.fill(Path(whole), with: .radialGradient(Gradient(colors: [Color.white.opacity(0.22), Color.white.opacity(0.03), Color.black.opacity(0.07)]),
                                                  center: CGPoint(x: size.width * 0.25, y: size.height * 0.1), startRadius: 10, endRadius: reach))
        guard hinge.width > 0, hinge.height > 0 else { return }
        let shade = Gradient(colors: [Color.black.opacity(0.45), Color.black.opacity(0)])
        if hinge.width < hinge.height {
            let deep = CGRect(x: hinge.minX, y: hinge.minY, width: hinge.width + 2, height: hinge.height)
            g.fill(Path(deep), with: .linearGradient(shade, startPoint: CGPoint(x: deep.minX, y: 0), endPoint: CGPoint(x: deep.maxX, y: 0)))
        } else {
            let upper = hinge.midY < size.height / 2
            let deep = CGRect(x: hinge.minX, y: upper ? hinge.minY : hinge.minY - 2, width: hinge.width, height: hinge.height + 2)
            g.fill(Path(deep), with: .linearGradient(shade, startPoint: CGPoint(x: 0, y: upper ? deep.minY : deep.maxY),
                                                     endPoint: CGPoint(x: 0, y: upper ? deep.maxY : deep.minY)))
        }
    }

    /// The display's housing, a raised block of dark plastic, and its glass.
    static func housing(_ g: GraphicsContext, _ l: RegisterLayout) {
        let r = l.housing
        guard r.width > 0, r.height > 0 else { return }
        let corner: CGFloat = l.across ? 22 : 26
        g.fill(Path(roundedRect: r.insetBy(dx: -1.5, dy: -1.5).offsetBy(dx: 0, dy: 3), cornerRadius: corner + 1.5, style: .continuous),
               with: .color(Color.black.opacity(0.22)))
        let block = Gradient(stops: [Gradient.Stop(color: rgb(60, 62, 68), location: 0), Gradient.Stop(color: rgb(43, 45, 50), location: 0.1),
                                     Gradient.Stop(color: rgb(24, 25, 28), location: 1)])
        g.fill(Path(roundedRect: r, cornerRadius: corner, style: .continuous), with: .linearGradient(block, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        g.stroke(Path(roundedRect: r.insetBy(dx: 0.8, dy: 0.8), cornerRadius: corner - 0.8, style: .continuous), with: .color(Color.white.opacity(0.16)), lineWidth: 1)
        let glass = Path(roundedRect: l.glass, cornerRadius: l.across ? 16 : 20, style: .continuous)
        g.fill(glass, with: .color(rgb(6, 7, 8)))
        g.stroke(glass, with: .color(Color.black.opacity(0.9)), lineWidth: 1.2)
    }

    /// The printer's mouth: its recess, the toothed steel tear bar over the
    /// dark slot (the paper and the slot's near lip are the printer's own).
    static func mouth(_ g: GraphicsContext, _ l: RegisterLayout) {
        let s = l.slot
        guard s.width > 0 else { return }
        let x = s.minX, y = s.minY, w = s.width
        let recess = Path(roundedRect: CGRect(x: x - 7, y: y - 15, width: w + 14, height: 29), cornerRadius: 8, style: .continuous)
        g.fill(recess, with: .linearGradient(Gradient(colors: [Color.black.opacity(0.2), Color.black.opacity(0.06)]),
                                             startPoint: CGPoint(x: 0, y: y - 15), endPoint: CGPoint(x: 0, y: y + 14)))
        g.stroke(recess, with: .color(Color.white.opacity(0.5)), lineWidth: 1)
        let bar = y - 10
        var teeth = Path()
        teeth.move(to: CGPoint(x: x, y: y + 1))
        teeth.addLine(to: CGPoint(x: x, y: bar + 3.4))
        var tx = x, index = 0
        while tx <= x + w + 0.01 {
            teeth.addLine(to: CGPoint(x: min(tx, x + w), y: bar + (index % 2 == 1 ? 3.4 : 0)))
            tx += 2.8
            index += 1
        }
        teeth.addLine(to: CGPoint(x: x + w, y: y + 1))
        teeth.closeSubpath()
        let steel = Gradient(stops: [Gradient.Stop(color: rgb(244, 245, 247), location: 0), Gradient.Stop(color: rgb(163, 168, 176), location: 0.45),
                                     Gradient.Stop(color: rgb(109, 114, 122), location: 1)])
        g.fill(teeth, with: .linearGradient(steel, startPoint: CGPoint(x: 0, y: bar), endPoint: CGPoint(x: 0, y: y)))
        g.fill(Path(roundedRect: CGRect(x: x - 1, y: y, width: w + 2, height: 9), cornerRadius: 4.5, style: .continuous), with: .color(rgb(5, 5, 6)))
    }

    /// ZERO on the body, pressed into the plastic.
    static func name(_ g: GraphicsContext, _ r: CGRect) {
        guard r.width > 0 else { return }
        let at = CGPoint(x: r.midX, y: r.midY)
        g.draw(Text(verbatim: "ZERO").font(.system(size: 15, weight: .black, design: .rounded)).tracking(6).foregroundColor(Color.white.opacity(0.55)),
               at: CGPoint(x: at.x, y: at.y + 0.8))
        g.draw(Text(verbatim: "ZERO").font(.system(size: 15, weight: .black, design: .rounded)).tracking(6).foregroundColor(RegisterPaint.print), at: at)
    }

    /// The keyboard's deck: dark, sunk into the body, a light edge round it.
    static func deck(_ g: GraphicsContext, _ r: CGRect) {
        guard r.width > 0, r.height > 0 else { return }
        g.fill(Path(roundedRect: r.insetBy(dx: -1.6, dy: -1.6), cornerRadius: 13.6, style: .continuous), with: .color(Color.white.opacity(0.45)))
        let shape = Path(roundedRect: r, cornerRadius: 12, style: .continuous)
        let sunk = Gradient(stops: [Gradient.Stop(color: rgb(42, 45, 51), location: 0), Gradient.Stop(color: rgb(58, 62, 70), location: 0.06),
                                    Gradient.Stop(color: rgb(48, 51, 58), location: 1)])
        g.fill(shape, with: .linearGradient(sunk, startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        var inner = g
        inner.clip(to: shape)
        speckle(inner, r, count: Int(r.width * r.height / 14), alpha: 0.05, seed: 0xDEC0_0001)
        inner.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 10)),
                   with: .linearGradient(Gradient(colors: [Color.black.opacity(0.45), Color.black.opacity(0)]), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.minY + 10)))
        g.stroke(shape, with: .color(Color.black.opacity(0.6)), lineWidth: 1)
    }

    /// Down the strip (upright): the paper roll seen end-on through a smoked
    /// window, and the grip's ribs, both where the Camera Control's overlay
    /// comes in (nothing to press there).
    static func strip(_ g: GraphicsContext, _ l: RegisterLayout) {
        let roll = l.roll
        if roll.width > 10, roll.height > 20 {
            g.fill(Path(roundedRect: roll.insetBy(dx: -1.5, dy: -1.5).offsetBy(dx: 0, dy: 0.5), cornerRadius: 10, style: .continuous), with: .color(Color.white.opacity(0.4)))
            let window = Path(roundedRect: roll, cornerRadius: 9, style: .continuous)
            g.fill(window, with: .color(rgb(23, 24, 28)))
            var inner = g
            inner.clip(to: window)
            let c = CGPoint(x: roll.midX, y: roll.minY + roll.height * 0.6)
            let radius = min(roll.width, roll.height) * 0.43
            var feed = Path()
            feed.move(to: CGPoint(x: c.x - radius + 1, y: c.y - 4))
            feed.addLine(to: CGPoint(x: roll.minX - 2, y: roll.minY + 10))
            feed.addLine(to: CGPoint(x: roll.minX - 2, y: roll.minY + 15))
            feed.addLine(to: CGPoint(x: c.x - radius + 2, y: c.y + 2))
            feed.closeSubpath()
            inner.fill(feed, with: .color(rgb(240, 238, 230).opacity(0.85)))
            let disc = CGRect(x: c.x - radius, y: c.y - radius, width: 2 * radius, height: 2 * radius)
            inner.fill(Path(ellipseIn: disc), with: .radialGradient(Gradient(colors: [rgb(251, 250, 245), rgb(214, 211, 200)]),
                                                                  center: CGPoint(x: c.x - radius * 0.3, y: c.y - radius * 0.3), startRadius: 2, endRadius: radius * 1.2))
            var ring = radius - 2
            while ring > radius * 0.36 {
                inner.stroke(Path(ellipseIn: CGRect(x: c.x - ring, y: c.y - ring, width: 2 * ring, height: 2 * ring)), with: .color(Color.black.opacity(0.07)), lineWidth: 0.6)
                ring -= 2.1
            }
            inner.fill(Path(ellipseIn: disc.insetBy(dx: radius * 0.68, dy: radius * 0.68)), with: .color(rgb(156, 138, 108)))
            inner.fill(Path(ellipseIn: disc.insetBy(dx: radius * 0.81, dy: radius * 0.81)), with: .color(rgb(42, 37, 32)))
            inner.fill(Path(roll), with: .color(rgb(28, 24, 40).opacity(0.42)))
            g.stroke(Path(roundedRect: roll.insetBy(dx: 0.6, dy: 0.6), cornerRadius: 8.5, style: .continuous), with: .color(Color.white.opacity(0.18)), lineWidth: 1)
        }
        ribs(g, l.ribs, across: false)
    }

    /// The grip's ribs: across it upright, up and down it held across.
    static func ribs(_ g: GraphicsContext, _ r: CGRect, across: Bool) {
        guard r.width > 4, r.height > 4 else { return }
        var dark = Path(), light = Path()
        if across {
            var x = r.minX
            while x < r.maxX - 2 {
                dark.addRoundedRect(in: CGRect(x: x, y: r.minY, width: 2.4, height: r.height), cornerSize: CGSize(width: 1.2, height: 1.2))
                light.addRoundedRect(in: CGRect(x: x + 2.4, y: r.minY, width: 1.4, height: r.height), cornerSize: CGSize(width: 0.7, height: 0.7))
                x += 8
            }
        } else {
            var y = r.minY
            while y < r.maxY - 2 {
                dark.addRoundedRect(in: CGRect(x: r.minX, y: y, width: r.width, height: 2.4), cornerSize: CGSize(width: 1.2, height: 1.2))
                light.addRoundedRect(in: CGRect(x: r.minX, y: y + 2.4, width: r.width, height: 1.4), cornerSize: CGSize(width: 0.7, height: 0.7))
                y += 8
            }
        }
        g.fill(dark, with: .color(Color.black.opacity(0.17)))
        g.fill(light, with: .color(Color.white.opacity(0.55)))
    }

    /// A plate's outline with its own corners above (`high`) and below (`low`).
    static func front(_ r: CGRect, high: CGFloat, low: CGFloat) -> Path {
        let a = min(high, r.width / 2, r.height / 2), b = min(low, r.width / 2, r.height / 2)
        var p = Path()
        p.move(to: CGPoint(x: r.minX + a, y: r.minY))
        p.addLine(to: CGPoint(x: r.maxX - a, y: r.minY))
        p.addQuadCurve(to: CGPoint(x: r.maxX, y: r.minY + a), control: CGPoint(x: r.maxX, y: r.minY))
        p.addLine(to: CGPoint(x: r.maxX, y: r.maxY - b))
        p.addQuadCurve(to: CGPoint(x: r.maxX - b, y: r.maxY), control: CGPoint(x: r.maxX, y: r.maxY))
        p.addLine(to: CGPoint(x: r.minX + b, y: r.maxY))
        p.addQuadCurve(to: CGPoint(x: r.minX, y: r.maxY - b), control: CGPoint(x: r.minX, y: r.maxY))
        p.addLine(to: CGPoint(x: r.minX, y: r.minY + a))
        p.addQuadCurve(to: CGPoint(x: r.minX + a, y: r.minY), control: CGPoint(x: r.minX, y: r.minY))
        p.closeSubpath()
        return p
    }

    /// The cash drawer's front: dark brushed metal; outside 相册 the label
    /// holder, the finger pull (upright) and the drawer's lock.
    static func drawer(_ g: GraphicsContext, _ r: CGRect, across: Bool, album: Bool) {
        guard r.width > 0, r.height > 0 else { return }
        let low: CGFloat = across ? 12 : 30
        g.fill(front(r.insetBy(dx: -1.5, dy: -1.5), high: 7.5, low: low + 1.5), with: .color(Color.black.opacity(0.5)))
        let shape = front(r, high: 6, low: low)
        let tone = RegisterPaint.drawer
        g.fill(shape, with: .linearGradient(Gradient(colors: [tone.color(0.16), tone.color(0), tone.color(-0.25)]), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        var inner = g
        inner.clip(to: shape)
        var state: UInt32 = 0xB1A5_7ED0
        var light = Path(), dark = Path()
        for _ in 0..<Int(r.height * 1.4) {
            state = state &* 1_664_525 &+ 1_013_904_223
            let y = r.minY + CGFloat((state >> 8) & 0xFFFF) / 65535 * r.height
            let line = CGRect(x: r.minX, y: y, width: r.width, height: 0.5)
            if (state >> 20) & 1 == 0 { light.addRect(line) } else { dark.addRect(line) }
        }
        inner.fill(light, with: .color(Color.white.opacity(0.06)))
        inner.fill(dark, with: .color(Color.black.opacity(0.08)))
        inner.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 8)),
                   with: .linearGradient(Gradient(colors: [Color.black.opacity(0.5), Color.black.opacity(0)]), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.minY + 8)))
        g.stroke(front(r.insetBy(dx: 0.7, dy: 0.7), high: 5.3, low: max(0, low - 0.7)), with: .color(Color.white.opacity(0.18)), lineWidth: 1)
        guard !album else { return }
        let tag = Self.holder(in: r, across: across)
        g.fill(Path(roundedRect: tag.insetBy(dx: -3, dy: -3), cornerRadius: 4), with: .linearGradient(silver, startPoint: CGPoint(x: tag.minX, y: tag.minY),
                                                                                                       endPoint: CGPoint(x: tag.maxX, y: tag.maxY)))
        g.fill(Path(roundedRect: tag, cornerRadius: 2), with: .color(RegisterPaint.card))
        g.stroke(Path(roundedRect: tag, cornerRadius: 2), with: .color(Color.black.opacity(0.35)), lineWidth: 0.8)
        if !across {
            let pull = CGRect(x: r.minX + 16, y: r.minY + 20, width: 36, height: 12)
            g.fill(Path(roundedRect: pull, cornerRadius: 6), with: .color(rgb(22, 23, 26)))
            g.stroke(Path(roundedRect: pull, cornerRadius: 6), with: .color(Color.white.opacity(0.22)), lineWidth: 0.8)
        }
        let key = across ? CGPoint(x: r.maxX - 24, y: r.minY + 22) : CGPoint(x: r.maxX - 34, y: r.minY + 26)
        let bezel = CGRect(x: key.x - 9, y: key.y - 9, width: 18, height: 18)
        g.fill(Path(ellipseIn: bezel), with: .linearGradient(silver, startPoint: CGPoint(x: bezel.minX, y: bezel.minY), endPoint: CGPoint(x: bezel.maxX, y: bezel.maxY)))
        g.fill(Path(ellipseIn: bezel.insetBy(dx: 2.5, dy: 2.5)), with: .color(rgb(43, 45, 50)))
        g.fill(Path(roundedRect: CGRect(x: key.x - 1, y: key.y - 4.5, width: 2, height: 9), cornerRadius: 1), with: .color(rgb(5, 5, 6)))
    }

    /// 相册: the drawer's tray, the walls between the slips.
    static func tray(_ g: GraphicsContext, _ l: RegisterLayout) {
        let r = l.tray
        guard r.width > 0, r.height > 0 else { return }
        g.fill(Path(roundedRect: r.insetBy(dx: -1.5, dy: -1.5), cornerRadius: 15.5, style: .continuous), with: .color(Color.white.opacity(0.45)))
        let shape = Path(roundedRect: r, cornerRadius: 14, style: .continuous)
        g.fill(shape, with: .linearGradient(Gradient(colors: [rgb(43, 46, 52), rgb(56, 59, 66)]), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.maxY)))
        var inner = g
        inner.clip(to: shape)
        speckle(inner, r, count: Int(r.width * r.height / 16), alpha: 0.05, seed: 0x7A4A_0001)
        inner.fill(Path(CGRect(x: r.minX, y: r.minY, width: r.width, height: 16)),
                   with: .linearGradient(Gradient(colors: [Color.black.opacity(0.55), Color.black.opacity(0)]), startPoint: CGPoint(x: 0, y: r.minY), endPoint: CGPoint(x: 0, y: r.minY + 16)))
        g.stroke(shape, with: .color(Color.black.opacity(0.65)), lineWidth: 1)
        let bottom: CGFloat = l.across ? r.maxY - 10 : max(r.minY + 20, l.place.minY - 6)
        let tall = max(0, bottom - r.minY - 10)
        for x in l.walls {
            g.fill(Path(CGRect(x: x + 2, y: r.minY + 10, width: 4, height: tall)), with: .color(Color.black.opacity(0.45)))
            g.fill(Path(CGRect(x: x, y: r.minY + 10, width: 4, height: tall)),
                   with: .linearGradient(Gradient(colors: [rgb(90, 94, 102), rgb(46, 49, 54)]), startPoint: CGPoint(x: x, y: 0), endPoint: CGPoint(x: x + 4, y: 0)))
            g.fill(Path(CGRect(x: x, y: r.minY + 10, width: 1, height: tall)), with: .color(Color.white.opacity(0.25)))
        }
    }

    /// The drawer's coin cups, empty.
    static func cups(_ g: GraphicsContext, _ l: RegisterLayout) {
        let rx = l.cupRadius, ry = l.cupRadius * 0.7
        for c in l.cups {
            g.fill(Path(ellipseIn: CGRect(x: c.x - rx - 1, y: c.y - ry, width: 2 * rx + 2, height: 2 * ry + 2)), with: .color(Color.white.opacity(0.12)))
            g.fill(Path(ellipseIn: CGRect(x: c.x - rx, y: c.y - ry, width: 2 * rx, height: 2 * ry)),
                   with: .radialGradient(Gradient(colors: [rgb(23, 24, 27), rgb(44, 47, 53)]), center: CGPoint(x: c.x, y: c.y - ry * 0.3), startRadius: 2, endRadius: rx))
        }
    }

    /// A strip of paper whose top is torn along the tear bar's teeth.
    static func tornTop(_ r: CGRect) -> Path {
        let tooth: CGFloat = 2.8, deep: CGFloat = 2.2
        let n = max(2, Int((r.width / tooth).rounded()))
        let step = r.width / CGFloat(n)
        var p = Path()
        p.move(to: CGPoint(x: r.minX, y: r.minY + deep))
        for i in 1...n { p.addLine(to: CGPoint(x: r.minX + CGFloat(i) * step, y: r.minY + (i % 2 == 1 ? 0 : deep))) }
        p.addLine(to: CGPoint(x: r.maxX, y: r.maxY))
        p.addLine(to: CGPoint(x: r.minX, y: r.maxY))
        p.closeSubpath()
        return p
    }
}

/// The cash register's body, drawn once (it is the same until the deck is
/// another size or the picture another shape): live, the display's housing,
/// the printer's mouth, the keyboard's deck and the drawer; in 相册 the
/// drawer pulled out (its tray, the cups, its front).
private struct RegisterBackdrop: View, Equatable {
    var layout: RegisterLayout
    var hinge: CGRect
    var album: Bool
    var body: some View {
        Canvas { context, size in
            RegisterArt.body(context, size, hinge: hinge)
            if layout.across { RegisterArt.ribs(context, layout.grip, across: true) }
            RegisterArt.name(context, layout.name)
            if album {
                RegisterArt.tray(context, layout)
                if layout.across { RegisterArt.deck(context, layout.deck) }
                RegisterArt.cups(context, layout)
                RegisterArt.drawer(context, layout.front, across: layout.across, album: true)
            } else {
                RegisterArt.housing(context, layout)
                RegisterArt.mouth(context, layout)
                RegisterArt.deck(context, layout.deck)
                RegisterArt.drawer(context, layout.drawer, across: layout.across, album: false)
            }
            if !layout.across { RegisterArt.strip(context, layout) }
            context.stroke(Path(CGRect(origin: .zero, size: size).insetBy(dx: 0.75, dy: 0.75)), with: .color(Color.white.opacity(0.3)), lineWidth: 1.5)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The display's glass up to the picture's edge (the viewfinder's own bezel
/// under it), and a dark line round the picture; nothing over the picture.
private struct RegisterGlassRim: View, Equatable {
    var glass: CGRect
    var hole: CGRect
    var radius: CGFloat
    var body: some View {
        Canvas { context, _ in
            guard glass.width > 0, hole.width > 0, hole.height > 0 else { return }
            var rim = Path(roundedRect: glass, cornerRadius: radius, style: .continuous)
            rim.addPath(Path(roundedRect: hole, cornerRadius: 5, style: .continuous))
            context.fill(rim, with: .color(RegisterArt.rgb(6, 7, 8)), style: FillStyle(eoFill: true))
            context.stroke(Path(roundedRect: hole.insetBy(dx: -0.5, dy: -0.5), cornerRadius: 5.5, style: .continuous), with: .color(Color.black), lineWidth: 1)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// While the camera would show what it has just taken (its own moment of
/// it), the display goes on showing what is in front of it.
private struct RegisterLiveCover: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var screen: CameraScreenModel
    var hole: CGRect
    var body: some View {
        if model.review != nil, model.phase == .live, hole.width > 0, hole.height > 0, let image = screen.image {
            Image(decorative: image, scale: 1).resizable().interpolation(.none)
                .frame(width: hole.width, height: hole.height)
                .clipShape(RoundedRectangle(cornerRadius: 5, style: .continuous))
                .position(x: hole.midX, y: hole.midY)
                .allowsHitTesting(false)
                .accessibilityHidden(true)
        }
    }
}

/// A thick square key of the till: its cap's sides show at the front while
/// it is up; down, it sinks to the deck and its top goes a little darker.
private struct RegisterKeyFace: View, Equatable {
    var tone: ShellTone
    var radius: CGFloat
    var depth: CGFloat
    var down: Bool
    var body: some View {
        Canvas { context, size in
            let w = size.width, h = size.height
            let sink: CGFloat = down ? max(0, depth - 1.6) : 0
            let sides = CGRect(x: 0, y: sink, width: w, height: max(0, h - sink))
            context.fill(Path(roundedRect: sides, cornerRadius: radius, style: .continuous),
                         with: .linearGradient(Gradient(colors: [tone.color(-0.1), tone.color(-0.42)]), startPoint: CGPoint(x: 0, y: sides.minY), endPoint: CGPoint(x: 0, y: sides.maxY)))
            let top = CGRect(x: 2.4, y: sink + 0.8, width: max(0, w - 4.8), height: max(0, h - depth - 0.8))
            let lit: [Color] = down ? [tone.color(0.1), tone.color(-0.05), tone.color(-0.1)] : [tone.color(0.32), tone.color(0), tone.color(-0.03)]
            context.fill(Path(roundedRect: top, cornerRadius: max(0, radius - 1), style: .continuous),
                         with: .linearGradient(Gradient(colors: lit), startPoint: CGPoint(x: 0, y: top.minY), endPoint: CGPoint(x: 0, y: top.maxY)))
            context.stroke(Path(roundedRect: top.insetBy(dx: 0.6, dy: 0.6), cornerRadius: max(0, radius - 1.5), style: .continuous),
                           with: .color(Color.white.opacity(down ? 0.28 : 0.6)), lineWidth: 1)
        }
    }
}

/// A key of the till. It goes down under the finger — or stays down
/// (`latched`: the zoom's number key in use) — and sounds as it goes down.
private struct RegisterKeyStyle: ButtonStyle {
    var tone: ShellTone
    var radius: CGFloat = 6
    var depth: CGFloat = 7
    var latched = false
    var sound: ConsoleSound? = .keyRubber
    var scale: Float = 0.7
    var haptic: HapticPart = .smallButton
    func makeBody(configuration: Configuration) -> some View {
        RegisterKeyBody(style: self, pressed: configuration.isPressed, label: AnyView(configuration.label))
    }
}

private struct RegisterKeyBody: View {
    var style: RegisterKeyStyle
    var pressed: Bool
    var label: AnyView
    @Environment(\.deckKeyInset) private var room
    var body: some View {
        let down = pressed || style.latched
        let sink: CGFloat = down ? max(0, style.depth - 1.6) : 0
        let lift: CGFloat = sink - style.depth / 2 + 0.4
        let well = RoundedRectangle(cornerRadius: style.radius + 2, style: .continuous)
        return label
            .offset(y: lift)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background {
                RegisterKeyFace(tone: style.tone, radius: style.radius, depth: style.depth, down: down).equatable()
                    .shadow(color: Color.black.opacity(down ? 0 : 0.45), radius: 2.5, y: 2)
            }
            .background(well.fill(Color.black.opacity(0.62)).padding(-2.2))
            .padding(room)
            .contentShape(Rectangle())
            .animation(.easeOut(duration: pressed ? 0.04 : 0.09), value: down)
            .onChange(of: pressed) { _, now in
                guard now else { return }
                if let sound = style.sound { ConsoleSounds.shared.play(sound, scale: style.scale) }
                ConsoleHaptics.shared.play(style.haptic, .press)
            }
    }
}

/// 浓淡's key: the half-dark circle and its sign, the step under it.
private struct RegisterToneLabel: View {
    var glyph: ShellGlyph
    var cells: ShellGlyph?
    var size: CGFloat
    var body: some View {
        VStack(spacing: 2) {
            ShellGlyphView(glyph: glyph, size: size, ink: RegisterPaint.ink)
            if let cells {
                ShellGlyphView(glyph: cells, size: size * 0.82, ink: RegisterPaint.ink)
            } else {
                Text(verbatim: "—").font(.system(size: size * 0.6, weight: .heavy, design: .rounded)).foregroundStyle(RegisterPaint.ink)
            }
        }
    }
}

/// The little green display's dark glass in its bezel, its faint dots.
private struct RegisterPlateFace: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size)
            context.fill(Path(roundedRect: r, cornerRadius: 7, style: .continuous),
                         with: .linearGradient(Gradient(colors: [RegisterArt.rgb(93, 97, 106), RegisterArt.rgb(44, 47, 53)]), startPoint: .zero, endPoint: CGPoint(x: 0, y: size.height)))
            context.stroke(Path(roundedRect: r.insetBy(dx: 0.6, dy: 0.6), cornerRadius: 6.5, style: .continuous), with: .color(Color.white.opacity(0.25)), lineWidth: 1)
            let glass = r.insetBy(dx: 5, dy: 5)
            let shape = Path(roundedRect: glass, cornerRadius: 4, style: .continuous)
            context.fill(shape, with: .color(RegisterArt.rgb(4, 16, 12)))
            var grid = Path()
            var y = glass.minY + 2
            while y < glass.maxY {
                var x = glass.minX + 2
                while x < glass.maxX {
                    grid.addRect(CGRect(x: x, y: y, width: 1.1, height: 1.1))
                    x += 2.4
                }
                y += 2.4
            }
            var inner = context
            inner.clip(to: shape)
            inner.fill(grid, with: .color(RegisterPaint.vfd.opacity(0.055)))
        }
        .background(RoundedRectangle(cornerRadius: 8, style: .continuous).fill(Color.black.opacity(0.55)).padding(-2).offset(y: 1))
    }
}

/// The little green display between the lens keys: the lens's glyph, its
/// name (the one in use is named), which of how many.
private struct RegisterPlate: View {
    var glyph: ShellGlyph
    var name: String
    var place: String
    var narrow: Bool
    var body: some View {
        ZStack {
            RegisterPlateFace().equatable()
            Group {
                if narrow {
                    VStack(spacing: 1) {
                        Text(name).font(.system(size: 13, weight: .heavy, design: .rounded)).lineLimit(1).minimumScaleFactor(0.6)
                        Text(verbatim: place).font(.system(size: 10, weight: .bold, design: .monospaced)).foregroundStyle(RegisterPaint.vfd.opacity(0.6))
                    }
                    .padding(.horizontal, 7)
                } else {
                    HStack(spacing: 6) {
                        ShellGlyphView(glyph: glyph, size: 15, ink: RegisterPaint.vfd.opacity(0.6))
                        Spacer(minLength: 0)
                        Text(name).font(.system(size: 17, weight: .heavy, design: .rounded)).lineLimit(1).minimumScaleFactor(0.6)
                        Spacer(minLength: 0)
                        Text(verbatim: place).font(.system(size: 12, weight: .bold, design: .monospaced)).foregroundStyle(RegisterPaint.vfd.opacity(0.85))
                    }
                    .padding(.horizontal, 13)
                }
            }
            .foregroundStyle(RegisterPaint.vfd)
            .shadow(color: RegisterPaint.vfd.opacity(0.45), radius: 2.5)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The mode lock's bezel: the marks at its two stops (the one the key is
/// at in the ink, the other paler), bright metal round a dark middle.
private struct RegisterLockBezel: View, Equatable {
    var centre: CGPoint
    var radius: CGFloat
    var turn: Double
    var video: Bool
    var ink: Color
    var dim: Color
    var body: some View {
        Canvas { context, _ in
            let r = radius, c = centre
            for (index, stop) in [-turn, turn].enumerated() {
                let a = stop - Double.pi / 2
                let on = (index == 1) == video
                var tick = Path()
                tick.move(to: CGPoint(x: c.x + CGFloat(cos(a)) * (r + 2.5), y: c.y + CGFloat(sin(a)) * (r + 2.5)))
                tick.addLine(to: CGPoint(x: c.x + CGFloat(cos(a)) * (r + 7), y: c.y + CGFloat(sin(a)) * (r + 7)))
                context.stroke(tick, with: .color(on ? ink : dim), style: StrokeStyle(lineWidth: 2, lineCap: .round))
            }
            let disc = CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r)
            context.fill(Path(ellipseIn: disc.insetBy(dx: -2.4, dy: -2.4).offsetBy(dx: 0, dy: 1.8)), with: .color(Color.black.opacity(0.45)))
            context.fill(Path(ellipseIn: disc), with: .linearGradient(RegisterArt.silver, startPoint: CGPoint(x: disc.minX, y: disc.minY), endPoint: CGPoint(x: disc.maxX, y: disc.maxY)))
            context.stroke(Path(ellipseIn: disc.insetBy(dx: 0.7, dy: 0.7)), with: .color(Color.white.opacity(0.8)), lineWidth: 0.9)
            let middle = disc.insetBy(dx: r * 0.32, dy: r * 0.32)
            context.fill(Path(ellipseIn: middle), with: .radialGradient(Gradient(colors: [RegisterArt.rgb(85, 88, 95), RegisterArt.rgb(20, 21, 24)]),
                                                                       center: CGPoint(x: c.x - 3, y: c.y - 4), startRadius: 1, endRadius: r))
            context.stroke(Path(ellipseIn: middle), with: .color(Color.black.opacity(0.6)), lineWidth: 1)
        }
    }
}

/// The lock's key, drawn pointing up (it is turned as a whole): the keyway,
/// the shank, the brass bow with the hole for its ring.
private struct RegisterLockKeyArt: View, Equatable {
    var radius: CGFloat
    var body: some View {
        Canvas { context, size in
            let r = radius, cx = size.width / 2, cy = size.height / 2
            context.fill(Path(roundedRect: CGRect(x: cx - 1.8, y: cy - r * 0.6, width: 3.6, height: r * 1.2), cornerRadius: 1.4), with: .color(RegisterArt.rgb(5, 5, 6)))
            let bw = r * 0.86, b0 = cy - r * 0.32, b1 = cy - r * 1.02
            context.fill(Path(roundedRect: CGRect(x: cx - 3, y: b0 - 2, width: 6, height: r * 0.5), cornerRadius: 1.5), with: .color(RegisterArt.rgb(176, 138, 62)))
            let bow = Path(roundedRect: CGRect(x: cx - bw / 2, y: b1, width: bw, height: max(0, b0 - b1 - 3)), cornerRadius: bw * 0.42)
            let brass = Gradient(stops: [Gradient.Stop(color: RegisterArt.rgb(138, 106, 42), location: 0), Gradient.Stop(color: RegisterArt.rgb(242, 212, 138), location: 0.3),
                                         Gradient.Stop(color: RegisterArt.rgb(211, 172, 88), location: 0.6), Gradient.Stop(color: RegisterArt.rgb(124, 94, 36), location: 1)])
            context.fill(bow, with: .linearGradient(brass, startPoint: CGPoint(x: cx - bw / 2, y: 0), endPoint: CGPoint(x: cx + bw / 2, y: 0)))
            context.stroke(bow, with: .color(RegisterArt.rgb(70, 50, 15).opacity(0.7)), lineWidth: 0.8)
            let hole = r * 0.09
            context.fill(Path(ellipseIn: CGRect(x: cx - hole, y: b1 + r * 0.22 - hole, width: 2 * hole, height: 2 * hole)), with: .color(RegisterArt.rgb(43, 42, 40)))
        }
    }
}

/// 拍照 / 录像: the mode lock, its key turned to the stop it is at; a camera
/// and a video camera at its two stops (over it upright, beside it held
/// across), the one it points at filled and in the ink, the other paler.
private struct RegisterLockView: View {
    var video: Bool
    var centre: CGPoint
    var radius: CGFloat
    var beside: Bool
    var onDeck: Bool
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        let turn: Double = beside ? 1.15 : 0.5
        let reach: CGFloat = radius + (beside ? 18 : 16)
        let ink: Color = onDeck ? RegisterPaint.light : RegisterPaint.ink
        let dim: Color = ink.opacity(0.45)
        let photoAt = Self.point(centre, -turn, reach), videoAt = Self.point(centre, turn, reach)
        let size: CGFloat = beside ? 13 : 14
        ZStack(alignment: .topLeading) {
            RegisterLockBezel(centre: centre, radius: radius, turn: turn, video: video, ink: ink, dim: dim).equatable()
            RegisterLockKeyArt(radius: radius).equatable()
                .frame(width: radius * 2.3, height: radius * 2.3)
                .rotationEffect(.radians(video ? turn : -turn))
                .position(centre)
                .animation(reduceMotion ? nil : .easeOut(duration: 0.18), value: video)
            ShellGlyphView(glyph: .photo(!video), size: size, ink: video ? dim : ink)
                .position(photoAt)
            ShellGlyphView(glyph: .video(video), size: size, ink: video ? ink : dim)
                .position(videoAt)
        }
    }
    static func point(_ c: CGPoint, _ angle: Double, _ reach: CGFloat) -> CGPoint {
        let a = angle - Double.pi / 2
        return CGPoint(x: c.x + CGFloat(cos(a)) * reach, y: c.y + CGFloat(sin(a)) * reach)
    }
}

