// MARK: - The cash register's slip: printed, torn off, scratched

/// The slips the cash register has printed: each one's picture (read at
/// its own size), which were printed here (their photos under the silver
/// coat), and which have had the coat scratched off — for good, by the
/// picture's file name (kept in UserDefaults, the newest few thousand).
@MainActor final class RegisterSlips: ObservableObject {
    static let shared = RegisterSlips()
    static let printedKey = "FoldArc.camera.receipt.printed"
    static let revealedKey = "FoldArc.camera.receipt.revealed"
    static let kept = 3000
    #if DEBUG
    /// `--foldarc-camera-receipt-stays`: a slip out of the printer stays
    /// there until the next picture (the UI tests scratch it).
    static let slipsStay = ProcessInfo.processInfo.arguments.contains("--foldarc-camera-receipt-stays")
    #else
    static let slipsStay = false
    #endif
    @Published private(set) var images: [URL: CGImage] = [:]
    @Published private(set) var printed: [String]
    @Published private(set) var revealed: [String]
    private var order: [URL] = []
    private var loading: Set<URL> = []

    init() {
        let defaults = UserDefaults.standard
        printed = defaults.stringArray(forKey: Self.printedKey) ?? []
        revealed = defaults.stringArray(forKey: Self.revealedKey) ?? []
    }

    /// The photo on this slip is under its coat.
    func coated(_ name: String) -> Bool { printed.contains(name) && !revealed.contains(name) }
    /// A slip just printed: a new coat over its photo (a name used again
    /// is a new slip).
    func coat(_ name: String) {
        printed.removeAll { $0 == name }
        printed.append(name)
        revealed.removeAll { $0 == name }
        RegisterScratches.shared.forget(name)
        store()
    }
    /// The coat off, for good.
    func reveal(_ name: String) {
        guard !revealed.contains(name) else { return }
        revealed.append(name)
        RegisterScratches.shared.forget(name)
        store()
    }
    /// What is left of the coat falls off (all at once with Reduce Motion).
    func takeOff(_ name: String, animated: Bool) {
        guard coated(name) else { return }
        ConsoleSounds.shared.play(.crumble, scale: 0.7)
        ConsoleHaptics.shared.play(.smallButton, .press)
        withAnimation(animated ? .easeIn(duration: 0.4) : nil) { reveal(name) }
    }
    private func store() {
        if printed.count > Self.kept { printed.removeFirst(printed.count - Self.kept) }
        if revealed.count > Self.kept { revealed.removeFirst(revealed.count - Self.kept) }
        UserDefaults.standard.set(printed, forKey: Self.printedKey)
        UserDefaults.standard.set(revealed, forKey: Self.revealedKey)
    }

    /// A picture at its own size (a slip's dots stay dots), from the ones
    /// read lately or from the card.
    func load(_ url: URL) async -> CGImage? {
        if let kept = images[url] { return kept }
        let image = await Task.detached(priority: .userInitiated) { CameraRoll.image(at: url, maxPixel: 2400) }.value
        if let image { keep(url, image) }
        return image
    }
    func request(_ url: URL) {
        guard images[url] == nil, !loading.contains(url) else { return }
        loading.insert(url)
        Task { [weak self] in
            let image = await Task.detached(priority: .userInitiated) { CameraRoll.image(at: url, maxPixel: 2400) }.value
            guard let self else { return }
            self.loading.remove(url)
            if let image { self.keep(url, image) }
        }
    }
    private func keep(_ url: URL, _ image: CGImage) {
        images[url] = image
        order.removeAll { $0 == url }
        order.append(url)
        while order.count > 10 { images[order.removeFirst()] = nil }
    }
}

/// One touch of the finger on a coat: where (the coat's width is 1, its
/// height in the same measure), how wide, and whether a new stroke begins
/// there (not joined to the touch before).
struct RegisterStroke: Equatable {
    var at: CGPoint
    var radius: CGFloat
    var fresh: Bool
}

/// The finger's work on the coats not yet off (this run only): the strokes
/// as drawn, and which of a coat's 16 × 12 cells they have cleared; at six
/// tenths cleared the rest of the coat falls off.
@MainActor final class RegisterScratches: ObservableObject {
    static let shared = RegisterScratches()
    static let columns = 16
    static let rows = 12
    static let enough = 0.6
    static let most = 900
    @Published private(set) var strokes: [String: [RegisterStroke]] = [:]
    private var cleared: [String: Set<Int>] = [:]
    /// When a finger was last on a coat (a slip being scratched is not torn off).
    var lastTouch = Date.distantPast

    func forget(_ name: String) {
        strokes[name] = nil
        cleared[name] = nil
    }
    /// The finger at `at` on the coat of slip `name` (`tall`: the coat's
    /// height over its width), joined to the touch before unless `fresh`:
    /// the share of the coat now cleared.
    func scratch(_ name: String, at: CGPoint, radius: CGFloat, tall: CGFloat, fresh: Bool) -> Double {
        lastTouch = Date()
        var marks = strokes[name] ?? []
        let from: CGPoint? = fresh ? nil : marks.last?.at
        if let from, hypot(from.x - at.x, from.y - at.y) < radius * 0.35 { return share(name) }
        if marks.count < Self.most {
            marks.append(RegisterStroke(at: at, radius: radius, fresh: from == nil))
            strokes[name] = marks
        }
        var done = cleared[name] ?? []
        let cw = 1 / CGFloat(Self.columns), ch = tall / CGFloat(Self.rows)
        var steps = 1
        if let from {
            let gap: CGFloat = hypot(from.x - at.x, from.y - at.y)
            steps = max(1, Int((gap / (radius * 0.5)).rounded(.up)))
        }
        for step in 1...steps {
            let t = CGFloat(step) / CGFloat(steps)
            let p: CGPoint = from.map { CGPoint(x: $0.x + (at.x - $0.x) * t, y: $0.y + (at.y - $0.y) * t) } ?? at
            for row in 0..<Self.rows {
                for column in 0..<Self.columns {
                    let cx = (CGFloat(column) + 0.5) * cw, cy = (CGFloat(row) + 0.5) * ch
                    if hypot(cx - p.x, cy - p.y) <= radius { done.insert(row * Self.columns + column) }
                }
            }
        }
        cleared[name] = done
        return share(name)
    }
    private func share(_ name: String) -> Double {
        Double(cleared[name]?.count ?? 0) / Double(Self.columns * Self.rows)
    }
}

/// The printer: after each picture its slip rises out of the mouth, line by
/// line (about a second and a half, the head's buzz with it, the lamp lit),
/// stays a few seconds and is torn off along the teeth into the drawer —
/// not while a finger is on its coat. Between slips the end of the paper
/// stands torn in the mouth. With Reduce Motion the slip is out at once and
/// goes at once.
private struct RegisterPrinter: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var slips: RegisterSlips
    var layout: RegisterLayout
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var slip: CameraPhoto? = nil
    @State private var image: CGImage? = nil
    /// How far out it is (0…1), whether it is being torn off.
    @State private var out: CGFloat = 0
    @State private var tearing = false
    /// Which slip a step waited for belongs to.
    @State private var serial = 0

    var body: some View {
        ZStack(alignment: .topLeading) {
            if let slip, let image { rising(slip, image) }
            RegisterSlotLip(slot: layout.slot, idle: slip == nil).equatable()
            RegisterLamp(on: slip != nil && out < 1 && !tearing)
                .position(layout.lamp)
        }
        .frame(width: layout.canvas.width, height: layout.canvas.height, alignment: .topLeading)
        .onChange(of: model.photos.first?.url) { old, url in
            guard let url, old != url, model.phase == .live, let newest = model.photos.first, newest.url == url, !newest.isVideo else { return }
            begin(newest)
        }
    }

    /// The slip, as far out of the mouth as it is (what is still inside is
    /// not seen), as wide as the room over the mouth lets it be.
    private func rising(_ photo: CameraPhoto, _ picture: CGImage) -> some View {
        let r = layout.rise
        let shape = CGFloat(picture.height) / CGFloat(max(1, picture.width))
        let wide: CGFloat = min(r.width, r.height / max(0.1, shape))
        let tall: CGFloat = wide * shape
        let mouth = layout.slot.minY
        let lifted: CGFloat = tearing ? 26 : 0
        return RegisterReceiptView(slips: slips, photo: photo, image: picture)
            .frame(width: wide, height: tall)
            .position(x: r.minX + r.width / 2, y: mouth - out * tall + tall / 2 - lifted)
            .opacity(tearing ? 0 : 1)
            .frame(width: layout.canvas.width, height: max(0, mouth + 4.5), alignment: .topLeading)
            .clipped()
    }

    private func begin(_ photo: CameraPhoto) {
        serial += 1
        let mine = serial
        // (One still out goes into the drawer first.)
        if slip != nil { finish() }
        Task { @MainActor in
            guard let picture = await slips.load(photo.url), serial == mine else { return }
            guard CameraReceiptPrint.isSlip(width: picture.width, height: picture.height) else { return }
            slips.coat(photo.name)
            var still = Transaction()
            still.disablesAnimations = true
            withTransaction(still) {
                slip = photo
                image = picture
                tearing = false
                out = reduceMotion ? 1 : 0
            }
            if reduceMotion {
                tearLater(mine, after: 3)
                return
            }
            ConsoleSounds.shared.play(.instantEject, scale: 0.8)
            try? await Task.sleep(nanoseconds: 60_000_000)
            guard serial == mine else { return }
            withAnimation(.linear(duration: 1.5)) { out = 1 }
            tearLater(mine, after: 4.5)
        }
    }
    /// Torn off `after` seconds — later while a finger is on its coat, or
    /// was a moment ago.
    private func tearLater(_ mine: Int, after seconds: Double) {
        guard !RegisterSlips.slipsStay else { return }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(seconds * 1_000_000_000))
            while serial == mine, slip != nil, Date().timeIntervalSince(RegisterScratches.shared.lastTouch) < 1.5 {
                try? await Task.sleep(nanoseconds: 500_000_000)
            }
            guard serial == mine, slip != nil else { return }
            tear(mine)
        }
    }
    private func tear(_ mine: Int) {
        ConsoleSounds.shared.play(.rip, scale: 0.8)
        guard !reduceMotion else { finish(); return }
        withAnimation(.easeIn(duration: 0.3)) { tearing = true }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 320_000_000)
            guard serial == mine else { return }
            finish()
        }
    }
    private func finish() {
        var still = Transaction()
        still.disablesAnimations = true
        withTransaction(still) {
            slip = nil
            image = nil
            out = 0
            tearing = false
        }
    }
}

/// The mouth's near lip, over the paper that leaves it; between slips the
/// end of the paper standing in it, torn along the teeth.
private struct RegisterSlotLip: View, Equatable {
    var slot: CGRect
    var idle: Bool
    var body: some View {
        Canvas { context, _ in
            let x = slot.minX, y = slot.minY, w = slot.width
            guard w > 40 else { return }
            if idle {
                let bar = y - 10
                let end = RegisterArt.tornTop(CGRect(x: x + 16, y: bar - 0.5, width: w - 32, height: y + 5 - bar))
                context.fill(end.applying(CGAffineTransform(translationX: 0, y: 1)), with: .color(Color.black.opacity(0.18)))
                context.fill(end, with: .color(RegisterPaint.paper))
                context.fill(Path(CGRect(x: x + 16, y: y + 2, width: w - 32, height: 3)), with: .color(Color.black.opacity(0.08)))
            }
            context.fill(Path(roundedRect: CGRect(x: x - 1, y: y + 4.4, width: w + 2, height: 4.6), cornerRadius: 2.3), with: .color(RegisterArt.rgb(5, 5, 6)))
            context.fill(Path(CGRect(x: x + 2, y: y + 9.2, width: w - 4, height: 0.9)), with: .color(Color.white.opacity(0.32)))
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The printer's lamp: orange while a slip is coming out.
private struct RegisterLamp: View {
    var on: Bool
    var body: some View {
        let lit = Color(red: 1.0, green: 0.659, blue: 0.235), off = Color(red: 0.471, green: 0.439, blue: 0.384)
        Circle().fill(on ? lit : off)
            .frame(width: 5.2, height: 5.2)
            .overlay(Circle().strokeBorder(Color.black.opacity(0.35), lineWidth: 0.6))
            .shadow(color: on ? lit.opacity(0.9) : Color.clear, radius: on ? 3 : 0)
            .frame(width: 14, height: 14)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
    }
}

/// A slip: the picture kept (ZERO, the time and its number over the photo
/// in dots), its ends torn along the teeth; over the photo, while it is
/// coated, the silver coat (RegisterCoating). VoiceOver hears 小票 and
/// whether the coat is on, and 刮开 takes it off at once.
private struct RegisterReceiptView: View {
    @ObservedObject var slips: RegisterSlips
    var photo: CameraPhoto
    var image: CGImage
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        GeometryReader { geo in
            let size = geo.size
            let hole = CameraReceiptPrint.photoRect(in: size)
            let coated = slips.coated(photo.name)
            ZStack(alignment: .topLeading) {
                paper(size, coated: coated)
                if coated {
                    RegisterCoating(scratches: RegisterScratches.shared, slips: slips, name: photo.name, size: hole.size)
                        .frame(width: hole.width, height: hole.height)
                        .offset(x: hole.minX, y: hole.minY)
                        .transition(.opacity)
                }
            }
        }
    }
    private func paper(_ size: CGSize, coated: Bool) -> some View {
        let said = coated ? String(localized: "涂层盖着") : String(localized: "已刮开")
        return ZStack {
            Image(decorative: image, scale: 1).resizable()
        }
        .frame(width: size.width, height: size.height)
        .clipShape(RegisterTornEdge())
        .shadow(color: Color.black.opacity(0.45), radius: 5, y: 3)
        .contentShape(Rectangle())
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(String(localized: "小票"))
        .accessibilityValue(said)
        .modifier(RegisterRevealAction(on: coated) { slips.takeOff(photo.name, animated: !reduceMotion) })
        .accessibilityIdentifier("camera-receipt")
    }
}

/// 刮开 for VoiceOver, while the coat is on.
private struct RegisterRevealAction: ViewModifier {
    var on: Bool
    var reveal: () -> Void
    @ViewBuilder func body(content: Content) -> some View {
        if on {
            content.accessibilityAction(named: Text("刮开")) { reveal() }
        } else {
            content
        }
    }
}

/// A slip's two ends, torn along the teeth.
private struct RegisterTornEdge: Shape {
    func path(in rect: CGRect) -> Path {
        let tooth: CGFloat = 3.2, deep: CGFloat = 2.2
        let n = max(2, Int((rect.width / tooth).rounded()))
        let step = rect.width / CGFloat(n)
        var p = Path()
        p.move(to: CGPoint(x: rect.minX, y: rect.minY + deep))
        for i in 1...n { p.addLine(to: CGPoint(x: rect.minX + CGFloat(i) * step, y: rect.minY + (i % 2 == 1 ? 0 : deep))) }
        p.addLine(to: CGPoint(x: rect.maxX, y: rect.maxY - deep))
        for i in stride(from: n - 1, through: 0, by: -1) {
            p.addLine(to: CGPoint(x: rect.minX + CGFloat(i) * step, y: rect.maxY - ((n - i) % 2 == 1 ? 0 : deep)))
        }
        p.closeSubpath()
        return p
    }
}

/// The silver coat over a slip's photo: a finger drawn across it takes it
/// off where it goes (the scratch about a fingertip wide, its edge frayed,
/// a rustle while the finger moves); at six tenths off the rest falls off
/// and the photo stays uncovered for good. 刮开 for VoiceOver, at once.
private struct RegisterCoating: View {
    @ObservedObject var scratches: RegisterScratches
    @ObservedObject var slips: RegisterSlips
    var name: String
    var size: CGSize
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var touching = false
    @State private var heard = Date.distantPast
    var body: some View {
        let marks = scratches.strokes[name] ?? []
        return RegisterCoatFace(size: size).equatable()
            .overlay(RegisterScratchMarks(marks: marks).equatable().blendMode(.destinationOut))
            .compositingGroup()
            .contentShape(Rectangle())
            .gesture(DragGesture(minimumDistance: 0)
                .onChanged { value in
                    let fresh = !touching
                    touching = true
                    scratch(value.location, fresh: fresh)
                }
                .onEnded { _ in
                    touching = false
                    scratches.lastTouch = Date()
                })
            .accessibilityElement()
            .accessibilityLabel(String(localized: "涂层"))
            .accessibilityAction(named: Text("刮开")) { slips.takeOff(name, animated: !reduceMotion) }
            .accessibilityIdentifier("camera-receipt-coating")
    }
    private func scratch(_ at: CGPoint, fresh: Bool) {
        guard size.width > 1, size.height > 1 else { return }
        let unit = CGPoint(x: at.x / size.width, y: at.y / size.width)
        let share = scratches.scratch(name, at: unit, radius: 11.5 / size.width, tall: size.height / size.width, fresh: fresh)
        if Date().timeIntervalSince(heard) > 0.45 {
            heard = Date()
            ConsoleSounds.shared.play(.scribble, scale: 0.55)
        }
        if share >= RegisterScratches.enough { slips.takeOff(name, animated: !reduceMotion) }
    }
}

/// Where the finger has been on a coat: each touch a fingertip's round,
/// joined to the one before along the stroke, a crumb off its side.
private struct RegisterScratchMarks: View, Equatable {
    var marks: [RegisterStroke]
    var body: some View {
        Canvas { context, size in
            let w = size.width
            var rounds = Path()
            var lines: [CGFloat: Path] = [:]
            for (index, mark) in marks.enumerated() {
                let c = CGPoint(x: mark.at.x * w, y: mark.at.y * w), r = mark.radius * w
                rounds.addEllipse(in: CGRect(x: c.x - r, y: c.y - r, width: 2 * r, height: 2 * r))
                let a = Double(index) * 2.399
                let crumb = r * (0.12 + 0.1 * CGFloat(index % 3))
                let off = CGPoint(x: c.x + CGFloat(cos(a)) * r * 1.02, y: c.y + CGFloat(sin(a)) * r * 1.02)
                rounds.addEllipse(in: CGRect(x: off.x - crumb, y: off.y - crumb, width: 2 * crumb, height: 2 * crumb))
                if index > 0, !mark.fresh {
                    let before = marks[index - 1].at
                    lines[r, default: Path()].move(to: CGPoint(x: before.x * w, y: before.y * w))
                    lines[r, default: Path()].addLine(to: c)
                }
            }
            context.fill(rounds, with: .color(Color.black))
            for (r, line) in lines {
                context.stroke(line, with: .color(Color.black), style: StrokeStyle(lineWidth: 2 * r, lineCap: .round, lineJoin: .round))
            }
        }
        .allowsHitTesting(false)
    }
}

/// The coat itself: silver with a fine grain, 刮开 printed faintly all over
/// it, and in its middle a plate with a finger's zigzag and 刮开.
private struct RegisterCoatFace: View, Equatable {
    var size: CGSize
    var body: some View {
        Canvas { context, area in
            let w = area.width, h = area.height
            let rect = CGRect(origin: .zero, size: area)
            let silver = Gradient(stops: [Gradient.Stop(color: RegisterArt.rgb(191, 195, 201), location: 0), Gradient.Stop(color: RegisterArt.rgb(236, 238, 241), location: 0.24),
                                          Gradient.Stop(color: RegisterArt.rgb(165, 170, 177), location: 0.47), Gradient.Stop(color: RegisterArt.rgb(225, 228, 231), location: 0.72),
                                          Gradient.Stop(color: RegisterArt.rgb(176, 181, 188), location: 1)])
            context.fill(Path(rect), with: .linearGradient(silver, startPoint: .zero, endPoint: CGPoint(x: w, y: h)))
            RegisterArt.speckle(context, rect, count: Int(w * h / 5), alpha: 0.16, seed: 0x0C0A_7EED)
            let k = max(0.4, w / 224)
            var faint = context
            faint.translateBy(x: w / 2, y: h / 2)
            faint.rotate(by: .radians(-0.32))
            let word = Text("刮开").font(.system(size: 9.5 * k, weight: .heavy, design: .rounded)).foregroundColor(RegisterArt.rgb(84, 90, 100).opacity(0.22))
            let stepX = 46 * k, stepY = 21 * k
            for row in -6...6 {
                for column in -4...4 {
                    let shift: CGFloat = row % 2 == 0 ? 0 : stepX / 2
                    faint.draw(word, at: CGPoint(x: CGFloat(column) * stepX + shift, y: CGFloat(row) * stepY))
                }
            }
            let pw: CGFloat = min(w - 20 * k, 132 * k), ph: CGFloat = 38 * k
            let plate = CGRect(x: (w - pw) / 2, y: (h - ph) / 2, width: pw, height: ph)
            context.fill(Path(roundedRect: plate, cornerRadius: 7 * k), with: .color(RegisterArt.rgb(70, 76, 86).opacity(0.78)))
            context.stroke(Path(roundedRect: plate.insetBy(dx: 2 * k, dy: 2 * k), cornerRadius: 5.5 * k), with: .color(Color.white.opacity(0.4)), lineWidth: 1)
            let fx = plate.minX + 18 * k, fy = plate.midY
            var zig = Path()
            zig.move(to: CGPoint(x: fx - 6 * k, y: fy + 4 * k))
            zig.addLine(to: CGPoint(x: fx - 2 * k, y: fy - 4 * k))
            zig.addLine(to: CGPoint(x: fx + 1 * k, y: fy + 4 * k))
            zig.addLine(to: CGPoint(x: fx + 5 * k, y: fy - 4 * k))
            let white = RegisterArt.rgb(244, 245, 247)
            context.stroke(zig, with: .color(white), style: StrokeStyle(lineWidth: 1.6 * k, lineCap: .round, lineJoin: .round))
            context.draw(Text("刮开").font(.system(size: 14.5 * k, weight: .black, design: .rounded)).foregroundColor(white), at: CGPoint(x: plate.midX + 8 * k, y: plate.midY))
        }
    }
}

// MARK: - The cash register's album: 小票夹

/// The cash register's 相册: the drawer pulled out. The slip looked at lies
/// whole under the drawer's clip (its coat still on if it has not been
/// scratched off: it can be scratched here), the edges of the ones before
/// and after it beside it, which one it is on a paper tag; a picture that
/// is not a slip lies there as a print with its number, a video too (▶
/// plays it where it lies). A push to the side, or ‹ and › on the
/// drawer's front, goes to the one before or after; 回去拍照 (its words
/// kept) and 合计 go back to taking pictures; 主菜单 as ever.
private struct RegisterAlbumView: View {
    @ObservedObject var model: CameraAppModel
    @ObservedObject var thumbnails: CameraThumbnails
    @ObservedObject var slips: RegisterSlips
    var register: RegisterLayout
    var hinge: CGRect
    @State private var push: CGFloat = 0

    /// While a picture is being drawn on inside, 回去拍照 waits (and says where it is).
    private var drawing: Bool { model.doodle != nil }
    private var drawingWhy: String { String(localized: "正在编辑 · 打开 Duo，在下屏接着画") }
    /// The video's length ("00:12"), once it is known.
    private var length: String? {
        guard let photo = model.albumPhoto, photo.isVideo, model.albumImageURL == photo.url, let seconds = model.albumDuration else { return nil }
        return CameraAppModel.clock(Int(seconds.rounded()))
    }
    private var videoWord: String { length.map { String(localized: "视频 \($0)") } ?? String(localized: "录像") }
    private func backToCamera() {
        if drawing { model.say(drawingWhy) } else { model.closeAlbum() }
    }
    /// The one before (−1) or after (+1); at either end a firm stop, and why.
    private func turn(_ delta: Int) {
        guard !drawing else { model.say(drawingWhy); return }
        let next = model.albumIndex + delta
        guard model.photos.indices.contains(next) else {
            ConsoleHaptics.shared.play(.sliderStop, .press)
            if model.photos.isEmpty {
                model.say(String(localized: "还没有照片"))
            } else {
                model.say(delta < 0 ? String(localized: "已经是第一张") : String(localized: "已经是最后一张"))
            }
            return
        }
        ConsoleSounds.shared.play(.pageFlip, scale: 0.5)
        model.chooseInAlbum(next, quiet: true)
    }
    /// The picture looked at, read at its own size (a video's first picture is the album's).
    private func readCurrent() {
        guard let photo = model.albumPhoto else { return }
        if photo.isVideo { thumbnails.request(photo.url) } else { slips.request(photo.url) }
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            RegisterBackdrop(layout: register, hinge: hinge, album: true).equatable()
            slivers
            current
            place
            words
            keys
            total
        }
        .onAppear { readCurrent() }
        .onChange(of: model.albumIndex) { _, _ in readCurrent() }
        .onChange(of: model.photos.first?.url) { _, _ in readCurrent() }
    }

    /// The edges of the slips before and after the one looked at.
    @ViewBuilder private var slivers: some View {
        let walls = register.walls, tray = register.tray, room = register.paper
        if walls.count == 2, room.height > 60 {
            let top = room.minY + 12, tall = max(40, room.height - 30)
            if model.albumIndex > 0 {
                RegisterSliver().equatable()
                    .frame(width: max(0, walls[0] - tray.minX - 6), height: tall)
                    .position(x: (tray.minX + 4 + walls[0] - 2) / 2, y: top + tall / 2)
            }
            if model.albumIndex + 1 < model.photos.count {
                RegisterSliver().equatable()
                    .frame(width: max(0, tray.maxX - walls[1] - 10), height: tall)
                    .position(x: (walls[1] + 6 + tray.maxX - 4) / 2, y: top + 4 + tall / 2)
            }
        }
    }

    /// The one looked at: a slip under the clip, or a print (a picture
    /// taken some other way, a video); nothing yet: says so.
    @ViewBuilder private var current: some View {
        let photos = model.photos, at = model.albumIndex, room = register.paper
        if photos.isEmpty {
            Text("还没有照片").font(.system(size: 13, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.7))
                .position(x: room.midX, y: room.midY)
        } else if photos.indices.contains(at) {
            let photo = photos[at]
            if photo.isVideo {
                card(photo, image: poster(photo))
            } else if let image = slips.images[photo.url] {
                if CameraReceiptPrint.isSlip(width: image.width, height: image.height) {
                    slip(photo, image)
                } else {
                    card(photo, image: image)
                }
            }
        }
    }
    private func poster(_ photo: CameraPhoto) -> CGImage? {
        (model.albumImageURL == photo.url ? model.albumImage : nil) ?? thumbnails.images[photo.url]
    }
    /// A push to the side: the one before or after.
    private var swipe: some Gesture {
        DragGesture(minimumDistance: 8)
            .onChanged { push = $0.translation.width }
            .onEnded { value in
                let dx = value.translation.width
                withAnimation(.easeOut(duration: 0.15)) { push = 0 }
                if abs(dx) > 60 { turn(dx < 0 ? 1 : -1) }
            }
    }

    /// A slip, whole, as large as the room lets it be, the clip over its top.
    private func slip(_ photo: CameraPhoto, _ image: CGImage) -> some View {
        let room = register.paper
        let shape = CGFloat(image.height) / CGFloat(max(1, image.width))
        let wide: CGFloat = min(room.width, room.height / max(0.1, shape))
        let tall: CGFloat = wide * shape
        return ZStack(alignment: .top) {
            RegisterReceiptView(slips: slips, photo: photo, image: image)
                .frame(width: wide, height: tall)
                .gesture(swipe)
            RegisterClip().equatable()
                .frame(width: 140, height: 26)
                .offset(y: -14)
        }
        .frame(width: wide, height: tall)
        .offset(x: push)
        .position(x: room.midX, y: room.minY + tall / 2)
    }

    /// A picture that is no slip, as a print: the picture on paper, its
    /// number under it; a video's first picture, ▶ on it (it plays there).
    private func card(_ photo: CameraPhoto, image: CGImage?) -> some View {
        let room = register.paper
        let wide = min(room.width, 250)
        let shape: CGFloat = image.map { CGFloat($0.height) / CGFloat(max(1, $0.width)) } ?? 0.75
        let pictureTall: CGFloat = min((wide - 16) * shape, max(40, room.height - 50))
        let pictureWide: CGFloat = pictureTall / max(0.1, shape)
        let tall: CGFloat = pictureTall + 50
        let number = CameraFileNames.fileNumber(photo.name).map { "No." + String(format: "%04d", $0) } ?? photo.name
        let caption = photo.isVideo ? number + "  " + (length ?? "") : number
        return VStack(spacing: 10) {
            ZStack {
                Color(white: 0.12)
                if let image { Image(decorative: image, scale: 1).resizable().scaledToFit() }
                if photo.isVideo { playing(photo) }
            }
            .frame(width: pictureWide, height: pictureTall)
            .clipped()
            .overlay(alignment: .bottomTrailing) {
                if photo.isVideo { playKey(photo) }
            }
            Text(verbatim: caption).font(.system(size: 11, weight: .heavy, design: .monospaced)).foregroundStyle(RegisterArt.rgb(50, 45, 58).opacity(0.8))
                .lineLimit(1).minimumScaleFactor(0.6)
        }
        .padding(.top, 8)
        .frame(width: wide, height: tall, alignment: .top)
        .background(RoundedRectangle(cornerRadius: 3, style: .continuous).fill(RegisterPaint.paper)
            .shadow(color: Color.black.opacity(0.45), radius: 5, y: 3))
        .contentShape(Rectangle())
        .gesture(swipe)
        .onTapGesture { if photo.isVideo { model.togglePlay() } }
        .accessibilityElement(children: .contain)
        .accessibilityLabel(photo.isVideo ? String(localized: "录像") : String(localized: "照片"))
        .accessibilityValue(photo.name)
        .accessibilityIdentifier("camera-deck-album-picture")
        .offset(x: push)
        .position(x: room.midX, y: room.minY + tall / 2)
    }
    @ViewBuilder private func playing(_ photo: CameraPhoto) -> some View {
        #if os(iOS)
        if model.playing == photo.url {
            CameraVideoPlayer(url: photo.url, ended: { model.playedToEnd() })
                .accessibilityIdentifier("camera-album-player")
        }
        #endif
    }
    /// ▶ on a video (the square while it plays).
    private func playKey(_ photo: CameraPhoto) -> some View {
        let running = model.playing == photo.url
        let word = running ? String(localized: "停止") : String(localized: "播放")
        return Button { model.togglePlay() } label: {
            ShellGlyphView(glyph: running ? .stop : .play, size: 18, ink: Color.white)
                .frame(width: 44, height: 44)
                .background(Circle().fill(RegisterArt.rgb(28, 26, 34).opacity(0.82)))
                .overlay(Circle().strokeBorder(Color.white.opacity(0.85), lineWidth: 2))
        }
        .buttonStyle(MenuPressStyle())
        .padding(6)
        .accessibilityLabel(word)
        .accessibilityValue(videoWord)
        .accessibilityIdentifier("camera-deck-album-play")
    }

    /// Which one it is, on a paper tag on the drawer's floor.
    private var place: some View {
        let count = model.photos.count
        let text: String = count == 0 ? "0" : "\(model.albumIndex + 1) / \(count)"
        return RegisterTag(text: text)
            .accessibilityElement()
            .accessibilityLabel(text)
            .accessibilityIdentifier("camera-deck-album-position")
            .deckPlaced(register.place)
            .allowsHitTesting(false)
    }

    /// Under it, what the camera says for a moment; else, while the slip
    /// looked at is coated, how to take its coat off.
    @ViewBuilder private var words: some View {
        let r = register.hint
        if let toast = model.toast {
            Text(toast).font(.system(size: 10.5, weight: .bold, design: .rounded)).foregroundStyle(Color.white.opacity(0.9))
                .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                .deckPlaced(r)
                .allowsHitTesting(false)
                .transition(.opacity)
        } else if let photo = model.albumPhoto, slips.coated(photo.name) {
            Text("用手指刮开涂层").font(.system(size: 11, weight: .heavy, design: .rounded)).foregroundStyle(Color.white.opacity(0.8))
                .lineLimit(2).multilineTextAlignment(.center).minimumScaleFactor(0.7)
                .deckPlaced(r)
                .allowsHitTesting(false)
        }
    }

    /// The drawer's front: ‹ and › (the one before, the one after), 回去拍照
    /// (red, its words kept), 主菜单.
    @ViewBuilder private var keys: some View {
        let rects = register.albumKeys
        if rects.count == 4 {
            let photos = model.photos, at = model.albumIndex
            let none = photos.isEmpty
            let empty = String(localized: "还没有照片")
            let earlier = String(localized: "上一张"), later = String(localized: "下一张")
            let hasBefore = !none && at > 0, hasAfter = at + 1 < photos.count
            let before: String = hasBefore ? String(localized: "第 \(at) 张") : ""
            let after: String = hasAfter ? String(localized: "第 \(at + 2) 张") : ""
            let firstWhy = none ? empty : String(localized: "已经是第一张")
            let lastWhy = none ? empty : String(localized: "已经是最后一张")
            let back = String(localized: "回去拍照")
            let grey = RegisterKeyStyle(tone: RegisterPaint.grey)
            Button { turn(-1) } label: { ShellGlyphView(glyph: .previous, size: 18, ink: RegisterPaint.ink) }
                .buttonStyle(grey)
                .accessibilityLabel(earlier)
                .accessibilityValue(before)
                .accessibilityIdentifier("camera-deck-album-previous")
                .deckDimmed(!hasBefore, why: firstWhy)
                .deckKey(rects[0])
            Button { turn(1) } label: { ShellGlyphView(glyph: .next, size: 18, ink: RegisterPaint.ink) }
                .buttonStyle(grey)
                .accessibilityLabel(later)
                .accessibilityValue(after)
                .accessibilityIdentifier("camera-deck-album-next")
                .deckDimmed(!hasAfter, why: lastWhy)
                .deckKey(rects[1])
            Button { backToCamera() } label: { ShellGlyphLabel(glyph: .returnToShooting, words: back, size: 16, wordSize: 12, ink: Color.white) }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.red))
                .accessibilityLabel(back)
                .accessibilityIdentifier("camera-deck-album-return")
                .deckDimmed(drawing, why: drawingWhy)
                .deckKey(rects[2])
            Button { model.leave() } label: { ShellGlyphView(glyph: .home, size: 19, ink: RegisterPaint.light) }
                .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.dark))
                .accessibilityLabel(String(localized: "camera.home.pill"))
                .accessibilityIdentifier("camera-deck-home")
                .deckKey(rects[3])
        }
    }

    /// 合计: back to taking pictures (回去拍照 on it, its words kept).
    private var total: some View {
        let back = String(localized: "回去拍照")
        return Button { backToCamera() } label: {
            ShellGlyphLabel(glyph: .returnToShooting, words: back, size: 17, wordSize: 11, ink: Color.white, stacked: !register.across)
                .padding(.horizontal, 4)
        }
        .buttonStyle(RegisterKeyStyle(tone: RegisterPaint.red, radius: 9, depth: 10, sound: .keyRubber, scale: 0.9, haptic: .smallButton))
        .accessibilityLabel(back)
        .accessibilityIdentifier("camera-deck-album-close")
        .deckDimmed(drawing, why: drawingWhy)
        .deckKey(register.total)
    }
}

/// A paper tag on the drawer's floor: the album's glyph and which one of how many.
private struct RegisterTag: View {
    var text: String
    var body: some View {
        HStack(spacing: 5) {
            ShellGlyphView(glyph: .album, size: 13, ink: RegisterPaint.ink)
            Text(verbatim: text).font(.system(size: 12, weight: .heavy, design: .rounded)).monospacedDigit().foregroundStyle(RegisterPaint.ink)
                .lineLimit(1).minimumScaleFactor(0.6)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(RoundedRectangle(cornerRadius: 4, style: .continuous).fill(Color(red: 0.949, green: 0.937, blue: 0.902)))
    }
}

/// The edge of a slip filed beside the one looked at.
private struct RegisterSliver: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let r = CGRect(origin: .zero, size: size)
            context.fill(RegisterTornEdge().path(in: r), with: .color(RegisterPaint.paper))
            var lines = Path()
            for k in 0..<5 { lines.addRect(CGRect(x: 6, y: 26 + CGFloat(k) * 16, width: max(0, size.width - 12), height: 1.4)) }
            context.fill(lines, with: .color(RegisterArt.rgb(50, 45, 58).opacity(0.18)))
            let photo = CGRect(x: 4, y: min(130, size.height * 0.3), width: max(0, size.width - 8), height: min(140, size.height * 0.35))
            context.fill(Path(photo), with: .color(RegisterArt.rgb(170, 172, 176).opacity(0.55)))
        }
        .shadow(color: Color.black.opacity(0.45), radius: 4, y: 2)
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}

/// The drawer's spring clip over the top of the slip looked at.
private struct RegisterClip: View, Equatable {
    var body: some View {
        Canvas { context, size in
            let cx = size.width / 2
            for ax in [cx - 46, cx + 46] {
                context.fill(Path(CGRect(x: ax - 1, y: 0, width: 3.5, height: size.height - 4)), with: .color(Color.black.opacity(0.35)))
                context.fill(Path(CGRect(x: ax - 2, y: 0, width: 4, height: size.height - 4)),
                             with: .linearGradient(Gradient(colors: [RegisterArt.rgb(124, 130, 139), RegisterArt.rgb(244, 245, 247), RegisterArt.rgb(138, 144, 152)]),
                                                   startPoint: CGPoint(x: ax - 2, y: 0), endPoint: CGPoint(x: ax + 2, y: 0)))
            }
            let bar = CGRect(x: cx - 64, y: size.height - 15, width: 128, height: 13)
            context.fill(Path(roundedRect: bar.offsetBy(dx: 0, dy: 2), cornerRadius: 6.5), with: .color(Color.black.opacity(0.3)))
            context.fill(Path(roundedRect: bar, cornerRadius: 6.5), with: .linearGradient(RegisterArt.silver, startPoint: CGPoint(x: bar.minX, y: bar.minY), endPoint: CGPoint(x: bar.maxX, y: bar.maxY)))
            context.stroke(Path(roundedRect: bar.insetBy(dx: 0.7, dy: 0.7), cornerRadius: 5.8), with: .color(Color.white.opacity(0.7)), lineWidth: 0.8)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }
}
